type DbtPreparationStage = 'validating' | 'compiling' | 'indexing' | 'ready';
type DbtPreparationStatus = 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';

interface DbtPreparationPhase {
  id: 'artifact_validation' | 'snapshot_compile' | 'search_index';
  label: string;
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  durationMs?: number;
}

interface DbtPreparationJob {
  id: string;
  kind: 'dbt_prepare' | 'dbt_refresh';
  status: DbtPreparationStatus;
  stage: DbtPreparationStage;
  progress: number;
  message: string;
  createdAt: string;
  updatedAt: string;
  snapshotId: string;
  phases: DbtPreparationPhase[];
  result?: Record<string, unknown>;
  error?: string;
}

export interface LocalServerOptions {
  rootDir: string;
  projectRoot?: string;
  executor: QueryExecutor;
  connection?: ConnectionConfig | null;
  preferredPort: number;
  /**
   * Host the HTTP server binds to. Defaults to `127.0.0.1` (loopback only)
   * for security. Set to `0.0.0.0` when running inside a container so the
   * port is reachable from the host. Honours `DQL_HOST` env var when unset.
   */
  host?: string;
  /** Required for non-loopback bindings. Defaults to `DQL_SERVER_TOKEN`. */
  authToken?: string;
  /** Exact browser origins allowed for non-loopback API access. */
  allowedOrigins?: string[];
  /**
   * Receives the underlying HTTP server once created, so short-lived callers
   * (e.g. `dql agent ask` starting an ephemeral runtime) can `close()` it and
   * let the process exit instead of hanging on an open listener.
   */
  captureServer?: (server: import('node:http').Server) => void;
  /**
   * Test/embedding seam for deterministic agent-run execution without a live LLM.
   * Production callers leave this unset and use the default governed executors.
  */
  agentRunExecutors?: AgentRunExecutors;
  /** Host-owned rollback seam; never read from client request payloads. */
  requireMeaningCallForNaturalLanguage?: boolean;
  /** The Ask runtime mode; there is one. Kept so health can report it. */
  askAgentRuntimeMode?: AskAgentRuntimeMode;
  /**
   * Host-only Ask-planner provider seam for deterministic local-runtime
   * integration tests.  It is never read from HTTP/MCP payloads and does not
   * grant a caller provider, route, or execution authority.
   */
  askAnalyticalPlannerProviderFactory?: (input: {
    projectRoot: string;
    request: AgentRunRequest;
  }) => AgentProvider | null | Promise<AgentProvider | null>;
  /**
   * Host-only watcher seam for local-runtime tests and embeddings. Production
   * uses `fs.watch`; browser/MCP input can never select a watcher or its scope.
   */
  projectWatcherFactory?: typeof watch;
  /**
   * Per-runtime capability minted by the local CLI launcher. Only a matching
   * request header may label a trace as `cli`; public JSON never carries this
   * authority and browser/MCP requests remain their own server-owned surface.
   */
  trustedCliTraceToken?: string;
}

/**
 * The Ask rollout mode is an operator-owned server setting.  It is never
 * parsed from an Ask HTTP/MCP payload, but the built CLI may select it at
 * startup so an operator can run an explicit authoritative canary.
 */
export const ASK_AGENT_RUNTIME_MODES = [
  // The interpreter-first Ask pipeline (intent → prepare → execute) is the
  // only serving runtime. The authoritative V2 kernel is deleted; persisted
  // runs still carry its receipts and its mode label.
  'pipeline_v3',
] as const satisfies readonly AskRuntimeModeV2[];

export type AskAgentRuntimeMode = typeof ASK_AGENT_RUNTIME_MODES[number];

/**
 * A Research hypothesis executed through the Ask pipeline, read back as the
 * governed answer the dossier expects: an executed result is a governed or
 * certified answer with its SQL and rows; anything else is a typed no-answer
 * carrying the pipeline's own sentence.
 */
export function agentAnswerFromPipelineBranch(result: AgentRouteExecutorResult): AgentAnswer {
  const payload = (result.artifacts ?? []).map((artifact) => artifact.payload as Record<string, unknown> | undefined).find((candidate) => candidate && (candidate.result || candidate.executionError || candidate.gap));
  const rows = payload?.result as AgentResultPayload | undefined;
  const text = result.answer ?? result.summary ?? '';
  if (result.status === 'completed' && rows && Array.isArray(rows.rows)) {
    const certified = result.trustState === 'certified';
    return {
      kind: certified ? 'certified' : 'uncertified',
      sourceTier: certified ? 'certified_artifact' : 'semantic_layer',
      certification: certified ? 'certified' : 'governed',
      reviewStatus: certified ? 'certified' : 'governed',
      text,
      answer: text,
      ...(typeof payload?.sql === 'string' ? { sql: payload.sql } : {}),
      result: rows,
      ...(payload?.dqlArtifact !== undefined ? { dqlArtifact: payload.dqlArtifact as AgentAnswer['dqlArtifact'] } : {}),
      citations: [],
      considered: [],
    } as AgentAnswer;
  }
  return {
    kind: 'no_answer',
    text,
    answer: text,
    refusalCode: result.answerRefusalCode ?? (result.status === 'needs_clarification' ? 'ambiguous' : 'grounding_gap'),
    ...(typeof payload?.executionError === 'string' ? { executionError: payload.executionError } : {}),
    citations: [],
    considered: [],
  } as AgentAnswer;
}

export function resolveAskAgentRuntimeMode(
  value: unknown,
): AskAgentRuntimeMode {
  if (value === undefined) return 'pipeline_v3';
  // A project that still says `authoritative_v2` gets the pipeline: the
  // kernel it named no longer exists, and refusing to start would help nobody.
  if (value === 'authoritative_v2') {
    console.warn('[dql] agent.askRuntimeMode "authoritative_v2" was removed; serving the Ask pipeline (pipeline_v3). Delete the setting.');
    return 'pipeline_v3';
  }
  if (typeof value === 'string' && (ASK_AGENT_RUNTIME_MODES as readonly string[]).includes(value)) {
    return value as AskAgentRuntimeMode;
  }
  throw new Error(
    `Invalid Ask runtime mode "${typeof value === 'string' ? value : String(value)}". Expected one of: ${ASK_AGENT_RUNTIME_MODES.join(', ')}.`,
  );
}

/**
 * The project's persisted Ask runtime mode, from `agent.askRuntimeMode` in
 * `dql.config.json`. Precedence is CLI flag > project config > default.
 * There is one runtime, `pipeline_v3`; a config that still names the deleted
 * `authoritative_v2` is served by the pipeline with a warning, and any other
 * value fails loudly rather than silently.
 */
/** `agent.askAutoExploration` in `dql.config.json`: false keeps the review-required SQL tier opt-in; anything else lets it run when nothing governed prepares. */
export function readProjectAskAutoExploration(projectRoot: string): boolean {
  try {
    const parsed = JSON.parse(readFileSync(join(projectRoot, 'dql.config.json'), 'utf-8')) as { agent?: { askAutoExploration?: unknown } };
    return parsed?.agent?.askAutoExploration !== false;
  } catch {
    return true;
  }
}

export function readProjectAskRuntimeMode(projectRoot: string): unknown {
  try {
    const raw = readFileSync(join(projectRoot, 'dql.config.json'), 'utf-8');
    const parsed = JSON.parse(raw) as { agent?: { askRuntimeMode?: unknown } };
    return parsed?.agent && typeof parsed.agent === 'object'
      ? (parsed.agent as { askRuntimeMode?: unknown }).askRuntimeMode
      : undefined;
  } catch {
    // An unreadable or malformed config must not silently choose a mode.
    return undefined;
  }
}

/** One-time local capability lifetime. It is never persisted or sent to a provider. */
export const CLI_ASK_TRACE_CAPABILITY_TTL_MS = 30_000;

export interface LocalCliAskTraceCapabilityV1 {
  capability: string;
  expiresAt: string;
  scope: 'agent-runs';
}

interface LocalCliAskTraceCapabilityRecordV1 {
  expiresAtMs: number;
  scope: LocalCliAskTraceCapabilityV1['scope'];
}

export interface LocalCliAskTraceCapabilityRegistryV1 {
  issue(input?: { capability?: string; nowMs?: number; ttlMs?: number }): LocalCliAskTraceCapabilityV1;
  consume(input: {
    capability: string | string[] | undefined;
    scope: LocalCliAskTraceCapabilityV1['scope'];
    loopbackServer: boolean;
    remoteAddress?: string;
    nowMs?: number;
  }): 'cli' | undefined;
}

function isLoopbackRemoteAddress(value: string | undefined): boolean {
  return value === '127.0.0.1'
    || value === '::1'
    || value === '::ffff:127.0.0.1';
}

/**
 * Host-owned, one-shot attribution capabilities for an already-local runtime.
 * A plain client header is never enough: it must be minted by this process,
 * unexpired, scoped to AgentRun admission, and arrive over loopback.
 */
export function createLocalCliAskTraceCapabilityRegistryV1(
  options: { now?: () => number; mint?: () => string } = {},
): LocalCliAskTraceCapabilityRegistryV1 {
  const records = new Map<string, LocalCliAskTraceCapabilityRecordV1>();
  const now = options.now ?? Date.now;
  const mint = options.mint ?? randomUUID;
  const purge = (at: number) => {
    for (const [capability, record] of records) {
      if (record.expiresAtMs <= at) records.delete(capability);
    }
  };
  return {
    issue(input = {}) {
      const issuedAt = input.nowMs ?? now();
      purge(issuedAt);
      const capability = input.capability ?? mint();
      const expiresAtMs = issuedAt + Math.max(1, Math.min(CLI_ASK_TRACE_CAPABILITY_TTL_MS, input.ttlMs ?? CLI_ASK_TRACE_CAPABILITY_TTL_MS));
      records.set(capability, { expiresAtMs, scope: 'agent-runs' });
      return {
        capability,
        expiresAt: new Date(expiresAtMs).toISOString(),
        scope: 'agent-runs',
      };
    },
    consume(input) {
      const at = input.nowMs ?? now();
      purge(at);
      if (!input.loopbackServer || !isLoopbackRemoteAddress(input.remoteAddress) || typeof input.capability !== 'string') return undefined;
      const record = records.get(input.capability);
      if (!record || record.scope !== input.scope || record.expiresAtMs <= at) return undefined;
      // A capability represents one concrete request admission. Deleting it
      // prevents copied local headers from relabelling later browser requests.
      records.delete(input.capability);
      return 'cli';
    },
  };
}

/**
 * Opaque host-only capability for one cold exact-literal grounding probe.
 * Unlike the trace-header capability above, this is never returned through an
 * HTTP response: the runtime holds the token only long enough to invoke its
 * local callback and strips it before any planner, trace, receipt, or store
 * projection. The registry owns the physical field details.
 */
export const CLI_ASK_LITERAL_PROBE_CAPABILITY_TTL_MS = 45_000;

interface LocalLiteralProbeCapabilityRecordV1 {
  request: AgentRunRequest;
  runId?: string;
  snapshotId: string;
  candidateId: string;
  candidateQualifiedId: string;
  relation: string;
  column: string;
  expiresAtMs: number;
}

export interface LocalLiteralProbeCapabilityRegistryV1 {
  issue(input: {
    request: AgentRunRequest;
    snapshotId: string;
    candidate: AgentEvidenceCandidate;
    relation: string;
    column: string;
    token?: string;
    nowMs?: number;
  }): string | undefined;
  consume(input: {
    token: unknown;
    request: AgentRunRequest;
    snapshotId?: string;
    activeSnapshotId?: string;
    candidate: AgentEvidenceCandidate;
    relation: string;
    column: string;
    nowMs?: number;
  }): boolean;
}

/**
 * The local process holds the only mapping from an opaque token to its exact
 * request, snapshot, candidate identity, and physical field. `consume` is
 * intentionally fail-closed and deletes a successful authorization before
 * the caller can construct or execute the probe SQL.
 */
export function createLocalLiteralProbeCapabilityRegistryV1(
  options: { now?: () => number; mint?: () => string } = {},
): LocalLiteralProbeCapabilityRegistryV1 {
  const records = new Map<string, LocalLiteralProbeCapabilityRecordV1>();
  const now = options.now ?? Date.now;
  const mint = options.mint ?? randomUUID;
  const purge = (at: number) => {
    for (const [token, record] of records) {
      if (record.expiresAtMs <= at) records.delete(token);
    }
  };
  const canonicalRelation = (value: string) => normalizeAgentSafeColumnReference(value);
  const canonicalColumn = (value: string) => normalizeAgentSafeColumnReference(value);
  return {
    issue(input) {
      const issuedAt = input.nowMs ?? now();
      purge(issuedAt);
      if (!input.snapshotId.trim()
        || !input.candidate.id.trim()
        || !input.candidate.qualifiedId?.trim()
        || !input.relation.trim()
        || !input.column.trim()) return undefined;
      const token = input.token ?? mint();
      if (!token.trim()) return undefined;
      records.set(token, {
        request: input.request,
        ...(input.request.runId ? { runId: input.request.runId } : {}),
        snapshotId: input.snapshotId,
        candidateId: input.candidate.id,
        candidateQualifiedId: input.candidate.qualifiedId,
        relation: canonicalRelation(input.relation),
        column: canonicalColumn(input.column),
        expiresAtMs: issuedAt + CLI_ASK_LITERAL_PROBE_CAPABILITY_TTL_MS,
      });
      return token;
    },
    consume(input) {
      const at = input.nowMs ?? now();
      purge(at);
      if (typeof input.token !== 'string' || !input.token.trim()) return false;
      const record = records.get(input.token);
      if (!record || record.expiresAtMs <= at) return false;
      // A copied token must not cross a request object or engine-issued run.
      // Identity comparison intentionally supplements the stable run ID: an
      // in-process retry/copy cannot replay another request's token.
      if (record.request !== input.request
        || record.runId !== input.request.runId
        || record.snapshotId !== input.snapshotId
        || record.snapshotId !== input.activeSnapshotId
        || record.candidateId !== input.candidate.id
        || record.candidateQualifiedId !== input.candidate.qualifiedId
        || record.relation !== canonicalRelation(input.relation)
        || record.column !== canonicalColumn(input.column)) return false;
      // Delete before SQL construction/execution: the capability is one-use
      // even if the connector subsequently returns no-match or fails.
      records.delete(input.token);
      return true;
    },
  };
}

// Every member of `AgentRunRequestedMode`. The `Record` (rather than a bare
// Set literal) is deliberate: a `Set<AgentRunRequestedMode>` happily accepts a
// subset, which is how 'modeling' and 'skill' went missing here — the parser
// dropped them to `undefined`, `selectRoute` never saw an explicit mode, and
// Modeling AI silently ran the governed answer loop instead of proposing a
// model. A Record makes an omission a compile error.
const AGENT_RUN_REQUESTED_MODE_MEMBERS: Record<AgentRunRequestedMode, true> = {
  auto: true, ask: true, research: true, sql: true, block: true, app: true, modeling: true, skill: true,
};
const AGENT_RUN_REQUESTED_MODES = new Set<AgentRunRequestedMode>(
  Object.keys(AGENT_RUN_REQUESTED_MODE_MEMBERS) as AgentRunRequestedMode[],
);

export interface AppCopilotResearchAgentInput {
  appId: string;
  dashboardId?: string;
  sourceTileId?: string;
  sourceBlockId?: string;
  title?: string;
  question: string;
  intent: string;
  context?: unknown;
  mode?: 'sql_and_memo' | 'memo_only';
  generatedSql?: string;
  metrics?: Record<string, unknown>;
  drivers?: Array<Record<string, unknown>>;
  resultPreviews?: unknown[];
  summaryHint?: string;
  recommendationHint?: string;
  sqlError?: string;
  sqlErrorKind?: string;
  hasReportEvidence?: boolean;
}

/** AGT-007 / AGT-022: App-specific context adapter into the uniform AgentRun. */
export function buildAppCopilotResearchAgentRequest(input: AppCopilotResearchAgentInput): AgentRunRequest {
  const memoOnly = input.mode === 'memo_only';
  const appResearch = {
    mode: 'app_research',
    generationMode: input.mode ?? 'sql_and_memo',
    intent: input.intent,
    appId: input.appId,
    dashboardId: input.dashboardId,
    sourceTileId: input.sourceTileId,
    sourceBlockId: input.sourceBlockId,
    title: input.title,
    instruction: [
      'Answer as an app-scoped analyst. Start from certified block/result context, active filters, dbt/semantic metadata, and schema evidence.',
      memoOnly
        ? 'Write the stakeholder memo from the supplied selected result, preview rows, generated SQL, metrics, drivers, filters, and caveats. Do not generate replacement SQL unless the user explicitly asks to fix SQL.'
        : 'Generate review-required read-only SQL only when the certified result does not exactly answer the requested analysis grain. Execute only through the bounded generated SQL preview path.',
      'In the natural-language answer, write a stakeholder analysis memo, not a generic chat answer. Use Markdown headings chosen for the question, usually Executive answer, Key numbers, Drivers or Business readout, Caveats, and Next action.',
      'Use concrete numbers from the selected result or preview when available. If baseline, segment, grain, lineage, or source proof is missing, say that explicitly instead of inventing a driver story.',
      'Keep raw SQL in proposedSql/sql. Do not put SQL code fences or implementation trace in the memo body.',
    ].join(' '),
    generatedSql: input.generatedSql,
    metrics: input.metrics,
    drivers: input.drivers,
    resultPreviews: input.resultPreviews,
    summaryHint: input.summaryHint,
    recommendationHint: input.recommendationHint,
    sqlError: input.sqlError,
    sqlErrorKind: input.sqlErrorKind,
    hasReportEvidence: input.hasReportEvidence,
    context: input.context,
  };
  return {
    question: memoOnly
      ? [
          `Research question: ${input.question}`,
          'Write the business memo now using only the evidence envelope supplied as upstream context.',
          'Return Markdown sections. Keep SQL, query text, implementation trace, and raw routing details out of the memo body.',
          'If the evidence is insufficient, state the gap and the next reviewer action instead of filling the story with generic text.',
        ].join('\n')
      : input.question,
    requestedMode: 'research',
    audience: 'stakeholder',
    selectedObject: {
      kind: 'app',
      id: input.appId,
      title: input.title,
    },
    analysisDepth: 'deep',
    workspaceContext: {
      surface: 'app_copilot',
      appId: input.appId,
      dashboardId: input.dashboardId,
      appResearch,
    },
  };
}
const AGENT_RUN_SELECTED_OBJECT_KINDS = new Set<AgentRunSelectedObject['kind']>([
  'notebook',
  'cell',
  'block',
  'app',
  'dashboard',
  'research',
  'workspace',
]);

function agentRunRecord(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : undefined;
}

function agentRunString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : undefined;
}

function parseSelectedResultBinding(value: unknown): AgentSelectedResultBindingV1 | undefined {
  const record = agentRunRecord(value);
  if (!record || record.version !== 1) return undefined;
  const sourceRunId = agentRunString(record.sourceRunId);
  const sourceArtifactId = agentRunString(record.sourceArtifactId);
  const canonicalColumn = agentRunString(record.canonicalColumn);
  const bindingValue = agentRunString(record.value);
  const rowFingerprint = agentRunString(record.rowFingerprint);
  const resultFingerprint = agentRunString(record.resultFingerprint);
  if (!sourceRunId || !sourceArtifactId || !canonicalColumn || !bindingValue || !rowFingerprint || !resultFingerprint) return undefined;
  return {
    version: 1,
    sourceRunId,
    sourceArtifactId,
    canonicalColumn,
    value: bindingValue,
    rowFingerprint,
    resultFingerprint,
  };
}

/**
 * Catalog previews are display-only run-store joins; the trace store and
 * strict exports remain prompt-free. Returning a partially redacted arbitrary
 * prompt is not safe: member values, SQL literals, URLs, filesystem paths, and
 * secrets are all meaningful diagnostics in an analytics system. Therefore a
 * preview is optional and all-or-nothing: it is returned only for a short
 * generic analytic question composed entirely of this deliberately small
 * vocabulary. Every other question is represented by its typed scenario label.
 */
const ASK_TRACE_PREVIEW_MAX_CHARS = 160;
const ASK_TRACE_PREVIEW_ALLOWED_WORDS = new Set([
  'a', 'account', 'accounts', 'all', 'amount', 'an', 'and', 'are', 'average',
  'by', 'categories', 'category', 'compare', 'count', 'current', 'customer',
  'customers', 'daily', 'data', 'date', 'dates', 'dimension', 'dimensions',
  'fiscal', 'for', 'from', 'growth', 'have', 'highest', 'how', 'is', 'last',
  'lowest', 'me', 'metric', 'metrics', 'month', 'monthly', 'of', 'order',
  'orders', 'our', 'previous', 'product', 'products', 'quarter', 'quarterly',
  'region', 'regions', 'result', 'results', 'revenue', 'sales', 'show',
  'spend', 'the', 'their', 'these', 'this', 'to', 'top', 'total', 'trend',
  'trends', 'what', 'when', 'where', 'which', 'who', 'why', 'with', 'year',
]);
const ASK_TRACE_PREVIEW_SENSITIVE_PATTERNS = [
  /\b(?:select|insert|update|delete|drop|alter|create|grant|revoke|truncate|merge|with)\b/i,
  /(?:--|\/\*|\*\/|;)/,
  /(?:https?|ftp):\/\/|\bwww\./i,
  /(?:^|[\s"'`])(?:~\/|\/(?:Users|home|var|tmp|private|etc|opt|Volumes)\/|[A-Za-z]:[\\/])/,
  /\b\d{3}-\d{2}-\d{4}\b/,
  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i,
  /(?:\+?\d[\d().\-\s]{7,}\d)/,
  /\b(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|authorization|password|secret|client[_ -]?secret|private[_ -]?key|session|cookie)\b/i,
  /\bbearer\s+[a-z0-9._~+\/-]{8,}/i,
  /\b(?:sk|pk|rk)_[a-z0-9_-]{8,}\b/i,
  /\b(?:AKIA|ASIA)[A-Z0-9]{12,}\b/,
  /\bgh[pousr]_[A-Za-z0-9]{16,}\b/,
  /\beyJ[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/,
];

export function askTraceQuestionPreview(question: string): string | undefined {
  const normalized = question.replace(/\s+/g, ' ').trim();
  if (!normalized || normalized.length > ASK_TRACE_PREVIEW_MAX_CHARS) return undefined;
  if (ASK_TRACE_PREVIEW_SENSITIVE_PATTERNS.some((pattern) => pattern.test(normalized))) return undefined;
  // Do not attempt to preserve literals, values, handles, or unclassified
  // business nouns. The catalog can still identify its typed scenario without
  // exposing those inputs.
  if (!/^[A-Za-z ?-]+$/.test(normalized)) return undefined;
  const words = normalized.toLowerCase().match(/[a-z]+/g);
  if (!words?.length || words.some((word) => !ASK_TRACE_PREVIEW_ALLOWED_WORDS.has(word))) return undefined;
  return normalized;
}

function askTraceScenarioLabel(run: Pick<AgentRun, 'requestedMode' | 'route'>): string {
  if (run.requestedMode === 'research' || run.route === 'research') return 'Research';
  const labels: Partial<Record<AgentRunRoute, string>> = {
    certified_answer: 'Certified answer',
    semantic_answer: 'Semantic answer',
    generated_answer: 'Review-required SQL',
    clarify: 'Clarification',
    blocked: 'Blocked',
    conversation: 'Conversation',
  };
  return labels[run.route] ?? 'Ask run';
}

/**
 * The SQLite trace envelope is intentionally small and may have been written
 * before the V2 terminal receipt was attached to the AgentRun. Project only
 * receipt-owned scalar facts at this API boundary so a completed V2 run does
 * not display stale V1 placeholders such as "No executable tier".
 */
function projectAuthoritativeV8TraceEnvelope<T extends {
  selectedTier?: string;
  candidateDecisionCount: number;
  trustState?: string;
}>(envelope: T, run: AgentRun | undefined): T {
  const receipt = run?.diagnosticReceiptV8;
  if (receipt?.mode !== 'authoritative_v2') return envelope;
  const selectedTier = receipt.tierAttempts.find((attempt) => attempt.frozen)?.tier
    ?? receipt.tierAttempts.find((attempt) => attempt.outcome === 'executed')?.tier
    // An unfrozen authoritative V2 run has no selected executable plan. Its
    // controller-owned progression may be shown, but an eligible inspection
    // is not route authority and must never win over a later unavailable tier.
    ?? receipt.controllerTier;
  return {
    ...envelope,
    selectedTier,
    // V8 owns the bounded admission count for authoritative Ask.  Legacy
    // candidate decisions can describe a wider pre-V2 retrieval path, so
    // merging them would misstate the actual planner workspace.
    candidateDecisionCount: receipt.initialCandidateCount,
    ...(run?.trustState ? { trustState: run.trustState } : {}),
  } as T;
}

/**
 * The notebook has exactly two trace client routes. Decode only the single
 * detail segment for validation so a valid encoded run id (for example
 * `run%3Aoffice-42`) reaches the SPA, while encoded slashes, malformed escapes,
 * and nested paths stay ordinary 404s.
 */
export function isAskTraceClientDetailPath(pathname: string): boolean {
  const prefix = '/ask/traces/';
  if (!pathname.startsWith(prefix)) return false;
  const encodedRunId = pathname.slice(prefix.length);
  if (!encodedRunId || encodedRunId.includes('/')) return false;
  try {
    const runId = decodeURIComponent(encodedRunId);
    return /^[0-9A-Za-z][0-9A-Za-z:_-]{0,255}$/.test(runId);
  } catch {
    return false;
  }
}

/**
 * Ask owns only these client-side routes. Keep the static fallback explicit so
 * a notebook reload works while an arbitrary missing path remains a real 404.
 */
export function isAskClientRoutePath(pathname: string): boolean {
  return pathname === '/ask'
    || pathname === '/ask/traces'
    || isAskTraceClientDetailPath(pathname);
}

/** UI catalog fallback labels are not declared project domains. */
/**
 * Resolve a UI-pinned domain scope, tolerating one that no longer exists.
 *
 * The Ask scope persists across reloads, so a domain that was renamed, deleted,
 * or simply mistyped would otherwise throw `Unknown domain: x` and BLOCK every
 * question with "no answer produced" until the user found the chip and cleared
 * it. A scope that cannot be resolved should widen the search, never wedge the
 * surface. Anything other than an unresolvable scope still throws, because that
 * is a real contract violation worth reporting.
 */
export function resolveUiDomainContext(input: ResolveDomainContextInput): DomainContextEnvelope | undefined {
  try {
    return resolveDomainContextEnvelope(input);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (/^Unknown domain:|^Unknown model area:|^Ambiguous model area:/.test(message)) return undefined;
    throw error;
  }
}


/**
 * Embedding models we offer by name so a user never has to know one.
 *
 * Retrieval quality is bounded by the embedder, and picking one is the single
 * step between lexical-only matching and real meaning-based recall — so the
 * product should name good defaults rather than expect a model string.
 * `dimensions` is informational: the index records whatever the provider
 * actually returns.
 */
export const EMBEDDING_MODEL_CATALOG = {
  ollama: [
    { model: 'nomic-embed-text', label: 'Nomic Embed Text', dimensions: 768, size: '274 MB', recommended: true,
      description: 'Best general default. Strong paraphrase matching for metric and dimension descriptions.' },
    { model: 'mxbai-embed-large', label: 'MxBai Embed Large', dimensions: 1024, size: '670 MB', recommended: false,
      description: 'Higher quality, slower and larger. Worth it for very large catalogs.' },
    { model: 'all-minilm', label: 'All-MiniLM', dimensions: 384, size: '46 MB', recommended: false,
      description: 'Smallest and fastest. Use on constrained machines.' },
  ],
  openai: [
    { model: 'text-embedding-3-small', label: 'text-embedding-3-small', dimensions: 1536, size: 'hosted', recommended: true,
      description: 'Cheapest hosted option and strong for catalog text.' },
    { model: 'text-embedding-3-large', label: 'text-embedding-3-large', dimensions: 3072, size: 'hosted', recommended: false,
      description: 'Highest quality hosted embedding; higher cost per index.' },
  ],
} as const;

export function normalizeAgentRunDomain(value: unknown): string | undefined {
  const domain = agentRunString(value);
  if (!domain) return undefined;
  const normalized = domain.toLowerCase();
  return normalized === 'uncategorized' || normalized === '_uncategorized'
    ? undefined
    : domain;
}

function parseAgentRunRequestedMode(value: unknown): AgentRunRequestedMode | undefined {
  return typeof value === 'string' && AGENT_RUN_REQUESTED_MODES.has(value as AgentRunRequestedMode)
    ? value as AgentRunRequestedMode
    : undefined;
}

function parseAgentRunReasoningEffort(value: unknown): ReasoningEffort | undefined {
  return value === 'low' || value === 'medium' || value === 'high'
    ? value
    : undefined;
}

function parseAgentRunAnalysisDepth(value: unknown): AnalysisDepth | undefined {
  return value === 'quick' || value === 'deep'
    ? value
    : undefined;
}

function isAskContinuationMode(mode: AgentRunRequestedMode | undefined): boolean {
  return mode !== 'block' && mode !== 'app' && mode !== 'modeling' && mode !== 'skill';
}

function parseAgentRunSelectedObject(value: unknown): AgentRunSelectedObject | undefined {
  const record = agentRunRecord(value);
  if (!record) return undefined;
  const kind = agentRunString(record.kind);
  if (!kind || !AGENT_RUN_SELECTED_OBJECT_KINDS.has(kind as AgentRunSelectedObject['kind'])) return undefined;
  return {
    kind: kind as AgentRunSelectedObject['kind'],
    id: agentRunString(record.id),
    title: agentRunString(record.title),
    path: agentRunString(record.path),
  };
}

function parseAgentRunHistory(value: unknown): AgentRunRequest['history'] {
  if (!Array.isArray(value)) return undefined;
  const history = value.flatMap((item): NonNullable<AgentRunRequest['history']>[number][] => {
    const record = agentRunRecord(item);
    if (!record) return [];
    const role = record.role === 'user' || record.role === 'assistant' ? record.role : undefined;
    const text = agentRunString(record.text) ?? agentRunString(record.content);
    return role && text ? [{ role, text }] : [];
  });
  return history.length > 0 ? history.slice(-20) : undefined;
}

export function parseAgentRunRequestBody(body: unknown): { request?: AgentRunRequest; error?: string } {
  const record = agentRunRecord(body);
  if (!record) return { error: 'Invalid JSON body.' };
  const question = agentRunString(record.question) ?? agentRunString(record.prompt) ?? agentRunString(record.message);
  if (!question) return { error: 'question is required.' };
  const selectedObject = parseAgentRunSelectedObject(record.selectedObject);
  const rawExecutionTarget = agentRunRecord(record.executionTarget)
    ?? agentRunRecord(agentRunRecord(record.workspaceContext)?.executionTarget);
  const executionTarget = rawExecutionTarget?.target === 'local'
    ? { target: 'local' as const }
    : rawExecutionTarget?.target === 'connection'
      ? {
          target: 'connection' as const,
          ...(agentRunString(rawExecutionTarget.connectionName)
            ? { connectionName: agentRunString(rawExecutionTarget.connectionName) }
            : {}),
        }
      : undefined;
  const workspaceContext = agentRunRecord(record.workspaceContext) ?? agentRunRecord(record.context);
  const signals = agentRunRecord(record.signals);
  const selectedResultBinding = parseSelectedResultBinding(record.selectedResultBinding);
  if (record.selectedResultBinding !== undefined && !selectedResultBinding) {
    return { error: 'selectedResultBinding must be a complete version 1 result reference.' };
  }
  const requestedMode = parseAgentRunRequestedMode(record.requestedMode) ?? parseAgentRunRequestedMode(record.mode);
  if (record.researchResultRowsOptIn !== undefined && typeof record.researchResultRowsOptIn !== 'boolean') {
    return { error: 'researchResultRowsOptIn must be a boolean.' };
  }
  if (record.researchResultRowsOptIn === true && requestedMode !== 'research') {
    return { error: 'researchResultRowsOptIn is accepted only for an explicitly requested Research run.' };
  }
  const audience = record.audience === 'stakeholder' || record.audience === 'analyst'
    ? record.audience
    : undefined;
  return {
    request: {
      question,
      selectedEvidenceId: agentRunString(record.selectedEvidenceId),
      ...(selectedResultBinding ? { selectedResultBinding } : {}),
      clarificationSourceQuestion: agentRunString(record.clarificationSourceQuestion),
      requestedMode,
      audience,
      intent: agentRunString(record.intent) as AgentRunRequest['intent'],
      signals: signals as AgentRunRequest['signals'],
      selectedObject,
      executionTarget,
      workspaceContext,
      conversationContext: sanitizeClientConversationContext(agentRunRecord(record.conversationContext), {
        stripStructuredSelectionEnvelope: Boolean(agentRunString(record.selectedEvidenceId)),
        // Ask (including explicit Research) may only carry result-set state
        // from a server-reconstructed thread. Browser payloads still retain
        // ordinary non-authoritative hints, but cannot establish a member
        // filter, source/trust claim, or prior-result continuation.
        stripResultBearingContext: isAskContinuationMode(requestedMode),
      }),
      // Public Ask/Research history is not a continuation authority. It may
      // contain prose that resembles a certified answer, a result row, or a
      // prior clarification; allowing it into the analytical path lets a
      // browser manufacture source attribution or a follow-up scope. A valid
      // local thread reconstructs its own bounded history after ingress.
      // Non-Ask authoring routes retain their existing request-local history.
      history: isAskContinuationMode(requestedMode)
        ? undefined
        : parseAgentRunHistory(record.history),
      threadId: agentRunString(record.threadId),
      // `runId` is deliberately absent at public ingress. It scopes the
      // controller, persisted run, SSE operation, and one-shot SQL capability,
      // so a browser-supplied value must never become execution authority.
      reasoningEffort: parseAgentRunReasoningEffort(record.reasoningEffort),
      analysisDepth: parseAgentRunAnalysisDepth(record.analysisDepth) ?? parseAgentRunAnalysisDepth(record.depth),
      thinkingMode: coerceThinkingMode(record.thinkingMode),
      researchResultRowsOptIn: requestedMode === 'research' && record.researchResultRowsOptIn === true,
    },
  };
}

const CLIENT_PLAN_AUTHORITY_KEYS = new Set([
  'priorResolvedAnalyticalPlan',
  'resolvedAnalyticalPlan',
  'analyticalFrame',
  // Only the local compound executor may inject this after it has derived a
  // canonical parent result binding. A browser-provided lookalike cannot become
  // a child filter or skip ordinary member validation.
  'analyticalTaskDependencyBinding',
]);

// Result-bearing conversation fields are authority only after the local host
// has reconstructed them from a persisted thread. In particular, accepting
// these values from an Ask HTTP body lets a browser turn an arbitrary literal
// into a governed SQL filter after a redacted prior result. Keep this list
// intentionally broad for Ask: opaque UI hints remain allowed, but result,
// source, prior, and transcript-shaped state never crosses this boundary.
const CLIENT_RESULT_BEARING_CONTEXT_KEYS = new Set([
  'turns',
  'history',
  'outputColumns',
  'answerContract',
  'dqlArtifact',
  'requestedFilters',
  'requestedDimensions',
  'requestedMeasures',
  'memberBindings',
  'resolvedReferences',
  'unresolvedReferences',
  'activeTurnId',
  'latestTurnId',
  'conversationSummary',
  'conversationEnvelope',
  'serverSnapshot',
  'serverIssuedClarificationSelection',
]);

function isClientResultBearingContextKey(key: string): boolean {
  if (CLIENT_RESULT_BEARING_CONTEXT_KEYS.has(key)) return true;
  const normalized = key.toLowerCase();
  return normalized.startsWith('source')
    || normalized.startsWith('prior')
    || normalized.startsWith('result');
}

// A selectedEvidenceId is a structured server continuation—not a client plan
// hint. The backing envelope is always host-owned; selected continuations also
// lose any lookalike envelope before the store validates the stable choice.
const CLIENT_STRUCTURED_SELECTION_AUTHORITY_KEYS = new Set([
  'conversationEnvelope',
  'serverSnapshot',
  'serverIssuedClarificationSelection',
]);

/**
 * Browser/embedding context is useful retrieval and history input, but it is
 * not a plan-authority channel. Remove plan-shaped fields recursively at HTTP
 * ingress; server-retained thread context is added afterwards from local state.
 */
function sanitizeClientConversationContext(
  context: Record<string, unknown> | undefined,
  options: {
    stripStructuredSelectionEnvelope?: boolean;
    stripResultBearingContext?: boolean;
  } = {},
): Record<string, unknown> | undefined {
  if (!context) return undefined;
  const sanitize = (value: unknown): unknown => {
    if (Array.isArray(value)) return value.map(sanitize);
    const record = agentRunRecord(value);
    if (!record) return value;
    return Object.fromEntries(Object.entries(record).flatMap(([key, nested]) => {
      const isHostOnlySelectionAuthority = key === 'serverIssuedClarificationSelection';
      const isUntrustedSelectionEnvelope = options.stripStructuredSelectionEnvelope
        && CLIENT_STRUCTURED_SELECTION_AUTHORITY_KEYS.has(key);
      const isUntrustedResultBearingContext = options.stripResultBearingContext
        && isClientResultBearingContextKey(key);
      return CLIENT_PLAN_AUTHORITY_KEYS.has(key)
        || isHostOnlySelectionAuthority
        || isUntrustedSelectionEnvelope
        || isUntrustedResultBearingContext
        ? []
        : [[key, sanitize(nested)]];
    }));
  };
  return sanitize(context) as Record<string, unknown>;
}

const AGENT_LOOKUP_DEADLINE_MS = 45_000;
const AGENT_RESEARCH_DEADLINE_MS = 180_000;

/**
 * PERF-002: one wall-clock budget follows the request through routing, provider
 * calls, repair, and execution. Ordinary Ask never inherits Research's budget
 * because of question wording, depth, provider, or relational shape; only an
 * explicit `requestedMode: research` activates the Research budget.
 */
/** Resolve governed display formats for result columns from the semantic layer (best-effort, cached per call). */
function agentColumnDisplayFormats(projectRoot: string, columns: string[]): Record<string, SemanticDisplayFormat> {
  const formats: Record<string, SemanticDisplayFormat> = {};
  try {
    const layer = loadAgentSemanticLayer(projectRoot);
    if (!layer) return formats;
    for (const column of columns) {
      const format = layer.displayFormatFor(column);
      if (format) formats[column] = format;
    }
  } catch { /* formatting is presentation-only; never fail an answer over it */ }
  return formats;
}

export function agentRunDeadlineMs(
  request: Pick<AgentRunRequest, 'question' | 'selectedEvidenceId' | 'clarificationSourceQuestion' | 'requestedMode' | 'analysisDepth' | 'reasoningEffort' | 'thinkingMode'>,
  env: NodeJS.ProcessEnv = process.env,
  activeProviderId?: string | null,
): number {
  void env;
  void activeProviderId;
  return request.requestedMode === 'research'
    ? AGENT_RESEARCH_DEADLINE_MS
    : AGENT_LOOKUP_DEADLINE_MS;
}

/** Result shape retained by the bounded compound scheduler. */
type CompoundDependencyFailure = Extract<AnalyticalTaskDependencyResolution, { ok: false }>;

export interface ScheduledCompoundAnalyticalTask<T> {
  task: AnalyticalTaskV1;
  value?: T;
  error?: string;
  dependencyError?: CompoundDependencyFailure;
}

/**
 * Run ready independent compound clauses concurrently, but wait for a typed
 * parent result before executing a declared dependent clause. The scheduler
 * itself has no authority to query or filter; callers supply both execution and
 * a dependency resolver so immutable-plan and SQL guards remain unchanged.
 */
export async function scheduleCompoundAnalyticalTasks<T>(input: {
  tasks: AnalyticalTaskV1[];
  runTask: (task: AnalyticalTaskV1, binding?: AnalyticalTaskDependencyBindingV1) => Promise<ScheduledCompoundAnalyticalTask<T>>;
  resolveDependency: (task: AnalyticalTaskV1, parent?: ScheduledCompoundAnalyticalTask<T>) => AnalyticalTaskDependencyResolution;
}): Promise<Array<ScheduledCompoundAnalyticalTask<T>>> {
  const pending = [...input.tasks];
  const settled = new Map<string, ScheduledCompoundAnalyticalTask<T>>();
  while (pending.length > 0) {
    const ready = pending.filter((task) => task.dependencies.every((dependencyId) => settled.has(dependencyId)));
    if (ready.length === 0) {
      for (const task of pending.splice(0)) {
        settled.set(task.id, {
          task,
          error: 'The compound task dependency graph could not be resolved.',
          dependencyError: {
            ok: false,
            code: 'RESULT_CONTRACT_MISMATCH',
            message: 'The dependent task could not run because its parent dependency was unresolved.',
          },
        });
      }
      break;
    }
    for (const task of ready) pending.splice(pending.indexOf(task), 1);
    const batch = await Promise.all(ready.map(async (task) => {
      if (!task.dependency || task.dependency.kind !== 'top_ranked_region') return input.runTask(task);
      const parent = settled.get(task.dependency.sourceTaskId);
      const resolution = input.resolveDependency(task, parent);
      if (!resolution.ok) {
        const dependencyError: CompoundDependencyFailure = resolution;
        return { task, error: dependencyError.message, dependencyError };
      }
      return input.runTask(task, resolution.binding);
    }));
    for (const result of batch) settled.set(result.task.id, result);
  }
  return input.tasks.map((task) => settled.get(task.id) ?? {
    task,
    error: 'The compound task did not produce an outcome.',
  });
}

/** What kind of narration a settled run has earned, and how many rows may ground it. */
export type AgentNarrationPlan =
  | { mode: 'skip'; reason: 'no_answer' | 'no_provider' | 'nothing_to_narrate' | 'ordinary_ask' }
  /** Claim-verified narration over the immutable fact set (analytical graph lanes). */
  | { mode: 'verified_facts'; maxRows: number }
  /** Preview-grounded narration for lanes that executed rows without a fact set. */
  | { mode: 'preview_grounded'; maxRows: number };

export type AgentNarrationAnswer =
  Pick<AgentAnswer, 'kind'>
  & Partial<Pick<
    AgentAnswer,
    'certification' | 'text' | 'answer' | 'result'
    | 'dqlArtifact' | 'exploratoryCandidate' | 'analyticalFacts' | 'analyticalNarrative'
  >>;

/**
 * Decide how a settled answer gets its business-facing prose.
 *
 * An ordinary Ask already spends its one permitted model call resolving meaning.
 * Its settled answer is the deterministic, receipt-bound answer produced by the
 * selected analytical tier; sending result rows to a second narrator would add
 * a hidden provider phase, change the egress receipt, and make a governed
 * semantic run look like Research. Only an explicit Research request may run
 * this optional, fact-checked narration stage.
 */
export type OrdinaryAskNarrationPolicy = 'off' | 'gaps_only' | 'always';

/**
 * `agent.narration.ordinaryAsk` — whether an ordinary Ask spends one extra
 * provider turn writing its answer from the host's fact set.
 *
 * Default `off`: measured on the subscription CLI transport that turn costs
 * roughly as much wall clock as the query itself, and the deterministic
 * narrative already states the headline, the leader and the share. It is a
 * setting rather than a hard rule because a team that values the prose more
 * than the seconds should be able to say so.
 */
function readOrdinaryAskNarrationPolicy(projectRoot: string): OrdinaryAskNarrationPolicy {
  const fromEnv = process.env.DQL_ASK_NARRATION;
  const accepted = new Set(['off', 'gaps_only', 'always']);
  if (fromEnv && accepted.has(fromEnv)) return fromEnv as OrdinaryAskNarrationPolicy;
  try {
    const configPath = join(projectRoot, 'dql.config.json');
    if (!existsSync(configPath)) return 'off';
    const raw = JSON.parse(readFileSync(configPath, 'utf8')) as Record<string, unknown>;
    const agent = raw.agent && typeof raw.agent === 'object' ? raw.agent as Record<string, unknown> : {};
    const narration = agent.narration && typeof agent.narration === 'object'
      ? agent.narration as Record<string, unknown>
      : {};
    const value = narration.ordinaryAsk;
    return typeof value === 'string' && accepted.has(value) ? value as OrdinaryAskNarrationPolicy : 'off';
  } catch {
    return 'off';
  }
}

export function planAgentRunNarration(
  governedAnswer: AgentNarrationAnswer,
  context: {
    requestedMode?: AgentRunRequestedMode;
    providerAvailable: boolean;
    rowEgress: ProviderResultRowEgressPolicy;
    /** `agent.narration.ordinaryAsk`; absent means off. */
    ordinaryAskNarration?: OrdinaryAskNarrationPolicy;
    /** The host projected its own deterministic facts for this answer. */
    hostFactsAvailable?: boolean;
  },
): AgentNarrationPlan {
  // A refusal is not narrated. It owes the user a reason or a clarifying
  // question, which is the clarification lane's job, not the narrator's.
  if (governedAnswer.kind === 'no_answer') return { mode: 'skip', reason: 'no_answer' };
  if (context.requestedMode !== 'research') {
    // AN ORDINARY ASK MAY NARRATE ITS OWN FACTS — AND ONLY ITS FACTS.
    //
    // The blanket skip was right about the danger and wrong about the remedy:
    // sending result ROWS to a second narrator would change the egress receipt
    // and make a governed answer look like Research. Sending the host's own
    // computed FACT SET does neither. Every sentence is checked back against
    // that fact set and the deterministic narrative remains the floor, so the
    // worst case is the answer the reader gets today.
    const policy = context.ordinaryAskNarration ?? 'off';
    const eligible = policy === 'always'
      || (policy === 'gaps_only' && governedAnswer.certification !== 'certified');
    if (!eligible) return { mode: 'skip', reason: 'ordinary_ask' };
    if (!context.providerAvailable) return { mode: 'skip', reason: 'no_provider' };
    if (!governedAnswer.analyticalFacts && !context.hostFactsAvailable) {
      return { mode: 'skip', reason: 'nothing_to_narrate' };
    }
    // maxRows 0 is the whole point: the narrator reads facts, never rows.
    return { mode: 'verified_facts', maxRows: 0 };
  }
  if (!context.providerAvailable) return { mode: 'skip', reason: 'no_provider' };
  const maxRows = Math.max(0, context.rowEgress.maxNarrationRows);
  // The fact set is the strongest grounding available: every sentence can be
  // tied back to a fact id and rejected when it is not.
  if (governedAnswer.analyticalFacts) return { mode: 'verified_facts', maxRows };
  if (governedAnswer.result) return { mode: 'preview_grounded', maxRows };
  return { mode: 'skip', reason: 'nothing_to_narrate' };
}

/**
 * Boolean view of {@link planAgentRunNarration}, kept for callers and tests that
 * only need "does this run narrate at all".
 */
export function shouldSynthesizeAgentRunAnswer(
  governedAnswer: AgentNarrationAnswer,
  requestedMode: AgentRunRequestedMode | undefined = 'ask',
): boolean {
  return planAgentRunNarration(governedAnswer, {
    requestedMode,
    providerAvailable: true,
    rowEgress: DEFAULT_ASK_ROW_EGRESS_POLICY,
  }).mode !== 'skip';
}

/**
 * A receipt may be rendered in the local inspector and exported into evaluation
 * output. Keep only stable validation codes there; provider error messages can
 * contain a prompt excerpt, result value, or connector detail and must not
 * become user-visible durable data.
 */
function narrationIntegrityFailureCodes(failures: readonly string[]): string[] {
  return [...new Set(failures.map((failure) => {
    const match = failure.trim().match(/^([A-Z][A-Z0-9_]{1,80})/);
    return match?.[1] ?? 'NARRATION_VALIDATION_FAILED';
  }).filter(Boolean))].slice(0, 8);
}

/**
 * AGT-010 — the semantic route label is descriptive, while the exact
 * route-specific aggregation proof is authoritative for governed trust.
 * Missing proof remains blocked for legacy or malformed results.
 */
/**
 * Trust for ONE answer, by the same rule the single-answer path uses: a route
 * label is not authority, and a semantic route earns `governed` only when its
 * aggregation proof actually passed.
 */
export function trustStateForAgentAnswer(
  answer: Pick<AgentAnswer, 'certification' | 'kind' | 'route' | 'aggregationSafetyProof' | 'semanticExecutionSafety'>,
): AgentRunTrustState {
  if (answer.certification === 'certified' || answer.kind === 'certified') return 'certified';
  return semanticAnswerHasPassedAggregationProof(answer) ? 'governed' : 'review_required';
}

/**
 * Persisted result payloads outlive the in-memory answer object, so they need
 * the same trust gate as the visible Ask card.  In particular, an exploratory
 * result used to inherit the old `governed` fallback merely because it had
 * rows.  Completion is not governance: only an exact certified answer or a
 * semantic answer carrying its aggregation proof may be persisted as governed.
 *
 * The `answer` overload is the normal Ask path and therefore has the proof.
 * Generic notebook/result callers deliberately fail closed: route/status words
 * such as `ai_generated`, `draft_ready`, and `analyst_review_required` are all
 * review-required, and a bare legacy `governed` string never manufactures
 * proof after the fact.
 */
function canonicalPersistedTrustState(input: {
  answer?: Pick<AgentAnswer, 'certification' | 'kind' | 'route' | 'aggregationSafetyProof' | 'semanticExecutionSafety'>;
  trustState?: unknown;
  answerTier?: unknown;
}): AgentRunTrustState | undefined {
  // A frozen plan may deliberately execute an inferred-but-unique semantic
  // substitution. Its physical result is useful, but the route has already
  // recorded an explicit `review_required` authority boundary. Never upgrade
  // that durable result marker merely because the semantic aggregation proof
  // also passed while compiling it.
  if (input.trustState === 'review_required') return 'review_required';
  if (input.answer) {
    return input.answer.kind === 'no_answer'
      ? 'blocked'
      : trustStateForAgentAnswer(input.answer);
  }
  const rawTrust = typeof input.trustState === 'string' ? input.trustState.trim().toLowerCase() : '';
  const tier = typeof input.answerTier === 'string' ? input.answerTier.trim().toLowerCase() : '';
  // These state names describe generated or analyst-review workflows, never a
  // governed proof. Keep this list explicit so a newly added presentation
  // label cannot silently gain governed trust through the old fallback.
  if (
    rawTrust === 'ai_generated'
    || rawTrust === 'draft_ready'
    || rawTrust === 'analyst_review_required'
    || rawTrust === 'exploratory'
    || tier === 'exploratory_sql'
    || tier === 'generated_sql'
    || tier === 'ai_generated'
    || tier === 'draft_ready'
    || tier === 'analyst_review_required'
  ) return 'review_required';
  if (rawTrust === 'blocked') return 'blocked';
  if (rawTrust === 'not_applicable') return 'not_applicable';
  if (rawTrust === 'review_required' || rawTrust === 'grounded') return rawTrust;
  // A bare persisted `governed` label (or an unqualified `certified` label)
  // lacks the in-memory certified block / semantic aggregation proof. It is
  // safe to display as review-required until a current Ask answer supplies
  // that proof above.
  if (rawTrust === 'governed' || rawTrust === 'certified') return 'review_required';
  return undefined;
}

const TRUST_RANK: Record<string, number> = {
  certified: 3,
  governed: 2,
  grounded: 1,
  review_required: 0,
};

/**
 * A compound answer is exactly as trustworthy as its WEAKEST successful child.
 *
 * The previous rule was `every child completed ? 'governed' : 'review_required'`,
 * which stamped `governed` on a parent whose children were review-required
 * generated SQL — completion is not proof. That is a governance violation and
 * the worst possible failure for this product: the reader is told a number
 * carries governed authority when nothing proved it.
 *
 * `certified` is deliberately NOT reachable here. Certified trust is granted
 * only by executing the exact certified artifact; a parent that merely
 * assembled certified children did not execute one, so it caps at `governed`.
 */
export function compoundTrustState(
  childTrust: readonly AgentRunTrustState[],
): AgentRunTrustState {
  if (childTrust.length === 0) return 'review_required';
  const weakest = childTrust.reduce((low, current) =>
    (TRUST_RANK[current] ?? 0) < (TRUST_RANK[low] ?? 0) ? current : low);
  return weakest === 'certified' ? 'governed' : weakest;
}

/** Neutral parent outcome: governed only when every child completed governed. */
export function compoundStopReason(
  completedCount: number,
  childCount: number,
  trustState: AgentRunTrustState,
): AgentRunStopReason {
  return completedCount === childCount && childCount > 0 && trustState === 'governed'
    ? 'governed_compound_answer'
    : 'human_review_required';
}

export function semanticAnswerHasPassedAggregationProof(
  governedAnswer: Pick<AgentAnswer, 'route' | 'aggregationSafetyProof' | 'semanticExecutionSafety'>,
): boolean {
  // Two proofs of the same fact: the V1 fanout probe, or the V2 lane's typed
  // statement that the engine owns join semantics / nothing was joined.
  return governedAnswer.route?.tier === 'semantic_metric'
    && (governedAnswer.aggregationSafetyProof?.status === 'safe'
      || governedAnswer.semanticExecutionSafety?.status === 'safe');
}

export function agentAnswerHasExecutionFailure(
  governedAnswer: Pick<AgentAnswer, 'executionError'>,
): boolean {
  return typeof governedAnswer.executionError === 'string'
    && governedAnswer.executionError.trim().length > 0;
}

/**
 * An error-shaped compatibility string is not enough to rewrite an Ask
 * failure into an execution incident when the producer retained a typed
 * analytical boundary. Compiler and result-contract failures can carry the
 * same redacted string for legacy display, but neither statement reached the
 * SQL execution failure boundary. Old payloads without a typed failure retain
 * the legacy compatibility projection.
 */
export function agentAnswerHasExecutionBoundaryFailure(
  governedAnswer: Pick<AgentAnswer, 'executionError' | 'analyticalFailure'>,
): boolean {
  return governedAnswer.analyticalFailure
    ? governedAnswer.analyticalFailure.phase === 'execution'
    : agentAnswerHasExecutionFailure(governedAnswer);
}

/**
 * Keep the producer's original refusal evidence intact, but never present a
 * post-freeze execution failure as a retrieval gap. Older answer-loop paths
 * used `grounding_gap` as their compatibility code even after a connector or
 * SQL attempt failed. The runtime is the presentation/persistence boundary,
 * so it projects that one case to the additive execution code without
 * changing the frozen plan, selected route, or source answer.
 */
export function projectAnswerExecutionFailureForRun(answer: AgentAnswer): AgentAnswer {
  if (!agentAnswerHasExecutionBoundaryFailure(answer) || answer.refusalCode === 'execution_error') return answer;
  return { ...answer, refusalCode: 'execution_error' };
}

/**
 * Persist the narrowest available terminal reason. Typed analytical failures
 * outrank legacy compatibility refusal codes so a compiler or result-contract
 * incident cannot be summarized as a grounding gap merely because its answer
 * payload also carries an old `executionError` field.
 */
function terminalFallbackReasonForAnswer(answer: AgentAnswer): string | undefined {
  if (answer.analyticalFailure?.phase === 'execution') return 'execution_error';
  if (answer.analyticalFailure) return answer.analyticalFailure.code;
  return answer.refusalCode;
}

/** A user-facing terminal heading must follow the producer's typed boundary. */
export function terminalFailureTitleForAnswer(
  answer: Pick<AgentAnswer, 'refusalCode' | 'analyticalFailure' | 'refusalDetails'>,
): string {
  return terminalTitle({
    ...(answer.refusalCode ? { refusalCode: answer.refusalCode } : {}),
    ...(answer.analyticalFailure?.phase ? { failurePhase: answer.analyticalFailure.phase } : {}),
    ...(answer.refusalDetails?.code ? { detailCode: answer.refusalDetails.code } : {}),
  });
}

/**
 * One local-runtime projection supplies all terminal presentation/evaluation
 * consumers. This prevents an execution-shaped legacy string from making the
 * title, telemetry, or evaluation disagree with the typed failure boundary.
 */
export function projectTerminalAnalyticalFailureForRun(answer: AgentAnswer): {
  answer: AgentAnswer;
  executionFailure: boolean;
  fallbackReason?: string;
  title: string;
} {
  const projected = projectAnswerExecutionFailureForRun(answer);
  return {
    answer: projected,
    executionFailure: agentAnswerHasExecutionBoundaryFailure(answer),
    ...(terminalFallbackReasonForAnswer(projected)
      ? { fallbackReason: terminalFallbackReasonForAnswer(projected) }
      : {}),
    title: terminalFailureTitleForAnswer(projected),
  };
}

/**
 * Return only a router/producer-issued analytical gap witness.
 *
 * `terminalOutcome.kind === 'modeling_gap'` is deliberately insufficient to
 * claim a relationship problem. Older receipts and generic tuple failures
 * return `undefined`; callers render generic coverage guidance for those.
 */
export function persistedAnalyticalGapWitness(
  routeDecision: IntentDecision | undefined,
): NonNullable<NonNullable<IntentDecision['terminalOutcome']>['gap']> | undefined {
  return routeDecision?.terminalOutcome?.kind === 'modeling_gap'
    ? routeDecision.terminalOutcome.gap
    : undefined;
}

/** Rebuild the immutable failed-run input from the artifact retained by API-007. */
export function analyticalFailedRunFromAgentRun(run: AgentRun): AnalyticalFailedRunV1 | undefined {
  for (const artifact of run.artifacts) {
    const payload = agentRunRecord(artifact.payload);
    if (!payload) continue;
    const failure = normalizeAnalyticalFailureV1(payload.analyticalFailure);
    const plan = agentRunRecord(payload.resolvedAnalyticalPlan);
    const planFingerprint = agentRunString(plan?.fingerprint) ?? failure?.planFingerprint;
    if (!failure || !planFingerprint) continue;
    const dqlArtifact = normalizeDqlArtifactReference(payload.dqlArtifact);
    const dqlSource = dqlArtifact?.source;
    const compiledSql = agentRunString(payload.sql)
      ?? agentRunString(payload.proposedSql)
      ?? dqlArtifact?.compiledSql;
    const graph = agentRunRecord(payload.analyticalExecutionGraph);
    const rawRoute = agentRunString(graph?.route) ?? agentRunString(plan?.recommendedRoute);
    const route: AnalyticalFailedRunV1['route'] = rawRoute === 'certified'
      ? 'certified'
      : rawRoute === 'semantic'
        ? 'semantic'
        : rawRoute === 'governed_sql'
          ? 'governed_sql'
          : 'generated_sql';
    const rawTrust = dqlArtifact?.trustState ?? agentRunString(payload.reviewStatus) ?? artifact.trustState;
    const trustState: AnalyticalFailedRunV1['trustState'] = rawTrust === 'certified'
      ? 'certified'
      : rawTrust === 'governed'
        ? 'governed'
        : 'review_required';
    return {
      version: 1,
      runId: failure.runId,
      snapshotId: failure.snapshotId,
      route,
      trustState,
      planFingerprint,
      ...(dqlSource ? { dqlSource } : {}),
      ...(failure.dqlFingerprint ? { dqlFingerprint: failure.dqlFingerprint } : {}),
      ...(compiledSql ? { compiledSql } : {}),
      ...(failure.sqlFingerprint ? { sqlFingerprint: failure.sqlFingerprint } : {}),
      failure,
    };
  }
  return undefined;
}

/** Exact failed statement retained on an immutable run, if one exists. */
export function repairableSqlFromAgentRun(run: AgentRun): string | undefined {
  for (const artifact of run.artifacts) {
    const payload = agentRunRecord(artifact.payload);
    if (!payload) continue;
    const dqlArtifact = normalizeDqlArtifactReference(payload.dqlArtifact);
    const sql = agentRunString(payload.proposedSql)
      ?? agentRunString(payload.sql)
      ?? dqlArtifact?.compiledSql;
    if (sql?.trim()) return sql.trim();
  }
  return undefined;
}

/** Editable DQL retained on an immutable failed run, including its bound values. */
export function repairableDqlArtifactFromAgentRun(run: AgentRun): DqlArtifactReference | undefined {
  for (const artifact of run.artifacts) {
    const payload = agentRunRecord(artifact.payload);
    if (!payload) continue;
    const dqlArtifact = normalizeDqlArtifactReference(payload.dqlArtifact);
    // Only an ownerless/custom SQL block is editable in place. Certified and
    // semantic artifacts remain immutable; their retained compiled SQL may
    // still produce a separate review-required repair result below.
    if (dqlArtifact?.kind === 'sql_block'
      && dqlArtifact.source?.trim()
      && notebookDqlSourceAllowsBackgroundRepair(dqlArtifact.source)) {
      return dqlArtifact;
    }
  }
  return undefined;
}

/**
 * Keep the parameter surface immutable while repairing malformed DQL. A parser
 * cannot reliably read a broken wrapper, so collect both declared parameter
 * names and SQL interpolation names with a deliberately small lexical pass.
 */
export function dqlRepairParameterContract(source: string): string[] {
  const names = new Set<string>();
  for (const match of source.matchAll(/\$\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}/g)) {
    names.add(match[1]);
  }
  for (const match of source.matchAll(/\bparams\s*\{([\s\S]*?)\}/gi)) {
    for (const declaration of match[1].matchAll(/(?:^|\n)\s*([A-Za-z_][A-Za-z0-9_]*)\s*:/g)) {
      names.add(declaration[1]);
    }
  }
  return [...names].sort((left, right) => left.localeCompare(right));
}

/** Structured producer failure retained on the source run. */
export function warehouseFailureFromAgentRun(run: AgentRun): WarehouseSqlFailureV1 | undefined {
  for (const artifact of run.artifacts) {
    const payload = agentRunRecord(artifact.payload);
    const failure = agentRunRecord(payload?.warehouseFailure);
    if (failure?.version !== 1 || typeof failure.redactedMessage !== 'string') continue;
    return failure as unknown as WarehouseSqlFailureV1;
  }
  return undefined;
}

const AUTOMATIC_ASK_REPAIR_FAILURE_CODES = new Set([
  'COLUMN_NOT_FOUND',
  'RELATION_NOT_FOUND',
  'AMBIGUOUS_COLUMN',
  'DIALECT_ERROR',
]);

/** Validate the immutable custom wrapper before any automatic repair is offered. */
export function validAskRepairDqlWrapper(source: string): boolean {
  try {
    const program = new Parser(source, '<ask-repair-capability>').parse();
    if (program.statements.length !== 1) return false;
    const block = program.statements[0];
    return block.kind === NodeKind.BlockDecl
      && block.blockType === 'custom'
      && Boolean(extractBlockStudioSql(source)?.trim());
  } catch {
    return false;
  }
}

/** Build retained automatic-repair authority from analytical failure state only. */
export function analyticalRepairCapabilityForAgentRun(
  run: AgentRun,
  resolvedTargetFingerprint?: string,
): AnalyticalRepairCapabilityV1 | undefined {
  if (run.status !== 'blocked' || run.stopReason !== 'blocked') return undefined;
  const failedRun = analyticalFailedRunFromAgentRun(run);
  const failure = failedRun?.failure;
  const dqlArtifact = run.artifacts.flatMap((artifact) => {
    const payload = agentRunRecord(artifact.payload);
    const candidate = normalizeDqlArtifactReference(payload?.dqlArtifact);
    return candidate?.kind === 'sql_block' && candidate.source?.trim() ? [candidate] : [];
  })[0];
  const dqlSource = dqlArtifact?.source?.trim();
  const sql = dqlArtifact?.compiledSql?.trim() || repairableSqlFromAgentRun(run);
  const target = run.executionTarget;
  const planFingerprint = failure?.planFingerprint?.trim();
  const hash = (value: unknown): string => `sha256:${createHash('sha256').update(stableExecutionValue(value)).digest('hex')}`;
  const sourceArtifact = run.artifacts.find((artifact) => {
    const payload = agentRunRecord(artifact.payload);
    return Boolean(normalizeDqlArtifactReference(payload?.dqlArtifact)?.source?.trim());
  });
  const retainedPlanFingerprint = sourceArtifact
    ? agentRunString(agentRunRecord(agentRunRecord(sourceArtifact.payload)?.resolvedAnalyticalPlan)?.fingerprint)
    : undefined;
  const sourceFingerprint = sourceArtifact && dqlArtifact
    ? hash({
        runId: run.id,
        artifactId: sourceArtifact.id,
        dqlArtifact: {
          kind: dqlArtifact.kind,
          name: dqlArtifact.name,
          source: dqlArtifact.source?.trim(),
          parameterValues: dqlArtifact.parameterValues ?? {},
          trustState: dqlArtifact.trustState,
          persistence: dqlArtifact.persistence,
        },
      })
    : undefined;
  const manualActions: Array<AnalyticalRepairCapabilityV1['manualActions'][number]> = (failure?.safeActions ?? []).flatMap((action) => {
    if (action === 'edit_dql' || action === 'open_sql_notebook' || action === 'refresh_snapshot'
      || action === 'retry_same_plan' || action === 'change_authorized_connection' || action === 'request_access') {
      return [action];
    }
    return [];
  });
  const ineligibilityReason: AnalyticalRepairCapabilityV1['ineligibilityReason'] = !failure
    ? 'missing_failure_authority'
    : failure.phase !== 'execution' || !AUTOMATIC_ASK_REPAIR_FAILURE_CODES.has(failure.code)
      ? 'failure_not_eligible'
      : !dqlSource
        ? 'missing_dql_wrapper'
        : !validAskRepairDqlWrapper(dqlSource)
          ? 'invalid_dql_wrapper'
          : !sql
            ? 'missing_compiled_sql'
          : !planFingerprint || !retainedPlanFingerprint || retainedPlanFingerprint !== planFingerprint
              ? 'missing_plan_fingerprint'
              : !sourceFingerprint
                ? 'missing_dql_wrapper'
              : !target || !resolvedTargetFingerprint
                ? 'missing_execution_target'
                : undefined;
  const eligible = ineligibilityReason === undefined;
  return {
    version: 1,
    automatic: {
      eligible,
      action: eligible ? 'repair_embedded_sql' : 'none',
      correctionCode: eligible ? 'SQL_EXECUTION_REPAIR' : 'MANUAL_REVIEW_REQUIRED',
      attemptsRemaining: eligible ? 1 : 0,
    },
    failureFingerprint: hash(failure ?? { unavailable: 'analytical_failure', runId: run.id }),
    sourceFingerprint: sourceFingerprint ?? hash({ unavailable: 'source', runId: run.id }),
    planFingerprint: retainedPlanFingerprint ?? planFingerprint ?? hash({ unavailable: 'plan', runId: run.id }),
    dqlFingerprint: dqlSource ? hash(dqlSource) : hash({ unavailable: 'dql', runId: run.id }),
    sqlFingerprint: sql ? hash(sql) : hash({ unavailable: 'sql', runId: run.id }),
    targetFingerprint: resolvedTargetFingerprint ?? hash({ unavailable: 'target', runId: run.id }),
    routeLocked: true,
    targetLocked: true,
    sourceImmutable: true,
    manualActions: Array.from(new Set(manualActions)),
    ...(ineligibilityReason ? { ineligibilityReason } : {}),
  };
}

function attachAnalyticalRepairCapability(run: AgentRun, resolvedTargetFingerprint?: string): AgentRun {
  const capability = analyticalRepairCapabilityForAgentRun(run, resolvedTargetFingerprint);
  if (!capability) return run;
  run.repairCapability = capability;
  if (run.diagnosticReceipt) run.diagnosticReceipt = { ...run.diagnosticReceipt, repairCapability: capability };
  run.artifacts = run.artifacts.map((artifact) => {
    const payload = agentRunRecord(artifact.payload);
    if (!payload) return artifact;
    const diagnostic = agentRunRecord(payload.diagnosticReceipt);
    return {
      ...artifact,
      payload: {
        ...payload,
        repairCapability: capability,
        ...(diagnostic ? { diagnosticReceipt: { ...diagnostic, repairCapability: capability } } : {}),
      },
    };
  });
  return run;
}

export function targetGenerationFingerprint(connection: ConnectionConfig, connectionName?: string): string {
  const identity = {
    driver: connection.driver,
    connectionName: connectionName ?? null,
    host: connection.host ?? null,
    port: connection.port ?? null,
    username: connection.username ?? null,
    authMethod: connection.authMethod ?? null,
    authenticator: connection.authenticator ?? null,
    profile: connection.profile ?? null,
    ssl: connection.ssl ?? null,
    account: connection.account ?? null,
    database: connection.database ?? null,
    schema: connection.schema ?? null,
    warehouse: connection.warehouse ?? null,
    role: connection.role ?? null,
    catalog: connection.catalog ?? null,
    httpPath: connection.httpPath ?? null,
    filepath: connection.filepath ?? null,
    projectId: connection.projectId ?? null,
    region: connection.region ?? null,
    workgroup: connection.workgroup ?? null,
    location: connection.location ?? null,
    outputLocation: connection.outputLocation ?? null,
    accessUrl: connection.accessUrl ?? null,
    application: connection.application ?? null,
    queryTag: connection.queryTag ?? null,
    workloadIdentityProvider: connection.workloadIdentityProvider ?? null,
    workloadIdentityAzureClientId: connection.workloadIdentityAzureClientId ?? null,
    workloadIdentityImpersonationPath: connection.workloadIdentityImpersonationPath ?? null,
    oauthAuthorizationUrl: connection.oauthAuthorizationUrl ?? null,
    oauthClientId: connection.oauthClientId ?? null,
    oauthRedirectUri: connection.oauthRedirectUri ?? null,
    oauthScope: connection.oauthScope ?? null,
    oauthTokenRequestUrl: connection.oauthTokenRequestUrl ?? null,
    keyFilename: connection.keyFilename ?? null,
    privateKeyPath: connection.privateKeyPath ?? null,
    accessKeyId: connection.accessKeyId ?? null,
    proxyHost: connection.proxyHost ?? null,
    proxyPort: connection.proxyPort ?? null,
    proxyProtocol: connection.proxyProtocol ?? null,
    proxyUser: connection.proxyUser ?? null,
    noProxy: connection.noProxy ?? null,
    credentialCacheDir: connection.credentialCacheDir ?? null,
    moduleSearchPaths: connection.moduleSearchPaths ?? null,
    clientRequestMFAToken: connection.clientRequestMFAToken ?? null,
    clientStoreTemporaryCredential: connection.clientStoreTemporaryCredential ?? null,
    clientSessionKeepAlive: connection.clientSessionKeepAlive ?? null,
    clientSessionKeepAliveHeartbeatFrequency: connection.clientSessionKeepAliveHeartbeatFrequency ?? null,
    keepAlive: connection.keepAlive ?? null,
    passcodeInPassword: connection.passcodeInPassword ?? null,
    browserActionTimeout: connection.browserActionTimeout ?? null,
    timeout: connection.timeout ?? null,
    waitTimeout: connection.waitTimeout ?? null,
    byteLimit: connection.byteLimit ?? null,
  };
  return executionFingerprint(stableExecutionValue(identity));
}

function normalizeSqlForComparison(sql: string): string {
  return sql.trim().replace(/;\s*$/, '').replace(/\s+/g, ' ');
}

/**
 * Retain planning and retrieval evidence for a successful derived repair while
 * deliberately dropping the source failure and any result-bound facts. This
 * is the presentation contract used by "How it was answered" and by grounded
 * follow-ups after repair.
 */
export function repairPresentationContextFromAgentRun(run: AgentRun): Record<string, unknown> {
  const retainedKeys = [
    'resolvedAnalyticalPlan',
    'analyticalExecutionGraph',
    'analyticalFreshnessObservation',
    'governedCompilationReceipt',
    'governedAnalyticalGraphCompilationReceipt',
    'contextPack',
    'contextPackId',
    'cascade',
    'citations',
    'lineage',
  ] as const;
  const context: Record<string, unknown> = {};
  for (const artifact of run.artifacts) {
    const payload = agentRunRecord(artifact.payload);
    if (!payload) continue;
    for (const key of retainedKeys) {
      if (context[key] === undefined && payload[key] !== undefined) context[key] = payload[key];
    }
    const semanticTrace = agentRunRecord(payload.semanticExecutionTrace);
    if (context.semanticExecutionTrace === undefined && semanticTrace && !semanticTrace.failure) {
      context.semanticExecutionTrace = semanticTrace;
    }
  }
  return context;
}

/** Permission, authentication, policy and unsafe-query failures are never AI-repaired. */
export function analyticalFailureAllowsDeterministicRetry(failure?: WarehouseSqlFailureV1): boolean {
  return !failure || !['permission', 'authentication', 'unsafe', 'cancelled'].includes(failure.category);
}

/** Structured policy/access refusals stay terminal even when retained SQL exists. */
export function analyticalFailureAllowsAppRepair(failure?: AgentAnswer['analyticalFailure']): boolean {
  return !failure || !['PERMISSION_DENIED', 'POLICY_DENIED'].includes(failure.code);
}

function businessNarrativeGaps(warnings: string[] | undefined): string[] | undefined {
  const businessRelevant = (warnings ?? []).filter((warning) => !(
    /missing requested output column/i.test(warning)
    || /\bquery plan\b/i.test(warning)
    || /\bgrain\b/i.test(warning)
    || /\bcolumn(?:s)?\b.*\bmissing\b/i.test(warning)
    || /\bSQL\b|\bDBT\b|\bjoin probe\b/i.test(warning)
  ));
  return businessRelevant.length > 0 ? businessRelevant : undefined;
}

// ── Server-side conversation threads ────────────────────────────────────────
// When a run carries a threadId, the persisted thread is the authoritative
// source of prior turns (survives refresh); the client-built context remains
// the fallback for embedders that never send a threadId.

async function conversationContextFromThread(
  store: ConversationStore,
  threadId: string,
  question?: string,
  preservePendingClarification = false,
): Promise<Record<string, unknown>> {
  // Token-budget backstop: six verbatim turns with per-field caps. Older turns
  // remain reachable through the rolling summary + semantic recall below —
  // carrying more raw prose mostly slows every provider call on follow-ups.
  const clampTurnText = (value: string | undefined): string | undefined =>
    value && value.length > 1_200 ? `${value.slice(0, 1_200)}…` : value;
  const turns = store.recentTurns(threadId, 6).map((turn) => {
    const contract = turn.contract ?? {};
    const topN = contract.topN;
    const topNValue = typeof topN === 'number'
      ? topN
      : topN && typeof topN === 'object' && typeof (topN as { n?: unknown }).n === 'number'
        ? (topN as { n: number }).n
        : undefined;
    return compactConversationRecord({
      id: turn.id,
      question: clampTurnText(turn.question),
      answerSummary: clampTurnText(turn.answerSummary),
      sourceCertifiedBlock: turn.sourceCertifiedBlock,
      route: turn.route,
      trustLabel: turn.trustLabel,
      runStatus: turn.runStatus,
      stopReason: turn.stopReason,
      // Carried so every consumer can compute trust from the same fields.
      refusalCode: turn.refusalCode,
      executionError: turn.executionError,
      certification: turn.certification,
      contextPackId: turn.contextPackId,
      dqlArtifact: turn.dqlArtifact,
      cascade: turn.cascade,
      sourceSql: turn.sql,
      requestedFilters: conversationStringArray(contract.filters),
      requestedDimensions: conversationStringArray(contract.dimensions),
      requestedMeasures: conversationStringArray(contract.measures),
      rankingDirection: agentRunString(contract.rankingDirection),
      topN: topNValue,
      result: turn.result
        ? compactConversationRecord({
            columns: turn.result.columns,
            rowsSample: turn.result.rowsSample,
            dimensionValues: turn.result.dimensionValues,
            memberSets: turn.result.memberSets,
            resultFingerprint: turn.result.resultFingerprint,
            measureColumns: turn.result.measureColumns,
            rowCount: turn.result.rowCount,
          })
        : undefined,
    });
  }).filter((turn): turn is Record<string, unknown> => Boolean(turn));
  const thread = store.getThread(threadId);
  // Bounded structured snapshot (working state + rolling summary + topic relation)
  // for the answer loop's conversation-state prompt section.
  const serverSnapshot = buildConversationSnapshot(store, threadId, {
    question,
    preservePendingClarification,
  });
  if (serverSnapshot && question) {
    // Semantic recall over OLDER turns (the recent window is already verbatim).
    serverSnapshot.recalledTurns = await recallRelevantTurns(store, threadId, question, {
      limit: 3,
      excludeTurnIds: serverSnapshot.recentTurns.map((turn) => turn.id),
    });
  }
  const pendingSelection = serverSnapshot?.pendingClarification?.selection;
  const pendingSourceTurnId = serverSnapshot?.pendingClarification?.sourceTurnId;
  // This value never crosses the HTTP boundary from a client. It is rebuilt
  // only after the local conversation store has resolved the requested thread,
  // and the router requires it for every selectedEvidenceId continuation.
  const serverIssuedClarificationSelection = pendingSelection?.snapshotId && pendingSourceTurnId
    ? {
        version: 1 as const,
        threadId,
        sourceTurnId: pendingSourceTurnId,
        snapshotId: pendingSelection.snapshotId,
        ...(pendingSelection.continuityFingerprint
          ? { continuityFingerprint: pendingSelection.continuityFingerprint }
          : {}),
      }
    : undefined;
  // A valid local thread is the sole authority for continuation context.
  // In particular, do not merge browser-carried result rows, dimensions,
  // source blocks, history, or prior-result member sets here: a redacted
  // persisted result must remain unavailable rather than being repopulated
  // with attacker-controlled values that later become a server-side filter.
  // Request-level non-authoritative UI hints travel through `workspaceContext`
  // and `selectedObject`, not this execution-relevant conversation envelope.
  return {
    conversationStateVersion: 1,
    threadId,
    ...(serverSnapshot ? { conversationEnvelope: serverSnapshot } : {}),
    ...(serverSnapshot ? { serverSnapshot } : {}),
    ...(serverIssuedClarificationSelection ? { serverIssuedClarificationSelection } : {}),
    ...(thread?.rollingSummary ? { conversationSummary: thread.rollingSummary } : {}),
    // `activeTurnId` is the FOLLOW-UP ANCHOR: the turn whose filters, prior DQL
    // artifact, and source SQL the next question builds on. Anchoring it to the
    // last turn unconditionally meant a failed turn became the anchor, and its
    // broken artifact and failing SQL were handed to the next question as
    // authoritative context — the sticky-error loop. `latestTurnId` keeps the
    // real tail for presentation.
    ...(turns.length > 0
      ? {
          turns,
          activeTurnId: lastTrustedTurnId(turns) ?? undefined,
          latestTurnId: (turns[turns.length - 1] as { id?: string }).id,
        }
      : {}),
  } as Record<string, unknown>;
}

/** The most recent turn a follow-up may safely build on. */
function lastTrustedTurnId(turns: Array<Record<string, unknown>>): string | undefined {
  for (let index = turns.length - 1; index >= 0; index -= 1) {
    const turn = turns[index] as Record<string, unknown> & { id?: string };
    // Chat-only recap and greeting turns are trustworthy prose, but they are
    // not a result-set anchor. Selecting one here discarded the prior
    // certified result's typed member set after reload, so "those customers"
    // quietly widened to every customer. Keep the latest substantive result
    // as the follow-up anchor; the recap is still retained as `latestTurnId`.
    if (isTrustedConversationTurn(turn as Parameters<typeof isTrustedConversationTurn>[0])
      && conversationTurnHasUsefulResult(turn)) return turn.id;
  }
  return undefined;
}

function conversationTurnHasUsefulResult(turn: Record<string, unknown>): boolean {
  const result = agentRunRecord(turn.result);
  if (!result) return false;
  return Array.isArray(result.columns) && result.columns.length > 0
    || Array.isArray(result.rowsSample) && result.rowsSample.length > 0
    || agentRunRecord(result.dimensionValues) && Object.keys(agentRunRecord(result.dimensionValues)!).length > 0
    || Array.isArray(result.memberSets) && result.memberSets.length > 0;
}

/**
 * A plural deictic phrase is an operation over a previously displayed set,
 * not an invitation to rerun the question over every row in the warehouse.
 * This intentionally lives at the HTTP host boundary because only this host
 * knows whether a persisted thread was resolved before the Ask runtime begins.
 */
function pluralPriorResultEntityReference(question: string): string | undefined {
  const normalized = question.toLowerCase().replace(/[^a-z0-9\s]/g, ' ');
  const match = normalized.match(/\b(?:those|these|the\s+(?:previous|prior)|above)\s+(customers|accounts|products|orders|opportunities|regions|categories)\b/);
  if (!match) return undefined;
  const plural = match[1];
  return plural === 'categories' ? 'category' : plural.slice(0, -1);
}

function markUnavailablePluralPriorResultSet(request: AgentRunRequest): void {
  if (request.selectedResultBindingGap || request.priorResultMemberBinding) return;
  const entity = pluralPriorResultEntityReference(request.question);
  if (!entity) return;
  request.selectedResultBindingGap = {
    code: 'PRIOR_RESULT_MEMBER_SET_UNAVAILABLE',
    message: `The previous result did not retain the displayed ${entity} set needed for this follow-up, so it cannot safely run against all data.`,
  };
}

/**
 * Carry a server-validated selected-result predicate into the same typed Ask
 * seed that retrieval, planning, and the compiler consume. The browser never
 * controls this data: callers invoke it only after durable local history or a
 * persisted conversation envelope has proved the binding.
 */
function seedWithPriorResultMemberBinding(
  seed: AnalyticalRequirementSeedV1,
  binding: NonNullable<AgentRunRequest['priorResultMemberBinding']>,
): AnalyticalRequirementSeedV1 {
  const requirements = withAnalyticalPriorResultMemberBinding(seed.requirements, binding);
  const filters = seed.queryIntent.filters.map((filter) => ({ ...filter }));
  for (const value of binding.values) {
    const alreadyPresent = filters.some((filter) =>
      filter.field.trim().toLowerCase() === binding.displayDimension.trim().toLowerCase()
      && filter.value.trim().toLowerCase() === value.trim().toLowerCase());
    if (!alreadyPresent) filters.push({ field: binding.displayDimension, value });
  }
  return {
    ...seed,
    requirements,
    queryIntent: {
      ...seed.queryIntent,
      filters,
    },
  };
}

/**
 * Resolve a browser-selected result cell from durable local run storage. This
 * remains valid after a notebook reload because the browser transmits only
 * stable IDs/fingerprints; result values are accepted only after this host
 * checks the persisted canonical result and artifact trust state.
 */
export function hydratePersistedSelectedResultBinding(
  request: AgentRunRequest,
  store: Pick<SqliteAgentRunStore, 'get'>,
): void {
  const binding = request.selectedResultBinding;
  if (!binding || request.askAnalystTaskChild || request.researchBranch) return;
  const fail = (code: string, message: string) => {
    delete request.selectedResultBinding;
    request.selectedResultBindingGap = { code, message };
  };
  const sourceRun = store.get(binding.sourceRunId);
  if (!sourceRun) {
    fail('PRIOR_RESULT_BINDING_UNAVAILABLE', 'The selected prior result is not available in this local run history.');
    return;
  }
  const sourceArtifact = sourceRun.artifacts.find((artifact) => artifact.id === binding.sourceArtifactId);
  if (!sourceArtifact || sourceArtifact.trustState === 'blocked') {
    fail('PRIOR_RESULT_BINDING_UNAVAILABLE', 'The selected prior result artifact is unavailable or was not accepted.');
    return;
  }
  const payload = agentRunRecord(sourceArtifact.payload);
  const rawResult = agentRunRecord(payload?.result) ?? agentRunRecord(payload?.resultPreview);
  const canonical = rawResult ? normalizeCanonicalQueryResult({
    columns: rawResult.columns,
    rows: rawResult.rows,
    rowCount: rawResult.rowCount,
    executionTime: rawResult.executionTime,
    resultFingerprint: agentRunString(rawResult.resultFingerprint),
    executionReceipt: rawResult.executionReceipt,
    trustState: rawResult.trustState,
    answerTier: rawResult.answerTier,
  }) : undefined;
  const validated = validateSelectedResultBinding(binding, canonical);
  if (!validated.ok) {
    fail(validated.code, validated.message);
    return;
  }
  request.conversationBinding = 'prior_result';
  const priorResultMemberBinding = {
    version: 1 as const,
    displayDimension: binding.canonicalColumn,
    values: [binding.value],
    sourceTurnId: binding.sourceRunId,
    resultFingerprint: binding.resultFingerprint,
  };
  request.priorResultMemberBinding = priorResultMemberBinding;
  const seed = request.hostRequirementSeed?.version === 1
    && request.hostRequirementSeed.sourceQuestion === request.question
    ? request.hostRequirementSeed
    : buildAnalyticalRequirementSeedV1({ question: request.question });
  request.hostRequirementSeed = {
    ...seedWithPriorResultMemberBinding(seed, priorResultMemberBinding),
    sourceQuestion: request.question,
  };
}

/**
 * An additive projection has to name its connection to the displayed result.
 * A bare "show revenue by region" is a fresh Ask, while "add region here" is
 * an explicit request to retain the successful result's analytical shape.
 * Keeping this intentionally narrow prevents a coincidental shared word from
 * replaying an unrelated prior plan.
 */
function isExplicitAnalyticalShapeContinuation(question: string): boolean {
  return /\b(?:add|include|also\s+(?:show|include))\s+(?:the\s+)?[a-z][a-z0-9_ -]{0,48}\s+(?:here|there|too|as\s+well)\b/i.test(question);
}

function stableConversationResultFingerprint(result: Record<string, unknown>): string | undefined {
  const direct = agentRunString(result.resultFingerprint)?.toLowerCase();
  if (direct && /^[a-f0-9]{64}$/.test(direct)) return direct;
  // Turns persisted before the direct result-level field still retain a
  // content-free fingerprint on their bounded entity member set. Reuse it
  // only when every retained set agrees, never by inventing one from rows.
  const fingerprints = Array.from(new Set((Array.isArray(result.memberSets) ? result.memberSets : [])
    .map((set) => agentRunRecord(set))
    .map((set) => agentRunString(set?.resultFingerprint)?.toLowerCase())
    .filter((value): value is string => Boolean(value && /^[a-f0-9]{64}$/.test(value)))));
  return fingerprints.length === 1 ? fingerprints[0] : undefined;
}

function boundedAnalyticalShapeTerms(values: Array<string | undefined>, max = 8): string[] {
  const seen = new Set<string>();
  const terms: string[] = [];
  for (const value of values) {
    const trimmed = value?.trim();
    if (!trimmed) continue;
    const key = trimmed.toLowerCase().replace(/[_.:/-]+/g, ' ').replace(/\s+/g, ' ').trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    terms.push(trimmed);
    if (terms.length >= max) break;
  }
  return terms;
}

/**
 * Derive a narrow, host-only analytical-shape anchor from a completed result.
 * No prose, SQL, rows, provider output, or browser fields become authority:
 * only the locally persisted source turn, its result fingerprint, and bounded
 * task shape are carried to the V3 program.
 */
function trustedAnalyticalShapeAnchorFromFollowUp(
  request: AgentRunRequest,
  context: Record<string, unknown> | undefined,
  followUp: ReturnType<typeof resolveAgentFollowUpContext>,
): TrustedAnalyticalTaskAnchorV1 | undefined {
  if (!isExplicitAnalyticalShapeContinuation(request.question)
    || followUp?.binding !== 'prior_result') return undefined;
  const sourceTurnId = agentRunString(followUp.sourceTurnId) ?? agentRunString(context?.activeTurnId);
  if (!sourceTurnId) return undefined;
  const source = (Array.isArray(context?.turns) ? context.turns : [])
    .map((turn) => agentRunRecord(turn))
    .find((turn) => agentRunString(turn?.id) === sourceTurnId);
  // A provisional, failed, blocked, clarification, or cancelled turn must
  // never become an analytical-shape source. This is deliberately stricter
  // than generic conversational context: the continuation changes execution.
  if (!source || agentRunString(source.runStatus) !== 'completed'
    || !isTrustedConversationTurn(source as Parameters<typeof isTrustedConversationTurn>[0])
    || !conversationTurnHasUsefulResult(source)) return undefined;
  const result = agentRunRecord(source.result);
  if (!result) return undefined;
  const resultFingerprint = stableConversationResultFingerprint(result);
  if (!resultFingerprint) return undefined;

  const contract = agentRunRecord(source.contract);
  const measures = boundedAnalyticalShapeTerms([
    ...(conversationStringArray(source.requestedMeasures) ?? []),
    ...(conversationStringArray(contract?.measures) ?? []),
    ...(conversationStringArray(result.measureColumns) ?? []),
  ]);
  // A result with no identified metric cannot safely supply an analytical
  // shape. The next turn remains a fresh Ask rather than inheriting a random
  // projection from a row-oriented result.
  if (measures.length === 0) return undefined;
  const dimensions = boundedAnalyticalShapeTerms([
    ...(conversationStringArray(source.requestedDimensions) ?? []),
    ...(conversationStringArray(contract?.dimensions) ?? []),
    ...(conversationStringArray(followUp.dimensions) ?? []),
  ]);
  return {
    version: 1,
    kind: 'analytical_shape',
    values: [],
    measures,
    ...(dimensions.length ? { dimensions } : {}),
    sourceTurnId,
    resultFingerprint,
  };
}

function seedWithTrustedAnalyticalShapeAnchor(
  seed: AnalyticalRequirementSeedV1,
  anchor: TrustedAnalyticalTaskAnchorV1,
): AnalyticalRequirementSeedV1 {
  const measures = boundedAnalyticalShapeTerms([
    ...seed.requirements.measures,
    ...(anchor.measures ?? []),
  ]);
  const dimensions = boundedAnalyticalShapeTerms([
    ...seed.requirements.dimensions,
    ...(anchor.dimensions ?? []),
  ]);
  const displayTerms = dimensions
    .map((dimension) => dimension.replace(/[_.:/-]+/g, ' ').replace(/\s+/g, ' ').trim())
    .filter((dimension) => /\b(?:name|label|email)\b$/i.test(dimension));
  const entityTerms = displayTerms
    .map((dimension) => dimension.replace(/\b(?:name|label|email)\b$/i, '').trim())
    .filter(Boolean);
  return buildAnalyticalRequirementSeedV1({
    question: seed.sourceQuestion,
    requirements: {
      ...seed.requirements,
      measures,
      dimensions,
      entityTerms: boundedAnalyticalShapeTerms([...seed.requirements.entityTerms, ...entityTerms]),
      entityDisplayTerms: boundedAnalyticalShapeTerms([...seed.requirements.entityDisplayTerms, ...displayTerms]),
      outputTerms: boundedAnalyticalShapeTerms([
        ...(seed.requirements.outputTerms ?? []),
        ...dimensions,
      ]),
    },
  });
}

/**
 * Materialize a plural prior-result reference before the authoritative Ask
 * runtime frames the request.  `buildAgentRunContextPack` also classifies
 * follow-ups for retrieval diagnostics, but it runs after the Ask runtime has
 * built its immutable requirement seed.  Applying this only after retrieval
 * made "those customers" an explanation-only hint and let a follow-up rank
 * the entire warehouse.
 *
 * This is intentionally an HTTP-host boundary: it accepts only the
 * server-reconstructed conversation envelope for the requested persisted
 * thread. Browser conversation JSON cannot supply this filter, a prior member
 * set, a shape anchor, or a host requirement seed. The values remain local
 * execution context; they are never copied into provider prompts.
 */
export function hydratePersistedPriorResultMemberBinding(request: AgentRunRequest): void {
  if (!request.threadId || request.askAnalystTaskChild || request.researchBranch) return;
  const context = request.conversationContext;
  const envelope = agentRunRecord(context?.conversationEnvelope);
  if (!envelope || agentRunString(envelope.threadId) !== request.threadId) return;

  const followUp = resolveAgentFollowUpContext(context, request.question);
  request.conversationBinding = followUp?.binding ?? request.conversationBinding ?? 'none';
  if (followUp?.priorResultSetUnavailable) {
    request.selectedResultBindingGap = {
      code: 'PRIOR_RESULT_MEMBER_SET_UNAVAILABLE',
      message: followUp.unresolvedReferences?.[0]
        ?? 'The prior result set is unavailable, so this follow-up cannot safely run against all data.',
    };
    return;
  }
  if (followUp?.binding !== 'prior_result') return;

  const trustedTaskAnchor = trustedAnalyticalShapeAnchorFromFollowUp(request, context, followUp);
  if (trustedTaskAnchor) {
    request.trustedTaskAnchor = trustedTaskAnchor;
    const seed = request.hostRequirementSeed?.version === 1
      && request.hostRequirementSeed.sourceQuestion === request.question
      ? request.hostRequirementSeed
      : buildAnalyticalRequirementSeedV1({ question: request.question });
    request.hostRequirementSeed = seedWithTrustedAnalyticalShapeAnchor(seed, trustedTaskAnchor);
  }

  const rawBinding = followUp.memberBindings?.find((binding) =>
    binding.source === 'prior_result' && binding.values.length > 0);
  if (!rawBinding) {
    // An ambiguous singular reference over several displayed members is a
    // question for the user, not a failure. The resolver deliberately declines
    // to guess which of ten customers "he" meant; turning that into a typed
    // gap here makes the run ask, instead of dead-ending as "not enough
    // context" — the answer was one tap away the whole time.
    const choices = followUp.deicticChoices;
    if (choices && choices.values.length > 1) {
      const options = choices.values.slice(0, 8).map((value) => ({
        id: `member:${choices.dimension}:${value}`,
        label: value,
        kind: 'member',
        question: `${request.question} (${value})`,
      }));
      request.selectedResultBindingGap = {
        code: 'PRIOR_RESULT_MEMBER_AMBIGUOUS',
        message: `The previous answer listed ${choices.values.length} ${humanizePriorMemberDimension(choices.dimension)}. Which one did you mean?`,
        options,
      };
    }
    return;
  }
  const values = [...new Set(rawBinding.values
    .map((value) => value.trim())
    .filter(Boolean))].slice(0, 24);
  if (values.length === 0) return;
  // The resolver intentionally uses business entities (`customer`) for
  // deictic language. Recover the persisted display field (`customer_name`)
  // when available so the compiler binds an actual qualified dimension rather
  // than reinterpreting an entity noun as a new broad grouping.
  // Prior values are now keyed by BOTH the display column and the business
  // entity, so a plain scan can return the entity noun ("customer") when the
  // real column ("customer_name") is sitting right beside it. Prefer a key the
  // result actually had — binding to the noun makes the compiler reinterpret it
  // as a new broad grouping.
  const displayCandidates = Object.entries(followUp.priorResultValues ?? {})
    .filter(([, candidateValues]) => values.every((value) => candidateValues.includes(value)))
    .map(([key]) => key);
  const priorColumns = new Set(followUp.priorResultColumns ?? []);
  const displayDimension = displayCandidates.find((key) => priorColumns.has(key))
    ?? displayCandidates[0]
    ?? rawBinding.dimension;
  if (!displayDimension) return;

  const priorResultMemberBinding = {
    version: 1 as const,
    displayDimension,
    values,
    ...(rawBinding.sourceTurnId ? { sourceTurnId: rawBinding.sourceTurnId } : {}),
  };
  request.priorResultMemberBinding = priorResultMemberBinding;
  const seed = request.hostRequirementSeed?.version === 1
    && request.hostRequirementSeed.sourceQuestion === request.question
    ? request.hostRequirementSeed
    : buildAnalyticalRequirementSeedV1({ question: request.question });
  request.hostRequirementSeed = {
    ...seedWithPriorResultMemberBinding(seed, priorResultMemberBinding),
    sourceQuestion: request.question,
  };
}

/**
 * Plural, human label for the dimension an ambiguous reference could bind to.
 * The dimension may be a business entity ("customer") or, when the prior
 * answer displayed a bare name column, that column ("name") — both read
 * correctly pluralized.
 */
function humanizePriorMemberDimension(dimension: string): string {
  const leaf = dimension.split(/[.:]/).pop() ?? dimension;
  const words = leaf.replace(/[_-]+/g, ' ').trim().toLowerCase();
  const last = words.split(' ').filter(Boolean).pop() ?? words;
  return last.endsWith('s') ? last : `${last}s`;
}

/** Best-effort: persist a completed run as a conversation turn (never throws). */
function recordConversationTurn(store: ConversationStore | null, threadId: string | undefined, run: AgentRun): void {
  if (!store || !threadId) return;
  try {
    if (!store.getThread(threadId)) {
      // Open the named thread rather than discarding the turn. `dql agent ask
      // --thread <id>` documents itself as continuing a conversation, but the
      // CLI never created the thread and this guard then dropped every turn —
      // so a follow-up reached the analyst with no prior plan, no prior
      // measures, and no binding, and answered a different question.
      store.createThread({ id: threadId, surface: 'cli' });
      if (!store.getThread(threadId)) return;
    }
    const turn = store.appendTurn(threadId, conversationTurnInputFromRun(run));
    // Fold the turn into the thread's working state + rolling summary — but
    // ONLY for turns that produced a real answer. A failed/blocked/no-answer
    // turn folding its (possibly misparsed) filters and measures into working
    // state poisoned every subsequent ask: the SAME question that worked once
    // then failed forever because the bad turn's phantom state carried forward.
    //
    // The previous guard tested `run.status`, which cannot express this: a
    // grounding-gap refusal and a perfectly good uncertified answer are BOTH
    // `needs_review`, so the guard admitted exactly the failures its comment
    // was written to exclude. Trust is now derived from answer state.
    if (isTrustedConversationTurn(turn)) advanceThreadState(store, threadId, turn);
  } catch {
    // Conversation persistence is additive; a failed write must not fail the run.
  }
}

/**
 * Presentation projection of a run, for anything that SHIPS it — thread history
 * and the live SSE stream alike.
 *
 * A stored run is dominated by DUPLICATED diagnostics rather than content. On a
 * real 2.4 MB run: `diagnosticReceipt` is held twice — once top-level and once
 * inside `artifacts[0].payload`, byte-identical — and each copy embeds its own
 * full `steps` and `artifacts`, which embed the payload again. The part the UI
 * actually renders (`payload.result`) was 3 KB.
 *
 * Everything the thread view reads is preserved, including
 * `diagnosticReceipt.failure.message`; only the self-referential nesting and the
 * unread `considered` block are dropped. The complete record stays available
 * from the existing `GET /api/agent-runs/:id` run-state route.
 */
export function slimAgentRunForTransport(run: AgentRun): AgentRun {
  const slimReceipt = (receipt: unknown): unknown => {
    const record = agentRunRecord(receipt);
    if (!record) return receipt;
    // `steps`/`artifacts` inside the receipt duplicate the run's own.
    const { steps: _steps, artifacts: _artifacts, ...rest } = record;
    return rest;
  };
  // The persisted run holds each receipt once, on the root. Readers of the
  // presentation projection (the notebook's inspector, the repair flow) look
  // for them on the answer artifact, so the projection places the root
  // receipts there — a view, never a second stored copy.
  const rootReceipts = {
    ...(run.diagnosticReceipt ? { diagnosticReceipt: slimReceipt(run.diagnosticReceipt) } : {}),
    ...(run.diagnosticReceiptV2 ? { diagnosticReceiptV2: run.diagnosticReceiptV2 } : {}),
    ...(run.diagnosticReceiptV3 ? { diagnosticReceiptV3: run.diagnosticReceiptV3 } : {}),
    ...(run.diagnosticReceiptV4 ? { diagnosticReceiptV4: run.diagnosticReceiptV4 } : {}),
    ...(run.diagnosticReceiptV5 ? { diagnosticReceiptV5: run.diagnosticReceiptV5 } : {}),
    ...(run.diagnosticReceiptV6 ? { diagnosticReceiptV6: run.diagnosticReceiptV6 } : {}),
    ...(run.diagnosticReceiptV8 ? { diagnosticReceiptV8: run.diagnosticReceiptV8 } : {}),
  };
  const receiptArtifactIndex = Math.max(0, (run.artifacts ?? []).findIndex((artifact) => artifact.kind === 'answer'));
  const artifacts = (run.artifacts ?? []).map((artifact, index) => {
    const payload = agentRunRecord(artifact.payload);
    const { considered: _considered, ...restPayload } = payload ?? {};
    if (!payload && index !== receiptArtifactIndex) return artifact;
    return {
      ...artifact,
      payload: {
        ...restPayload,
        ...(payload?.diagnosticReceipt ? { diagnosticReceipt: slimReceipt(payload.diagnosticReceipt) } : {}),
        ...(index === receiptArtifactIndex ? rootReceipts : {}),
      },
    };
  });
  // `steps[].artifacts` is a THIRD copy of the run's own artifacts, and one
  // progress event carries a FOURTH as its payload. Both are dropped rather than
  // truncated: the data itself is unchanged and still on `run.artifacts`.
  const MAX_EVENT_PAYLOAD_BYTES = 8 * 1024;
  const steps = (run.steps ?? []).map((step) => {
    const record = agentRunRecord(step);
    if (!record?.artifacts) return step;
    const { artifacts: _stepArtifacts, ...rest } = record;
    return rest as unknown as typeof step;
  });
  const events = (run.events ?? []).slice(-20).map((event) => {
    const record = agentRunRecord(event);
    if (!record?.payload) return event;
    const encoded = JSON.stringify(record.payload) ?? '';
    if (encoded.length <= MAX_EVENT_PAYLOAD_BYTES) return event;
    return { ...record, payload: { omitted: 'oversized', bytes: encoded.length } } as unknown as typeof event;
  });
  return {
    ...run,
    artifacts,
    steps,
    events,
    ...(run.diagnosticReceipt
      ? { diagnosticReceipt: slimReceipt(run.diagnosticReceipt) as AgentRun['diagnosticReceipt'] }
      : {}),
  };
}

/**
 * INDEX projection for `GET /api/agent-runs` — strictly lighter than the
 * presentation projection above.
 *
 * A run history list renders one ROW per run: question, route, status, trust,
 * timing, summary. It never renders an answer body, an event stream, or a step
 * trace. Shipping those anyway dominated the response: on 300 real stored runs
 * a 20-run page was 47.61 MB whole and still 6.80 MB under the presentation
 * projection, of which 6.35 MB was `artifacts[].payload` alone.
 *
 * Artifact identity (`id`/`kind`/`title`/`trustState`) is kept so a row can say
 * what it produced; only the payload body is dropped. The complete immutable
 * record stays available from `GET /api/agent-runs/:id`.
 *
 * Acceptance: PERF-003, E2E-022.
 */
export function agentRunListEntryForTransport(run: AgentRun): AgentRun {
  const slim = slimAgentRunForTransport(run);
  const artifacts = (slim.artifacts ?? []).map((artifact) => {
    const record = agentRunRecord(artifact);
    if (!record) return artifact;
    const { payload: _payload, ...rest } = record;
    return rest as unknown as typeof artifact;
  });
  return { ...slim, artifacts, steps: [], events: [] };
}

export function conversationTurnInputFromRun(run: AgentRun): ConversationTurnInput {
  const artifact = run.artifacts.find((candidate) => candidate.kind === 'answer')
    ?? run.artifacts.find((candidate) => candidate.kind === 'research_run')
    ?? run.artifacts[0];
  const payload = agentRunRecord(artifact?.payload);
  // A blocked run may retain diagnostic artifacts, but their result-shaped
  // payload is never accepted conversation evidence or prose authority.
  const result = run.status === 'blocked' || run.status === 'cancelled'
    ? undefined
    : agentRunRecord(payload?.result);
  const columns = conversationResultColumns(result?.columns);
  // The visual preview stays tiny, but member resolution needs a wider bounded
  // value window. Deriving dimensions from only the eight preview rows caused a
  // valid row 9/10 member to disappear before the next turn (AGT-012/E2E-010).
  const memberRows = Array.isArray(result?.rows)
    ? result.rows.filter((row): row is Record<string, unknown> =>
        Boolean(row && typeof row === 'object' && !Array.isArray(row))).slice(0, 50)
    : [];
  // The full retained window feeds both member resolution and cross-result
  // follow-up compute ("of the results above, the average"). The store clamps
  // it (MAX_SAMPLE_ROWS); rows are never dumped into the prompt.
  const rows = memberRows;
  const rowsSample = rows.map((row) => columns.map((column) => row[column]));
  const contextPack = agentRunRecord(payload?.contextPack);
  const questionPlan = agentRunRecord(contextPack?.questionPlan);
  const requestedShape = agentRunRecord(questionPlan?.requestedShape);
  // A structured clarification choice must survive reload/restart with the
  // exact option IDs and typed requirements that rendered it. This is stored
  // inside the existing JSON contract envelope so older conversation rows stay
  // readable; the router treats it as reject-only continuity evidence and
  // always rechecks the current snapshot before it can freeze a plan.
  // Most analytical clarifications retain the router-owned cascade requirement
  // set. Evidence-only ambiguity deliberately has no frozen cascade, however,
  // and its first rendered options still need a typed, reload-safe contract.
  // Derive that narrow fallback from the immutable original question and the
  // already-resolved intent—not from a later click or client context—so the
  // first valid structured selection can be revalidated without weakening the
  // server-issued-envelope requirement.
  const clarificationRequirements = run.diagnosticReceiptV3?.cascade?.requirements
    ?? run.routeDecision?.analyticalCascadeDecision?.requirements
    ?? (run.status === 'needs_clarification' && (run.clarificationOptions?.length ?? 0) > 0
      ? buildAnalyticalRequirementSet({
          question: run.question,
          parsedIntent: run.routeDecision?.meaningResolution?.queryIntent,
        })
      : undefined);
  const clarificationSelection = run.status === 'needs_clarification'
    && (run.clarificationOptions?.length ?? 0) > 0
    ? {
        version: 1 as const,
        optionIds: [...new Set(run.clarificationOptions!.map((option) => option.id).filter(Boolean))].slice(0, 16),
        ambiguityCandidateIds: [...new Set(run.clarificationOptions!.map((option) => option.id).filter(Boolean))].slice(0, 16),
        ...(clarificationRequirements
          ? { requirements: clarificationRequirements }
          : {}),
        ...(run.routeDecision?.retrievalEvidence?.snapshotId
          ? { snapshotId: run.routeDecision.retrievalEvidence.snapshotId }
          : {}),
        ...(run.routeDecision?.retrievalEvidence?.continuityFingerprint
          ? { continuityFingerprint: run.routeDecision.retrievalEvidence.continuityFingerprint }
          : {}),
      }
    : undefined;
  const rowCountRaw = result?.rowCount;
  const measureColumns = conversationMeasureColumns(columns, requestedShape, rows);
  const dimensionValues = conversationDimensionValues(columns, memberRows);
  const resultFingerprint = conversationResultFingerprint(result, payload);
  const memberSets = conversationResultMemberSets(columns, memberRows, resultFingerprint);
  return {
    agentRunId: run.id,
    question: run.question,
    answerSummary: run.answer ?? run.summary,
    answerText: run.answer,
    route: run.route,
    // A route/context label is presentation metadata, not the terminal trust
    // authority. In particular, a certified run can retain a `mixed` context
    // label from candidates considered before the certified tuple froze. Using
    // that label here made the persisted conversation contradict the immutable
    // run. Persist the canonical run state unless the answer itself has
    // multiple materially different answer sections.
    trustLabel: conversationTrustLabelFromRun(run, payload),
    runStatus: run.status,
    stopReason: run.stopReason,
    // Persisted so a later turn can tell a refusal from an answer. `runStatus`
    // alone cannot: a grounding gap and a good uncertified answer are both
    // `needs_review`.
    refusalCode: agentRunString(payload?.refusalCode),
    executionError: agentRunString(payload?.executionError),
    certification: agentRunString(payload?.certification),
    sourceCertifiedBlock: agentRunString(payload?.sourceCertifiedBlock)
      ?? (artifact?.kind === 'answer' ? agentRunString(artifact.ref) : undefined),
    contextPackId: agentRunString(payload?.contextPackId) ?? agentRunString(contextPack?.id),
    knowledgeLens: agentRunRecord(contextPack?.knowledgeLens) as ConversationTurnInput['knowledgeLens'],
    sql: agentRunString(payload?.proposedSql) ?? agentRunString(payload?.sql),
    dqlArtifact: agentRunRecord(payload?.dqlArtifact) as ConversationTurnInput['dqlArtifact'],
    cascade: agentRunRecord(payload?.cascade) as CascadeAnswerResult | undefined,
    narrationIntegrityReceipt: run.narrationIntegrityReceipt,
    result: columns.length > 0 || rows.length > 0
      ? {
          columns,
          rowsSample,
          ...(Array.isArray(result?.columnsMeta) ? { columnsMeta: result.columnsMeta.filter((meta): meta is { name: string; kind: string } => Boolean(meta && typeof meta === 'object' && typeof (meta as { name?: unknown }).name === 'string' && typeof (meta as { kind?: unknown }).kind === 'string')) } : {}),
          dimensionValues,
          ...(memberSets?.length ? { memberSets } : {}),
          ...(resultFingerprint ? { resultFingerprint } : {}),
          measureColumns,
          rowCount: typeof rowCountRaw === 'number' ? rowCountRaw : rows.length || undefined,
        }
      : undefined,
    contract: {
      ...(requestedShape ?? {}),
      ...(clarificationSelection ? { clarificationSelection } : {}),
      // The pipeline's executed intent: the next turn edits THIS, not prose.
      ...(payload?.askIntentV1 && typeof payload.askIntentV1 === 'object' ? { askIntentV1: payload.askIntentV1 } : {}),
    },
  };
}

function conversationTrustLabelFromRun(
  run: Pick<AgentRun, 'trustState' | 'artifacts'>,
  payload: Record<string, unknown> | undefined,
): string | undefined {
  if (!isCanonicalConversationTrustState(run.trustState)) {
    return agentRunString(payload?.trustLabel);
  }
  return hasMixedAnswerSectionTrust(run.artifacts) ? 'mixed' : run.trustState;
}

function isCanonicalConversationTrustState(value: unknown): value is AgentRunTrustState {
  return value === 'certified'
    || value === 'governed'
    || value === 'grounded'
    || value === 'review_required'
    || value === 'blocked'
    || value === 'not_applicable';
}

/**
 * `mixed` is meaningful only when the durable answer contains sections with
 * materially different trust states. Supporting artifacts such as a DQL draft
 * or a diagnostics receipt do not turn one certified answer into mixed trust.
 */
function hasMixedAnswerSectionTrust(artifacts: readonly AgentRun['artifacts'][number][]): boolean {
  const states = new Set(artifacts
    .filter((artifact) => artifact.kind === 'answer' || artifact.kind === 'research_run')
    .map((artifact) => artifact.trustState)
    .filter((state) => state === 'certified'
      || state === 'governed'
      || state === 'grounded'
      || state === 'review_required'));
  return states.size > 1;
}

function conversationResultColumns(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value
    .map((column) => typeof column === 'string'
      ? column
      : agentRunString((column as { name?: unknown })?.name) ?? '')
    .filter(Boolean)
    .slice(0, 24);
}

function conversationMeasureColumns(
  columns: string[],
  requestedShape: Record<string, unknown> | undefined,
  rows: Array<Record<string, unknown>>,
): string[] | undefined {
  // A requested phrase is not evidence that the execution returned that
  // measure.  In particular, an incomplete certified block used to persist
  // `revenue` beside its actual `lifetime_spend` output merely because the
  // request said revenue.  Retain an exact requested column only when it is
  // actually present in the result contract.
  const requested = conversationStringArray(requestedShape?.measures) ?? [];
  const canonical = (value: string) => value.toLowerCase()
    .replace(/[_./:-]+/g, ' ')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const actualRequestedColumns = columns.filter((column) => {
    const identity = canonical(column);
    return identity.length > 0 && requested.some((measure) => canonical(measure) === identity);
  });
  const numericColumns = columns.filter((column) =>
    rows.some((row) => typeof row[column] === 'number' && Number.isFinite(row[column] as number))
  );
  const metricNamedColumns = columns.filter((column) =>
    /\b(revenue|sales|amount|total|count|average|avg|sum|spend|cost|margin|profit|value|points?|score|quantity|units?|rate|volume)\b/i.test(
      column.replace(/_/g, ' '),
    )
  );
  const unique = Array.from(new Set([...actualRequestedColumns, ...numericColumns, ...metricNamedColumns]
    .map((value) => value.trim())
    .filter(Boolean)));
  return unique.length > 0 ? unique.slice(0, 24) : undefined;
}

/** Distinct string values per low-cardinality column — the deictic-resolution fuel. */
function conversationDimensionValues(
  columns: string[],
  rows: Array<Record<string, unknown>>,
): Record<string, string[]> | undefined {
  if (columns.length === 0 || rows.length === 0) return undefined;
  const out: Record<string, string[]> = {};
  for (const column of columns.slice(0, 8)) {
    const values = Array.from(new Set(
      rows.map((row) => row[column]).filter((value): value is string => typeof value === 'string' && value.trim().length > 0),
    )).slice(0, 24);
    if (values.length > 0 && values.length <= 24) out[column] = values;
  }
  return Object.keys(out).length > 0 ? out : undefined;
}

/**
 * Project only bounded entity identity/display sets from an executed result.
 * They are persisted locally for deterministic continuation binding, never
 * emitted into the content-free Ask trace or portable diagnostics.
 */
function conversationResultMemberSets(
  columns: string[],
  rows: Array<Record<string, unknown>>,
  resultFingerprint: string | undefined,
): ConversationResultMemberSetV1[] | undefined {
  if (columns.length === 0 || rows.length === 0) return undefined;
  const entityForColumn = (column: string): ConversationResultMemberSetV1['entity'] | undefined => {
    const lower = column.toLowerCase();
    if (/\bcustomer\b/.test(lower.replace(/[_./:-]+/g, ' '))) return 'customer';
    if (/\baccount\b/.test(lower.replace(/[_./:-]+/g, ' '))) return 'account';
    if (/\bproduct\b/.test(lower.replace(/[_./:-]+/g, ' '))) return 'product';
    if (/\buser\b/.test(lower.replace(/[_./:-]+/g, ' '))) return 'user';
    return undefined;
  };
  const valuesFor = (column: string): string[] => Array.from(new Set(rows
    .map((row) => row[column])
    .filter((value): value is string | number => (typeof value === 'string' && value.trim().length > 0)
      || (typeof value === 'number' && Number.isFinite(value)))
    .map((value) => String(value).trim())))
    .filter(Boolean)
    .slice(0, 24);
  const sets: ConversationResultMemberSetV1[] = [];
  for (const column of columns.slice(0, 24)) {
    const entity = entityForColumn(column);
    // A display label is the only safe deictic binding surface. Numeric IDs
    // become an optional companion key, never the fallback display value.
    if (!entity || /(?:^|_)(?:id|key)(?:$|_)/i.test(column)) continue;
    const displayValues = valuesFor(column);
    if (displayValues.length === 0) continue;
    const keyColumn = columns.find((candidate) => {
      const lower = candidate.toLowerCase();
      return entityForColumn(candidate) === entity && /(?:^|_)(?:id|key)(?:$|_)/i.test(lower);
    });
    const keyValues = keyColumn ? valuesFor(keyColumn) : undefined;
    sets.push({
      version: 1,
      entity,
      displayColumn: column,
      displayValues,
      ...(keyColumn && keyValues?.length ? { keyColumn, keyValues } : {}),
      ...(resultFingerprint ? { resultFingerprint } : {}),
    });
  }
  return sets.length > 0 ? sets.slice(0, 4) : undefined;
}

function conversationResultFingerprint(
  result: Record<string, unknown> | undefined,
  payload: Record<string, unknown> | undefined,
): string | undefined {
  const executionReceipt = agentRunRecord(result?.executionReceipt);
  const businessAnswer = agentRunRecord(payload?.businessAnswer);
  const candidates = [
    agentRunString(result?.resultFingerprint),
    agentRunString(executionReceipt?.resultFingerprint),
    agentRunString(businessAnswer?.resultFingerprint),
  ];
  return candidates.find((value): value is string => Boolean(value && /^[a-f0-9]{64}$/i.test(value)))?.toLowerCase();
}

function conversationStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const values = value.filter((item): item is string => typeof item === 'string' && item.trim().length > 0);
  return values.length > 0 ? values : undefined;
}

function isLoopbackOrigin(value: string): boolean {
  try {
    const hostname = new URL(value).hostname;
    return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '::1' || hostname === '[::1]';
  } catch {
    return false;
  }
}

function compactConversationRecord(record: Record<string, unknown>): Record<string, unknown> | undefined {
  const entries = Object.entries(record).filter(([, value]) => value !== undefined && value !== null);
  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

function apiRequestId(scope: string): string {
  return `${scope}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/** UI-007 / E2E-005: report the installed CLI version that owns this runtime. */
export function readDqlRuntimeVersion(runtimeUrl = import.meta.url): string {
  const runtimeDir = dirname(fileURLToPath(runtimeUrl));
  for (const packagePath of [join(runtimeDir, 'package.json'), join(runtimeDir, '../package.json')]) {
    try {
      const parsed = JSON.parse(readFileSync(packagePath, 'utf-8')) as { version?: unknown };
      if (typeof parsed.version === 'string' && parsed.version.trim()) return parsed.version.trim();
    } catch {
      // Source and published layouts place package.json at different levels.
    }
  }
  return 'unknown';
}

function apiErrorEnvelope(input: {
  requestId: string;
  code: string;
  message: string;
  snapshotId?: string;
  recoverable?: boolean;
  details?: unknown;
  nextActions?: string[];
}) {
  return {
    requestId: input.requestId,
    ...(input.snapshotId ? { snapshotId: input.snapshotId } : {}),
    code: input.code,
    message: input.message,
    // Retain the legacy field during the compatibility window.
    error: input.message,
    recoverable: input.recoverable ?? input.code !== 'DOMAIN_COLLISION',
    ...(input.details !== undefined ? { details: input.details } : {}),
    ...(input.nextActions?.length ? { nextActions: input.nextActions } : {}),
  };
}

function apiErrorCode(error: unknown, fallback: string): string {
  return typeof error === 'object' && error && 'code' in error
    ? String((error as { code?: unknown }).code)
    : fallback;
}

function apiErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * Slowest provider dispatch we assume before any have been observed, and the
 * settle time reserved after the last one. A subscription-CLI provider costs
 * roughly 10-15s per call, so these keep the first admission decision honest.
 */
const ASSUMED_PROVIDER_DISPATCH_MS = 12_000;
const DISPATCH_SETTLE_MARGIN_MS = 4_000;

/** Server-owned cap for physical provider sends in one Ask run. */
export interface AgentRunProviderDispatchBudget {
  total: number;
  /** Legacy/no-evidence category calls have their own one-call allowance. */
  classification?: number;
  meaningResolution: number;
  /** Optional stricter cap for planning inside `generationGroup`. */
  planning?: number;
  /**
   * One verifier-directed, same-snapshot revision after a successfully
   * admitted initial analytical planner call.  This is deliberately separate
   * from the ordinary planning and SQL-generation limits: it cannot turn into
   * a second free-form plan or consume the SQL generation allowance.
   */
  planningRevision?: number;
  /** One root Research hypothesis plan; separate from child Simple-Ask plans. */
  researchHypothesisPlanning?: number;
  generationGroup: number;
  narration: number;
  repair: number;
  /** Authoritative Ask V2's first LLM-controlled tool turn. */
  agentControl?: number;
  /** Authoritative Ask V2 tool observations/follow-up turns after control. */
  toolFollowup?: number;
}

/**
 * The one runtime authority for provider-send caps.
 *
 * Research is limited to twelve physical sends total, one planner, and one
 * narrator. Ordinary generated lookup normally gets two sends across
 * candidate-ID meaning and planning/generation. A router-frozen bounded
 * exploratory plan may use one additional, same-plan provider correction only
 * after the generation response declines SQL. That third send is a `repair`,
 * not an LLM replan: it retains the frozen snapshot, target, closure, output
 * tuple, and route. Classification is a separate legacy/no-evidence phase,
 * but still consumes the total cap and cannot coexist with candidate-ID
 * meaning resolution in the ledger.
 */
export function agentRunProviderDispatchBudgetForMode(
  requestedMode: AgentRunRequestedMode | undefined,
  options: { ordinaryAskNarration?: boolean } = {},
): AgentRunProviderDispatchBudget {
  if (requestedMode === 'research') {
    return {
      // An investigation reads the question once and may draft SQL for each
      // query it runs when the metric has no governed definition: the frame,
      // freshness, headline and coverage drafts, one dimension selection and
      // one consented narration all fit inside sixteen sends.
      total: 16,
      classification: 1,
      // A bounded Research root may plan up to six independently routed
      // hypothesis children. The root investigation plan has its own one-send
      // slot; each child then uses the same typed Simple Ask planner contract
      // as ordinary Ask. All of those physical sends still share the hard
      // twelve-send ledger below.
      meaningResolution: 6,
      researchHypothesisPlanning: 1,
      planning: 6,
      // A revision is verifier-directed and can only follow an admitted child
      // initial plan. The total cap remains the final authority, so these
      // limits do not grant more than twelve provider sends in a Research run.
      planningRevision: 5,
      // At most the remaining calls may be provider tools/generation. Together
      // with root/child planning, narration and repair, `total` remains the
      // hard ceiling.
      generationGroup: 13,
      narration: 1,
      repair: 1,
      // Each pipeline reading is one interpreter read; every drafted statement
      // is a follow-up. These share the sixteen-send ceiling with narration.
      agentControl: 6,
      toolFollowup: 12,
    };
  }
  return {
    // Legacy V1 keeps its existing phase limits.  Authoritative Ask V2 uses
    // the additive agent-control/tool-followup phases below: one initial
    // control turn plus bounded discovery/execution follow-ups and one
    // post-result narration control.
    //
    // The follow-up allowance was four, which on a cold large repo is spent
    // ENTIRELY on the discovery ladder (two tier inspections + two tier
    // attempts) — the taught refusals then hand the model the admitted
    // identifiers with no send remaining to use them, and every such turn
    // died at "orchestration budget" having done everything right. Nine
    // follow-ups affords the full ladder plus one corrected retry per
    // executable tier; the run deadline and per-phase caps still bound cost.
    total: 12,
    classification: 1,
    meaningResolution: 1,
    planning: 1,
    planningRevision: 1,
    generationGroup: 1,
    // An authoritative V2 turn already labels its final `finish_answer`
    // control as narration, so the single slot is spent before a post-run
    // narrator can send anything: enabling narration without this produced
    // "budget exhausted after 1 physical attempts" every time. The second slot
    // exists only while the setting asks for it, and `total` still bounds the
    // run.
    narration: options.ordinaryAskNarration ? 2 : 1,
    repair: 1,
    agentControl: 1,
    toolFollowup: 9,
  };
}

export class RunScopedProviderDispatchEvidence implements ProviderDispatchEvidenceSink {
  private readonly receipts: ProviderEgressReceiptV1[] = [];
  private readonly phaseCounts = new Map<ProviderDispatchPhaseV1, number>();
  /** Planning revisions have their own verifier-owned admission slot. */
  private planningInitialCount = 0;
  private planningRevisionCount = 0;
  /** The one root Research hypothesis-plan transport. */
  private researchHypothesisPlanningCount = 0;
  /** At most one physical same-provider transient retry may be admitted per run. */
  private retryCount = 0;
  private currentRoute: AgentRunRoute;
  /** Wall-clock start of the previous dispatch, used to learn this provider's cost. */
  private lastDispatchStartedAtMs?: number;
  private readonly observedDispatchDurations: number[] = [];

  /**
   * How long the NEXT dispatch is likely to take, learned from this run.
   *
   * Counting dispatches is not a time budget. A provider costing ~13s a call
   * will burn a 45s deadline in three calls and get killed mid-flight, so the
   * run ends with nothing — strictly worse than stopping early and answering
   * from what it already has.
   */
  private expectedDispatchMs(): number {
    return predictDispatchMs(this.observedDispatchDurations);
  }

  /**
   * The run budget's own clock when there is one, so dispatch cost is measured
   * against the same timeline the deadline is enforced on (and stays injectable
   * for deterministic tests).
   */
  private nowMs(): number {
    return this.runBudget ? this.runBudget.elapsedMs() : Date.now();
  }

  private recordDispatchStart(): void {
    const now = this.nowMs();
    if (this.lastDispatchStartedAtMs !== undefined) {
      this.observedDispatchDurations.push(Math.max(0, now - this.lastDispatchStartedAtMs));
    }
    this.lastDispatchStartedAtMs = now;
  }

  constructor(private readonly policy: AgentRunProviderDispatchBudget, private readonly runBudget?: AgentRunBudget,
    private readonly rowEgress: ProviderResultRowEgressPolicy = ZERO_ROW_EGRESS_POLICY,
  ) {
    this.currentRoute = runBudget?.mode === 'research' ? 'research' : 'generated_answer';
  }

  setRoute(route: AgentRunRoute | undefined): void {
    if (route) this.currentRoute = route;
  }

  mayStartToolCall(): boolean {
    return !this.runBudget || this.runBudget.mayStartDiscovery(this.currentRoute);
  }

  remainingDispatches(): number {
    return Math.max(0, this.policy.total - this.receipts.length);
  }

  observe(
    event: ProviderDispatchEvent,
    context: {
      purpose: ProviderEgressPurpose;
      dispatchPhase: ProviderDispatchPhaseV1;
      optIn: boolean;
      serializedResultShape?: { resultRowCount: number; columnCount: number };
      cumulativeResultRowCount?: number;
      retryOfAttemptIndex?: number;
      /** Server-owned subtype for root Research or the Ask planner. */
      planningKind?: 'initial' | 'targeted_revision' | 'research_hypothesis';
      /**
       * A caller's own bound on how long this call takes. Drafting one SQL
       * statement takes seconds even when reading the question took a minute;
       * judging it by the slowest reading turned a fast draft away.
       */
      expectedMs?: number;
    },
  ): Record<string, unknown> {
    const isInterpretationPhase = context.dispatchPhase === 'classification'
      || context.dispatchPhase === 'meaning_resolution';
    // Classification is a genuine short discovery/clarify preflight. Meaning
    // resolution belongs to the Ask program and must use the selected route's
    // regular analytical budget; charging it to clarify caused valid semantic
    // and exploratory fallbacks to die before their first compiler attempt.
    const softRoute = context.dispatchPhase === 'classification' ? 'clarify' : this.currentRoute;
    // Admission control BEFORE the phase targets: starting a call that the hard
    // deadline will kill mid-flight wastes the remaining budget and ends the run
    // with nothing. Stopping here lets the caller answer from what it has.
    // Narration is exempt: it is the step that produces the answer, and it is
    // separately bounded by its own soft target below.
    const expectedMs = context.expectedMs !== undefined ? Math.min(context.expectedMs, this.expectedDispatchMs()) : this.expectedDispatchMs();
    if (context.dispatchPhase !== 'narration' && this.runBudget && this.runBudget.remainingMs() < expectedMs + DISPATCH_SETTLE_MARGIN_MS) {
      throw Object.assign(new Error(
        `Only ${Math.round((this.runBudget?.remainingMs() ?? 0) / 1_000)}s of the run deadline remain, which is not enough for another ~${Math.round(expectedMs / 1_000)}s provider call. Answering from what has already been gathered.`,
      ), { code: 'RUN_DEADLINE_INSUFFICIENT' });
    }
    if (context.dispatchPhase === 'narration') {
      if (this.runBudget && !this.runBudget.mayStartNarration()) {
        throw Object.assign(new Error(
          `The ${Math.round(this.runBudget.narrationSoftTargetMs() / 1_000)}-second narration target elapsed before the answer could be written.`,
        ), { code: 'RUN_SOFT_TARGET_EXCEEDED' });
      }
    } else if (this.runBudget && !this.runBudget.mayStartDiscovery(softRoute)) {
      throw Object.assign(new Error(
        `The ${Math.round(this.runBudget.softTargetMs(softRoute) / 1_000)}-second soft target elapsed before this provider dispatch could start.`,
      ), { code: 'RUN_SOFT_TARGET_EXCEEDED' });
    }
    if (this.receipts.length >= this.policy.total) {
      throw Object.assign(new Error(
        `Run-wide provider dispatch budget exhausted after ${this.policy.total} physical attempts.`,
      ), { code: 'PROVIDER_DISPATCH_BUDGET_EXHAUSTED' });
    }
    const retryOfAttemptIndex = context.retryOfAttemptIndex;
    const retryRequested = retryOfAttemptIndex !== undefined;
    const retryParent = retryRequested
      ? this.receipts.find((receipt) => (
        receipt.provider === event.provider
        && receipt.dispatchPhase === context.dispatchPhase
        && receipt.purpose === context.purpose
        && receipt.attemptIndex === retryOfAttemptIndex
      ))
      : undefined;
    // A retry is transport recovery, not another generation, repair, or route
    // decision. It must be tied to the same admitted physical provider phase,
    // and the frozen exploratory repair lane is deliberately excluded so its
    // one reserved repair transport cannot be spent by a network retry.
    if (retryRequested && (
      !Number.isInteger(retryOfAttemptIndex)
      || retryOfAttemptIndex < 1
      || !retryParent
      || this.retryCount >= 1
      || context.dispatchPhase === 'repair'
    )) {
      throw Object.assign(new Error(
        'A provider retry must be the one permitted same-provider retry of an admitted non-repair physical attempt.',
      ), { code: 'PROVIDER_DISPATCH_RETRY_NOT_ALLOWED' });
    }
    const admittedTransientRetry = retryRequested && Boolean(retryParent);
    const phaseCount = this.phaseCounts.get(context.dispatchPhase) ?? 0;
    const planningKind = context.dispatchPhase === 'planning'
      ? (context.planningKind ?? 'initial')
      : undefined;
    const phaseLimit = context.dispatchPhase === 'classification'
      ? (this.policy.classification ?? 1)
      : context.dispatchPhase === 'meaning_resolution'
        ? this.policy.meaningResolution
      : context.dispatchPhase === 'planning'
      ? planningKind === 'targeted_revision'
          ? (this.policy.planningRevision ?? 0)
          : planningKind === 'research_hypothesis'
            ? (this.policy.researchHypothesisPlanning ?? 0)
            : (this.policy.planning ?? this.policy.generationGroup)
      : context.dispatchPhase === 'repair'
        ? this.policy.repair
        : context.dispatchPhase === 'narration'
          ? this.policy.narration
          : context.dispatchPhase === 'agent_control'
            ? (this.policy.agentControl ?? 0)
            : context.dispatchPhase === 'tool_followup'
              ? (this.policy.toolFollowup ?? 0)
          : this.policy.generationGroup;
    // Category-only classification is a legacy/no-evidence fallback, not an
    // alternate route into analytical binding. A run must record one or the
    // other: allowing both would turn an opaque category prompt into a false
    // claim that candidate IDs were resolved.
    const conflictingInterpretationPhase = isInterpretationPhase
      && this.receipts.some((receipt) => (
        receipt.dispatchPhase === 'classification'
        || receipt.dispatchPhase === 'meaning_resolution'
      ) && receipt.dispatchPhase !== context.dispatchPhase);
    if (conflictingInterpretationPhase) {
      throw Object.assign(new Error(
        'The legacy category classifier and candidate-ID meaning resolution cannot both dispatch in one Ask run.',
      ), { code: 'PROVIDER_INTERPRETATION_PHASE_CONFLICT' });
    }
    // SQL generation owns a distinct one-send cap.  Planning is a structured
    // interpretation phase, and one verifier-directed same-snapshot revision
    // is separately admitted below.  Counting planning as SQL generation used
    // to block the accepted initial-planner -> targeted-context -> revision
    // flow before the revision reached provider egress.
    const generationGroupCount = this.receipts.filter((receipt) =>
      receipt.dispatchPhase === 'generation').length;
    const targetedRevisionBeforeInitial = planningKind === 'targeted_revision'
      && this.planningInitialCount < 1;
    const planningCount = planningKind === 'targeted_revision'
      ? this.planningRevisionCount
      : planningKind === 'research_hypothesis'
        ? this.researchHypothesisPlanningCount
        : planningKind === 'initial'
          ? this.planningInitialCount
          : phaseCount;
    if (!admittedTransientRetry && (
      targetedRevisionBeforeInitial
      || planningCount >= phaseLimit
      || (context.dispatchPhase === 'generation' && generationGroupCount >= this.policy.generationGroup)
    )) {
      throw Object.assign(new Error(
        targetedRevisionBeforeInitial
          ? 'A targeted planning revision requires one admitted initial planner call.'
          : `Provider dispatch budget exhausted for ${planningKind === 'targeted_revision' ? 'targeted planning revision' : context.dispatchPhase} after ${phaseLimit} physical attempts.`,
        ), { code: 'PROVIDER_DISPATCH_BUDGET_EXHAUSTED' });
    }
    const envelope = prepareProviderWireEnvelopeForDispatch(event.provider, event.envelope);
    const projectedRowCount = context.serializedResultShape?.resultRowCount ?? 0;
    const projectedCumulativeRowCount = context.cumulativeResultRowCount ?? projectedRowCount;
    // The resolver is the single privacy authority. A legacy
    // `answer_narration` receipt can remain content-free for backwards
    // readability, but it can never disclose result rows. Research narration
    // requires both the explicit per-run consent and authority minted by that
    // resolver; a hand-built positive limit is not enough.
    const researchNarrationRowsAuthorized = context.purpose === 'research_narration'
      && context.optIn
      && this.rowEgress.resultRowAuthority === 'research_run_opt_in';
    const permittedRowLimit = researchNarrationRowsAuthorized
      ? this.rowEgress.maxNarrationRows
      : context.optIn && context.purpose === 'research_tool'
        ? this.rowEgress.maxToolRows
        : 0;
    if (projectedRowCount > permittedRowLimit || projectedCumulativeRowCount > permittedRowLimit) {
      throw Object.assign(new Error(
        permittedRowLimit === 0
          ? 'Provider egress blocked result rows without explicit Research run consent.'
          : `Provider egress blocked result rows beyond the cumulative Research limit of ${permittedRowLimit}.`,
      ), { code: permittedRowLimit === 0 ? 'PROVIDER_RESULT_ROWS_BLOCKED' : 'PROVIDER_RESULT_ROWS_LIMIT_EXCEEDED' });
    }
    assertProviderPayloadAllowed(envelope, {
      allowResultRows: false,
      maxResultRows: 0,
      purpose: context.purpose,
    });
    const rowCount = projectedRowCount;
    // A rejected admission is not a physical send.  Do not let a rejected
    // egress/budget guard teach the run budget that the provider was slow, or
    // consume a receipt/phase count that a later trace would present as a
    // completed attempt.
    this.recordDispatchStart();
    this.receipts.push(createProviderDispatchEgressReceipt({
      purpose: context.purpose,
      dispatchPhase: context.dispatchPhase,
      provider: event.provider,
      ...(event.model ? { model: event.model } : {}),
      operation: event.operation,
      attemptIndex: event.attemptIndex,
      ...(retryOfAttemptIndex !== undefined ? { retryOfAttemptIndex } : {}),
      options: event.options,
      permittedCategories: rowCount > 0
        ? ['instructions', 'question', 'schema_metadata', 'governed_context', 'result_rows']
        : ['instructions', 'question', 'schema_metadata', 'governed_context'],
      optIn: context.optIn && rowCount > 0,
      envelope,
      ...(context.serializedResultShape ? { serializedResultShape: context.serializedResultShape } : {}),
      ...(typeof context.cumulativeResultRowCount === 'number'
        ? { cumulativeResultRowCount: context.cumulativeResultRowCount }
        : {}),
    }));
    // Admission accounting belongs to this ledger only. The Ask provider
    // wrapper owns trace spans because it is the only boundary that observes
    // the matching HTTP completion/failure. Recording `ok` here would turn an
    // admitted-but-failed physical send into a false provider success.
    this.phaseCounts.set(context.dispatchPhase, phaseCount + 1);
    if (!admittedTransientRetry && planningKind === 'initial') this.planningInitialCount += 1;
    if (!admittedTransientRetry && planningKind === 'targeted_revision') this.planningRevisionCount += 1;
    if (!admittedTransientRetry && planningKind === 'research_hypothesis') this.researchHypothesisPlanningCount += 1;
    if (admittedTransientRetry) this.retryCount += 1;
    return envelope;
  }

  snapshot(fallbackReason = 'none'): ProviderDispatchTerminalEvidence {
    return {
      providerEgressReceipts: [...this.receipts],
      providerRoundTrips: this.receipts.length,
      // This request-local ledger observes the physical admission boundary.
      // Provider readiness/preflight checks intentionally do not create a
      // receipt, so a terminal merge must not resurrect them as round trips.
      authoritativeProviderRoundTrips: true,
      toolCalls: 0,
      sqlExecutions: 0,
      repairs: 0,
      fallbackReason,
    };
  }
}

const agentRunProviderEvidenceContext = new AsyncLocalStorage<RunScopedProviderDispatchEvidence>();
/**
 * Request-local trace context. It is intentionally independent of provider
 * accounting: tracing cannot admit a dispatch, consume a budget, or change a
 * connector call. Nested host callbacks can only append typed observations.
 */
const agentRunAskTraceContext = new AsyncLocalStorage<AskTraceObserverV1>();

function activeAskTraceObserver(): AskTraceObserverV1 | undefined {
  const observer = agentRunAskTraceContext.getStore();
  return observer?.enabled ? observer : undefined;
}

function runtimeTraceFingerprint(value: string): string {
  return `sha256:${createHash('sha256').update(value).digest('hex')}`;
}

function providerTracePhase(phase: ProviderDispatchPhaseV1): ProviderFailureDiagnosticV1['phase'] {
  switch (phase) {
    case 'classification': return 'classification';
    case 'meaning_resolution': return 'meaning_resolution';
    case 'planning': return 'planning';
    case 'generation': return 'generation';
    case 'repair': return 'repair';
    case 'narration': return 'narration';
    case 'agent_control': return 'agent_control';
    case 'tool_followup': return 'tool_followup';
    default: return 'unknown';
  }
}

/**
 * Attach one physical provider transport to the current redacted Ask trace.
 * The caller remains the authority for admission and egress; this wrapper only
 * records the same physical send/settlement with its server-owned phase and
 * purpose.  It is intentionally reusable for meaning and Research narration
 * so trace provider-attempt counts cannot drift from egress receipts.
 */
/**
 * @internal Exported solely for the local runtime boundary harness.  It is not
 * an HTTP or durable API: production callers use it to pair the one provider
 * transport with its same-run trace span and egress receipt.
 */
export function createProviderDispatchTrace(input: {
  observer?: AskTraceObserverV1;
  phase: ProviderDispatchPhaseV1;
  purpose: ProviderEgressPurpose;
  admit: (event: ProviderDispatchEvent) => Record<string, unknown>;
}): {
  options: {
    onProviderDispatch: (event: ProviderDispatchEvent) => Record<string, unknown>;
    onProviderDispatchComplete: (event: ProviderDispatchCompletionEvent) => void;
    onProviderDispatchRejected: (event: ProviderDispatchRejectionEvent) => void;
  };
  settle: (outcome: 'ok' | 'error' | 'cancelled', error?: unknown) => void;
} {
  const observer = input.observer;
  type PendingAttempt = {
    spanId: string | undefined;
    provider: ProviderName;
    model?: string;
    attempt: ProviderDispatchEvent['attemptIndex'];
  };
  const pending = new Map<string, PendingAttempt[]>();
  // A transport failure is reported by `onProviderDispatchComplete` and removes
  // its pending entry before the outer promise rejects. Keep the number of
  // observed provider boundaries independent of `pending`: a completed
  // transport failure and a pre-send denial both already have a span, so
  // `settle(error)` must not manufacture a second synthetic attempt.
  let observedBoundaryCount = 0;
  const deniedKeys = new Set<string>();
  // Some provider adapters emit a rejection notification after reporting the
  // same HTTP failure through completion. Once admission succeeded, that
  // notification is not a second denied send; it is the same physical
  // attempted transport and must retain its admitted/error span only.
  const admittedKeys = new Set<string>();
  const key = (event: Pick<ProviderDispatchEvent, 'provider' | 'operation' | 'attemptIndex'>) =>
    `${event.provider}:${event.operation}:${event.attemptIndex}`;
  const diagnostic = (event: Pick<ProviderDispatchEvent, 'provider' | 'model'> | undefined, error: unknown) =>
    classifyProviderFailure({
      message: error instanceof Error ? error.message : String(error ?? 'provider completion failed'),
      code: error && typeof error === 'object' ? String((error as { code?: unknown }).code ?? '') : undefined,
      phase: providerTracePhase(input.phase),
      ...(event?.provider ? { providerFingerprint: runtimeTraceFingerprint(event.provider) } : {}),
      ...(event?.model ? { modelFingerprint: runtimeTraceFingerprint(event.model) } : {}),
    });
  const start = (
    event: Pick<ProviderDispatchEvent, 'provider' | 'operation' | 'attemptIndex' | 'model'>,
    admission: 'admitted' | 'denied',
    failure?: unknown,
  ): PendingAttempt => {
    observedBoundaryCount += 1;
    const failureDiagnostic = failure === undefined ? undefined : diagnostic(event, failure);
    const attempt = {
      version: 1 as const,
      phase: providerTracePhase(input.phase),
      purpose: input.purpose,
      physicalAttemptIndex: event.attemptIndex,
      providerFingerprint: runtimeTraceFingerprint(event.provider),
      ...(event.model ? { modelFingerprint: runtimeTraceFingerprint(event.model) } : {}),
      readiness: admission === 'admitted' ? 'ready' as const : 'unknown' as const,
      admission,
      ...(failureDiagnostic?.httpStatusClass ? { httpStatusClass: failureDiagnostic.httpStatusClass } : {}),
      ...(failureDiagnostic?.retryable !== undefined ? { retryable: failureDiagnostic.retryable } : {}),
      ...(failureDiagnostic?.safeAction ? { safeAction: failureDiagnostic.safeAction } : {}),
      ...(failureDiagnostic?.cause ? { cause: failureDiagnostic.cause } : {}),
      provenance: 'live' as const,
    };
    const spanId = observer?.startSpan({
      name: 'provider.attempt',
      stage: 'provider',
      reasonCode: failureDiagnostic ? 'provider_failure' : 'started',
      payload: { kind: 'provider', attempt },
    });
    return { spanId, provider: event.provider, ...(event.model ? { model: event.model } : {}), attempt: event.attemptIndex };
  };
  const finish = (
    entry: PendingAttempt,
    outcome: 'ok' | 'error' | 'cancelled',
    error?: unknown,
    httpStatus?: number,
  ) => {
    if (!entry.spanId) return;
    if (outcome === 'ok') {
      observer?.finishSpan(entry.spanId, { outcome: 'ok', reasonCode: 'completed' });
      return;
    }
    const failureDiagnostic = diagnostic(
      { provider: entry.provider, ...(entry.model ? { model: entry.model } : {}) },
      error ?? (typeof httpStatus === 'number'
        ? Object.assign(new Error(`HTTP ${httpStatus}`), { code: `HTTP_${httpStatus}` })
        : undefined),
    );
    observer?.finishSpan(entry.spanId, {
      outcome: outcome === 'cancelled' ? 'cancelled' : 'error',
      reasonCode: outcome === 'cancelled' ? 'cancelled' : 'provider_failure',
      payload: {
        kind: 'provider',
        attempt: {
          version: 1,
          phase: providerTracePhase(input.phase),
          purpose: input.purpose,
          physicalAttemptIndex: entry.attempt,
          providerFingerprint: runtimeTraceFingerprint(entry.provider),
          ...(entry.model ? { modelFingerprint: runtimeTraceFingerprint(entry.model) } : {}),
          readiness: 'ready',
          admission: 'admitted',
          ...(failureDiagnostic.httpStatusClass ? { httpStatusClass: failureDiagnostic.httpStatusClass } : {}),
          retryable: failureDiagnostic.retryable,
          safeAction: failureDiagnostic.safeAction,
          cause: outcome === 'cancelled' ? 'cancelled' as const : failureDiagnostic.cause,
          provenance: 'live',
        },
      },
    });
  };
  const recordDenied = (
    event: Pick<ProviderDispatchEvent, 'provider' | 'operation' | 'attemptIndex' | 'model'>,
    error: unknown,
  ) => {
    const eventKey = key(event);
    // A provider adapter can notify a rejection after our host admission
    // already threw, or after reporting a completed physical HTTP failure.
    // The first case retains one denied span and no receipt; the second is
    // already represented by its admitted/error span and must not be doubled.
    if (admittedKeys.has(eventKey)) return;
    if (deniedKeys.has(eventKey)) return;
    deniedKeys.add(eventKey);
    const entry = start(event, 'denied', error);
    const failureDiagnostic = diagnostic(event, error);
    observer?.finishSpan(entry.spanId, {
      outcome: 'denied',
      reasonCode: 'provider_failure',
      payload: {
        kind: 'provider',
        attempt: {
          version: 1,
          phase: providerTracePhase(input.phase),
          purpose: input.purpose,
          physicalAttemptIndex: event.attemptIndex,
          providerFingerprint: runtimeTraceFingerprint(event.provider),
          ...(event.model ? { modelFingerprint: runtimeTraceFingerprint(event.model) } : {}),
          readiness: 'unknown',
          admission: 'denied',
          ...(failureDiagnostic.httpStatusClass ? { httpStatusClass: failureDiagnostic.httpStatusClass } : {}),
          retryable: failureDiagnostic.retryable,
          safeAction: failureDiagnostic.safeAction,
          cause: failureDiagnostic.cause,
          provenance: 'live',
        },
      },
    });
  };
  const options = {
    onProviderDispatch: (event: ProviderDispatchEvent): Record<string, unknown> => {
      // Admission is the physical-send boundary.  First let the ledger accept
      // and receipt the exact envelope; only then start an admitted trace
      // span. If it rejects, record a denied boundary with no pending entry,
      // receipt, or claim that bytes left the process.
      try {
        const envelope = input.admit(event);
        const entry = start(event, 'admitted');
        const eventKey = key(event);
        admittedKeys.add(eventKey);
        pending.set(eventKey, [...(pending.get(eventKey) ?? []), entry]);
        return envelope;
      } catch (error) {
        recordDenied(event, error);
        throw error;
      }
    },
    onProviderDispatchComplete: (event: ProviderDispatchCompletionEvent) => {
      // A transport/process success is not yet an accepted meaning result. The
      // provider promise settles after parsing; close the matching physical
      // span from `settle` so malformed output remains a visible failure.
      if (event.outcome === 'ok') return;
      const eventKey = key(event);
      const entries = pending.get(eventKey) ?? [];
      const entry = entries.shift();
      if (entries.length > 0) pending.set(eventKey, entries); else pending.delete(eventKey);
      if (entry) finish(
        entry,
        event.outcome === 'cancelled' ? 'cancelled' : 'error',
        event.error,
        event.httpStatus,
      );
    },
    onProviderDispatchRejected: (event: ProviderDispatchRejectionEvent) => {
      recordDenied(event, event.error);
    },
  };
  return {
    options,
    settle: (outcome, error) => {
      const entries = [...pending.values()].flat();
      pending.clear();
      for (const entry of entries) finish(entry, outcome, error);
      // A provider can fail before it reaches the dispatch observer (for
      // example subscription CLI readiness). Record that as one typed
      // provider boundary instead of allowing the root trace to fall back to
      // `unknown`.
      if (observedBoundaryCount === 0 && outcome !== 'ok' && observer?.enabled) {
        const failureDiagnostic = diagnostic(undefined, error);
        const span = observer.startSpan({
          name: 'provider.attempt',
          stage: 'provider',
          reasonCode: 'provider_failure',
          payload: {
            kind: 'provider',
            attempt: {
              version: 1,
              phase: providerTracePhase(input.phase),
              purpose: input.purpose,
              physicalAttemptIndex: 1,
              readiness: 'unknown',
              admission: 'unknown',
              retryable: failureDiagnostic.retryable,
              safeAction: failureDiagnostic.safeAction,
              cause: failureDiagnostic.cause,
              provenance: 'live',
            },
          },
        });
        observer.finishSpan(span, { outcome: outcome === 'cancelled' ? 'cancelled' : 'error', reasonCode: outcome === 'cancelled' ? 'cancelled' : 'provider_failure' });
      }
    },
  };
}

/**
 * Router interpretation happens before the answer runner's AsyncLocal trace
 * scope exists. Its request already carries the server-owned observer, so
 * adapt the physical category-classification or candidate-ID meaning call to
 * the shared physical-send trace wrapper without changing router authority.
 */
/**
 * @internal Host-owned physical dispatch bridge for Ask interpretation and
 * planning. Exported only for the local egress integration harness; the
 * runtime never receives a ledger or trace authority from client ingress.
 */
export function createRouterInterpretationProviderTrace(input: {
  request: AgentRunRequest;
  routerPhase: 'classification' | 'meaning_resolution' | 'planning';
  /** The only planning revision admission is minted by AskAnalystRuntime. */
  planningKind?: 'initial' | 'targeted_revision';
  /** Test/host injection only; production resolves the request-local ledger. */
  ledger?: ProviderDispatchEvidenceSink;
}): ReturnType<typeof createProviderDispatchTrace> {
  const purpose: ProviderEgressPurpose = input.routerPhase === 'classification'
    ? 'classification'
    : 'answer_generation';
  return createProviderDispatchTrace({
    observer: askTraceObserverForV1(input.request),
    phase: input.routerPhase,
    purpose,
    admit: (event) => {
      const ledger = input.ledger ?? agentRunProviderEvidenceContext.getStore();
      if (ledger) {
        return ledger.observe(event, {
          purpose,
          dispatchPhase: input.routerPhase,
          optIn: false,
          ...(input.routerPhase === 'planning' && input.planningKind
            ? { planningKind: input.planningKind }
            : {}),
        });
      }
      const envelope = prepareProviderWireEnvelopeForDispatch(event.provider, event.envelope);
      assertProviderPayloadAllowed(envelope, {
        allowResultRows: false,
        maxResultRows: 0,
        purpose,
      });
      return envelope;
    },
  });
}

/** @internal Exported for the Research-root terminal aggregation regression. */
export function mergeRunScopedProviderDispatchEvidence(
  run: AgentRun,
  evidence: ProviderDispatchTerminalEvidence,
): AgentRun {
  const providerEgressReceipts = [...evidence.providerEgressReceipts];
  const elapsed = Math.max(0, Date.parse(run.completedAt) - Date.parse(run.startedAt));
  // A Research root has no direct warehouse call of its own: its bounded
  // Simple-Ask children persist the execution receipts.  The executor adds
  // their content-safe aggregate to `run.telemetry`; this terminal merge must
  // retain it instead of overwriting it with the root provider-ledger's
  // intentionally zero SQL/tool counters. Provider receipts remain ledger
  // authoritative because all root and child sends share that one ledger.
  const inheritedTelemetry = run.telemetry;
  const telemetry: AgentRunTelemetryV1 = {
    version: 1,
    stageDurationsMs: {
      ...(inheritedTelemetry?.stageDurationsMs ?? {}),
      total: Number.isFinite(elapsed) ? Math.min(86_400_000, elapsed) : 0,
    },
    // A request-scoped ledger is the physical-send authority: provider round
    // trips must equal its receipt count, never the number of readiness or
    // preflight trace spans. Older/direct executor evidence can omit that
    // authority marker, in which case retain the existing telemetry fallback.
    providerRoundTrips: evidence.authoritativeProviderRoundTrips
      ? providerEgressReceipts.length
      : Math.max(evidence.providerRoundTrips, inheritedTelemetry?.providerRoundTrips ?? 0),
    toolCalls: Math.max(evidence.toolCalls, inheritedTelemetry?.toolCalls ?? 0),
    sqlExecutions: Math.max(evidence.sqlExecutions, inheritedTelemetry?.sqlExecutions ?? 0),
    repairs: Math.max(evidence.repairs, inheritedTelemetry?.repairs ?? 0),
    egressReceipts: providerEgressReceipts.length,
    ...(inheritedTelemetry?.warehouseDurationMs !== undefined
      ? { warehouseDurationMs: inheritedTelemetry.warehouseDurationMs }
      : {}),
    ...(inheritedTelemetry?.fallbackReason
      ? { fallbackReason: inheritedTelemetry.fallbackReason }
      : evidence.fallbackReason !== 'none'
        ? { fallbackReason: evidence.fallbackReason }
        : {}),
  };
  const diagnosticReceipt = run.diagnosticReceipt
    ? { ...run.diagnosticReceipt, providerEgressReceipts }
    : undefined;
  const diagnosticReceiptV2 = {
    version: 2 as const,
    runId: run.id,
    route: run.route,
    status: run.status,
    telemetry,
    providerEgressReceiptFingerprints: providerEgressReceipts.map((receipt) =>
      executionFingerprint(stableExecutionValue(receipt))),
    ...(run.diagnosticReceiptV2?.repairCapabilityFingerprint
      ? { repairCapabilityFingerprint: run.diagnosticReceiptV2.repairCapabilityFingerprint }
      : {}),
  };
  // An investigation carries its own receipt (V9 with `investigation`); only
  // the older hypothesis Research gets the synthesized V5/V6 root receipts.
  const legacyResearchReceipts = run.requestedMode === 'research' && !run.diagnosticReceiptV9?.investigation;
  const diagnosticReceiptV5 = legacyResearchReceipts
    ? run.diagnosticReceiptV5
      ? synchronizeResearchRuntimeReceiptV5(run.diagnosticReceiptV5, telemetry)
      : researchRootRuntimeReceiptV5(run, telemetry)
    : run.diagnosticReceiptV5;
  const diagnosticReceiptV6 = legacyResearchReceipts
    ? run.diagnosticReceiptV6
      ? synchronizeResearchRuntimeReceiptV6(run.diagnosticReceiptV6, telemetry, diagnosticReceiptV5)
      : researchRootRuntimeReceiptV6(run, telemetry, diagnosticReceiptV5)
    : run.diagnosticReceiptV6;
  const diagnosticReceiptV8: AgentRunDiagnosticReceiptV8 | undefined = run.diagnosticReceiptV8;
  // Receipts live on the run root only; the transport projection presents
  // them on the answer artifact for readers that expect them there.
  return {
    ...run,
    providerEgressReceipts,
    telemetry,
    ...(diagnosticReceipt ? { diagnosticReceipt } : {}),
    diagnosticReceiptV2,
    ...(diagnosticReceiptV5 ? { diagnosticReceiptV5 } : {}),
    ...(diagnosticReceiptV6 ? { diagnosticReceiptV6 } : {}),
    ...(diagnosticReceiptV8 ? { diagnosticReceiptV8 } : {}),
  };
}

function synchronizeResearchRuntimeReceiptV5(
  receipt: NonNullable<AgentRun['diagnosticReceiptV5']>,
  telemetry: AgentRunTelemetryV1,
): NonNullable<AgentRun['diagnosticReceiptV5']> {
  const { summaryFingerprint: _previousSummaryFingerprint, ...summaryWithoutFingerprint } = receipt.summary;
  const executionAttempts = Math.max(summaryWithoutFingerprint.executionAttempts, telemetry.sqlExecutions);
  const toolCallCount = Math.max(summaryWithoutFingerprint.toolCallCount, telemetry.toolCalls);
  const summaryInput = { ...summaryWithoutFingerprint, toolCallCount, executionAttempts };
  return {
    ...receipt,
    state: {
      ...receipt.state,
      counters: {
        ...receipt.state.counters,
        toolCalls: Math.max(receipt.state.counters.toolCalls, telemetry.toolCalls),
        executionAttempts: Math.max(receipt.state.counters.executionAttempts, telemetry.sqlExecutions),
        repairAttempts: Math.max(receipt.state.counters.repairAttempts, telemetry.repairs),
      },
    },
    summary: {
      ...summaryInput,
      summaryFingerprint: executionFingerprint(JSON.stringify(summaryInput)),
    },
  };
}

function synchronizeResearchRuntimeReceiptV6(
  receipt: NonNullable<AgentRun['diagnosticReceiptV6']>,
  telemetry: AgentRunTelemetryV1,
  receiptV5: AgentRun['diagnosticReceiptV5'],
): NonNullable<AgentRun['diagnosticReceiptV6']> {
  const executionAttempts = Math.max(receipt.execution.attempts, telemetry.sqlExecutions);
  return {
    ...receipt,
    ...(receiptV5 ? {
      state: receiptV5.state,
      summary: receiptV5.summary,
      ...(receiptV5.businessAnswer ? { businessAnswer: receiptV5.businessAnswer } : {}),
    } : {}),
    telemetry,
    execution: { attempts: executionAttempts },
    story: receipt.story.map((stage) => stage.stage === 'execution' && telemetry.sqlExecutions > 0
      ? { ...stage, status: 'completed' as const, reasonCode: 'research_child_sql_attempted' }
      : stage),
  };
}

/**
 * Explicit Research currently owns its root hypothesis plan separately from
 * the ordinary AskAnalyst state machine.  It can still produce several
 * independently frozen Simple-Ask children.  Build a deliberately
 * content-free V5/V6 root projection from those durable child receipts so the
 * trace does not claim that their SQL/tool work was zero or absent.
 *
 * This is an aggregation receipt, not a new execution authority: it names no
 * rows, SQL, candidate labels, or child prompt material, and the root ledger
 * remains the authority for provider egress receipts.
 */
function researchRootRuntimeReceiptV5(
  run: AgentRun,
  telemetry: AgentRunTelemetryV1,
): AgentRunDiagnosticReceiptV5 {
  const children = researchRootReceiptChildren(run);
  const observedChildFingerprints = children
    .flatMap((child) => child.resultFingerprint ? [child.resultFingerprint] : []);
  const trustedState = run.trustState === 'certified'
    ? 'certified'
    : run.trustState === 'review_required'
      ? 'review_required'
      : run.status === 'blocked'
        ? 'blocked'
        : run.trustState === 'not_applicable'
          ? 'not_applicable'
          : 'governed';
  const state = {
    version: 1 as const,
    mode: 'authoritative' as const,
    phase: run.status === 'blocked' || run.status === 'cancelled'
      ? 'blocked' as const
      : 'executed' as const,
    questionFingerprint: executionFingerprint(`research-root:${run.question}`),
    kind: 'research' as const,
    requirementCounts: { measures: 0, dimensions: 0, entityTerms: 0, members: 0, filters: 0 },
    mission: {
      mode: 'research' as const,
      taskCount: children.length,
      deferredTaskCount: 0,
      hypothesisCount: children.length,
    },
    workspace: {
      admittedCandidateCount: 0,
      excludedCandidateCount: 0,
      sourceCoverage: [],
      tools: [{
        id: 'tool:research_child_execution',
        kind: 'execute' as const,
        status: telemetry.sqlExecutions > 0 ? 'completed' as const : 'skipped' as const,
        reasonCode: telemetry.sqlExecutions > 0
          ? 'research_child_sql_attempted'
          : 'no_research_child_sql_attempt',
      }],
    },
    program: {
      id: `research-root:${executionFingerprint(run.id).slice(0, 24)}`,
      taskCount: children.length,
      candidateCount: 0,
      requiredRoles: [],
      outputAssertionCount: 0,
    },
    counters: {
      planningContinuations: 0,
      toolCalls: telemetry.toolCalls,
      executionAttempts: telemetry.sqlExecutions,
      repairAttempts: telemetry.repairs,
    },
  } satisfies AgentRunDiagnosticReceiptV5['state'];
  const nextAction = run.diagnosticReceiptV4?.summary.safeNextAction ?? 'none';
  const summaryInput = {
    version: 2 as const,
    runtimeMode: 'authoritative' as const,
    whatHappened: telemetry.sqlExecutions > 0
      ? 'Research aggregated child analytical SQL attempts.'
      : 'Research completed without a recorded child SQL attempt.',
    why: telemetry.sqlExecutions > 0
      ? 'Counts use server-owned child execution counters when present; canonical result fingerprints remain the separate fact boundary.'
      : 'No child recorded a physical SQL execution or durable execution receipt.',
    impact: telemetry.sqlExecutions > 0
      ? 'The root trace retains child physical execution attempts without copying result rows; only receipt-backed results are presented as facts.'
      : 'No child physical execution is presented as a root data answer.',
    nextAction,
    programTaskCount: children.length,
    admittedCandidateCount: 0,
    toolCallCount: telemetry.toolCalls,
    executionAttempts: telemetry.sqlExecutions,
  } satisfies Omit<AgentRunDiagnosticReceiptV5['summary'], 'summaryFingerprint'>;
  return {
    version: 5,
    runId: run.id,
    state,
    summary: {
      ...summaryInput,
      summaryFingerprint: executionFingerprint(JSON.stringify(summaryInput)),
    },
    ...(observedChildFingerprints.length > 0 ? {
      businessAnswer: {
        version: 1,
        mode: 'facts_only',
        trustState: trustedState,
        factIds: observedChildFingerprints.map((fingerprint) => `research-result:${fingerprint.slice(0, 24)}`),
        ...(observedChildFingerprints.length === 1 ? { resultFingerprint: observedChildFingerprints[0] } : {}),
        limitationCount: Math.max(0, children.length - observedChildFingerprints.length),
      },
    } : {}),
    finalStopReason: run.stopReason,
  };
}

function researchRootRuntimeReceiptV6(
  run: AgentRun,
  telemetry: AgentRunTelemetryV1,
  receiptV5: AgentRun['diagnosticReceiptV5'],
): AgentRunDiagnosticReceiptV6 | undefined {
  if (!receiptV5) return undefined;
  const executionObserved = telemetry.sqlExecutions > 0;
  const connectionAttempted = executionObserved;
  return {
    ...receiptV5,
    version: 6,
    roleCoverage: [],
    cascade: {
      attempts: [],
      planFrozen: executionObserved,
    },
    connection: { attempted: connectionAttempted },
    execution: { attempts: telemetry.sqlExecutions },
    telemetry,
    facts: {
      factCount: receiptV5.businessAnswer?.factIds.length ?? 0,
      ...(receiptV5.businessAnswer?.resultFingerprint
        ? { resultFingerprint: receiptV5.businessAnswer.resultFingerprint }
        : {}),
    },
    safeNextAction: receiptV5.summary.nextAction,
    story: [
      { stage: 'retrieval', status: 'skipped', reasonCode: 'research_root_uses_child_snapshots' },
      { stage: 'role_coverage', status: 'skipped', reasonCode: 'research_child_role_coverage_retained_per_branch' },
      { stage: 'planner', status: telemetry.providerRoundTrips > 0 ? 'completed' : 'skipped', reasonCode: telemetry.providerRoundTrips > 0 ? 'research_provider_activity_recorded' : 'no_research_provider_activity' },
      { stage: 'verification', status: executionObserved ? 'completed' : 'skipped', reasonCode: executionObserved ? 'research_child_physical_execution_recorded' : 'no_research_child_physical_execution' },
      { stage: 'targeted_recovery', status: 'skipped', reasonCode: 'not_applicable_to_research_root' },
      { stage: 'cascade', status: executionObserved ? 'completed' : 'skipped', reasonCode: executionObserved ? 'child_cascade_completed' : 'no_child_cascade_completed' },
      { stage: 'freeze', status: executionObserved ? 'completed' : 'skipped', reasonCode: executionObserved ? 'child_plan_frozen' : 'no_child_plan_frozen' },
      { stage: 'connection', status: connectionAttempted ? 'completed' : 'skipped', reasonCode: connectionAttempted ? 'child_connection_attempted' : 'connection_not_attempted' },
      { stage: 'execution', status: executionObserved ? 'completed' : 'skipped', reasonCode: executionObserved ? 'research_child_sql_attempted' : 'execution_not_attempted' },
      { stage: 'facts', status: (receiptV5.businessAnswer?.factIds.length ?? 0) > 0 ? 'completed' : 'skipped', reasonCode: (receiptV5.businessAnswer?.factIds.length ?? 0) > 0 ? 'receipt_backed_research_facts' : 'no_receipt_backed_research_facts' },
    ],
  };
}

function researchRootReceiptChildren(run: AgentRun): Array<{ id: string; resultFingerprint?: string }> {
  const artifact = run.artifacts.find((candidate) => candidate.kind === 'research_run');
  const payload = agentRunRecord(artifact?.payload);
  const runs = Array.isArray(payload?.researchRuns) ? payload.researchRuns : [];
  const seen = new Set<string>();
  return runs.flatMap((child, index) => {
    const record = agentRunRecord(child);
    const id = agentRunString(record?.id) ?? `research-child-${index + 1}`;
    if (seen.has(id)) return [];
    seen.add(id);
    const preview = agentRunRecord(record?.resultPreview);
    const receipt = normalizeAnalyticalExecutionReceipt(preview?.executionReceipt);
    const resultFingerprint = normalizeAnalyticalExecutionFingerprint(preview?.resultFingerprint)
      ?? receipt?.resultFingerprint;
    return [{ id, ...(resultFingerprint ? { resultFingerprint } : {}) }];
  });
}

/**
 * Final physical generated-SQL boundary.
 *
 * This receives the exact prepared statement immediately before the connector
 * callback.  It intentionally validates before invoking `execute`: a bad
 * capability or unproven prepared reference must result in zero warehouse
 * calls, not a post-execution warning.  It is module-exported only for the
 * local-runtime boundary harness; it is never an HTTP API or durable artifact.
 *
 * @internal
 */
export async function executePreparedAgenticSqlBoundary<T>(input: {
  capability?: AgenticSqlExecutionCapabilityV1;
  preparedSql: string;
  bindings: unknown;
  scope?: SqlAuthorizationCheck;
  execute: () => Promise<T>;
  /** Internal harness injection; production obtains the request-local observer. */
  traceObserver?: AskTraceObserverV1;
}): Promise<T> {
  const trace = input.traceObserver ?? activeAskTraceObserver();
  const sqlFingerprint = runtimeTraceFingerprint(input.preparedSql);
  const sqlPayload = {
    kind: 'sql' as const,
    execution: {
      version: 1 as const,
      sqlFingerprint,
      reviewRequired: true,
    },
  };
  // The statement reached this boundary from the frozen generated-plan path.
  // Do not infer a generation success later from execution counters: this span
  // records the actual prepared statement handoff (fingerprint only).
  const generationSpan = trace?.startSpan({
    name: 'sql.generate',
    stage: 'sql',
    reasonCode: 'started',
    payload: sqlPayload,
  });
  trace?.finishSpan(generationSpan, { outcome: 'ok', reasonCode: 'completed', payload: sqlPayload });
  const capability = input.capability;
  const validationSpan = trace?.startSpan({
    name: 'sql.validate',
    stage: 'sql',
    reasonCode: 'started',
    payload: sqlPayload,
  });
  const validation = validateAuthorizedSqlReferences(input.preparedSql, undefined);
  if (!validation.ok) {
    trace?.finishSpan(validationSpan, { outcome: 'denied', reasonCode: 'sql_denied', payload: sqlPayload });
    throw analyticalError(
      'The generated statement did not pass read-only SQL validation, so it was not executed.',
      { origin: 'governance_gate', stage: 'validation', code: 'unauthorized_sql' },
    );
  }
  trace?.finishSpan(validationSpan, { outcome: 'ok', reasonCode: 'completed', payload: sqlPayload });
  if (capability) {
    const authorizationSpan = trace?.startSpan({
      name: 'sql.authorize',
      stage: 'sql',
      reasonCode: 'started',
      payload: sqlPayload,
    });
    const authorization = mintFinalSqlAuthorization({
      sql: input.preparedSql,
      proven: capability.provenIdentifiers.map((identifier) => ({
        identifier,
        evidence: capability.evidence[identifier] ?? 'catalog',
      })),
      runId: capability.runId,
      executionId: capability.executionId,
      snapshotId: capability.snapshotId,
      planId: capability.planId,
      targetFingerprint: capability.targetFingerprint,
      bindings: input.bindings,
    });
    const verdict = verifyFinalSql(authorization, input.preparedSql, qualifyAuthorizationReferences(input.preparedSql, {
      relations: validation.referencedRelations ?? [],
      columns: validation.referencedColumns ?? [],
    }), {
      ...input.scope,
      bindings: input.bindings,
    });
    if (process.env.DQL_ORCHESTRATOR_TRACE) {
      console.warn(`[dql] execution authorization: ${verdict.ok ? 'admitted' : 'REFUSED'} proven=${authorization.provenIdentifiers.length}${verdict.ok ? '' : ` reason=${verdict.reason}`}`);
    }
    if (!verdict.ok) {
      trace?.finishSpan(authorizationSpan, { outcome: 'denied', reasonCode: 'sql_denied', payload: sqlPayload });
      throw analyticalError(
        verdict.reason ?? 'The statement was not authorized for execution.',
        { origin: 'governance_gate', stage: 'execute', code: 'unauthorized_sql' },
      );
    }
    trace?.finishSpan(authorizationSpan, { outcome: 'ok', reasonCode: 'completed', payload: sqlPayload });
  }
  const executionSpan = trace?.startSpan({
    name: 'sql.execute',
    stage: 'sql',
    reasonCode: 'started',
    payload: sqlPayload,
  });
  try {
    const result = await input.execute();
    trace?.finishSpan(executionSpan, { outcome: 'ok', reasonCode: 'completed', payload: sqlPayload });
    return result;
  } catch (error) {
    trace?.finishSpan(executionSpan, { outcome: 'error', reasonCode: 'sql_failure', payload: sqlPayload });
    throw error;
  }
}

/**
 * The DQL-artifact executor reaches this callback only after the existing
 * compiler/read-only validation completed. Record that physical boundary when
 * an Ask trace is active, without teaching the tracer to choose a tier or
 * authorize a statement. Generated SQL keeps its stronger capability-bound
 * boundary above.
 */
async function executePreparedArtifactTraceBoundary<T>(input: {
  preparedSql: string;
  reviewRequired: boolean;
  execute: () => Promise<T>;
}): Promise<T> {
  const trace = activeAskTraceObserver();
  const payload = {
    kind: 'sql' as const,
    execution: {
      version: 1 as const,
      sqlFingerprint: runtimeTraceFingerprint(input.preparedSql),
      reviewRequired: input.reviewRequired,
    },
  };
  // Certified/semantic artifact execution arrives after its own authoritative
  // compiler checks. This wrapper has no independent validation or capability
  // verdict to observe, so it records only the physical execution instead of
  // manufacturing successful validate/authorize stages after the fact.
  const execution = trace?.startSpan({ name: 'sql.execute', stage: 'sql', reasonCode: 'started', payload });
  try {
    const result = await input.execute();
    trace?.finishSpan(execution, { outcome: 'ok', reasonCode: 'completed', payload });
    return result;
  } catch (error) {
    trace?.finishSpan(execution, { outcome: 'error', reasonCode: 'sql_failure', payload });
    throw error;
  }
}


export async function startLocalServer(opts: LocalServerOptions): Promise<number> {
  const { rootDir, executor, connection: rawConnection, preferredPort, projectRoot = process.cwd() } = opts;
  // Validate before creating listeners, project state, or a connection.  A
  // malformed embedding/CLI option must fail safely rather than silently
  // starting an ambiguous rollout mode.
  // CLI flag wins; otherwise the project's persisted choice; otherwise the
  // default. Validation stays here so a typo in either source fails at startup
  // rather than silently serving an unintended rollout mode.
  const askAgentRuntimeMode = resolveAskAgentRuntimeMode(
    opts.askAgentRuntimeMode ?? readProjectAskRuntimeMode(projectRoot),
  );
  const projectWatcherFactory: typeof watch = opts.projectWatcherFactory ?? watch;
  const bindHost = opts.host ?? process.env.DQL_HOST ?? '127.0.0.1';
  const loopback = bindHost === '127.0.0.1' || bindHost === 'localhost' || bindHost === '::1';
  const authToken = opts.authToken ?? process.env.DQL_SERVER_TOKEN;
  const trustedCliTraceToken = opts.trustedCliTraceToken;
  const cliAskTraceCapabilities = createLocalCliAskTraceCapabilityRegistryV1();
  // Process-local and deliberately non-persistent. Its opaque tokens are
  // attached only to the transient retrieval candidate that the runtime will
  // immediately consume/strip before any planner or trace projection.
  const literalProbeCapabilities = createLocalLiteralProbeCapabilityRegistryV1();
  // An ephemeral `dql agent ask` runtime receives its one-shot capability from
  // its parent process. Register it through the same short-lived, scoped
  // registry used by an already-running loopback runtime's challenge endpoint.
  if (trustedCliTraceToken) cliAskTraceCapabilities.issue({ capability: trustedCliTraceToken });
  const runtimeVersion = readDqlRuntimeVersion();
  // Warm the latest-version cache in the background (2s cap, 24h cache; offline → unknown).
  void fetchLatestPublishedDqlVersion();
  const allowedOrigins = new Set((opts.allowedOrigins ?? (process.env.DQL_ALLOWED_ORIGINS ?? '').split(','))
    .map((value) => value.trim().replace(/\/$/, ''))
    .filter(Boolean));
  if (!loopback && !authToken) {
    throw new Error('Non-loopback DQL server binding requires DQL_SERVER_TOKEN (or LocalServerOptions.authToken).');
  }
  if (!loopback && allowedOrigins.size === 0) {
    throw new Error('Non-loopback DQL server binding requires DQL_ALLOWED_ORIGINS (or LocalServerOptions.allowedOrigins).');
  }
  const gitRoot = await resolveGitRoot(projectRoot);
  if (gitRoot) ensureLocalRuntimeGitignore(projectRoot);
  let projectConfig = loadProjectConfig(projectRoot);
  // The served project's embedder becomes the process default so EVERY
  // retrieval surface — catalog, SQL-lane hybrid ranking, conversation
  // matching — measures similarity with the same provider the index was
  // built with. Before this, library call sites without a project root fell
  // back to hashed embeddings while the catalog itself was semantic.
  setProcessDefaultEmbeddingProvider(projectEmbeddingProvider(projectRoot));
  // ZERO-CONFIG SEMANTIC RETRIEVAL.
  //
  // The hashed provider is a token hash: it matches shared words and nothing
  // else, so "customer accounts" cannot find a model documented as "billing
  // entities" no matter how good the ranking is. It was the default for every
  // project because turning it off required an environment variable no product
  // surface mentioned. When the machine already runs Ollama with an embedding
  // model pulled, use it — the data stays local, and a warehouse question
  // finally matches on meaning.
  //
  // Re-embedding the index is not optional here: `searchVectorObjects` returns
  // NOTHING when the requested provider disagrees with the one the index was
  // built with, so upgrading the provider without upgrading the index would
  // make retrieval strictly worse. Both move together or neither does.
  void (async () => {
    const upgrade = await autoUpgradeProjectEmbeddings(projectRoot, {
      probeLocalOllamaEmbeddings,
      upgradeVectorIndexForProject,
      setProcessDefaultEmbeddingProvider,
    });
    if (upgrade.model && upgrade.providerId !== 'hashed-token-v1') {
      console.log(`DQL: semantic retrieval enabled with local Ollama embeddings (${upgrade.model}).`);
    }
  })();
  // A slow provider needs a longer Ask window, and DQL already knows which
  // class the active provider is in: a local Ollama model or a
  // subscription-CLI passthrough costs 10-90s PER DISPATCH, so the default
  // 45s budget made them structurally unusable and every user rediscovered
  // DQL_AGENT_DEADLINE_SCALE the hard way. Register the class-appropriate
  // default; the environment variable still overrides.
  const syncDeadlineScaleToActiveProvider = () => {
    // Deterministic tests spin many servers with varied provider fixtures in
    // one process; a leaked process-wide scale would couple them. Production
    // servers are one project per process, where this default belongs.
    if (process.env.VITEST) return;
    const active = getActiveProvider(projectRoot);
    const slowLocalOrCli = active === 'ollama' || active === 'claude-code' || active === 'codex';
    // Hosted APIs still pay real latency on large-repo analyst prompts
    // (extended thinking, 80-candidate workspaces), so they get headroom
    // too — just less of it.
    const hostedApi = active === 'anthropic' || active === 'openai' || active === 'gemini' || active === 'custom-openai';
    setProcessDefaultDeadlineScale(slowLocalOrCli ? 6 : hostedApi ? 2 : 1);
  };
  syncDeadlineScaleToActiveProvider();
  // This opaque value lets the Ask browser cache distinguish a newly started
  // project/runtime on the same browser origin without exposing `projectRoot`.
  const conversationProjectIdentity = askConversationProjectIdentity(projectRoot);
  const analyticalExecutionService = new ExecutionService({
    executor,
    projectRoot,
    projectConfig: () => projectConfig,
  });
  recordAgentRuntimeVersion(projectRoot, runtimeVersion);
  // A clone carries governed Hint Graph files in Git, never the rebuildable
  // `.dql/cache` database. Materialize that projection as soon as the Notebook
  // opens so Agent Learning and the first retrieval see the same shared truth.
  // Malformed/local cache state must not prevent the rest of the OSS notebook
  // from starting; normal review/reindex surfaces can still report and repair it.
  try {
    ensureHintIndexFresh(projectRoot);
  } catch {
    // Best-effort bootstrap, consistent with the existing agent reindex path.
  }
  const configuredConnection = rawConnection
    ? normalizeProjectConnection(rawConnection, projectRoot)
    : projectConfig.defaultConnection
      ? normalizeProjectConnection(projectConfig.defaultConnection, projectRoot)
      : null;
  let connection = configuredConnection ?? resolveDbtProfileRuntimeConnection(projectRoot, projectConfig);
  const projectSnapshots = new ProjectSnapshotService<DQLManifest>();
  // Server-lifetime registry for exact compiler-owned SQL. The downstream DQL
  // artifact executor uses this to preserve the selected adapter and target
  // rather than treating compiled semantic SQL as unrelated generic SQL.
  const compiledSemanticQueries = new Map<string, SemanticRuntimeCompileResult>();
  const dashboardRunEvidence = new Map<string, {
    appId: string;
    dashboardId: string;
    snapshotId: string;
    filterFingerprint: string;
    resultFingerprint: string;
    personaFingerprint: string;
    successfulTileIds: string[];
    /** Semantic tiles that executed from compiler-owned SQL without AI repair. */
    semanticApprovalEligibleTileIds: string[];
    facts: ReturnType<typeof buildDeterministicDashboardStory>['facts'];
    story: ReturnType<typeof buildDeterministicDashboardStory>['story'];
    expiresAt: number;
  }>();
  const loadAppBuildPreviewEvidence = (runId: string) => {
    const memoryEvidence = dashboardRunEvidence.get(runId);
    if (memoryEvidence && memoryEvidence.expiresAt >= Date.now()) return memoryEvidence;
    if (memoryEvidence) dashboardRunEvidence.delete(runId);
    const storage = new LocalAppStorage(defaultLocalAppsDbPath(projectRoot));
    try {
      const persisted = storage.getAppPreviewEvidence(runId);
      if (!persisted) return null;
      return {
        appId: persisted.draftId,
        dashboardId: persisted.dashboardId,
        snapshotId: persisted.snapshotId,
        filterFingerprint: persisted.filterFingerprint,
        resultFingerprint: persisted.resultFingerprint,
        personaFingerprint: persisted.personaFingerprint,
        successfulTileIds: persisted.successfulTileIds,
        semanticApprovalEligibleTileIds: persisted.semanticApprovalEligibleTileIds,
        // Persisted receipts are bound again by draft revision, source
        // fingerprints, filters and snapshot during preflight. They therefore
        // survive a process restart without making result rows durable.
        expiresAt: Number.POSITIVE_INFINITY,
      };
    } finally {
      storage.close();
    }
  };
  const dbtNodeDetailCache = new Map<string, DbtNodeAuthoringDetail | undefined>();
  /**
   * A dbt model's authoring detail, with columns completed from the warehouse
   * when dbt documents none or only some of them. Cached per snapshot; without
   * a connection, or when the lookup fails, dbt's own columns are used.
   */
  const nodeDetailWithColumns = async (snapshotId: string, uniqueId: string): Promise<DbtNodeAuthoringDetail | undefined> => {
    const cacheKey = `${snapshotId}:${uniqueId}`;
    if (dbtNodeDetailCache.has(cacheKey)) return dbtNodeDetailCache.get(cacheKey);
    if (isWarehouseNodeId(uniqueId)) {
      // The warehouse catalog snapshot already holds the relation's columns.
      const warehouseDetail = loadWarehouseNodeAuthoringDetail(projectRoot, uniqueId);
      dbtNodeDetailCache.set(cacheKey, warehouseDetail);
      return warehouseDetail;
    }
    const dbtManifestPath = resolveDbtManifestPath(projectRoot);
    let detail = dbtManifestPath ? loadDbtNodeAuthoringDetail(dbtManifestPath, uniqueId) : undefined;
    const sql = detail?.relation ? buildNamedRelationProbeSql([detail.relation], 1) : null;
    if (detail && sql) {
      try {
        const activeConnection = await resolveExecutionConnection({});
        const result = await executor.executeQuery(sql, [], {}, activeConnection);
        detail = mergeWarehouseColumns(detail, result.rows as Array<Record<string, unknown>>);
      } catch {
        // No warehouse to ask: the builder still offers the columns dbt documents.
      }
    }
    dbtNodeDetailCache.set(cacheKey, detail);
    return detail;
  };
  const onboardingJobs = new Map<string, DbtPreparationJob>();
  const metricFlowInstaller = new ManagedMetricFlowInstaller(projectRoot);
  const projectSnapshot = () => {
    const dbtManifestPath = resolveDbtManifestPath(projectRoot, projectConfig) ?? undefined;
    const inputs = collectInputFiles({ projectRoot, dbtManifestPath });
    const signatureHash = createHash('sha256');
    for (const input of inputs.sort()) {
      try {
        const stats = statSync(input);
        signatureHash.update(`${input}\0${stats.size}\0${stats.mtimeMs}\n`);
      } catch {
        signatureHash.update(`${input}\0missing\n`);
      }
    }
    const signature = signatureHash.digest('hex');
    const previousId = projectSnapshots.current()?.snapshotId;
    const snapshot = projectSnapshots.refresh(signature, () => buildManifest({ projectRoot, dbtManifestPath }));
    if (snapshot.snapshotId !== previousId) dbtNodeDetailCache.clear();
    return {
      signature: snapshot.sourceVersion,
      snapshotId: snapshot.snapshotId,
      manifest: snapshot.value,
      stale: snapshot.stale,
      error: snapshot.error,
    };
  };
  const latestDbtPreparationJob = (): DbtPreparationJob | undefined => Array.from(onboardingJobs.values())
    .reverse()
    .find((job) => job.kind === 'dbt_prepare' || job.kind === 'dbt_refresh');
  const startDbtPreparationJob = (input: {
    kind: DbtPreparationJob['kind'];
    snapshotId: string;
    manifest: DQLManifest;
    validationDurationMs: number;
    compileDurationMs: number;
    forceRebuild?: boolean;
  }): DbtPreparationJob => {
    const now = new Date().toISOString();
    const id = apiRequestId(input.kind === 'dbt_refresh' ? 'dbt-refresh' : 'dbt-prepare');
    const job: DbtPreparationJob = {
      id,
      kind: input.kind,
      status: 'running',
      stage: 'indexing',
      progress: 65,
      message: 'Indexing dbt models, columns, semantic metrics, certified blocks, and governed relationships.',
      createdAt: now,
      updatedAt: now,
      snapshotId: input.snapshotId,
      phases: [
        { id: 'artifact_validation', label: 'Validated dbt project and artifacts', status: 'completed', durationMs: input.validationDurationMs },
        { id: 'snapshot_compile', label: 'Compiled immutable project snapshot', status: 'completed', durationMs: input.compileDurationMs },
        { id: 'search_index', label: 'Build governed search indexes', status: 'running' },
      ],
    };
    if (onboardingJobs.size >= 24) {
      for (const [existingId, existing] of onboardingJobs) {
        if (existing.status === 'running' || existing.status === 'queued') continue;
        onboardingJobs.delete(existingId);
        if (onboardingJobs.size < 16) break;
      }
    }
    onboardingJobs.set(id, job);

    // Start after the Apply response can be returned. Governed Ask calls the
    // same versioned preparation service, so an early first question awaits
    // this in-flight promise instead of starting a duplicate cold rebuild.
    setTimeout(() => {
      void (async () => {
        const indexStartedAt = Date.now();
        try {
          const prepared = await ensureAgentProjectReady(projectRoot, {
            kgPath: defaultKgPath(projectRoot),
            manifest: input.manifest,
            forceKgIndex: input.forceRebuild,
            forceMetadataCatalog: input.forceRebuild,
          });
          const current = onboardingJobs.get(id);
          if (!current || current.status === 'cancelled') return;
          const indexDurationMs = Date.now() - indexStartedAt;
          const completedAt = new Date().toISOString();
          onboardingJobs.set(id, {
            ...current,
            status: 'completed',
            stage: 'ready',
            progress: 100,
            message: `Ready. Indexed ${prepared.nodes.toLocaleString()} governed objects for fast search.`,
            updatedAt: completedAt,
            phases: current.phases.map((phase) => phase.id === 'search_index'
              ? { ...phase, status: 'completed', durationMs: indexDurationMs }
              : phase),
            result: {
              snapshotId: input.snapshotId,
              cacheHit: prepared.cacheHit,
              sourceVersion: prepared.sourceVersion,
              objectCount: prepared.nodes,
              edgeCount: prepared.edges,
              metadataFingerprint: prepared.metadataFingerprint,
              kgFingerprint: prepared.kgFingerprint,
              phaseDurationsMs: {
                artifactValidation: input.validationDurationMs,
                snapshotCompile: input.compileDurationMs,
                searchIndex: indexDurationMs,
                total: input.validationDurationMs + input.compileDurationMs + indexDurationMs,
              },
              completedAt,
            },
          });
        } catch (error) {
          const current = onboardingJobs.get(id);
          if (!current || current.status === 'cancelled') return;
          onboardingJobs.set(id, {
            ...current,
            status: 'failed',
            progress: 65,
            message: 'The dbt project is connected, but its governed search indexes need attention.',
            updatedAt: new Date().toISOString(),
            phases: current.phases.map((phase) => phase.id === 'search_index'
              ? { ...phase, status: 'failed', durationMs: Date.now() - indexStartedAt }
              : phase),
            error: error instanceof Error ? error.message : String(error),
          });
        }
      })();
    }, 0);
    return job;
  };
  const onboardingDbtPaths = (body: Record<string, unknown> = {}) => {
    const repoUrl = typeof body.repoUrl === 'string' && body.repoUrl.trim() ? body.repoUrl.trim() : undefined;
    const branch = typeof body.branch === 'string' && body.branch.trim() ? body.branch.trim() : undefined;
    const subPath = typeof body.subPath === 'string' && body.subPath.trim() ? body.subPath.trim() : undefined;
    const repo = repoUrl ? resolveRepoSource({
      provider: 'dbt', source: repoUrl.includes('gitlab') ? 'gitlab' : 'github', repoUrl, branch, subPath,
    }, projectRoot) : undefined;
    const projectDirInput = repo?.localPath ?? (typeof body.projectDir === 'string' ? body.projectDir : projectConfig.dbt?.projectDir ?? '.');
    const dbtProjectDir = resolve(projectRoot, projectDirInput);
    const manifestInput = typeof body.manifestPath === 'string' ? body.manifestPath : projectConfig.dbt?.manifestPath ?? 'target/manifest.json';
    const manifestPath = resolve(dbtProjectDir, manifestInput);
    if (!(manifestPath === dbtProjectDir || manifestPath.startsWith(`${dbtProjectDir}/`))) {
      throw Object.assign(new Error('dbt manifestPath must stay inside dbt projectDir.'), { code: 'DBT_ARTIFACT_INVALID' });
    }
    const profilesDirInput = typeof body.profilesDir === 'string'
      ? body.profilesDir
      : projectConfig.dbt?.profilesDir;
    const configuredProfilesDir = profilesDirInput ? resolve(projectRoot, profilesDirInput) : undefined;
    const profilePath = findDbtProfilePaths(projectRoot, dbtProjectDir, configuredProfilesDir)[0];
    const profilesDir = configuredProfilesDir ?? (profilePath ? dirname(profilePath) : undefined);
    return { dbtProjectDir, manifestPath, projectDirInput, manifestInput, profilesDir, repoUrl, branch, subPath, repoWarnings: repo?.warnings ?? [] };
  };
  const previewDbtOnboarding = (body: Record<string, unknown> = {}) => {
    const paths = onboardingDbtPaths(body);
    if (!existsSync(join(paths.dbtProjectDir, 'dbt_project.yml'))) throw Object.assign(new Error('dbt_project.yml was not found.'), { code: 'DBT_PROJECT_NOT_FOUND' });
    if (!existsSync(paths.manifestPath)) throw Object.assign(new Error(`dbt manifest is missing at ${paths.manifestPath}. Run dbt parse, then retry.`), { code: 'DBT_MANIFEST_MISSING' });
    let raw: Record<string, unknown>;
    try {
      raw = JSON.parse(readFileSync(paths.manifestPath, 'utf8')) as Record<string, unknown>;
    } catch (error) {
      throw Object.assign(new Error(`dbt manifest is invalid: ${error instanceof Error ? error.message : String(error)}`), { code: 'DBT_ARTIFACT_INVALID' });
    }
    const fingerprint = createHash('sha256').update(readFileSync(paths.manifestPath)).digest('hex');
    return {
      projectDir: portableProjectPath(projectRoot, paths.dbtProjectDir),
      manifestPath: relative(paths.dbtProjectDir, paths.manifestPath).replace(/\\/g, '/'),
      ...(paths.profilesDir ? { profilesDir: portableProjectPath(projectRoot, paths.profilesDir) } : {}),
      ...(paths.repoUrl ? { repoUrl: paths.repoUrl, branch: paths.branch, subPath: paths.subPath } : {}),
      ...(paths.repoWarnings.length ? { warnings: paths.repoWarnings } : {}),
      fingerprint,
      projectName: typeof (raw.metadata as Record<string, unknown> | undefined)?.project_name === 'string' ? (raw.metadata as Record<string, unknown>).project_name : undefined,
      counts: {
        models: Object.keys((raw.nodes as Record<string, unknown> | undefined) ?? {}).filter((id) => id.startsWith('model.')).length,
        sources: Object.keys((raw.sources as Record<string, unknown> | undefined) ?? {}).length,
        metrics: Object.keys((raw.metrics as Record<string, unknown> | undefined) ?? {}).length,
      },
      artifacts: {
        manifest: paths.manifestPath,
        catalog: existsSync(join(dirname(paths.manifestPath), 'catalog.json')) ? join(dirname(paths.manifestPath), 'catalog.json') : null,
        semanticManifest: existsSync(join(dirname(paths.manifestPath), 'semantic_manifest.json')) ? join(dirname(paths.manifestPath), 'semantic_manifest.json') : null,
      },
    };
  };
  const datasetWorkspace = new NotebookDatasetWorkspace(
    projectRoot,
    executor,
    connectorModuleSearchPaths(projectRoot),
  );
  let localWorkspaceReady = false;
  const ensureLocalWorkspaceReady = async (): Promise<ConnectionConfig> => {
    ensureConnectorInstalledForStartup(projectRoot, "duckdb");
    if (!localWorkspaceReady) {
      await datasetWorkspace.initialize();
      localWorkspaceReady = true;
    }
    return datasetWorkspace.localConnection;
  };
  const resolveNamedConnection = (
    name: string | undefined,
  ): ConnectionConfig | null => {
    if (!name) return null;
    // `GET /api/connections` exposes the active legacy/default connection as
    // `default` so every execution surface can present one uniform selector.
    // Resolve that selector through the same project contract used by metadata
    // APIs instead of looking only in the newer named `connections` map.
    return projectConnectionById(projectRoot, projectConfig, name);
  };
  const resolveExecutionConnection = async (
    body: Record<string, unknown>,
  ): Promise<ConnectionConfig> => {
    const target =
      body.executionTarget && typeof body.executionTarget === "object"
        ? (body.executionTarget as Record<string, unknown>)
        : null;
    if (target?.target === "local") return ensureLocalWorkspaceReady();
    if (
      target?.target === "connection" &&
      typeof target.connectionName === "string"
    ) {
      const named = resolveNamedConnection(target.connectionName);
      if (!named)
        throw new Error(`Connection not found: ${target.connectionName}`);
      return named;
    }
    return requireActiveConnection(
      isConnectionConfig(body.connection) ? body.connection : connection,
    );
  };
  const resolveAgentRunExecutionConnection = (
    request: AgentRunRequest,
  ): Promise<ConnectionConfig> => resolveExecutionConnection(
    request.executionTarget ? { executionTarget: request.executionTarget } : {},
  );
  const executionTargetDescriptor = (
    body: Record<string, unknown>,
  ): { target: 'local' } | { target: 'connection'; connectionName?: string } => {
    const target =
      body.executionTarget && typeof body.executionTarget === 'object'
        ? body.executionTarget as Record<string, unknown>
        : null;
    if (target?.target === 'local') return { target: 'local' };
    const storedConnections = getStoredConnections(
      projectConfig as unknown as Record<string, unknown>,
    );
    const connectionName = target?.target === 'connection' && typeof target.connectionName === 'string'
      ? target.connectionName
      : projectConfig.defaultConnectionName
        ?? resolveDefaultConnectionKey(
          projectConfig as unknown as Record<string, unknown>,
          storedConnections,
        );
    return {
      target: 'connection',
      ...(connectionName ? { connectionName } : {}),
    };
  };
  const requireActiveConnection = (
    candidate: ConnectionConfig | null | undefined = connection,
  ): ConnectionConfig => {
    if (!candidate) {
      // This happens before DQL compiles an artifact or hands SQL to a
      // connector. Preserve that physical boundary for the Ask trace: callers
      // can project the typed setup failure without claiming that SQL executed.
      throw analyticalError(
        'No database connection is configured yet. Open Connections, add a warehouse or local DuckDB/file connection, then retry.',
        { origin: 'host', stage: 'execute', code: 'connection_not_configured' },
      );
    }
    assertConnectionNodeCompatibility(candidate);
    return candidate;
  };

  // Auto-ensure the active connection's driver so a configured connection is never
  // left "broken" after a fresh clone, a CLI upgrade, or a Node version change (the
  // driver lives in gitignored, per-project .dql/connectors). Best-effort + non-fatal.
  if (connection) assertConnectionNodeCompatibility(connection);
  ensureConnectorInstalledForStartup(projectRoot, connection?.driver);
  if (connection && connectorAddonPackages(connection).length > 0) {
    try {
      ensureConnectionPackages(projectRoot, connection);
    } catch (error) {
      console.log(`[dql] Could not install the packages this connection needs (${error instanceof Error ? error.message : String(error)}).`);
    }
  }

  // Load semantic layer via provider system (dql native, dbt, cubejs, etc.)
  let semanticLayer: SemanticLayer | undefined;
  let semanticLayerErrors: string[] = [];
  let semanticDetectedProvider: string | undefined;
  const semanticLayerDir = join(projectRoot, 'semantic-layer');
  let semanticImportManifest = loadSemanticImportManifest(projectRoot);
  const userPrefsPath = join(projectRoot, '.dql-user-prefs.json');
  let semanticConfig = resolveProjectSemanticConfig(projectConfig, projectRoot);
  let semanticLastSyncTime: string | null = null;
  const reloadSemanticLayer = async (): Promise<SemanticLayerResult> => {
    semanticConfig = resolveProjectSemanticConfig(projectConfig, projectRoot);
    const semanticConnection = connection;
    const executeQuery = semanticConfig?.provider === 'snowflake' && semanticConnection
      ? async (sql: string) => { const r = await executor.executeQuery(sql, [], {}, semanticConnection); return { rows: r.rows }; }
      : undefined;
    const result = await resolveSemanticLayerAsync(semanticConfig, projectRoot, executeQuery);
    semanticLayerErrors = result.errors;
    semanticDetectedProvider = result.detectedProvider;
    if (result.layer) {
      semanticLayer = result.layer;
      semanticLastSyncTime = new Date().toISOString();
    } else if (result.errors.length === 0) {
      semanticLayer = undefined;
      semanticLastSyncTime = null;
    }
    semanticImportManifest = loadSemanticImportManifest(projectRoot);
    // Legacy fallback if provider system returned nothing and no errors
    if (!semanticLayer && semanticLayerErrors.length === 0 && existsSync(semanticLayerDir)) {
      try {
        semanticLayer = loadSemanticLayerFromDir(semanticLayerDir);
        semanticLastSyncTime = new Date().toISOString();
      } catch { /* continue without */ }
    }
    return result;
  };
  await reloadSemanticLayer();
  // Normal startup reuses the fingerprinted local catalog when its inputs are
  // unchanged. Explicit refresh, save, and certification paths still request
  // the default forced rebuild below.
  await refreshLocalMetadataCatalog(projectRoot, undefined, undefined, false);

  // PERF-001 / API-001: project mutations acknowledge after their source file
  // is durable. Rebuildable manifest, lineage, metadata, and KG projections run
  // in one coalesced worker lane and remain observable across page navigation.
  const operationCoordinator = new LocalOperationCoordinator(
    join(projectRoot, '.dql', 'cache', 'operations.sqlite'),
  );
  const operationSseClients = new Set<ServerResponse>();
  const operationIdempotency = new Map<string, string>();
  const projectRefreshCoordinator = new ProjectRefreshCoordinator(
    operationCoordinator,
    () => {
      projectSnapshots.invalidate();
      dbtNodeDetailCache.clear();
      invalidateAgentProjectState(projectRoot);
      _lineageCache.delete(projectRoot);
    },
  );
  const scheduleProjectRefresh = (reason: string, writeManifest = true): LocalOperation => (
    projectRefreshCoordinator.schedule({
      projectRoot,
      dbtManifestPath: resolveDbtManifestPath(projectRoot, projectConfig) ?? undefined,
      writeManifest,
      reason,
    })
  );
  const unsubscribeOperationEvents = operationCoordinator.subscribe((operation) => {
    const payload = serializeJSON(operation);
    for (const client of operationSseClients) {
      try {
        client.write(`event: operation\ndata: ${payload}\n\n`);
      } catch {
        operationSseClients.delete(client);
      }
    }
  });
  const startupDbtManifestPath = resolveDbtManifestPath(projectRoot, projectConfig);
  if (startupDbtManifestPath && !isAgentProjectIndexReady(projectRoot)) {
    try {
      const startupSnapshot = projectSnapshot();
      startDbtPreparationJob({
        kind: 'dbt_prepare',
        snapshotId: startupSnapshot.snapshotId,
        manifest: startupSnapshot.manifest,
        validationDurationMs: 0,
        compileDurationMs: 0,
        forceRebuild: true,
      });
    } catch {
      // Startup remains available with the last valid cache; Setup exposes the
      // compile error and the next explicit refresh retries preparation.
    }
  }

  const recordDatasetMetadataSnapshot = (
    datasets: DatasetSource[] = datasetWorkspace.list(),
  ): void => {
    if (datasets.length === 0) return;
    try {
      recordRuntimeSchemaSnapshot(projectRoot, {
        source: "notebook_local_datasets",
        tables: datasets.map((dataset) => ({
          relation: dataset.alias,
          schema: "notebook_local",
          name: dataset.name,
          description: [
            dataset.description,
            `${dataset.storageMode} ${dataset.format} dataset`,
            `refreshed ${dataset.refreshedAt}`,
            `trust ${dataset.trustState}`,
          ]
            .filter(Boolean)
            .join(" · "),
          source:
            dataset.storageMode === "project"
              ? "project_dataset"
              : "local_dataset",
          columns: dataset.profile.columns.map((column) => ({
            name: column.name,
            type: column.type,
            description: column.flags?.length
              ? column.flags.join(", ")
              : undefined,
          })),
        })),
      });
    } catch {
      // Dataset metadata improves retrieval but must never block notebook startup.
    }
  };
  if (datasetWorkspace.list().length > 0) {
    await ensureLocalWorkspaceReady().catch(() => undefined);
    recordDatasetMetadataSnapshot();
  }

  // Auto-register data/ CSV and Parquet files as DuckDB views so semantic layer
  // queries like `FROM orders` resolve without requiring read_csv_auto() in SQL.
  if (connection && (connection.driver === 'file' || connection.driver === 'duckdb')) {
    const dataDir = projectConfig.dataDir
      ? resolve(projectRoot, projectConfig.dataDir)
      : join(projectRoot, 'data');
    if (existsSync(dataDir)) {
      try {
        const files = readdirSync(dataDir, { withFileTypes: true })
          .filter((e) => e.isFile() && /\.(csv|parquet)$/i.test(e.name));
        for (const file of files) {
          const tableName = file.name.replace(/\.(csv|parquet)$/i, '');
          const absPath = join(dataDir, file.name).replaceAll('\\', '/');
          const reader = file.name.endsWith('.parquet') ? 'read_parquet' : 'read_csv_auto';
          const ddl = `CREATE OR REPLACE VIEW "${tableName}" AS SELECT * FROM ${reader}('${absPath}')`;
          try { await executor.executeQuery(ddl, [], {}, connection); } catch { /* non-fatal */ }
        }
      } catch { /* non-fatal */ }
    }
  }

  const executeLocalSqlForStoredResult = async (sql: string, executionConnection?: ConnectionConfig) => {
    const activeConnection = requireActiveConnection(executionConnection);
    const semantic = prepareSemanticSql(sql, semanticLayer);
    if (semantic.unresolvedRefs.length > 0) {
      throw new Error(`Unknown semantic reference${semantic.unresolvedRefs.length > 1 ? 's' : ''}: ${semantic.unresolvedRefs.join(', ')}`);
    }
    const prepared = prepareLocalExecution(semantic.sql, activeConnection, projectRoot, projectConfig);
    const result = await executor.executeQuery(
      prepared.sql,
      [],
      runtimeVariables({}),
      prepared.connection,
    );
    return normalizeQueryResult(result, semantic.semanticRefs);
  };

  const runBlockReflectionProbe = async ({ sql, invariants }: { sql: string; invariants: string[] }) => {
    const activeConnection = requireActiveConnection();
    const prepared = prepareLocalExecution(sql, activeConnection, projectRoot, projectConfig);
    const probeSql = `SELECT * FROM (${stripSqlTerminator(prepared.sql)}) _dql_probe LIMIT 2000`;
    const probeResult = await executor.executeQuery(probeSql, [], runtimeVariables({}), prepared.connection);
    const rows = (Array.isArray(probeResult?.rows) ? probeResult.rows : []) as Array<Record<string, unknown>>;
    const rawColumns = Array.isArray((probeResult as { columns?: unknown })?.columns)
      ? (probeResult as { columns: unknown[] }).columns
      : [];
    const actualColumns = rawColumns.length > 0
      ? rawColumns.map((c) => (typeof c === 'string' ? c : (c as { name?: string })?.name ?? String(c)))
      : (rows[0] ? Object.keys(rows[0]) : []);
    const invariantResults = evaluateInvariants(invariants, { columns: actualColumns, rows });
    const passed = invariantResults.filter((r) => r.passed && !r.uncheckable).length;
    const failed = invariantResults.filter((r) => !r.passed && !r.uncheckable).length;
    return {
      actualColumns,
      invariantResults,
      tests: invariants.length > 0
        ? { passed, failed, assertionCount: invariantResults.length }
        : undefined,
    };
  };

  const agentRunWorkspaceValue = (request: AgentRunRequest, key: string): string | undefined => {
    const workspace = request.workspaceContext ?? {};
    const nested = agentRunRecord(workspace.context);
    return agentRunString(workspace[key]) ?? (nested ? agentRunString(nested[key]) : undefined);
  };
  const agentRunWorkspaceValues = (request: AgentRunRequest, key: string): string[] | undefined => {
    const workspace = request.workspaceContext ?? {};
    const nested = agentRunRecord(workspace.context);
    const raw = workspace[key] ?? nested?.[key];
    if (!Array.isArray(raw)) return undefined;
    const values = raw.filter((item): item is string => typeof item === 'string' && Boolean(item.trim())).map((item) => item.trim());
    return values.length > 0 ? [...new Set(values)] : undefined;
  };

  const agentRunTitle = (question: string, fallback: string): string => {
    const cleaned = question.replace(/\s+/g, ' ').trim();
    if (!cleaned) return fallback;
    return cleaned.length > 90 ? `${cleaned.slice(0, 87)}...` : cleaned;
  };

  const parseAgentRunSelectedBlockIds = (request: AgentRunRequest): string[] => {
    const workspace = request.workspaceContext ?? {};
    const value = workspace.selectedBlockIds ?? workspace.blockIds;
    if (!Array.isArray(value)) return [];
    return Array.from(new Set(value.flatMap((item) => {
      const id = agentRunString(item);
      return id ? [id] : [];
    })));
  };

  const formatAgentRunInfrastructureError = (error: unknown, scope: string): string => {
    const message = error instanceof Error ? error.message : String(error);
    if (/Could not locate the bindings file/i.test(message) || /better[-_]sqlite3/i.test(message)) {
      return `${scope} is unavailable because the local SQLite native bindings are not installed for this Node.js runtime.`;
    }
    return message;
  };

  const formatNotebookResearchStorageError = (error: unknown): string => (
    formatAgentRunInfrastructureError(error, 'Notebook research storage')
  );

  /**
   * CTX-001 / SKILL-001 — Build surfaces receive the same server-resolved,
   * snapshot-bound domain envelope and compact evidence pack as Ask. The pack
   * is a retrieval boundary, never an authorization bypass.
   */
  const buildDirectBuildContext = async (input: {
    question: string;
    domain?: string;
    purpose?: string;
    modelAreaId?: string;
    skillRefs?: string[];
    surface: 'notebook' | 'block';
    selectedContext?: Record<string, unknown>;
  }) => {
    const snapshot = projectSnapshot();
    const activeDomain = normalizeAgentRunDomain(input.domain);
    const domainContext = resolveUiDomainContext({
      manifest: snapshot.manifest,
      activeDomain,
      purpose: input.purpose,
      modelAreaId: input.modelAreaId,
      ...(input.skillRefs?.length ? { skillRefs: input.skillRefs } : {}),
      source: activeDomain ? 'explicit_ui' : 'inferred',
      snapshotId: snapshot.snapshotId,
    });
    const contextPack = await buildLocalContextPack(projectRoot, {
      question: input.question,
      mode: 'build',
      surface: input.surface,
      selectedContext: {
        activeSurface: input.surface,
        domain: activeDomain,
        purpose: input.purpose,
        modelAreaId: input.modelAreaId,
        ...input.selectedContext,
      },
      domainContext,
      strictness: 'balanced',
      limit: 120,
    });
    return { domainContext, contextPack };
  };

  const agentRunEvaluation = (
    id: string,
    label: string,
    passed: boolean,
    severity: AgentRunEvaluation['severity'],
    message: string,
    evidence?: unknown,
  ): AgentRunEvaluation => ({ id, label, passed, severity, message, evidence });

  const agentRunArtifact = (
    kind: AgentRunArtifact['kind'],
    title: string,
    payload: unknown,
    ref?: string,
    trustState: AgentRunTrustState = 'review_required',
  ): AgentRunArtifact => ({
    id: `${kind}:${Date.now()}`,
    kind,
    title,
    trustState,
    ref,
    payload,
  });

  // Provider-backed narration for an explicitly consented Research result.
  // Ordinary Ask never enters this helper; deterministic narration remains the
  // fallback when Research has no row-egress authority.
  const narrateForAgentRun = async (
    input: NarrateInput,
    researchResultRowsOptIn = false,
    traceObserver?: AskTraceObserverV1,
  ): Promise<NarrateResult> => {
    // Without caller consent, keep narration deterministic and make no physical
    // provider dispatch. With consent, serialize only the bounded, redacted
    // sample the transport receipt will account for — bounded by the project's
    // own egress policy, so an admin kill-switch is not silently bypassed here.
    if (!researchResultRowsOptIn || !input.result) return narrateResult(input);
    const narrationRowEgress = resolveProviderResultRowEgressPolicy({
      projectSetting: projectConfig?.agent?.providerResultRowEgress,
      requestedMode: 'research',
      researchOptIn: researchResultRowsOptIn,
    });
    if (narrationRowEgress.maxNarrationRows === 0) return narrateResult(input);
    const safeResult = {
      ...input.result,
      rows: redactProviderResultRows(input.result.rows, narrationRowEgress.maxNarrationRows),
    };
    const safeInput: NarrateInput = {
      ...input,
      result: safeResult,
    };
    const narrationTrace = createProviderDispatchTrace({
      // This Research handler can execute after its async trace scope has
      // returned.  Carry the server-owned observer rather than relying on
      // AsyncLocalStorage lifetime, so the physical narration receipt and
      // provider.attempt span remain one-to-one.
      observer: traceObserver ?? activeAskTraceObserver(),
      phase: 'narration',
      purpose: 'research_narration',
      admit: (event) => {
        const ledger = agentRunProviderEvidenceContext.getStore();
        if (ledger) {
          return ledger.observe(event, {
            purpose: 'research_narration',
            dispatchPhase: 'narration',
            optIn: true,
            serializedResultShape: {
              resultRowCount: safeResult.rows.length,
              columnCount: safeResult.columns.length,
            },
            cumulativeResultRowCount: safeResult.rows.length,
          });
        }
        const envelope = prepareProviderWireEnvelopeForDispatch(event.provider, event.envelope);
        assertProviderPayloadAllowed(envelope, {
          allowResultRows: false,
          maxResultRows: 0,
          purpose: 'research_narration',
        });
        return envelope;
      },
    });
    return narrateResult(safeInput, {
    complete: async ({ system, user, signal }) => {
      const provider = await createBlockStudioAssistProvider(projectRoot);
      if (!provider) throw new Error('No AI provider configured for narration.');
      try {
        const response = await provider.generate(
          [{ role: 'system', content: system }, { role: 'user', content: user }],
          {
            maxTokens: 600,
            temperature: 0.2,
            signal,
            maxProviderDispatches: 2,
            ...narrationTrace.options,
          },
        );
        narrationTrace.settle('ok');
        return response;
      } catch (error) {
        narrationTrace.settle(signal?.aborted ? 'cancelled' : 'error', error);
        throw error;
      }
    },
    });
  };

  type GovernedAgentAnswerForRun = AgentAnswer;

  /**
   * THE GOVERNED ANSWER. Every analytical answer the host produces outside
   * an engine step — App Copilot, notebook SQL authoring, notebook research —
   * runs through the Ask pipeline exactly like an Ask turn: one interpreter
   * read, every governed tier prepared, an execution proof, the same
   * sql/result/receipt shape. `route`, `repair` and the route decision are
   * accepted for signature compatibility; the pipeline neither reroutes nor
   * replans.
   */
  async function runGovernedAgentAnswerForRun(
    request: AgentRunRequest,
    _repair?: { attempt: number; repairHint?: string },
    route: AgentRunRoute = 'generated_answer',
    onProgress?: (message: string) => void,
    _routeDecision?: IntentDecision,
  ): Promise<GovernedAgentAnswerForRun> {
    const runId = request.runId ?? randomUUID();
    const pipelineRequest = attachAskTraceObserverV1<AgentRunRequest>({ ...request, runId, askAgentRuntimeMode: 'pipeline_v3' }, askTraceObserverForV1(request));
    const result = await askPipelineExecutor({
      runId,
      request: pipelineRequest,
      route: route === 'certified_answer' || route === 'semantic_answer' ? route : 'generated_answer',
      maxRepairAttempts: 0,
      attempt: 0,
      emit: (event) => { if (event.message) onProgress?.(event.message); },
    });
    const answer = agentAnswerFromPipelineBranch(result);
    // Authoring callers read `proposedSql`; the pipeline's prepared SQL is it.
    return answer.sql && !answer.proposedSql ? { ...answer, proposedSql: answer.sql } : answer;
  }

  /**
   * The model picks a visualization while composing the answer, but only the
   * executed rows know whether that choice is viable. Preserve an authored DQL
   * chart; otherwise validate the model preference against the actual result and
   * attach a compact, explainable display contract for every consumer.
   */
  function applySmartVisualization(governedAnswer: AgentAnswer, question: string): void {
    const result = governedAnswer.result;
    if (!result || !Array.isArray(result.rows)) return;
    const rows = result.rows.filter((row): row is Record<string, unknown> => Boolean(agentRunRecord(row)));
    const columns = Array.isArray(result.columns)
      ? result.columns.map((column) => typeof column === 'string'
        ? column
        : agentRunString(agentRunRecord(column)?.name) ?? String(column))
      : (rows.length > 0 ? Object.keys(rows[0]) : []);
    if (rows.length === 0 || columns.length === 0) return;
    const existing = agentRunRecord(result.chartConfig) ?? {};
    const resultRecord = agentRunRecord(result) ?? {};
    const semanticRefs = agentRunRecord(resultRecord.semanticRefs);
    const plannedMeasures = governedAnswer.resolvedAnalyticalPlan?.outputContract.measures ?? [];
    const semanticMeasures = Array.isArray(semanticRefs?.metrics)
      ? semanticRefs.metrics.filter((value): value is string => typeof value === 'string')
      : [];
    const requestedMeasureNames = Array.from(new Set([...plannedMeasures, ...semanticMeasures]));
    const normalizedQuestion = question.toLowerCase().replace(/[^a-z0-9]+/g, ' ');
    const numericMeasureColumns = columns.filter((column) => {
      if (/(?:^|_)(?:id|key|code|rank|position)$/i.test(column)) return false;
      const hasNumericValue = rows.some((row) => typeof row[column] === 'number' && Number.isFinite(row[column] as number));
      if (!hasNumericValue) return false;
      const phrase = column.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
      return requestedMeasureNames.length > 1
        || (phrase.length > 0 && normalizedQuestion.includes(phrase));
    });
    const multiMeasureColumns = numericMeasureColumns.length > 1
      ? numericMeasureColumns
      : [];
    // A declared chart on the execution result came from authored DQL and is a
    // governed display contract. Preserve its type/bindings, but still enrich a
    // missing display format from the result semantics; otherwise an authored
    // KPI for `lifetime_spend` renders as a generic `671.4K` instead of `$671.4K`.
    // Agent `suggestedViz` remains a soft preference when no chart was authored.
    //
    // EXCEPTION: a bare `chart = "table"` with no authored bindings on a
    // NON-certified answer is the synthetic default that candidateToDqlSource
    // stamps on every generated artifact (since the Ask Apply unification) —
    // NOT an author's display choice. Treating it as authored suppressed the
    // smart visualization for every generated Ask answer. Authored tables on
    // certified blocks remain authoritative.
    const certifiedAuthoredResult = Boolean(governedAnswer.sourceCertifiedBlock)
      || governedAnswer.dqlArtifact?.kind === 'certified_block'
      || governedAnswer.kind === 'certified';
    const syntheticTableDefault = existing.chart === 'table'
      && !certifiedAuthoredResult
      && typeof existing.x !== 'string'
      && typeof existing.y !== 'string';
    const hasAuthoredChart = typeof existing.chart === 'string' && !syntheticTableDefault;
    const recommendation = recommendVisualization(projectRoot, {
      blockRef: governedAnswer.sourceCertifiedBlock ?? governedAnswer.block?.name,
      prompt: question,
      resultSchema: columns,
      rowSample: rows.slice(0, 25),
      defaultVisualization: governedAnswer.suggestedViz,
    });
    if (!recommendation.ok) return;
    const fieldHints = recommendation.display.fieldHints ?? {};
    // AGT-017 / UI-012: until the notebook chart runtime supports a true
    // multi-Y contract, a comparison table is the only representation that
    // cannot silently hide requested measures. Authored charts remain intact.
    const chart = !hasAuthoredChart && multiMeasureColumns.length > 1
      ? 'table'
      : hasAuthoredChart
      ? String(existing.chart).replace(/_/g, '-')
      : recommendation.display.defaultVisualization.replace(/_/g, '-');
    const agentChoice = typeof governedAnswer.suggestedViz === 'string'
      ? governedAnswer.suggestedViz.toLowerCase().replace(/_/g, '-')
      : undefined;
    result.chartConfig = {
      ...existing,
      chart,
      decisionSource: hasAuthoredChart ? 'authored' : agentChoice === chart ? 'agent' : 'data',
      rationale: hasAuthoredChart
        ? agentRunString(existing.rationale) ?? 'Authored DQL visualization enriched with result-aware display semantics.'
        : multiMeasureColumns.length > 1
          ? `Comparison table preserves all requested measures: ${multiMeasureColumns.join(', ')}.`
        : recommendation.display.rationale,
      ...(multiMeasureColumns.length > 1 ? { metrics: multiMeasureColumns } : {}),
      ...(typeof existing.x !== 'string' && typeof fieldHints.x === 'string' ? { x: fieldHints.x } : {}),
      ...(typeof existing.y !== 'string' && typeof fieldHints.y === 'string' ? { y: fieldHints.y } : {}),
      ...(typeof existing.color !== 'string' && typeof fieldHints.color === 'string' ? { color: fieldHints.color } : {}),
      ...(typeof existing.format !== 'string'
        && (fieldHints.format === 'currency' || fieldHints.format === 'percent' || fieldHints.format === 'number')
        ? { format: fieldHints.format }
        : {}),
    };
    governedAnswer.suggestedViz = chart;
    const evidence = governedAnswer.evidence ?? {
      route: [],
      lineage: [],
      businessContext: [],
      selectedAssets: [],
      sourceTables: [],
      semanticObjects: [],
      citations: [],
    };
    governedAnswer.evidence = evidence;
    evidence.route = [
      ...evidence.route,
      {
        tool: 'recommend_visualization',
        status: 'selected',
        label: `Smart visualization: ${chart.replace(/-/g, ' ')}`,
        detail: recommendation.display.rationale,
      },
    ];
  }

  function generatedSqlArtifactContract(
    question: string,
    sql: string,
    seed?: DqlArtifactReference,
  ): DqlArtifactReference {
    const parameterized = parameterizeSqlForDqlImport(sql);
    const artifactName = seed?.name
      ?? seed?.source.match(/\bblock\s+"([^"]+)"/i)?.[1]
      ?? deriveGeneratedDraftSlug(question);
    const domain = seed?.source.match(/\bdomain\s*=\s*"([^"]+)"/i)?.[1] ?? 'uncategorized';
    const source = candidateToDqlSource({
      name: artifactName,
      domain,
      description: question,
      owner: '',
      tags: ['ai-generated', 'review-required'],
      terms: [],
      pattern: '',
      grain: '',
      entities: [],
      outputs: [],
      dimensions: [],
      allowedFilters: parameterized.allowedFilters,
      parameterPolicy: parameterized.parameterPolicy,
      filterBindings: parameterized.filterBindings,
      parameterDecisions: parameterized.parameterDecisions,
      sourceSystems: [],
      replacementFor: [],
      reviewCadence: 'monthly',
      sql: parameterized.sql,
      llmContext: `Review-required DQL generated for: ${question}`,
    });
    return {
      ...(seed ?? { kind: 'sql_block' as const }),
      kind: 'sql_block',
      name: artifactName,
      source,
    };
  }

  /**
   * AGT-010 / API-003 / UI-011 — attach the exact artifact already used for
   * execution. Post-execution translation is forbidden because it creates a
   * second query contract whose Apply result can differ from the displayed Ask
   * result.
   */
  function attachExecutableDqlArtifactContract(governedAnswer: AgentAnswer, question: string): void {
    const originalSql = governedAnswer.proposedSql?.trim() || governedAnswer.sql?.trim();
    const executedArtifact = normalizeDqlArtifactReference(governedAnswer.result?.dqlArtifact);
    let artifact = executedArtifact ?? governedAnswer.dqlArtifact;
    if (!artifact && originalSql) artifact = generatedSqlArtifactContract(question, originalSql);
    if (!artifact?.source) return;
    const invocation = prepareBlockInvocation({
      source: artifact.source,
      parameters: artifact.parameterValues,
      question,
      surface: 'ask_ai',
    });
    const certified = governedAnswer.certification === 'certified' || governedAnswer.kind === 'certified';
    // A semantic route is governed only when its route-specific aggregation
    // proof passed. The route label is not authority: treating a blocked or
    // missing proof as governed caused the CLI to persist a successful badge
    // even though the answer artifact recorded insufficient context.
    const semantic = semanticAnswerHasPassedAggregationProof(governedAnswer);
    // A semantic aggregation proof establishes that the compiled query is
    // safe; it does not erase a frozen Ask plan's visible inferred-substitution
    // boundary. Preserve the stricter result/artifact state throughout the
    // answer card and reusable DQL contract.
    const remainsReviewRequired = artifact.trustState === 'review_required'
      || governedAnswer.result?.trustState === 'review_required';
    const artifactTrustState = certified
      ? 'certified' as const
      : remainsReviewRequired
        ? 'review_required' as const
        : semantic
          ? 'governed' as const
          : 'review_required' as const;
    governedAnswer.dqlArtifact = {
      ...artifact,
      ...(invocation.parameters.length > 0 ? { parameters: invocation.parameters } : {}),
      ...(Object.keys(invocation.values).length > 0 ? { parameterValues: invocation.values } : {}),
      persistence: artifact.sourcePath ? 'saved' : 'transient',
      trustState: artifactTrustState,
      ...(governedAnswer.result?.sql ? { compiledSql: governedAnswer.result.sql } : originalSql ? { compiledSql: originalSql } : {}),
      ...(governedAnswer.result?.executionReceipt ? { executionReceipt: governedAnswer.result.executionReceipt } : {}),
      ...(governedAnswer.result?.executableArtifact ? {
        executableArtifact: {
          ...governedAnswer.result.executableArtifact,
          kind: artifact.kind,
          trustState: artifactTrustState,
        },
      } : {}),
    };
    if (governedAnswer.result) delete governedAnswer.result.dqlArtifact;
  }

  // THE ENGINE, DECIDED ONCE. MetricFlow is planned only when its manifest
  // exists where dbt writes it — beside the dbt manifest, under the dbt
  // project directory (`dbt.projectDir`), not under the DQL root. When the
  // runtime is installed but the manifest is missing, the downgrade to the
  // native composer is recorded so a compile refusal can say why. Cached
  // briefly: the runtime status probes the CLI and, when configured, dbt
  // Cloud, and a question should not pay for that twice.
  let plannedEngineCache: { at: number; value: { engine: SemanticRuntimeAdapterId; downgraded?: string } } | undefined;
  const plannedAskEngine = async (): Promise<{ engine: SemanticRuntimeAdapterId; downgraded?: string }> => {
    if (plannedEngineCache && Date.now() - plannedEngineCache.at < 60_000) return plannedEngineCache.value;
    const planned = await resolvePlannedSemanticAdapter(projectRoot, undefined);
    const semanticManifestPath = resolveSemanticManifestPath(projectRoot, { dbtProjectDir: projectConfig.dbt?.projectDir, dbtManifestPath: projectConfig.dbt?.manifestPath, provenanceManifestPath: projectSnapshot().manifest?.dbtProvenance?.manifestPath });
    const value = planned === 'metricflow-cli' && !existsSync(semanticManifestPath)
      ? { engine: 'native' as const, downgraded: `MetricFlow is installed but ${relative(projectRoot, semanticManifestPath) || semanticManifestPath} was not found; run \`dbt parse\` in the dbt project so derived metrics compile on MetricFlow` }
      : { engine: planned };
    plannedEngineCache = { at: Date.now(), value };
    return value;
  };
  const askPipelineHost = createAskPipelineHost({
    projectRoot,
    executor,
    autoExploration: readProjectAskAutoExploration(projectRoot),
    resolveConnection: resolveAgentRunExecutionConnection,
    getSemanticLayer: () => semanticLayer,
    getManifest: () => {
      const snapshot = projectSnapshot();
      return { manifest: snapshot.manifest, snapshotId: snapshot.snapshotId };
    },
    selectProvider: async (request) => {
      // Host-only test/embedding seam, the same one the legacy runtime honours:
      // an injected provider is the interpreter; it never comes from a payload.
      if (opts.askAnalyticalPlannerProviderFactory) {
        const injected = await opts.askAnalyticalPlannerProviderFactory({ projectRoot, request });
        return injected ?? undefined;
      }
      const requested = agentRunWorkspaceValue(request, 'provider');
      const selected = await selectAssistProvider(projectRoot, requested as ProviderSettingsId | undefined);
      if (selected) askRequestProviders.set(request, selected.id);
      return selected?.provider;
    },
    // The engine the semantic candidate will compile on, decided the same
    // way `compileSemantic` decides it, so the binder speaks its dialect.
    semanticEngine: async () => plannedAskEngine().then((planned) => planned.engine),
    compileSemantic: async (request, connection, askContext?: AskSemanticCompileContext) => {
      if (!semanticLayer) throw new Error('no semantic layer is loaded');
      // Ask supplies the request-local bindings it discovered against this
      // exact target. Never substitute the default connection's cached
      // runtime-schema snapshot here: it may name the same schema/table in a
      // different Snowflake database.
      const tableMapping = await resolveSemanticTableMapping(
        executor,
        connection,
        semanticLayer,
        projectRoot,
        askContext ? undefined : projectConfig.defaultConnectionName,
        askContext ? {
          physicalBindings: askContext.physicalBindings,
          snapshotId: askContext.snapshotId,
          executionTargetFingerprint: askContext.executionTargetFingerprint,
        } : undefined,
      );
      // A full runtime that cannot actually run here (MetricFlow without a
      // parsed semantic manifest) must not veto the native composer: the
      // pipeline prepares on whatever engine can compile, and says which.
      const planned = await plannedAskEngine();
      const plannedAdapter = planned.engine;
      // MetricFlow's `mf query` command has no per-query dbt target option.
      // Give the runtime the selected Ask target and strict default-profile
      // provenance so it can refuse before dispatch instead of compiling
      // through a DB_A profile for a DB_B Ask request.
      const metricFlowAskTarget = askContext && plannedAdapter === 'metricflow-cli'
        ? resolveMetricFlowAskTargetContext(projectRoot, projectConfig, connection, askContext)
        : undefined;
      const compiled = await compileSemanticRuntimeQuery({ ...request, engine: plannedAdapter }, {
        projectRoot,
        projectConfig,
        detectedProvider: semanticDetectedProvider,
        semanticLayer,
        driver: connection.driver,
        tableMapping,
        ...(metricFlowAskTarget ? { metricFlowAskTarget } : {}),
        ...(request.signal ? { signal: request.signal } : {}),
      });
      if (!compiled) {
        // Say WHY the native composer was the engine when a fuller one was planned.
        throw new Error(`the ${plannedAdapter} semantic engine could not compose metrics ${request.metrics.join(', ')}${planned.downgraded ? ` (${planned.downgraded})` : ''}${request.dimensions.length ? ` by ${request.dimensions.join(', ')}` : ''}: no join path or grouping satisfied every metric`);
      }
      return {
        sql: compiled.sql.trim(),
        engine: compiled.engine,
        ...(compiled.fanoutProbeSql ? { fanoutProbeSql: compiled.fanoutProbeSql } : {}),
        ...(compiled.strategy ? { strategy: compiled.strategy } : {}),
        ...(compiled.warnings?.length ? { warnings: compiled.warnings } : {}),
      };
    },
    dispatchOptions: (purpose, request) => {
      // Research words its summary from computed facts only with the run's
      // consent: that call is narration on the ledger, never a drafting turn.
      const narrate = purpose === 'research_narrate';
      const dispatchPhase = purpose === 'resolve' ? 'agent_control' as const : narrate ? 'narration' as const : 'tool_followup' as const;
      const egressPurpose = narrate ? 'research_narration' as const : 'answer_generation' as const;
      const trace = createProviderDispatchTrace({
        observer: askTraceObserverForV1(request),
        phase: dispatchPhase,
        purpose: egressPurpose,
        admit: (event) => {
          const ledger = agentRunProviderEvidenceContext.getStore();
          if (ledger) {
            // Drafting one SQL statement is a short call: it is bounded by its own
            // size, not by how long the question took to read.
            return ledger.observe(event, { purpose: egressPurpose, dispatchPhase, optIn: narrate && request.researchResultRowsOptIn === true, ...(purpose === 'draft' || purpose === 'research_select' ? { expectedMs: 30_000 } : {}) });
          }
          const envelope = prepareProviderWireEnvelopeForDispatch(event.provider, event.envelope);
          assertProviderPayloadAllowed(envelope, { allowResultRows: false, maxResultRows: 0, purpose: egressPurpose });
          return envelope;
        },
      });
      // How hard the model thinks on this call. Without it every provider ran
      // at its own default, and on the subscription CLI that default spent
      // 8-12k thinking tokens reading one question: 80-120 s per call against
      // a 90 s CLI deadline, so Ask timed out, retried and often gave up.
      const reasoningEffort = askDispatchReasoningEffort(
        projectRoot,
        purpose,
        request,
        askRequestProviders.get(request) ?? getActiveProvider(projectRoot),
      );
      return { options: { ...trace.options, reasoningEffort }, settle: trace.settle };
    },
    priorIntent: (request) => {
      const store = getConversationStore();
      if (!store || !request.threadId) return undefined;
      const turns = store.recentTurns(request.threadId, 6).sort((a, b) => b.seq - a.seq);
      // A blocked turn produced no rows, but its typed reading is still the
      // question the user asked. It carries forward as an UNEXECUTED plan:
      // the next turn may keep its restrictions, ranking and period, and may
      // never claim its result. Without this a blocked turn resets the
      // conversation and the next answer silently covers every row.
      for (const turn of turns) {
        const intent = (turn.contract as Record<string, unknown> | undefined)?.askIntentV1;
        if (!intent || typeof intent !== 'object') continue;
        const executed = !turn.runStatus || ['completed', 'needs_review'].includes(turn.runStatus);
        // An answer whose SQL the AI drafted carries that statement forward, so
        // the next turn edits it; a governed answer is edited through its reading.
        const drafted = executed && Boolean(turn.sql) && [turn.certification, turn.trustLabel].includes('review_required');
        return {
          intent: intent as AnalyticalIntentV1,
          ...(executed ? {} : { executed: false }),
          ...(executed && turn.answerSummary ? { summary: turn.answerSummary } : {}),
          ...(drafted ? { sql: turn.sql, drafted: true } : {}),
        };
      }
      return undefined;
    },
    buildIdentity: () => ({ runtime: 'pipeline_v3', snapshotId: projectSnapshot().snapshotId }),
    // THE PACK IS THE PROJECTION (CTX-010). Complete eligible admission for
    // the resolved envelope, the selected skills and approved hints, the domain
    // briefing; no reranker and no fit-confirm call, so an Ask turn gains no
    // dispatch. The vocabulary the interpreter reads is built from it.
    // The catalog's own search, held to the request's domains (CTX-001): the
    // SQL drafter finds tables by names, descriptions and documented columns.
    searchCatalog: (_request, envelope, query, options) => {
      const catalog = openActiveKnowledgeSnapshot(projectRoot);
      try {
        return catalog.searchObjects({ query, objectTypes: options.objectTypes, domains: domainContextSearchDomains(envelope), limit: options.limit })
          .map((object) => {
            const relation = typeof object.payload?.relation === 'string' ? object.payload.relation : typeof object.payload?.model === 'string' ? object.payload.model : undefined;
            return { objectType: object.objectType, name: object.name, ...(relation ? { relation } : {}), ...(object.description ? { description: object.description } : {}) };
          });
      } finally {
        catalog.close();
      }
    },
    buildContextPack: async (request, envelope) => {
      const snapshot = projectSnapshot();
      const followUp = resolveAgentFollowUpContext(request.conversationContext, request.question);
      const serverSnapshot = agentRunRecord(request.conversationContext?.conversationEnvelope ?? request.conversationContext?.serverSnapshot);
      const topicRelation = agentRunString(serverSnapshot?.topicRelation);
      const preparedMetadataFingerprint = isAgentProjectIndexReady(projectRoot) ? currentMetadataFingerprint(projectRoot) : undefined;
      const targetDescriptor = executionTargetDescriptor(request as unknown as Record<string, unknown>);
      const targetConnectionName = targetDescriptor.target === 'connection' ? targetDescriptor.connectionName : undefined;
      let runtimeSchemaSnapshot: RuntimeSchemaSnapshot | undefined;
      if (targetConnectionName) {
        const targetConnection = resolveNamedConnection(targetConnectionName);
        const activeScope = targetConnection ? optionalActiveConnectionMetadataScope(projectRoot, projectConfig, targetConnection, targetConnectionName) : null;
        runtimeSchemaSnapshot = runtimeSchemaSnapshotForAgentConnection(projectRoot, targetConnectionName, activeScope?.scopeFingerprint);
      }
      return buildLocalContextPack(projectRoot, {
        question: request.question,
        focusObjectKey: request.selectedEvidenceId,
        mode: 'question',
        admission: 'complete_eligible',
        followUp,
        priorContextPackId: agentRunString(request.conversationContext?.contextPackId),
        conversationTopicRelation: topicRelation === 'continuation' || topicRelation === 'refinement' || topicRelation === 'return' || topicRelation === 'shift' ? topicRelation : undefined,
        reusePolicy: 'seed',
        preparedMetadataFingerprint,
        ...(runtimeSchemaSnapshot ? { runtimeSchemaSnapshot } : {}),
        surface: agentRunWorkspaceValue(request, 'surface') ?? 'notebook',
        selectedContext: { selectedObject: request.selectedObject, workspaceContext: request.workspaceContext },
        strictness: 'balanced',
        limit: 80,
        ...(envelope.activeDomain ? { domainContext: envelope } : {}),
      }).then((pack) => (projectSnapshot().snapshotId === snapshot.snapshotId ? pack : undefined));
    },
    // The thread's compacted memory: what earlier turns settled.
    conversation: (request) => {
      const store = getConversationStore();
      if (!store || !request.threadId) return undefined;
      const thread = store.getThread(request.threadId);
      return thread?.rollingSummary ? { summary: thread.rollingSummary } : undefined;
    },
    // Exact literal probes stay behind the operator allowlist
    // (`agent.runtimeValueGrounding.searchSafeColumns`): a column the project
    // did not name is never queried for a value, and the probe is one
    // bounded equality lookup that returns stored values only.
    literalProbeAllowed: (relation, column) => {
      const policy = resolveAgentRuntimeValueGrounding(projectConfig);
      if (policy.mode !== 'safe_automatic') return false;
      // The host names a relation by its exact physical binding (quoted,
      // database-qualified on Snowflake); the allowlist is written as
      // schema.table.column. Compare the unquoted tail, and the full spelling.
      const parts = parsePhysicalIdentifier(relation).map((part) => part.value);
      const candidates = new Set([`${relation}.${column}`, `${parts.join('.')}.${column}`, `${parts.slice(-2).join('.')}.${column}`]);
      return [...candidates].some((reference) => policy.searchSafeColumns.has(normalizeAgentSafeColumnReference(reference)));
    },
    probeLiteral: async (relation, column, value, connection) => {
      const dialect = getDialect(connection.driver);
      const quotedRelation = parsePhysicalIdentifier(relation).map((part) => part.quoted ? `"${part.value.replace(/"/g, '""')}"` : dialect.quoteIdentifier(part.value)).join('.');
      const quotedColumn = dialect.quoteIdentifier(column);
      const literal = value.replace(/'/g, "''");
      const sql = `SELECT DISTINCT ${quotedColumn} AS stored_value FROM ${quotedRelation} WHERE LOWER(CAST(${quotedColumn} AS VARCHAR)) = LOWER('${literal}') LIMIT 5`;
      const result = await executor.executeQuery(sql, [], {}, connection);
      return result.rows.map((row) => String((row as Record<string, unknown>).stored_value ?? (row as Record<string, unknown>).STORED_VALUE ?? '')).filter(Boolean);
    },
    // Physical spans for the pipeline's statements and probes: the trace
    // carries fingerprints and outcomes only, never SQL or values.
    traceExecution: (request, span) => {
      const observer = askTraceObserverForV1(request);
      const tier: 'certified' | 'semantic' | 'governed_relational' | 'exploratory_sql' | undefined = span.name === 'sql.execute'
        ? (span.tier === 'relational' ? 'governed_relational' : span.tier === 'exploratory' ? 'exploratory_sql' : span.tier)
        : undefined;
      const payload = span.name === 'sql.execute'
        ? { kind: 'sql' as const, execution: { version: 1 as const, sqlFingerprint: span.sqlFingerprint, reviewRequired: false, executionReason: span.purpose, ...(tier ? { tier } : {}) } }
        : { kind: 'tool' as const, call: { version: 1 as const, toolCallId: span.inputFingerprint.slice(0, 16), toolKind: span.toolKind, attemptIndex: 1, inputFingerprint: span.inputFingerprint } };
      const id = observer.startSpan({ name: span.name, stage: span.name === 'sql.execute' ? 'sql' : 'tool', reasonCode: 'started', payload });
      return {
        finish: (outcome, extra) => {
          const finished = span.name === 'sql.execute'
            ? { ...payload, execution: { ...(payload as { execution: Record<string, unknown> }).execution, ...(extra?.resultFingerprint ? { resultFingerprint: extra.resultFingerprint } : {}) } }
            : { ...payload, call: { ...(payload as { call: Record<string, unknown> }).call, ...(extra?.safeErrorCode ? { safeErrorCode: extra.safeErrorCode } : {}) } };
          observer.finishSpan(id, { outcome, reasonCode: outcome === 'ok' ? 'completed' : span.name === 'sql.execute' ? 'sql_failure' : 'tool_failure', payload: finished as never });
        },
      };
    },
    // The keys behind a label, under the same allowlist and the same bounded
    // equality shape: which members a singular name actually denotes.
    probeLabelKeys: async (relation, keyColumn, labelColumn, value, connection) => {
      const dialect = getDialect(connection.driver);
      const quotedRelation = parsePhysicalIdentifier(relation).map((part) => part.quoted ? `"${part.value.replace(/"/g, '""')}"` : dialect.quoteIdentifier(part.value)).join('.');
      const quotedKey = dialect.quoteIdentifier(keyColumn);
      const quotedLabel = dialect.quoteIdentifier(labelColumn);
      const literal = value.replace(/'/g, "''");
      const sql = `SELECT DISTINCT ${quotedKey} AS member_key, ${quotedLabel} AS member_label FROM ${quotedRelation} WHERE LOWER(CAST(${quotedLabel} AS VARCHAR)) = LOWER('${literal}') LIMIT 6`;
      const result = await executor.executeQuery(sql, [], {}, connection);
      return result.rows.map((row) => {
        const record = row as Record<string, unknown>;
        return { key: String(record.member_key ?? record.MEMBER_KEY ?? ''), label: String(record.member_label ?? record.MEMBER_LABEL ?? '') };
      }).filter((member) => member.key);
    },
  });
  const askPipelineExecutor = askPipelineHost.execute;

  const answerRunExecutor: AgentRouteExecutor = async (executionContext) => {
    // THE ASK PIPELINE. One interpreter, every tier prepared before anything
    // is committed. This is the whole answer path for every analytical route.
    const { runId, request } = executionContext;
    if (!request.runId) request.runId = runId;
    return askPipelineExecutor(executionContext);
  };

  const conversationRunExecutor: AgentRouteExecutor = async ({ request, routeDecision, emitAnswerDelta }) => {
    const kind = routeDecision?.conversationalKind ?? 'smalltalk';
    const isGeneralKnowledge = routeDecision?.category === 'general_knowledge';
    const answerKind = isGeneralKnowledge ? 'general_knowledge' : 'conversational';
    const catalogContext = kind === 'answer_explanation' ? '' : buildAgentRunCatalogContext();
    const suggestions = buildConversationSuggestions(projectRoot, kind);
    const nextActions: AgentRunNextAction[] = suggestions.map((prompt, index) => ({
      id: `suggest-question-${index + 1}`,
      label: prompt,
    }));

    // A closed thread-recap is an evidence lookup, not open conversation. Its
    // ranking and result facts must come only from the persisted local turn;
    // sending that turn to a provider lets ordinary prose invent a different
    // sort column or leader. `smalltalk` reaches this branch only for the
    // tightly classified recap grammar, and only when a retained recap exists.
    const persistedRecap = kind === 'smalltalk'
      ? buildConversationContextRecap(request.conversationContext)
      : undefined;
    // A question about the latest answer is likewise an evidence lookup, not
    // another warehouse run. Resolve it from the persisted artifact contract
    // before considering a provider-generated conversational reply.
    let text = persistedRecap ?? (kind === 'answer_explanation'
      ? buildPriorAnswerExplanation(request.question, request.conversationContext)
      : undefined);
    // A definitional question that NAMES a governed artifact is answerable from
    // the catalog: the description, domain, and dimensions are already recorded.
    // Reaching for a provider to paraphrase facts we hold can only add drift, and
    // the generic conversational reply this replaces used none of them.
    //
    // Returns undefined unless the question names something real, so a turn that
    // does not match keeps today's behaviour exactly.
    if (!text) text = buildGovernedObjectExplanation(request.question);
    if (text) {
      emitAnswerDelta?.(text);
    } else {
      try {
        const provider = await createBlockStudioAssistProvider(projectRoot);
        if (provider) {
          const system = buildConversationSystemPrompt(kind, isGeneralKnowledge, catalogContext, request.audience ?? 'analyst');
          const conversationMemory = renderConversationMemoryForPrompt(request.conversationContext);
          const messages = [
            { role: 'system' as const, content: system },
            ...(conversationMemory ? [{ role: 'system' as const, content: conversationMemory }] : []),
            ...(request.history ?? []).slice(-6).map((message) => ({ role: message.role, content: message.text })),
            { role: 'user' as const, content: request.question },
          ];
          // Conversation generation is a physical provider transport too.
          // It is outside the router's candidate-ID meaning call, so retain its
          // actual `generation` phase rather than relabelling it as meaning.
          const conversationTrace = createProviderDispatchTrace({
            observer: askTraceObserverForV1(request),
            phase: 'generation',
            purpose: 'answer_generation',
            admit: (event) => {
              const ledger = agentRunProviderEvidenceContext.getStore();
              if (ledger) {
                return ledger.observe(event, {
                  purpose: 'answer_generation',
                  dispatchPhase: 'generation',
                  optIn: false,
                });
              }
              const envelope = prepareProviderWireEnvelopeForDispatch(event.provider, event.envelope);
              assertProviderPayloadAllowed(envelope, {
                allowResultRows: false,
                maxResultRows: 0,
                purpose: 'answer_generation',
              });
              return envelope;
            },
          });
          try {
            text = (await provider.generate(messages, {
              maxTokens: 320,
              temperature: 0.6,
              maxProviderDispatches: 2,
              ...conversationTrace.options,
            })).trim();
            conversationTrace.settle('ok');
          } catch (error) {
            conversationTrace.settle(request.signal?.aborted ? 'cancelled' : 'error', error);
            throw error;
          }
          // Perceived-latency: surface the reply as one delta for surfaces wired to stream.
          if (text) emitAnswerDelta?.(text);
        }
      } catch (error) {
        if (error && typeof error === 'object'
          && (error as { code?: unknown }).code === 'PROVIDER_DISPATCH_BUDGET_EXHAUSTED') {
          throw error;
        }
        // Provider unavailable / errored — fall through to the deterministic reply.
        text = undefined;
      }
    }
    if (!text) {
      text = buildConversationContextRecap(request.conversationContext)
        ?? buildConversationalFallback(kind, isGeneralKnowledge, request.question, suggestions);
      emitAnswerDelta?.(text);
    }

    return {
      summary: persistedRecap
        ? 'Summarized persisted conversation facts.'
        : kind === 'answer_explanation'
          ? 'Explained the previous answer.'
          : 'Replied conversationally.',
      answer: text,
      answerKind,
      status: 'completed',
      trustState: 'not_applicable',
      stopReason: 'conversational_reply',
      artifacts: [],
      evaluations: [],
      nextActions,
    };
  };

  const contextProposalStore = new FileContextAuthoringProposalStore(projectRoot);

  /**
   * UI-019: authoring must never dead-end on a Domain/Area that does not exist
   * yet. Every modeling operation still belongs to exactly one Domain and Area
   * (`11-context-authoring-and-ai.md`); the difference is that DQL now creates
   * the missing scope as part of the same reviewable proposal instead of
   * blocking the author until they create it by hand. The synthesized
   * operations are ordinary reviewable patches, so nothing is written until the
   * proposal is explicitly committed.
   */
  const ensureAuthoringScopeOperations = (
    operations: ContextAuthoringOperation[],
    manifest: DQLManifest,
  ): ContextAuthoringOperation[] => {
    const modeling = manifest.modeling;
    if (!modeling) return operations;
    const existingDomains = new Set(Object.keys(modeling.packages ?? {}));
    const existingAreas = new Set(
      Object.values(modeling.areas ?? {}).flatMap((area) => [`${area.domain}::${area.localId}`, `${area.domain}::${area.qualifiedId}`]),
    );
    // A scope created earlier in this same batch counts as existing.
    for (const operation of operations) {
      if (operation.kind !== 'modeling_change') continue;
      if (operation.change.operation === 'upsert_domain') existingDomains.add(operation.change.value.id);
      if (operation.change.operation === 'upsert_area') existingAreas.add(`${operation.change.value.domain}::${operation.change.value.id}`);
    }

    const created: ContextAuthoringOperation[] = [];
    const domainOperationId = new Map<string, string>();
    const areaOperationId = new Map<string, string>();
    const defaultAreaName = manifest.dbtProvenance?.projectName
      ? titleCaseAuthoring(manifest.dbtProvenance.projectName)
      : 'Core models';

    const withScope = operations.map((operation): ContextAuthoringOperation => {
      if (operation.kind !== 'modeling_change') return operation;
      const change = operation.change;
      if (change.operation !== 'upsert_entity' && change.operation !== 'upsert_relationship') return operation;
      const domain = change.value.domain;
      if (!domain) return operation;
      const dependsOn = [...(operation.dependsOn ?? [])];

      if (!existingDomains.has(domain)) {
        let id = domainOperationId.get(domain);
        if (!id) {
          id = `scope:domain:${domain}`;
          domainOperationId.set(domain, id);
          created.push({
            id,
            kind: 'modeling_change',
            evidence: ['created automatically so the requested modeling scope exists'],
            change: { operation: 'upsert_domain', value: { id: domain, name: titleCaseAuthoring(domain) } },
          });
        }
        if (!dependsOn.includes(id)) dependsOn.push(id);
      }

      const areaId = change.value.areaId;
      if (areaId && !existingAreas.has(`${domain}::${areaId}`)) {
        const key = `${domain}::${areaId}`;
        let id = areaOperationId.get(key);
        if (!id) {
          id = `scope:area:${domain}:${areaId}`;
          areaOperationId.set(key, id);
          created.push({
            id,
            kind: 'modeling_change',
            dependsOn: domainOperationId.has(domain) ? [domainOperationId.get(domain)!] : [],
            evidence: ['created automatically so the requested modeling scope exists'],
            change: {
              operation: 'upsert_area',
              value: {
                id: areaId,
                domain,
                name: areaId === DEFAULT_MODEL_AREA_ID ? defaultAreaName : titleCaseAuthoring(areaId),
                description: 'Subject area created automatically when modeling started. Rename or split it at any time.',
              },
            },
          });
        }
        if (!dependsOn.includes(id)) dependsOn.push(id);
      }

      return dependsOn.length ? { ...operation, dependsOn } : operation;
    });

    return created.length ? [...created, ...withScope] : withScope;
  };

  /**
   * REL-004: when a batch binds dbt models, bring across the relationships dbt
   * already declares in its `relationships` tests. dbt states the exact key
   * pair and `dbt test` enforces it, so redrawing those edges by hand is pure
   * duplicated work.
   *
   * REL-001 is unchanged: a dbt test is evidence, not join authorization. Every
   * edge produced here is `status: 'draft'` with `fanout: 'unknown'` and no
   * validation receipt, so it can never prove an automatic join.
   */
  const appendDbtDeclaredRelationships = (
    operations: ContextAuthoringOperation[],
    manifest: DQLManifest,
  ): ContextAuthoringOperation[] => {
    const manifestPath = manifest.dbtProvenance?.manifestPath;
    if (!manifestPath || !existsSync(manifestPath)) return operations;

    // Entities this batch creates, plus entities already bound in the project.
    const bound = new Map<string, { id: string; domain: string; areaId?: string; operationId?: string }>();
    for (const entity of Object.values(manifest.modeling?.entities ?? {})) {
      bound.set(entity.dbtUniqueId, { id: entity.localId, domain: entity.domain, areaId: modelAreaLocalId(entity.areaId) });
    }
    let batchBindings = 0;
    for (const operation of operations) {
      if (operation.kind !== 'modeling_change' || operation.change.operation !== 'upsert_entity') continue;
      const value = operation.change.value;
      bound.set(value.dbtModel, { id: value.id, domain: value.domain, areaId: value.areaId, operationId: operation.id });
      batchBindings += 1;
    }
    if (batchBindings === 0 || bound.size < 2) return operations;

    let rawManifest: Record<string, unknown>;
    try { rawManifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as Record<string, unknown>; } catch { return operations; }

    const existingRelationshipIds = new Set([
      ...Object.values(manifest.modeling?.relationships ?? {}).map((relationship) => `${relationship.ownerDomain ?? ''}::${relationship.localId}`),
      ...operations.flatMap((operation) => operation.kind === 'modeling_change' && operation.change.operation === 'upsert_relationship'
        ? [`${operation.change.value.domain}::${operation.change.value.id}`]
        : []),
    ]);

    const harvested: ContextAuthoringOperation[] = [];
    for (const edge of collectDbtRelationshipTests(rawManifest, new Set(bound.keys()))) {
      if (edge.fromColumn === 'unknown' || edge.toColumn === 'unknown') continue;
      const from = bound.get(edge.fromDbtUniqueId);
      const to = bound.get(edge.toDbtUniqueId);
      if (!from || !to || from.id === to.id) continue;
      // Only offer edges this batch actually introduces, and keep cross-domain
      // links on the explicit export/import path.
      if (!from.operationId && !to.operationId) continue;
      if (from.domain !== to.domain) continue;
      const id = `${from.id}_to_${to.id}`;
      const key = `${from.domain}::${id}`;
      if (existingRelationshipIds.has(key)) continue;
      existingRelationshipIds.add(key);
      harvested.push({
        id: `dbt-test:${edge.testUniqueId}`,
        kind: 'modeling_change',
        dependsOn: [from.operationId, to.operationId].filter((value): value is string => Boolean(value)),
        evidence: [edge.testUniqueId, ...(edge.sourcePath ? [edge.sourcePath] : [])],
        change: {
          operation: 'upsert_relationship',
          value: {
            id, domain: from.domain, areaId: from.areaId ?? to.areaId,
            from: from.id, to: to.id,
            keys: [{ from: edge.fromColumn, to: edge.toColumn }],
            cardinality: 'many_to_one', fanout: 'unknown', status: 'draft',
            rationale: `Declared by the dbt relationships test ${edge.testUniqueId}. Validate against the warehouse before certifying.`,
          },
        },
      });
    }
    return harvested.length ? [...operations, ...harvested] : operations;
  };

  const previewContextAuthoring = (input: {
    origin: ContextAuthoringOrigin;
    operations: ContextAuthoringOperation[];
    /** The draft this one revises: carried forward, then overwritten by `operations` sharing an id. */
    baseOperations?: ContextAuthoringOperation[];
    expectedSnapshotId?: string;
    sourceRunId?: string;
    sourceArtifactId?: string;
    revision?: number;
    diagnostics?: ContextAuthoringDiagnosticV1[];
  }): ContextAuthoringProposalV1 => {
    const snapshot = projectSnapshot();
    if (input.expectedSnapshotId && input.expectedSnapshotId !== snapshot.snapshotId) {
      throw Object.assign(new Error('Project sources changed before the authoring proposal was previewed.'), { code: 'PROPOSAL_STALE' });
    }
    if (input.operations.length === 0) throw Object.assign(new Error('At least one authoring operation is required.'), { code: 'INVALID_REQUEST' });
    const diagnostics: ContextAuthoringDiagnosticV1[] = [...(input.diagnostics ?? [])];
    // A follow-up turn changes part of a draft and leaves the rest standing.
    // Operation ids are deterministic (entity:<domain>:<id>), so the new turn
    // overwrites the operation it revises instead of proposing a second one.
    const requested = input.baseOperations?.length
      ? mergeAuthoringOperations(input.baseOperations, input.operations)
      : input.operations;
    const operations = requested.map((operation): ContextAuthoringOperation => {
      if (operation.kind === 'skill_change') {
        const value = { ...operation.value };
        value.status = 'draft';
        if (value.sourceRefs?.some((reference) => !contextSourceReferenceExists(snapshot.manifest, reference))) {
          diagnostics.push({ code: 'UNKNOWN_GOVERNED_REFERENCE', severity: 'blocking', operationId: operation.id, message: 'The Skill proposal references a model or relationship that is not present in the current snapshot.' });
        }
        return { ...operation, value };
      }
      if (operation.kind !== 'modeling_change') return operation;
      if ((input.origin === 'ai' || input.origin === 'correction') && operation.change.operation.startsWith('remove_')) {
        diagnostics.push({ code: 'AI_DELETE_FORBIDDEN', severity: 'blocking', operationId: operation.id, message: 'Modeling AI can create or update context, but it cannot delete governed source.' });
      }
      if (operation.change.operation === 'upsert_relationship') {
        const current = operation.change.value;
        if (current.crossDomain && (input.origin === 'ai' || input.origin === 'yaml_import')) {
          diagnostics.push({ code: 'CROSS_DOMAIN_IMPORT_FORBIDDEN', severity: 'blocking', operationId: operation.id, message: 'Cross-domain relationships require the explicit export, contract, and import workflow.' });
        }
        if (input.origin === 'ai' || input.origin === 'correction' || input.origin === 'yaml_import') {
          return {
            ...operation,
            change: {
              ...operation.change,
              value: {
                ...current,
                status: 'draft',
                fanout: current.fanout === 'unsafe' ? 'forbidden' : current.fanout,
                certifiedAgainst: undefined,
                validation: undefined,
              },
            },
          };
        }
      }
      if (operation.change.operation === 'upsert_entity'
        && (input.origin === 'ai' || input.origin === 'yaml_import' || input.origin === 'dbt_discovery' || input.origin === 'warehouse_discovery')
        && !operation.change.value.areaId) {
        // Every model still belongs to exactly one Domain and subject area. An
        // omitted area is filled with the default rather than blocking the
        // author; `ensureAuthoringScopeOperations` creates it if it is new.
        diagnostics.push({ code: 'MODEL_AREA_DEFAULTED', severity: 'info', operationId: operation.id, message: `No subject area was selected, so these models were placed in "${DEFAULT_MODEL_AREA_ID}". You can rename or move them later.` });
        return { ...operation, change: { ...operation.change, value: { ...operation.change.value, areaId: DEFAULT_MODEL_AREA_ID } } };
      }
      return operation;
    });
    // dbt discovery and Modeling AI bind models; give them the edges dbt already
    // declares. Manual authoring and YAML import bring their own relationships.
    const withDeclaredEdges = input.origin === 'dbt_discovery' || input.origin === 'ai'
      ? appendDbtDeclaredRelationships(operations, snapshot.manifest)
      : operations;
    const scopedOperations = ensureAuthoringScopeOperations(withDeclaredEdges, snapshot.manifest);
    const operationIds = new Set(scopedOperations.map((operation) => operation.id));
    for (const operation of scopedOperations) {
      for (const dependency of operation.dependsOn ?? []) {
        if (!operationIds.has(dependency)) diagnostics.push({ code: 'DEPENDENCY_CONFLICT', severity: 'blocking', operationId: operation.id, message: `Required proposal operation is missing: ${dependency}` });
      }
    }

    const patches: ContextAuthoringPatchV1[] = [];
    const modelingOperations = scopedOperations.filter((operation): operation is Extract<ContextAuthoringOperation, { kind: 'modeling_change' }> => operation.kind === 'modeling_change');
    if (modelingOperations.length > 0) {
      const batch = previewModelingChanges(projectRoot, modelingOperations.map((operation) => operation.change));
      // The batch attributes each path while composing its shadow, so a change
      // that depends on an earlier one (an entity in a Domain this same batch
      // creates) is attributed correctly and without re-previewing per patch.
      const ownerByPath = new Map<string, string>();
      batch.patchPathsByChange.forEach((paths, index) => {
        const operationId = modelingOperations[index]?.id;
        if (!operationId) return;
        for (const path of paths) if (!ownerByPath.has(path)) ownerByPath.set(path, operationId);
      });
      for (const patch of batch.patches) {
        patches.push({ ...patch, owner: 'dql', operationId: ownerByPath.get(patch.path) ?? modelingOperations[0]!.id });
      }
    }
    for (const operation of scopedOperations) {
      if (operation.kind === 'skill_change') {
        const preview = previewSkillChange(projectRoot, operation.value, operation.targetQualifiedId, operation.expectedSourceHash);
        for (const patch of preview.patches) {
          patches.push({
            path: relative(projectRoot, patch.path).replace(/\\/g, '/'),
            before: patch.before,
            after: patch.after,
            changed: patch.changed,
            owner: 'dql',
            operationId: operation.id,
          });
        }
      } else if (operation.kind === 'term_change') {
        // A term is a governed definition file; the proposal shows the whole
        // file as it will be written, over what is there today.
        const termPath = termFilePath(operation.value.domain, operation.value.title);
        const absolute = join(projectRoot, termPath);
        const before = existsSync(absolute) ? readFileSync(absolute, 'utf8') : '';
        const after = buildTermTemplate(operation.value);
        patches.push({ path: termPath, before, after, changed: before !== after, owner: 'dql', operationId: operation.id });
      } else if (operation.kind === 'dbt_source_change') {
        const { dbtProjectDir, manifestPath } = onboardingDbtPaths({});
        const preview = previewDbtSourcePatch(dbtProjectDir, manifestPath, operation.change);
        patches.push({
          path: relative(projectRoot, resolve(dbtProjectDir, preview.patch.path)).replace(/\\/g, '/'),
          before: preview.patch.before,
          after: preview.patch.after,
          changed: preview.patch.changed,
          owner: 'dbt',
          operationId: operation.id,
        });
      }
    }
    const duplicatePaths = patches.map((patch) => patch.path).filter((path, index, values) => values.indexOf(path) !== index);
    for (const path of [...new Set(duplicatePaths)]) diagnostics.push({ code: 'OWNERSHIP_CONFLICT', severity: 'blocking', message: `More than one proposal operation owns ${path}. Repreview after resolving the conflict.` });
    const dependencyFingerprints = Object.fromEntries(patches.map((patch) => [
      patch.path,
      createHash('sha256').update(patch.before).digest('hex'),
    ]));
    const proposal = buildContextAuthoringProposal({
      origin: input.origin,
      baseSnapshotId: snapshot.snapshotId,
      dependencyFingerprints,
      operations: scopedOperations,
      patches,
      diagnostics,
      sourceRunId: input.sourceRunId,
      sourceArtifactId: input.sourceArtifactId,
      revision: input.revision,
    });
    contextProposalStore.save(proposal);
    return proposal;
  };

  const modelingAuthoringRunExecutor: AgentRouteExecutor = async ({ runId, request }) => {
    const snapshot = projectSnapshot();
    // AGT-024: a configured provider designs the model; the deterministic
    // matcher is the documented provider-unavailable fallback, and the answer
    // says which one ran so an evidence-only suggestion is never mistaken for
    // an AI proposal.
    // The draft the author is looking at. A second message revises it rather
    // than starting from the committed files again.
    const openDraft = openAuthoringDraft(contextProposalStore, request, snapshot.snapshotId, 'modeling_change');
    const provider = await createBlockStudioAssistProvider(projectRoot);
    let usedProvider = Boolean(provider);
    let operations: ContextAuthoringOperation[];
    if (provider) {
      try {
        operations = await buildAiModelingOperations(projectRoot, snapshot.manifest, request, provider, openDraft?.operations ?? []);
      } catch (error) {
        // Fall back only when the provider itself is unusable. A rejected
        // proposal (invented identifiers, nothing to propose) is a real result
        // and must surface, not be papered over by the template matcher.
        if (!/could not complete this modeling request/.test(error instanceof Error ? error.message : String(error))) throw error;
        usedProvider = false;
        operations = buildDeterministicModelingOperations(projectRoot, snapshot.manifest, request);
      }
    } else {
      operations = buildDeterministicModelingOperations(projectRoot, snapshot.manifest, request);
    }
    const proposal = previewContextAuthoring({
      origin: request.workspaceContext?.correction === true ? 'correction' : 'ai',
      operations,
      ...(openDraft ? { baseOperations: openDraft.operations } : {}),
      // Base the draft on the snapshot it was just built from, not on the id the
      // client captured at page load. Gating construction on the client's id
      // rejected a proposal assembled from `snapshot.manifest` moments earlier,
      // so any unrelated project write (a block edit, a dbt reapply) made every
      // Modeling AI request fail with PROPOSAL_STALE until a manual refresh.
      // Drift is still caught where it matters: applying the proposal re-checks
      // its `baseSnapshotId` and `dependencyFingerprints` and fails SOURCE_CHANGED.
      expectedSnapshotId: snapshot.snapshotId,
      sourceRunId: runId,
      revision: Number(request.workspaceContext?.revision ?? 1),
    });
    const blocked = proposal.diagnostics.some((item) => item.severity === 'blocking');
    return {
      summary: `Prepared ${proposal.impact.modelingChanges} modeling change${proposal.impact.modelingChanges === 1 ? '' : 's'} for review.`,
      answer: blocked
        ? 'I prepared a modeling proposal, but the blocking items must be resolved before it can be saved.'
        : usedProvider
          ? 'I designed a modeling proposal from your dbt metadata. Every model and column was checked against the current snapshot. Review the exact source diff before saving it as a draft.'
          : 'No AI provider is configured, so these are evidence-only suggestions matched from dbt metadata rather than an AI proposal. Review the exact source diff before saving it as a draft.',
      status: 'needs_review',
      trustState: 'review_required',
      stopReason: 'human_review_required',
      artifacts: [{ id: `${runId}:modeling-proposal`, kind: 'modeling_change_proposal', title: usedProvider ? 'Modeling change proposal' : 'Evidence-only modeling suggestions', trustState: 'review_required', ref: proposal.id, payload: proposal }],
      evaluations: proposal.diagnostics.map((diagnostic) => ({ id: `${proposal.id}:${diagnostic.code}`, label: diagnostic.code, passed: diagnostic.severity !== 'blocking', severity: diagnostic.severity, message: diagnostic.message })),
      nextActions: [{ id: 'review-modeling-proposal', label: 'Review in Modeling', artifactKind: 'modeling_change_proposal' }],
    };
  };

  const skillAuthoringRunExecutor: AgentRouteExecutor = async ({ runId, request }) => {
    const snapshot = projectSnapshot();
    // SKILL-006: same contract as Modeling AI — a provider drafts the skill
    // body and vocabulary; the template is the labelled fallback.
    const openDraft = openAuthoringDraft(contextProposalStore, request, snapshot.snapshotId, 'skill_change');
    const provider = await createBlockStudioAssistProvider(projectRoot);
    let usedProvider = Boolean(provider);
    let operations: ContextAuthoringOperation[];
    if (provider) {
      try {
        operations = await buildAiSkillOperations(projectRoot, snapshot.manifest, request, provider, openDraft?.operations ?? []);
      } catch {
        // The provider was unusable. Say so: a template presented as an AI
        // draft reads as guidance someone wrote.
        usedProvider = false;
        operations = buildMetadataBoundSkillOperations(projectRoot, snapshot.manifest, request);
      }
    } else {
      operations = buildMetadataBoundSkillOperations(projectRoot, snapshot.manifest, request);
    }
    const proposal = previewContextAuthoring({
      origin: request.workspaceContext?.correction === true ? 'correction' : 'ai',
      operations,
      ...(openDraft ? { baseOperations: openDraft.operations } : {}),
      // Same reasoning as the modeling executor above: base the draft on the
      // snapshot it was built from; apply-time re-validation catches real drift.
      expectedSnapshotId: snapshot.snapshotId,
      sourceRunId: runId,
      revision: Number(request.workspaceContext?.revision ?? 1),
    });
    return {
      summary: `Prepared ${proposal.impact.skillChanges} metadata-bound Skill change${proposal.impact.skillChanges === 1 ? '' : 's'} for review.`,
      answer: usedProvider
        ? 'I prepared a scope-qualified Skill draft. It will not guide an agent unless you save it and later activate it explicitly.'
        : 'No AI provider completed this request, so this is a metadata-bound Skill template rather than an AI draft. Edit it before saving; it will not guide an agent unless you save and activate it.',
      status: 'needs_review',
      trustState: 'review_required',
      stopReason: 'human_review_required',
      artifacts: [{ id: `${runId}:skill-proposal`, kind: 'skill_change_proposal', title: usedProvider ? 'Skill change proposal' : 'Metadata-only Skill template', trustState: 'review_required', ref: proposal.id, payload: proposal }],
      evaluations: proposal.diagnostics.map((diagnostic) => ({ id: `${proposal.id}:${diagnostic.code}`, label: diagnostic.code, passed: diagnostic.severity !== 'blocking', severity: diagnostic.severity, message: diagnostic.message })),
      nextActions: [{ id: 'review-skill-proposal', label: 'Review Skill draft', artifactKind: 'skill_change_proposal' }],
    };
  };

  const agentRunExecutors: AgentRunExecutors = {
    conversation: conversationRunExecutor,
    certified_answer: answerRunExecutor,
    semantic_answer: answerRunExecutor,
    generated_answer: answerRunExecutor,
    modeling_draft: modelingAuthoringRunExecutor,
    skill_draft: skillAuthoringRunExecutor,
    research: createInvestigationExecutor({ host: askPipelineHost, loadRun: async (runId) => agentRunStore.get(runId) }),
    sql_cell: async ({ request, routeDecision, attempt, repairHint }) => {
      const selectedCellSql = agentRunWorkspaceValue(request, 'cellSql');
      const mixedSourcePlan = selectedCellSql
        ? planMixedSourceSql(selectedCellSql, datasetWorkspace.list().map((dataset) => dataset.alias))
        : null;
      if (mixedSourcePlan) {
        const explanation = [
          `The original query directly joined warehouse data with the local dataset ${mixedSourcePlan.localDataset}. Those sources execute in different engines, so the CSV is not a missing dbt table.`,
          `I prepared the warehouse-only extraction and retained ${mixedSourcePlan.warehouseKey}, the key needed to join with ${mixedSourcePlan.localDataset}.${mixedSourcePlan.localKey}.`,
          'Insert and run this SQL on the warehouse connection. On its result, choose Combine with local data, select the local dataset, and confirm the suggested keys. The final mixed result runs locally and remains review-required.',
        ].join(' ');
        const result = {
          target: 'cell' as const,
          sql: mixedSourcePlan.warehouseSql,
          explanation,
          mixedSourcePlan,
        };
        return {
          summary: `Prepared a warehouse extraction for local combination with ${mixedSourcePlan.localDataset}.`,
          answer: explanation,
          artifacts: [agentRunArtifact('sql_cell', 'Warehouse extraction for local analysis', result)],
          evaluations: [
            agentRunEvaluation('route-decision', 'Route decision', true, 'info', routeDecision?.reason ?? 'Detected a mixed local and warehouse SQL repair.'),
            agentRunEvaluation('mixed-source-boundary', 'Mixed-source boundary', true, 'warning', 'No direct cross-engine join was executed. The user must explicitly stage the bounded warehouse result.'),
          ],
          nextActions: [{ id: 'insert-sql', label: 'Insert warehouse extraction', artifactKind: 'sql_cell' }],
        };
      }
      const requestedNotebookDataset = findMentionedNotebookDataset(
        request.question,
        datasetWorkspace.list(),
      );
      const authoringRequest: AgentRunRequest = requestedNotebookDataset
        ? {
            ...request,
            question: [
              request.question,
              '',
              `Notebook SQL fallback contract: ${requestedNotebookDataset.alias} is a local dataset, not a warehouse table. Produce the warehouse-only row-level extraction needed for the requested analysis. Include the warehouse join key that corresponds to the local dataset identifier, plus the requested order/detail columns. Do not return an aggregate certified answer and do not reference ${requestedNotebookDataset.alias} in the warehouse SQL. The UI will stage this bounded result and create the local join cell after confirmation.`,
            ].join('\n'),
          }
        : request;
      // P4: route Notebook SQL-cell generation through the SAME tool-rich governed
      // pipeline Ask AI uses (schema-discovery tools P3 + declined-retry P1 + budget
      // recovery P2), instead of the tool-less buildFromPrompt path. A SQL cell only
      // needs the SQL, which the governed answer produces directly as proposedSql.
      const governedAnswer = await runGovernedAgentAnswerForRun(
        authoringRequest,
        { attempt: attempt ?? 0, repairHint },
        'sql_cell',
      );
      attachExecutableDqlArtifactContract(governedAnswer, request.question);
      const schemaContext = requestedNotebookDataset
        ? await getSchemaContextForAgent(request.question)
        : [];
      const generatedSql = governedAnswer.proposedSql ?? governedAnswer.sql ?? '';
      const generatedPlan = requestedNotebookDataset && generatedSql.trim()
        ? planMixedSourceNotebookSql(
            generatedSql,
            {
              id: requestedNotebookDataset.id,
              name: requestedNotebookDataset.name,
              alias: requestedNotebookDataset.alias,
              columns: requestedNotebookDataset.profile.columns.map((column) => ({
                name: column.name,
                flags: column.flags,
              })),
            },
            schemaContext,
          )
        : null;
      const generatedReusedNonExactAsset = Boolean(
        governedAnswer.sourceCertifiedBlock || governedAnswer.dqlArtifact?.kind === 'certified_block',
      );
      const fallbackSql = requestedNotebookDataset && (generatedReusedNonExactAsset || !generatedSql.trim())
        ? buildMixedSourceWarehouseFallbackSql(
            request.question,
            {
              id: requestedNotebookDataset.id,
              name: requestedNotebookDataset.name,
              alias: requestedNotebookDataset.alias,
              columns: requestedNotebookDataset.profile.columns.map((column) => ({ name: column.name, flags: column.flags })),
            },
            schemaContext,
          )
        : undefined;
      const naturalMixedSourcePlan = requestedNotebookDataset && fallbackSql
        ? planMixedSourceNotebookSql(
            fallbackSql,
            {
              id: requestedNotebookDataset.id,
              name: requestedNotebookDataset.name,
              alias: requestedNotebookDataset.alias,
              columns: requestedNotebookDataset.profile.columns.map((column) => ({ name: column.name, flags: column.flags })),
            },
            schemaContext,
          )
        : generatedPlan;
      const sql = naturalMixedSourcePlan?.warehouseSql ?? generatedSql;
      const explanation = governedAnswer.answer ?? governedAnswer.text;
      const hasSql = Boolean(sql.trim());
      // Preserve the BuildCellResult shape the notebook UI already consumes.
      const result = {
        target: 'cell' as const,
        sql,
        explanation: naturalMixedSourcePlan
          ? `No certified block or semantic result exactly covered all requested sources. The workflow combines ${naturalMixedSourcePlan.warehouseRelations?.join(', ') || 'the requested warehouse tables'} in one bounded warehouse extraction, then joins it locally with ${naturalMixedSourcePlan.localDataset} on ${naturalMixedSourcePlan.warehouseKey} = ${naturalMixedSourcePlan.localKey}. Click Add workflow to notebook below to create the cells. The mixed result remains review-required.`
          : explanation,
        ...(naturalMixedSourcePlan ? { mixedSourcePlan: naturalMixedSourcePlan } : {}),
        ...(!naturalMixedSourcePlan && governedAnswer.dqlArtifact ? { dqlArtifact: governedAnswer.dqlArtifact } : {}),
        ...(governedAnswer.appliedSkills ? { appliedSkills: governedAnswer.appliedSkills } : {}),
      };
      return {
        summary: hasSql
          ? naturalMixedSourcePlan
            ? `Prepared a mixed-source notebook workflow using ${naturalMixedSourcePlan.localDataset}.`
            : 'Created a review-required DQL query cell.'
          : (explanation || 'No SQL could be generated for this request.'),
        answer: result.explanation,
        artifacts: [agentRunArtifact('sql_cell', naturalMixedSourcePlan ? 'Warehouse extraction for local analysis' : 'Generated DQL query cell', result)],
        evaluations: [
          agentRunEvaluation('route-decision', 'Route decision', true, 'info', routeDecision?.reason ?? 'Routed request to SQL cell generation.'),
          agentRunEvaluation('review-boundary', 'Review boundary', true, 'warning', naturalMixedSourcePlan
            ? 'The warehouse extraction is staged with limits and the CSV join runs locally. Mixed-source output is never auto-certified.'
            : 'Generated DQL and its compiled SQL evidence must be reviewed before certification.'),
        ],
        nextActions: naturalMixedSourcePlan ? [] : [
          { id: 'insert-sql', label: governedAnswer.dqlArtifact ? 'Insert as DQL cell' : 'Insert SQL preview', artifactKind: 'sql_cell' },
          { id: 'create-block', label: 'Review as DQL draft', route: 'dql_block_draft', artifactKind: 'dql_block_draft' },
        ],
      };
    },
    dql_block_draft: async ({
      request,
      routeDecision,
      attempt,
      repairHint,
      emit,
      runId,
      maxRepairAttempts,
    }) => {
      const contextRecord = agentRunRecord(request.conversationContext);
      const carriedDqlArtifact = normalizeDqlArtifactReference(contextRecord?.dqlArtifact)
        ?? normalizeDqlArtifactReference(request.workspaceContext?.dqlArtifact);
      // UI-016 / E2E-015: a cold Block AI request uses the same governed answer
      // pipeline as Ask and Notebook. Generation is write-free. The returned
      // ownerless artifact is persisted only when the user explicitly chooses
      // Add to Block Studio.
      const governedResult: AgentRouteExecutorResult = carriedDqlArtifact && (attempt ?? 0) === 0
        ? {
            summary: 'Reused the governed answer artifact as a transient Block AI draft.',
            answer: 'Prepared the existing governed DQL as an ownerless review draft. No file was changed.',
            artifacts: [agentRunArtifact(
              'answer',
              carriedDqlArtifact.name ?? 'Governed DQL answer',
              { dqlArtifact: carriedDqlArtifact },
              undefined,
              carriedDqlArtifact.trustState,
            )],
            evaluations: [
              agentRunEvaluation(
                'dql-artifact-reuse',
                'Reused governed DQL artifact',
                true,
                'info',
                'Reused the exact answer artifact without regenerating SQL or writing a block file.',
              ),
            ],
          }
        : await answerRunExecutor({
            request,
            route: 'generated_answer',
            routeDecision,
            attempt,
            repairHint,
            emit,
            runId,
            maxRepairAttempts,
          });
      if (governedResult.status === 'blocked' || governedResult.status === 'needs_clarification') {
        return governedResult;
      }
      const governedPayload = (governedResult.artifacts ?? [])
        .map((artifact) => agentRunRecord(artifact.payload))
        .find((payload) => Boolean(
          normalizeDqlArtifactReference(payload?.dqlArtifact)
          ?? normalizeDqlArtifactReference(payload),
        ));
      const directDqlArtifact = normalizeDqlArtifactReference(governedPayload);
      const governedAnswer: Pick<AgentAnswer, 'dqlArtifact' | 'result' | 'proposedSql' | 'sql'> | undefined = governedPayload
        ? directDqlArtifact
          ? { dqlArtifact: directDqlArtifact }
          : governedPayload as unknown as Pick<AgentAnswer, 'dqlArtifact' | 'result' | 'proposedSql' | 'sql'>
        : undefined;
      const dqlArtifact = governedAnswer
        ? ownerlessReviewDqlArtifactFromAnswer(governedAnswer, request.question)
        : undefined;
      if (!dqlArtifact) {
        return governedResult;
      }
      const sql = dqlArtifact.compiledSql
        ?? agentRunString(governedPayload?.proposedSql)
        ?? agentRunString(governedPayload?.sql);
      const result = {
        target: 'block' as const,
        name: dqlArtifact.name ?? deriveGeneratedDraftSlug(request.question),
        source: dqlArtifact.source,
        dqlSource: dqlArtifact.source,
        dqlArtifact,
        ...(sql ? { sql, sqlPreview: sql } : {}),
        ...(governedPayload?.result ? { result: governedPayload.result } : {}),
        description: request.question,
        dimensions: dqlArtifact.dimensions ?? [],
        outputs: [...(dqlArtifact.dimensions ?? []), ...(dqlArtifact.metrics ?? [])],
        certifierVerdict: {
          ready: true,
          blocking: [],
          warnings: [
            'Ownership is intentionally absent from the AI draft and is assigned by a human during promotion.',
            'Review the generated DQL, compiled SQL, grain, and result before promotion.',
          ],
        },
      };
      return {
        summary: 'Prepared an ownerless, review-required DQL block draft. No file was changed.',
        answer: governedResult.answer,
        status: 'needs_review',
        trustState: 'review_required',
        stopReason: 'human_review_required',
        artifacts: [agentRunArtifact(
          'dql_block_draft',
          result.name,
          result,
          undefined,
          'review_required',
        )],
        evaluations: [
          ...(governedResult.evaluations ?? []),
          agentRunEvaluation(
            'block-commit-boundary',
            'Explicit Block Studio commit',
            true,
            'warning',
            'Generation produced an ownerless transient DQL artifact. Add to Block Studio is the only action that writes the review draft.',
            result,
          ),
        ],
        nextActions: [
          { id: 'add-to-block-studio', label: 'Add to Block Studio', artifactKind: 'dql_block_draft' },
        ],
      };
    },
    app_build: async ({ request, routeDecision, emit }) => {
      emit({
        type: 'executor.started',
        message: 'Planning the app: matching certified blocks and finding coverage gaps.',
        route: 'app_build',
      });
      // Two-phase build: this run only PROPOSES the content list (no files). The
      // user confirms the selection and the UI calls the commit endpoint directly.
      let session: Awaited<ReturnType<typeof proposeAppAiBuild>>;
      try {
        session = await proposeAppAiBuild(projectRoot, {
          prompt: request.question,
          domain: agentRunWorkspaceValue(request, 'domain'),
          owner: agentRunWorkspaceValue(request, 'owner'),
          notebookPath: agentRunWorkspaceValue(request, 'notebookPath') ?? request.selectedObject?.path,
          selectedBlockIds: parseAgentRunSelectedBlockIds(request),
          plannerMode: 'deterministic',
        }, {
          generateGovernedAnswer: async (question) => {
            emit({
              type: 'executor.started',
              message: `Generating review-required SQL for an uncovered question: ${question}`,
              route: 'app_build',
            });
            return generateAppBuildAnswerWithRepair(question);
          },
        });
      } catch (error) {
        const message = formatAgentRunInfrastructureError(error, 'App build storage');
        return {
          summary: message,
          status: 'blocked',
          trustState: 'blocked',
          stopReason: 'blocked',
          evaluations: [
            agentRunEvaluation('route-decision', 'Route decision', true, 'info', routeDecision?.reason ?? 'Routed request to app build.'),
            agentRunEvaluation(
              'app-build-storage',
              'App build storage',
              false,
              'blocking',
              message,
              { originalErrorType: error instanceof Error ? error.name : typeof error },
            ),
          ],
          nextActions: [
            { id: 'research-coverage', label: 'Research missing coverage', route: 'research', artifactKind: 'research_run' },
            { id: 'create-gap-blocks', label: 'Create DQL drafts for gaps', route: 'dql_block_draft', artifactKind: 'dql_block_draft' },
          ],
        };
      }
      const proposal = session.status === 'proposed' ? session.proposal : undefined;
      // A real app needs a certified anchor: only offer confirmation when at least
      // one certified tile is present. Otherwise fall through to the escalate path
      // (research / draft the missing blocks) so the user isn't sent to a dead end.
      const proposed = Boolean(proposal && proposal.tiles.some((tile) => (tile.certification === 'certified' || tile.certification === 'reviewed_semantic') && !tile.error));
      const sessionPlan = agentRunRecord(session.plan);
      const appTitle = agentRunString(sessionPlan?.name) ?? 'App proposal';
      const certifiedCount = proposal?.coverage.certifiedTiles ?? 0;
      const generatedCount = proposal?.coverage.generatedTiles ?? 0;
      const semanticCount = proposal?.coverage.semanticTiles ?? 0;
      const gapCount = proposal?.coverage.gaps ?? 0;
      // A coverage gap is NOT terminal — leave status open so the gate can escalate to
      // drafting the missing blocks. Only genuine infra errors (the catch above) block.
      return {
        summary: proposed
          ? `Proposed ${certifiedCount} certified tile${certifiedCount === 1 ? '' : 's'}`
            + (semanticCount > 0 ? ` + ${semanticCount} reviewed semantic tile${semanticCount === 1 ? '' : 's'}` : '')
            + (generatedCount > 0 ? ` + ${generatedCount} AI-generated (review required)` : '')
            + (gapCount > 0 ? `; ${gapCount} question${gapCount === 1 ? '' : 's'} still uncovered` : '')
            + '. Review the list and confirm to create the app.'
          : 'App build needs more certified DQL coverage before a proposal can be assembled.',
        status: proposed ? 'needs_review' : undefined,
        trustState: proposed ? 'review_required' : undefined,
        stopReason: proposed ? 'human_review_required' : undefined,
        artifacts: proposed ? [agentRunArtifact('app_proposal', appTitle, {
          sessionId: session.id,
          appId: session.appId,
          dashboardId: session.dashboardId,
          plan: session.plan,
          proposal,
          proposalHash: session.proposalHash,
          warnings: session.warnings,
        }, session.appId)] : [],
        evaluations: [
          agentRunEvaluation('route-decision', 'Route decision', true, 'info', routeDecision?.reason ?? 'Routed request to app build.'),
          agentRunEvaluation(
            'app-coverage',
            'Certified coverage',
            proposed,
            proposed ? 'info' : 'blocking',
            proposed
              ? `Proposal is backed by ${certifiedCount} certified tile${certifiedCount === 1 ? '' : 's'}; nothing is created until you confirm.`
              : session.error ?? 'No certified app tiles matched the request.',
            session,
          ),
        ],
        nextActions: proposed
          ? [
              { id: 'confirm-app-build', label: 'Create this app', artifactKind: 'app_proposal' },
              { id: 'adjust-app-build', label: 'Adjust the plan', route: 'app_build', artifactKind: 'app_proposal' },
            ]
          : [
              { id: 'research-coverage', label: 'Research missing coverage', route: 'research', artifactKind: 'research_run' },
              { id: 'create-gap-blocks', label: 'Create DQL drafts for gaps', route: 'dql_block_draft', artifactKind: 'dql_block_draft' },
            ],
      };
    },
  };
  // One immutable, question-ranked pack is shared by routing, planning, schema
  // lookup, and governed execution for the lifetime of a request. This removes
  // both positional catalog truncation and the previous duplicate retrieval pass.
  const preparedAgentContextPacks = new WeakMap<AgentRunRequest, LocalContextPack>();
  // The catalog snapshot and compiled DQL manifest have intentionally distinct
  // snapshot-ID namespaces. Keep the manifest selected at the *same request
  // start* beside the pack instead of comparing those unrelated IDs later.
  // The current manifest service must still report the same ID before this
  // carrier is used, and execution reasserts that ID before it can run.
  const preparedAgentManifestSnapshots = new WeakMap<AgentRunRequest, {
    snapshotId: string;
    manifest: DQLManifest;
  }>();
  // The candidate-ID meaning call is the sole model-owned relevance decision
  // for an ordinary Ask.  Do not attach the optional raw-provider cross
  // encoder here: it bypasses the request-scoped dispatch ledger and can turn
  // a meaning + generation + frozen-plan repair into four physical provider
  // sends.  Deterministic retrieval already fuses exact, lexical, vector and
  // graph evidence before role-balanced admission; the canonical meaning
  // resolver may reorder only those admitted IDs under the normal Ask budget.
  // Research has its own explicitly traced planner/evidence paths and does
  // not borrow an unobserved rerank transport from this shared builder.
  const pendingAgentContextPacks = new WeakMap<AgentRunRequest, Promise<LocalContextPack>>();

  const buildAgentRunContextPack = async (request: AgentRunRequest): Promise<LocalContextPack> => {
    const prepared = preparedAgentContextPacks.get(request);
    if (prepared) return prepared;
    const pending = pendingAgentContextPacks.get(request);
    if (pending) return pending;
    const snapshot = projectSnapshot();
    const requestedDomain = normalizeAgentRunDomain(agentRunWorkspaceValue(request, 'domain'));
    // CTX-003: resolve result entities/values before evidence retrieval. The
    // router, planner, and answer loop must rank the same typed follow-up; doing
    // this only inside the provider adapter allowed stale catalog matches to win
    // before "they" / "this amount" became customer-scoped context.
    const followUp = resolveAgentFollowUpContext(request.conversationContext, request.question);
    // Persist only the server-produced binding classification on the ephemeral
    // run request. The engine/trace can explain why prior state was (or was
    // not) admitted without receiving any prior rows or prompt content.
    request.conversationBinding = followUp?.binding
      ?? (request.priorResultMemberBinding ? 'prior_result' : request.conversationBinding ?? 'none');
    // A plural deictic reference is a bounded prior-result set operation, not
    // a friendly hint. If the server-side thread cannot recover that set after
    // restart (for example a deliberately redacted legacy result), stop before
    // retrieval/planning rather than widening "those customers" to all data.
    if (followUp?.priorResultSetUnavailable) {
      request.selectedResultBindingGap = {
        code: 'PRIOR_RESULT_MEMBER_SET_UNAVAILABLE',
        message: followUp.unresolvedReferences?.[0]
          ?? 'The prior result set is unavailable, so this follow-up cannot safely run against all data.',
      };
    }
    const serverSnapshot = agentRunRecord(
      request.conversationContext?.conversationEnvelope
        ?? request.conversationContext?.serverSnapshot,
    );
    const topicRelation = agentRunString(serverSnapshot?.topicRelation);
    const workspaceSurface = agentRunWorkspaceValue(request, 'surface');
    const blockAuthoringContext = request.requestedMode === 'block'
      || workspaceSurface === 'block-studio';
    // The readiness marker is source-versioned. When it matches, pass the
    // already-built metadata identity into retrieval so buildLocalContextPack
    // opens the immutable snapshot directly instead of rebuilding all metadata
    // merely to rediscover the same fingerprint on every follow-up.
    const preparedMetadataFingerprint = isAgentProjectIndexReady(projectRoot)
      ? currentMetadataFingerprint(projectRoot)
      : undefined;
    const targetDescriptor = executionTargetDescriptor(
      request as unknown as Record<string, unknown>,
    );
    const targetConnectionName = targetDescriptor.target === 'connection'
      ? targetDescriptor.connectionName
      : undefined;
    let runtimeSchemaSnapshot: RuntimeSchemaSnapshot | undefined;
    if (targetConnectionName) {
      const targetConnection = resolveNamedConnection(targetConnectionName);
      const activeScope = targetConnection
        ? optionalActiveConnectionMetadataScope(
            projectRoot,
            projectConfig,
            targetConnection,
            targetConnectionName,
          )
        : null;
      runtimeSchemaSnapshot = runtimeSchemaSnapshotForAgentConnection(
        projectRoot,
        targetConnectionName,
        activeScope?.scopeFingerprint,
      );
    }
    const task = buildLocalContextPack(projectRoot, {
      question: request.question,
      focusObjectKey: request.selectedEvidenceId,
      mode: blockAuthoringContext ? 'build' : 'question',
      // Research plans over the complete eligible set of the envelope (CTX-010).
      ...(request.requestedMode === 'research' ? { admission: 'complete_eligible' as const } : {}),
      includeDraftBlocks: blockAuthoringContext,
      followUp,
      priorContextPackId: agentRunString(request.conversationContext?.contextPackId),
      conversationTopicRelation: topicRelation === 'continuation'
        || topicRelation === 'refinement'
        || topicRelation === 'return'
        || topicRelation === 'shift'
        ? topicRelation
        : undefined,
      // Reuse remains available for fast follow-ups; the context-pack freshness
      // contract now binds it to this runtime snapshot's connection/generation.
      reusePolicy: 'seed',
      preparedMetadataFingerprint,
      ...(runtimeSchemaSnapshot ? { runtimeSchemaSnapshot } : {}),
      surface: blockAuthoringContext
        ? 'block'
        : workspaceSurface ?? 'notebook',
      selectedContext: {
        selectedObject: request.selectedObject,
        workspaceContext: request.workspaceContext,
      },
      strictness: request.analysisDepth === 'deep' ? 'exploratory' : 'balanced',
      limit: request.analysisDepth === 'deep' ? 120 : 80,
      domainContext: requestedDomain
        ? resolveUiDomainContext({
            manifest: snapshot.manifest,
            activeDomain: requestedDomain,
            purpose: agentRunWorkspaceValue(request, 'purpose'),
            modelAreaId: agentRunWorkspaceValue(request, 'modelAreaId'),
            skillRefs: agentRunWorkspaceValues(request, 'skillRefs'),
            source: 'explicit_ui',
            snapshotId: snapshot.snapshotId,
          })
        : undefined,
    }).then((pack) => {
      // Do not associate a catalog pack with a manifest if project inputs
      // changed while retrieval was assembling it. In that case the normal
      // no-attestation path remains fail-closed and the later execution
      // boundary will require a fresh request/snapshot.
      // Refresh from the project inputs rather than reading the service's last
      // cached value. `buildLocalContextPack` and the metadata catalog use
      // their own snapshot identifiers, so a cached manifest can be older
      // even when the source files which defined this request have not
      // changed. Recomputing the manifest source fingerprint is the one
      // authoritative freshness check for this request-scoped carrier.
      if (projectSnapshot().snapshotId === snapshot.snapshotId) {
        preparedAgentManifestSnapshots.set(request, {
          snapshotId: snapshot.snapshotId,
          manifest: snapshot.manifest,
        });
      }
      preparedAgentContextPacks.set(request, pack);
      pendingAgentContextPacks.delete(request);
      return pack;
    }).catch((error) => {
      pendingAgentContextPacks.delete(request);
      throw error;
    });
    pendingAgentContextPacks.set(request, task);
    return task;
  };

  /**
   * Readiness is established from persisted local configuration and the
   * already-loaded semantic snapshot. This probe deliberately does not execute
   * SQL: it distinguishes a compiler which can author a frozen semantic plan
   * from the later connection boundary which can execute that plan.
   */
  /**
   * Retrieval evidence for the run planner's catalog context. The Ask
   * pipeline reads the snapshot vocabulary itself; this bounded candidate
   * list only ranks catalog objects for multi-step (app, modeling) planning.
   */
  const buildAgentRunEvidence = async (request: AgentRunRequest): Promise<AgentRetrievalEvidence> => {
    const startedAt = Date.now();
    const pack = await buildAgentRunContextPack(request);
    const meaningEvidence = pack.retrievalDiagnostics.meaningEvidence;
    if (!meaningEvidence) {
      return {
        snapshotId: pack.knowledgeLens.snapshotId,
        sourceFingerprint: pack.freshness.fingerprint ?? undefined,
        knowledgeLens: pack.knowledgeLens,
        candidates: [],
        diagnostics: { durationMs: Date.now() - startedAt },
      } as AgentRetrievalEvidence;
    }
    const evidence = toAgentRetrievalEvidence(meaningEvidence, pack.questionPlan, {
      snapshotId: pack.knowledgeLens.snapshotId,
      sourceFingerprint: pack.freshness.fingerprint ?? undefined,
      knowledgeLens: pack.knowledgeLens,
      analyticalPolicies: pack.skills.flatMap((skill) => skill.analyticalPolicy ? [skill.analyticalPolicy] : []),
      contextObjects: pack.objects,
      retrievalLanes: pack.retrievalDiagnostics.lanes,
      durationMs: Date.now() - startedAt,
      truncated: pack.retrievalDiagnostics.topRejected.length > 0,
      preferSnapshotCandidates: true,
    });
    return applyContextPackCompatibility(evidence, pack, request.selectedEvidenceId);
  };

  /**
   * One retrieval build per Ask request, shared by both runtimes.
   *
   * In shadow mode V2 builds evidence, discards its decision, and delegates to
   * V1 — which builds evidence again from the identical request object. The
   * context pack was already memoized, but candidate binding, relationship-path
   * hashing and the workspace bridge were redone every turn for a result
   * nothing consumed. Keyed by request identity (each turn constructs exactly
   * one), so nothing is shared across turns and no snapshot is held open.
   */
  const agentRunEvidenceByRequest = new WeakMap<AgentRunRequest, Promise<AgentRetrievalEvidence>>();
  const memoizedAgentRunEvidence = (request: AgentRunRequest): Promise<AgentRetrievalEvidence> => {
    const existing = agentRunEvidenceByRequest.get(request);
    if (existing) return existing;
    const built = buildAgentRunEvidence(request);
    agentRunEvidenceByRequest.set(request, built);
    return built;
  };

  const buildRankedAgentRunCatalogContext = async (request: AgentRunRequest): Promise<string> => {
    const evidence = await memoizedAgentRunEvidence(request);
    return evidence.candidates.map((candidate) => {
      const detail = candidate.definition ? `: ${candidate.definition}` : '';
      return `- ${candidate.id} [${candidate.trustTier}; ${candidate.compatibility}]${detail}`;
    }).join('\n');
  };

  // Compact fallback used only for plain conversational replies. Analytical
  // turns use the structured, question-ranked evidence path above.
  /**
   * Explain a governed artifact the question names, from catalog metadata alone.
   *
   * Certified blocks are offered first: when a concept exists both as a
   * certified block and a raw model, the certified one is the authored
   * definition and the other is an implementation detail.
   */
  const buildGovernedObjectExplanation = (question: string): string | undefined => {
    try {
      const blocks = collectPlanBlocks(projectRoot, { certifiedOnly: true });
      const certifiedNames = new Set(blocks.map((block) => block.name));
      const all = [
        ...blocks.map((block) => ({ block, status: 'certified' })),
        ...collectPlanBlocks(projectRoot, { certifiedOnly: false })
          .filter((block) => !certifiedNames.has(block.name))
          .map((block) => ({ block, status: 'draft' })),
      ];
      // Metrics as well as blocks. "How is revenue defined here?" names a
      // semantic metric, not a block, and answering it from the metric's own
      // description is the whole point of holding one.
      const metricObjects = loadSemanticMetrics(projectRoot).map((metric) => ({
        objectKey: `semantic:metric:${metric.name}`,
        objectType: 'semantic_metric',
        name: metric.name,
        ...(metric.description ? { description: metric.description } : {}),
        ...(metric.domain ? { domain: metric.domain } : {}),
        status: 'governed',
        payload: {},
      }));
      const explanation = composeBusinessExplanation(question, [
        ...all.map(({ block, status }) => ({
          objectKey: `dql:block:${block.name}`,
          objectType: 'dql_block',
          name: block.name,
          ...(block.description ? { description: block.description } : {}),
          ...(block.domain ? { domain: block.domain } : {}),
          status,
          payload: {
            ...(block.dimensions?.length ? { dimensions: block.dimensions } : {}),
          },
        })),
        ...metricObjects,
      ]);
      return explanation?.text;
    } catch {
      // Never let an explanation attempt break a conversational turn.
      return undefined;
    }
  };

  const buildAgentRunCatalogContext = (): string => {
    try {
      const blocks = collectPlanBlocks(projectRoot, { certifiedOnly: true });
      const sourceBlocks = blocks.length > 0 ? blocks : collectPlanBlocks(projectRoot, { certifiedOnly: false });
      const blockLines = sourceBlocks.slice(0, 24).map((block) => {
        const domain = block.domain ? ` [${block.domain}]` : '';
        const detail = block.description ? `: ${block.description}` : '';
        return `- ${block.name}${domain}${detail}`;
      });
      const metrics = loadSemanticMetrics(projectRoot).slice(0, 24);
      const metricLines = metrics.map((metric) => {
        const node = metric as { name?: string; label?: string; id?: string };
        return `- ${node.name ?? node.label ?? node.id ?? 'metric'}`;
      });
      return [
        blockLines.length > 0 ? `Available DQL blocks:\n${blockLines.join('\n')}` : 'Available DQL blocks: none',
        metricLines.length > 0 ? `Governed metrics:\n${metricLines.join('\n')}` : '',
      ].filter(Boolean).join('\n\n');
    } catch {
      return '';
    }
  };

  // Provider-agnostic completion the planner injects. Reuses the configured provider
  // adapter; throwing here makes the planner fall back to its deterministic path.
  const agentRunPlanner = createLlmAgentRunPlanner({
    complete: async ({ system, user, request, signal }) => {
      const provider = await createBlockStudioAssistProvider(projectRoot);
      if (!provider) throw new Error('No AI provider configured for planning.');
      const planningTrace = createProviderDispatchTrace({
        observer: askTraceObserverForV1(request),
        phase: 'planning',
        purpose: 'answer_generation',
        admit: (event) => {
          const ledger = agentRunProviderEvidenceContext.getStore();
          if (ledger) {
            return ledger.observe(event, {
              purpose: 'answer_generation',
              dispatchPhase: 'planning',
              optIn: false,
            });
          }
          const envelope = prepareProviderWireEnvelopeForDispatch(event.provider, event.envelope);
          assertProviderPayloadAllowed(envelope, {
            allowResultRows: false,
            maxResultRows: 0,
            purpose: 'answer_generation',
          });
          return envelope;
        },
      });
      try {
        const response = await provider.generate(
          [
            { role: 'system', content: system },
            { role: 'user', content: user },
          ],
          {
            maxTokens: 700,
            temperature: 0.1,
            signal,
            // A planner is one bounded preparation transport, never a retry
            // lane. The run-scoped ledger also enforces the cross-phase cap.
            maxProviderDispatches: 1,
            ...planningTrace.options,
          },
        );
        planningTrace.settle('ok');
        return response;
      } catch (error) {
        planningTrace.settle(signal?.aborted ? 'cancelled' : 'error', error);
        throw error;
      }
    },
    getCatalogContext: buildRankedAgentRunCatalogContext,
  });
  // Cold runtime-value indexes are common immediately after a project opens.
  // This is deliberately a *single* host-owned exact existence check, not a
  // value-search tool: it may operate only on one already-qualified snapshot
  // field that the project explicitly allowlists, and it returns no row/value
  // payload to the Ask runtime or trace.
  // The rollout selection is server-owned. It is copied onto each internal
  // AgentRun request immediately before the engine runs so the engine can
  // distinguish the authoritative-V2 Research entry from the legacy forced
  // `requestedMode: research` shortcut. Public JSON parsing never accepts
  // this field.
  const agentRunRouter = {
    mode: askAgentRuntimeMode,
    // The pipeline reads the question once, inside its executor; the router
    // only says "answer". No retrieval, no certified fast path, no regex
    // classification happens before the interpreter has spoken.
    decide: async (request: AgentRunRequest): Promise<IntentDecision> => ({
      action: 'answer',
      confidence: 1,
      reason: 'Ask pipeline: the interpreter resolves the intent and the host prepares every governed tier.',
      followsUp: Boolean(request.threadId),
      source: 'heuristic',
    }),
  };

  // P0: one row per run with retention + old-run compaction. The legacy JSON
  // store rewrote the entire file (123 MB observed) twice per answered question;
  // existing history is imported once and the JSON renamed to *.migrated.
  const agentRunStore = new SqliteAgentRunStore({
    path: defaultAgentRunSqlitePath(projectRoot),
    legacyJsonPath: defaultAgentRunStorePath(projectRoot),
  });
  // OBS-002: traces intentionally live outside agent-runs.sqlite. A corrupt,
  // oversized, or schema-newer trace store must not make Ask unavailable.
  const askTraceStore = new AskTraceSqliteStoreV1({
    path: defaultAskTraceSqlitePath(projectRoot),
  });
  const conversationStorePath = await prepareConversationPath(projectRoot);
  // A run may outlive its streaming browser connection, so cancellation is
  // server-owned and keyed by run id rather than relying on fetch abort alone.
  const activeAgentRunControllers = new Map<string, AbortController>();
  const cancelActiveAgentRun = (id: string): boolean => {
    const controller = activeAgentRunControllers.get(id);
    if (!controller) return false;
    const progress = agentRunStore.getProgress(id);
    if (progress) {
      agentRunStore.saveProgress({
        ...progress,
        lifecycle: {
          ...progress.lifecycle,
          state: 'cancelling',
          revision: progress.lifecycle.revision + 1,
          updatedAt: new Date().toISOString(),
        },
      });
    }
    controller.abort(createAgentRunCancellationError());
    return true;
  };
  const activeAnalyticalRepairReservations = new Set<string>();
  const consumedAnalyticalRepairCapabilities = new Set<string>();
  // Server-side conversation threads: persisted multi-turn state (survives refresh).
  // Lazy so a failed native-sqlite load never blocks the runtime; conversation
  // persistence degrades to the per-request context instead.
  let conversationStoreInstance: ConversationStore | null | undefined;
  const getConversationStore = (): ConversationStore | null => {
    if (conversationStoreInstance !== undefined) return conversationStoreInstance;
    try {
      conversationStoreInstance = new ConversationStore(conversationStorePath);
    } catch {
      conversationStoreInstance = null;
    }
    return conversationStoreInstance;
  };
  const agentRunEngine = new AgentRunEngine({
    store: agentRunStore,
    executors: {
      ...agentRunExecutors,
      ...(opts.agentRunExecutors ?? {}),
    },
    gates: defaultAgentRunGates,
    planner: agentRunPlanner,
    router: agentRunRouter,
    traceObserverFactory: ({ runId, request, requestedMode }) => createAskTraceObserverV1({
      store: askTraceStore,
      runId,
      // This host-only value is attached after HTTP capability validation.
      // The public JSON parser never accepts a caller-supplied surface.
      surface: request.traceSurface ?? 'browser',
      mode: requestedMode === 'research' ? 'research' : 'ask',
      // The durable trace never receives the question text. This server-side
      // fingerprint is stable enough to correlate a reviewed reproduction.
      questionFingerprint: `sha256:${createHash('sha256').update(request.question).digest('hex')}`,
      ...(request.threadId ? { threadId: request.threadId } : {}),
    }),
  });

  const runNotebookForApp = async (appId: string, notebookPath: string): Promise<void> => {
    const absPath = safeJoin(projectRoot, notebookPath);
    if (!absPath || !existsSync(absPath) || statSync(absPath).isDirectory() || !absPath.endsWith('.dqlnb')) {
      throw new Error(`Notebook not found: ${notebookPath}`);
    }
    const app = loadRuntimeApp(projectRoot, appId);
    if (!app) throw new Error(`App "${appId}" not found`);

    const raw = readFileSync(absPath, 'utf-8');
    const parsed = JSON.parse(raw) as {
      cells?: Array<Record<string, unknown>>;
    };
    const sourceCells = parsed.cells ?? [];
    const resultByName = new Map<string, ReturnType<typeof normalizeQueryResult>>();
    const resultById = new Map<string, ReturnType<typeof normalizeQueryResult>>();
    const snapshotCells: Array<{
      cellId: string;
      status: 'idle' | 'running' | 'success' | 'error';
      result?: ReturnType<typeof normalizeQueryResult>;
      compiledSqlFingerprint?: string;
      resultFingerprint?: string;
      error?: string;
      executionCount?: number;
      executedAt?: string;
    }> = [];

    for (let index = 0; index < sourceCells.length; index++) {
      const sourceCell = sourceCells[index];
      const cellId = typeof sourceCell.id === 'string' ? sourceCell.id : `cell-${index + 1}`;
      const type = typeof sourceCell.type === 'string' ? sourceCell.type : 'sql';
      const title = typeof sourceCell.name === 'string'
        ? sourceCell.name
        : typeof sourceCell.title === 'string'
          ? sourceCell.title
          : undefined;
      const executedAt = new Date().toISOString();

      if (type === 'sql' || type === 'dql') {
        try {
          const cell: NotebookCell = {
            id: cellId,
            type: type as NotebookCell['type'],
            source: typeof sourceCell.content === 'string'
              ? sourceCell.content
              : typeof sourceCell.source === 'string'
                ? sourceCell.source
                : '',
            title,
            config: (sourceCell.chartConfig ?? sourceCell.config) as NotebookCell['config'],
          };
          const resolved = resolveNotebookBlockReferenceCell(cell, projectRoot);
          const activeConnection = requireActiveConnection();
          const tableMapping = await resolveSemanticTableMapping(executor, activeConnection, semanticLayer, projectRoot);
          const semanticCompose = resolved.cell.type === 'dql'
            && semanticLayer
            && /\btype\s*=\s*"semantic"/i.test(resolved.cell.source)
            ? await composeSemanticBlockSqlForRuntime(resolved.cell.source, semanticLayer, {
                driver: activeConnection.driver,
                tableMapping,
                detectedProvider: semanticDetectedProvider,
                projectRoot,
                projectConfig,
              })
            : null;
          if (semanticCompose && !semanticCompose.sql) {
            throw new Error(semanticCompose.diagnostics.map((diagnostic) => diagnostic.message).join(' '));
          }
          const plan = buildExecutionPlan(resolved.cell, {
            semanticLayer,
            driver: activeConnection.driver,
            tableMapping,
            semanticSql: semanticCompose?.sql ?? undefined,
          });
          const executableSql = semanticCompose?.sql ?? plan?.sql;
          if (!executableSql) {
            snapshotCells.push({ cellId, status: 'idle', executionCount: 0, executedAt });
            continue;
          }
          assertAppAccess({ app, domain: resolved.domain ?? app.domain, level: 'execute' });
          const execution = await analyticalExecutionService.execute({
            sql: executableSql,
            subject: 'App notebook query',
            connection: activeConnection,
            sqlParams: plan?.sqlParams,
            variables: plan?.variables,
          });
          const result = execution.result;
          snapshotCells.push({
            cellId,
            status: 'success',
            result,
            compiledSqlFingerprint: execution.compiledSqlFingerprint,
            resultFingerprint: execution.resultFingerprint,
            executionCount: 1,
            executedAt,
          });
          resultById.set(cellId, result);
          if (title) resultByName.set(title, result);
        } catch (err) {
          snapshotCells.push({
            cellId,
            status: 'error',
            error: err instanceof Error ? err.message : String(err),
            executionCount: 1,
            executedAt,
          });
        }
        continue;
      }

      const upstream = typeof sourceCell.upstream === 'string' ? sourceCell.upstream : undefined;
      const upstreamResult = upstream ? resultByName.get(upstream) ?? resultById.get(upstream) : undefined;
      if (upstreamResult && (type === 'chart' || type === 'table' || type === 'pivot' || type === 'single_value' || type === 'filter')) {
        snapshotCells.push({
          cellId,
          status: 'success',
          result: upstreamResult,
          executionCount: 1,
          executedAt,
        });
      }
    }

    writeRunSnapshot(projectRoot, notebookPath, {
      version: 1,
      notebookPath,
      capturedAt: new Date().toISOString(),
      cells: snapshotCells,
    });
  };

  const executeDqlArtifactSourceForAgent = async (
    source: string,
    metadata: {
      name?: string;
      path?: string;
      domain?: string;
      chartType?: string;
      /** Caller-owned trust presentation; tracing never infers it from SQL. */
      reviewRequired?: boolean;
      /** Same-snapshot physical relations admitted by the frozen Ask plan. */
      qualifiedSchemaContext?: AgentSchemaTable[];
      /**
       * Authoritative V2 governed-DQL closure.  This is host-only and is
       * populated from immutable candidate/path handles, not provider text.
       */
      askV2Closure?: {
        contextPack: LocalContextPack;
        candidateIds: string[];
        relationshipPathIds: string[];
        /** Host-only proof for compiled joins selected through V2 path handles. */
        assertRelationshipPaths?: (sql: string) => void;
      };
    } = {},
    invocationInput?: {
      question?: string;
      parameters?: Record<string, unknown>;
      parameterSources?: Record<string, 'policy' | 'explicit' | 'question' | 'prior_result' | 'surface' | 'default'>;
      rowLimit?: number;
    },
    executionConnection?: ConnectionConfig,
    executionConnectionName?: string,
  ): Promise<AgentResultPayload> => {
    // Everything from here to the executor call is DQL's OWN block compiler:
    // parse, parameter resolution, plan build, semantic compose. A failure in
    // any of it means DQL could not rebuild its artifact — the warehouse was
    // never contacted. Tagging the origin here stops the answer loop from
    // reporting these as "the generated SQL failed to execute".
    const invocation = withAnalyticalCompilationOrigin('bind', () => prepareBlockInvocation({
      source,
      parameters: invocationInput?.parameters,
      parameterSources: invocationInput?.parameterSources,
      question: invocationInput?.question,
      surface: 'ask_ai',
    }));
    if (invocation.errors.length > 0) {
      throw analyticalError(invocation.errors.join(' '), { origin: 'dql_compilation', stage: 'compile' });
    }
    if (invocation.unresolvedParameters.length > 0) {
      throw analyticalError(
        `I need values for: ${invocation.unresolvedParameters.join(', ')}.`,
        {
          origin: 'dql_compilation',
          stage: 'bind',
          code: 'unresolved_parameter',
          offending: { parameter: invocation.unresolvedParameters[0] },
        },
      );
    }
    const activeConnection = requireActiveConnection(executionConnection);
    const precompiledSemanticQuery = Boolean(extractBlockStudioSql(source));
    const tableMapping = !precompiledSemanticQuery
      ? await resolveSemanticTableMapping(
          executor,
          activeConnection,
          semanticLayer,
          projectRoot,
          executionConnectionName,
        )
      : undefined;
    const composeLayer = semanticLayer;
    const semanticCompose = composeLayer
      ? await withAnalyticalErrorOrigin(
          { origin: 'dql_compilation', stage: 'compile' },
          () => composeSemanticBlockSqlForRuntime(source, composeLayer, {
            driver: activeConnection.driver,
            tableMapping,
            projectRoot,
            projectConfig,
            detectedProvider: semanticDetectedProvider,
            parameters: invocation.values,
          }),
        )
      : null;
    const plan = withAnalyticalCompilationOrigin('compile', () => buildExecutionPlan(
      { id: `agent-${metadata.name ?? 'dql-artifact'}`, type: 'dql', source, title: metadata.name ?? 'DQL artifact' },
      {
        semanticLayer,
        driver: activeConnection.driver,
        tableMapping,
        parameters: invocation.values,
        semanticSql: semanticCompose?.sql ?? undefined,
      },
    ));
    if (!plan && !semanticCompose?.sql) {
      const semanticError = semanticCompose?.diagnostics.find((diagnostic) => diagnostic.severity === 'error')?.message;
      throw analyticalError(
        semanticError ?? `DQL artifact "${metadata.name ?? 'draft'}" produced no executable SQL.`,
        { origin: 'dql_compilation', stage: 'compile' },
      );
    }

    // A certified block is authored as DQL rather than warehouse-specific SQL.
    // When its source uses an unqualified leaf relation, bind it only if the
    // immutable context snapshot proves one unique physical relation.  Do not
    // reuse broad exploratory repairs here: certified execution may not alter
    // joins, aggregation, aliases, or any other frozen artifact semantics.
    const compiledSql = semanticCompose?.sql ?? plan!.sql;
    const qualificationRepairs: string[] = [];
    const executableSql = !semanticCompose?.sql && metadata.qualifiedSchemaContext?.length
      ? qualifyUnambiguousSqlRelationsFromSchema(
          compiledSql,
          metadata.qualifiedSchemaContext,
          qualificationRepairs,
          activeConnection.driver,
        )
      : compiledSql;

    if (metadata.askV2Closure) {
      const closureValidation = validateAuthorizedSqlReferences(executableSql, metadata.askV2Closure.contextPack, {
        ...(activeConnection.driver ? { dialect: activeConnection.driver } : {}),
        runtimeSchema: metadata.qualifiedSchemaContext,
        // The plan is frozen and host-authorized by the time it reaches here.
        // Re-asking "should we have clarified first?" can only refuse a query
        // whose identifiers this host already admitted.
        enforceGenerationReadiness: false,
      });
      if (!closureValidation.ok) {
        // The closure gate is the hardest failure in Ask to diagnose from a
        // trace, because the receipt records only the typed reason. This
        // opt-in dump names the offending relation/column and the column lists
        // the gate actually held, which is what tells a wide-warehouse false
        // rejection apart from a genuinely wrong query.
        if (process.env.DQL_DEBUG_EXECUTION_ERROR) {
          console.error('[DQL_DEBUG closure]', JSON.stringify({
            code: (closureValidation as { code?: string }).code,
            error: (closureValidation as { error?: string }).error,
            offending: (closureValidation as { offending?: unknown }).offending,
            referencedRelations: closureValidation.referencedRelations,
            allowed: metadata.askV2Closure.contextPack.allowedSqlContext.relations
              .map((relation) => ({ relation: relation.relation, completeness: relation.columnCompleteness, columnCount: relation.columns.length }))
              .slice(0, 6),
            runtimeSchema: (metadata.qualifiedSchemaContext ?? [])
              .map((table) => ({ relation: table.relation, completeness: table.columnCompleteness, columnCount: table.columns.length }))
              .slice(0, 6),
          }));
        }
        throw analyticalError('The governed DQL program referenced a relation or column outside its immutable V2 closure, so it was not executed.', {
          origin: 'governance_gate', stage: 'validation', code: 'unauthorized_sql',
        });
      }
      if (closureValidation.referencedRelations.length > 1 && metadata.askV2Closure.relationshipPathIds.length === 0) {
        throw analyticalError('A governed DQL program that joins multiple relations requires one admitted relationship-path handle, so it was not executed.', {
          origin: 'governance_gate', stage: 'validation', code: 'unauthorized_sql',
        });
      }
      metadata.askV2Closure.assertRelationshipPaths?.(executableSql);
    }

    const app = loadRuntimeApp(projectRoot, activePersonaAppId());
    const sourceDomain = metadata.domain ?? source.match(/\bdomain\s*=\s*"([^"]+)"/i)?.[1];
    assertAppAccess({ app, domain: sourceDomain ?? app?.domain, level: 'execute' });
    const pinnedSemanticCompile = semanticCompose?.sql
      ? compiledSemanticQueries.get(executionFingerprint(semanticCompose.sql))
      : undefined;
    const semanticExecutionHolder: {
      value: Awaited<ReturnType<typeof executeTargetBoundSemanticQuery>> | null;
    } = { value: null };
    const execution = await analyticalExecutionService.execute({
      sql: executableSql,
      subject: 'DQL artifact query',
      connection: activeConnection,
      // Preserve the existing contract: previewed Ask artifacts are explicitly
      // read-only and bounded; saved/manual DQL execution keeps its compiler-
      // governed behavior when no preview bound was requested.
      enforceReadOnly: invocationInput?.rowLimit !== undefined,
      rowLimit: invocationInput?.rowLimit,
      sqlParams: plan?.sqlParams,
      variables: { ...(plan?.variables ?? {}), ...invocation.values },
      executePrepared: async (preparation) => {
        return executePreparedArtifactTraceBoundary({
          preparedSql: preparation.executedSql,
          reviewRequired: metadata.reviewRequired ?? true,
          execute: async () => {
            if (pinnedSemanticCompile) {
              const semanticExecution = await executeTargetBoundSemanticQuery({
                executor,
                connection: activeConnection,
                projectRoot,
                plannedAdapter: pinnedSemanticCompile.engine,
                metricFlow: pinnedSemanticCompile.engine === 'metricflow-cli'
                  ? resolveMetricFlowTargetMetadata(projectRoot, projectConfig)
                  : undefined,
                compile: async () => pinnedSemanticCompile,
                prepareSql: () => ({ sql: preparation.executedSql, connection: preparation.connection }),
                rowBound: invocationInput?.rowLimit ?? pinnedSemanticCompile.effectiveRequest.limit,
              });
              if (semanticExecution) {
                semanticExecutionHolder.value = semanticExecution;
                return semanticExecution.result;
              }
            }
            return executor.executeQuery(
              preparation.executedSql,
              plan?.sqlParams ?? [],
              runtimeVariables({ ...(plan?.variables ?? {}), ...invocation.values }),
              preparation.connection,
            );
          }
        });
      },
    });
    const semanticExecution = semanticExecutionHolder.value;
    const { preparation, result: normalized } = execution;
    const executionSql = preparation.executedSql;
    const executionReceipt = createDqlArtifactExecutionReceipt(
      source,
      executionSql,
      invocation.values,
      normalized,
    );
    const executableArtifact: DqlExecutableArtifactV1 = {
      version: 1,
      kind: precompiledSemanticQuery || semanticCompose?.sql ? 'semantic_block' : 'sql_block',
      dqlFingerprint: executionFingerprint(source),
      sourceFingerprint: executionFingerprint(stableExecutionValue({
        name: metadata.name ?? null,
        path: metadata.path ?? null,
        domain: sourceDomain ?? null,
      })),
      compiledSqlFingerprint: executionFingerprint(executableSql ?? preparation.sourceSql),
      normalizedSqlFingerprint: executionFingerprint(preparation.decodedSql),
      parameterFingerprint: executionReceipt.parameterFingerprint,
      provenanceFingerprint: executionFingerprint(stableExecutionValue(invocation.resolvedParameters.map((parameter) => ({
        name: parameter.name,
        source: parameter.source,
      })))),
      targetFingerprint: targetGenerationFingerprint(activeConnection, executionConnectionName),
      snapshotFingerprint: executionFingerprint(projectSnapshot().snapshotId),
      planFingerprint: executionFingerprint(stableExecutionValue({
        sqlFingerprint: executionFingerprint(executableSql ?? preparation.sourceSql),
        parameterCount: plan?.sqlParams?.length ?? 0,
        variableNames: Object.keys(plan?.variables ?? {}).sort(),
        chartConfig: plan?.chartConfig ?? null,
      })),
      semanticAdapter: pinnedSemanticCompile?.engine ?? 'native',
      previewPolicy: invocationInput?.rowLimit === undefined
        ? { mode: 'compiler_governed' }
        : { mode: 'read_only_bounded', rowLimit: invocationInput.rowLimit },
      trustState: 'review_required',
      receipt: executionReceipt,
    };
    return {
      columns: normalized.columns,
      rows: normalized.rows,
      rowCount: normalized.rowCount,
      executionTime: normalized.executionTime,
      chartConfig: plan?.chartConfig ?? (metadata.chartType ? { chart: metadata.chartType } : undefined),
      sql: executionSql,
      ...(metadata.name ? { blockName: metadata.name } : {}),
      ...(metadata.path ? { blockPath: metadata.path } : {}),
      parameters: invocation.resolvedParameters,
      auditId: invocation.auditId,
      executionReceipt,
      executableArtifact,
      ...(semanticExecution ? {
        semanticExecutionReceipt: semanticExecution.executionReceipt,
        semanticTargetBinding: semanticExecution.targetBinding,
        semanticTrace: semanticExecution.semanticTrace,
      } : {}),
    };
  };

  const executeCertifiedBlockByNameForAgent = async (
    blockName: string,
    invocationInput?: CertifiedBlockInvocationInput,
    requireCertified = false,
    executionConnection?: ConnectionConfig,
    executionConnectionName?: string,
    qualifiedSchemaContext?: AgentSchemaTable[],
  ): Promise<AgentResultPayload> => {
    const manifest = buildManifest({ projectRoot });
    const block = manifest.blocks[blockName];
    if (!block) {
      throw new Error(`Matched block "${blockName}" is not present in the project manifest.`);
    }
    if (requireCertified && block.status !== 'certified') {
      throw new Error(`Block "${block.name}" is not certified and cannot be rerun as a certified answer.`);
    }
    const source = readFileSync(join(projectRoot, block.filePath), 'utf-8');
    const result = await executeDqlArtifactSourceForAgent(source, {
      name: block.name,
      path: block.filePath,
      domain: block.domain,
      chartType: block.chartType,
      reviewRequired: false,
      ...(qualifiedSchemaContext?.length ? { qualifiedSchemaContext } : {}),
    }, invocationInput, executionConnection, executionConnectionName);
    // Use the resolved invocation returned by the compiler, rather than only
    // caller-supplied values. This keeps an exact V2 certified execution
    // replayable and makes declared defaults visible as the applied inputs.
    const resolvedParameterValues = Object.fromEntries(
      (result.parameters ?? []).map((parameter) => [parameter.name, parameter.value]),
    );
    return {
      ...result,
      dqlArtifact: {
        kind: 'certified_block',
        name: block.name,
        source,
        sourcePath: block.filePath,
        persistence: 'saved',
        trustState: 'certified',
        compiledSql: result.sql,
        executionReceipt: result.executionReceipt,
        ...(result.executableArtifact ? {
          executableArtifact: { ...result.executableArtifact, kind: 'certified_block', trustState: 'certified' },
        } : {}),
        ...(invocationInput?.rowLimit ? { limit: invocationInput.rowLimit } : {}),
        ...(Object.keys(resolvedParameterValues).length > 0
          ? { parameterValues: resolvedParameterValues }
          : invocationInput?.parameters && Object.keys(invocationInput.parameters).length > 0
            ? { parameterValues: invocationInput.parameters }
          : {}),
      },
    };
  };

  const executeCertifiedBlockForAgent = async (
    node: KGNode,
    invocationInput?: CertifiedBlockInvocationInput,
    executionConnection?: ConnectionConfig,
    executionConnectionName?: string,
    qualifiedSchemaContext?: AgentSchemaTable[],
    requireCertified = false,
  ): Promise<AgentResultPayload> => {
    if (node.kind !== 'block') {
      throw new Error(`Certified ${node.kind} "${node.name}" is a navigation artifact and cannot be executed as a block.`);
    }
    return executeCertifiedBlockByNameForAgent(
      node.name || node.nodeId.replace(/^block:/, ''),
      invocationInput,
      requireCertified,
      executionConnection,
      executionConnectionName,
      qualifiedSchemaContext,
    );
  };

  // Secondary agent surfaces use this compatibility callback. Delegate to the
  // same artifact-first path as Ask so research/app/notebook execution cannot
  // silently reintroduce a raw-SQL result followed by a different DQL artifact.
  const executeGeneratedSqlForAgent = async (
    sql: string,
    artifact?: DqlArtifactReference,
  ): Promise<AgentResultPayload> => executeGeneratedArtifactForAgent(
    artifact?.name ?? 'AI-generated query',
    sql,
    artifact,
  );

  const executeArtifactReferenceForAgent = async (
    artifact: DqlArtifactReference,
    question: string,
    executionConnection?: ConnectionConfig,
    executionConnectionName?: string,
    askV2Closure?: {
      contextPack: LocalContextPack;
      candidateIds: string[];
      relationshipPathIds: string[];
      qualifiedSchemaContext: AgentSchemaTable[];
      assertRelationshipPaths?: (sql: string) => void;
    },
  ): Promise<AgentResultPayload> => {
    const invocation = prepareBlockInvocation({
      source: artifact.source,
      parameters: artifact.parameterValues,
      question,
      surface: 'ask_ai',
    });
    const result = await executeDqlArtifactSourceForAgent(
      artifact.source,
      {
        name: artifact.name,
        path: artifact.sourcePath,
        domain: artifact.source.match(/\bdomain\s*=\s*"([^"]+)"/i)?.[1],
        // Trust is owned by the route that froze this artifact. A governed
        // semantic artifact is not exploratory merely because it is not a
        // certified block. A frozen, inferred semantic substitution is the
        // narrow exception: it carries its explicit `review_required` marker
        // into the physical SQL span and returned result.
        reviewRequired: artifact.trustState === 'review_required',
        ...(askV2Closure ? {
          qualifiedSchemaContext: askV2Closure.qualifiedSchemaContext,
          askV2Closure: {
            contextPack: askV2Closure.contextPack,
            candidateIds: askV2Closure.candidateIds,
            relationshipPathIds: askV2Closure.relationshipPathIds,
            ...(askV2Closure.assertRelationshipPaths ? { assertRelationshipPaths: askV2Closure.assertRelationshipPaths } : {}),
          },
        } : {}),
      },
      {
        question,
        parameters: invocation.values,
        rowLimit: artifact.limit ?? 200,
      },
      executionConnection,
      executionConnectionName,
    );
    return {
      ...result,
      // Keep the execution result at the frozen plan's stricter trust state.
      // `canonicalPersistedTrustState` consumes this marker while the attached
      // DQL artifact keeps the same boundary for the card and Apply surface.
      ...(artifact.trustState === 'review_required' ? { trustState: 'review_required' as const } : {}),
      dqlArtifact: {
        ...artifact,
        ...(invocation.parameters.length > 0 ? { parameters: invocation.parameters } : {}),
        ...(Object.keys(invocation.values).length > 0 ? { parameterValues: invocation.values } : {}),
        compiledSql: result.sql,
        executionReceipt: result.executionReceipt,
        ...(result.executableArtifact ? { executableArtifact: result.executableArtifact } : {}),
      },
    };
  };

  /**
   * Build the reusable DQL artifact for an answer that HAS ALREADY EXECUTED,
   * and check that it recompiles.
   *
   * AGT-010 requires the attached artifact to be the one used for execution, so
   * that "Apply" cannot diverge from what Ask displayed. The old code satisfied
   * that invariant backwards: it made EXECUTION follow the artifact, routing the
   * model's SQL through `parameterizeSqlForDqlImport` → `candidateToDqlSource` →
   * the DQL parser → `processSQL` before running anything. Every one of those
   * stages could fail on SQL the warehouse would have accepted, and each failure
   * destroyed the whole answer.
   *
   * Now the executed string is the source of truth and the artifact is derived
   * from it. Building the artifact is a SAVE concern, so a failure here degrades
   * the artifact to review-required and never throws: the user still gets their
   * answer, and only "Save as block" is affected.
   */
  const buildVerifiedGeneratedArtifact = (
    question: string,
    sql: string,
    executedSql: string,
    seed: DqlArtifactReference | undefined,
    warnings: string[],
    resultColumns: string[] = [],
    dialect = 'duckdb',
  ): DqlArtifactReference | undefined => {
    // Which result columns the user may promote to a filter input. Decided here
    // because it needs a real dialect parse of the SQL that actually ran.
    const filterableColumns = resultColumns.length > 0
      ? filterableResultColumns(executedSql, resultColumns, dialect)
      : [];
    const withCandidates = <T extends DqlArtifactReference>(artifact: T): T => (
      filterableColumns.length > 0 ? { ...artifact, filterableColumns } : artifact
    );
    let artifact: DqlArtifactReference;
    try {
      artifact = generatedSqlArtifactContract(question, sql, seed);
    } catch (error) {
      warnings.push(`This answer could not be captured as a reusable DQL block: ${apiErrorMessage(error)}`);
      return undefined;
    }

    try {
      const invocation = prepareBlockInvocation({ source: artifact.source, question, surface: 'ask_ai' });
      const divergence = invocation.errors.length > 0
        ? invocation.errors.join(' ')
        : invocation.unresolvedParameters.length > 0
          ? `it still needs values for ${invocation.unresolvedParameters.join(', ')}`
          : undefined;
      if (divergence) {
        warnings.push(`The reusable DQL block for this answer needs review before reuse: ${divergence}`);
        // Keep the declared parameter contract even when the block cannot run
        // as-is. This branch is precisely "it still needs values for X", so the
        // parameter-input surface needs the list in order to ASK for them —
        // dropping it would leave the user a review-required block with no way
        // to see, or supply, what it wants.
        return withCandidates({
          ...artifact,
          trustState: 'review_required',
          compiledSql: executedSql,
          ...(invocation.parameters.length > 0 ? { parameters: invocation.parameters } : {}),
          ...(Object.keys(invocation.values).length > 0 ? { parameterValues: invocation.values } : {}),
        });
      }
      return withCandidates({
        ...artifact,
        compiledSql: executedSql,
        ...(invocation.parameters.length > 0 ? { parameters: invocation.parameters } : {}),
        ...(Object.keys(invocation.values).length > 0 ? { parameterValues: invocation.values } : {}),
      });
    } catch (error) {
      warnings.push(`The reusable DQL block for this answer needs review before reuse: ${apiErrorMessage(error)}`);
      return withCandidates({ ...artifact, trustState: 'review_required', compiledSql: executedSql });
    }
  };

  /**
   * Execute the model's SQL EXACTLY as validated — the same way a notebook cell
   * runs it. This is the fix for "the query Ask generated fails in Ask but runs
   * in the notebook": both paths now reach `executor.executeQuery` with the same
   * string, so the only remaining reasons to differ are the connection and the
   * governance gates, both of which report themselves honestly.
   */
  const executeGeneratedSqlDirect = async (
    question: string,
    sql: string,
    seed?: DqlArtifactReference,
    executionConnection?: ConnectionConfig,
    bindings?: {
      sqlParams?: SQLParamSpec[];
      variables?: Record<string, unknown>;
    },
    executionConnectionName?: string,
    agenticCapability?: AgenticSqlExecutionCapabilityV1,
    agenticScope?: SqlAuthorizationCheck,
    /**
     * Ask execution can outlive the runner's AsyncLocalStorage handoff when a
     * legacy adapter invokes the frozen compiler. Carry the server-owned
     * observer explicitly for that narrow path so the SQL boundary records
     * what actually happened rather than relying on an ambient context.
     */
    traceObserver?: AskTraceObserverV1,
  ): Promise<AgentResultPayload> => {
    const activeConnection = requireActiveConnection(executionConnection);
    const rowBound = clampAnalyticalRowBound(seed?.limit ?? 200);
    const trimmed = sql.trim().replace(/;\s*$/, '').trim();
    if (!trimmed) throw analyticalError('The generated SQL was empty.', { origin: 'host', stage: 'execute' });
    const bindingValue = {
      sqlParams: bindings?.sqlParams ?? [],
      variables: bindings?.variables ?? {},
    };
    if (agenticCapability) {
      // The proposal itself is immutable. A changed literal, comment, or
      // whitespace is drift here rather than a benign formatting change.
      const currentSnapshotId = projectSnapshot().snapshotId;
      let targetFingerprint: string | undefined;
      if (agenticCapability.targetFingerprint) {
        try {
          targetFingerprint = (await observeWarehouseTargetIdentity(executor, activeConnection)).identityFingerprint;
        } catch {
          throw analyticalError('DQL could not re-confirm the selected execution target, so the analyst-approved query was not run.', {
            origin: 'governance_gate', stage: 'execute', code: 'unauthorized_sql',
          });
        }
      }
      const capabilityVerdict = verifyAgenticSqlExecutionCapability(agenticCapability, sql, {
        ...agenticScope,
        bindings: bindingValue,
        snapshotId: currentSnapshotId,
        ...(targetFingerprint ? { targetFingerprint } : {}),
      });
      if (!capabilityVerdict.ok) {
        throw analyticalError(capabilityVerdict.reason ?? 'The analyst-approved SQL no longer matches this execution.', {
          origin: 'governance_gate', stage: 'execute', code: 'unauthorized_sql',
        });
      }
    }

    // RESOLVE FIRST, VALIDATE SECOND. Executing verbatim means executing the
    // statement the notebook would execute — and the notebook resolves
    // `@metric()` / `@dim()` refs and dbt macros before it runs anything.
    // Skipping that here made Ask fail on semantic refs and MetricFlow
    // (`metric_time`) queries the notebook runs fine, and validating the raw
    // model SQL first meant `source::` identities and macro-shaped text were
    // rejected before the step that would have resolved them ever ran.
    const semanticMapping = semanticLayer && hasStandaloneSemanticRef(trimmed)
      ? await resolveSemanticTableMapping(executor, activeConnection, semanticLayer, projectRoot)
      : undefined;
    const semantic = semanticLayer
      ? prepareSemanticSql(trimmed, semanticLayer, { tableMapping: semanticMapping })
      : { sql: trimmed, unresolvedRefs: [] as string[], semanticRefs: undefined };
    if (semantic.unresolvedRefs.length > 0) {
      throw analyticalError(
        `Unknown semantic reference${semantic.unresolvedRefs.length > 1 ? 's' : ''}: ${semantic.unresolvedRefs.join(', ')}`,
        { origin: 'dql_compilation', stage: 'compile', code: 'semantic_ref' },
      );
    }
    const app = loadRuntimeApp(projectRoot, activePersonaAppId());
    // Generated SQL is governed as 'uncategorized' unless its seed declares a
    // domain — the same value `generatedSqlArtifactContract` stamps into the
    // block source. Falling through to `app.domain` instead would evaluate the
    // policy against the app's OWN domain and could allow a query the previous
    // release denied; a governance boundary must not move as a side effect.
    const sourceDomain = seed?.source?.match(/\bdomain\s*=\s*"([^"]+)"/i)?.[1] ?? 'uncategorized';
    assertAppAccess({ app, domain: sourceDomain, level: 'execute' });

    const semanticExecutionHolder: {
      value: Awaited<ReturnType<typeof executeTargetBoundSemanticQuery>> | null;
    } = { value: null };
    const execution = await analyticalExecutionService.execute({
      sql: semantic.sql,
      subject: 'Generated SQL',
      connection: activeConnection,
      enforceReadOnly: true,
      rowLimit: rowBound,
      sqlParams: bindings?.sqlParams,
      variables: bindings?.variables,
      semanticRefs: semantic.semanticRefs,
      executePrepared: async (preparation) => {
        // Both the native executor and the target-bound semantic adapter can
        // reach the warehouse from this callback. Admit the exact prepared
        // bytes before either path so a matching cached semantic compile cannot
        // bypass the generated proposal's capability.
        return executePreparedAgenticSqlBoundary({
          capability: agenticCapability,
          preparedSql: preparation.executedSql,
          bindings: bindingValue,
          scope: {
            ...agenticScope,
            snapshotId: projectSnapshot().snapshotId,
            ...(agenticCapability ? { targetFingerprint: agenticCapability.targetFingerprint } : {}),
          },
          ...(traceObserver ? { traceObserver } : {}),
          execute: async () => {
            // A semantic query the loop already compiled (MetricFlow / dbt
            // Cloud) must execute through its pinned target binding, not as
            // loose SQL.
            const pinnedSemanticCompile = compiledSemanticQueries.get(executionFingerprint(preparation.preparedSql))
              ?? compiledSemanticQueries.get(executionFingerprint(trimmed));
            if (pinnedSemanticCompile) {
              const semanticExecution = await executeTargetBoundSemanticQuery({
                executor,
                connection: activeConnection,
                projectRoot,
                plannedAdapter: pinnedSemanticCompile.engine,
                metricFlow: pinnedSemanticCompile.engine === 'metricflow-cli'
                  ? resolveMetricFlowTargetMetadata(projectRoot, projectConfig)
                  : undefined,
                compile: async () => pinnedSemanticCompile,
                prepareSql: () => ({ sql: preparation.executedSql, connection: preparation.connection }),
                rowBound,
              });
              if (semanticExecution) {
                semanticExecutionHolder.value = semanticExecution;
                return semanticExecution.result;
              }
            }
            return executor.executeQuery(
              preparation.executedSql,
              bindings?.sqlParams ?? [],
              runtimeVariables(bindings?.variables ?? {}),
              preparation.connection,
              // Where no LIMIT could be written into the statement (SQL
              // Server has none), the connector stops reading one row past
              // the bound instead of fetching the whole result.
              preparation.rowBound?.outcome === 'skipped' ? { maxRows: rowBound + 1 } : undefined,
            );
          }
        });
      },
    });
    const semanticExecution = semanticExecutionHolder.value;
    const { preparation, result: normalized } = execution;
    const bounded = preparation.rowBound!;
    // The authoritative bound. `buildRowBoundedSql` may legitimately decline to
    // touch the statement, and only one of 15 drivers honours a maxRows hint, so
    // the host is the only layer correctness may depend on.
    const truncated = normalized.rows.length > rowBound;
    const rows = truncated ? normalized.rows.slice(0, rowBound) : normalized.rows;

    const warnings: string[] = [];
    const artifact = buildVerifiedGeneratedArtifact(
      question, trimmed, bounded.sql, seed, warnings, normalized.columns, activeConnection.driver,
    );
    const receiptSource = artifact?.source ?? trimmed;
    const executionBindings = bindings && ((bindings.sqlParams?.length ?? 0) > 0 || Object.keys(bindings.variables ?? {}).length > 0)
      ? { sqlParams: bindings.sqlParams ?? [], variables: bindings.variables ?? {} }
      : {};
    const executionReceipt = createDqlArtifactExecutionReceipt(
      receiptSource,
      bounded.sql,
      executionBindings,
      { columns: normalized.columns, rows, rowCount: rows.length },
    );
    const executableArtifact: DqlExecutableArtifactV1 = {
      version: 1,
      kind: 'sql_block',
      dqlFingerprint: executionFingerprint(receiptSource),
      sourceFingerprint: executionFingerprint(stableExecutionValue({
        name: artifact?.name ?? seed?.name ?? null,
        path: artifact?.sourcePath ?? seed?.sourcePath ?? null,
      })),
      compiledSqlFingerprint: executionFingerprint(semantic.sql),
      normalizedSqlFingerprint: executionFingerprint(preparation.decodedSql),
      parameterFingerprint: executionReceipt.parameterFingerprint,
      provenanceFingerprint: executionFingerprint(stableExecutionValue({
        sqlParamCount: bindings?.sqlParams?.length ?? 0,
        variableNames: Object.keys(bindings?.variables ?? {}).sort(),
      })),
      targetFingerprint: targetGenerationFingerprint(activeConnection, executionConnectionName),
      snapshotFingerprint: executionFingerprint(projectSnapshot().snapshotId),
      planFingerprint: executionFingerprint(stableExecutionValue({
        compiledSqlFingerprint: executionFingerprint(semantic.sql),
        executedSqlFingerprint: executionFingerprint(bounded.sql),
        rowBound,
      })),
      semanticAdapter: semanticExecution?.targetBinding.adapterId ?? 'native',
      previewPolicy: { mode: 'read_only_bounded', rowLimit: rowBound },
      trustState: 'review_required',
      receipt: executionReceipt,
    };
    return {
      columns: normalized.columns,
      rows,
      rowCount: rows.length,
      executionTime: normalized.executionTime,
      sql: bounded.sql,
      ...(truncated ? { truncated: true } : {}),
      ...(artifact ? { dqlArtifact: { ...artifact, limit: rowBound, executionReceipt, executableArtifact } } : {}),
      ...(warnings.length > 0 ? { validationWarnings: warnings } : {}),
      executionReceipt,
      executableArtifact,
    };
  };

  const executeGeneratedArtifactForAgent = async (
    question: string,
    sql: string,
    seed?: DqlArtifactReference,
    executionConnection?: ConnectionConfig,
    executionConnectionName?: string,
    agenticCapability?: AgenticSqlExecutionCapabilityV1,
    agenticScope?: SqlAuthorizationCheck,
    traceObserver?: AskTraceObserverV1,
  ): Promise<AgentResultPayload> => {
    // A seed that is already a certified/saved artifact keeps the DQL-first
    // path: there the `.dql` source IS the contract, and its parameters and
    // semantic refs must be compiled, not bypassed.
    if (seed && seed.kind !== 'sql_block') {
      if (agenticCapability) {
        throw analyticalError('The analyst-approved SQL cannot be redirected through a saved artifact.', {
          origin: 'governance_gate', stage: 'execute', code: 'unauthorized_sql',
        });
      }
      return executeArtifactReferenceForAgent(
        { ...seed, limit: seed.limit ?? 200 },
        question,
        executionConnection,
        executionConnectionName,
      );
    }
    return executeGeneratedSqlDirect(
      question,
      sql,
      seed,
      executionConnection,
      undefined,
      executionConnectionName,
      agenticCapability,
      agenticScope,
      traceObserver,
    );
  };

  /**
   * EXP-001: execution host for the deliberately narrow non-governed lane.
   * It does not reinterpret dbt lineage or shared names as relationship proof.
   * Instead it validates the generated equality predicates against bounded
   * samples, records the result as exploratory evidence, then executes the
   * existing read-only 200-row preview. Any malformed, broad, or unsupported
   * candidate remains review-required and is not executed automatically.
   */
  const executeExploratoryCandidate = async (
    candidate: NonNullable<AgentAnswer['exploratoryCandidate']>,
    schemaContext: AgentSchemaTable[] = [],
    question = '',
    requestedTopN?: number,
    executionConnection?: ConnectionConfig,
  ): Promise<{
    result?: AgentResultPayload;
    proofs: Array<{ summary: string }>;
    sql: string;
    repairs: string[];
    error?: string;
    warehouseFailure?: WarehouseSqlFailureV1;
  }> => {
    const activeConnection = requireActiveConnection(executionConnection);
    const failed = (
      message: string,
      sql: string,
      repairs: string[],
      proofs: Array<{ summary: string }> = [],
      code = 'exploratory_validation_failed',
    ) => ({
      proofs,
      sql,
      repairs,
      error: message,
      warehouseFailure: normalizeWarehouseSqlFailure(
        analyticalError(message, {
          origin: 'governance_gate',
          stage: 'validation',
          code,
        }),
        activeConnection.driver,
      ),
    });

    let normalizedCandidateSql: string;
    try {
      normalizedCandidateSql = (await prepareAnalyticalExecutionSql({
        sql: candidate.sql,
        subject: question || 'this exploratory query',
        executor,
        connection: activeConnection,
        projectRoot,
        projectConfig,
        enforceReadOnly: true,
      })).preparedSql;
    } catch (error) {
      const failure = normalizeWarehouseSqlFailure(error, activeConnection.driver);
      return {
        proofs: [],
        sql: candidate.sql,
        repairs: [],
        error: failure.redactedMessage,
        warehouseFailure: failure,
      };
    }

    const preflight = repairExploratorySqlBeforeExecution(normalizedCandidateSql, schemaContext, question, activeConnection.driver);
    const boundedSql = applyRequestedTopNToExploratorySql(preflight.sql, requestedTopN);
    const repairs = boundedSql === preflight.sql
      ? [...preflight.repairs]
      : [...preflight.repairs, `Applied the requested overall top-${requestedTopN} bound before exploratory execution.`];
    // This is the only deterministic SQL rewrite point on the exploratory
    // execution path. Record it here, rather than inferring a successful SQL
    // repair later from a generic engine retry event.
    if (repairs.length > 0) {
      const trace = activeAskTraceObserver();
      const repairPayload = {
        kind: 'sql' as const,
        execution: {
          version: 1 as const,
          sqlFingerprint: runtimeTraceFingerprint(boundedSql),
          planFingerprint: runtimeTraceFingerprint(normalizedCandidateSql),
          reviewRequired: true,
        },
      };
      const repairSpan = trace?.startSpan({
        name: 'sql.repair',
        stage: 'sql',
        reasonCode: 'repair_attempted',
        payload: repairPayload,
      });
      trace?.finishSpan(repairSpan, {
        outcome: 'ok',
        reasonCode: 'repair_attempted',
        payload: repairPayload,
      });
    }
    if (preflight.blockedReason) {
      return failed(preflight.blockedReason, boundedSql, repairs, [], 'exploratory_preflight_blocked');
    }
    const analysis = analyzeSqlReferences(boundedSql, activeConnection.driver);
    if (!analysis.parsed && sqlMayContainJoin(boundedSql)) {
      return failed(
        'DQL could not parse the exploratory SQL to validate its join predicates. Nothing was sent to the warehouse.',
        boundedSql,
        repairs,
        [],
        'exploratory_join_parse_failed',
      );
    }
    if (!analysis.parsed) {
      repairs.push('The local DQL parser could not inspect this join-free statement; warehouse read-only execution will provide the authoritative syntax check.');
    }
    const probeableJoins = probeableExploratoryJoins(
      analysis.parsed ? analysis.joins : [],
      analysis.parsed ? analysis.ctes : [],
      analysis.parsed ? analysis.derivedRelations : [],
    );

    // A normal customer → order → order-item → product question needs three
    // joins. Keep the lane bounded, but do not reject this common dbt-star path
    // solely because the old two-join demo limit was too small. CTE-internal
    // joins are counted physically (they appear in analysis.joins with their
    // physical endpoints); joins ON a CTE are restructuring, not new paths.
    if (probeableJoins.length > 4) {
      return failed('This exploratory query has more than four joins and requires an analyst to review the relationship path.', boundedSql, repairs, [], 'exploratory_join_limit');
    }
    if (probeableJoins.some((join) => !join.leftRelation || !join.rightRelation)) {
      return failed('This exploratory query has a join endpoint DQL could not resolve for bounded validation.', boundedSql, repairs, [], 'exploratory_join_unresolved');
    }

    // Structural binding: when the candidate carries a declared draft join path,
    // every SQL join must ride one of its edges on the declared key pair. A join
    // outside the declared path (or on different keys) is not executed — it is a
    // review-required modeling question, not a runtime guess.
    const declaredEdges = candidate.exploratoryPath?.edges ?? [];
    const joinEdges = new Map<number, (typeof declaredEdges)[number]>();
    if (declaredEdges.length > 0) {
      for (const [index, join] of probeableJoins.entries()) {
        const edge = declaredEdges.find((value) =>
          declaredExploratoryRelationMatches(join.leftRelation!, value.fromRelation) && declaredExploratoryRelationMatches(join.rightRelation!, value.toRelation)
          || declaredExploratoryRelationMatches(join.leftRelation!, value.toRelation) && declaredExploratoryRelationMatches(join.rightRelation!, value.fromRelation));
        if (!edge) {
          return failed(
            `The join between ${join.leftRelation} and ${join.rightRelation} is not part of the declared relationship path, so DQL did not execute it. Declare the relationship in the DQL model to enable it.`,
            boundedSql,
            repairs,
            [],
            'undeclared_relationship',
          );
        }
        const keyMatches = edge.keys.some((key) =>
          exploratoryColumnsMatch(join.leftColumn, key.from) && exploratoryColumnsMatch(join.rightColumn, key.to)
          || exploratoryColumnsMatch(join.leftColumn, key.to) && exploratoryColumnsMatch(join.rightColumn, key.from));
        if (!keyMatches) {
          return failed(
            `The join ${join.leftColumn} = ${join.rightColumn} uses different keys than relationship "${edge.relationshipId}" declares (${edge.keys.map((key) => `${key.from}=${key.to}`).join(', ')}). Review the declared keys before executing.`,
            boundedSql,
            repairs,
            [],
            'relationship_key_mismatch',
          );
        }
        joinEdges.set(index, edge);
      }
      const exercised = new Set([...joinEdges.values()].map((edge) => edge.relationshipId));
      for (const edge of declaredEdges) {
        if (!exercised.has(edge.relationshipId)) {
          repairs.push(`Declared relationship "${edge.relationshipId}" was not exercised by this query.`);
        }
      }
    }

    if (analysis.parsed && probeableJoins.length < analysis.joins.length) {
      repairs.push(`Skipped join probes for ${analysis.joins.length - probeableJoins.length} join(s) on derived (CTE) relations; the final query execution validates them.`);
    }

    const proofs: Array<{ summary: string }> = [];
    try {
      for (const [index, join] of probeableJoins.entries()) {
        const proofSql = buildExploratoryJoinProbeSql({
          leftRelation: join.leftRelation!,
          leftColumn: join.leftColumn,
          rightRelation: join.rightRelation!,
          rightColumn: join.rightColumn,
        });
        const prepared = prepareLocalExecution(proofSql, activeConnection, projectRoot, projectConfig);
        const raw = await executor.executeQuery(prepared.sql, [], runtimeVariables({}), prepared.connection);
        proofs.push({ summary: summarizeExploratoryJoinProbe(raw.rows, join.leftRelation!, join.leftColumn, join.rightRelation!, join.rightColumn) });
        // Gating (not observational): a structural contradiction between the
        // UNFILTERED key overlap and the declared relationship stops automatic
        // execution. A legitimately empty *filtered* business result is still an
        // answer — these gates only inspect the raw key samples.
        const contradiction = exploratoryProbeContradiction(raw.rows, join, joinEdges.get(index));
        if (contradiction) {
          return failed(contradiction, boundedSql, repairs, proofs, 'relationship_probe_contradiction');
        }
      }
      const result = await executeGeneratedArtifactForAgent(
        question,
        boundedSql,
        undefined,
        activeConnection,
      );
      return { result, proofs, sql: boundedSql, repairs };
    } catch (error) {
      const failure = normalizeWarehouseSqlFailure(error, activeConnection.driver);
      return {
        proofs,
        sql: boundedSql,
        repairs,
        error: failure.redactedMessage,
        warehouseFailure: failure,
      };
    }
  };

  /**
   * Ask the warehouse whether specific named relations exist, AFTER the cached
   * catalog has already missed them.
   *
   * `getSchemaContextForAgent` deliberately returns nothing on a lexical miss —
   * "a lexical miss is not permission to rescan every visible schema". That is
   * right for BULK retrieval, but it also meant a relation the model named
   * explicitly, and that the notebook queries without complaint, was refused as
   * "outside the inspected metadata context" without the warehouse ever being
   * asked. A point lookup of up to four named `(schema, table)` pairs is not a
   * rescan.
   *
   * The payoff is honesty as much as recall: after this probe, a miss is
   * evidence. The refusal can say the relation is not visible to this
   * connection, rather than only that DQL had not looked at it.
   */
  const probeNamedRelationsForAgent = async (
    relations: string[],
    probeConnection?: ConnectionConfig,
    verifyExecutionSchema = false,
  ): Promise<GroundingExpansionResult | undefined> => {
    const probeTarget = probeConnection ?? connection;
    if (!probeTarget) return undefined;
    // Named relation discovery remains behind the operator's live-grounding
    // switch. Executable schema verification is different: it is a bounded,
    // read-only metadata point lookup for relations already selected from dbt,
    // and never reads row values or mutates the active target.
    if (!verifyExecutionSchema && resolveAgentRuntimeValueGrounding(projectConfig).mode !== 'safe_automatic') return undefined;
    const sql = buildNamedRelationProbeSql(relations);
    if (!sql) return undefined;

    const prepared = prepareLocalExecution(sql, probeTarget, projectRoot, projectConfig);
    const result = await executor.executeQuery(prepared.sql, [], runtimeVariables({}), prepared.connection);
    const rows = normalizeQueryResult(result).rows as Array<Record<string, unknown>>;
    if (rows.length === 0) return undefined;

    const tables = buildAgentSchemaContext('', rows, { includeUnscored: true, limit: 8 });
    if (tables.length === 0) return undefined;
    return {
      relations: tables.map((table) => ({
        relation: table.relation,
        name: table.name,
        // Provenance is explicit: these columns came from a live lookup, not
        // from the immutable snapshot.
        source: 'scoped live probe',
        columns: table.columns.map((column) => ({ name: column.name, type: column.type })),
        columnCompleteness: 'complete' as const,
      })),
      schemaContext: tables.map((table) => ({
        relation: table.relation,
        schema: table.schema,
        name: table.name,
        columns: table.columns,
      })) as RuntimeSchemaTable[],
      notes: tables.map((table) => `${table.relation} resolved by a scoped live probe`),
    };
  };

  const getSchemaContextForAgent = async (
    question: string,
    preparedContextPack?: LocalContextPack,
    executionConnection?: ConnectionConfig,
    executionConnectionName?: string,
  ): Promise<AgentSchemaTable[]> => {
    const schemaConnection = executionConnection ?? connection;
    const scanRuntimeSchema = async (): Promise<{ ranked: AgentSchemaTable[]; snapshot: AgentSchemaTable[] }> => {
      if (!schemaConnection) return { ranked: [], snapshot: [] };
      const result = await executor.executePositional(
        buildRuntimeSchemaSearchSql(question),
        [],
        schemaConnection,
        { maxRows: 600, maxBytes: 2 * 1024 * 1024, batchSize: 200, deadlineMs: 30_000 },
      );
      return {
        ranked: buildAgentSchemaContext(question, result.rows),
        snapshot: buildAgentSchemaContext(question, result.rows, { includeUnscored: true, limit: 100 }),
      };
    };
    const catalogContext = await buildAgentSchemaContextFromCatalog(projectRoot, question, preparedContextPack).catch(() => []);
    const activeScope = schemaConnection
      ? optionalActiveConnectionMetadataScope(
          projectRoot,
          projectConfig,
          schemaConnection,
          executionConnectionName ?? projectConfig.defaultConnectionName ?? 'default',
        )
      : null;
    const activeRuntimeSnapshot = latestRuntimeSchemaSnapshotForProject(
      projectRoot,
      executionConnectionName,
    );
    const hasActivatedMetadataGeneration = Boolean(
      activeScope
      && activeRuntimeSnapshot?.scopeFingerprint === activeScope.scopeFingerprint
      && activeRuntimeSnapshot.status !== 'stale',
    );
    const valueGrounding = resolveAgentRuntimeValueGrounding(projectConfig);
    if (catalogContext.length > 0) {
      if (!schemaConnection) return catalogContext;
      // dbt metadata is the semantic authority, but generated SQL must use the
      // physical columns visible on THIS execution target. Verify only the few
      // question-ranked relations with a bounded information_schema point lookup;
      // this is read-only and never mutates DuckDB, Snowflake, or any other target.
      let executionSchema = catalogContext;
      try {
        const live = await probeNamedRelationsForAgent(
          catalogContext.slice(0, 4).map((table) => table.relation),
          schemaConnection,
          true,
        );
        if (live?.schemaContext?.length) {
          executionSchema = reconcileAgentSchemaContextWithLive(
            catalogContext,
            live.schemaContext as AgentSchemaTable[],
          );
        }
      } catch {
        // Live verification is additive. Existing metadata remains available if
        // the connection cannot expose information_schema to this user.
      }
      // The immutable dbt/DQL snapshot owns schema discovery. Live verification
      // only confirms those named relations; row values remain governed by the
      // separate allowlisted grounding policy below.
      if (valueGrounding.mode !== 'safe_automatic') return executionSchema;
      const enriched = await enrichAgentSchemaContextWithValueMatches(
        question,
        executionSchema,
        executor,
        schemaConnection,
        valueGrounding.searchSafeColumns,
      );
      return enriched;
    }

    // An activated, scope-qualified warehouse generation is the complete warm
    // metadata authority. A lexical miss is not permission to rescan every
    // visible schema for each question; the governed planner may clarify or the
    // user may explicitly refresh the selected scope.
    if (hasActivatedMetadataGeneration) return [];

    if (!schemaConnection) return [];
    try {
      const schemaContext = await scanRuntimeSchema();
      const enriched = valueGrounding.mode === 'safe_automatic'
        ? await enrichAgentSchemaContextWithValueMatches(
          question,
          schemaContext.ranked,
          executor,
          schemaConnection,
          valueGrounding.searchSafeColumns,
        )
        : schemaContext.ranked;
      recordAgentRuntimeSchemaSnapshot(
        projectRoot,
        schemaContext.snapshot,
        'question-scoped information_schema search',
        executionConnectionName,
      );
      return enriched;
    } catch {
      return [];
    }
  };

  type BoundedSqlRepairResult = {
    result: AgentResultPayload;
    repairedSql: string;
    repairMode: 'deterministic' | 'ai';
    firstFailure?: WarehouseSqlFailureV1;
    providerEgressReceipts: ProviderEgressReceiptV1[];
    providerRoundTrips: number;
    rewrites: Array<{ from: string; to: string }>;
  };

  type BoundedDqlRepairResult = BoundedSqlRepairResult & {
    repairedSource: string;
    sqlParams: SQLParamSpec[];
    variables: Record<string, unknown>;
  };

  /**
   * CTX-008: the project's authored relationships, as plain join facts for the
   * relations a bounded repair can actually see.
   *
   * A repair prompt previously carried only the failure, the failed SQL, and a
   * bare relation list, so a repair could silently replace a correct governed
   * join with a shared-column guess. This is grounding only — it never widens
   * the relation scope and never authorizes a join (`REL-002` still governs
   * execution); trust is labelled so a draft edge reads as a draft.
   */
  const governedJoinFactsForRelations = (relations: string[]): string[] => {
    const modeling = (() => {
      try { return projectSnapshot().manifest.modeling; } catch { return undefined; }
    })();
    if (!modeling) return [];
    const manifest = projectSnapshot().manifest;
    const normalize = (value: string) => value.toLowerCase().replace(/"/g, '').split('.').at(-1) ?? value.toLowerCase();
    const visible = new Set(relations.map(normalize));
    const relationFor = (entityKey: string): string | undefined => {
      const entity = modeling.entities[entityKey];
      if (!entity) return undefined;
      const node = manifest.dbtProvenance?.nodes[entity.dbtUniqueId];
      return node?.relation ?? node?.name;
    };
    return Object.values(modeling.relationships).flatMap((relationship) => {
      const from = relationFor(relationship.from);
      const to = relationFor(relationship.to);
      if (!from || !to || !visible.has(normalize(from)) || !visible.has(normalize(to))) return [];
      const keys = relationship.keys.map((key) => `${from}.${key.from} = ${to}.${key.to}`).join(' AND ');
      const trust = relationship.automaticJoinAllowed ? 'certified' : `${relationship.status} (review required)`;
      const meaning = [relationship.verb, relationship.description].filter(Boolean).join(' — ');
      return [`${keys} (${relationship.cardinality}, fanout ${relationship.fanout}, ${trust}${meaning ? `; ${meaning}` : ''})`];
    }).slice(0, 12);
  };

  const boundedRepairError = (
    message: string,
    status: number,
    warehouseFailure?: WarehouseSqlFailureV1,
  ): Error & { status: number; warehouseFailure?: WarehouseSqlFailureV1 } => Object.assign(
    new Error(message),
    { status, ...(warehouseFailure ? { warehouseFailure } : {}) },
  );

  /**
   * Shared one-attempt SQL repair for Ask and Notebook. It never creates a
   * conversation, writes a DQL file, changes targets, or promotes trust.
   */
  const executeBoundedSqlRepair = async (input: {
    question: string;
    sourceSql: string;
    targetConnection: ConnectionConfig;
    targetConnectionName?: string;
    sqlParams?: SQLParamSpec[];
    variables?: Record<string, unknown>;
  }): Promise<BoundedSqlRepairResult> => {
    let sourceSql = input.sourceSql;
    let rewrites: Array<{ from: string; to: string }> = [];
    if (internalRelationIdsInSql(sourceSql).length > 0) {
      const normalizedSource = await prepareAnalyticalExecutionSql({
        sql: sourceSql,
        subject: 'Repair source SQL',
        executor,
        connection: input.targetConnection,
        projectRoot,
        projectConfig,
        enforceReadOnly: true,
      });
      sourceSql = normalizedSource.decodedSql;
      rewrites = normalizedSource.rewrites;
    }
    const sourceSignature = buildSqlAnalyticalSignature(sourceSql, input.targetConnection.driver);
    if (!sourceSignature) {
      throw boundedRepairError('DQL could not prove an immutable analytical signature for the source SQL. Repair it manually.', 409);
    }
    let result: AgentResultPayload | undefined;
    let repairedSql = sourceSql;
    let repairMode: 'deterministic' | 'ai' = 'deterministic';
    let firstFailure: WarehouseSqlFailureV1 | undefined;
    const providerEgressReceipts: ProviderEgressReceiptV1[] = [];
    let providerRoundTrips = 0;
    try {
      result = await executeGeneratedSqlDirect(
        input.question,
        sourceSql,
        undefined,
        input.targetConnection,
        { sqlParams: input.sqlParams, variables: input.variables },
        input.targetConnectionName,
      );
    } catch (error) {
      firstFailure = normalizeWarehouseSqlFailure(error, input.targetConnection.driver);
    }

    if (!result) {
      if (firstFailure?.retryDisposition !== 'model_repair') {
        throw boundedRepairError(
          firstFailure?.redactedMessage ?? 'The deterministic repair did not produce an executable query.',
          422,
          firstFailure,
        );
      }

      const provider = await createBlockStudioAssistProvider(projectRoot);
      if (!provider) {
        throw boundedRepairError('Configure an available AI provider in Settings to repair this query.', 409);
      }
      let schemaContext: AgentSchemaTable[];
      try {
        schemaContext = await getSchemaContextForAgent(
          input.question,
          undefined,
          input.targetConnection,
          input.targetConnectionName,
        );
      } catch (error) {
        const failure = normalizeWarehouseSqlFailure(error, input.targetConnection.driver);
        throw boundedRepairError(failure.redactedMessage, 422, failure);
      }
      const boundedSchema = markProviderMetadataArray(schemaContext.slice(0, 16).map((table) => ({
        relation: table.relation,
        columns: markProviderMetadataArray(table.columns.slice(0, 40).map((column) => ({ name: column.name, type: column.type }))),
      })));
      // CTX-008: a repair that re-derives joins from column names can undo a
      // join the original query got right. Give it the authored key pairs.
      const governedJoins = markProviderMetadataArray(
        governedJoinFactsForRelations(schemaContext.slice(0, 16).map((table) => table.relation)),
      );
      const repairPayload = {
        question: input.question,
        driver: input.targetConnection.driver,
        failure: firstFailure.redactedMessage,
        sql: sourceSql,
        parameters: input.sqlParams ? markProviderMetadataArray(input.sqlParams.map((parameter) => ({
          name: parameter.name,
          placeholder: `$${parameter.position}`,
        }))) : undefined,
        schema: boundedSchema,
        ...(governedJoins.length ? { governedJoins } : {}),
      };
      const repairMessages = [
        {
          role: 'system' as const,
          content: [
            'Repair one failed read-only analytical SQL statement.',
            'Return exactly one JSON object in a ```json fence with keys summary, sql, viz, outputs.',
            'Preserve the requested grain, filters, output columns, and aggregation semantics.',
            input.sqlParams?.length
              ? 'Preserve every positional parameter placeholder exactly; do not add, remove, or renumber placeholders.'
              : '',
            'Use only relations and columns present in the supplied schema context.',
            'When governedJoins is present, join on those exact key pairs rather than inferring a join from column names.',
            'Never emit internal DQL relation identities such as source::, model::, seed::, or snapshot::.',
            'Do not add writes, DDL, multiple statements, or commentary outside the JSON fence.',
          ].join(' '),
        },
        {
          role: 'user' as const,
          content: JSON.stringify(repairPayload),
        },
      ];
      const repairEnvelope = prepareProviderWireEnvelopeForDispatch(provider.name, { messages: repairMessages }) as {
        messages: Parameters<AgentProvider['generate']>[0];
      };
      assertProviderPayloadAllowed(repairEnvelope, {
        allowResultRows: false,
        maxResultRows: 0,
        purpose: 'repair_sql',
      });
      const repairDispatchTrace = createProviderDispatchTrace({
        observer: activeAskTraceObserver(),
        phase: 'repair',
        purpose: 'repair_sql',
        admit: (event) => {
          const envelope = prepareProviderWireEnvelopeForDispatch(provider.name, event.envelope);
          assertProviderPayloadAllowed(envelope, {
            allowResultRows: false,
            maxResultRows: 0,
            purpose: 'repair_sql',
          });
          providerRoundTrips += 1;
          providerEgressReceipts.push(createProviderDispatchEgressReceipt({
            purpose: 'repair_sql',
            dispatchPhase: 'repair',
            provider: provider.name,
            permittedCategories: ['instructions', 'question', 'schema_metadata', 'governed_context'],
            optIn: false,
            envelope,
          }));
          return envelope;
        },
      });
      let raw: string;
      try {
        raw = await provider.generate(repairEnvelope.messages, {
          maxTokens: 1200,
          temperature: 0,
          // This is the one parent-bound repair transport. A provider retry
          // would be a second repair attempt, so the host never authorizes it.
          maxProviderDispatches: 1,
          ...repairDispatchTrace.options,
        });
        repairDispatchTrace.settle('ok');
      } catch (error) {
        repairDispatchTrace.settle('error', error);
        throw Object.assign(
          boundedRepairError('The AI provider could not complete this repair. Check Provider Settings and retry.', 502),
          {
            providerDispatchEvidence: {
              providerEgressReceipts: [...providerEgressReceipts],
              providerRoundTrips,
              toolCalls: 0,
              sqlExecutions: 0,
              repairs: 1,
              fallbackReason: 'repair_provider_error',
            } satisfies ProviderDispatchTerminalEvidence,
          },
        );
      }
      const proposal = parseProposal(raw);
      if (!proposal.sql?.trim()) {
        throw boundedRepairError('The AI repair did not return an executable SQL statement.', 422);
      }
      repairedSql = proposal.sql.trim();
      const requiredPlaceholders = (input.sqlParams ?? []).map((parameter) => `$${parameter.position}`);
      if (requiredPlaceholders.some((placeholder) => !new RegExp(`${placeholder.replace('$', '\\$')}\\b`).test(repairedSql))) {
        throw boundedRepairError('The repair changed this cell\'s parameter contract, so DQL stopped it before execution.', 422);
      }
      const repairedSignature = buildSqlAnalyticalSignature(repairedSql, input.targetConnection.driver);
      if (!repairedSignature || stableExecutionValue(repairedSignature) !== stableExecutionValue(sourceSignature)) {
        throw boundedRepairError('The provider repair changed or could not prove the immutable analytical plan, so DQL stopped before execution.', 409);
      }
      const aggregationProof = buildAggregationSafetyProof(repairedSql, undefined, input.targetConnection.driver);
      if (aggregationProof.status !== 'safe') {
        throw boundedRepairError(`The repaired SQL lacks complete aggregation-safety evidence (${aggregationProof.issueCodes.join(', ')}). Repair it manually.`, 409);
      }
      repairMode = 'ai';
      try {
        result = await executeGeneratedSqlDirect(
          input.question,
          repairedSql,
          undefined,
          input.targetConnection,
          { sqlParams: input.sqlParams, variables: input.variables },
          input.targetConnectionName,
        );
      } catch (error) {
        const failure = normalizeWarehouseSqlFailure(error, input.targetConnection.driver);
        throw boundedRepairError(failure.redactedMessage, 422, failure);
      }
    }

    // Keep preview-only row bounds out of editable notebook source. The one
    // deterministic source rewrite we do persist is decoding internal graph
    // identities, because those can never execute as warehouse SQL.
    if (internalRelationIdsInSql(repairedSql).length > 0) {
      const normalizedSource = await prepareAnalyticalExecutionSql({
        sql: repairedSql,
        subject: 'Repaired SQL',
        executor,
        connection: input.targetConnection,
        projectRoot,
        projectConfig,
        enforceReadOnly: true,
      });
      repairedSql = normalizedSource.decodedSql;
      rewrites.push(...normalizedSource.rewrites);
    }

    return { result, repairedSql, repairMode, firstFailure, providerEgressReceipts, providerRoundTrips, rewrites };
  };

  /**
   * Repair a DQL wrapper that cannot compile far enough to expose executable
   * SQL. This is the DQL-side half of the same bounded repair contract used by
   * Ask and Notebook: one provider call, one block, identical parameters, one
   * read-only execution, and the exact target selected by the failed run.
   */
  const executeBoundedDqlRepair = async (input: {
    question: string;
    source: string;
    failure: string;
    targetConnection: ConnectionConfig;
    targetConnectionName?: string;
    parameters?: Record<string, unknown>;
    artifactName?: string;
  }): Promise<BoundedDqlRepairResult> => {
    const provider = await createBlockStudioAssistProvider(projectRoot);
    if (!provider) {
      throw boundedRepairError('Configure an available AI provider in Settings to repair this DQL draft.', 409);
    }
    const providerEgressReceipts: ProviderEgressReceiptV1[] = [];
    let providerRoundTrips = 0;

    let schemaContext: AgentSchemaTable[];
    try {
      // Include source identifiers in retrieval so a terse cell title still
      // resolves the physical dbt relations and live target columns it uses.
      schemaContext = await getSchemaContextForAgent(
        `${input.question}\n${input.source.slice(0, 6_000)}`,
        undefined,
        input.targetConnection,
        input.targetConnectionName,
      );
    } catch (error) {
      const failure = normalizeWarehouseSqlFailure(error, input.targetConnection.driver);
      throw boundedRepairError(failure.redactedMessage, 422, failure);
    }

    const boundedSchema = schemaContext.slice(0, 16).map((table) => ({
      relation: table.relation,
      columns: table.columns.slice(0, 40).map((column) => ({ name: column.name, type: column.type })),
    }));
    // CTX-008: same as the SQL repair — keep authored joins out of the guesser.
    const governedJoins = governedJoinFactsForRelations(schemaContext.slice(0, 16).map((table) => table.relation));
    let raw: string;
    try {
      raw = await provider.generate([
        {
          role: 'system',
          content: [
            'Repair one malformed executable DQL custom block and its embedded read-only SQL.',
            'Return only one JSON object with exactly one key named dql. Do not use markdown.',
            'The DQL shape is: block "Name" { type = "custom" params { name: type = default } query = """SELECT ...""" visualization { ... } tests { ... } }.',
            'Preserve the block name, business fields, visualization, tests, requested grain, filters, output columns, and aggregation semantics.',
            'Preserve every declared parameter and every ${parameter} interpolation exactly. Do not add or remove parameters.',
            'Use only relations and columns present in the supplied schema context.',
            'When governedJoins is present, join on those exact key pairs rather than inferring a join from column names.',
            'Never emit internal relation identities such as source::, model::, seed::, or snapshot::.',
            'Return exactly one custom block. Never certify it, bind a saved block, add writes, DDL, or multiple SQL statements.',
          ].join(' '),
        },
        {
          role: 'user',
          content: JSON.stringify({
            question: input.question,
            driver: input.targetConnection.driver,
            failure: input.failure.slice(0, 2_000),
            dql: input.source.slice(0, 40_000),
            parameters: input.parameters ?? {},
            schema: boundedSchema,
            ...(governedJoins.length ? { governedJoins } : {}),
          }),
        },
      ], {
        maxTokens: 2400,
        temperature: 0,
        maxProviderDispatches: 2,
        onProviderDispatch: (event) => {
          const envelope = prepareProviderWireEnvelopeForDispatch(provider.name, event.envelope);
          assertProviderPayloadAllowed(envelope, {
            allowResultRows: false,
            maxResultRows: 0,
            purpose: 'repair_sql',
          });
          providerRoundTrips += 1;
          providerEgressReceipts.push(createProviderDispatchEgressReceipt({
            purpose: 'repair_sql',
            dispatchPhase: 'repair',
            provider: provider.name,
            permittedCategories: ['instructions', 'question', 'schema_metadata', 'governed_context'],
            optIn: false,
            envelope,
          }));
          return envelope;
        },
      });
    } catch {
      throw Object.assign(
        boundedRepairError('The AI provider could not complete this DQL repair. Check Provider Settings and retry.', 502),
        {
          providerDispatchEvidence: {
            providerEgressReceipts: [...providerEgressReceipts],
            providerRoundTrips,
            toolCalls: 0,
            sqlExecutions: 0,
            repairs: 1,
            fallbackReason: 'repair_provider_error',
          } satisfies ProviderDispatchTerminalEvidence,
        },
      );
    }

    let repairedSource: string | undefined;
    try {
      const parsed = parseFirstJsonObject(raw);
      repairedSource = parsed && typeof parsed === 'object' && !Array.isArray(parsed)
        && typeof (parsed as Record<string, unknown>).dql === 'string'
        ? String((parsed as Record<string, unknown>).dql).trim()
        : undefined;
    } catch {
      repairedSource = undefined;
    }
    if (!repairedSource) {
      throw boundedRepairError('The AI repair did not return a complete DQL block.', 422);
    }
    if (repairedSource.length > 50_000) {
      throw boundedRepairError('The repaired DQL exceeded the safe editable-draft size limit.', 422);
    }
    if (/^\s*@block\(/i.test(repairedSource) || /\btype\s*=\s*"semantic"/i.test(repairedSource)) {
      throw boundedRepairError('The repair changed this editable custom block into a governed reference or semantic block.', 422);
    }
    if (!/\bstatus\s*=\s*"certified"/i.test(input.source)
      && /\bstatus\s*=\s*"certified"/i.test(repairedSource)) {
      throw boundedRepairError('The repair attempted to certify an AI-edited block, so DQL stopped it.', 422);
    }

    const beforeParameters = dqlRepairParameterContract(input.source);
    const afterParameters = dqlRepairParameterContract(repairedSource);
    if (beforeParameters.join('|') !== afterParameters.join('|')) {
      throw boundedRepairError('The repair changed this block\'s parameter contract, so DQL stopped it before execution.', 422);
    }

    let invocation: ReturnType<typeof prepareBlockInvocation>;
    let plan: ReturnType<typeof buildExecutionPlan>;
    try {
      // The source label is echoed into parse errors, which reach the user.
      // `<bounded-dql-repair>` is an internal artifact id and tells them nothing;
      // it appeared verbatim in a reported failure card.
      const program = new Parser(repairedSource, 'repaired query').parse();
      const blocks = program.statements.filter((statement) => statement.kind === NodeKind.BlockDecl);
      if (blocks.length !== 1 || program.statements.length !== 1) {
        throw new Error('The repaired source must contain exactly one DQL block.');
      }
      const block = blocks[0];
      if (block.kind !== NodeKind.BlockDecl || block.blockType !== 'custom') {
        throw new Error('The repaired source must remain a custom DQL block.');
      }
      invocation = prepareBlockInvocation({
        source: repairedSource,
        parameters: input.parameters,
        question: input.question,
        surface: 'notebook',
      });
      if (invocation.errors.length) throw new Error(invocation.errors.join(' '));
      if (invocation.unresolvedParameters.length) {
        throw new Error(`Provide required parameters before retrying: ${invocation.unresolvedParameters.join(', ')}.`);
      }
      plan = buildExecutionPlan({
        id: 'bounded-dql-repair',
        type: 'dql',
        source: repairedSource,
        title: input.artifactName,
      }, {
        semanticLayer,
        driver: input.targetConnection.driver,
        parameters: invocation.values,
      });
      if (!plan?.sql?.trim()) throw new Error('The repaired DQL did not compile to SQL.');
    } catch (error) {
      throw boundedRepairError(
        `The repaired DQL did not compile safely: ${error instanceof Error ? error.message : String(error)}`,
        422,
      );
    }

    const seed: DqlArtifactReference = {
      kind: 'sql_block',
      source: repairedSource,
      name: input.artifactName ?? plan.title,
      persistence: 'transient',
      trustState: 'review_required',
      compiledSql: plan.sql,
      ...(invocation.parameters.length ? { parameters: invocation.parameters } : {}),
      ...(Object.keys(invocation.values).length ? { parameterValues: invocation.values } : {}),
    };
    let result: AgentResultPayload;
    try {
      result = await executeGeneratedSqlDirect(
        input.question,
        plan.sql,
        seed,
        input.targetConnection,
        { sqlParams: plan.sqlParams, variables: { ...plan.variables, ...invocation.values } },
      );
    } catch (error) {
      const failure = normalizeWarehouseSqlFailure(error, input.targetConnection.driver);
      throw boundedRepairError(failure.redactedMessage, 422, failure);
    }

    result = {
      ...result,
      dqlArtifact: {
        ...(result.dqlArtifact ?? seed),
        source: repairedSource,
        compiledSql: result.sql ?? plan.sql,
        trustState: 'review_required',
        persistence: 'transient',
        ...(result.executionReceipt ? { executionReceipt: result.executionReceipt } : {}),
      },
    };
    return {
      result,
      repairedSql: plan.sql,
      repairedSource,
      repairMode: 'ai',
      providerEgressReceipts,
      providerRoundTrips,
      rewrites: [],
      sqlParams: plan.sqlParams,
      variables: { ...plan.variables, ...invocation.values },
    };
  };

  /**
   * App proposal parity with Ask/Notebook repair. The first governed attempt is
   * retained unchanged. Only an execution failure with retained read-only SQL
   * may spend the shared one-attempt repair budget, on the same connection.
   * The repaired candidate is still exploratory and review-required.
   */
  const generateAppBuildAnswerWithRepair = async (
    question: string,
    appContext?: AppContextEnvelopeV1,
  ): Promise<AppBuildGeneratedAnswer> => {
    const request: AgentRunRequest = {
      question,
      audience: 'stakeholder',
      workspaceContext: appContext
        ? { surface: 'app_builder', appContext }
        : { surface: 'app_builder' },
    };
    const answer = await runGovernedAgentAnswerForRun(request);
    const sourceSql = answer.proposedSql?.trim() || answer.sql?.trim();
    const hasExecutionFailure = agentAnswerHasExecutionFailure(answer)
      || Boolean(answer.warehouseFailure)
      || Boolean(answer.analyticalFailure);
    if (answer.result || !sourceSql || !hasExecutionFailure) return answer;

    const attemptedAt = new Date().toISOString();
    const originalFailure = answer.warehouseFailure?.redactedMessage
      ?? answer.executionError
      ?? 'The generated query did not execute.';
    const originalSqlFingerprint = `sha256:${createHash('sha256').update(sourceSql).digest('hex')}`;
    const failedTrace = (message: string): AppExecutionRepairTrace => ({
      version: 1,
      status: 'failed',
      source: 'query_generator',
      attemptedAt,
      originalFailure,
      originalSqlFingerprint,
      approvalEligible: false,
      message,
    });

    if (
      !analyticalFailureAllowsDeterministicRetry(answer.warehouseFailure)
      || !analyticalFailureAllowsAppRepair(answer.analyticalFailure)
    ) {
      return {
        ...answer,
        appBuilderRepair: failedTrace('This failure needs an access, policy, or connection decision and was not sent to AI repair.'),
      };
    }

    try {
      const targetConnection = await resolveAgentRunExecutionConnection(request);
      const targetConnectionName = request.executionTarget?.target === 'connection'
        ? request.executionTarget.connectionName
        : request.executionTarget?.target === 'local'
          ? 'local'
          : projectConfig.defaultConnectionName;
      const repaired = await executeBoundedSqlRepair({
        question,
        sourceSql,
        targetConnection,
        targetConnectionName,
      });
      const repair: AppExecutionRepairTrace = {
        version: 1,
        status: 'repaired',
        source: 'query_generator',
        mode: repaired.repairMode,
        attemptedAt,
        originalFailure,
        originalSqlFingerprint,
        repairedSqlFingerprint: `sha256:${createHash('sha256').update(repaired.repairedSql).digest('hex')}`,
        approvalEligible: false,
        message: `${repaired.repairMode === 'ai' ? 'AI' : 'Deterministic'} repair executed successfully on the same data target. Review the repaired query before adding it to the private App draft.`,
      };
      return {
        ...answer,
        result: repaired.result,
        proposedSql: repaired.repairedSql,
        sql: repaired.repairedSql,
        executionError: undefined,
        warehouseFailure: undefined,
        analyticalFailure: undefined,
        validationWarnings: [
          ...(answer.validationWarnings ?? []),
          repair.message,
        ],
        appBuilderRepair: repair,
      };
    } catch (error) {
      return {
        ...answer,
        appBuilderRepair: failedTrace(
          error instanceof Error
            ? `The bounded repair could not complete: ${error.message}`
            : 'The bounded repair could not complete.',
        ),
      };
    }
  };

  const repairFailedAppTileExecution = async (input: {
    source: 'semantic_query' | 'draft_analysis' | 'certified_block' | 'review_block';
    question: string;
    sourceSql?: string;
    sourceDql?: string;
    artifactName?: string;
    error: unknown;
    targetConnection?: ConnectionConfig;
    targetConnectionName?: string;
    sqlParams?: SQLParamSpec[];
    variables?: Record<string, unknown>;
  }): Promise<
    | { ok: true; result: AgentResultPayload; repairedSql: string; repairedDql?: string; repair: AppExecutionRepairTrace }
    | { ok: false; repair: AppExecutionRepairTrace }
  > => {
    const attemptedAt = new Date().toISOString();
    const driver = input.targetConnection?.driver ?? connection?.driver ?? 'duckdb';
    const failure = normalizeWarehouseSqlFailure(input.error, driver);
    const originalFailure = failure.redactedMessage;
    const originalSqlFingerprint = input.sourceSql
      ? `sha256:${createHash('sha256').update(input.sourceSql).digest('hex')}`
      : undefined;
    const failed = (message: string): { ok: false; repair: AppExecutionRepairTrace } => ({
      ok: false,
      repair: {
        version: 1,
        status: 'failed',
        source: input.source,
        attemptedAt,
        originalFailure,
        ...(originalSqlFingerprint ? { originalSqlFingerprint } : {}),
        approvalEligible: false,
        message,
      },
    });
    if (!input.targetConnection) {
      return failed('Configure the original data target before retrying this App tile.');
    }
    if (!input.sourceSql?.trim() && input.sourceDql?.trim()) {
      try {
        const repaired = await executeBoundedDqlRepair({
          question: input.question,
          source: input.sourceDql,
          failure: originalFailure,
          targetConnection: input.targetConnection,
          targetConnectionName: input.targetConnectionName,
          parameters: input.variables,
          artifactName: input.artifactName,
        });
        const repair: AppExecutionRepairTrace = {
          version: 1,
          status: 'repaired',
          source: input.source,
          mode: repaired.repairMode,
          attemptedAt,
          originalFailure,
          repairedSqlFingerprint: `sha256:${createHash('sha256').update(repaired.repairedSql).digest('hex')}`,
          approvalEligible: false,
          message: `${repaired.repairMode === 'ai' ? 'AI' : 'Deterministic'} DQL repair executed successfully on the same data target. The App result remains review-required and the source file was not changed.`,
        };
        return {
          ok: true,
          result: repaired.result,
          repairedSql: repaired.repairedSql,
          repairedDql: repaired.repairedSource,
          repair,
        };
      } catch (error) {
        return failed(error instanceof Error
          ? `The bounded DQL repair could not complete: ${error.message}`
          : 'The bounded DQL repair could not complete.');
      }
    }
    if (!input.sourceSql?.trim()) {
      return failed('DQL retained the failure, but no read-only SQL or editable DQL was available for bounded repair.');
    }
    if (!analyticalFailureAllowsDeterministicRetry(failure)) {
      return failed('This failure needs an access, policy, or connection decision and was not sent to AI repair.');
    }
    try {
      const repaired = await executeBoundedSqlRepair({
        question: input.question,
        sourceSql: input.sourceSql,
        targetConnection: input.targetConnection,
        targetConnectionName: input.targetConnectionName,
        sqlParams: input.sqlParams,
        variables: input.variables,
      });
      const repair: AppExecutionRepairTrace = {
        version: 1,
        status: 'repaired',
        source: input.source,
        mode: repaired.repairMode,
        attemptedAt,
        originalFailure,
        ...(originalSqlFingerprint ? { originalSqlFingerprint } : {}),
        repairedSqlFingerprint: `sha256:${createHash('sha256').update(repaired.repairedSql).digest('hex')}`,
        approvalEligible: false,
        message: `${repaired.repairMode === 'ai' ? 'AI' : 'Deterministic'} repair executed successfully on the same data target. The result remains review-required.`,
      };
      return { ok: true, result: repaired.result, repairedSql: repaired.repairedSql, repair };
    } catch (error) {
      return failed(error instanceof Error
        ? `The bounded repair could not complete: ${error.message}`
        : 'The bounded repair could not complete.');
    }
  };

  const generateInvestigationSqlForApp = async (input: AppCopilotResearchAgentInput): Promise<{
    sql?: string;
    answer?: string;
    result?: AgentResultPayload;
    analysisPlan?: unknown;
    evidence?: unknown;
    citations?: unknown[];
    suggestedViz?: string;
    executionError?: string;
    providerUsed?: string;
  }> => {
    const request = buildAppCopilotResearchAgentRequest(input);
    // AGT-007 / AGT-022: App Copilot keeps its server-owned App evidence
    // adapter, while routing the actual investigation through the uniform
    // snapshot, retrieval, trust, execution, and bounded-repair orchestration.
    const governedAnswer = await runGovernedAgentAnswerForRun(request, undefined, 'research');

    return {
      sql: input.mode === 'memo_only' ? undefined : governedAnswer.proposedSql ?? governedAnswer.sql,
      answer: governedAnswer.answer ?? governedAnswer.text,
      result: governedAnswer.result,
      analysisPlan: governedAnswer.analysisPlan,
      evidence: governedAnswer.evidence,
      citations: governedAnswer.citations,
      suggestedViz: governedAnswer.suggestedViz,
      executionError: governedAnswer.executionError,
      providerUsed: governedAnswer.providerUsed,
    };
  };

  const openNotebookResearchStorage = () => new LocalNotebookResearchStorage(defaultNotebookResearchDbPath(projectRoot));
  const notebookResearchStorageUnavailableMessage = 'Notebook research storage is unavailable because the local SQLite native bindings are not installed for this Node.js runtime.';
  const notebookResearchNextActionFilters: NotebookResearchNextActionFilter[] = [
    'fix_blockers',
    'review_sql',
    'review_context',
    'run_preview',
    'reuse_existing',
    'create_dql_draft',
    'open_certification',
    'complete_review',
    'continue_review',
  ];
  const isNotebookResearchStorageUnavailable = (error: unknown): boolean => {
    const message = error instanceof Error ? error.message : String(error);
    return /better[-_]sqlite3/i.test(message) || /Could not locate the bindings file/i.test(message);
  };
  const emptyNotebookResearchNextActionCounts = (): Record<NotebookResearchNextActionFilter, number> => Object.fromEntries(
    notebookResearchNextActionFilters.map((action) => [action, 0]),
  ) as Record<NotebookResearchNextActionFilter, number>;
  const emptyNotebookResearchListPage = (input: { limit?: number; offset?: number } = {}): NotebookResearchRunListResult => ({
    runs: [],
    total: 0,
    domains: [],
    owners: [],
    intents: [],
    notebooks: [],
    counts: {
      total: 0,
      ready: 0,
      needsReview: 0,
      dqlDrafts: 0,
      errors: 0,
      reuseExisting: 0,
      extendExisting: 0,
      replacements: 0,
      createNew: 0,
      draftReady: 0,
      certificationReady: 0,
      blocked: 0,
      staleOpen: 0,
      expiredOpen: 0,
      sourceLinked: 0,
      nextActions: emptyNotebookResearchNextActionCounts(),
    },
    groupCounts: {
      domains: 0,
      owners: 0,
      intents: 0,
      notebooks: 0,
    },
    reviewMetrics: {
      totalReviewCount: 0,
      openReviewCount: 0,
      terminalReviewCount: 0,
      draftCreatedCount: 0,
      certifiedCount: 0,
      completedCount: 0,
      rejectedCount: 0,
      draftCreationRate: null,
      certifyConversionRate: null,
      medianOpenReviewAgeMs: null,
      medianTimeToDraftMs: null,
      medianTimeToCertificationMs: null,
      medianTimeToTerminalMs: null,
    },
    limit: input.limit,
    offset: input.offset ?? 0,
  });
  const emptyNotebookResearchDiagnostics = (): NotebookResearchDiagnostics => ({
    counts: {
      totalRuns: 0,
      activeRuns: 0,
      closedRuns: 0,
      notebooks: 0,
      domains: 0,
      owners: 0,
      sourceLinkedRuns: 0,
    },
    health: {
      staleOpenRuns: 0,
      expiredOpenRuns: 0,
      staleThresholdDays: 7,
      expiredThresholdDays: 30,
    },
    search: {
      indexed: false,
      indexRows: 0,
      stale: false,
    },
    updatedAt: {},
    limits: {
      pageSize: 50,
      maxPageSize: 500,
      sourceCoverageLimit: 10_000,
      seedCellLimit: 1000,
    },
    warnings: [notebookResearchStorageUnavailableMessage],
  });

  const runNotebookResearch = async (
    storage: LocalNotebookResearchStorage,
    run: NotebookResearchRun,
    input: {
      domain?: string;
      owner?: string;
      sourceCellFingerprint?: string;
      question?: string;
      intent?: NotebookResearchIntent;
      context?: unknown;
      generatedSql?: string;
      reviewedSql?: string;
      dqlArtifact?: NotebookResearchDqlArtifact;
      executionConnection?: ConnectionConfig;
      executionConnectionName?: string;
      signal?: AbortSignal;
      baselineSql?: string;
      baselineDqlArtifact?: NotebookResearchDqlArtifact;
      baselineRunId?: string;
      /**
       * Explicit Research child branches arrive here only after the shared Ask
       * router froze their own qualified plan and the governed answer runner
       * completed (or honestly refused) that plan.  This sentinel prevents the
       * generic Notebook Research fallback below from reopening a legacy raw
       * provider/SQL route for a branch that already has an authoritative Ask
       * decision.
       */
      authoritativeBranch?: {
        answer: AgentAnswer;
        routeDecision: IntentDecision;
      };
    } = {},
  ): Promise<NotebookResearchRun> => {
    // A fair-share branch signal is separate from the root run signal. Check it
    // at each durable boundary so an overrun cannot later overwrite the
    // timeout/skipped receipt the parent has already recorded.
    const throwIfResearchSignalAborted = () => {
      if (!input.signal?.aborted) return;
      throw input.signal.reason ?? new DOMException('The Research branch deadline elapsed.', 'TimeoutError');
    };
    throwIfResearchSignalAborted();
    const question = notebookResearchString(input.question) || run.question;
    const domain = notebookResearchString(input.domain) ?? run.domain;
    const owner = notebookResearchString(input.owner) ?? run.owner;
    const sourceCellFingerprint = notebookResearchString(input.sourceCellFingerprint) ?? run.sourceCellFingerprint;
    const intent = input.intent ?? run.intent;
    const context = input.context === undefined ? run.context : input.context;
    let generatedSql = notebookResearchString(input.generatedSql) ?? run.generatedSql;
    let reviewedSql = notebookResearchString(input.reviewedSql) ?? run.reviewedSql;
    let dqlArtifact = normalizeDqlArtifactReference(input.dqlArtifact) ?? run.dqlArtifact;
    const baselineSql = notebookResearchString(input.baselineSql);
    const baselineDqlArtifact = normalizeDqlArtifactReference(input.baselineDqlArtifact);
    let usedBaselineFallback = false;
    const startedAt = new Date().toISOString();
    storage.updateRun(run.id, {
      domain,
      owner,
      sourceCellFingerprint,
      question,
      intent,
      context,
      generatedSql,
      reviewedSql,
      dqlArtifact,
      status: 'running',
      reviewStatus: 'needs_review',
      error: '',
    });

    try {
      throwIfResearchSignalAborted();
      // An explicit Research child has already retrieved, interpreted, and
      // frozen its own authoritative Ask plan before it reaches this durable
      // Notebook record. Rebuilding a broad Notebook context pack here is
      // both duplicate work and a fairness bug: it can consume the child's
      // entire branch window *after* a safe SQL result already exists. Keep a
      // deliberately small receipt projection instead. It is reporting-only;
      // execution remains bound to the child RAP supplied above.
      const contextPack = input.authoritativeBranch
        ? {
            id: '',
            routeDecision: input.authoritativeBranch.routeDecision,
            evidenceRoles: [],
            warnings: [],
            retrievalDiagnostics: { selectedEvidence: [] },
          } as unknown as LocalContextPack
        : await buildLocalContextPack(projectRoot, {
            question,
            mode: 'question',
            surface: 'notebook',
            selectedContext: {
              ...notebookResearchSelectedContext(run, context),
              domain,
              owner,
              intent,
              researchPattern: notebookResearchIntentPattern(intent),
            },
            strictness: 'exploratory',
            limit: 160,
          }).catch((error) => {
            const message = error instanceof Error ? error.message : String(error);
            return {
              id: '',
              routeDecision: undefined,
              evidenceRoles: [],
              warnings: [`Context pack failed: ${message}`],
              retrievalDiagnostics: { selectedEvidence: [] },
            } as unknown as LocalContextPack;
          });
      throwIfResearchSignalAborted();

      let governedAnswer: AgentAnswer | undefined = input.authoritativeBranch?.answer;
      let providerError: string | undefined;
      const generationWarnings: string[] = [];
      if (!generatedSql && !reviewedSql && !input.authoritativeBranch) {
        const governedResearch = await resolveGovernedAnswerRunner(projectRoot);
        const resolvedProvider = governedResearch?.provider ?? null;
        if (!resolvedProvider) {
          generationWarnings.push('No AI provider is configured. Metadata context was saved as a research plan; paste SQL or configure an AI provider to generate candidate SQL.');
        } else {
          const researchSignal = input.signal ?? new AbortController().signal;
          try {
            throwIfResearchSignalAborted();
            // Notebook research generates its candidate through the Ask
            // pipeline: interpreted once, prepared on every governed tier,
            // proven before rows are shown, review-required until promoted.
            governedAnswer = await runGovernedAgentAnswerForRun({
              question,
              requestedMode: 'ask',
              signal: researchSignal,
              analysisDepth: 'deep',
              workspaceContext: { surface: 'notebook_research', notebookPath: run.notebookPath, ...(run.sourceCellId ? { sourceCellId: run.sourceCellId } : {}), ...(domain ? { domain } : {}), ...(owner ? { owner } : {}), intent, researchPattern: notebookResearchIntentPattern(intent) },
            } as AgentRunRequest, undefined, 'generated_answer');
            throwIfResearchSignalAborted();
          } catch (error) {
            rethrowIfCancelled(error, input.signal);
            providerError = error instanceof Error ? error.message : String(error);
          }
          if (!governedAnswer) {
            generationWarnings.push(`AI SQL generation did not return a governed answer. Metadata context was saved for review.${providerError ? ` ${providerError}` : ''}`);
          } else {
            dqlArtifact = normalizeDqlArtifactReference(governedAnswer.dqlArtifact) ?? dqlArtifact;
            generatedSql = notebookResearchString(governedAnswer.proposedSql) ?? notebookResearchString(governedAnswer.sql);
            if (!generatedSql && !dqlArtifact) {
              generationWarnings.push('AI returned a governed answer without SQL. Metadata context was saved; add reviewed SQL before DQL promotion.');
            }
          }
        }
      }

      const deeperCompositionFailed = !governedAnswer
        || governedAnswer.kind === 'no_answer'
        || agentAnswerHasExecutionFailure(governedAnswer)
        || Boolean(governedAnswer.analyticalFailure)
        || (!governedAnswer.result && !generatedSql && !dqlArtifact);
      // A root baseline is an execution receipt for its own analytical tuple,
      // not a reusable SQL authority for every Research hypothesis. Explicit
      // Research children always carry their own router-frozen RAP, so they
      // must never borrow this generic Notebook fallback.
      if (!input.authoritativeBranch && !reviewedSql && baselineSql && deeperCompositionFailed) {
        const failure = governedAnswer?.executionError
          ?? governedAnswer?.analyticalFailure?.message
          ?? governedAnswer?.answer
          ?? governedAnswer?.text
          ?? providerError;
        generatedSql = baselineSql;
        dqlArtifact = baselineDqlArtifact ?? dqlArtifact;
        usedBaselineFallback = true;
        generationWarnings.push([
          'The deeper composition did not produce a safer executable query, so DQL kept and revalidated the successful Ask baseline on the same data target.',
          failure ? `Research detail: ${failure}` : '',
        ].filter(Boolean).join(' '));
      }

      const sqlForPreview = reviewedSql || generatedSql;
      const warnings = [
        ...(contextPack.warnings ?? []),
        ...(governedAnswer?.validationWarnings ?? []),
        ...generationWarnings,
      ].filter(Boolean);
      let resultPreview: ReturnType<typeof normalizeQueryResult> | undefined;
      let previewError: string | undefined;
      if (!usedBaselineFallback && governedAnswer?.result?.rows && !reviewedSql) {
        throwIfResearchSignalAborted();
        resultPreview = normalizeNotebookAgentResult(governedAnswer.result);
      } else if (sqlForPreview && !input.authoritativeBranch) {
        try {
          throwIfResearchSignalAborted();
          const previewSql = buildAgentPreviewSql(sqlForPreview);
          const previewStart = Date.now();
          resultPreview = await executeLocalSqlForStoredResult(previewSql, input.executionConnection);
          throwIfResearchSignalAborted();
          recordNotebookQueryRun(projectRoot, {
            notebookPath: run.notebookPath,
            cellId: run.sourceCellId,
            cellName: run.sourceCellName,
            researchRunId: run.id,
            source: reviewedSql ? 'notebook_research_reviewed_sql' : 'notebook_research_ai_sql',
            status: 'success',
            rowCount: resultPreview.rowCount ?? resultPreview.rows.length,
            durationMs: Date.now() - previewStart,
            sql: sqlForPreview,
            contextPackId: contextPack.id,
          });
        } catch (error) {
          previewError = error instanceof Error ? error.message : String(error);
          recordNotebookQueryRun(projectRoot, {
            notebookPath: run.notebookPath,
            cellId: run.sourceCellId,
            cellName: run.sourceCellName,
            researchRunId: run.id,
            source: reviewedSql ? 'notebook_research_reviewed_sql' : 'notebook_research_ai_sql',
            status: 'error',
            errorCode: previewError,
            sql: sqlForPreview,
            contextPackId: contextPack.id,
          });
        }
      }

      const routeDecision = input.authoritativeBranch?.routeDecision
        ?? notebookResearchRouteDecisionForRun(run, contextPack.routeDecision, sqlForPreview);
      const display = resultPreview
        ? recommendVisualization(projectRoot, {
            prompt: question,
            resultSchema: resultPreview.columns,
            rowSample: resultPreview.rows.slice(0, 25),
            defaultVisualization: governedAnswer?.suggestedViz,
          })
        : undefined;
      const evidence = {
        trustStatus: {
          label: usedBaselineFallback
            ? 'Successful Ask baseline · revalidated on the same target'
            : governedAnswer?.trustLabel
              ?? (reviewedSql ? 'Reviewed notebook SQL' : generatedSql ? 'AI-generated research SQL' : dqlArtifact ? 'AI-generated DQL artifact' : 'Metadata-grounded research plan'),
          reviewRequired: true,
        },
        contextPackId: contextPack.id,
        routeDecision,
        selectedEvidence: contextPack.evidenceRoles?.slice(0, 24) ?? [],
        evidenceRoles: contextPack.evidenceRoles?.slice(0, 24) ?? [],
        evidenceSummaries: contextPack.evidenceSummaries?.slice(0, 16) ?? [],
        allowedSqlContext: {
          relations: (contextPack.allowedSqlContext?.relations ?? []).slice(0, 24).map((relation) => ({
            relation: relation.relation,
            name: relation.name,
            source: relation.source,
            columns: relation.columns.slice(0, 32).map((column) => {
              if (typeof column === 'string') return column;
              if (column && typeof column === 'object' && typeof (column as { name?: unknown }).name === 'string') {
                return String((column as { name: unknown }).name);
              }
              return String(column);
            }),
          })),
          sourceBlockSql: contextPack.allowedSqlContext?.sourceBlockSql?.slice(0, 12) ?? [],
        },
        missingContext: contextPack.missingContext?.slice(0, 16) ?? [],
        warnings: contextPack.warnings?.slice(0, 16) ?? [],
        retrievalDiagnostics: contextPack.retrievalDiagnostics,
        agentEvidence: governedAnswer?.evidence,
        analysisPlan: governedAnswer?.analysisPlan,
        citations: [
          ...(contextPack.citations ?? []),
          ...(governedAnswer?.citations ?? []),
        ].slice(0, 40),
      };
      const previewRecord = agentRunRecord(resultPreview);
      const executionReceipt = normalizeAnalyticalExecutionReceipt(previewRecord?.executionReceipt);
      // Do not treat a child run ID as execution evidence. The canonical
      // fingerprint is the only proof that this Research branch produced a
      // result; planning, SQL text, and a durable run record remain review
      // required until that proof exists (AGT-016/033).
      const executionProof = normalizeAnalyticalExecutionFingerprint(previewRecord?.resultFingerprint)
        ?? executionReceipt?.resultFingerprint;
      const executionUnavailable = !previewError && !executionProof;
      // A governed branch that ended without rows explains itself: its own
      // sentence (a clarification, a modeling gap, a compiler message) is
      // the branch failure, not a generic "no execution receipt".
      const governedNoAnswer = governedAnswer && governedAnswer.kind === 'no_answer'
        ? (governedAnswer.executionError ?? governedAnswer.analyticalFailure?.message ?? governedAnswer.answer ?? governedAnswer.text)
        : undefined;
      const terminalError = previewError
        ?? (executionUnavailable
          ? (governedNoAnswer?.trim() || 'Research did not produce an executed result or execution receipt; the branch remains review-required.')
          : undefined);
      // A Research child reaches this point only after its own Ask cascade
      // selected and executed a frozen plan.  Once that execution has a
      // canonical receipt, preserve it immediately with a deterministic,
      // fact-bound branch narrative.  In particular, do not route the result
      // back through ordinary Ask narration (or another provider transport)
      // while the branch's fair-share deadline is running.  The root Research
      // synthesis consumes this persisted observation later.
      const authoritativeExecutedBranch = Boolean(
        input.authoritativeBranch
        && resultPreview
        && !previewError
        && executionProof,
      );
      const summary = authoritativeExecutedBranch
        ? deterministicResearchBranchSummary({
            question,
            result: resultPreview!,
            executionReceipt,
            analyticalNarrative: governedAnswer?.analyticalNarrative,
          })
        : usedBaselineFallback && resultPreview && !previewError
          ? 'Research retained the successful Ask baseline and revalidated it on the same data target. No unverified replacement query was accepted; use the dossier to add the next breakdown or comparison.'
          : notebookResearchString(governedAnswer?.answer)
            ?? notebookResearchString(governedAnswer?.text)
            ?? notebookResearchSummary(question, resultPreview, previewError);
      const recommendation = previewError
        ? 'Review the SQL, selected metadata, and connection context before rerunning.'
        : dqlArtifact && !reviewedSql
          ? 'Review the DQL artifact, parameter choices, grain, and evidence before promoting this research into a DQL draft block.'
        : sqlForPreview
          ? 'Review the SQL, parameter choices, grain, and evidence before promoting this research into a DQL draft block.'
          : 'Review the selected metadata context, then paste reviewed SQL or configure an AI provider before DQL draft promotion.';
      const researchPlan = buildNotebookResearchPlan({
        run,
        evidence,
        resultPreview,
        previewError,
        generatedSql,
        reviewedSql,
        dqlArtifact,
        routeDecision,
      });
      throwIfResearchSignalAborted();
      return storage.updateRun(run.id, {
        domain,
        owner,
        sourceCellFingerprint,
        question,
        intent,
        context,
        // A plan, generated SQL, or DQL artifact is not an observed execution.
        // Only a result carrying an execution fingerprint/receipt may become
        // `ready`; otherwise persist a failed review state with no fabricated
        // evidence (AGT-016/033).
        status: terminalError ? 'error' : 'ready',
        summary: terminalError && executionUnavailable
          ? 'Research branch stopped without an executed result; no observation was recorded.'
          : summary,
        recommendation,
        resultPreview,
        evidence,
        researchPlan,
        generatedSql,
        reviewedSql,
        dqlArtifact,
        display: display && display.ok ? display.display : undefined,
        contextPackId: contextPack.id,
        routeDecision,
        warnings: [
          ...(usedBaselineFallback && input.baselineRunId
            ? [`Baseline Ask run: ${input.baselineRunId}`]
            : []),
          ...warnings,
          ...(display && !display.ok ? [display.error] : []),
          ...(display && display.ok ? display.warnings : []),
        ],
        reviewStatus: 'needs_review',
        error: terminalError,
        lastRunAt: startedAt,
      }) ?? run;
    } catch (error) {
      rethrowIfCancelled(error, input.signal);
      return storage.updateRun(run.id, {
        domain,
        owner,
        sourceCellFingerprint,
        status: 'error',
        error: error instanceof Error ? error.message : String(error),
        reviewStatus: 'needs_review',
        lastRunAt: startedAt,
      }) ?? run;
    }
  };

  const promoteNotebookResearchToDql = async (
    storage: LocalNotebookResearchStorage,
    run: NotebookResearchRun,
    input: { domain?: string; owner?: string; tags?: string[]; provider?: string } = {},
  ): Promise<{ run: NotebookResearchRun; session: DqlGenerationSession }> => {
    const reviewedSql = notebookResearchString(run.reviewedSql);
    const dqlArtifact = normalizeDqlArtifactReference(run.dqlArtifact);
    const sql = reviewedSql ?? notebookResearchString(run.generatedSql);
    const sourcePath = `${run.notebookPath}${run.sourceCellId ? `#${run.sourceCellId}` : ''}`;
    if (!reviewedSql && dqlArtifact) {
      const session = await createDqlArtifactGenerationSessionForProject(projectRoot, {
        question: run.question,
        dqlArtifact,
        inputMode: 'upload',
        inputPath: dqlArtifact.sourcePath ?? sourcePath,
        domain: notebookResearchString(input.domain) ?? run.domain,
        owner: notebookResearchString(input.owner) ?? run.owner,
        tags: ['notebook-research', 'review-required', ...(Array.isArray(input.tags) ? input.tags : [])],
        generatedSql: notebookResearchString(run.generatedSql),
        contextPackId: run.contextPackId,
        routeIntent: run.intent,
        sourceBlock: dqlArtifact.sourcePath,
      }, semanticLayer);
      const draftPath = session.candidates.find((candidate) => candidate.draftSave?.path)?.draftSave?.path
        ?? session.candidates.find((candidate) => candidate.savedPath)?.savedPath;
      const promotion = buildNotebookDqlPromotionSummary(session, draftPath);
      const updated = storage.markPromoted(run.id, {
        draftBlockPath: draftPath,
        dqlImportId: session.id,
        dqlCandidateIds: session.candidates.map((candidate) => candidate.id),
        dqlPromotion: promotion,
      }) ?? run;
      const planned = storage.updateRun(updated.id, {
        researchPlan: buildNotebookResearchPlan({
          run: updated,
          evidence: updated.evidence,
          resultPreview: updated.resultPreview as ReturnType<typeof normalizeQueryResult> | undefined,
          generatedSql: updated.generatedSql,
          reviewedSql: updated.reviewedSql,
          dqlArtifact: updated.dqlArtifact,
          routeDecision: updated.routeDecision,
        }),
      }) ?? updated;
      return { run: planned, session };
    }
    if (!sql) throw new Error('Notebook research needs reviewed SQL, generated SQL, or a DQL artifact before DQL draft promotion.');
    const session = await createDqlGenerationSessionForProject(projectRoot, {
      inputMode: 'upload',
      sources: [{ path: sourcePath.endsWith('.sql') ? sourcePath : `${sourcePath}.sql`, content: sql }],
      sourceKind: 'raw-sql-file',
      domain: notebookResearchString(input.domain) ?? run.domain,
      owner: notebookResearchString(input.owner),
      tags: ['notebook-research', 'review-required', ...(Array.isArray(input.tags) ? input.tags : [])],
      provider: input.provider,
    }, semanticLayer);
    const draftPath = session.candidates.find((candidate) => candidate.draftSave?.path)?.draftSave?.path
      ?? session.candidates.find((candidate) => candidate.savedPath)?.savedPath;
    const promotion = buildNotebookDqlPromotionSummary(session, draftPath);
    const updated = storage.markPromoted(run.id, {
      draftBlockPath: draftPath,
      dqlImportId: session.id,
      dqlCandidateIds: session.candidates.map((candidate) => candidate.id),
      dqlPromotion: promotion,
    }) ?? run;
    const planned = storage.updateRun(updated.id, {
      researchPlan: buildNotebookResearchPlan({
        run: updated,
        evidence: updated.evidence,
        resultPreview: updated.resultPreview as ReturnType<typeof normalizeQueryResult> | undefined,
        generatedSql: updated.generatedSql,
        reviewedSql: updated.reviewedSql,
        dqlArtifact: updated.dqlArtifact,
        routeDecision: updated.routeDecision,
      }),
    }) ?? updated;
    return { run: planned, session };
  };

  const checkNotebookResearchReuse = async (
    storage: LocalNotebookResearchStorage,
    run: NotebookResearchRun,
    input: { domain?: string; owner?: string } = {},
  ): Promise<{ run: NotebookResearchRun; promotion: NotebookResearchDqlPromotion; match: Awaited<ReturnType<typeof matchSqlForDqlReuse>> }> => {
    const sql = notebookResearchString(run.reviewedSql) ?? notebookResearchString(run.generatedSql);
    if (!sql) throw new Error('Notebook research needs generated or reviewed SQL before reuse checking.');
    const sourcePath = `${run.notebookPath}${run.sourceCellId ? `#${run.sourceCellId}` : ''}.sql`;
    const match = await matchSqlForDqlReuse({
      sql,
      sourcePath,
      name: run.title || 'Notebook research SQL',
      domain: notebookResearchString(input.domain) ?? run.domain ?? 'uncategorized',
      owner: notebookResearchString(input.owner) ?? 'analytics',
    });
    const promotion: NotebookResearchDqlPromotion = {
      importId: `reuse-check:${run.id}:${Date.now()}`,
      candidateIds: ['reuse_check'],
      recommendedAction: match.recommendedAction,
      similarityMatches: match.similarityMatches.slice(0, 8).map(toNotebookPromotionMatch),
      candidates: [{
        id: 'reuse_check',
        name: run.title || 'Notebook research SQL',
        domain: notebookResearchString(input.domain) ?? run.domain,
        reviewStatus: 'reuse_checked',
        recommendedAction: match.recommendedAction,
        similarityMatches: match.similarityMatches.slice(0, 5).map(toNotebookPromotionMatch),
        parameterPolicy: match.parameterPolicy.slice(0, 16).map((entry) => ({
          name: entry.name,
          policy: entry.policy,
        })),
        allowedFilters: match.allowedFilters.slice(0, 16),
        warnings: match.parameterDecisions
          .filter((decision) => decision.reason)
          .map((decision) => `${decision.name}: ${decision.reason}`)
          .slice(0, 12),
      }],
      createdAt: new Date().toISOString(),
    };
    const checked = storage.updateRun(run.id, {
      dqlPromotionAction: match.recommendedAction,
      dqlPromotion: promotion,
      researchPlan: buildNotebookResearchPlan({
        run: {
          ...run,
          dqlPromotionAction: match.recommendedAction,
          dqlPromotion: promotion,
        },
        evidence: run.evidence,
        resultPreview: run.resultPreview as ReturnType<typeof normalizeQueryResult> | undefined,
        generatedSql: run.generatedSql,
        reviewedSql: run.reviewedSql,
        routeDecision: run.routeDecision,
      }),
    }) ?? run;
    return { run: checked, promotion, match };
  };

  const matchSqlForDqlReuse = async (input: {
    sql: string;
    sourcePath?: string;
    name?: string;
    domain?: string;
    owner?: string;
  }) => {
    const sql = input.sql.trim();
    if (!sql) throw new Error('Missing SQL for reuse check.');
    const sourceTables = extractSqlTablesLight(sql);
    const candidate: BlockStudioImportCandidate = {
      id: 'match_sql',
      sourceKind: 'raw-sql-file',
      sourcePath: input.sourcePath ?? 'pasted.sql',
      name: input.name ?? 'SQL match preview',
      domain: input.domain ?? 'imported',
      description: 'SQL match preview candidate.',
      owner: input.owner ?? 'analytics',
      tags: [],
      sql,
      dqlSource: '',
      validation: null,
      preview: null,
      lineage: {
        sourceTables,
        parameters: [],
        warnings: [],
        statementIndex: 1,
        totalStatements: 1,
      },
      confidence: 0.8,
      splitStrategy: 'manual',
      warnings: [],
      conversionNotes: [],
      aiAssistance: [],
      reviewStatus: 'draft',
    };
    const evidence = deterministicDqlGenerationEvidence(candidate);
    const patch = deterministicDqlGenerationPatch(candidate, evidence);
    const contextPack = await buildDqlGenerationContextPack(projectRoot, { ...candidate, sql: patch.sql ?? sql }).catch(() => null);
    const similarity = buildDqlGenerationSimilarityMatches(candidate, patch, contextPack);
    return {
      parameterDecisions: patch.parameterDecisions ?? [],
      parameterPolicy: patch.parameterPolicy ?? [],
      filterBindings: patch.filterBindings ?? [],
      allowedFilters: patch.allowedFilters ?? [],
      parameterizedSql: patch.sql ?? sql,
      similarityMatches: similarity.matches,
      recommendedAction: similarity.recommendedAction,
    };
  };

  const buildNotebookDqlPromotionSummary = (
    session: DqlGenerationSession,
    draftBlockPath?: string,
  ): NotebookResearchDqlPromotion => {
    const primary = draftBlockPath
      ? session.candidates.find((candidate) => candidate.draftSave?.path === draftBlockPath || candidate.savedPath === draftBlockPath) ?? session.candidates[0]
      : session.candidates[0];
    return {
      importId: session.id,
      candidateIds: session.candidates.map((candidate) => candidate.id),
      draftBlockPath,
      recommendedAction: primary?.recommendedAction,
      similarityMatches: (primary?.similarityMatches ?? []).slice(0, 8).map(toNotebookPromotionMatch),
      candidates: session.candidates.map((candidate) => ({
        id: candidate.id,
        name: candidate.name,
        domain: candidate.domain,
        draftPath: candidate.draftSave?.path,
        savedPath: candidate.savedPath,
        reviewStatus: candidate.reviewStatus,
        recommendedAction: candidate.recommendedAction,
        similarityMatches: (candidate.similarityMatches ?? []).slice(0, 5).map(toNotebookPromotionMatch),
        parameterPolicy: (candidate.parameterPolicy ?? []).slice(0, 16).map((entry) => ({
          name: entry.name,
          policy: entry.policy,
        })),
        allowedFilters: (candidate.allowedFilters ?? []).slice(0, 16),
        warnings: [...(candidate.warnings ?? []), ...(candidate.lineage.warnings ?? [])].slice(0, 12),
      })),
      createdAt: new Date().toISOString(),
    };
  };

  const toNotebookPromotionMatch = (match: BlockSimilarityMatch) => ({
    kind: match.kind,
    objectKey: match.objectKey,
    name: match.name,
    status: match.status,
    source: match.source,
    score: match.score,
    reason: match.reason,
    recommendedAction: match.recommendedAction,
  });

  // SSE clients for /api/watch hot-reload
  const sseClients = new Set<ServerResponse>();
  const projectWatchers: Array<ReturnType<typeof watch>> = [];
  let runtimeClosing = false;
  let watcherWarningEmitted = false;

  const closeProjectWatcher = (watcher: ReturnType<typeof watch>) => {
    const index = projectWatchers.indexOf(watcher);
    if (index >= 0) projectWatchers.splice(index, 1);
    try { watcher.close(); } catch { /* watcher already closed or unavailable */ }
  };

  /**
   * `fs.watch()` reports descriptor exhaustion asynchronously. The synchronous
   * creation try/catch below cannot catch that emitter error, so contain it at
   * the watcher boundary. Watching only feeds hot refresh; it is never the
   * authority for persisted project or run state, which remains available.
   */
  const registerProjectWatcher = (watcher: ReturnType<typeof watch>, scope: string) => {
    projectWatchers.push(watcher);
    let watcherFailed = false;
    // Keep the listener installed after the first failure. A queued second
    // `error` event after `close()` must not become a new unhandled exception.
    watcher.on('error', (error: unknown) => {
      if (watcherFailed) return;
      watcherFailed = true;
      closeProjectWatcher(watcher);
      if (runtimeClosing || watcherWarningEmitted) return;
      watcherWarningEmitted = true;
      const code = error && typeof error === 'object' && (error as { code?: unknown }).code === 'EMFILE'
        ? 'EMFILE'
        : 'unavailable';
      // Do not include a project path or the raw OS error: both can be noisy or
      // sensitive. One bounded warning is enough to explain the degraded hot
      // refresh without masking a healthy local server or durable persistence.
      console.warn(`[dql] Project file watching was degraded (${code}) for ${scope}; automatic refresh is unavailable for that source, but the server and persisted local state remain available. Restart DQL to resume watching.`);
    });
  };

  // Watch all Git-owned authoring roots. Domain Packages are recursive and are
  // the canonical home for modeling, skills, blocks, notebooks, Apps, and evals.
  if (projectRoot) {
    for (const dir of ['domains', 'skills', 'tests', 'notebooks', 'workbooks', 'blocks', 'apps', 'dashboards', 'semantic-layer', 'data']) {
      const watchDir = join(projectRoot, dir);
      if (!existsSync(watchDir)) continue;
      try {
        const watcher = projectWatcherFactory(watchDir, { persistent: false, recursive: true }, (eventType, filename) => {
          if (runtimeClosing) return;
          if (!filename) return;
          const path = `${dir}/${filename}`;
          const payload = JSON.stringify({ type: eventType === 'rename' ? 'file-added' : 'file-changed', path });
          for (const client of sseClients) {
            try { client.write(`event: change\ndata: ${payload}\n\n`); } catch { sseClients.delete(client); }
          }
          if (['domains', 'skills', 'tests', 'blocks', 'apps', 'notebooks'].includes(dir)) {
            invalidateAgentProjectState(projectRoot);
            scheduleProjectRefresh(`file:${path}`);
          }
          // Hot-reload semantic layer on change and notify frontend
          if (dir === 'semantic-layer') {
            reloadSemanticLayer().then(() => {
              // Notify all connected notebook clients to re-fetch the semantic layer
              const reloadPayload = JSON.stringify({ type: 'semantic-reload' });
              for (const client of sseClients) {
                try { client.write(`event: change\ndata: ${reloadPayload}\n\n`); } catch { sseClients.delete(client); }
              }
            }).catch(() => { /* reload errors are non-fatal */ });
          }
        });
        registerProjectWatcher(watcher, 'project authoring');
      } catch { /* dir not watchable */ }
    }
    // A dbt repository commonly keeps its shared Skills folder beside the DQL
    // project (`../skills`). It is Git-owned context too, so watch the resolved
    // configured root even when it is not the default projectRoot/skills path.
    const configuredSkillsRoot = skillsDir(projectRoot);
    const defaultSkillsRoot = join(projectRoot, 'skills');
    if (existsSync(configuredSkillsRoot) && resolve(configuredSkillsRoot) !== resolve(defaultSkillsRoot)) {
      try {
        const watcher = projectWatcherFactory(configuredSkillsRoot, { persistent: false, recursive: true }, (eventType, filename) => {
          if (runtimeClosing || !filename) return;
          const path = relative(projectRoot, join(configuredSkillsRoot, String(filename))).replace(/\\/g, '/');
          invalidateAgentProjectState(projectRoot);
          scheduleProjectRefresh(`skills:${path}`);
          const payload = JSON.stringify({ type: eventType === 'rename' ? 'file-added' : 'file-changed', path });
          for (const client of sseClients) {
            try { client.write(`event: change\ndata: ${payload}\n\n`); } catch { sseClients.delete(client); }
          }
        });
        registerProjectWatcher(watcher, 'configured skills');
      } catch { /* configured Skills folder is not watchable */ }
    }
    const configuredDbtManifest = resolveDbtManifestPath(projectRoot, projectConfig);
    if (configuredDbtManifest && existsSync(dirname(configuredDbtManifest))) {
      try {
        const watcher = projectWatcherFactory(dirname(configuredDbtManifest), { persistent: false }, (_eventType, filename) => {
          if (runtimeClosing) return;
          if (!filename || !['manifest.json', 'catalog.json', 'semantic_manifest.json', 'run_results.json'].includes(String(filename))) return;
          invalidateAgentProjectState(projectRoot);
          scheduleProjectRefresh(`dbt:${String(filename)}`);
          const payload = JSON.stringify({ type: 'dbt-artifacts-changed', path: String(filename) });
          for (const client of sseClients) {
            try { client.write(`event: change\ndata: ${payload}\n\n`); } catch { sseClients.delete(client); }
          }
          void reloadSemanticLayer().then(() => {
            const reloadPayload = JSON.stringify({ type: 'semantic-reload' });
            for (const client of sseClients) {
              try { client.write(`event: change\ndata: ${reloadPayload}\n\n`); } catch { sseClients.delete(client); }
            }
          }).catch(() => { /* artifact reload errors are exposed in diagnostics */ });
        });
        registerProjectWatcher(watcher, 'dbt artifacts');
      } catch { /* dbt artifact directory not watchable */ }
    }
  }

  const validateImportCandidate = (candidate: BlockStudioImportCandidate): BlockStudioImportCandidate => ({
    ...candidate,
    validation: validateBlockStudioSource(candidate.dqlSource, semanticLayer),
  });

  const validateImportCandidateForSave = (candidate: BlockStudioImportCandidate): {
    candidate: BlockStudioImportCandidate;
    errors: string[];
  } => {
    const validated = validateImportCandidate(candidate);
    const diagnostics = ((validated.validation as any)?.diagnostics ?? []) as Array<{ severity?: string; message?: string }>;
    const errors = diagnostics
      .filter((diagnostic) => diagnostic.severity === 'error')
      .map((diagnostic) => diagnostic.message || 'Candidate validation failed.');
    if (validated.reviewStatus === 'rejected') {
      errors.unshift('Candidate was rejected.');
    }
    const duplicateBlocker = duplicateCertificationBlocker(validated);
    if (duplicateBlocker) errors.unshift(duplicateBlocker);
    return { candidate: validated, errors };
  };

  const duplicateCertificationBlocker = (candidate: BlockStudioImportCandidate): string | null => {
    const match = candidate.similarityMatches?.[0];
    if (!match) return null;
    const duplicateKind = match.kind === 'exact_sql_match'
      || match.kind === 'parameterized_duplicate'
      || (match.kind === 'business_duplicate' && match.status === 'certified' && match.score >= 0.76);
    if (!duplicateKind) return null;
    const replacementFor = new Set((candidate.replacementFor ?? []).map((value) => value.toLowerCase()));
    const documentedReplacement = candidate.recommendedAction === 'create_replacement'
      || replacementFor.has(match.name.toLowerCase())
      || (match.objectKey && replacementFor.has(match.objectKey.toLowerCase()));
    if (documentedReplacement) return null;
    return `Likely duplicate of ${match.name} (${match.kind}, ${Math.round(match.score * 100)}% match). Reuse the existing block, extend it, or document this draft as a replacement before certification.`;
  };

  const runBlockStudioPreviewSource = async (
    source: string,
    targetConnection?: ConnectionConfig | null,
    parameters: Record<string, unknown> = {},
  ): Promise<{
    sql: string;
    result: ReturnType<typeof normalizeQueryResult>;
    compiledSqlFingerprint: string;
    resultFingerprint: string;
    chartConfig: { chart?: string; x?: string; y?: string; color?: string; title?: string } | null;
    invocation: ReturnType<typeof prepareBlockInvocation>;
    tests: NonNullable<ReturnType<typeof buildExecutionPlan>>['tests'];
    validation: BlockStudioValidationResult;
  }> => {
    const activeConnection = requireActiveConnection(targetConnection);
    let tableMapping: Record<string, string> | undefined;
    if (semanticLayer) {
      tableMapping = await resolveSemanticTableMapping(
        executor,
        activeConnection,
        semanticLayer,
        projectRoot,
      );
    }
    const invocation = prepareBlockInvocation({ source, parameters, surface: 'block_studio' });
    if (invocation.errors.length > 0) throw new Error(invocation.errors.join(' '));
    if (invocation.unresolvedParameters.length > 0) {
      throw new Error(`Provide required parameter${invocation.unresolvedParameters.length === 1 ? '' : 's'}: ${invocation.unresolvedParameters.join(', ')}.`);
    }
    const semanticCompose = semanticLayer
      ? await composeSemanticBlockSqlForRuntime(source, semanticLayer, {
          driver: activeConnection.driver,
          tableMapping,
          projectRoot,
          projectConfig,
          detectedProvider: semanticDetectedProvider,
          parameters: invocation.values,
        })
      : null;
    const staticValidation = validateBlockStudioSource(source, semanticLayer);
    const validation = semanticCompose
      ? reconcileBlockStudioRuntimeValidation(staticValidation, semanticCompose)
      : staticValidation;
    const executableSql = semanticCompose?.sql ?? validation.executableSql;
    if (!executableSql) {
      const message = semanticCompose?.diagnostics.find((item) => item.severity === 'error')?.message
        ?? validation.diagnostics.find((item) => item.severity === 'error')?.message
        ?? 'No executable SQL found in block source.';
      throw new Error(message);
    }
    const plan = buildExecutionPlan(
      { id: 'block-studio', type: 'dql', source, title: 'Block Studio' },
      {
        semanticLayer,
        driver: activeConnection.driver,
        tableMapping,
        semanticSql: semanticCompose?.sql ?? undefined,
      },
    );
    const execution = await analyticalExecutionService.execute({
      sql: semanticCompose?.sql ?? plan?.sql ?? executableSql,
      subject: 'Block Studio preview query',
      connection: activeConnection,
      sqlParams: plan?.sqlParams,
      variables: { ...(plan?.variables ?? {}), ...invocation.values },
    });
    return {
      sql: execution.preparation.executedSql,
      result: execution.result,
      compiledSqlFingerprint: execution.compiledSqlFingerprint,
      resultFingerprint: execution.resultFingerprint,
      chartConfig: plan?.chartConfig ?? validation.chartConfig ?? null,
      invocation,
      tests: plan?.tests ?? [],
      validation,
    };
  };

  const runBlockStudioTestSummary = async (
    source: string,
    targetConnection?: ConnectionConfig | null,
    executedPreview?: Awaited<ReturnType<typeof runBlockStudioPreviewSource>>,
  ): Promise<TestResultSummary> => {
    const start = Date.now();
    if (executedPreview) {
      return evaluateBlockStudioTests(
        executedPreview.tests,
        executedPreview.result.rows,
        executedPreview.result.columns,
        start,
      );
    }
    const activeConnection = requireActiveConnection(targetConnection);
    const tableMapping = await resolveSemanticTableMapping(executor, activeConnection, semanticLayer, projectRoot);
    // Run tests against the SAME SQL the preview runs: for a semantic block with a
    // pre-compiled query, that's the query (not a recompiled metric), so the test's
    // output columns match the block's declared outputs.
    const semanticCompose = semanticLayer
      ? await composeSemanticBlockSqlForRuntime(source, semanticLayer, {
          driver: activeConnection.driver,
          tableMapping,
          projectRoot,
          projectConfig,
          detectedProvider: semanticDetectedProvider,
        })
      : null;
    const plan = buildExecutionPlan(
      { id: 'block-studio-tests', type: 'dql', source, title: 'Block Studio' },
      {
        semanticLayer,
        driver: activeConnection.driver,
        tableMapping,
        semanticSql: semanticCompose?.sql ?? undefined,
      },
    );
    const tests = plan?.tests ?? [];
    if (!plan || !plan.sql) {
      return {
        passed: 0,
        failed: Math.max(tests.length, 1),
        skipped: 0,
        duration: Date.now() - start,
        assertions: [{
          name: 'build execution plan',
          passed: false,
          error: semanticCompose?.diagnostics.find((diagnostic) => diagnostic.severity === 'error')?.message
            ?? 'Could not build an execution plan for this block.',
        }],
        runAt: new Date(),
      };
    }
    if (tests.length === 0) {
      return { passed: 0, failed: 0, skipped: 0, duration: Date.now() - start, assertions: [], runAt: new Date() };
    }
    const execution = await analyticalExecutionService.execute({
      sql: semanticCompose?.sql ?? plan.sql,
      subject: 'Block Studio certification test query',
      connection: activeConnection,
      sqlParams: plan.sqlParams,
      variables: plan.variables,
    });
    const { rows, columns } = execution.result;
    return evaluateBlockStudioTests(tests, rows, columns, start);
  };

  const saveDqlGenerationDraft = (
    importId: string,
    candidate: BlockStudioImportCandidate,
  ): DqlGenerationCandidate => saveDqlGenerationDraftForProject(projectRoot, importId, candidate);

  const createDqlGenerationSessionFromBody = async (body: any): Promise<DqlGenerationSession> => {
    return createDqlGenerationSessionForProject(projectRoot, {
      inputPath: typeof body.path === 'string' ? body.path : '',
      inputMode: body.inputMode === 'paste' || body.inputMode === 'upload' || body.inputMode === 'path' ? body.inputMode : undefined,
      sources: Array.isArray(body.sources)
        ? body.sources.map((source: any, index: number) => ({
            path: typeof source?.path === 'string' ? source.path : `source-${index + 1}.sql`,
            content: typeof source?.content === 'string' ? source.content : '',
          }))
        : undefined,
      sourceKind: typeof body.sourceKind === 'string' ? body.sourceKind : 'raw-sql',
      domain: typeof body.domain === 'string' ? body.domain : undefined,
      owner: typeof body.owner === 'string' ? body.owner : undefined,
      tags: Array.isArray(body.tags) ? body.tags.map(String) : undefined,
      provider: typeof body.provider === 'string' ? body.provider : undefined,
      async: body.async === true,
      persistence: body.persistence === 'session-only' || body.persistence === 'draft-files' ? body.persistence : undefined,
    }, semanticLayer);
  };

  const loadDqlGenerationSession = (importId: string): DqlGenerationSession => {
    const session = loadBlockStudioImportSession(projectRoot, importId);
    const candidates = session.candidates.map((candidate) => ({
      ...candidate,
      generationMode: candidate.generationMode ?? 'deterministic',
      generationProvider: candidate.generationProvider ?? 'local-deterministic',
      llmContext: candidate.llmContext ?? deterministicDqlGenerationContext(candidate, candidate.evidence ?? []),
      evidence: candidate.evidence ?? deterministicDqlGenerationEvidence(candidate),
      draftSave: candidate.draftSave ?? (
        isDraftBlockPath(candidate.savedPath)
          ? { status: 'saved' as const, path: candidate.savedPath }
          : { status: 'pending' as const }
      ),
    }));
    return {
      ...session,
      mode: 'ai-import',
      candidates,
      generation: {
        provider: candidates.find((candidate) => candidate.generationProvider)?.generationProvider ?? 'local-deterministic',
        aiEnabled: candidates.some((candidate) => candidate.generationMode === 'ai'),
        contextObjectCount: candidates.reduce((sum, candidate) => sum + (candidate.evidence?.length ?? 0), 0),
        createdDrafts: candidates.filter((candidate) => candidate.draftSave.status === 'saved').length,
        warnings: candidates.flatMap((candidate) => candidate.draftSave.status === 'error' && candidate.draftSave.error ? [candidate.draftSave.error] : []),
      },
    };
  };

  const certifyBlockStudioSource = async (
    source: string,
    blockPath?: string | null,
    options: {
      enterprise?: boolean;
      reportProgress?: (progress: { phase: string; progress: number; message: string }) => void;
    } = {},
  ) => {
    options.reportProgress?.({
      phase: 'validating',
      progress: 10,
      message: 'Validating the saved DQL source.',
    });
    let validation = validateBlockStudioSource(source, semanticLayer);
    let preview: Awaited<ReturnType<typeof runBlockStudioPreviewSource>> | null = null;
    let testResults: TestResultSummary | null = null;
    const blockers: string[] = [];

    options.reportProgress?.({
      phase: 'previewing',
      progress: 30,
      message: 'Compiling and previewing the saved block.',
    });
    try {
      preview = await runBlockStudioPreviewSource(source);
      validation = preview.validation;
    } catch (error) {
      blockers.push(error instanceof Error ? error.message : String(error));
    }

    options.reportProgress?.({
      phase: 'testing',
      progress: 60,
      message: 'Evaluating declared block tests.',
    });
    try {
      testResults = preview
        ? await runBlockStudioTestSummary(source, undefined, preview)
        : await runBlockStudioTestSummary(source);
    } catch (error) {
      testResults = {
        passed: 0,
        failed: 1,
        skipped: 0,
        duration: 0,
        assertions: [{ name: 'run tests', passed: false, error: error instanceof Error ? error.message : String(error) }],
        runAt: new Date(),
      };
    }
    options.reportProgress?.({
      phase: 'assessing',
      progress: 75,
      message: 'Assessing certification rules and evidence.',
    });

    const parsed = parseBlockSourceMetadata(source);
    const record: BlockRecord = {
      id: parsed.name || 'local',
      name: parsed.name || 'unnamed',
      domain: parsed.domain,
      type: parsed.blockType || 'custom',
      version: '0.0.0',
      status: 'draft',
      gitRepo: '',
      gitPath: blockPath ?? '',
      gitCommitSha: '',
      description: parsed.description,
      owner: parsed.owner,
      tags: parsed.tags,
      llmContext: parsed.llmContext,
      pattern: parsed.pattern,
      grain: parsed.grain,
      entities: parsed.entities,
      declaredOutputs: parsed.outputs,
      dimensions: parsed.dimensions,
      allowedFilters: parsed.allowedFilters,
      parameterPolicy: parsed.parameterPolicy,
      filterBindings: parsed.filterBindings,
      sourceSystems: parsed.sourceSystems,
      replacementFor: parsed.replacementFor,
      reviewCadence: parsed.reviewCadence,
      metricRef: parsed.metricRef || undefined,
      metricsRef: parsed.metricsRef.length > 0 ? parsed.metricsRef : undefined,
      dependencies: [],
      usedInCount: 0,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    // Evaluate declared invariants against the preview result so the
    // `invariants-hold` certifier rule can enforce them. Best-effort: when the
    // preview failed there is no result to check, and the rule then blocks
    // certification (in enterprise mode) because the guarantees are unverified.
    const invariantEval = preview
      ? evaluateBlockInvariants(source, {
          columns: preview.result.columns,
          rows: preview.result.rows,
        })
      : null;
    record.invariants = extractBlockInvariants(source);
    const certification = new Certifier(options.enterprise ? ENTERPRISE_RULES : undefined).evaluate(
      record,
      testResults ?? undefined,
      invariantEval ? { invariantResults: invariantEval.invariantResults } : undefined,
    );
    const checklist = buildBlockStudioCertificationChecklist({
      source,
      validation,
      previewSucceeded: Boolean(preview),
      testResults,
      certificationErrors: certification.errors,
      extraBlockers: blockers,
    });
    return {
      certification,
      checklist,
      validation,
      preview,
      testResults,
      invariantResults: invariantEval?.invariantResults ?? [],
      invariantViolation: invariantEval?.invariantViolation ?? false,
    };
  };

  const writeAgentRunSse = (
    response: ServerResponse,
    event: string,
    data: AgentRun | AgentRunEvent | { error: string } | { runId?: string; delta: string } | { runId?: string; operationId?: string; replayed?: boolean },
  ) => {
    response.write(`event: ${event}\n`);
    response.write(`data: ${serializeJSON(data)}\n\n`);
  };

  /**
   * Gzip text responses.
   *
   * Nothing was compressed before: the main bundle went out at 592 KB where gzip
   * makes it 154 KB (73% smaller), and JSON API responses — which compress even
   * better — were also sent raw. One wrapper here rather than a change at
   * hundreds of `res.end(...)` call sites.
   *
   * STREAMING IS EXEMPT. Buffering an SSE response in order to compress it would
   * defeat streaming entirely, so any response that calls `res.write()` opts
   * itself out permanently, as does `text/event-stream`.
   */
  const MIN_COMPRESS_BYTES = 1024;
  const COMPRESSIBLE = /^(?:text\/(?!event-stream)|application\/(?:json|javascript|xml|wasm)|image\/svg)/i;
  const withCompression = <T>(request: IncomingMessage, rawResponse: T): T => {
    const response = rawResponse as unknown as ServerResponse;
    if (!/\bgzip\b/i.test(String(request.headers['accept-encoding'] ?? ''))) return rawResponse;
    const writeHead = response.writeHead.bind(response);
    const end = response.end.bind(response);
    const write = response.write.bind(response);
    let status = 200;
    let headers: Record<string, unknown> = {};
    let captured = false;
    let streaming = false;

    response.writeHead = ((code: number, hdrs?: Record<string, unknown>) => {
      status = code;
      headers = hdrs ?? {};
      captured = true;
      return response;
    }) as typeof response.writeHead;

    response.write = ((...args: Parameters<typeof write>) => {
      if (captured && !streaming) { streaming = true; writeHead(status, headers as never); }
      return write(...args);
    }) as typeof response.write;

    response.end = ((...args: Parameters<typeof end>) => {
      const body = args[0];
      const contentType = String(headers['Content-Type'] ?? '');
      const encodable = captured
        && !streaming
        && (typeof body === 'string' || Buffer.isBuffer(body))
        && COMPRESSIBLE.test(contentType);
      if (!encodable) {
        if (captured && !streaming) { streaming = true; writeHead(status, headers as never); }
        return end(...args);
      }
      const raw = Buffer.isBuffer(body) ? body : Buffer.from(body as string, 'utf8');
      streaming = true;

      // VALIDATOR CACHING. API responses carried no ETag or Last-Modified, so a
      // browser could never revalidate: every panel switch re-downloaded every
      // read in full. An ETag with `Cache-Control: no-cache` means the browser
      // always ASKS but the server answers 304 with no body when nothing
      // changed — freshness is unchanged, the bytes are not re-sent.
      const cacheableRead = request.method === 'GET' && status === 200;
      const etag = cacheableRead
        ? `W/"${createHash('sha1').update(raw).digest('base64url')}"`
        : undefined;
      if (etag && String(request.headers['if-none-match'] ?? '') === etag) {
        writeHead(304, {
          ETag: etag,
          'Cache-Control': headers['Cache-Control'] ?? 'no-cache',
          Vary: 'Accept-Encoding, Origin',
        } as never);
        return end();
      }
      const validatorHeaders = etag
        ? { ETag: etag, 'Cache-Control': headers['Cache-Control'] ?? 'no-cache' }
        : {};

      if (raw.byteLength < MIN_COMPRESS_BYTES) {
        writeHead(status, { ...headers, ...validatorHeaders } as never);
        return end(raw);
      }
      gzip(raw, (error, gz) => {
        if (response.destroyed || response.writableEnded) return;
        if (error) {
          writeHead(status, { ...headers, ...validatorHeaders } as never);
          end(raw);
          return;
        }
        writeHead(status, {
          ...headers,
          ...validatorHeaders,
          'Content-Encoding': 'gzip',
          'Content-Length': gz.byteLength,
          Vary: 'Accept-Encoding, Origin',
        } as never);
        end(gz);
      });
      return response;
    }) as typeof response.end;
    return rawResponse;
  };

  const server = createServer((req, res) => {
    res = withCompression(req, res);
    const requestUrl = req.url || '/';
    const url = new URL(requestUrl, 'http://127.0.0.1');
    const path = url.pathname || '/';
    void (async () => {

    // Exact-origin CORS. Loopback dev origins are accepted; remote serving
    // requires an explicit allowlist and bearer token.
    const requestOrigin = typeof req.headers.origin === 'string' ? req.headers.origin.replace(/\/$/, '') : undefined;
    const loopbackOrigin = requestOrigin ? isLoopbackOrigin(requestOrigin) : false;
    const originAllowed = !requestOrigin || (loopback ? loopbackOrigin : allowedOrigins.has(requestOrigin));
    if (requestOrigin && originAllowed) res.setHeader('Access-Control-Allow-Origin', requestOrigin);
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, Idempotency-Key, X-DQL-Ask-Trace-Capability');
    if (!originAllowed && path.startsWith('/api/')) {
      res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ error: 'Origin is not allowed.' }));
      return;
    }
    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }
    if (!loopback && path.startsWith('/api/') && path !== '/api/health') {
      const authorization = req.headers.authorization ?? '';
      if (authorization !== `Bearer ${authToken}`) {
        res.writeHead(401, { 'Content-Type': 'application/json; charset=utf-8', 'WWW-Authenticate': 'Bearer' });
        res.end(serializeJSON({ error: 'A valid DQL server bearer token is required.' }));
        return;
      }
    }

    // Existing `dql notebook` runtimes cannot hand their in-memory capability
    // to a later CLI process. A short-lived challenge is therefore issued only
    // when BOTH the server binding and requesting socket are loopback. Remote
    // and browser-origin requests retain their normal `browser` attribution.
    if (req.method === 'GET' && path === '/api/ask-traces/cli-capability') {
      if (!loopback || !isLoopbackRemoteAddress(req.socket.remoteAddress)) {
        res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_CLI_CAPABILITY_FORBIDDEN', error: 'CLI trace attribution is available only to a loopback local runtime.' }));
        return;
      }
      const capability = cliAskTraceCapabilities.issue();
      res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
      res.end(serializeJSON(capability));
      return;
    }

    if (req.method === 'GET' && path === '/api/health') {
      // REL-002: expose runtime/build identity so a server started before a
      // rebuild or running a different version than the project pin is visibly
      // stale. Uses only the cached latest-version lookup — never blocks.
      const versionStatus = resolveDqlRuntimeVersionStatus({ projectRoot, runningVersion: runtimeVersion });
      void fetchLatestPublishedDqlVersion();
      const healthValueGrounding = resolveAgentRuntimeValueGrounding(projectConfig);
      const retrievalHealth = resolveRetrievalHealthStatus({
        projectRoot,
        valueGroundingMode: healthValueGrounding.mode,
        searchSafeColumnCount: healthValueGrounding.searchSafeColumns.size,
      });
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        status: 'ok',
        version: runtimeVersion,
        versionStatus,
        retrievalHealth,
        askRuntimeMode: askAgentRuntimeMode,
      }));
      return;
    }

    if (req.method === 'GET' && path === '/api/operations/events') {
      res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
        'X-Accel-Buffering': 'no',
      });
      res.write(': connected\n\n');
      operationSseClients.add(res as unknown as ServerResponse);
      for (const operation of operationCoordinator.list(20).reverse()) {
        res.write(`event: operation\ndata: ${serializeJSON(operation)}\n\n`);
      }
      req.on('close', () => operationSseClients.delete(res as unknown as ServerResponse));
      return;
    }

    if (req.method === 'GET' && path === '/api/operations') {
      const limit = Number(url.searchParams.get('limit') ?? 50);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ operations: operationCoordinator.list(limit) }));
      return;
    }

    const operationMatch = path.match(/^\/api\/operations\/([^/]+)$/);
    if (operationMatch && req.method === 'GET') {
      const operation = operationCoordinator.get(decodeURIComponent(operationMatch[1]));
      res.writeHead(operation ? 200 : 404, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(operation ?? { error: 'Operation not found.' }));
      return;
    }
    if (operationMatch && req.method === 'DELETE') {
      const operationId = decodeURIComponent(operationMatch[1]);
      const existingOperation = operationCoordinator.get(operationId);
      if (existingOperation?.type === 'agent_run' && existingOperation.scope.startsWith('agent-run:')) {
        cancelActiveAgentRun(existingOperation.scope.slice('agent-run:'.length));
      }
      const operation = operationCoordinator.cancel(operationId);
      res.writeHead(operation ? 200 : 404, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(operation ?? { error: 'Operation not found.' }));
      return;
    }

    if (req.method === 'GET' && path === '/api/onboarding/launch') {
      const requestId = apiRequestId('onboarding-launch');
      const prefs = readUserPrefs(userPrefsPath);
      const acknowledgedVersion = prefs.setup?.acknowledgedVersion ?? null;
      const dbtAppliedVersion = prefs.setup?.dbtAppliedVersion ?? null;
      const shouldOpen = acknowledgedVersion !== runtimeVersion;
      const configuredDbtSource = projectConfig.dbt?.repoUrl ?? projectConfig.dbt?.projectDir;
      const configuredDbtRoot = findDbtProjectPath(projectRoot, projectConfig);
      const dbtConfigured = existsSync(join(configuredDbtRoot, 'dbt_project.yml'))
        || Boolean(configuredDbtSource && !/\{\{[^}]+\}\}/.test(configuredDbtSource));
      const requiresDbtReapply = Boolean(
        shouldOpen
        && acknowledgedVersion
        && dbtConfigured
        && dbtAppliedVersion !== runtimeVersion,
      );
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        requestId,
        version: runtimeVersion,
        acknowledgedVersion,
        dbtAppliedVersion,
        requiresDbtReapply,
        shouldOpen,
        reason: shouldOpen ? (acknowledgedVersion ? 'version_upgrade' : 'first_install') : null,
      }));
      return;
    }

    if (req.method === 'POST' && path === '/api/onboarding/acknowledge') {
      const requestId = apiRequestId('onboarding-acknowledge');
      const prefs = readUserPrefs(userPrefsPath);
      const configuredDbtSource = projectConfig.dbt?.repoUrl ?? projectConfig.dbt?.projectDir;
      const configuredDbtRoot = findDbtProjectPath(projectRoot, projectConfig);
      const dbtConfigured = existsSync(join(configuredDbtRoot, 'dbt_project.yml'))
        || Boolean(configuredDbtSource && !/\{\{[^}]+\}\}/.test(configuredDbtSource));
      const isVersionUpgrade = Boolean(
        prefs.setup?.acknowledgedVersion
        && prefs.setup.acknowledgedVersion !== runtimeVersion,
      );
      if (isVersionUpgrade && dbtConfigured && prefs.setup?.dbtAppliedVersion !== runtimeVersion) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          code: 'DBT_REAPPLY_REQUIRED',
          message: `Reapply the saved dbt project with DQL ${runtimeVersion} before completing the update review.`,
          nextActions: ['Open Project & dbt, preview the prefilled project, then choose Reapply project.'],
        })));
        return;
      }
      prefs.setup = {
        ...prefs.setup,
        acknowledgedVersion: runtimeVersion,
        acknowledgedAt: new Date().toISOString(),
      };
      writeUserPrefs(userPrefsPath, prefs);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ requestId, version: runtimeVersion, acknowledged: true }));
      return;
    }

    if (req.method === 'GET' && path === '/api/onboarding/status') {
      const requestId = apiRequestId('onboarding-status');
      const dbtProjectDir = findDbtProjectPath(projectRoot, projectConfig);
      const manifestPath = resolve(dbtProjectDir, projectConfig.dbt?.manifestPath ?? 'target/manifest.json');
      const configuredDbtSource = projectConfig.dbt?.repoUrl ?? projectConfig.dbt?.projectDir;
      const dbtConfigured = existsSync(join(dbtProjectDir, 'dbt_project.yml'))
        || Boolean(configuredDbtSource && !/\{\{[^}]+\}\}/.test(configuredDbtSource));
      const configuredProfilesDir = projectConfig.dbt?.profilesDir ? resolve(projectRoot, projectConfig.dbt.profilesDir) : undefined;
      const profilePath = findDbtProfilePaths(projectRoot, dbtProjectDir, configuredProfilesDir)[0];
      const registry = loadDomainPackageRegistry(projectRoot);
      const manifestFound = existsSync(manifestPath);
      let snapshotId: string | undefined;
      let snapshotError: string | undefined;
      if (manifestFound) {
        try {
          snapshotId = projectSnapshot().snapshotId;
        } catch (error) {
          snapshotError = error instanceof Error ? error.message : String(error);
        }
      }
      const preparation = latestDbtPreparationJob();
      const preparationForSnapshot = preparation?.snapshotId === snapshotId ? preparation : undefined;
      const searchIndexesPresent = isAgentProjectIndexReady(projectRoot);
      const snapshotState = preparationForSnapshot?.status === 'running' || preparationForSnapshot?.status === 'queued'
        ? 'building'
        : preparationForSnapshot?.status === 'failed'
          ? 'failed'
          : snapshotId && searchIndexesPresent
            ? 'ready'
            : snapshotId
              ? 'stale'
              : 'missing';
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        requestId,
        snapshotId,
        dbt: {
          configured: dbtConfigured,
          projectDir: projectConfig.dbt?.projectDir,
          manifestPath: projectConfig.dbt?.manifestPath,
          profilesDir: configuredProfilesDir
            ? portableProjectPath(projectRoot, configuredProfilesDir)
            : profilePath ? portableProjectPath(projectRoot, dirname(profilePath)) : undefined,
          repoUrl: projectConfig.dbt?.repoUrl,
          branch: projectConfig.dbt?.branch,
          subPath: projectConfig.dbt?.subPath,
          projectFound: existsSync(join(dbtProjectDir, 'dbt_project.yml')),
          manifestFound,
          artifactState: manifestFound ? 'ready' : 'missing',
        },
        modeling: {
          enabled: modelingModeOf(projectConfig) !== undefined,
          manifestVersion: projectConfig.manifestVersion ?? 2,
          mode: projectConfig.modeling?.mode,
          snapshotState,
        },
        domains: { count: registry.values().length, diagnostics: registry.diagnostics },
        snapshot: { id: snapshotId, error: snapshotError },
        preparation,
        readiness: {
          project: {
            state: snapshotState === 'ready' ? 'ready' : snapshotState === 'building' ? 'preparing' : snapshotState === 'failed' ? 'failed' : dbtConfigured ? 'configured' : 'missing',
            message: preparationForSnapshot?.message ?? (snapshotState === 'ready'
              ? 'dbt metadata and governed search indexes are ready.'
              : snapshotState === 'stale'
                ? 'dbt metadata is configured; search indexes will be refreshed before governed Ask.'
                : undefined),
          },
        },
        capabilities: {
          warehouse: Boolean(connection),
          ai: Boolean(process.env.OPENAI_API_KEY || process.env.ANTHROPIC_API_KEY || process.env.GEMINI_API_KEY || process.env.OLLAMA_BASE_URL),
        },
      }));
      return;
    }

    if (req.method === 'POST' && path === '/api/onboarding/dbt/preview') {
      const requestId = apiRequestId('onboarding-dbt-preview');
      try {
        const preview = previewDbtOnboarding(await readJSON(req) as Record<string, unknown>);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, ...preview }));
      } catch (error) {
        const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: unknown }).code) : 'DBT_ARTIFACT_INVALID';
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Verify the dbt project and artifact paths, then preview again.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/onboarding/dbt/apply') {
      const requestId = apiRequestId('onboarding-dbt-apply');
      try {
        const applyStartedAt = Date.now();
        const body = await readJSON(req) as Record<string, unknown>;
        let preview;
        try {
          preview = previewDbtOnboarding(body);
        } catch (error) {
          const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: unknown }).code) : '';
          if (code !== 'DBT_MANIFEST_MISSING' || body.buildArtifacts !== true) throw error;
          const { dbtProjectDir } = onboardingDbtPaths(body);
          try {
            const { profilesDir } = onboardingDbtPaths(body);
            const parseArgs = buildDbtParseArgs(dbtProjectDir, profilesDir);
            execFileSync('dbt', parseArgs, {
              cwd: dbtProjectDir,
              timeout: 120_000,
              maxBuffer: 1024 * 1024,
              encoding: 'utf8',
              stdio: ['ignore', 'pipe', 'pipe'],
              env: { ...process.env, DBT_LOG_FORMAT: 'text' },
            });
          } catch (parseError) {
            throw Object.assign(new Error(`dbt parse failed. Run it in ${dbtProjectDir} to inspect the project error, then retry.`), { code: 'DBT_PARSE_FAILED', cause: parseError });
          }
          preview = previewDbtOnboarding(body);
        }
        const expectedFingerprint = typeof body.fingerprint === 'string'
          ? body.fingerprint
          : typeof body.expectedFingerprint === 'string' ? body.expectedFingerprint : undefined;
        if ((!expectedFingerprint && body.buildArtifacts !== true) || (expectedFingerprint && expectedFingerprint !== preview.fingerprint)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(apiErrorEnvelope({ requestId, code: 'SOURCE_CHANGED', message: 'dbt artifacts changed after preview. Review the refreshed preview before applying.', nextActions: ['Refresh the preview and review the new diff.'] })));
          return;
        }
        const validationDurationMs = Date.now() - applyStartedAt;
        const nextConfig: ProjectConfig = {
          ...projectConfig,
          manifestVersion: 3,
          // A warehouse-first project that adds dbt keeps its relation-bound
          // entities working beside the new dbt models (RFC 0007).
          modeling: { mode: modelingModeOf(projectConfig) === 'warehouse-first' || modelingModeOf(projectConfig) === 'hybrid' ? 'hybrid' : 'dbt-first' },
          dbt: {
            projectDir: preview.projectDir,
            manifestPath: preview.manifestPath,
            ...(preview.profilesDir ? { profilesDir: preview.profilesDir } : {}),
            ...(preview.repoUrl ? { repoUrl: preview.repoUrl, branch: preview.branch, subPath: preview.subPath } : {}),
          },
          semanticLayer: { provider: 'dbt', projectPath: preview.projectDir },
        };
        const configPath = join(projectRoot, 'dql.config.json');
        const previousConfigSource = readFileSync(configPath, 'utf8');
        const previousProjectConfig = projectConfig;
        const previousConnection = connection;
        const tempPath = `${configPath}.tmp-${process.pid}`;
        writeFileSync(tempPath, `${JSON.stringify(nextConfig, null, 2)}\n`, { encoding: 'utf8', mode: 0o600 });
        renameSync(tempPath, configPath);
        projectConfig = nextConfig;
        if (!configuredConnection) connection = resolveDbtProfileRuntimeConnection(projectRoot, nextConfig);
        projectSnapshots.invalidate();
        invalidateAgentProjectState(projectRoot);
        let snapshotId: string;
        let snapshotManifest: DQLManifest;
        const compileStartedAt = Date.now();
        try {
          const semanticReload = await reloadSemanticLayer();
          if (semanticReload.errors.length > 0) {
            throw new Error(`dbt semantic artifacts could not be loaded: ${semanticReload.errors.join('; ')}`);
          }
          const snapshot = projectSnapshot();
          snapshotId = snapshot.snapshotId;
          snapshotManifest = snapshot.manifest;
        } catch (error) {
          const rollbackPath = `${configPath}.rollback-${process.pid}`;
          writeFileSync(rollbackPath, previousConfigSource, { encoding: 'utf8', mode: 0o600 });
          renameSync(rollbackPath, configPath);
          projectConfig = previousProjectConfig;
          connection = previousConnection;
          projectSnapshots.invalidate();
          invalidateAgentProjectState(projectRoot);
          await reloadSemanticLayer();
          throw Object.assign(new Error(`dbt-first configuration did not compile and was rolled back: ${error instanceof Error ? error.message : String(error)}`), { code: 'SNAPSHOT_BUILD_FAILED' });
        }
        // An OSS version upgrade is acknowledged only after the user explicitly
        // previews and reapplies the saved dbt project. Record that successful
        // user-controlled compile without replacing their other preferences.
        const prefs = readUserPrefs(userPrefsPath);
        prefs.setup = {
          ...prefs.setup,
          dbtAppliedVersion: runtimeVersion,
          dbtAppliedAt: new Date().toISOString(),
        };
        writeUserPrefs(userPrefsPath, prefs);
        const preparation = startDbtPreparationJob({
          kind: 'dbt_prepare',
          snapshotId,
          manifest: snapshotManifest,
          validationDurationMs,
          compileDurationMs: Date.now() - compileStartedAt,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          requestId,
          applied: true,
          config: { manifestVersion: 3, modeling: nextConfig.modeling, dbt: nextConfig.dbt },
          fingerprint: preview.fingerprint,
          jobId: preparation.id,
          ...preparation,
        }));
      } catch (error) {
        const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: unknown }).code) : 'DBT_ARTIFACT_INVALID';
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Fix the reported dbt issue and run preview again.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/onboarding/refresh') {
      const requestId = apiRequestId('onboarding-refresh');
      const refreshStartedAt = Date.now();
      try {
        const body = await readJSON(req) as { expectedFingerprint?: string };
        const currentArtifact = previewDbtOnboarding({});
        if (!body.expectedFingerprint || body.expectedFingerprint !== currentArtifact.fingerprint) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(apiErrorEnvelope({ requestId, code: 'SOURCE_CHANGED', message: 'dbt artifacts changed before refresh. Review the current artifact preview.', nextActions: ['Return to the dbt preview step and review the refreshed fingerprint.'] })));
          return;
        }
        const validationDurationMs = Date.now() - refreshStartedAt;
        const compileStartedAt = Date.now();
        projectSnapshots.invalidate();
        await reloadSemanticLayer();
        const snapshot = projectSnapshot();
        invalidateAgentProjectState(projectRoot);
        const job = startDbtPreparationJob({
          kind: 'dbt_refresh',
          snapshotId: snapshot.snapshotId,
          manifest: snapshot.manifest,
          validationDurationMs,
          compileDurationMs: Date.now() - compileStartedAt,
        });
        res.writeHead(202, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, jobId: job.id, ...job }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code: 'SNAPSHOT_BUILD_FAILED', message: error instanceof Error ? error.message : String(error), nextActions: ['Keep using the previous snapshot while fixing compile diagnostics.'] })));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/onboarding/jobs/')) {
      const requestId = apiRequestId('onboarding-job');
      const id = decodeURIComponent(path.slice('/api/onboarding/jobs/'.length));
      const job = onboardingJobs.get(id);
      res.writeHead(job ? 200 : 404, { 'Content-Type': 'application/json; charset=utf-8' });
      const jobSnapshotId = typeof (job?.result as { snapshotId?: unknown } | undefined)?.snapshotId === 'string'
        ? String((job?.result as { snapshotId: string }).snapshotId)
        : undefined;
      res.end(serializeJSON(job ? { requestId, ...(jobSnapshotId ? { snapshotId: jobSnapshotId } : {}), ...job } : apiErrorEnvelope({ requestId, code: 'ONBOARDING_JOB_NOT_FOUND', message: `onboarding job not found: ${id}`, recoverable: false })));
      return;
    }

    if (req.method === 'DELETE' && path.startsWith('/api/onboarding/jobs/')) {
      const requestId = apiRequestId('onboarding-job-cancel');
      const id = decodeURIComponent(path.slice('/api/onboarding/jobs/'.length));
      const job = onboardingJobs.get(id);
      const cancelled = job ? {
        ...job,
        status: 'cancelled' as const,
        message: 'Stopped waiting for dbt preparation. The last valid snapshot remains available.',
        updatedAt: new Date().toISOString(),
        phases: job.phases.map((phase) => phase.status === 'running' ? { ...phase, status: 'cancelled' as const } : phase),
      } : undefined;
      if (cancelled) onboardingJobs.set(id, cancelled);
      res.writeHead(job ? 200 : 404, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(cancelled ? { requestId, ...cancelled } : apiErrorEnvelope({ requestId, code: 'ONBOARDING_JOB_NOT_FOUND', message: `onboarding job not found: ${id}`, recoverable: false })));
      return;
    }

    if (req.method === 'POST' && path === '/api/onboarding/domains/discover') {
      const requestId = apiRequestId('domain-discovery');
      try {
        const dbtManifestPath = resolveDbtManifestPath(projectRoot);
        if (!dbtManifestPath || !existsSync(dbtManifestPath)) throw Object.assign(new Error('No dbt manifest found. Run dbt parse or connect the project first.'), { code: 'DBT_MANIFEST_MISSING' });
        const report = discoverDbtDomains({ projectRoot, dbtManifestPath });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          requestId,
          snapshotId: projectSnapshot().snapshotId,
          ...report,
          capabilities: { aiEnrichment: false, deterministic: true },
        }));
      } catch (error) {
        const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: unknown }).code) : 'DBT_ARTIFACT_INVALID';
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Build a valid dbt manifest and retry discovery.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/onboarding/domains/apply') {
      const requestId = apiRequestId('domain-apply');
      try {
        const body = await readJSON(req) as { sourceFingerprint?: string; expectedSourceFingerprint?: string; selectedDomains?: unknown; domains?: unknown; proposals?: unknown; mode?: string };
        const dbtManifestPath = resolveDbtManifestPath(projectRoot);
        if (!dbtManifestPath || !existsSync(dbtManifestPath)) throw Object.assign(new Error('No dbt manifest found.'), { code: 'DBT_MANIFEST_MISSING' });
        const report = discoverDbtDomains({ projectRoot, dbtManifestPath });
        const expectedFingerprint = body.sourceFingerprint ?? body.expectedSourceFingerprint;
        if (!expectedFingerprint || expectedFingerprint !== report.sourceFingerprint) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: projectSnapshot().snapshotId, code: 'SOURCE_CHANGED', message: 'dbt/domain evidence changed after discovery. Review the refreshed proposals before applying.', nextActions: ['Run domain discovery again and review the updated evidence.'] })));
          return;
        }
        const proposalIds = Array.isArray(body.proposals) ? body.proposals.flatMap((value) => typeof value === 'object' && value && 'id' in value && typeof (value as { id?: unknown }).id === 'string' ? [(value as { id: string }).id] : []) : [];
        const requested = proposalIds.length > 0 ? proposalIds : Array.isArray(body.selectedDomains) ? body.selectedDomains : Array.isArray(body.domains) ? body.domains : report.proposals.map((proposal) => proposal.id);
        const selected = new Set(requested.filter((value): value is string => typeof value === 'string'));
        if (body.mode === 'preview') {
          const preview = report.proposals.filter((proposal) => selected.has(proposal.id)).map((proposal) => ({ path: join('domains', ...proposal.id.split('.'), 'domain.dql').replace(/\\/g, '/'), operation: 'create_or_retain', summary: `${proposal.matchedDbtUniqueIds.length} dbt model(s); review required` }));
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ requestId, snapshotId: projectSnapshot().snapshotId, applied: false, preview }));
          return;
        }
        const existing = loadDomainPackageRegistry(projectRoot);
        const applied: Array<{ id: string; status: string; path?: string; message: string }> = [];
        for (const proposal of report.proposals.filter((value) => selected.has(value.id))) {
          if (existing.get(proposal.id)) {
            applied.push({ id: proposal.id, status: 'existing', message: 'Existing Domain Package retained unchanged.' });
            continue;
          }
          const segments = proposal.id.split('.');
          if (segments.length === 0 || segments.some((segment) => !/^[a-z0-9_]+$/.test(segment))) {
            applied.push({ id: proposal.id, status: 'blocked', message: 'Domain id is not a safe normalized path.' });
            continue;
          }
          const sourcePath = join('domains', ...segments, 'domain.dql').replace(/\\/g, '/');
          const absolute = join(projectRoot, sourcePath);
          mkdirSync(dirname(absolute), { recursive: true });
          const dbtPaths = [...new Set(report.memberships.filter((membership) => membership.proposedDomain === proposal.id).flatMap((membership) => membership.sourcePath ? [membership.sourcePath] : []))].sort();
          const source = renderDomainDeclaration({
            id: proposal.id,
            name: proposal.name,
            parent: proposal.proposedParent,
            owner: proposal.owner,
            dbtPaths,
            description: 'Draft domain boundary proposed from cited dbt evidence; review before governance use.',
          });
          const temp = `${absolute}.tmp-${process.pid}`;
          writeFileSync(temp, source, { encoding: 'utf8', mode: 0o600 });
          renameSync(temp, absolute);
          applied.push({ id: proposal.id, status: 'created', path: sourcePath, message: 'Review-required domain boundary created; no relationships or skills were certified.' });
        }
        projectSnapshots.invalidate();
        invalidateAgentProjectState(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: projectSnapshot().snapshotId, applied: true, results: applied, domains: loadDomainPackageRegistry(projectRoot).values().map((pkg) => ({ id: pkg.id, filePath: pkg.declarationPath, lifecycle: 'draft' })) }));
      } catch (error) {
        const code = typeof error === 'object' && error && 'code' in error ? String((error as { code?: unknown }).code) : 'DOMAIN_COLLISION';
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Resolve the collision or invalid proposal and preview again.'] })));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/domain-packages') {
      const snapshot = projectSnapshot();
      const manifest = snapshot.manifest;
      const registry = loadDomainPackageRegistry(projectRoot);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        domains: listDomains(projectRoot),
        packages: registry.values().map((pkg) => ({
          id: pkg.id,
          name: pkg.name,
          parent: pkg.parent,
          depth: pkg.depth,
          ancestry: pkg.ancestry,
          declarationPath: pkg.declarationPath,
          root: relative(projectRoot, pkg.root).replace(/\\/g, '/'),
          owner: pkg.owner,
          exports: pkg.exports,
        })),
        modeling: manifest.modeling,
        dbtProvenance: manifest.dbtProvenance,
        domainAssets: collectDomainPackageAssets(projectRoot, registry),
        diagnostics: manifest.diagnostics ?? [],
        snapshot: { id: snapshot.snapshotId, stale: snapshot.stale, error: snapshot.error },
      }));
      return;
    }

    if (req.method === 'GET' && path === '/api/domain-workspaces') {
      const requestId = apiRequestId('domain-workspaces');
      const snapshot = projectSnapshot();
      const manifest = snapshot.manifest;
      const packages = Object.values(manifest.modeling?.packages ?? {});
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        requestId,
        snapshotId: snapshot.snapshotId,
        snapshot: { id: snapshot.snapshotId, stale: snapshot.stale, error: snapshot.error },
        domains: packages.map((pkg) => domainWorkspaceSummary(manifest, pkg.id)),
        unassignedModels: Object.values(manifest.dbtProvenance?.nodes ?? {}).filter((node) =>
          !Object.values(manifest.modeling?.entities ?? {}).some((entity) => entity.dbtUniqueId === node.uniqueId)
        ).length,
      }));
      return;
    }

    if (req.method === 'GET' && path === '/api/domain-workspaces/related-products') {
      const requestId = apiRequestId('domain-related-products');
      const snapshot = projectSnapshot();
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        requestId,
        domain: null,
        ...relatedProductsForDomain(snapshot.manifest, undefined, scanNotebookFiles(projectRoot)),
        snapshotId: snapshot.snapshotId,
      }));
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/domain-workspaces/')) {
      const requestId = apiRequestId('domain-workspace');
      const suffix = decodeURIComponent(path.slice('/api/domain-workspaces/'.length));
      const relatedSuffix = '/related-products';
      const knowledgeSuffix = '/knowledge';
      const domainId = suffix.endsWith(relatedSuffix)
        ? suffix.slice(0, -relatedSuffix.length)
        : suffix.endsWith(knowledgeSuffix)
          ? suffix.slice(0, -knowledgeSuffix.length)
          : suffix;
      const snapshot = projectSnapshot();
      const manifest = snapshot.manifest;
      if (!manifest.modeling?.packages[domainId]) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code: 'DOMAIN_NOT_FOUND', message: `domain workspace not found: ${domainId}`, recoverable: false })));
        return;
      }
      if (suffix.endsWith(knowledgeSuffix)) {
        await ensureMetadataCatalogFresh(projectRoot, { manifest, semanticLayer });
        const knowledge = readIndexedDomainKnowledge(projectRoot, domainId)
          ?? canonicalDomainKnowledge(manifest, domainId, snapshot.snapshotId);
        if (!knowledge) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code: 'DOMAIN_KNOWLEDGE_NOT_FOUND', message: `domain knowledge capsule not found: ${domainId}`, recoverable: false })));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, ...knowledge }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(suffix.endsWith(relatedSuffix)
        ? { requestId, domain: domainId, ...relatedProductsForDomain(manifest, domainId, scanNotebookFiles(projectRoot)), snapshotId: snapshot.snapshotId }
        : {
            requestId,
            snapshotId: snapshot.snapshotId,
            ...domainWorkspaceSummary(manifest, domainId),
            relatedProducts: relatedProductsForDomain(manifest, domainId),
            snapshot: { id: snapshot.snapshotId, stale: snapshot.stale, error: snapshot.error },
          }));
      return;
    }

    // Manifest v3 modeling surface. This response intentionally contains dbt
    // provenance references and the sparse DQL overlay, never copied dbt YAML.
    if (req.method === 'GET' && path === '/api/modeling/dbt-first') {
      const requestId = apiRequestId('modeling-dbt-first');
      const modelingMode = modelingModeOf(projectConfig);
      const modelingEnabled = modelingMode !== undefined;
      if (!modelingEnabled) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          code: 'DBT_FIRST_NOT_ENABLED',
          message: 'dbt-first modeling is not enabled. Connect and apply a dbt project from Settings → Project & dbt.',
          details: {
            manifestVersion: projectConfig.manifestVersion ?? 2,
            modelingMode: projectConfig.modeling?.mode ?? null,
          },
          nextActions: ['Open Settings → Project & dbt and apply a valid dbt project.'],
        })));
        return;
      }

      const dbtProjectDir = findDbtProjectPath(projectRoot, projectConfig);
      const configuredManifestPath = projectConfig.dbt?.manifestPath ?? 'target/manifest.json';
      const expectedManifestPath = resolve(dbtProjectDir, configuredManifestPath);
      // Only dbt-first modeling needs a dbt manifest; warehouse-first and
      // hybrid modeling compile from the warehouse catalog snapshot.
      if (modelingMode === 'dbt-first' && !existsSync(expectedManifestPath)) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          code: 'DBT_MANIFEST_NOT_FOUND',
          message: `The configured dbt manifest was not found at ${configuredManifestPath}.`,
          details: {
            projectDir: projectConfig.dbt?.projectDir ?? portableProjectPath(projectRoot, dbtProjectDir),
            manifestPath: configuredManifestPath,
          },
          nextActions: ['Run dbt parse, dbt compile, or dbt build in the configured dbt project, then refresh Domain Studio.'],
        })));
        return;
      }

      let snapshot: ReturnType<typeof projectSnapshot>;
      try {
        snapshot = projectSnapshot();
      } catch (error) {
        res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          code: 'DBT_MANIFEST_COMPILE_FAILED',
          message: apiErrorMessage(error),
          details: { manifestPath: configuredManifestPath },
          nextActions: ['Fix or rebuild the dbt manifest, then refresh Domain Studio.'],
        })));
        return;
      }
      const manifest = snapshot.manifest;
      if (manifest.manifestVersion !== 3 || !manifest.modeling || !manifest.dbtProvenance) {
        res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          snapshotId: snapshot.snapshotId,
          code: 'DBT_MANIFEST_COMPILE_FAILED',
          message: snapshot.error ?? 'DQL could not compile Domain Studio from the configured dbt manifest.',
          details: { manifestPath: configuredManifestPath },
          nextActions: ['Review the dbt artifact and DQL compile diagnostics, rebuild the dbt manifest, then refresh Domain Studio.'],
        })));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        requestId,
        snapshotId: snapshot.snapshotId,
        manifestVersion: manifest.manifestVersion,
        dbtProvenance: manifest.dbtProvenance,
        modeling: manifest.modeling,
        domainAssets: collectDomainPackageAssets(projectRoot, loadDomainPackageRegistry(projectRoot)),
        lineage: manifest.lineage,
        diagnostics: manifest.diagnostics ?? [],
        snapshot: { id: snapshot.snapshotId, stale: snapshot.stale, error: snapshot.error },
      }));
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/modeling/dbt-first/nodes/')) {
      const requestId = apiRequestId('modeling-node');
      const uniqueId = decodeURIComponent(path.slice('/api/modeling/dbt-first/nodes/'.length));
      const snapshot = projectSnapshot();
      const detail = await nodeDetailWithColumns(snapshot.snapshotId, uniqueId);
      if (!detail) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code: 'DBT_NODE_NOT_FOUND', message: `dbt node not found: ${uniqueId}`, recoverable: false })));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ requestId, snapshotId: snapshot.snapshotId, ...detail }));
      return;
    }

    if (req.method === 'GET' && path === '/api/modeling/dbt-first/inventory') {
      const requestId = apiRequestId('modeling-inventory');
      const physicalOnly = url.searchParams.get('physicalOnly') === 'true';
      const modelingMode = modelingModeOf(projectConfig);
      const modelingEnabled = modelingMode !== undefined;
      if (physicalOnly && !modelingEnabled) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          code: 'DBT_FIRST_NOT_ENABLED',
          message: 'dbt-first modeling is not enabled. Connect and apply a dbt project from Settings → Project & dbt.',
          nextActions: ['Open Settings → Project & dbt and apply a valid dbt project.'],
        })));
        return;
      }
      const dbtProjectDir = findDbtProjectPath(projectRoot, projectConfig);
      const configuredManifestPath = projectConfig.dbt?.manifestPath ?? 'target/manifest.json';
      const expectedManifestPath = resolve(dbtProjectDir, configuredManifestPath);
      if (physicalOnly && modelingMode === 'dbt-first' && !existsSync(expectedManifestPath)) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          code: 'DBT_MANIFEST_NOT_FOUND',
          message: `The configured dbt manifest was not found at ${configuredManifestPath}.`,
          details: { manifestPath: configuredManifestPath },
          nextActions: ['Run dbt parse, dbt compile, or dbt build, then refresh the database catalog.'],
        })));
        return;
      }
      let snapshot: ReturnType<typeof projectSnapshot>;
      if (physicalOnly) {
        try {
          snapshot = projectSnapshot();
        } catch (error) {
          res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(apiErrorEnvelope({
            requestId,
            code: 'DBT_MANIFEST_COMPILE_FAILED',
            message: apiErrorMessage(error),
            details: { manifestPath: configuredManifestPath },
            nextActions: ['Fix or rebuild the dbt manifest, then refresh the database catalog.'],
          })));
          return;
        }
      } else {
        snapshot = projectSnapshot();
      }
      const manifest = snapshot.manifest;
      if (physicalOnly && (manifest.manifestVersion !== 3 || !manifest.modeling || !manifest.dbtProvenance)) {
        res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          snapshotId: snapshot.snapshotId,
          code: 'DBT_MANIFEST_COMPILE_FAILED',
          message: snapshot.error ?? 'DQL could not compile the dbt database catalog.',
          details: { manifestPath: configuredManifestPath },
          nextActions: ['Review the dbt artifact, rebuild it, then refresh the database catalog.'],
        })));
        return;
      }
      // PERF-001 / CTX-005: only the Database browser opts into the smaller,
      // physical-relation contract. Existing modeling consumers retain their
      // original inventory scope and pagination defaults.
      const maxLimit = physicalOnly ? 100 : 200;
      const defaultLimit = physicalOnly ? 25 : 50;
      const limit = Math.min(maxLimit, Math.max(1, Number(url.searchParams.get('limit')) || defaultLimit));
      const cursor = Math.max(0, Number(url.searchParams.get('cursor')) || 0);
      const query = (url.searchParams.get('q') ?? '').trim().toLowerCase();
      const queryTokens = query.split(/[^a-z0-9]+/).filter(Boolean);
      const domain = (url.searchParams.get('domain') ?? '').trim();
      const boundByDbtId = new Map(Object.values(manifest.modeling?.entities ?? {}).map((entity) => [entity.dbtUniqueId, entity]));
      const physicalIds = physicalOnly && existsSync(expectedManifestPath) ? physicalDbtRelationIds(expectedManifestPath) : undefined;
      const nodes = Object.values(manifest.dbtProvenance?.nodes ?? {})
        // A warehouse relation is physical by construction.
        .filter((node) => !physicalOnly || (Boolean(node.relation) && (node.resourceType === 'warehouse' || !physicalIds || physicalIds.has(node.uniqueId))))
        .filter((node) => {
          if (!queryTokens.length) return true;
          const haystack = `${node.name} ${node.uniqueId} ${node.relation ?? ''} ${node.sourcePath ?? ''}`.toLowerCase();
          return queryTokens.every((token) => haystack.includes(token));
        })
        .filter((node) => !domain || boundByDbtId.get(node.uniqueId)?.domain === domain)
        .sort((a, b) => {
          if (!query) return a.uniqueId.localeCompare(b.uniqueId);
          const score = (node: typeof a) => {
            const name = node.name.toLowerCase();
            const uniqueId = node.uniqueId.toLowerCase();
            let value = name === query || uniqueId === query ? 1_000 : 0;
            if (name.startsWith(query)) value += 500;
            if (uniqueId.startsWith(query)) value += 300;
            if (name.includes(query)) value += 200;
            value += queryTokens.reduce((total, token) => total + (name.startsWith(token) ? 80 : name.includes(token) ? 40 : 10), 0);
            return value;
          };
          return score(b) - score(a) || a.uniqueId.localeCompare(b.uniqueId);
        });
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        requestId,
        items: nodes.slice(cursor, cursor + limit).map((node) => ({ ...node, binding: boundByDbtId.get(node.uniqueId) })),
        nextCursor: cursor + limit < nodes.length ? cursor + limit : null,
        total: nodes.length,
        snapshotId: snapshot.snapshotId,
        ...(physicalOnly ? {
          manifestPath: manifest.dbtProvenance!.manifestPath,
          projectName: manifest.dbtProvenance!.projectName,
          scope: modelingMode === 'dbt-first' ? 'dbt_relations' : 'warehouse_relations',
        } : {}),
      }));
      return;
    }

    if (req.method === 'POST' && path === '/api/modeling/dbt-first/nodes/batch') {
      const requestId = apiRequestId('modeling-node-batch');
      const body = await readJSON(req) as { uniqueIds?: unknown };
      const uniqueIds = Array.isArray(body.uniqueIds) ? body.uniqueIds.filter((value): value is string => typeof value === 'string').slice(0, 100) : [];
      const snapshot = projectSnapshot();
      const details = (await Promise.all(uniqueIds.map((uniqueId) => nodeDetailWithColumns(snapshot.snapshotId, uniqueId)))).filter(Boolean);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ requestId, details, snapshotId: snapshot.snapshotId }));
      return;
    }

    if (req.method === 'GET' && path === '/api/modeling/dbt-first/neighborhood') {
      const requestId = apiRequestId('modeling-neighborhood');
      const snapshot = projectSnapshot();
      const manifest = snapshot.manifest;
      const entityRef = url.searchParams.get('entity') ?? '';
      const limit = Math.min(200, Math.max(1, Number(url.searchParams.get('limit')) || 200));
      const entities = manifest.modeling?.entities ?? {};
      const relationships = manifest.modeling?.relationships ?? {};
      const entityKey = entities[entityRef] ? entityRef : Object.entries(entities).find(([, entity]) => entity.qualifiedId === entityRef)?.[0];
      if (!entityKey) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code: 'MODELING_ENTITY_NOT_FOUND', message: `modeling entity not found: ${entityRef}`, recoverable: false })));
        return;
      }
      const edges = Object.values(relationships).filter((relationship) => relationship.from === entityKey || relationship.to === entityKey).slice(0, limit);
      const keys = new Set([entityKey, ...edges.flatMap((edge) => [edge.from, edge.to])]);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        requestId,
        entities: Object.fromEntries([...keys].flatMap((key) => entities[key] ? [[key, entities[key]]] : [])),
        relationships: Object.fromEntries(edges.map((edge) => [edge.qualifiedId, edge])),
        snapshotId: snapshot.snapshotId,
      }));
      return;
    }

    if (req.method === 'POST' && path === '/api/modeling/dbt-first/imports') {
      const requestId = apiRequestId('modeling-import');
      try {
        const body = await readJSON(req) as Record<string, unknown>;
        const source = body.source && typeof body.source === 'object' ? body.source as Record<string, unknown> : body;
        const session = createModelingImportSession(projectRoot, gitRoot, loopback, source);
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, session: publicModelingImportSession(session) }));
      } catch (error) {
        const code = apiErrorCode(error, 'MODELING_IMPORT_INVALID');
        res.writeHead(code === 'PATH_ACCESS_FORBIDDEN' ? 403 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Choose DQL or dbt YAML from the current Git workspace, or paste/upload the YAML.'] })));
      }
      return;
    }

    const modelingImportMatch = path.match(/^\/api\/modeling\/dbt-first\/imports\/([^/]+)$/);
    if (req.method === 'GET' && modelingImportMatch) {
      const session = readModelingImportSession(projectRoot, decodeURIComponent(modelingImportMatch[1]!));
      if (!session) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Modeling import session not found.', code: 'MODELING_IMPORT_NOT_FOUND' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ session: publicModelingImportSession(session) }));
      return;
    }

    const modelingImportPreviewMatch = path.match(/^\/api\/modeling\/dbt-first\/imports\/([^/]+)\/preview$/);
    if (req.method === 'POST' && modelingImportPreviewMatch) {
      const requestId = apiRequestId('modeling-import-preview');
      try {
        const session = readModelingImportSession(projectRoot, decodeURIComponent(modelingImportPreviewMatch[1]!));
        if (!session) throw Object.assign(new Error('Modeling import session not found.'), { code: 'MODELING_IMPORT_NOT_FOUND' });
        const body = await readJSON(req) as Record<string, unknown>;
        const snapshot = projectSnapshot();
        const selectedCandidateIds = Array.isArray(body.selectedCandidateIds)
          ? body.selectedCandidateIds.filter((value): value is string => typeof value === 'string')
          : session.candidates.filter((candidate) => candidate.dialect !== 'unsupported' && candidate.action !== 'open_existing').map((candidate) => candidate.id);
        // An unspecified scope is defaulted, not rejected: the proposal carries
        // the `upsert_domain`/`upsert_area` patches so the author reviews the
        // scope alongside the models it will hold.
        const domain = typeof body.domain === 'string' && body.domain.trim()
          ? body.domain.trim()
          : defaultAuthoringDomainId(snapshot.manifest);
        const areaId = typeof body.areaId === 'string' && body.areaId.trim() ? body.areaId.trim() : DEFAULT_MODEL_AREA_ID;
        const planned = modelingImportOperations(session, selectedCandidateIds, domain, areaId, snapshot.manifest);
        const proposal = previewContextAuthoring({
          origin: 'yaml_import',
          operations: planned.operations,
          expectedSnapshotId: typeof body.expectedSnapshotId === 'string' ? body.expectedSnapshotId : snapshot.snapshotId,
          diagnostics: planned.diagnostics,
        });
        const updated = { ...session, proposalId: proposal.id, updatedAt: new Date().toISOString() };
        writeModelingImportSession(projectRoot, updated);
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, session: publicModelingImportSession(updated), proposal }));
      } catch (error) {
        const code = apiErrorCode(error, 'MODELING_IMPORT_PREVIEW_FAILED');
        res.writeHead(code === 'MODELING_IMPORT_NOT_FOUND' ? 404 : code === 'PROPOSAL_STALE' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Resolve unmatched models or choose another Domain and Area, then preview again.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/context-proposals') {
      const requestId = apiRequestId('context-proposal');
      try {
        const body = await readJSON(req) as Record<string, unknown>;
        const origin = parseContextAuthoringOrigin(body.origin);
        const operations = parseContextAuthoringOperations(body.operations);
        const proposal = previewContextAuthoring({
          origin,
          operations,
          expectedSnapshotId: typeof body.expectedSnapshotId === 'string' ? body.expectedSnapshotId : undefined,
          sourceRunId: typeof body.sourceRunId === 'string' ? body.sourceRunId : undefined,
          sourceArtifactId: typeof body.sourceArtifactId === 'string' ? body.sourceArtifactId : undefined,
          revision: typeof body.revision === 'number' ? body.revision : undefined,
        });
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, proposal }));
      } catch (error) {
        const code = apiErrorCode(error, 'PROPOSAL_INVALID');
        res.writeHead(code === 'PROPOSAL_STALE' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Refresh Modeling and preview the proposal again.'] })));
      }
      return;
    }

    const contextProposalMatch = path.match(/^\/api\/context-proposals\/([^/]+)$/);
    if (req.method === 'GET' && contextProposalMatch) {
      const id = decodeURIComponent(contextProposalMatch[1]!);
      const proposal = contextProposalStore.get(id);
      if (!proposal) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Context proposal not found.', code: 'PROPOSAL_NOT_FOUND' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ proposal }));
      return;
    }

    const contextRepreviewMatch = path.match(/^\/api\/context-proposals\/([^/]+)\/repreview$/);
    if (req.method === 'POST' && contextRepreviewMatch) {
      const requestId = apiRequestId('context-repreview');
      try {
        const current = contextProposalStore.get(decodeURIComponent(contextRepreviewMatch[1]!));
        if (!current) throw Object.assign(new Error('Context proposal not found.'), { code: 'PROPOSAL_NOT_FOUND' });
        const body = await readJSON(req) as { selectedOperationIds?: unknown; rebase?: unknown };
        const selected = Array.isArray(body.selectedOperationIds)
          ? body.selectedOperationIds.filter((value): value is string => typeof value === 'string')
          : current.operations.map((operation) => operation.id);
        const operations = contextAuthoringDependencyClosure(current.operations, selected);
        const proposal = previewContextAuthoring({
          origin: current.origin,
          operations,
          expectedSnapshotId: body.rebase === true ? projectSnapshot().snapshotId : current.baseSnapshotId,
          sourceRunId: current.sourceRunId,
          sourceArtifactId: current.sourceArtifactId,
          revision: (current.revision ?? 1) + 1,
        });
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, proposal }));
      } catch (error) {
        const code = apiErrorCode(error, 'PROPOSAL_INVALID');
        res.writeHead(code === 'PROPOSAL_STALE' ? 409 : code === 'PROPOSAL_NOT_FOUND' ? 404 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Refresh the proposal against the latest project snapshot.'] })));
      }
      return;
    }

    const contextCommitMatch = path.match(/^\/api\/context-proposals\/([^/]+)\/commit$/);
    if (req.method === 'POST' && contextCommitMatch) {
      const requestId = apiRequestId('context-commit');
      const proposalId = decodeURIComponent(contextCommitMatch[1]!);
      try {
        const proposal = contextProposalStore.get(proposalId);
        if (!proposal) throw Object.assign(new Error('Context proposal not found.'), { code: 'PROPOSAL_NOT_FOUND' });
        const body = await readJSON(req) as Record<string, unknown>;
        const unexpected = Object.keys(body).filter((key) => key !== 'expectedProposalHash' && key !== 'idempotencyKey');
        if (unexpected.length) throw Object.assign(new Error('Commit accepts only expectedProposalHash and idempotencyKey.'), { code: 'INVALID_REQUEST' });
        const expectedProposalHash = typeof body.expectedProposalHash === 'string' ? body.expectedProposalHash : '';
        const idempotencyKey = typeof body.idempotencyKey === 'string' ? body.idempotencyKey.trim() : '';
        if (!expectedProposalHash || !idempotencyKey) throw Object.assign(new Error('The reviewed proposal hash and idempotency key are required.'), { code: 'INVALID_REQUEST' });
        const receipt = contextProposalStore.getCommitReceipt(idempotencyKey);
        if (receipt) {
          if (receipt.proposalId !== proposal.id || receipt.proposalHash !== expectedProposalHash) throw Object.assign(new Error('The idempotency key belongs to another reviewed proposal request.'), { code: 'IDEMPOTENCY_CONFLICT' });
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ requestId, proposal: contextProposalStore.get(proposal.id), snapshotId: receipt.snapshotId, idempotent: true }));
          return;
        }
        if (proposal.status !== 'proposed') throw Object.assign(new Error('Only a proposed change can be committed.'), { code: 'PROPOSAL_STALE' });
        if (proposal.proposalHash !== expectedProposalHash) throw Object.assign(new Error('The proposal changed after review.'), { code: 'PROPOSAL_STALE' });
        if (proposal.diagnostics.some((diagnostic) => diagnostic.severity === 'blocking')) throw Object.assign(new Error('Resolve all blocking proposal diagnostics before saving.'), { code: 'PROPOSAL_BLOCKED' });
        const beforeSnapshot = projectSnapshot();
        if (beforeSnapshot.snapshotId !== proposal.baseSnapshotId) throw Object.assign(new Error('Project sources changed after this proposal was reviewed.'), { code: 'PROPOSAL_STALE' });
        const resolvedPatches = proposal.patches.map((patch) => ({ patch, absolute: resolveContextPatchPath(projectRoot, gitRoot, patch.path) }));
        for (const { patch, absolute } of resolvedPatches) {
          const current = existsSync(absolute) ? readFileSync(absolute, 'utf8') : '';
          if (current !== patch.before) throw Object.assign(new Error(`Source changed after preview: ${patch.path}`), { code: 'SOURCE_CHANGED' });
        }
        const written: Array<{ patch: ContextAuthoringPatchV1; absolute: string }> = [];
        try {
          for (const item of resolvedPatches) {
            if (!item.patch.changed) continue;
            if (!item.patch.after) rmSync(item.absolute, { force: true });
            else {
              mkdirSync(dirname(item.absolute), { recursive: true });
              writeFileSync(item.absolute, item.patch.after, 'utf8');
            }
            written.push(item);
          }
          projectSnapshots.invalidate();
          invalidateAgentProjectState(projectRoot);
          const nextSnapshot = projectSnapshot();
          if (nextSnapshot.error) throw Object.assign(new Error(nextSnapshot.error), { code: 'COMPILE_FAILED' });
          await refreshUnifiedProjectIndexes(projectRoot);
          const committed: ContextAuthoringProposalV1 = { ...proposal, status: 'committed', committedAt: new Date().toISOString(), committedSnapshotId: nextSnapshot.snapshotId };
          contextProposalStore.save(committed);
          contextProposalStore.saveCommitReceipt(idempotencyKey, { proposalId: proposal.id, proposalHash: proposal.proposalHash, snapshotId: nextSnapshot.snapshotId });
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ requestId, proposal: committed, snapshotId: nextSnapshot.snapshotId, modeling: nextSnapshot.manifest.modeling }));
        } catch (error) {
          for (const { patch, absolute } of written.reverse()) {
            if (!patch.before) rmSync(absolute, { force: true });
            else {
              mkdirSync(dirname(absolute), { recursive: true });
              writeFileSync(absolute, patch.before, 'utf8');
            }
          }
          projectSnapshots.invalidate();
          invalidateAgentProjectState(projectRoot);
          contextProposalStore.save(proposal);
          contextProposalStore.deleteCommitReceipt(idempotencyKey);
          throw error;
        }
      } catch (error) {
        const code = apiErrorCode(error, /changed after/i.test(apiErrorMessage(error)) ? 'SOURCE_CHANGED' : 'PROPOSAL_COMMIT_FAILED');
        const status = code === 'PROPOSAL_NOT_FOUND' ? 404 : ['PROPOSAL_STALE', 'SOURCE_CHANGED', 'IDEMPOTENCY_CONFLICT', 'OWNERSHIP_CONFLICT', 'DEPENDENCY_CONFLICT'].includes(code) ? 409 : code === 'PROPOSAL_BLOCKED' ? 422 : 400;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error), nextActions: ['Rebase or repreview the proposal before saving.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/modeling/dbt-first/dbt-source/preview') {
      const requestId = apiRequestId('modeling-dbt-source-preview');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req) as { change?: DbtSourceAuthoringInput; expectedSnapshotId?: string };
        if (!body.change) throw Object.assign(new Error('A dbt source change is required.'), { code: 'INVALID_REQUEST' });
        if (body.expectedSnapshotId && body.expectedSnapshotId !== snapshot.snapshotId) {
          throw Object.assign(new Error('Project sources changed after the model was loaded.'), { code: 'SOURCE_CHANGED' });
        }
        const { dbtProjectDir, manifestPath } = onboardingDbtPaths({});
        const preview = previewDbtSourcePatch(dbtProjectDir, manifestPath, body.change);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: snapshot.snapshotId, ...preview }));
      } catch (error) {
        const code = apiErrorCode(error, 'DBT_SOURCE_PATCH_INVALID');
        res.writeHead(code === 'SOURCE_CHANGED' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code, message: apiErrorMessage(error), nextActions: ['Refresh the model and review the dbt YAML source patch again.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/modeling/dbt-first/dbt-source/apply') {
      const requestId = apiRequestId('modeling-dbt-source-apply');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req) as { change?: DbtSourceAuthoringInput; fingerprint?: string; expectedFingerprint?: string; expectedSnapshotId?: string };
        if (!body.change) throw Object.assign(new Error('A dbt source change is required.'), { code: 'INVALID_REQUEST' });
        if (!body.expectedSnapshotId || body.expectedSnapshotId !== snapshot.snapshotId) {
          throw Object.assign(new Error('Project sources changed after the source patch preview.'), { code: 'SOURCE_CHANGED' });
        }
        const expectedFingerprint = body.expectedFingerprint ?? body.fingerprint;
        if (!expectedFingerprint) throw Object.assign(new Error('The reviewed source patch fingerprint is required.'), { code: 'SOURCE_CHANGED' });
        const { dbtProjectDir, manifestPath } = onboardingDbtPaths({});
        const applied = applyDbtSourcePatch(dbtProjectDir, manifestPath, body.change, expectedFingerprint);
        projectSnapshots.invalidate();
        invalidateAgentProjectState(projectRoot);
        const nextSnapshot = projectSnapshot();
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: nextSnapshot.snapshotId, applied }));
      } catch (error) {
        const inferred = /changed after the preview/i.test(apiErrorMessage(error)) ? 'SOURCE_CHANGED' : 'DBT_SOURCE_PATCH_INVALID';
        const code = apiErrorCode(error, inferred);
        res.writeHead(code === 'SOURCE_CHANGED' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code, message: apiErrorMessage(error), nextActions: ['Refresh the source patch preview before applying.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/modeling/dbt-first/preview') {
      const requestId = apiRequestId('modeling-preview');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req) as { change?: ModelingAuthoringChange; expectedSnapshotId?: string };
        if (!body.change) throw new Error('A modeling change is required.');
        if (body.expectedSnapshotId && body.expectedSnapshotId !== snapshot.snapshotId) throw Object.assign(new Error('Project sources changed after the model was loaded.'), { code: 'SOURCE_CHANGED' });
        const preview = previewModelingChange(projectRoot, body.change);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: snapshot.snapshotId, ...preview }));
      } catch (error) {
        const code = apiErrorCode(error, 'MODELING_CHANGE_INVALID');
        res.writeHead(code === 'SOURCE_CHANGED' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code, message: apiErrorMessage(error), nextActions: ['Refresh Domain Studio and preview the change again.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/modeling/dbt-first/apply') {
      const requestId = apiRequestId('modeling-apply');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req) as { change?: ModelingAuthoringChange; fingerprint?: string; expectedSnapshotId?: string };
        if (!body.change) throw new Error('A modeling change is required.');
        if (!body.expectedSnapshotId || body.expectedSnapshotId !== snapshot.snapshotId) throw Object.assign(new Error('Project sources changed after the modeling preview.'), { code: 'SOURCE_CHANGED' });
        if (!body.fingerprint) throw Object.assign(new Error('The reviewed modeling source fingerprint is required.'), { code: 'SOURCE_CHANGED' });
        const applied = applyModelingChange(projectRoot, body.change, body.fingerprint);
        projectSnapshots.invalidate();
        const nextSnapshot = projectSnapshot();
        const manifest = nextSnapshot.manifest;
        await refreshUnifiedProjectIndexes(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: nextSnapshot.snapshotId, applied, modeling: manifest.modeling, diagnostics: manifest.diagnostics ?? [] }));
      } catch (error) {
        const inferred = /changed after the preview/i.test(apiErrorMessage(error)) ? 'SOURCE_CHANGED' : 'MODELING_APPLY_FAILED';
        const code = apiErrorCode(error, inferred);
        res.writeHead(code === 'SOURCE_CHANGED' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code, message: apiErrorMessage(error), nextActions: ['Refresh Domain Studio and review the latest source diff.'] })));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/modeling/dbt-first/relationships/validate') {
      const requestId = apiRequestId('modeling-relationship-validate');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req) as { relationship?: RelationshipAuthoringInput; expectedSnapshotId?: string };
        if (!body.relationship) throw new Error('A relationship is required.');
        if (!body.expectedSnapshotId || body.expectedSnapshotId !== snapshot.snapshotId) throw Object.assign(new Error('Project sources changed before relationship validation.'), { code: 'SOURCE_CHANGED' });
        const manifest = snapshot.manifest;
        const activeConnection = await resolveExecutionConnection(body as Record<string, unknown>);
        const evidence = await validateModelingRelationship(
          body.relationship,
          manifest,
          (sql) => executor.executeQuery(sql, [], {}, activeConnection),
          (identifier) => getDialect(activeConnection.driver).quoteIdentifier(identifier),
          projectRoot,
        );
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: snapshot.snapshotId, evidence }));
      } catch (error) {
        const code = apiErrorCode(error, 'RELATIONSHIP_VALIDATION_FAILED');
        res.writeHead(code === 'SOURCE_CHANGED' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code, message: apiErrorMessage(error), nextActions: ['Refresh the model or configure a warehouse connection, then retry validation.'] })));
      }
      return;
    }

    // The relationship builder checks a join before anyone picks a
    // cardinality: one statement, the cardinality the data shows, and evidence
    // for that proposal so saving it saves a matching proof.
    if (req.method === 'POST' && path === '/api/modeling/dbt-first/relationships/profile') {
      const requestId = apiRequestId('modeling-relationship-profile');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req) as { relationship?: { from?: string; to?: string; keys?: Array<{ from: string; to: string }> }; expectedSnapshotId?: string };
        const relationship = body.relationship;
        const keys = (relationship?.keys ?? []).filter((key) => key?.from && key?.to);
        if (!relationship?.from || !relationship.to || keys.length === 0) throw new Error('Choose both models and at least one pair of matching columns.');
        if (!body.expectedSnapshotId || body.expectedSnapshotId !== snapshot.snapshotId) throw Object.assign(new Error('Project sources changed before the warehouse check.'), { code: 'SOURCE_CHANGED' });
        const { fromRelation, toRelation } = relationshipRelations(snapshot.manifest, relationship.from, relationship.to);
        const activeConnection = await resolveExecutionConnection(body as Record<string, unknown>);
        const spec = { fromRelation, toRelation, keys };
        const profile = await profileRelationshipOnWarehouse(
          { ...spec, keyTypes: catalogKeyTypes(snapshot.manifest, spec, undefined, projectRoot) },
          (sql) => executor.executeQuery(sql, [], {}, activeConnection),
          (identifier) => getDialect(activeConnection.driver).quoteIdentifier(identifier),
        );
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: snapshot.snapshotId, ...profile }));
      } catch (error) {
        const code = apiErrorCode(error, 'RELATIONSHIP_PROFILE_FAILED');
        res.writeHead(code === 'SOURCE_CHANGED' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code, message: apiErrorMessage(error), nextActions: ['Check the matching columns or configure a warehouse connection, then check again.'] })));
      }
      return;
    }

    // Modeling → "Model my warehouse": turn on warehouse modeling (RFC 0007).
    // A project without modeling becomes warehouse-first; a dbt-first one
    // becomes hybrid only when asked to explicitly. Nothing else in
    // dql.config.json changes.
    if (req.method === 'POST' && path === '/api/modeling/warehouse/enable') {
      const requestId = apiRequestId('modeling-warehouse-enable');
      try {
        const body = await readJSON(req).catch(() => ({})) as { mode?: string };
        const current = modelingModeOf(loadProjectConfig(projectRoot));
        const requested = body.mode === 'hybrid' ? 'hybrid' : 'warehouse-first';
        if (current === 'dbt-first' && requested !== 'hybrid') {
          throw Object.assign(new Error('This project models dbt. Choose hybrid to add warehouse tables that dbt does not cover.'), { code: 'MODELING_MODE_CONFLICT' });
        }
        const next = current === 'warehouse-first' || current === 'hybrid' ? current : requested;
        if (next !== current) {
          const configPath = join(projectRoot, 'dql.config.json');
          const raw = existsSync(configPath) ? JSON.parse(readFileSync(configPath, 'utf-8')) as Record<string, unknown> : {};
          const modeling = raw.modeling && typeof raw.modeling === 'object' && !Array.isArray(raw.modeling) ? raw.modeling as Record<string, unknown> : {};
          raw.manifestVersion = 3;
          raw.modeling = { ...modeling, mode: next };
          writeFileSync(configPath, JSON.stringify(raw, null, 2) + '\n', 'utf-8');
          projectConfig = loadProjectConfig(projectRoot);
          projectSnapshots.invalidate();
        }
        const cfg = loadProjectConfig(projectRoot);
        const catalog = warehouseCatalogStatus(projectRoot, cfg, warehouseCatalogConnectionId(cfg));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, mode: next, changed: next !== current, connectionId: warehouseCatalogConnectionId(cfg), ...(catalog ? { warehouseCatalog: catalog } : {}) }));
      } catch (error) {
        const code = apiErrorCode(error, 'MODELING_MODE_INVALID');
        res.writeHead(code === 'MODELING_MODE_CONFLICT' ? 409 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, code, message: apiErrorMessage(error) })));
      }
      return;
    }

    // Modeling → Draft from warehouse: the runtime drafts the map and opens it
    // as an ordinary reviewable proposal. The operations, and any validation
    // evidence on them, come from this server's own discovery run, never from
    // the browser.
    if (req.method === 'POST' && path === '/api/modeling/warehouse/discover/proposal') {
      const requestId = apiRequestId('modeling-warehouse-proposal');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req).catch(() => ({})) as { validate?: boolean; queryHistory?: boolean; domain?: string; expectedSnapshotId?: string };
        if (body.expectedSnapshotId && body.expectedSnapshotId !== snapshot.snapshotId) {
          throw Object.assign(new Error('Project sources changed. Refresh Modeling and draft again.'), { code: 'PROPOSAL_STALE' });
        }
        const report = await discoverProjectWarehouseModel(projectRoot, { manifest: snapshot.manifest, domain: body.domain, validate: body.validate === true, queryHistory: body.queryHistory === true, executor });
        // New Domains and subject areas are created by the proposal's own scope
        // step, as for dbt discovery, so the batch stays in dependency order.
        // A drafted join lives in the subject area of the entity it starts
        // from, as the Modeling editor writes it, so a later edit updates it
        // in place instead of adding a second copy. New entities land in the
        // default area.
        const areaOfEntity = new Map(Object.values(snapshot.manifest.modeling?.entities ?? {}).map((entity) => [`${entity.domain}::${entity.localId ?? entity.id}`, entity.areaId?.split('::').pop()]));
        const changes = warehouseDiscoveryChanges(report)
          .filter((change) => change.operation !== 'upsert_domain')
          .map((change): ModelingAuthoringChange => change.operation === 'upsert_relationship' && !change.value.areaId
            ? { ...change, value: { ...change.value, areaId: areaOfEntity.get(`${change.value.domain}::${change.value.from}`) ?? DEFAULT_MODEL_AREA_ID } }
            : change);
        if (changes.length === 0) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ requestId, report, proposal: null }));
          return;
        }
        const evidenceFor = (change: ModelingAuthoringChange): string[] => {
          if (change.operation === 'upsert_entity') {
            const entity = report.entities.find((item) => item.relationId === change.value.dbtModel);
            return [`warehouse relation ${entity?.relation ?? change.value.dbtModel}`, ...(entity?.grainSource === 'primary_key' ? [`declared primary key ${entity.grain}`] : entity?.grainSource === 'unique_column' ? [`${entity.grain} is unique on the warehouse`] : [])];
          }
          if (change.operation === 'upsert_relationship') {
            const relationship = report.relationships.find((item) => item.id === change.value.id && item.domain === change.value.domain);
            return [...(relationship?.evidence.map((item) => item.reason) ?? []), ...(relationship?.validation ? [`warehouse check: ${relationship.validation.message}`] : [])];
          }
          return [`warehouse catalog ${report.catalogFingerprint.slice(0, 12)}`];
        };
        const operationId = (change: ModelingAuthoringChange): string => {
          const value = change.value as { id: string; domain?: string };
          return change.operation === 'upsert_domain' ? `warehouse:domain:${value.id}` : `warehouse:${change.operation.replace('upsert_', '')}:${value.domain}:${value.id}`;
        };
        const operations: ContextAuthoringOperation[] = changes.map((change) => ({
          id: operationId(change),
          kind: 'modeling_change',
          change,
          evidence: evidenceFor(change),
        }));
        const proposal = previewContextAuthoring({ origin: 'warehouse_discovery', operations, expectedSnapshotId: snapshot.snapshotId });
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, report, proposal }));
      } catch (error) {
        const code = apiErrorCode(error, 'WAREHOUSE_DISCOVERY_FAILED');
        const status = code === 'PROPOSAL_STALE' ? 409 : code === 'WAREHOUSE_MODELING_NOT_ENABLED' ? 404 : code === 'WAREHOUSE_CATALOG_MISSING' ? 409 : 400;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          snapshotId: snapshot.snapshotId,
          code,
          message: apiErrorMessage(error),
          nextActions: code === 'WAREHOUSE_CATALOG_MISSING' ? ['Open Settings → Connections and Sync schema, or run `dql sync warehouse --schemas <schema>`.'] : [],
        })));
      }
      return;
    }

    if (req.method === 'POST' && (path === '/api/modeling/warehouse/discover' || path === '/api/modeling/warehouse/discover/apply')) {
      const requestId = apiRequestId('modeling-warehouse-discover');
      const snapshot = projectSnapshot();
      try {
        const body = await readJSON(req).catch(() => ({})) as { validate?: boolean; queryHistory?: boolean; domain?: string; expectedSnapshotId?: string; entityIds?: string[]; relationshipIds?: string[] };
        const applying = path.endsWith('/apply');
        if (applying && (!body.expectedSnapshotId || body.expectedSnapshotId !== snapshot.snapshotId)) {
          throw Object.assign(new Error('Project sources changed after discovery. Review the refreshed drafts before adding them.'), { code: 'SOURCE_CHANGED' });
        }
        const report = await discoverProjectWarehouseModel(projectRoot, { manifest: snapshot.manifest, domain: body.domain, validate: body.validate === true, queryHistory: body.queryHistory === true, executor });
        if (!applying) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ requestId, snapshotId: snapshot.snapshotId, report }));
          return;
        }
        const applied = applyProjectWarehouseDiscovery(projectRoot, report, { entityIds: body.entityIds, relationshipIds: body.relationshipIds });
        projectSnapshots.invalidate();
        const next = projectSnapshot();
        await refreshUnifiedProjectIndexes(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: next.snapshotId, applied, modeling: next.manifest.modeling, diagnostics: next.manifest.diagnostics ?? [] }));
      } catch (error) {
        const code = apiErrorCode(error, 'WAREHOUSE_DISCOVERY_FAILED');
        const status = code === 'SOURCE_CHANGED' ? 409 : code === 'WAREHOUSE_MODELING_NOT_ENABLED' ? 404 : code === 'WAREHOUSE_CATALOG_MISSING' ? 409 : 400;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId,
          snapshotId: snapshot.snapshotId,
          code,
          message: apiErrorMessage(error),
          nextActions: code === 'WAREHOUSE_CATALOG_MISSING' ? ['Open Settings → Connections and Sync schema, or run `dql sync warehouse --schemas <schema>`.'] : [],
        })));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/modeling/dbt-first/relationships/suggestions') {
      const requestId = apiRequestId('modeling-relationship-suggestions');
      const snapshot = projectSnapshot();
      try {
        const { fromRelation, toRelation, fromUniqueId, toUniqueId } = relationshipRelations(snapshot.manifest, url.searchParams.get('from') ?? '', url.searchParams.get('to') ?? '');
        const dbtManifestPath = resolveDbtManifestPath(projectRoot);
        const [fromDetail, toDetail] = await Promise.all([nodeDetailWithColumns(snapshot.snapshotId, fromUniqueId), nodeDetailWithColumns(snapshot.snapshotId, toUniqueId)]);
        const columnsOf = (uniqueId: string): string[] => (uniqueId === fromUniqueId ? fromDetail : toDetail)?.columns.map((column) => column.name) ?? [];
        const dbtTests = dbtRelationshipTestEdges(snapshot.snapshotId, dbtManifestPath)
          .filter((edge) => edge.fromColumn !== 'unknown' && edge.toColumn !== 'unknown')
          .filter((edge) => (edge.fromDbtUniqueId === fromUniqueId && edge.toDbtUniqueId === toUniqueId) || (edge.fromDbtUniqueId === toUniqueId && edge.toDbtUniqueId === fromUniqueId))
          .map((edge) => ({ fromColumn: edge.fromColumn, toColumn: edge.toColumn, reversed: edge.fromDbtUniqueId !== fromUniqueId }));
        const suggestions = suggestRelationshipKeys({ fromColumns: columnsOf(fromUniqueId), toColumns: columnsOf(toUniqueId), fromRelation, toRelation, dbtTests });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ requestId, snapshotId: snapshot.snapshotId, suggestions }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(apiErrorEnvelope({ requestId, snapshotId: snapshot.snapshotId, code: apiErrorCode(error, 'RELATIONSHIP_SUGGESTIONS_FAILED'), message: apiErrorMessage(error) })));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/agent-runs') {
      const rawLimit = Number(url.searchParams.get('limit'));
      const limit = Number.isFinite(rawLimit) && rawLimit > 0
        ? Math.min(200, Math.floor(rawLimit))
        : 50;
      // This is an INDEX payload: one row per run, no answer bodies. Shipping
      // stored runs whole meant a measured 47.61 MB for 20 real runs, and
      // PARSING every stored run to build the index took the server past its
      // heap on a project with 300 runs of history (1.2 GB of JSON). The store
      // reads only the page, newest first.
      // `GET /api/agent-runs/:id` still serves the complete immutable record.
      const runs = agentRunStore.list(limit)
        .sort((a: AgentRun, b: AgentRun) => b.startedAt.localeCompare(a.startedAt))
        .map(agentRunListEntryForTransport);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ runs, total: agentRunStore.count(), limit }));
      return;
    }

    // OBS-005: local-only Ask trace APIs. These endpoints return the compact
    // trace envelope or its typed, redacted detail; they never read a prompt,
    // SQL string, result row, provider response, or live network exporter.
    const writeTraceStoreUnavailable = (traceStatus: ReturnType<typeof askTraceStore.status>) => {
      const schemaUnsupported = traceStatus.reason === 'unsupported_schema';
      res.writeHead(schemaUnsupported ? 409 : 503, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        code: schemaUnsupported ? 'TRACE_SCHEMA_UNSUPPORTED' : 'TRACE_STORE_UNAVAILABLE',
        error: schemaUnsupported
          ? 'The local Ask trace schema is newer than this DQL runtime can read.'
          : 'Local Ask trace storage is unavailable.',
        status: traceStatus,
      }));
    };
    if (req.method === 'GET' && path === '/api/ask-traces/status') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ status: askTraceStore.status() }));
      return;
    }

    if (req.method === 'GET' && path === '/api/ask-traces') {
      const traceStatus = askTraceStore.status();
      if (!traceStatus.available) {
        writeTraceStoreUnavailable(traceStatus);
        return;
      }
      const rawLimit = Number(url.searchParams.get('limit'));
      const limit = Number.isFinite(rawLimit) && rawLimit > 0 ? Math.min(100, Math.floor(rawLimit)) : 50;
      // Trace-store filters are all allowlisted scalar receipt fields. The
      // question preview is deliberately NOT a trace-store filter: prompts do
      // not live in ask-observability.sqlite and list pagination remains
      // snapshot/receipt based rather than text-search based.
      const traceListInput: AskTraceListQueryV1 = {
        limit,
        ...(url.searchParams.get('cursor') ? { cursor: url.searchParams.get('cursor')! } : {}),
        ...(url.searchParams.get('status') ? { status: url.searchParams.get('status') as AskTraceListQueryV1['status'] } : {}),
        ...(url.searchParams.get('mode') ? { mode: url.searchParams.get('mode') as AskTraceListQueryV1['mode'] } : {}),
        ...(url.searchParams.get('trustState') ? { trustState: url.searchParams.get('trustState')! } : {}),
        ...(url.searchParams.get('selectedTier') ? { selectedTier: url.searchParams.get('selectedTier')! } : {}),
        ...(url.searchParams.get('surface') ? { surface: url.searchParams.get('surface') as AskTraceListQueryV1['surface'] } : {}),
        ...(url.searchParams.get('recordingStatus') ? { recordingStatus: url.searchParams.get('recordingStatus') as AskTraceListQueryV1['recordingStatus'] } : {}),
      };
      const page = askTraceStore.list(traceListInput);
      const traces = await Promise.all(page.traces.map(async (trace) => {
        const run = await agentRunStore.get(trace.runId);
        if (!run) return trace;
        const questionPreview = askTraceQuestionPreview(run.question);
        return {
          ...projectAuthoritativeV8TraceEnvelope(trace, run),
          ...(questionPreview ? { questionPreview } : {}),
          scenarioLabel: askTraceScenarioLabel(run),
          ...(run.askAgentRuntimeMode ? { runtimeMode: run.askAgentRuntimeMode } : {}),
        };
      }));
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ ...page, traces }));
      return;
    }

    if (req.method === 'GET' && /^\/api\/ask-traces\/by-run\/[^/]+$/.test(path)) {
      const traceStatus = askTraceStore.status();
      if (!traceStatus.available) {
        writeTraceStoreUnavailable(traceStatus);
        return;
      }
      const runId = decodeURIComponent(path.slice('/api/ask-traces/by-run/'.length));
      const trace = askTraceStore.getByRun(runId);
      if (!trace) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_NOT_FOUND', error: 'No local trace was found for this Ask run.' }));
        return;
      }
      if (trace.envelope.recordingStatus === 'detail_expired') {
        res.writeHead(410, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_DETAIL_EXPIRED', error: 'Detailed trace evidence has expired; the run summary remains available.', envelope: trace.envelope }));
        return;
      }
      const run = await agentRunStore.get(runId);
      const projectedTrace = {
        ...trace,
        envelope: projectAuthoritativeV8TraceEnvelope(trace.envelope, run),
      };
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      // The canonical Ask story is persisted on the AgentRun, not rebuilt from
      // spans. Join it only at this local API boundary so trace storage never
      // becomes prompt/result retention and old runs explicitly omit it.
      res.end(serializeJSON({
        ...projectedTrace,
        ...(run?.diagnosticReceiptV4?.summary ? { decisionSummary: run.diagnosticReceiptV4.summary } : {}),
        ...(run?.diagnosticReceiptV5?.summary ? { runtimeDecisionSummary: run.diagnosticReceiptV5.summary } : {}),
        ...(run?.diagnosticReceiptV5 ? { runtimeReceiptV5: run.diagnosticReceiptV5 } : {}),
        ...(run?.diagnosticReceiptV6 ? { runtimeReceiptV6: run.diagnosticReceiptV6 } : {}),
        ...(run?.diagnosticReceiptV8 ? { runtimeReceiptV8: run.diagnosticReceiptV8 } : {}),
        ...(run?.diagnosticReceiptV9 ? { runtimeReceiptV9: run.diagnosticReceiptV9 } : {}),
        ...(run?.diagnosticReceiptV9 && traceAnswerProjection(run) ? { runtimeAnswerV1: traceAnswerProjection(run) } : {}),
        ...(run?.askAgentRuntimeMode ? { runtimeMode: run.askAgentRuntimeMode } : {}),
      }));
      return;
    }

    if (req.method === 'GET' && /^\/api\/ask-traces\/[0-9a-f]{32}\/export$/.test(path)) {
      const traceStatus = askTraceStore.status();
      if (!traceStatus.available) {
        writeTraceStoreUnavailable(traceStatus);
        return;
      }
      const traceId = path.split('/')[3] ?? '';
      const trace = askTraceStore.get(traceId);
      if (!trace) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_NOT_FOUND', error: 'No local trace was found.' }));
        return;
      }
      if (trace.envelope.recordingStatus === 'detail_expired') {
        res.writeHead(410, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_DETAIL_EXPIRED', error: 'Detailed trace evidence has expired; it cannot be exported.' }));
        return;
      }
      if ((url.searchParams.get('profile') ?? 'strict') !== 'strict') {
        res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_EXPORT_REDACTION_FAILED', error: 'The runtime export endpoint only serves strict redacted bundles.' }));
        return;
      }
      try {
        const run = await agentRunStore.get(trace.envelope.runId);
        const bundle = createAskTracePortableBundleV1(trace, {
          profile: 'strict',
          runReceipt: run,
          provenance: 'recorded',
        });
        askTraceStore.recordExportReceipt(trace.envelope.traceId, {
          version: 1,
          profile: 'strict',
          bundleFingerprint: bundle.manifest.bundleFingerprint,
          exportedAt: bundle.manifest.createdAt,
          checksums: {
            'manifest.json': `sha256:${createHash('sha256').update(serializeJSON(bundle.manifest)).digest('hex')}`,
            ...bundle.manifest.checksums,
          },
          canaryPassed: true,
          ...(bundle.trace.envelope.traceFingerprint ? { traceFingerprint: bundle.trace.envelope.traceFingerprint } : {}),
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Disposition': `attachment; filename="ask-trace-${traceId}.json"` });
        res.end(serializeJSON(bundle));
      } catch {
        res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_EXPORT_REDACTION_FAILED', error: 'The local trace could not be exported safely.' }));
      }
      return;
    }

    if (req.method === 'GET' && /^\/api\/ask-traces\/[0-9a-f]{32}$/.test(path)) {
      const traceStatus = askTraceStore.status();
      if (!traceStatus.available) {
        writeTraceStoreUnavailable(traceStatus);
        return;
      }
      const traceId = path.split('/').at(-1) ?? '';
      const trace = askTraceStore.get(traceId);
      if (!trace) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_NOT_FOUND', error: 'No local trace was found.' }));
        return;
      }
      if (trace.envelope.recordingStatus === 'detail_expired') {
        res.writeHead(410, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ code: 'TRACE_DETAIL_EXPIRED', error: 'Detailed trace evidence has expired; the run summary remains available.', envelope: trace.envelope }));
        return;
      }
      const run = await agentRunStore.get(trace.envelope.runId);
      const projectedTrace = {
        ...trace,
        envelope: projectAuthoritativeV8TraceEnvelope(trace.envelope, run),
      };
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        ...projectedTrace,
        ...(run?.diagnosticReceiptV4?.summary ? { decisionSummary: run.diagnosticReceiptV4.summary } : {}),
        ...(run?.diagnosticReceiptV5?.summary ? { runtimeDecisionSummary: run.diagnosticReceiptV5.summary } : {}),
        ...(run?.diagnosticReceiptV5 ? { runtimeReceiptV5: run.diagnosticReceiptV5 } : {}),
        ...(run?.diagnosticReceiptV6 ? { runtimeReceiptV6: run.diagnosticReceiptV6 } : {}),
        ...(run?.diagnosticReceiptV8 ? { runtimeReceiptV8: run.diagnosticReceiptV8 } : {}),
        ...(run?.diagnosticReceiptV9 ? { runtimeReceiptV9: run.diagnosticReceiptV9 } : {}),
        ...(run?.diagnosticReceiptV9 && traceAnswerProjection(run) ? { runtimeAnswerV1: traceAnswerProjection(run) } : {}),
        ...(run?.askAgentRuntimeMode ? { runtimeMode: run.askAgentRuntimeMode } : {}),
      }));
      return;
    }

    /**
     * One-click bounded execution repair.
     *
     * The source run is immutable. First, retry its exact SQL through the
     * shared deterministic preparation boundary (this repairs internal IDs and
     * dialect-safe row bounds without an LLM). Only a connector-classified
     * model-repair failure may spend one provider call to rewrite the SQL. The
     * derived SQL is still read-only, bounded, and executed on the source run's
     * exact target before a replacement card is returned.
     *
     * Acceptance: API-003, API-007, UI-012, UI-013, SEC-004, E2E-014.
     */
    if (req.method === 'POST' && /^\/api\/agent-runs\/[^/]+\/repair-execution$/.test(path)) {
      const match = path.match(/^\/api\/agent-runs\/([^/]+)\/repair-execution$/);
      const sourceRunId = decodeURIComponent(match?.[1] ?? '');
      const sourceRun = await agentRunStore.get(sourceRunId);
      if (!sourceRun) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Agent run not found.' }));
        return;
      }

      const capability = normalizeAnalyticalRepairCapabilityV1(sourceRun.repairCapability);
      if (!capability?.automatic.eligible || capability.automatic.attemptsRemaining < 1) {
        const manualActions = capability?.manualActions?.length
          ? capability.manualActions
          : ['edit_dql', 'open_sql_notebook'] as const;
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_CAPABILITY_REQUIRED',
          error: 'This run does not retain eligible automatic execution-repair authority.',
          manualActions,
          ...(capability?.ineligibilityReason ? { ineligibilityReason: capability.ineligibilityReason } : {}),
        }));
        return;
      }

      // Rebind every server-issued capability identity to the currently
      // persisted immutable source run before checking idempotence or reserving
      // an attempt. A copied/stale capability must never authorize provider or
      // SQL work against a mutated plan, failure, or source artifact.
      const canonicalCapability = analyticalRepairCapabilityForAgentRun(
        sourceRun,
        capability.targetFingerprint,
      );
      const bindingMatches = canonicalCapability
        && canonicalCapability.automatic.eligible
        && canonicalCapability.planFingerprint === capability.planFingerprint
        && canonicalCapability.failureFingerprint === capability.failureFingerprint
        && canonicalCapability.sourceFingerprint === capability.sourceFingerprint;
      if (!bindingMatches) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_CAPABILITY_REQUIRED',
          error: 'The persisted source plan, failure, or artifact no longer matches its server-issued repair capability.',
          manualActions: capability.manualActions,
        }));
        return;
      }

      const derivedRunId = `${sourceRun.id}:repair:1`;
      if (activeAnalyticalRepairReservations.has(derivedRunId)) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_IN_PROGRESS',
          error: 'The single permitted repair attempt is already in progress.',
          manualActions: capability.manualActions,
        }));
        return;
      }
      const existing = await agentRunStore.get(derivedRunId);
      if (existing) {
        const succeeded = existing.status === 'needs_review' && existing.trustState === 'review_required';
        res.writeHead(succeeded ? 200 : 409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(succeeded
          ? { run: existing }
          : {
              code: 'REPAIR_ATTEMPT_EXHAUSTED',
              error: 'The single permitted repair attempt was already consumed and did not complete successfully.',
              manualActions: capability.manualActions,
              run: existing,
            }));
        return;
      }

      const sourceDqlArtifact = repairableDqlArtifactFromAgentRun(sourceRun);
      const retainedFailure = warehouseFailureFromAgentRun(sourceRun);
      if (!sourceDqlArtifact || !validAskRepairDqlWrapper(sourceDqlArtifact.source)) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_CAPABILITY_REQUIRED',
          error: 'The retained DQL wrapper is unavailable or invalid. Keep it editable and repair it manually.',
          manualActions: capability.manualActions,
        }));
        return;
      }
      const capabilityHash = (value: unknown): string => `sha256:${createHash('sha256').update(stableExecutionValue(value)).digest('hex')}`;
      if (capability.dqlFingerprint !== capabilityHash(sourceDqlArtifact.source.trim())) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_CAPABILITY_REQUIRED',
          error: 'The retained DQL source no longer matches its immutable repair capability.',
          manualActions: capability.manualActions,
        }));
        return;
      }

      const body = agentRunRecord(await readJSON(req).catch(() => null));
      const threadId = agentRunString(body?.threadId);
      let targetConnection: ConnectionConfig;
      try {
        targetConnection = await resolveAgentRunExecutionConnection({
          question: sourceRun.question,
          executionTarget: sourceRun.executionTarget,
        });
      } catch (error) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: apiErrorMessage(error) }));
        return;
      }
      const targetConnectionName = sourceRun.executionTarget?.target === 'connection'
        ? sourceRun.executionTarget.connectionName
        : sourceRun.executionTarget?.target === 'local'
          ? 'local'
          : projectConfig.defaultConnectionName;
      const resolvedTargetFingerprint = targetGenerationFingerprint(targetConnection, targetConnectionName);
      if (resolvedTargetFingerprint !== capability.targetFingerprint) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_TARGET_DRIFT',
          error: 'The named execution target now resolves to a different connection generation. Automatic repair was not attempted.',
          manualActions: capability.manualActions,
        }));
        return;
      }

      if (consumedAnalyticalRepairCapabilities.has(derivedRunId)) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_ATTEMPT_EXHAUSTED',
          error: 'The single permitted repair attempt has already been consumed.',
          manualActions: capability.manualActions,
        }));
        return;
      }
      activeAnalyticalRepairReservations.add(derivedRunId);
      consumedAnalyticalRepairCapabilities.add(derivedRunId);
      const releaseRepairReservation = (): void => { activeAnalyticalRepairReservations.delete(derivedRunId); };
      res.once('finish', releaseRepairReservation);
      res.once('close', releaseRepairReservation);

      const repairStartedAt = new Date().toISOString();
      const repairStartedAtMs = Date.now();
      const sourceFailureForReservation = analyticalFailedRunFromAgentRun(sourceRun)?.failure;
      // A one-click repair is a derived Ask run, not an invisible side effect
      // of the original failure. Give it its own addressable local trace and
      // keep the source run/trace plus immutable plan fingerprint as typed
      // linkage. No prompt, SQL, result row, or raw failure text enters it.
      const repairTrace = createAskTraceObserverV1({
        store: askTraceStore,
        runId: derivedRunId,
        surface: 'browser',
        mode: sourceRun.requestedMode === 'research' ? 'research' : 'ask',
        questionFingerprint: runtimeTraceFingerprint(sourceRun.question),
        ...(sourceRun.traceReference?.traceId ? { parentTraceId: sourceRun.traceReference.traceId } : {}),
        parentRunId: sourceRun.id,
      });
      repairTrace.recordLink({
        kind: 'derived_repair',
        targetRunId: sourceRun.id,
        ...(sourceRun.traceReference?.traceId ? { targetTraceId: sourceRun.traceReference.traceId } : {}),
      });
      const repairTracePayload = {
        kind: 'sql' as const,
        execution: {
          version: 1 as const,
          tier: 'exploratory_sql' as const,
          planFingerprint: capability.planFingerprint,
          sqlFingerprint: capability.sqlFingerprint,
          targetFingerprint: capability.targetFingerprint,
          reviewRequired: true,
        },
      };
      const repairTraceSpan = repairTrace.startSpan({
        name: 'sql.repair',
        stage: 'sql',
        reasonCode: 'repair_attempted',
        payload: repairTracePayload,
      });
      const reservationEvent: AgentRunEvent = {
        id: `${derivedRunId}:repair`,
        runId: derivedRunId,
        type: 'repair.attempted',
        at: repairStartedAt,
        message: 'Reserved the single bounded repair attempt.',
        route: 'generated_answer',
      };
      const reservedRun: AgentRun = {
        id: derivedRunId,
        question: sourceRun.question,
        requestedMode: sourceRun.requestedMode,
        route: 'generated_answer',
        status: 'blocked',
        trustState: 'blocked',
        stopReason: 'blocked',
        startedAt: repairStartedAt,
        completedAt: repairStartedAt,
        selectedObject: sourceRun.selectedObject,
        executionTarget: sourceRun.executionTarget,
        routeDecision: sourceRun.routeDecision,
        plan: sourceRun.plan,
        steps: [],
        summary: 'The single repair attempt was reserved but has not completed successfully.',
        artifacts: [],
        evaluations: [],
        events: [reservationEvent],
        nextActions: sourceRun.nextActions,
        repairAttempts: 1,
        lifecycle: {
          version: 1,
          state: 'terminal',
          phase: 'repair.attempted',
          revision: 1,
          eventCursor: 1,
          startedAt: repairStartedAt,
          updatedAt: repairStartedAt,
          completedAt: repairStartedAt,
        },
        derivation: {
          version: 1,
          kind: 'analytical_repair',
          sourceRunId: sourceRun.id,
          ...(sourceFailureForReservation?.failureId ? { sourceFailureId: sourceFailureForReservation.failureId } : {}),
          attempt: 1,
        },
      };
      try {
        await agentRunStore.save(reservedRun);
      } catch (error) {
        releaseRepairReservation();
        throw error;
      }
      let repaired: BoundedDqlRepairResult;
      try {
        repaired = await agentRunAskTraceContext.run(repairTrace, async () => {
        // Compile the immutable original wrapper first. A provider receives only
        // this embedded SQL, never the DQL wrapper or its surrounding fields.
        const invocation = prepareBlockInvocation({
          source: sourceDqlArtifact.source,
          parameters: sourceDqlArtifact.parameterValues,
          question: sourceRun.question,
          surface: 'ask_ai',
        });
        if (invocation.errors.length || invocation.unresolvedParameters.length) {
          throw boundedRepairError(
            invocation.errors.join(' ') || `Provide required parameters before retrying: ${invocation.unresolvedParameters.join(', ')}.`,
            409,
          );
        }
        const originalPlan = buildExecutionPlan({
          id: 'ask-execution-repair-source',
          type: 'dql',
          source: sourceDqlArtifact.source,
          title: sourceDqlArtifact.name,
        }, {
          semanticLayer,
          driver: targetConnection.driver,
          parameters: invocation.values,
        });
        if (!originalPlan?.sql?.trim()) throw boundedRepairError('The original DQL wrapper did not compile to SQL.', 409);
        if (capability.sqlFingerprint !== capabilityHash(originalPlan.sql.trim())) {
          throw boundedRepairError('The original compiled SQL no longer matches its immutable repair capability.', 409);
        }
        const sqlRepair = await executeBoundedSqlRepair({
          question: sourceRun.question,
          sourceSql: originalPlan.sql,
          targetConnection,
          targetConnectionName,
          sqlParams: originalPlan.sqlParams,
          variables: { ...originalPlan.variables, ...invocation.values },
        });
        const embeddedSql = restoreNotebookDqlParameterInterpolations(sqlRepair.repairedSql, originalPlan.sqlParams);
        const repairedSource = replaceNotebookDqlQueryForRepair(sourceDqlArtifact.source, embeddedSql);
        if (!repairedSource) throw boundedRepairError('DQL could not reinsert the repaired SQL into the immutable wrapper.', 422);
        const repairedInvocation = prepareBlockInvocation({
          source: repairedSource,
          parameters: sourceDqlArtifact.parameterValues,
          question: sourceRun.question,
          surface: 'ask_ai',
        });
        if (repairedInvocation.errors.length || repairedInvocation.unresolvedParameters.length) {
          throw boundedRepairError('The SQL-only repair did not preserve a compilable DQL wrapper.', 422);
        }
        const repairedPlan = buildExecutionPlan({
          id: 'ask-execution-repair-derived',
          type: 'dql',
          source: repairedSource,
          title: sourceDqlArtifact.name,
        }, {
          semanticLayer,
          driver: targetConnection.driver,
          parameters: repairedInvocation.values,
        });
        if (!repairedPlan?.sql?.trim() || normalizeSqlForComparison(repairedPlan.sql) !== normalizeSqlForComparison(sqlRepair.repairedSql)) {
          throw boundedRepairError('The repaired wrapper recompiled to different SQL, so DQL stopped before publishing it.', 422);
        }
        const repairedExecutionReceipt = createDqlArtifactExecutionReceipt(
          repairedSource,
          sqlRepair.result.sql ?? repairedPlan.sql,
          repairedInvocation.values,
          sqlRepair.result,
        );
        const repairedExecutableArtifact = sqlRepair.result.executableArtifact
          ? {
              ...sqlRepair.result.executableArtifact,
              kind: 'sql_block' as const,
              dqlFingerprint: executionFingerprint(repairedSource),
              sourceFingerprint: executionFingerprint(stableExecutionValue({
                name: sourceDqlArtifact.name ?? null,
                path: sourceDqlArtifact.sourcePath ?? null,
              })),
              compiledSqlFingerprint: executionFingerprint(repairedPlan.sql),
              normalizedSqlFingerprint: executionFingerprint(sqlRepair.repairedSql),
              parameterFingerprint: repairedExecutionReceipt.parameterFingerprint,
              provenanceFingerprint: executionFingerprint(stableExecutionValue(repairedInvocation.resolvedParameters.map((parameter) => ({
                name: parameter.name,
                source: parameter.source,
              })))),
              planFingerprint: executionFingerprint(stableExecutionValue({
                compiledSqlFingerprint: executionFingerprint(repairedPlan.sql),
                parameterCount: repairedPlan.sqlParams?.length ?? 0,
                variableNames: Object.keys(repairedPlan.variables ?? {}).sort(),
              })),
              trustState: 'review_required' as const,
              receipt: repairedExecutionReceipt,
            }
          : undefined;
        const repairedArtifact: DqlArtifactReference = {
          ...sourceDqlArtifact,
          source: repairedSource,
          compiledSql: repairedPlan.sql,
          trustState: 'review_required',
          persistence: 'transient',
          executionReceipt: repairedExecutionReceipt,
          ...(repairedExecutableArtifact ? { executableArtifact: repairedExecutableArtifact } : {}),
          ...(repairedInvocation.parameters.length ? { parameters: repairedInvocation.parameters } : {}),
          ...(Object.keys(repairedInvocation.values).length ? { parameterValues: repairedInvocation.values } : {}),
        };
        return {
          ...sqlRepair,
          result: {
            ...sqlRepair.result,
            executionReceipt: repairedExecutionReceipt,
            ...(repairedExecutableArtifact ? { executableArtifact: repairedExecutableArtifact } : {}),
            dqlArtifact: repairedArtifact,
          },
          repairedSql: repairedPlan.sql,
          repairedSource,
          sqlParams: repairedPlan.sqlParams,
          variables: { ...repairedPlan.variables, ...repairedInvocation.values },
        };
        });
        repairTrace.finishSpan(repairTraceSpan, {
          outcome: 'ok',
          reasonCode: 'repair_attempted',
          payload: repairTracePayload,
        });
      } catch (error) {
        const repairError = error as Error & { status?: number; warehouseFailure?: WarehouseSqlFailureV1 };
        repairTrace.finishSpan(repairTraceSpan, {
          outcome: 'error',
          reasonCode: 'sql_failure',
          payload: repairTracePayload,
        });
        const repairTraceReference = repairTrace.finalize({
          status: 'blocked',
          terminalOutcome: 'blocked',
          trustState: 'blocked',
          selectedTier: 'exploratory_sql',
        });
        const dispatchEvidence = providerDispatchTerminalEvidence(error);
        const failedAt = new Date().toISOString();
        const failedTelemetry: AgentRunTelemetryV1 = {
          version: 1,
          stageDurationsMs: { repair: Date.now() - repairStartedAtMs, total: Date.now() - repairStartedAtMs },
          providerRoundTrips: dispatchEvidence?.providerRoundTrips ?? 0,
          toolCalls: dispatchEvidence?.toolCalls ?? 0,
          sqlExecutions: dispatchEvidence?.sqlExecutions ?? 0,
          repairs: Math.max(1, dispatchEvidence?.repairs ?? 0),
          egressReceipts: dispatchEvidence?.providerEgressReceipts.length ?? 0,
          fallbackReason: dispatchEvidence?.fallbackReason ?? 'repair_failed',
        };
        const failedReceipts = dispatchEvidence?.providerEgressReceipts ?? [];
        await agentRunStore.save({
          ...reservedRun,
          completedAt: failedAt,
          summary: repairError.message,
          lifecycle: reservedRun.lifecycle ? {
            ...reservedRun.lifecycle,
            phase: 'run.failed',
            updatedAt: failedAt,
            completedAt: failedAt,
          } : undefined,
          events: [
            reservationEvent,
            {
              id: `${derivedRunId}:failed`,
              runId: derivedRunId,
              type: 'run.failed',
              at: failedAt,
              message: repairError.message,
              route: 'generated_answer',
              status: 'blocked',
              trustState: 'blocked',
            },
          ],
          telemetry: failedTelemetry,
          ...(failedReceipts.length ? { providerEgressReceipts: failedReceipts } : {}),
          diagnosticReceiptV2: {
            version: 2,
            runId: derivedRunId,
            route: 'generated_answer',
            status: 'blocked',
            telemetry: failedTelemetry,
            providerEgressReceiptFingerprints: failedReceipts.map((receipt) => executionFingerprint(stableExecutionValue(receipt))),
            repairCapabilityFingerprint: executionFingerprint(stableExecutionValue(capability)),
          },
          ...(repairTraceReference ? { traceReference: repairTraceReference } : {}),
        });
        res.writeHead(repairError.status ?? 500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          error: repairError.message,
          ...(repairError.warehouseFailure ? { warehouseFailure: repairError.warehouseFailure } : {}),
        }));
        return;
      }
      const { result, repairedSql, repairMode, firstFailure, providerEgressReceipts, providerRoundTrips } = repaired;

      const completedAt = new Date().toISOString();
      // Repair never grants a second answer/narration call and never sends rows
      // to a provider. Present the validated contract deterministically.
      const presentationText = `The repaired query returned ${result.rowCount} row${result.rowCount === 1 ? '' : 's'}. Review the derived SQL before reuse.`;
      const sourceFailure = analyticalFailedRunFromAgentRun(sourceRun)?.failure;
      const presentationContext = repairPresentationContextFromAgentRun(sourceRun);
      const executionResultFingerprint = result.executionReceipt?.resultFingerprint;
      const resultTraceSpan = repairTrace.startSpan({
        name: 'result.normalize',
        stage: 'result',
        reasonCode: 'result_accepted',
        payload: {
          kind: 'result',
          ...(executionResultFingerprint ? { resultFingerprint: executionResultFingerprint } : {}),
          rowCount: result.rowCount,
          trustState: 'review_required',
        },
      });
      repairTrace.finishSpan(resultTraceSpan, {
        outcome: 'ok',
        reasonCode: 'result_accepted',
      });
      const repairTotalDurationMs = Date.now() - repairStartedAtMs;
      const repairTelemetry: AgentRunTelemetryV1 = {
        version: 1,
        stageDurationsMs: {
          retrieval: 0,
          meaning: 0,
          repair: repairTotalDurationMs,
          ...(typeof result.executionTime === 'number' ? { execution: result.executionTime } : {}),
          narration: 0,
          total: repairTotalDurationMs,
        },
        providerRoundTrips,
        toolCalls: 0,
        sqlExecutions: firstFailure ? 2 : 1,
        repairs: 1,
        egressReceipts: providerEgressReceipts.length,
        ...(typeof result.executionTime === 'number' ? { warehouseDurationMs: result.executionTime } : {}),
      };
      const artifact = agentRunArtifact(
        'answer',
        'Repaired analytical answer',
        {
          kind: 'uncertified',
          certification: 'analyst_review_required',
          reviewStatus: 'analyst_review_required',
          trustLabel: 'AI-generated · review required',
          answer: presentationText,
          text: presentationText,
          ...presentationContext,
          result,
          proposedSql: repairedSql,
          sql: result.sql ?? repairedSql,
          dqlArtifact: result.dqlArtifact,
          diagnosticReceipt: {
            version: 1,
            phase: 'run.completed',
            route: 'generated_answer',
            repair: {
              attempt: 1,
              mode: repairMode,
              sourceRunId: sourceRun.id,
              targetPreserved: true,
              readOnly: true,
            },
            execution: {
              rowCount: result.rowCount,
              ...(executionResultFingerprint ? { resultFingerprint: executionResultFingerprint } : {}),
            },
            providerEgressReceipts,
          },
          previousAttempt: {
            sourceRunId: sourceRun.id,
            sql: repairableSqlFromAgentRun(sourceRun),
            ...(sourceDqlArtifact?.source ? { dql: sourceDqlArtifact.source } : {}),
            failure: retainedFailure ?? firstFailure,
          },
          repair: { attempt: 1, mode: repairMode },
        },
        undefined,
        'review_required',
      );
      const evaluation: AgentRunEvaluation = {
        id: `${derivedRunId}:execution`,
        label: 'Repaired query execution',
        passed: true,
        severity: 'info',
        message: `The ${repairMode === 'ai' ? 'AI-repaired' : 'deterministically normalized'} read-only query executed on the original target.`,
      };
      const repairStep = {
        id: `${derivedRunId}:step`,
        index: 0,
        route: 'generated_answer' as const,
        resolvedRoute: 'generated_answer' as const,
        goal: 'Repair and execute the failed analytical query on its original target.',
        successCriteria: ['Read-only validation passes.', 'The original execution target returns a bounded result.'],
        status: 'repaired' as const,
        attempts: 1,
        summary: evaluation.message,
        evaluations: [evaluation],
        artifacts: [artifact],
      };
      const events: AgentRunEvent[] = [
        { id: `${derivedRunId}:repair`, runId: derivedRunId, type: 'repair.attempted', at: repairStartedAt, message: 'Started one bounded query repair.', route: 'generated_answer' },
        { id: `${derivedRunId}:artifact`, runId: derivedRunId, type: 'artifact.created', at: completedAt, message: 'Created the repaired result artifact.', route: 'generated_answer', trustState: 'review_required' },
        { id: `${derivedRunId}:complete`, runId: derivedRunId, type: 'run.completed', at: completedAt, message: 'The repaired query executed successfully.', route: 'generated_answer', status: 'needs_review', trustState: 'review_required' },
      ];
      const derivedRun: AgentRun = {
        id: derivedRunId,
        question: sourceRun.question,
        requestedMode: sourceRun.requestedMode,
        route: 'generated_answer',
        status: 'needs_review',
        trustState: 'review_required',
        stopReason: 'generated_review_required',
        startedAt: repairStartedAt,
        completedAt,
        selectedObject: sourceRun.selectedObject,
        executionTarget: sourceRun.executionTarget,
        routeDecision: sourceRun.routeDecision,
        plan: sourceRun.plan,
        steps: [repairStep],
        summary: presentationText,
        answer: presentationText,
        answerKind: 'governed',
        artifacts: [artifact],
        evaluations: [evaluation],
        events,
        nextActions: sourceRun.nextActions,
        repairAttempts: 1,
        lifecycle: {
          version: 1,
          state: 'terminal',
          phase: 'run.completed',
          revision: 1,
          eventCursor: events.length,
          startedAt: repairStartedAt,
          updatedAt: completedAt,
          completedAt,
        },
        diagnosticReceipt: {
          version: 1,
          runId: derivedRunId,
          phase: 'run.completed',
          route: 'generated_answer',
          plan: sourceRun.plan,
          steps: [repairStep],
          artifacts: [artifact],
          evaluations: [evaluation],
          providerEgressReceipts,
        },
        diagnosticReceiptV2: {
          version: 2,
          runId: derivedRunId,
          route: 'generated_answer',
          status: 'needs_review',
          telemetry: repairTelemetry,
          providerEgressReceiptFingerprints: providerEgressReceipts.map((receipt) => executionFingerprint(stableExecutionValue(receipt))),
          repairCapabilityFingerprint: executionFingerprint(stableExecutionValue(capability)),
        },
        telemetry: repairTelemetry,
        providerEgressReceipts,
        derivation: {
          version: 1,
          kind: 'analytical_repair',
          sourceRunId: sourceRun.id,
          ...(sourceFailure?.failureId ? { sourceFailureId: sourceFailure.failureId } : {}),
          attempt: 1,
        },
      };
      const repairTraceReference = repairTrace.finalize({
        status: 'completed',
        terminalOutcome: 'needs_review',
        trustState: 'review_required',
        selectedTier: 'exploratory_sql',
      });
      if (repairTraceReference) derivedRun.traceReference = repairTraceReference;
      await agentRunStore.save(derivedRun);
      recordConversationTurn(threadId ? getConversationStore() : null, threadId, derivedRun);
      res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ run: derivedRun }));
      return;
    }

    if (req.method === 'POST' && /^\/api\/agent-runs\/[^/]+\/analytical-repair$/.test(path)) {
      const match = path.match(/^\/api\/agent-runs\/([^/]+)\/analytical-repair$/);
      const id = decodeURIComponent(match?.[1] ?? '');
      const run = await agentRunStore.get(id);
      if (!run) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Agent run not found.' }));
        return;
      }
      if (run.status !== 'blocked' || run.stopReason !== 'blocked') {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          code: 'REPAIR_CAPABILITY_REQUIRED',
          error: 'Only a terminal blocked run with a blocked stop reason may derive an analytical repair.',
        }));
        return;
      }
      const source = analyticalFailedRunFromAgentRun(run);
      if (!source) {
        res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'This run has no retained analytical failure artifact.' }));
        return;
      }
      const body = await readJSON(req).catch(() => null);
      const record = agentRunRecord(body);
      const repair = (agentRunRecord(record?.repair) ?? record) as unknown as AnalyticalRepairRequestV1 | undefined;
      if (!repair) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'A v1 analytical repair request is required.' }));
        return;
      }
      // API-007: snapshot refresh is resolved by the runtime, not trusted from
      // browser input. projectSnapshot() recompiles when governed sources have
      // changed and gives the immutable identity used by the derivation.
      const repairWithRuntimeContext: AnalyticalRepairRequestV1 = repair.action === 'refresh_snapshot'
        ? { ...repair, refreshedSnapshotId: projectSnapshot().snapshotId }
        : repair;
      const result = deriveAnalyticalRepair(source, repairWithRuntimeContext);
      if (result.status === 'blocked') {
        const status = result.code === 'SOURCE_FINGERPRINT_MISMATCH'
          ? 409
          : result.code === 'PERMISSION_FAILURE_TERMINAL' || result.code === 'ACTION_NOT_ALLOWED'
            ? 403
            : 400;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
        return;
      }
      res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(result));
      return;
    }

    if (req.method === 'POST' && /^\/api\/agent-runs\/[^/]+\/cancel$/.test(path)) {
      const match = path.match(/^\/api\/agent-runs\/([^/]+)\/cancel$/);
      const id = decodeURIComponent(match?.[1] ?? '');
      if (!cancelActiveAgentRun(id)) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: 'This run is no longer active.' }));
        return;
      }
      res.writeHead(202, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ ok: true, id }));
      return;
    }

    if (req.method === 'POST' && path === '/api/agent-runs') {
      try {
        const body = await readJSON(req).catch(() => null);
        const parsed = parseAgentRunRequestBody(body);
        if (!parsed.request) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: parsed.error ?? 'Invalid agent run request.' }));
          return;
        }
        // A trace surface is host-controlled metadata. Do not parse it from
        // the JSON body: only the unguessable per-runtime capability passed
        // from `dql agent ask` may mark this local request as CLI.
        const traceSurface = cliAskTraceCapabilities.consume({
          capability: req.headers['x-dql-ask-trace-capability'],
          scope: 'agent-runs',
          loopbackServer: loopback,
          remoteAddress: req.socket.remoteAddress,
        });
        if (traceSurface) parsed.request.traceSurface = traceSurface;
        // The answer-loop cascade now proves certified/semantic/generated tiers
        // after retrieval and execution. Avoid pre-routing ordinary Ask runs from
        // token-overlap signals; explicit callers may still provide signals.
        // Thread-scoped runs: the persisted thread supplies prior turns (server
        // state wins; the client-built context stays the no-threadId fallback).
        const conversationStore = parsed.request.threadId ? getConversationStore() : null;
        if (conversationStore && parsed.request.threadId && conversationStore.getThread(parsed.request.threadId)) {
          parsed.request.conversationContext = await conversationContextFromThread(
            conversationStore,
            parsed.request.threadId,
            parsed.request.question,
            Boolean(parsed.request.selectedEvidenceId),
          );
          // The persisted thread is authoritative for prior turns. Raw client
          // history would duplicate the same conversation into the prompt a
          // second time — dropping it keeps follow-up prompts bounded.
          if (parsed.request.history?.length) parsed.request.history = [];
          // Must run before `AgentRunEngine.run`: the Ask runtime freezes its
          // requirement seed before later retrieval/context-pack construction.
          // This host-only call turns a persisted plural result set into one
          // immutable local member filter or a typed continuity gap.
          hydratePersistedPriorResultMemberBinding(parsed.request);
        }
        // An explicit result selection is stronger than conversational prose:
        // rebind it directly from durable run storage after any thread
        // hydration, so it remains stable across reloads and cannot be
        // overwritten by a best-effort text follow-up classifier.
        hydratePersistedSelectedResultBinding(parsed.request, agentRunStore);
        // Threadless/public continuation JSON is deliberately non-authoritative.
        // If a plural deictic Ask cannot be rebound from a persisted member set,
        // fail closed before retrieval or planning rather than turning "those
        // customers" into an unscoped governed query. This also covers a valid
        // but empty/legacy thread where no retained member set was recoverable.
        if (isAskContinuationMode(parsed.request.requestedMode)) {
          markUnavailablePluralPriorResultSet(parsed.request);
        }
        const wantsStream = url.searchParams.get('stream') === '1' || url.searchParams.get('stream') === 'true';
        // REQUEST IDENTITY. A browser that lost its stream before the accepted
        // event used to resubmit and start a second run doing the same work.
        // With an Idempotency-Key the submission is claimed before anything
        // runs; a replay attaches to the original run, a changed question
        // under the same key conflicts, and an unknown outcome stays explicit.
        const idempotencyKey = typeof req.headers['idempotency-key'] === 'string' ? req.headers['idempotency-key'].trim().slice(0, 200) : '';
        const requestFingerprint = idempotencyKey
          ? createHash('sha256').update(JSON.stringify({
            question: parsed.request.question,
            requestedMode: parsed.request.requestedMode ?? null,
            threadId: parsed.request.threadId ?? null,
            selectedEvidenceId: parsed.request.selectedEvidenceId ?? null,
            executionTarget: parsed.request.executionTarget ?? null,
          })).digest('hex')
          : '';
        const priorClaim = idempotencyKey ? agentRunStore.requestClaim(idempotencyKey) : undefined;
        if (priorClaim) {
          if (priorClaim.fingerprint !== requestFingerprint) {
            res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ error: 'This request identity was already used for a different submission.', code: 'IDEMPOTENCY_CONFLICT', runId: priorClaim.runId }));
            return;
          }
          const priorRun = await agentRunStore.get(priorClaim.runId);
          const inFlight = activeAgentRunControllers.has(priorClaim.runId);
          if (priorRun && !inFlight) {
            if (wantsStream) {
              res.writeHead(200, { 'Content-Type': 'text/event-stream; charset=utf-8', 'Cache-Control': 'no-cache', 'Connection': 'keep-alive', 'X-Accel-Buffering': 'no' });
              writeAgentRunSse(res as unknown as ServerResponse, 'agent-run-accepted', { runId: priorClaim.runId, replayed: true });
              writeAgentRunSse(res as unknown as ServerResponse, 'agent-run-complete', slimAgentRunForTransport(priorRun));
              res.end();
            } else {
              res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
              res.end(serializeJSON({ run: slimAgentRunForTransport(priorRun), replayed: true }));
            }
            return;
          }
          if (inFlight) {
            // Attach to the original run: report progress from the store until it settles.
            if (wantsStream) {
              res.writeHead(200, { 'Content-Type': 'text/event-stream; charset=utf-8', 'Cache-Control': 'no-cache', 'Connection': 'keep-alive', 'X-Accel-Buffering': 'no' });
              writeAgentRunSse(res as unknown as ServerResponse, 'agent-run-accepted', { runId: priorClaim.runId, replayed: true });
              const deadline = Date.now() + 10 * 60_000;
              while (Date.now() < deadline && !res.destroyed) {
                await new Promise((resolve) => setTimeout(resolve, 500));
                if (activeAgentRunControllers.has(priorClaim.runId)) continue;
                const settled = await agentRunStore.get(priorClaim.runId);
                if (settled) writeAgentRunSse(res as unknown as ServerResponse, 'agent-run-complete', slimAgentRunForTransport(settled));
                else writeAgentRunSse(res as unknown as ServerResponse, 'agent-run-error', { error: 'The original submission ended without a stored run; check the run list before asking again.' });
                break;
              }
              if (!res.writableEnded) res.end();
            } else {
              res.writeHead(202, { 'Content-Type': 'application/json; charset=utf-8' });
              res.end(serializeJSON({ runId: priorClaim.runId, status: 'running', replayed: true }));
            }
            return;
          }
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'An earlier submission with this request identity ended with an unknown outcome. Check the run list before asking again.', code: 'REQUEST_OUTCOME_UNKNOWN', runId: priorClaim.runId }));
          return;
        }
        // The public body may carry UI correlation data, but the run identity
        // is server-owned. Mint it before every controller/SSE/engine handoff
        // so no client-provided string can bind a SQL capability or operation.
        const runId = randomUUID();
        parsed.request.runId = runId;
        if (idempotencyKey) agentRunStore.claimRequest(idempotencyKey, runId, requestFingerprint);
        // This is host-selected rollout state, never user ingress. In
        // particular, it lets `AgentRunEngine` route explicit Research through
        // the authoritative V2 kernel once while retaining legacy/shadow
        // forced-mode behavior unchanged.
        parsed.request.askAgentRuntimeMode = askAgentRuntimeMode;
        const runController = new AbortController();
        activeAgentRunControllers.set(runId, runController);
        let streamConnected = true;
        res.on('close', () => { streamConnected = false; });
        const writeStream = (
          event: string,
          data: AgentRun | AgentRunEvent | { error: string } | { runId?: string; delta: string } | { runId?: string; operationId?: string },
        ) => {
          if (!streamConnected || res.destroyed || res.writableEnded) return;
          try { writeAgentRunSse(res as unknown as ServerResponse, event, data); } catch { streamConnected = false; }
        };
        if (wantsStream) {
          res.writeHead(200, {
            'Content-Type': 'text/event-stream; charset=utf-8',
            'Cache-Control': 'no-cache',
            'Connection': 'keep-alive',
            'X-Accel-Buffering': 'no',
          });
        }
        const operation = operationCoordinator.create({
          type: 'agent_run',
          scope: `agent-run:${runId}`,
          resourceRevision: parsed.request.threadId,
          message: 'AI request accepted. You can change pages while it runs.',
          cancellable: true,
        });
        if (wantsStream) writeStream('agent-run-accepted', { runId, operationId: operation?.id });
        let completedRun: AgentRun | undefined;
        let runError: unknown;
        try {
          const executeRun = async (
            operationSignal?: AbortSignal,
            report?: (progress: Partial<LocalOperationProgress>) => void,
          ) => {
            const ingressSignal = AbortSignal.any([
              runController.signal,
              ...(operationSignal ? [operationSignal] : []),
            ]);
            parsed.request!.runBudget = createAgentRunBudget({
              requestedMode: parsed.request!.requestedMode,
              inheritedSignal: ingressSignal,
            });
            parsed.request!.signal = parsed.request!.runBudget.hardSignal;
            const runProviderEvidence = new RunScopedProviderDispatchEvidence(
              agentRunProviderDispatchBudgetForMode(parsed.request!.requestedMode, {
                ordinaryAskNarration: readOrdinaryAskNarrationPolicy(projectRoot) !== 'off',
              }),
              parsed.request!.runBudget,
              resolveProviderResultRowEgressPolicy({
                projectSetting: projectConfig?.agent?.providerResultRowEgress,
                requestedMode: parsed.request!.requestedMode,
                researchOptIn: parsed.request!.requestedMode === 'research'
                  && parsed.request!.researchResultRowsOptIn === true,
              }),
            );
            report?.({ phase: 'reasoning', progress: 8, message: 'Grounding the request and selecting the governed route.' });
            try {
              const engineRun = await agentRunProviderEvidenceContext.run(
                runProviderEvidence,
                () => agentRunEngine.run(parsed.request!, (event) => {
                  runProviderEvidence.setRoute(event.route);
                  if (wantsStream) writeStream('agent-run-event', event);
                  report?.({ phase: event.type, progress: 45, message: event.message });
                }, (delta) => {
                  if (wantsStream) writeStream('agent-run-answer-delta', { runId: parsed.request!.runId, delta });
                }),
              );
              const rawRun = mergeRunScopedProviderDispatchEvidence(
                engineRun,
                runProviderEvidence.snapshot(engineRun.telemetry?.fallbackReason ?? engineRun.stopReason),
              );
              let resolvedTargetFingerprint: string | undefined;
              try {
                const resolvedTarget = await resolveAgentRunExecutionConnection({
                  question: rawRun.question,
                  executionTarget: rawRun.executionTarget,
                });
                const resolvedTargetName = rawRun.executionTarget?.target === 'connection'
                  ? rawRun.executionTarget.connectionName
                  : rawRun.executionTarget?.target === 'local'
                    ? 'local'
                    : projectConfig.defaultConnectionName;
                resolvedTargetFingerprint = targetGenerationFingerprint(resolvedTarget, resolvedTargetName);
              } catch {
                // Missing target-generation evidence keeps automatic repair
                // ineligible; the failed run itself remains fully inspectable.
              }
              const run = attachAnalyticalRepairCapability(rawRun, resolvedTargetFingerprint);
              // The engine persists before the host can validate the DQL wrapper;
              // replace that row with the server-owned capability atomically.
              await agentRunStore.save(run);
              completedRun = run;
              recordConversationTurn(conversationStore, parsed.request!.threadId, run);
              return { runId: run.id, threadId: parsed.request!.threadId, status: run.status };
            } catch (error) {
              runError = error;
              throw error;
            }
          };

          if (operation) await operationCoordinator.run(operation.id, (signal, report) => executeRun(signal, report));
          else await executeRun();
          if (runError) throw runError;
          if (!completedRun) throw new Error('The AI request ended before producing a stored run.');
          if (wantsStream) {
            // The complete stored run stays in the run-state route; the live
            // stream ships only the renderable transport projection.
            writeStream('agent-run-complete', slimAgentRunForTransport(completedRun));
            if (streamConnected && !res.writableEnded) res.end();
            return;
          }
          res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
          // Same run, same reader as the stream above, so it ships the same
          // projection. Sending the stored record here instead made an ordinary
          // completed Ask a 4.66 MB reply.
          res.end(serializeJSON({ run: slimAgentRunForTransport(completedRun) }));
        } finally {
        activeAgentRunControllers.delete(runId);
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        if (res.headersSent) {
          if (!res.destroyed && !res.writableEnded) {
            writeAgentRunSse(res as unknown as ServerResponse, 'agent-run-error', { error: message });
            res.end();
          }
        } else {
          res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: message }));
        }
      }
      return;
    }

    // Stakeholder → analyst handoff: turn a review-required output into a draft
    // research run in the analyst notebook queue (no authoring by the stakeholder).
    if (req.method === 'POST' && path === '/api/agent-runs/request-certification') {
      try {
        const body = await readJSON(req).catch(() => null);
        const record = agentRunRecord(body);
        const question = record ? agentRunString(record.question) : undefined;
        if (!question) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'question is required.' }));
          return;
        }
        const notebookPath = (record && agentRunString(record.notebookPath))
          ?? `notebooks/certification-requests/${Date.now()}.dqlnb`;
        const generatedSql = record ? agentRunString(record.generatedSql) : undefined;
        const dqlArtifact = record ? normalizeDqlArtifactReference(record.dqlArtifact) : undefined;
        try {
          const storage = openNotebookResearchStorage();
          try {
            const created = storage.createRun({
              notebookPath,
              title: agentRunTitle(question, 'Certification request'),
              question,
              intent: 'ad_hoc_analysis',
              domain: record ? agentRunString(record.domain) : undefined,
              owner: record ? agentRunString(record.owner) : undefined,
              generatedSql,
              dqlArtifact,
              context: {
                surface: 'stakeholder_request_certification',
                requestedContext: agentRunRecord(record?.context) ?? null,
                dqlArtifact: dqlArtifact ?? null,
              },
            });
            res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ ok: true, researchRunId: created.id, notebookPath }));
          } finally {
            storage.close();
          }
        } catch (error) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: formatNotebookResearchStorageError(error) }));
        }
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const agentRunMatch = /^\/api\/agent-runs\/([^/]+)$/.exec(path);
    if (req.method === 'GET' && agentRunMatch) {
      const id = decodeURIComponent(agentRunMatch[1]);
      const run = await agentRunStore.get(id);
      const progress = run ? undefined : agentRunStore.getProgress(id);
      if (!run && !progress) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Agent run not found.' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(run
        ? { lifecycleState: 'terminal', run }
        : { lifecycleState: progress!.lifecycle.state, progress }));
      return;
    }

    // Readiness → propose backbone. Returns a readiness summary plus the ranked
    // DRAFT proposals (each with its stored Certifier verdict) so the notebook
    // "Get Started" surface can route them into human review. dryRun preview —
    // nothing is written or certified by this call.
    if (req.method === 'GET' && path === '/api/agent-runs/tier-distribution') {
      try {
        const store = getConversationStore();
        const limitParam = Number(url.searchParams.get('limit'));
        const limit = Number.isFinite(limitParam) && limitParam > 0 ? limitParam : undefined;
        const distribution = store
          ? store.tierDistribution({ ...(limit ? { limit } : {}) })
          : { total: 0, byRouteTier: {}, byTerminalLane: {} };
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(JSON.stringify(distribution));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(JSON.stringify({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if ((req.method === 'GET' || req.method === 'POST') && path === '/api/propose') {
      try {
        let owner: string | undefined;
        let limit: number | undefined;
        if (req.method === 'POST') {
          const body = await readJSON(req).catch(() => ({}));
          if (typeof body?.owner === 'string') owner = body.owner;
          if (typeof body?.limit === 'number' && Number.isFinite(body.limit) && body.limit > 0) {
            limit = body.limit;
          }
        } else {
          const ownerParam = url.searchParams.get('owner');
          if (ownerParam) owner = ownerParam;
          const limitParam = Number(url.searchParams.get('limit'));
          if (Number.isFinite(limitParam) && limitParam > 0) limit = limitParam;
        }
        const readiness = buildProposeReadiness(projectRoot, loadProjectConfig(projectRoot), { owner, limit });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(readiness));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Composting preview: mine certified block clusters for semantic metric
    // candidates. Read-only; returns draft YAML + PR body text for review.
    if ((req.method === 'GET' || req.method === 'POST') && path === '/api/propose/composting') {
      try {
        let owner: string | undefined;
        let limit: number | undefined;
        let minSupport: number | undefined;
        if (req.method === 'POST') {
          const body = await readJSON(req).catch(() => ({}));
          if (typeof body?.owner === 'string') owner = body.owner;
          if (typeof body?.limit === 'number' && Number.isFinite(body.limit) && body.limit > 0) limit = body.limit;
          if (typeof body?.minSupport === 'number' && Number.isFinite(body.minSupport) && body.minSupport > 1) minSupport = body.minSupport;
        } else {
          const ownerParam = url.searchParams.get('owner');
          if (ownerParam) owner = ownerParam;
          const limitParam = Number(url.searchParams.get('limit'));
          if (Number.isFinite(limitParam) && limitParam > 0) limit = limitParam;
          const minSupportParam = Number(url.searchParams.get('minSupport'));
          if (Number.isFinite(minSupportParam) && minSupportParam > 1) minSupport = minSupportParam;
        }
        const changeset = buildSemanticCompostingChangeset(projectRoot, { owner, limit, minSupport });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(changeset));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Composting generation: writes only approved metric candidate ids under
    // semantic-layer/metrics/_drafts plus a PR-body artifact. Nothing certified.
    if (req.method === 'POST' && path === '/api/propose/composting/generate') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as {
          ids?: unknown;
          owner?: unknown;
          limit?: unknown;
          minSupport?: unknown;
        };
        const ids = Array.isArray(body?.ids)
          ? body.ids.filter((id): id is string => typeof id === 'string' && id.trim().length > 0)
          : [];
        if (ids.length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide non-empty { ids } to generate semantic composting drafts.' }));
          return;
        }
        const owner = typeof body?.owner === 'string' ? body.owner : undefined;
        const limit = typeof body?.limit === 'number' && Number.isFinite(body.limit) && body.limit > 0 ? body.limit : undefined;
        const minSupport = typeof body?.minSupport === 'number' && Number.isFinite(body.minSupport) && body.minSupport > 1 ? body.minSupport : undefined;
        const result = generateSemanticCompostingDrafts(projectRoot, ids, { owner, limit, minSupport });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Deterministic PLAN only (classify → plan). Writes NOTHING. Same data the
    // readiness endpoint embeds, exposed standalone for the approve gate.
    if (req.method === 'POST' && path === '/api/propose/plan') {
      try {
        const readiness = buildProposeReadiness(projectRoot, loadProjectConfig(projectRoot));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(readiness.ready ? readiness.plan : { ready: false, reason: readiness.reason }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Materialize drafts for an APPROVED scope { slugs } (or { domains }).
    // This is the only propose endpoint that writes — and only for the approved,
    // business-only selection. Nothing is ever certified.
    if (req.method === 'POST' && path === '/api/propose/generate') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as {
          slugs?: unknown;
          domains?: unknown;
          owner?: unknown;
        };
        const config = loadProjectConfig(projectRoot);
        let slugs = Array.isArray(body?.slugs)
          ? body.slugs.filter((s): s is string => typeof s === 'string')
          : [];
        // { domains } → resolve to the plan's slugs for those domains.
        if (slugs.length === 0 && Array.isArray(body?.domains)) {
          const wanted = new Set(body.domains.filter((d): d is string => typeof d === 'string'));
          const readiness = buildProposeReadiness(projectRoot, config);
          slugs = readiness.ready
            ? readiness.plan.domains
                .filter((d) => wanted.has(d.name))
                .flatMap((d) => d.candidates.map((c) => c.slug))
            : [];
        }
        if (slugs.length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide a non-empty { slugs } or { domains } scope to generate.' }));
          return;
        }
        const owner = typeof body?.owner === 'string' ? body.owner : undefined;
        const result = await generateProposeDrafts(projectRoot, slugs, config, { owner });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Materialize a single approved draft { slug } and return it. Convenience for
    // the per-block "Review & Certify" affordance.
    if (req.method === 'POST' && path === '/api/propose/draft') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as { slug?: unknown; owner?: unknown };
        const slug = typeof body?.slug === 'string' ? body.slug : '';
        if (!slug) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide { slug } to draft.' }));
          return;
        }
        const owner = typeof body?.owner === 'string' ? body.owner : undefined;
        const result = await generateProposeDrafts(projectRoot, [slug], loadProjectConfig(projectRoot), { owner });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Transparent PLAN PREVIEW for ONE candidate (spec 14, part A). Lazy +
    // expensive: builds the real SQL + Certifier verdict + best-effort AI
    // enrichment for a single slug, so the UI shows the actual logic before a
    // human commits. Writes NOTHING.
    if (req.method === 'GET' && path === '/api/propose/preview') {
      try {
        const slug = url.searchParams.get('slug')?.trim();
        if (!slug) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide a ?slug= query parameter.' }));
          return;
        }
        const candidate = await buildProposeCandidatePreview(projectRoot, slug, url.searchParams.get('owner') ?? undefined);
        if (!candidate) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `No proposed candidate found for slug "${slug}".` }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ candidate }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Unified AI BUILD (spec 14, part B). ONE engine, two targets:
    //   target:'cell'  → generate SQL from the prompt (+ context). Writes nothing.
    //   target:'block' → assemble a COMPLETE draft, WRITE it, return preview fields.
    // Never routes through the governed Q&A answer-loop.
    if (req.method === 'POST' && path === '/api/ai/build') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as {
          prompt?: unknown;
          context?: { cellSql?: unknown; selection?: unknown };
          target?: unknown;
          owner?: unknown;
          domain?: unknown;
          modelAreaId?: unknown;
          mode?: unknown;
          blockPath?: unknown;
          skillRefs?: unknown;
          threadId?: unknown;
          executionTarget?: unknown;
        };
        const prompt = typeof body?.prompt === 'string' ? body.prompt.trim() : '';
        if (!prompt) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide a non-empty { prompt }.' }));
          return;
        }
        const target = body?.target === 'cell' || body?.target === 'block' ? body.target : undefined;
        if (!target) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: "Provide { target: 'cell' | 'block' }." }));
          return;
        }
        const context = {
          cellSql: typeof body?.context?.cellSql === 'string' ? body.context.cellSql : undefined,
          selection: typeof body?.context?.selection === 'string' ? body.context.selection : undefined,
        };
        const owner = typeof body?.owner === 'string' ? body.owner : undefined;
        const domain = typeof body?.domain === 'string' && body.domain.trim() ? body.domain.trim() : undefined;
        const modelAreaId = typeof body?.modelAreaId === 'string' && body.modelAreaId.trim() ? body.modelAreaId.trim() : undefined;
        const purpose = typeof (body as { purpose?: unknown })?.purpose === 'string'
          ? (body as { purpose?: string }).purpose?.trim() || undefined
          : undefined;
        const userId = typeof (body as { userId?: unknown })?.userId === 'string'
          ? (body as { userId?: string }).userId
          : undefined;
        // The same scope selection Ask carries (CTX-001): skills to select, and
        // the thread this build belongs to; the execution target below decides
        // which warehouse the probe runs on.
        const buildScope = askScopeFromWorkspace({ domain, purpose, modelAreaId, skillRefs: body?.skillRefs });
        const buildThreadId = typeof body?.threadId === 'string' && body.threadId.trim() ? body.threadId.trim() : undefined;
        // Edit mode (spec 17, part A): modify the block at `blockPath` in place.
        const mode = body?.mode === 'edit' ? 'edit' : 'create';
        const blockPath = typeof body?.blockPath === 'string' && body.blockPath.trim()
          ? body.blockPath.trim()
          : undefined;
        if (mode === 'edit' && (target !== 'block' || !blockPath)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: "Edit mode requires target 'block' and a { blockPath }." }));
          return;
        }
        // Ensure the agent knowledge graph is built before generating, so the Build
        // path's semantic-metric routing sees the governed metrics on the very first
        // call (a cold Build-before-Ask otherwise reads an unbuilt KG and misses them).
        // Mirrors what the Ask path does; reindex is idempotent and closes its write
        // connection, so the read-only metric load observes committed data.
        try {
          await reindexProject(projectRoot, { kgPath: defaultKgPath(projectRoot) });
        } catch {
          // Best-effort: a failed reindex falls back to whatever KG exists (or none).
        }
        const { domainContext, contextPack } = await buildDirectBuildContext({
          question: prompt,
          domain,
          purpose,
          modelAreaId,
          skillRefs: buildScope.skillRefs,
          surface: target === 'cell' ? 'notebook' : 'block',
          selectedContext: { target, mode, blockPath, owner, ...(buildThreadId ? { threadId: buildThreadId } : {}) },
        });
        // Inject user-authored Skills as business context; the engine selects the
        // relevant subset and stamps `appliedSkills` on the result.
        const skills = loadSkills(projectRoot).skills;
        const result: BuildFromPromptResult = await buildFromPrompt({
          projectRoot,
          prompt,
          context,
          target,
          mode,
          blockPath,
          owner,
          domain,
          modelAreaId,
          contextPack,
          domainContext,
          userId,
          skills,
          dbtManifestPath: resolveDbtManifestPath(projectRoot, loadProjectConfig(projectRoot)),
          // Reflect-before-certify probe (P2): run the candidate block's SQL to learn
          // its REAL output columns and evaluate the declared invariants, so the agent
          // can reconcile the output contract + produce a grounded verdict before a
          // human reviews. Best-effort — buildFromPrompt falls back to a static reflection.
          executionProbe: async ({ sql, invariants }) => {
            const activeConnection = await resolveExecutionConnection(body as Record<string, unknown>);
            const prepared = prepareLocalExecution(sql, activeConnection, projectRoot, projectConfig);
            const probeSql = `SELECT * FROM (${stripSqlTerminator(prepared.sql)}) _dql_probe LIMIT 2000`;
            const probeResult = await executor.executeQuery(probeSql, [], runtimeVariables({}), prepared.connection);
            const rows = (Array.isArray(probeResult?.rows) ? probeResult.rows : []) as Array<Record<string, unknown>>;
            const rawColumns = Array.isArray((probeResult as { columns?: unknown })?.columns)
              ? (probeResult as { columns: unknown[] }).columns
              : [];
            const actualColumns = rawColumns.length > 0
              ? rawColumns.map((c) => (typeof c === 'string' ? c : (c as { name?: string })?.name ?? String(c)))
              : (rows[0] ? Object.keys(rows[0]) : []);
            const invariantResults = evaluateInvariants(invariants, { columns: actualColumns, rows });
            const passed = invariantResults.filter((r) => r.passed && !r.uncheckable).length;
            const failed = invariantResults.filter((r) => !r.passed && !r.uncheckable).length;
            return {
              actualColumns,
              invariantResults,
              tests: invariants.length > 0
                ? { passed, failed, assertionCount: invariantResults.length }
                : undefined,
            };
          },
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Resolved local OSS owner (spec 14, part C). Stamps drafts so a new block is
    // never born with a "Missing owner" Certifier strike.
    if (req.method === 'GET' && path === '/api/identity') {
      try {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ owner: resolveLocalOwner(projectRoot) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Skills (spec 16) — user-authored business context. AI drafts, humans
    //    certify; skills never carry certification. PROJECT skills (user empty)
    //    are shared; PERSONAL skills (user set) are user-bound. ────────────────
    if (req.method === 'GET' && path === '/api/skills/settings') {
      try {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(buildSkillPathSettings(projectRoot)));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'PUT' && path === '/api/skills/settings') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as { path?: unknown };
        const requestedPath = typeof body.path === 'string' ? body.path.trim() : '';
        if (!requestedPath || requestedPath.includes('\0')) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide an existing Skills folder path.' }));
          return;
        }
        const resolvedPath = resolve(projectRoot, requestedPath);
        if (!existsSync(resolvedPath) || !statSync(resolvedPath).isDirectory()) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Skills folder not found: ${resolvedPath}` }));
          return;
        }
        const configPath = join(projectRoot, 'dql.config.json');
        const raw = existsSync(configPath)
          ? JSON.parse(readFileSync(configPath, 'utf-8')) as Record<string, unknown>
          : {};
        const layout = raw.layout && typeof raw.layout === 'object' && !Array.isArray(raw.layout)
          ? raw.layout as Record<string, unknown>
          : {};
        raw.layout = { ...layout, skillsPath: requestedPath };
        writeFileSync(configPath, `${JSON.stringify(raw, null, 2)}\n`, 'utf-8');
        projectConfig = loadProjectConfig(projectRoot);
        invalidateAgentProjectState(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(buildSkillPathSettings(projectRoot)));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/skills') {
      try {
        const skills = [
          ...loadSkills(projectRoot).skills.filter((skill) => skill.scope === 'project'),
          ...loadPrivateSkills(projectRoot),
        ].map(serializeSkill);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ skills }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Form pickers: metrics from the semantic layer + certified block ids.
    if (req.method === 'GET' && path === '/api/skills/options') {
      try {
        const query = (url.searchParams.get('q') ?? '').trim().toLowerCase();
        const limit = Math.min(50, Math.max(1, Number(url.searchParams.get('limit') ?? 30) || 30));
        const matches = (value: string) => !query || value.toLowerCase().includes(query);
        const metrics = semanticLayer
          ? semanticLayer.listMetrics(undefined, { includeMeasures: false }).map((m) => m.name).filter(matches).sort().slice(0, limit)
          : [];
        const manifest = buildManifest({
          projectRoot,
          dqlVersion: 'notebook',
          dbtManifestPath: resolveDbtManifestPath(projectRoot) ?? undefined,
        });
        const blocks = Object.values(manifest.blocks)
          .filter((b) => b.status === 'certified')
          .map((b) => b.name)
          .filter(matches)
          .sort();
        const modelingRefs = [
          ...Object.values(manifest.modeling?.entities ?? {}).map((entity) => entity.qualifiedId),
          ...Object.values(manifest.modeling?.relationships ?? {}).map((relationship) => relationship.qualifiedId),
        ].filter(matches).sort();
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ metrics, blocks: blocks.slice(0, limit), modelingRefs: modelingRefs.slice(0, limit) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/skills') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as { skill?: unknown };
        const input = parseSkillInput(body?.skill);
        if (!input) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide { skill } with id, scope, and body.' }));
          return;
        }
        const wantsPrivate = (body?.skill as { visibility?: unknown } | undefined)?.visibility === 'private';
        if (wantsPrivate) {
          const target = privateSkillPath(projectRoot, input.id);
          const sharedTwin = loadSkills(projectRoot).skills.some((skill) => skill.id === input.id);
          if (existsSync(target) || sharedTwin) {
            res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ error: `A skill named ${input.id} already exists. Choose another name.` }));
            return;
          }
          const written = writeSkill(projectRoot, { ...input, sourcePath: target });
          // Nothing shared changed, so there is no index or snapshot to refresh:
          // a private skill is invisible to retrieval until it is published.
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            skill: serializeSkill({
              ...written,
              localId: written.id,
              qualifiedId: `${PRIVATE_SKILL_IDENTITY_PREFIX}${written.id}`,
            }),
          }));
          return;
        }
        const skill = writeSkill(projectRoot, input);
        projectSnapshots.invalidate();
        invalidateAgentProjectState(projectRoot);
        await refreshUnifiedProjectIndexes(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ skill: serializeSkill(skill) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // POST /api/skills/publish — move a private skill into the shared Skills
    // folder. This is the moment it starts shaping answers, so the project
    // indexes are refreshed here and nowhere earlier.
    if (req.method === 'POST' && path === '/api/skills/publish') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as { id?: unknown };
        const identity = typeof body.id === 'string' ? body.id.trim() : '';
        const privateId = privateSkillLocalId(identity);
        if (!privateId) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Only a private skill can be published.' }));
          return;
        }
        const source = privateSkillPath(projectRoot, privateId);
        if (!existsSync(source)) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: `Private skill not found: ${privateId}` }));
          return;
        }
        const parsed = parseSkill(readFileSync(source, 'utf-8'), source);
        const domains = parsed?.domains?.length ? parsed.domains : parsed?.domain ? [parsed.domain] : [];
        const destination = skillPath(projectRoot, privateId, domains);
        const sharedTwin = loadSkills(projectRoot).skills.some((skill) => skill.id === privateId);
        if (existsSync(destination) || sharedTwin) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            ok: false,
            error: `A shared skill named ${privateId} already exists. Rename the private skill before publishing it.`,
          }));
          return;
        }
        mkdirSync(dirname(destination), { recursive: true });
        renameSync(source, destination);
        projectSnapshots.invalidate();
        invalidateAgentProjectState(projectRoot);
        await refreshUnifiedProjectIndexes(projectRoot);
        const published = loadSkills(projectRoot).skills.find((skill) => resolve(skill.sourcePath) === resolve(destination));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          previousId: identity,
          path: relative(projectRoot, destination).replace(/\\/g, '/'),
          ...(published ? { skill: serializeSkill(published) } : {}),
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'PUT' && path.startsWith('/api/skills/')) {
      try {
        const id = decodeURIComponent(path.slice('/api/skills/'.length));
        const body = (await readJSON(req).catch(() => ({}))) as { skill?: unknown };
        const input = parseSkillInput(body?.skill, id);
        if (!input) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide { skill } with scope and body.' }));
          return;
        }
        const privateId = privateSkillLocalId(id);
        if (privateId) {
          // Written back to its own private file. Resolving it through
          // `loadSkills` would miss it and write a shared copy instead —
          // editing a private skill would silently publish it.
          const target = privateSkillPath(projectRoot, privateId);
          if (!existsSync(target)) {
            res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ error: `Private skill not found: ${privateId}` }));
            return;
          }
          const written = writeSkill(projectRoot, { ...input, id: privateId, sourcePath: target });
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            skill: serializeSkill({ ...written, localId: privateId, qualifiedId: id }),
          }));
          return;
        }
        const skill = writeSkill(projectRoot, { ...input, qualifiedId: id });
        projectSnapshots.invalidate();
        invalidateAgentProjectState(projectRoot);
        await refreshUnifiedProjectIndexes(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ skill: serializeSkill(skill) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'DELETE' && path.startsWith('/api/skills/')) {
      try {
        const id = decodeURIComponent(path.slice('/api/skills/'.length));
        const privateId = privateSkillLocalId(id);
        if (privateId) {
          const target = privateSkillPath(projectRoot, privateId);
          if (!existsSync(target)) {
            res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ error: `Private skill not found: ${privateId}` }));
            return;
          }
          // Never committed, so the recovery bundle is the only way back.
          const recovered = moveToTrashBundle(projectRoot, projectRoot, [
            relative(projectRoot, target).replace(/\\/g, '/'),
          ], 'skills');
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: true, recovered }));
          return;
        }
        // A shared skill inside the project goes to the recovery bundle too: an
        // uncommitted one is in no commit to restore. A Skills folder configured
        // outside the project keeps the old delete, since a bundle path must
        // stay inside the project.
        const existing = loadSkills(projectRoot).skills.find((skill) => skill.qualifiedId === id || skill.id === id);
        const relativeSource = existing ? relative(projectRoot, existing.sourcePath).replace(/\\/g, '/') : '';
        let recovered: ReturnType<typeof moveToTrashBundle> | undefined;
        if (existing && relativeSource && !relativeSource.startsWith('..') && !isAbsolute(relativeSource)) {
          recovered = moveToTrashBundle(projectRoot, projectRoot, [relativeSource], 'skills');
        } else {
          deleteSkill(projectRoot, id);
        }
        projectSnapshots.invalidate();
        invalidateAgentProjectState(projectRoot);
        await refreshUnifiedProjectIndexes(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, ...(recovered ? { recovered } : {}) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Ask scope — the domains, subject areas and approved purposes a
    //    question can be scoped to, for the picker in the question box. ────
    if (req.method === 'GET' && path === '/api/ask/scopes') {
      try {
        const manifest = projectSnapshot().manifest;
        const modeling = manifest.modeling;
        const domains = Object.values(modeling?.packages ?? {})
          .map((pkg) => ({
            id: pkg.id,
            label: manifest.domains?.[pkg.id]?.name ?? pkg.id,
            ...(pkg.parent ? { parent: pkg.parent } : {}),
            areas: Object.values(modeling?.areas ?? {}).filter((area) => area.domain === pkg.id).map((area) => ({ id: area.qualifiedId, name: area.name })).sort((a, b) => a.name.localeCompare(b.name)),
            purposes: [...new Set(Object.values(modeling?.interfaces?.imports ?? {}).filter((item) => item.domain === pkg.id && item.purpose).map((item) => item.purpose))].sort(),
          }))
          .sort((a, b) => a.label.localeCompare(b.label));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ domains }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── What Ask will do for a domain (and subject area): the skills and
    //    required filters that apply, the relationships by what Ask may do
    //    with them, and the imports that need a purpose. ──────────────────
    if (req.method === 'GET' && path === '/api/modeling/ask-impact') {
      try {
        const domain = url.searchParams.get('domain') ?? '';
        const area = url.searchParams.get('area') ?? '';
        const manifest = projectSnapshot().manifest;
        const modeling = manifest.modeling;
        if (!domain || !modeling?.packages?.[domain]) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `The domain "${domain}" does not exist.` }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(askImpactFor(manifest, loadSkills(projectRoot).skills, domain, area || undefined)));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Business terms — the words Ask maps to governed definitions. Direct
    //    save like skills: a term carries no join or certification authority,
    //    and Git history is its review. ─────────────────────────────────────
    if (path === '/api/terms' && (req.method === 'GET' || req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE')) {
      const json = (status: number, body: unknown) => {
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(body));
      };
      const readTerms = () => Object.values(buildManifest({ projectRoot, dqlVersion: 'notebook' }).terms ?? {})
        .sort((a, b) => a.name.localeCompare(b.name));
      try {
        if (req.method === 'GET') {
          json(200, { terms: readTerms() });
          return;
        }
        if (req.method === 'DELETE') {
          const filePath = url.searchParams.get('filePath') ?? '';
          if (!readTerms().some((term) => term.filePath === filePath)) {
            json(404, { error: 'That term no longer exists. Refresh the list.' });
            return;
          }
          deleteTermDeclaration(projectRoot, filePath);
          await refreshUnifiedProjectIndexes(projectRoot);
          json(200, { ok: true });
          return;
        }
        const body = (await readJSON(req).catch(() => ({}))) as { term?: unknown; filePath?: unknown };
        const input = parseTermInput(body?.term);
        if (!input) {
          json(400, { error: 'A term needs a name.' });
          return;
        }
        const existing = readTerms();
        const previousPath = req.method === 'PUT' && typeof body.filePath === 'string' ? body.filePath : undefined;
        if (req.method === 'PUT' && !existing.some((term) => term.filePath === previousPath)) {
          json(404, { error: 'That term no longer exists. Refresh the list.' });
          return;
        }
        const clash = existing.find((term) => term.name.toLowerCase() === input.name.toLowerCase() && term.filePath !== previousPath);
        if (clash) {
          json(409, { error: `A term named "${clash.name}" already exists in ${clash.filePath}.` });
          return;
        }
        // A term that names a metric Ask cannot find would teach it a word for
        // nothing, so the link is checked against the governed metrics.
        if (semanticLayer && input.metricRefs?.length) {
          const known = new Set(semanticLayer.listMetrics(undefined, { includeMeasures: false }).map((metric) => metric.name.toLowerCase()));
          const unknown = input.metricRefs.filter((ref) => !known.has(ref.toLowerCase()));
          if (unknown.length) {
            json(400, { error: `Unknown metric${unknown.length === 1 ? '' : 's'}: ${unknown.join(', ')}. Pick metrics from the list.` });
            return;
          }
        }
        const written = writeTermDeclaration(projectRoot, input, { directory: termDirectoryFor(projectRoot, input.domain), existingPath: previousPath });
        await refreshUnifiedProjectIndexes(projectRoot);
        json(200, { term: readTerms().find((term) => term.filePath === written.path) ?? { ...input, filePath: written.path } });
      } catch (error) {
        json(400, { error: error instanceof Error ? error.message : String(error) });
      }
      return;
    }

    // ── Domains (spec 17, part B) — first-class business domain declarations.
    //    Authoring here satisfies `dql doctor`'s "missing domain declaration"
    //    warning. AI drafts, humans certify; domains carry no certification. ────
    if (req.method === 'GET' && path === '/api/domains') {
      try {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ domains: listDomains(projectRoot) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/domains') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as { domain?: unknown };
        const input = parseDomainInput(body?.domain);
        if (!input) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide { domain } with a non-empty name.' }));
          return;
        }
        applyModelingChange(projectRoot, {
          operation: 'upsert_domain',
          value: { ...input, id: input.id ?? domainFolderSlug(input.name).replace(/-/g, '_') },
        });
        await refreshUnifiedProjectIndexes(projectRoot);
        const domain = findDomain(projectRoot, input.id ?? input.name);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ domain }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'PUT' && path.startsWith('/api/domains/')) {
      try {
        const id = decodeURIComponent(path.slice('/api/domains/'.length));
        const body = (await readJSON(req).catch(() => ({}))) as { domain?: unknown };
        const input = parseDomainInput(body?.domain, id);
        if (!input) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Provide { domain } with a name.' }));
          return;
        }
        // If the name changed, remove the old declaration so we never orphan one.
        if (domainKey(id) !== domainKey(input.id ?? input.name)) {
          deleteCanonicalDomainDeclaration(projectRoot, id);
        }
        applyModelingChange(projectRoot, {
          operation: 'upsert_domain',
          value: { ...input, id: input.id ?? id },
        });
        await refreshUnifiedProjectIndexes(projectRoot);
        const domain = findDomain(projectRoot, input.id ?? input.name);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ domain }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'DELETE' && path.startsWith('/api/domains/')) {
      try {
        const id = decodeURIComponent(path.slice('/api/domains/'.length));
        deleteCanonicalDomainDeclaration(projectRoot, id);
        await refreshUnifiedProjectIndexes(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Domain + Skill bootstrap — evidence-first, session-only until save. ──
    if (req.method === 'POST' && path === '/api/context-bootstrap') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as { ai?: unknown };
        const manifest = buildManifest({ projectRoot, dqlVersion: 'notebook' });
        const existingSkills = new Set(loadSkills(projectRoot).skills.map((skill) => skill.id));
        const candidates = draftDomainSkillBootstrap(manifest).map((candidate) => (
          candidate.kind === 'skill' && candidate.skill && existingSkills.has(candidate.skill.id)
            ? { ...candidate, action: 'unchanged' as const, evidence: [...candidate.evidence, 'Existing skill preserved'] }
            : candidate
        ));
        const session = writeContextBootstrapSession(projectRoot, {
          candidates,
          status: 'queued',
          ai: { requested: body.ai !== false, mode: 'pending' },
          progress: bootstrapProgress(candidates, new Set(), 4, 'Queued repository inventory for domain and skill drafts…', ['Draft session created.']),
        });
        void enrichContextBootstrapSession(projectRoot, session.id).catch((error) => {
          updateContextBootstrapSession(projectRoot, session.id, (current) => ({
            ...current,
            status: 'needs_attention',
            progress: bootstrapProgress(current.candidates, new Set(), 100, 'Repository draft is ready, but AI enrichment could not start.', [...current.progress.events, 'AI enrichment could not start.']),
            warnings: [...(current.warnings ?? []), `AI enrichment could not start: ${error instanceof Error ? error.message : String(error)}`],
          }));
        });
        res.writeHead(202, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(session));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/context-bootstrap/latest') {
      try {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ session: latestOpenContextBootstrapSession(projectRoot) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/context-bootstrap/')) {
      try {
        const id = decodeURIComponent(path.slice('/api/context-bootstrap/'.length));
        const session = readContextBootstrapSession(projectRoot, id);
        if (!session) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Bootstrap session not found.' }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(session));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && /^\/api\/context-bootstrap\/[^/]+\/save-selected$/.test(path)) {
      try {
        const match = path.match(/^\/api\/context-bootstrap\/([^/]+)\/save-selected$/);
        const id = decodeURIComponent(match?.[1] ?? '');
        const session = readContextBootstrapSession(projectRoot, id);
        if (!session) throw new Error('Bootstrap session not found.');
        if (!['ready', 'needs_attention'].includes(session.status)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Wait for the repository draft to finish before saving selected candidates.' }));
          return;
        }
        const body = (await readJSON(req).catch(() => ({}))) as { candidateIds?: unknown };
        const selected = new Set(Array.isArray(body.candidateIds) ? body.candidateIds.filter((value): value is string => typeof value === 'string') : []);
        const saved: Array<{ id: string; path?: string; status: 'saved' | 'skipped' | 'blocked'; blockers?: string[] }> = [];
        for (const candidate of session.candidates) {
          if (!selected.has(candidate.id)) continue;
          if (candidate.action === 'unchanged') {
            saved.push({ id: candidate.id, status: 'skipped' });
            continue;
          }
          try {
            if (candidate.kind === 'domain' && candidate.domain) {
              const domainId = candidate.domain.id ?? domainFolderSlug(candidate.domain.name).replace(/-/g, '_');
              const written = applyModelingChange(projectRoot, {
                operation: 'upsert_domain',
                value: { ...candidate.domain, id: domainId },
              });
              saved.push({ id: candidate.id, path: written.patches[0]?.path, status: 'saved' });
            } else if (candidate.kind === 'skill' && candidate.skill) {
              const skill = writeSkill(projectRoot, { ...candidate.skill, scope: 'project', status: 'draft' });
              saved.push({ id: candidate.id, path: relative(projectRoot, skill.sourcePath), status: 'saved' });
            } else {
              saved.push({ id: candidate.id, status: 'blocked', blockers: ['Candidate has no writable artifact.'] });
            }
          } catch (error) {
            saved.push({ id: candidate.id, status: 'blocked', blockers: [error instanceof Error ? error.message : String(error)] });
          }
        }
        await refreshUnifiedProjectIndexes(projectRoot);
        updateContextBootstrapSession(projectRoot, id, (current) => ({ ...current, closedAt: new Date().toISOString() }));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ id, saved }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/favicon.ico') {
      res.writeHead(200, {
        'Content-Type': 'image/svg+xml',
        'Cache-Control': 'public, max-age=86400',
      });
      res.end(NOTEBOOK_FAVICON_SVG);
      return;
    }

    if (req.method === 'GET' && path === '/api/settings/env-status') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ groups: collectSettingsEnvStatus() }));
      return;
    }

    if (req.method === 'GET' && path === '/api/settings/providers') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ providers: listProviderSettings(projectRoot) }));
      return;
    }

    // Live detection for subscription-CLI providers: is the CLI installed and logged
    // in, and (for Claude) which account/plan. Lets Settings show real status instead
    // of a static hint. Spawns the CLIs, so it's a separate async call from the list.
    if (req.method === 'GET' && path === '/api/settings/providers/cli-status') {
      try {
        const [claudeCode, codex] = await Promise.all([
          ClaudeCodeCliProvider.detect(),
          CodexCliProvider.detect(),
        ]);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ status: { 'claude-code': claudeCode, codex } }));
      } catch (error) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ status: {}, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/settings/providers') {
      try {
        const body = await readJSON(req);
        if (!isProviderSettingsId(body?.id)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Unknown provider id.' }));
          return;
        }
        const providers = saveProviderSettings(projectRoot, {
          id: body.id,
          enabled: typeof body.enabled === 'boolean' ? body.enabled : undefined,
          apiKey: typeof body.apiKey === 'string' ? body.apiKey : undefined,
          baseUrl: typeof body.baseUrl === 'string' ? body.baseUrl : undefined,
          model: typeof body.model === 'string' ? body.model : undefined,
          reasoningEffort: isReasoningEffortSetting(body.reasoningEffort) ? body.reasoningEffort : undefined,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        syncDeadlineScaleToActiveProvider();
        res.end(serializeJSON({ ok: true, providers }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Subscription OAuth (Claude Pro/Max, ChatGPT Plus/Pro) ──────────────
    {
      const authMatch = path.match(/^\/api\/auth\/(claude|codex)\/(start|status|signout)$/);
      if (authMatch) {
        const oauthProvider = authMatch[1] as 'claude' | 'codex';
        const action = authMatch[2] as 'start' | 'status' | 'signout';
        const info = oauthProvider === 'claude'
          ? { models: CLAUDE_OAUTH_MODELS as readonly string[], defaultModel: CLAUDE_OAUTH_DEFAULT_MODEL }
          : { models: CODEX_OAUTH_MODELS as readonly string[], defaultModel: CODEX_OAUTH_DEFAULT_MODEL };
        const manager = getOAuthManager(projectRoot, oauthProvider);
        const statusPayload = () => {
          const connected = oauthProvider === 'claude' ? claudeOAuthConnected(projectRoot) : codexOAuthConnected(projectRoot);
          return {
            provider: oauthProvider,
            connected,
            email: connected ? manager.getEmail() : null,
            models: info.models,
            defaultModel: info.defaultModel,
            pending: manager.isPending(),
          };
        };
        try {
          if (action === 'status' && req.method === 'GET') {
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON(statusPayload()));
            return;
          }
          if (action === 'signout' && req.method === 'POST') {
            manager.signOut();
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON(statusPayload()));
            return;
          }
          if (action === 'start' && req.method === 'POST') {
            // Begin a fresh flow: build the authorize URL and start the loopback
            // callback server. The client opens the URL; the server captures the
            // redirect and persists tokens. The pending state lives on the manager,
            // so a superseded flow settles cleanly. Errors surface on the next poll.
            const url = manager.startAuthorizationFlow();
            void manager.waitForCallback().catch(() => { /* timeout/denied/superseded — status stays disconnected */ });
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ url, ...statusPayload() }));
            return;
          }
          res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Method not allowed' }));
        } catch (error) {
          res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
        }
        return;
      }
    }

    if (req.method === 'POST' && path === '/api/settings/providers/test') {
      try {
        const body = await readJSON(req);
        if (!isProviderSettingsId(body?.id)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Unknown provider id.' }));
          return;
        }
        const ok = await testProviderConfig(projectRoot, body.id, {
          apiKey: typeof body.apiKey === 'string' && body.apiKey ? body.apiKey : undefined,
          baseUrl: typeof body.baseUrl === 'string' && body.baseUrl ? body.baseUrl : undefined,
          model: typeof body.model === 'string' && body.model ? body.model : undefined,
        });
        res.writeHead(ok.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(ok));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Embeddings decide whether retrieval can match MEANING or only shared
    // words. This was environment-variable-only and mentioned nowhere in the
    // product, so in practice every project ran the lexical hashed fallback.
    if (req.method === 'GET' && path === '/api/settings/embeddings') {
      try {
        const provider = projectEmbeddingProvider(projectRoot);
        const configPath = join(projectRoot, 'dql.config.json');
        const raw = existsSync(configPath)
          ? JSON.parse(readFileSync(configPath, 'utf-8')) as Record<string, unknown>
          : {};
        const ai = raw.ai && typeof raw.ai === 'object' && !Array.isArray(raw.ai) ? raw.ai as Record<string, unknown> : {};
        const settings = ai.embeddings && typeof ai.embeddings === 'object' && !Array.isArray(ai.embeddings)
          ? ai.embeddings as Record<string, unknown>
          : {};
        const catalog = openMetadataCatalog(projectRoot);
        let indexedProvider: string | undefined;
        try { indexedProvider = catalog.state('vector_provider') ?? undefined; } finally { catalog.close(); }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          settings: {
            provider: typeof settings.provider === 'string' ? settings.provider : 'hashed',
            endpoint: typeof settings.endpoint === 'string' ? settings.endpoint : '',
            model: typeof settings.model === 'string' ? settings.model : '',
            // Never return the key itself.
            apiKeySet: typeof settings.apiKey === 'string' && settings.apiKey.trim().length > 0,
          },
          activeProviderId: provider.id,
          semantic: !isHashedEmbeddingProvider(provider),
          indexedProviderId: indexedProvider,
          // A mismatch means the catalog still holds vectors from the previous
          // embedder; the next compile/refresh re-embeds it.
          reindexRequired: Boolean(indexedProvider) && indexedProvider !== provider.id,
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'PUT' && path === '/api/settings/embeddings') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as Record<string, unknown>;
        const provider = typeof body.provider === 'string' ? body.provider.trim() : 'hashed';
        if (provider !== 'hashed' && provider !== 'ollama' && provider !== 'openai') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Embedding provider must be hashed, ollama, or openai.' }));
          return;
        }
        const str = (value: unknown): string => typeof value === 'string' ? value.trim() : '';
        if (provider === 'ollama' && !str(body.endpoint)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'An Ollama endpoint is required, e.g. http://127.0.0.1:11434' }));
          return;
        }
        const configPath = join(projectRoot, 'dql.config.json');
        const raw = existsSync(configPath)
          ? JSON.parse(readFileSync(configPath, 'utf-8')) as Record<string, unknown>
          : {};
        const ai = raw.ai && typeof raw.ai === 'object' && !Array.isArray(raw.ai) ? raw.ai as Record<string, unknown> : {};
        const existing = ai.embeddings && typeof ai.embeddings === 'object' && !Array.isArray(ai.embeddings)
          ? ai.embeddings as Record<string, unknown>
          : {};
        // Preserve a stored key when the form did not resend it.
        const apiKey = str(body.apiKey) || (typeof existing.apiKey === 'string' ? existing.apiKey : '');
        raw.ai = {
          ...ai,
          embeddings: {
            provider,
            ...(str(body.endpoint) ? { endpoint: str(body.endpoint) } : {}),
            ...(str(body.model) ? { model: str(body.model) } : {}),
            ...(provider === 'openai' && apiKey ? { apiKey } : {}),
          },
        };
        writeFileSync(configPath, `${JSON.stringify(raw, null, 2)}\n`, 'utf-8');
        projectConfig = loadProjectConfig(projectRoot);
        clearProjectEmbeddingCache(projectRoot);
        invalidateAgentProjectState(projectRoot);
        const resolved = projectEmbeddingProvider(projectRoot);
        // Keep the process-wide default in step with the edited setting.
        setProcessDefaultEmbeddingProvider(resolved);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          activeProviderId: resolved.id,
          semantic: !isHashedEmbeddingProvider(resolved),
          reindexRequired: !isHashedEmbeddingProvider(resolved),
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Re-embed now, rather than waiting for the next compile.
    if (req.method === 'POST' && path === '/api/settings/embeddings/reindex') {
      try {
        const provider = projectEmbeddingProvider(projectRoot);
        const result = await upgradeVectorIndexForProject(projectRoot, provider);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // The model catalog, plus which Ollama models are already pulled, so the UI
    // can offer names and an install button instead of a free-text field.
    if (req.method === 'GET' && path === '/api/settings/embeddings/models') {
      try {
        const endpoint = (url.searchParams.get('endpoint') ?? 'http://127.0.0.1:11434').replace(/\/$/, '');
        let installed: string[] = [];
        let reachable = false;
        try {
          const response = await fetch(`${endpoint}/api/tags`, { signal: AbortSignal.timeout(2500) });
          if (response.ok) {
            reachable = true;
            const payload = await response.json() as { models?: Array<{ name?: string }> };
            installed = (payload.models ?? []).map((m) => String(m.name ?? '').split(':')[0]).filter(Boolean);
          }
        } catch { /* Ollama not running — the UI says so rather than failing */ }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ catalog: EMBEDDING_MODEL_CATALOG, ollamaReachable: reachable, installed }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Pull an Ollama embedding model so "use this one" is a single click.
    if (req.method === 'POST' && path === '/api/settings/embeddings/install') {
      try {
        const body = (await readJSON(req).catch(() => ({}))) as { model?: unknown; endpoint?: unknown };
        const model = typeof body.model === 'string' ? body.model.trim() : '';
        const endpoint = (typeof body.endpoint === 'string' && body.endpoint.trim() ? body.endpoint.trim() : 'http://127.0.0.1:11434').replace(/\/$/, '');
        const known = EMBEDDING_MODEL_CATALOG.ollama.some((entry) => entry.model === model);
        if (!known) {
          // Only ever pull a model we list: this shells out to a local daemon,
          // so an arbitrary caller-supplied name is not something to forward.
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Unknown embedding model: ${model || '(none)'}` }));
          return;
        }
        const response = await fetch(`${endpoint}/api/pull`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name: model, stream: false }),
          signal: AbortSignal.timeout(15 * 60_000),
        });
        if (!response.ok) throw new Error(`Ollama pull failed (${response.status}). Is Ollama running at ${endpoint}?`);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, model }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Prove the configured embedder actually answers before we re-index on it.
    if (req.method === 'POST' && path === '/api/settings/embeddings/test') {
      try {
        const provider = projectEmbeddingProvider(projectRoot);
        const started = Date.now();
        const [vector] = await provider.embed(['monthly revenue by customer segment']);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: Array.isArray(vector) && vector.length > 0,
          providerId: provider.id,
          dimensions: vector?.length ?? 0,
          elapsedMs: Date.now() - started,
          semantic: !isHashedEmbeddingProvider(provider),
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/settings/mcp') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ settings: listRemoteMcpSettings(projectRoot) }));
      return;
    }

    if (req.method === 'POST' && path === '/api/settings/mcp') {
      try {
        const body = await readJSON(req);
        const settings = saveRemoteMcpSettings(projectRoot, { entries: body?.entries });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, settings }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Conversation threads (server-side session persistence) ────────────
    if (path === '/api/agent/threads' || path.startsWith('/api/agent/threads/')) {
      const store = getConversationStore();
      if (!store) {
        res.writeHead(503, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Conversation store is unavailable.' }));
        return;
      }
      try {
        if (req.method === 'GET' && path === '/api/agent/threads') {
          const limit = Number(url.searchParams.get('limit') ?? '50');
          const includeArchived = url.searchParams.get('archived') === '1';
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            threads: store.listThreads({ limit: Number.isFinite(limit) ? limit : 50, includeArchived }),
            // Browser cache identity only. It is an opaque one-way fingerprint
            // and intentionally does not become conversation/trace evidence.
            projectIdentity: conversationProjectIdentity,
          }));
          return;
        }
        if (req.method === 'POST' && path === '/api/agent/threads') {
          const body = await readJSON(req).catch(() => null);
          const record = agentRunRecord(body) ?? {};
          const thread = store.createThread({
            surface: agentRunString(record.surface),
            title: agentRunString(record.title),
            notebookPath: agentRunString(record.notebookPath),
          });
          res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ thread }));
          return;
        }
        // Cross-thread turn search ("search conversations") — must precede :id.
        if (req.method === 'GET' && path === '/api/agent/threads/search') {
          const query = url.searchParams.get('q') ?? '';
          const limit = Number(url.searchParams.get('limit') ?? '10');
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            turns: query.trim()
              ? store.searchTurns({ query, limit: Number.isFinite(limit) ? limit : 10 })
              : [],
          }));
          return;
        }
        const threadMatch = path.match(/^\/api\/agent\/threads\/([^/]+)(?:\/(archive|promote))?$/);
        if (threadMatch) {
          const threadId = decodeURIComponent(threadMatch[1]);
          const action = threadMatch[2];
          const thread = store.getThread(threadId);
          if (!thread) {
            res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ error: 'Unknown thread id.' }));
            return;
          }
          if (req.method === 'POST' && action === 'archive') {
            store.archiveThread(threadId);
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ ok: true }));
            return;
          }
          // Rename / pin. Both are housekeeping on an existing conversation, so
          // neither moves `updated_at` — see the store methods.
          if (req.method === 'PATCH' && !action) {
            const body = await readJSON(req).catch(() => null);
            const record = agentRunRecord(body) ?? {};
            const title = agentRunString(record.title);
            const favorite = typeof record.favorite === 'boolean' ? record.favorite : undefined;
            if (title === undefined && favorite === undefined) {
              res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
              res.end(serializeJSON({ error: 'Provide a title or a favorite flag.' }));
              return;
            }
            if (title !== undefined) store.renameThread(threadId, title);
            if (favorite !== undefined) store.setThreadFavorite(threadId, favorite);
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ thread: store.getThread(threadId) }));
            return;
          }
          if (req.method === 'DELETE' && !action) {
            store.deleteThread(threadId);
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ ok: true }));
            return;
          }
          // Explicit promotion — the ONLY path from conversation into durable
          // memory ("remember this"). Deliberate user act, tagged for audit.
          if (req.method === 'POST' && action === 'promote') {
            const body = await readJSON(req).catch(() => null);
            const record = agentRunRecord(body) ?? {};
            const turnId = agentRunString(record.turnId);
            const turn = turnId
              ? store.recentTurns(threadId, 200).find((candidate) => candidate.id === turnId)
              : undefined;
            if (!turn) {
              res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
              res.end(serializeJSON({ error: 'turnId is required and must belong to this thread.' }));
              return;
            }
            const scopeRaw = agentRunString(record.scope);
            const scope = scopeRaw === 'notebook' || scopeRaw === 'project' || scopeRaw === 'user' ? scopeRaw : 'project';
            const memory = new MemoryStore(defaultMemoryPath(projectRoot));
            try {
              const saved = memory.upsert({
                scope,
                title: agentRunString(record.title) ?? turn.question.slice(0, 120),
                content: `Q: ${turn.question}\nA: ${turn.answerSummary ?? turn.answerText ?? '(no answer summary)'}`,
                tags: ['conversation', threadId],
                source: 'conversation',
                confidence: 0.6,
                importance: 0.5,
                enabled: true,
              });
              res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
              res.end(serializeJSON({ ok: true, memory: saved }));
            } finally {
              memory.close();
            }
            return;
          }
          if (req.method === 'GET' && !action) {
            const limit = Number(url.searchParams.get('limit') ?? '50');
            const turns = store.recentTurns(threadId, Number.isFinite(limit) ? limit : 50);
            const runs = turns.flatMap((turn) => {
              if (!turn.agentRunId) return [];
              const run = agentRunStore.get(turn.agentRunId);
              // Thread history is a PRESENTATION payload. A stored run averages
              // ~700 KB and can exceed 2 MB, almost none of it renderable, so
              // fetching 50 of them meant tens of megabytes to read, parse,
              // re-serialize and ship before the sidebar could draw — the
              // reported ~10s load. `GET /api/agent-runs/:id` serves the full
              // record when the inspector actually needs it.
              return run ? [slimAgentRunForTransport(run)] : [];
            });
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({
              thread,
              turns,
              runs,
            }));
            return;
          }
        }
        res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Method not allowed' }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/agent/memory') {
      const memory = new MemoryStore(defaultMemoryPath(projectRoot));
      try {
        const scope = url.searchParams.get('scope') ?? undefined;
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ memories: memory.list(isMemoryScope(scope) ? scope : undefined) }));
      } finally {
        memory.close();
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/agent/memory') {
      const body = await readJSON(req).catch(() => null);
      if (!body || !isMemoryScope(body.scope) || typeof body.title !== 'string' || typeof body.content !== 'string') {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'scope, title, and content are required.' }));
        return;
      }
      const memory = new MemoryStore(defaultMemoryPath(projectRoot));
      try {
        const saved = memory.upsert({
          id: typeof body.id === 'string' ? body.id : undefined,
          scope: body.scope,
          scopeId: typeof body.scopeId === 'string' ? body.scopeId : undefined,
          title: body.title,
          content: body.content,
          tags: Array.isArray(body.tags) ? body.tags.map(String) : undefined,
          source: typeof body.source === 'string' ? body.source : 'settings-ui',
          confidence: typeof body.confidence === 'number' ? body.confidence : undefined,
          importance: typeof body.importance === 'number' ? body.importance : undefined,
          validFrom: typeof body.validFrom === 'string' ? body.validFrom : undefined,
          validTo: typeof body.validTo === 'string' ? body.validTo : undefined,
          supersedes: typeof body.supersedes === 'string' ? body.supersedes : undefined,
          enabled: typeof body.enabled === 'boolean' ? body.enabled : undefined,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, memory: saved }));
      } finally {
        memory.close();
      }
      return;
    }

    if (req.method === 'DELETE' && path === '/api/agent/memory') {
      const id = url.searchParams.get('id');
      if (!id) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'id is required.' }));
        return;
      }
      const memory = new MemoryStore(defaultMemoryPath(projectRoot));
      try {
        memory.delete(id);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true }));
      } finally {
        memory.close();
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/agent/memory/default-files') {
      const files = ensureDefaultMemoryFiles(projectRoot).map((p) => relative(projectRoot, p));
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ ok: true, files }));
      return;
    }

    // CTX-005 / API-003 / E2E-001 local-first Hint Graph review queue.
    // Corrections are captured as
    // candidates; only the shared governed lifecycle can evaluate and approve
    // them for future advisory retrieval.
    if (req.method === 'GET' && path === '/api/agent/hints') {
      try {
        const status = url.searchParams.get('status');
        const all = listHintsFromGit(projectRoot);
        const selected = (status ? all.filter((hint) => hint.status === status) : all)
          .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
          .slice(0, 200);
        const hintIndex = new HintStore(defaultHintIndexPath(projectRoot));
        const graphEdgesByHint = new Map(
          selected.map((hint) => [hint.id, hintIndex.edgesForHint(hint.id)] as const),
        );
        hintIndex.close();
        const snapshotId = projectSnapshot().snapshotId;
        const approved = all.filter((hint) => hint.status === 'approved');
        const inspectionById = new Map(await Promise.all(
          all
            .filter((hint) => hint.status === 'candidate' || hint.status === 'approved')
            .map(async (hint) => [
              hint.id,
              await inspectGovernedHint(projectRoot, { hintId: hint.id, snapshotId }),
            ] as const),
        ));
        // Match retrieval truth: stale/invalid approved hints cannot create a
        // conflict or supersede another otherwise-current hint.
        const eligibleApproved = approved.filter(
          (hint) => inspectionById.get(hint.id)?.state === 'current',
        );
        const conflictIds = new Map<string, string[]>();
        for (let left = 0; left < eligibleApproved.length; left += 1) {
          for (let right = left + 1; right < eligibleApproved.length; right += 1) {
            if (!hintsConflict(eligibleApproved[left], eligibleApproved[right])) continue;
            conflictIds.set(eligibleApproved[left].id, [...(conflictIds.get(eligibleApproved[left].id) ?? []), eligibleApproved[right].id]);
            conflictIds.set(eligibleApproved[right].id, [...(conflictIds.get(eligibleApproved[right].id) ?? []), eligibleApproved[left].id]);
          }
        }
        const supersededIds = new Map(
          eligibleApproved.filter((hint) => hint.supersedes).map((hint) => [hint.supersedes!, hint.id]),
        );
        const hints = await Promise.all(selected.map(async (hint) => {
          const inspection = inspectionById.get(hint.id) ?? null;
          const exclusions = [
            ...(inspection && inspection.state !== 'current'
              ? [{ reason: inspection.state, detail: inspection.checks.filter((check) => !check.passed).map((check) => check.evidence).join(' ') }]
              : []),
            ...(supersededIds.has(hint.id)
              ? [{ reason: 'superseded', detail: `Superseded by ${supersededIds.get(hint.id)}.`, relatedHintId: supersededIds.get(hint.id) }]
              : []),
            ...((conflictIds.get(hint.id) ?? []).map((relatedHintId) => ({
              reason: 'conflict',
              detail: `Conflicts with approved hint ${relatedHintId}.`,
              relatedHintId,
            }))),
          ];
          return {
            ...hint,
            graphEdges: graphEdgesByHint.get(hint.id) ?? [],
            trace: hint.traceId ? getCorrectionTraceFromGit(projectRoot, hint.traceId) : undefined,
            evaluation: hint.evaluationId ? getHintEvaluationFromGit(projectRoot, hint.evaluationId) : undefined,
            inspection: inspection ? {
              currentSnapshotId: inspection.currentSnapshotId,
              snapshotCurrent: inspection.snapshotCurrent,
              dependenciesCurrent: inspection.dependenciesCurrent,
              driftedDependencies: inspection.driftedDependencies,
              checks: inspection.checks,
              state: inspection.state,
            } : undefined,
            exclusions,
          };
        }));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          hints,
          counts: {
            candidate: all.filter((hint) => hint.status === 'candidate').length,
            approved: all.filter((hint) => hint.status === 'approved').length,
            rejected: all.filter((hint) => hint.status === 'rejected').length,
            retired: all.filter((hint) => hint.status === 'retired').length,
          },
        }));
      } catch (error) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ hints: [], counts: { candidate: 0, approved: 0, rejected: 0, retired: 0 }, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const hintEditMatch = /^\/api\/agent\/hints\/([^/]+)$/.exec(path);
    if (req.method === 'PATCH' && hintEditMatch) {
      try {
        const hintId = decodeURIComponent(hintEditMatch[1]);
        const body = await readJSON(req).catch(() => null) as Record<string, unknown> | null;
        if (!body) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Candidate fields are required.' }));
          return;
        }
        const rawScope = body.scope && typeof body.scope === 'object' ? body.scope as Record<string, unknown> : undefined;
        const scopeValue = (key: string): string | undefined => {
          const value = rawScope?.[key];
          return typeof value === 'string' && value.trim() ? value.trim() : undefined;
        };
        const hint = await editGovernedHintCandidate(projectRoot, {
          hintId,
          title: typeof body.title === 'string' ? body.title : undefined,
          guidance: typeof body.guidance === 'string' ? body.guidance : undefined,
          lesson: parseHintLessonInput(body.lesson),
          correctedSql: typeof body.correctedSql === 'string' ? body.correctedSql : undefined,
          scope: rawScope ? {
            metric: scopeValue('metric'),
            dbtModel: scopeValue('dbtModel'),
            domain: scopeValue('domain'),
            dialect: scopeValue('dialect'),
            term: scopeValue('term'),
            block: scopeValue('block'),
          } : undefined,
          snapshotId: projectSnapshot().snapshotId,
        });
        if (!hint) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Hint not found.' }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, hint }));
      } catch (error) {
        res.writeHead(error instanceof Error && error.name === 'HintLifecycleError' ? 409 : 500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const hintLifecycleMatch = /^\/api\/agent\/hints\/([^/]+)\/lifecycle$/.exec(path);
    if (req.method === 'POST' && hintLifecycleMatch) {
      try {
        const hintId = decodeURIComponent(hintLifecycleMatch[1]);
        const body = await readJSON(req).catch(() => null) as Record<string, unknown> | null;
        const action = body?.action;
        const reviewer = typeof body?.reviewer === 'string' && body.reviewer.trim()
          ? body.reviewer.trim()
          : (resolveLocalOwner(projectRoot) ?? 'local');
        const note = typeof body?.note === 'string' && body.note.trim() ? body.note.trim() : undefined;
        let result;
        if (action === 'retire') {
          result = retireHint(projectRoot, { hintId, reviewer, note });
        } else if (action === 'reopen') {
          result = await reopenGovernedHint(projectRoot, {
            hintId,
            reviewer,
            note,
            snapshotId: projectSnapshot().snapshotId,
          });
        } else if (action === 'supersede') {
          const targetHintId = typeof body?.targetHintId === 'string' ? body.targetHintId.trim() : '';
          if (!targetHintId) {
            res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ ok: false, error: 'targetHintId is required for supersede.' }));
            return;
          }
          result = supersedeHint(projectRoot, { hintId, targetHintId, reviewer, note });
        } else {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: "action must be 'retire', 'reopen', or 'supersede'." }));
          return;
        }
        if (!result) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Hint not found.' }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, hint: result.hint, review: result.review }));
      } catch (error) {
        res.writeHead(error instanceof Error && error.name === 'HintLifecycleError' ? 409 : 500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const hintReviewMatch = /^\/api\/agent\/hints\/([^/]+)\/review$/.exec(path);
    if (req.method === 'POST' && hintReviewMatch) {
      try {
        const hintId = decodeURIComponent(hintReviewMatch[1]);
        const body = await readJSON(req).catch(() => null) as Record<string, unknown> | null;
        const decision = body?.decision === 'approved' || body?.decision === 'rejected' ? body.decision : null;
        if (!decision) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: "decision must be 'approved' or 'rejected'." }));
          return;
        }
        const reviewer = typeof body?.reviewer === 'string' && body.reviewer.trim()
          ? body.reviewer.trim()
          : (resolveLocalOwner(projectRoot) ?? 'local');
        const note = typeof body?.note === 'string' && body.note.trim() ? body.note.trim() : undefined;
        const snapshotId = projectSnapshot().snapshotId;
        const reviewed = await reviewGovernedHint(projectRoot, {
          hintId,
          decision,
          reviewer,
          snapshotId,
          ...(note ? { note } : {}),
          ...(decision === 'approved' ? {
            executeSql: async (sql, execution) => executeGeneratedSqlForAgent(sql, {
              ...generatedSqlArtifactContract(execution.question, sql),
              limit: execution.rowLimit,
            }),
          } : {}),
        });
        if (!reviewed) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Hint not found.' }));
          return;
        }
        const hint = reviewed.hint;
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, hint, evaluation: reviewed.evaluation }));
      } catch (error) {
        res.writeHead(error instanceof Error && error.name === 'HintLifecycleError' ? 409 : 500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/agent/learnings/correction') {
      const body = await readJSON(req).catch(() => null);
      const question = body && typeof body.question === 'string' ? body.question.trim() : '';
      const correctedSql = body && typeof body.correctedSql === 'string' ? body.correctedSql.trim() : '';
      if (!body || !question || !correctedSql) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'question and correctedSql are required.' }));
        return;
      }
      const rawScope = body.scope && typeof body.scope === 'object' ? body.scope as Record<string, unknown> : {};
      const scopeStr = (key: string): string | undefined => (typeof rawScope[key] === 'string' && (rawScope[key] as string).trim() ? (rawScope[key] as string).trim() : undefined);
      const scope = {
        metric: scopeStr('metric'),
        dbtModel: scopeStr('dbtModel'),
        domain: scopeStr('domain'),
        dialect: scopeStr('dialect'),
        term: scopeStr('term'),
        block: scopeStr('block'),
      };
      const wrongSql = typeof body.wrongSql === 'string' ? body.wrongSql.trim() : '';
      const rationale = typeof body.rationale === 'string' && body.rationale.trim() ? body.rationale.trim() : undefined;
      const author = typeof body.author === 'string' ? body.author : (resolveLocalOwner(projectRoot) ?? undefined);
      try {
        // dbt-first manifest v3 requires reviewable provenance before a correction
        // may be recorded at all. The client cannot know most of it, so derive it
        // here: without this the endpoint rejects every correction on exactly the
        // governed projects the learning loop is meant to serve.
        const correctionEvidence = Array.isArray(body.evidence)
          ? body.evidence.map(String).filter(Boolean)
          : [
              `question: ${question}`,
              ...(wrongSql ? [`previous SQL: ${wrongSql.replace(/\s+/g, ' ').slice(0, 400)}`] : []),
              `corrected SQL: ${correctedSql.replace(/\s+/g, ' ').slice(0, 400)}`,
              ...(rationale ? [`rationale: ${rationale}`] : []),
            ];
        const correctionSnapshotId = typeof body.snapshotId === 'string' && body.snapshotId.trim()
          ? body.snapshotId.trim()
          : projectSnapshot().snapshotId;
        const correctionFailedRoute = typeof body.failedRoute === 'string' && body.failedRoute.trim()
          ? body.failedRoute.trim()
          : 'generated_answer';
        // Stable name linked to the Git evaluation artifacts created during
        // review. Capture itself does not silently write a regression source.
        const correctionEvaluation = typeof body.requiredEvaluation === 'string' && body.requiredEvaluation.trim()
          ? body.requiredEvaluation.trim()
          : `correction: ${question.slice(0, 60)}`;
        const { trace, hint } = await recordGovernedCorrection(projectRoot, {
          question,
          scope,
          wrongAnswer: wrongSql || '(no prior SQL captured)',
          correction: correctedSql,
          correctedSql,
          rationale,
          author,
          failedRoute: correctionFailedRoute,
          evidence: correctionEvidence,
          snapshotId: correctionSnapshotId,
          requiredEvaluation: correctionEvaluation,
          hintTitle: typeof body.title === 'string' && body.title.trim() ? body.title.trim() : undefined,
          hintGuidance: typeof body.guidance === 'string' && body.guidance.trim() ? body.guidance.trim() : undefined,
          lesson: parseHintLessonInput(body.lesson),
          tags: Array.isArray(body.tags) ? body.tags.map(String) : undefined,
        });
        // `approve` is intentionally ignored: capture never promotes a hint.
        // Review must use /api/agent/hints/:id/review so the same evidence gates
        // run for notebook, CLI runtime, and MCP callers.
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          trace,
          hint,
          approvalRequested: body.approve === true,
          note: body.approve === true
            ? 'Captured as a candidate. Automatic approval is not permitted; use the review queue.'
            : undefined,
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const appStoryRun = path.match(/^\/api\/apps\/([^/]+)\/dashboards\/([^/]+)\/story$/);
    if (req.method === 'POST' && appStoryRun) {
      const body = await readJSON(req).catch(() => ({}));
      const runId = typeof body.runId === 'string' ? body.runId : '';
      const evidence = dashboardRunEvidence.get(runId);
      const appId = decodeURIComponent(appStoryRun[1]);
      const dashboardId = decodeURIComponent(appStoryRun[2]);
      if (!evidence || evidence.expiresAt < Date.now() || evidence.appId !== appId || evidence.dashboardId !== dashboardId) {
        dashboardRunEvidence.delete(runId);
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Dashboard run evidence expired or does not match this App. Run the dashboard again.' }));
        return;
      }
      // The endpoint accepts runId only. Optional provider wording can be added
      // here later; the claim-checked deterministic brief is always available.
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        runId,
        snapshotId: evidence.snapshotId,
        filterFingerprint: evidence.filterFingerprint,
        resultFingerprint: evidence.resultFingerprint,
        personaFingerprint: evidence.personaFingerprint,
        facts: evidence.facts,
        story: evidence.story,
      }));
      return;
    }

    const appDashRun = path.match(/^\/api\/(apps|app-builds)\/([^/]+)\/dashboards\/([^/]+)\/run$/);
    if (req.method === 'POST' && appDashRun) {
      try {
        const runSurface = appDashRun[1] as 'apps' | 'app-builds';
        const appId = decodeURIComponent(appDashRun[2]);
        const dashboardId = decodeURIComponent(appDashRun[3]);
        const body = await readJSON(req).catch(() => ({}));
        const loaded = runSurface === 'app-builds'
          ? loadAppBuildDraftDashboard(projectRoot, appId, dashboardId)
          : loadAppDashboard(projectRoot, appId, dashboardId);
        if (!loaded) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Dashboard "${dashboardId}" not found in ${runSurface === 'app-builds' ? 'local App draft' : 'App'} "${appId}"` }));
          return;
        }
        const activeApp = activePersonaAppId();
        if (runSurface === 'apps' && activeApp && activeApp !== appId) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `The active persona belongs to App "${activeApp}", not "${appId}".` }));
          return;
        }

        const manifest = buildManifest({ projectRoot });
        const variables = body.variables && typeof body.variables === 'object'
          ? body.variables as Record<string, unknown>
          : {};
        const dashboardVariables = dashboardRuntimeVariables(loaded.dashboard, variables);
        const requestedTileId = typeof body.tileId === 'string' && body.tileId.trim()
          ? body.tileId.trim()
          : undefined;
        const tiles: Array<{ tileId: string; status: string; [key: string]: any }> = [];
        const localApps = { current: null as LocalAppStorage | null };
        const itemsToRun = loaded.dashboard.layout.items.filter((item) => !requestedTileId || item.i === requestedTileId);
        const tileOrder = new Map(itemsToRun.map((item, index) => [item.i, index]));
        let nextTileIndex = 0;
        // App preview is a multi-source execution, so isolate each tile's
        // failure and run a small fixed pool. Four avoids serial 4k-catalog
        // behavior without flooding the configured warehouse.
        const runTileWorker = async () => {
          while (nextTileIndex < itemsToRun.length) {
            const item = itemsToRun[nextTileIndex++];
            if (!item) continue;
          if (item.text) {
            tiles.push({
              tileId: item.i,
              status: 'ok',
              tileType: 'text',
              title: item.title,
              viz: item.viz,
              text: item.text,
            });
            continue;
          }
          if (item.aiPin) {
            try {
              localApps.current ??= new LocalAppStorage(defaultLocalAppsDbPath(projectRoot));
            } catch (err) {
              tiles.push({
                tileId: item.i,
                status: 'error',
                tileType: 'aiPin',
                error: err instanceof Error ? err.message : String(err),
              });
              continue;
            }
            let pin = localApps.current.getAiPin(item.aiPin.id);
            if (!pin) {
              tiles.push({
                tileId: item.i,
                status: 'unresolved',
                tileType: 'aiPin',
                error: `AI pin "${item.aiPin.id}" could not be found`,
              });
              continue;
            }
            const pinPlan = pin.analysisPlan && typeof pin.analysisPlan === 'object' && !Array.isArray(pin.analysisPlan)
              ? pin.analysisPlan as Record<string, unknown>
              : undefined;
            const pinArtifact = normalizeDqlArtifactReference(pinPlan?.dqlArtifact);
            let renderedPinResult = pin.result;
            let renderedPinChartConfig = pin.chartConfig as Record<string, unknown> | undefined;
            if (pinArtifact) {
              try {
                const boundParameters = dashboardTileParameterValues({
                  item,
                  dashboardValues: dashboardVariables,
                  requestValues: variables,
                });
                const executed = await executeDqlArtifactSourceForAgent(
                  pinArtifact.source,
                  { name: pinArtifact.name ?? pin.title, path: pinArtifact.sourcePath },
                  { question: pin.question, parameters: { ...(pinArtifact.parameterValues ?? {}), ...boundParameters } },
                );
                renderedPinResult = executed;
                renderedPinChartConfig = executed.chartConfig && typeof executed.chartConfig === 'object'
                  ? executed.chartConfig as Record<string, unknown>
                  : renderedPinChartConfig;
              } catch (err) {
                tiles.push({
                  tileId: item.i,
                  status: 'error',
                  tileType: 'aiPin',
                  title: item.title ?? pin.title,
                  error: err instanceof Error ? err.message : String(err),
                  trustState: pinArtifact.trustState ?? 'review_required',
                });
                continue;
              }
            } else if (pin.refreshCadence === 'daily' && pin.sql && isAiPinRefreshDue(pin.lastRefreshedAt)) {
              try {
                const refreshed = await executeLocalSqlForStoredResult(pin.sql);
                pin = localApps.current.updateAiPinResult(pin.id, refreshed) ?? pin;
              } catch (err) {
                pin = localApps.current.updateAiPinResult(
                  pin.id,
                  pin.result,
                  err instanceof Error ? err.message : String(err),
                ) ?? pin;
              }
            }
            tiles.push({
              tileId: item.i,
              status: 'ok',
              tileType: 'aiPin',
              title: item.title ?? pin.title,
              viz: item.viz,
              chartConfig: mergeDashboardChartConfig(renderedPinChartConfig, item),
              result: renderedPinResult,
              aiPin: pin,
              citation: {
                kind: 'ai_pin',
                name: pin.title,
              },
              artifact: {
                version: 1,
                sourceKind: 'ai_pin',
                name: pinArtifact?.name ?? pin.title,
                ...(pinArtifact?.sourcePath ? { sourcePath: pinArtifact.sourcePath } : {}),
                ...(pinArtifact?.source ? { dql: pinArtifact.source.slice(0, 40_000) } : {}),
                ...(pinArtifact?.compiledSql || pin.sql ? { sql: (pinArtifact?.compiledSql ?? pin.sql)!.slice(0, 40_000) } : {}),
                trustState: pinArtifact?.trustState === 'certified' || pin.certification === 'certified'
                  ? 'certified'
                  : 'review_required',
                explanation: [
                  'This result comes from a saved App insight.',
                  pinArtifact ? 'The DQL artifact was executed again with the current App parameters.' : 'The saved bounded result is displayed with its original trust state.',
                ],
                executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
              },
            });
            continue;
          }
          if (item.draftAnalysis) {
            let draftSource: string | undefined;
            let draftAppRelativePath: string | undefined;
            let draftParameters: Record<string, unknown> = {};
            let draftTargetConnection: ConnectionConfig | undefined;
            let draftRepairPlan: ReturnType<typeof buildExecutionPlan> | undefined;
            try {
              const localDraftPath = loaded.draftArtifactsDir
                ? join(loaded.draftArtifactsDir, item.draftAnalysis.ref)
                : undefined;
              const draftRoot = localDraftPath && existsSync(localDraftPath)
                ? loaded.draftArtifactsDir!
                : loaded.appDir;
              const draftPath = join(draftRoot, item.draftAnalysis.ref);
              draftAppRelativePath = relative(draftRoot, draftPath);
              if (draftAppRelativePath.startsWith('..') || draftAppRelativePath.startsWith('/')) {
                throw new Error('App-scoped analysis reference escapes the App directory.');
              }
              draftSource = readFileSync(draftPath, 'utf-8');
              const fingerprint = `sha256:${createHash('sha256').update(draftSource).digest('hex')}`;
              if (fingerprint !== item.draftAnalysis.artifactFingerprint) {
                throw new Error('App-scoped analysis changed after approval. Review the draft again.');
              }
              draftParameters = dashboardTileParameterValues({
                item,
                dashboardValues: dashboardVariables,
                requestValues: variables,
              });
              draftTargetConnection = isConnectionConfig(body.connection)
                ? body.connection
                : connection ?? undefined;
              draftRepairPlan = buildExecutionPlan(
                { id: item.i, type: 'dql', source: draftSource, title: item.title ?? item.i },
                {
                  semanticLayer,
                  driver: draftTargetConnection?.driver ?? 'duckdb',
                  parameters: draftParameters,
                },
              );
              let result: AgentResultPayload;
              let repair: AppExecutionRepairTrace | undefined;
              let repairedSql: string | undefined;
              let repairedDql: string | undefined;
              try {
                result = await executeDqlArtifactSourceForAgent(
                  draftSource,
                  { name: item.title ?? item.i, path: draftAppRelativePath },
                  { question: item.title, parameters: draftParameters },
                );
              } catch (executionError) {
                const repaired = await repairFailedAppTileExecution({
                  source: 'draft_analysis',
                  question: item.title ?? item.i,
                  sourceSql: draftRepairPlan?.sql,
                  sourceDql: draftSource,
                  artifactName: item.title ?? item.i,
                  error: executionError,
                  targetConnection: draftTargetConnection,
                  targetConnectionName: projectConfig.defaultConnectionName,
                  sqlParams: draftRepairPlan?.sqlParams,
                  variables: { ...(draftRepairPlan?.variables ?? {}), ...draftParameters },
                });
                if (!repaired.ok) {
                  tiles.push({
                    tileId: item.i,
                    status: 'error',
                    tileType: 'draftAnalysis',
                    title: item.title ?? item.i,
                    error: executionError instanceof Error ? executionError.message : String(executionError),
                    trustState: 'review_required',
                    repair: repaired.repair,
                    artifact: {
                      version: 1,
                      sourceKind: 'draft_analysis',
                      name: item.title ?? item.i,
                      sourcePath: draftAppRelativePath,
                      dql: draftSource.slice(0, 40_000),
                      ...(draftRepairPlan?.sql ? { sql: draftRepairPlan.sql.slice(0, 40_000) } : {}),
                      trustState: 'review_required',
                      explanation: ['This App-scoped analysis remains review-required.', 'Automatic repair could not produce a safe executable result.'],
                      executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                    },
                  });
                  continue;
                }
                result = repaired.result;
                repair = repaired.repair;
                repairedSql = repaired.repairedSql;
                repairedDql = repaired.repairedDql;
              }
              tiles.push({
                tileId: item.i,
                status: 'ok',
                tileType: 'draftAnalysis',
                title: item.title ?? item.i,
                viz: item.viz,
                chartConfig: mergeDashboardChartConfig(result.chartConfig as object | undefined, item),
                result,
                trustState: 'review_required',
                citation: { kind: repair ? 'app_draft_analysis_repaired' : 'app_draft_analysis', name: item.title ?? item.i, path: draftAppRelativePath },
                ...(repair ? { repair } : {}),
                artifact: {
                  version: 1,
                  sourceKind: 'draft_analysis',
                  name: item.title ?? item.i,
                  sourcePath: draftAppRelativePath,
                  dql: (repairedDql ?? draftSource).slice(0, 40_000),
                  ...(repairedSql ?? draftRepairPlan?.sql ? { sql: (repairedSql ?? draftRepairPlan!.sql).slice(0, 40_000) } : {}),
                  trustState: 'review_required',
                  explanation: [
                    'This is private App analysis and remains review-required.',
                    repair ? 'A bounded repair ran on the original data target without changing the saved source file.' : 'The saved App-scoped DQL was executed with the current filters.',
                  ],
                  executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                },
              });
            } catch (err) {
              const repaired = await repairFailedAppTileExecution({
                source: 'draft_analysis',
                question: item.title ?? item.i,
                sourceSql: draftRepairPlan?.sql,
                sourceDql: draftSource,
                artifactName: item.title ?? item.i,
                error: err,
                targetConnection: draftTargetConnection,
                targetConnectionName: projectConfig.defaultConnectionName,
                sqlParams: draftRepairPlan?.sqlParams,
                variables: { ...(draftRepairPlan?.variables ?? {}), ...draftParameters },
              });
              if (repaired.ok && draftSource) {
                tiles.push({
                  tileId: item.i,
                  status: 'ok',
                  tileType: 'draftAnalysis',
                  title: item.title ?? item.i,
                  viz: item.viz,
                  chartConfig: mergeDashboardChartConfig(repaired.result.chartConfig as object | undefined, item),
                  result: repaired.result,
                  trustState: 'review_required',
                  citation: { kind: 'app_draft_analysis_repaired', name: item.title ?? item.i, path: draftAppRelativePath },
                  repair: repaired.repair,
                  artifact: {
                    version: 1,
                    sourceKind: 'draft_analysis',
                    name: item.title ?? item.i,
                    ...(draftAppRelativePath ? { sourcePath: draftAppRelativePath } : {}),
                    dql: (repaired.repairedDql ?? draftSource).slice(0, 40_000),
                    sql: repaired.repairedSql.slice(0, 40_000),
                    trustState: 'review_required',
                    explanation: ['A bounded DQL repair executed on the original data target. The saved App analysis was not changed.'],
                    executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                  },
                });
                continue;
              }
              tiles.push({
                tileId: item.i,
                status: 'error',
                tileType: 'draftAnalysis',
                title: item.title ?? item.i,
                error: err instanceof Error ? err.message : String(err),
                trustState: 'review_required',
                repair: repaired.repair,
                ...(draftSource ? {
                  artifact: {
                    version: 1,
                    sourceKind: 'draft_analysis',
                    name: item.title ?? item.i,
                    ...(draftAppRelativePath ? { sourcePath: draftAppRelativePath } : {}),
                    dql: draftSource.slice(0, 40_000),
                    ...(draftRepairPlan?.sql ? { sql: draftRepairPlan.sql.slice(0, 40_000) } : {}),
                    trustState: 'review_required',
                    explanation: ['Automatic repair could not produce a safe executable result. The saved App analysis was not changed.'],
                    executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                  },
                } : {}),
              });
            }
            continue;
          }
          if (item.semantic) {
            try {
              if (!semanticLayer) throw new Error('Semantic layer is not available for this governed query.');
              const knownMetrics = new Set(semanticLayer.listMetrics().map((metric) => metric.name));
              const missingMetrics = item.semantic.metrics.filter((metric) => !knownMetrics.has(metric));
              if (missingMetrics.length) throw new Error(`Semantic definition changed; missing metric(s): ${missingMetrics.join(', ')}`);
              const knownModels = new Set(semanticLayer.listSemanticModels().map((model) => model.name));
              const missingModels = item.semantic.semanticModelRefs.filter((model) => !knownModels.has(model));
              if (missingModels.length) throw new Error(`Semantic definition changed; missing model(s): ${missingModels.join(', ')}`);
              const targetConnection = requireActiveConnection(isConnectionConfig(body.connection) ? body.connection : connection);
              const tableMapping = await resolveSemanticTableMapping(executor, targetConnection, semanticLayer, projectRoot);
              const activeFilters = dashboardSemanticFiltersForTile(loaded.dashboard, item, dashboardVariables);
              const staticFilters = (item.semantic.filters ?? []).map((filter) => ({
                dimension: filter.field,
                operator: filter.operator,
                values: Array.isArray(filter.value) ? filter.value.map(String) : [String(filter.value)],
              }));
              const composed = await composeRuntimeSemanticQuery({
                metrics: item.semantic.metrics,
                dimensions: item.semantic.dimensions ?? [],
                filters: [...staticFilters, ...activeFilters],
                ...(item.semantic.timeDimension ? { timeDimension: { name: item.semantic.timeDimension, granularity: 'month' } } : {}),
                orderBy: item.semantic.orderBy?.map((order) => ({ name: order.field, direction: order.direction })),
                limit: item.semantic.limit,
                engine: item.semantic.provider,
              }, semanticLayer, {
                projectRoot,
                projectConfig,
                detectedProvider: semanticDetectedProvider,
                driver: targetConnection.driver,
                tableMapping,
              });
              if (!composed) throw new Error('The governed semantic query could not be composed.');
              let normalizedResult: ReturnType<typeof normalizeQueryResult>;
              let repair: AppExecutionRepairTrace | undefined;
              let executedSql = composed.sql;
              let executionFingerprints: Pick<ExecutionServiceResult, 'compiledSqlFingerprint' | 'resultFingerprint'> | undefined;
              try {
                const execution = await analyticalExecutionService.execute({
                  sql: composed.sql,
                  subject: 'App tile semantic query',
                  connection: targetConnection,
                });
                normalizedResult = execution.result;
                executedSql = execution.preparation.executedSql;
                executionFingerprints = {
                  compiledSqlFingerprint: execution.compiledSqlFingerprint,
                  resultFingerprint: execution.resultFingerprint,
                };
              } catch (executionError) {
                const repaired = await repairFailedAppTileExecution({
                  source: 'semantic_query',
                  question: item.title ?? item.semantic.id,
                  sourceSql: composed.sql,
                  error: executionError,
                  targetConnection,
                });
                if (!repaired.ok) {
                  tiles.push({
                    tileId: item.i,
                    status: 'error',
                    tileType: 'semantic',
                    title: item.title ?? item.semantic.id,
                    error: executionError instanceof Error ? executionError.message : String(executionError),
                    trustState: 'review_required',
                    repair: repaired.repair,
                    artifact: {
                      version: 1,
                      sourceKind: 'semantic_query',
                      name: item.title ?? item.semantic.id,
                      sql: composed.sql.slice(0, 40_000),
                      trustState: 'review_required',
                      explanation: ['Automatic repair could not execute the governed semantic query safely.'],
                      executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                    },
                  });
                  continue;
                }
                normalizedResult = normalizeQueryResult(repaired.result);
                repair = repaired.repair;
                executedSql = repaired.repairedSql;
              }
              tiles.push({
                tileId: item.i,
                status: 'ok',
                tileType: 'semantic',
                title: item.title ?? item.semantic.id,
                viz: item.viz,
                result: normalizedResult,
                ...(executionFingerprints ?? {}),
                trustState: 'review_required',
                citation: { kind: repair ? 'semantic_query_repaired' : 'semantic_query', name: item.semantic.id },
                ...(repair ? { repair } : {}),
                artifact: {
                  version: 1,
                  sourceKind: 'semantic_query',
                  name: item.title ?? item.semantic.id,
                  sql: executedSql.slice(0, 40_000),
                  trustState: 'review_required',
                  explanation: [
                    `Metrics: ${item.semantic.metrics.join(', ') || 'none'}.`,
                    `Dimensions: ${item.semantic.dimensions?.join(', ') || 'none'}.`,
                    repair ? 'The composed SQL needed bounded repair and therefore remains review-required.' : 'The governed semantic intent was composed for the active warehouse and remains review-required until approval.',
                  ],
                  executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                },
              });
            } catch (err) {
              tiles.push({
                tileId: item.i,
                status: 'error',
                tileType: 'semantic',
                title: item.title ?? item.semantic.id,
                error: err instanceof Error ? err.message : String(err),
                trustState: 'review_required',
              });
            }
            continue;
          }
          const block = resolveDashboardItemBlock(item, manifest);
          if (!block) {
            tiles.push({
              tileId: item.i,
              status: 'unresolved',
              blockRef: item.block ? (isBlockIdRef(item.block) ? item.block.blockId : item.block.ref) : '(missing source)',
              error: 'Block reference could not be resolved',
            });
            continue;
          }
          let blockSource: string | undefined;
          let blockTargetConnection: ConnectionConfig | undefined;
          let blockPlan: ReturnType<typeof buildExecutionPlan> | undefined;
          let blockFilterApplication: ReturnType<typeof applyDashboardFiltersToBlockExecution> | undefined;
          let blockInvocation: ReturnType<typeof prepareBlockInvocation> | undefined;
          try {
            assertAppAccess({
              app: loaded.app,
              domain: block.domain ?? loaded.dashboard.metadata.domain ?? loaded.app.domain,
              level: 'execute',
            });
            const absBlockPath = join(projectRoot, block.filePath);
            blockSource = readFileSync(absBlockPath, 'utf-8');
            const currentSourceRevision = `sha256:${createHash('sha256').update(blockSource).digest('hex')}`;
            if (item.sourceRevision && item.sourceRevision !== currentSourceRevision) {
              tiles.push({
                tileId: item.i,
                status: 'error',
                tileType: 'block',
                blockId: block.name,
                blockPath: block.filePath,
                certificationStatus: block.status ?? null,
                title: item.title ?? block.name,
                trustState: 'review_required',
                error: 'This App source changed after it was selected. Refresh the source binding and rerun preview.',
              });
              continue;
            }
            blockTargetConnection = requireActiveConnection(isConnectionConfig(body.connection) ? body.connection : connection);
            const tableMapping = await resolveSemanticTableMapping(executor, blockTargetConnection, semanticLayer, projectRoot);
            const boundParameters = dashboardTileParameterValues({
              item,
              dashboardValues: dashboardVariables,
              requestValues: variables,
            });
            blockInvocation = prepareBlockInvocation({
              block: block.name,
              source: blockSource,
              parameters: { ...dashboardVariables, ...boundParameters },
              parameterSources: Object.fromEntries(
                Object.keys(boundParameters).map((name) => [name, 'surface' as const]),
              ),
              surface: 'app',
            });
            if (blockInvocation.errors.length || blockInvocation.unresolvedParameters.length) {
              tiles.push({
                tileId: item.i,
                status: 'unresolved',
                tileType: 'block',
                blockId: block.name,
                title: item.title ?? block.name,
                error: blockInvocation.errors[0] ?? `Needs values for: ${blockInvocation.unresolvedParameters.join(', ')}`,
                invocation: {
                  resolvedParameters: blockInvocation.resolvedParameters,
                  unresolvedParameters: blockInvocation.unresolvedParameters,
                  auditId: blockInvocation.auditId,
                },
              });
              continue;
            }
            const semanticCompose = semanticLayer
              ? await composeSemanticBlockSqlForRuntime(blockSource, semanticLayer, {
                  driver: blockTargetConnection.driver,
                  tableMapping,
                  projectRoot,
                  projectConfig,
                  detectedProvider: semanticDetectedProvider,
                  parameters: blockInvocation.values,
                })
              : null;
            blockPlan = buildExecutionPlan(
              { id: item.i, type: 'dql', source: blockSource, title: item.title ?? block.name },
              {
                semanticLayer,
                driver: blockTargetConnection.driver,
                tableMapping,
                parameters: blockInvocation.values,
                semanticSql: semanticCompose?.sql ?? undefined,
              },
            );
            if (!blockPlan && !semanticCompose?.sql) {
              tiles.push({
                tileId: item.i,
                status: 'error',
                blockId: block.name,
                error: semanticCompose?.diagnostics.find((diagnostic) => diagnostic.severity === 'error')?.message ?? 'Block produced no executable plan',
              });
              continue;
            }
            blockFilterApplication = applyDashboardFiltersToBlockExecution({
              sql: semanticCompose?.sql ?? blockPlan!.sql,
              sqlParams: blockPlan?.sqlParams ?? [],
              variables: { ...(blockPlan?.variables ?? {}), ...dashboardVariables },
              block,
              dashboard: loaded.dashboard,
              tileId: item.i,
              tileFilterBindings: item.filterBindings,
            });
            const execution = await analyticalExecutionService.execute({
              sql: blockFilterApplication.sql,
              subject: 'App tile block query',
              connection: blockTargetConnection,
              sqlParams: blockFilterApplication.sqlParams,
              variables: { ...blockFilterApplication.variables, ...blockInvocation.values },
            });
            tiles.push({
              tileId: item.i,
              status: 'ok',
              blockId: block.name,
              blockPath: block.filePath,
              certificationStatus: block.status ?? null,
              title: item.title ?? block.name,
              viz: item.viz,
              chartConfig: mergeDashboardChartConfig(blockPlan?.chartConfig, item),
              result: execution.result,
              compiledSqlFingerprint: execution.compiledSqlFingerprint,
              resultFingerprint: execution.resultFingerprint,
              filters: {
                applied: blockFilterApplication.appliedFilters,
                skipped: blockFilterApplication.skippedFilters,
              },
              invocation: {
                resolvedParameters: blockInvocation.resolvedParameters,
                unresolvedParameters: blockInvocation.unresolvedParameters,
                auditId: blockInvocation.auditId,
              },
              trustState: block.status === 'certified' ? 'certified' : 'review_required',
              citation: {
                kind: 'block',
                name: block.name,
                path: block.filePath,
              },
              artifact: {
                version: 1,
                sourceKind: block.status === 'certified' ? 'certified_block' : 'review_block',
                name: block.name,
                sourcePath: block.filePath,
                dql: blockSource.slice(0, 40_000),
                sql: blockFilterApplication.sql.slice(0, 40_000),
                trustState: block.status === 'certified' ? 'certified' : 'review_required',
                explanation: [
                  block.status === 'certified' ? 'This tile executed a certified project block.' : 'This project block is not certified and remains review-required.',
                  'Dashboard filters and typed parameters were bound before read-only execution.',
                ],
                executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
              },
            });
          } catch (err) {
            if (err instanceof DQLAccessDeniedError) {
              tiles.push({
                tileId: item.i,
                status: 'unauthorized',
                blockId: block.name,
                error: err.message,
              });
            } else {
              const repaired = await repairFailedAppTileExecution({
                source: block.status === 'certified' ? 'certified_block' : 'review_block',
                question: item.title ?? block.name,
                sourceSql: blockFilterApplication?.sql ?? blockPlan?.sql,
                sourceDql: blockSource,
                artifactName: block.name,
                error: err,
                targetConnection: blockTargetConnection,
                targetConnectionName: projectConfig.defaultConnectionName,
                sqlParams: blockFilterApplication?.sqlParams ?? blockPlan?.sqlParams,
                variables: {
                  ...(blockPlan?.variables ?? {}),
                  ...(blockFilterApplication?.variables ?? {}),
                  ...(blockInvocation?.values ?? {}),
                },
              });
              if (repaired.ok) {
                tiles.push({
                  tileId: item.i,
                  status: 'ok',
                  tileType: 'block',
                  blockId: block.name,
                  blockPath: block.filePath,
                  certificationStatus: block.status ?? null,
                  title: item.title ?? block.name,
                  viz: item.viz,
                  chartConfig: mergeDashboardChartConfig(blockPlan?.chartConfig, item),
                  result: normalizeQueryResult(repaired.result),
                  ...(blockFilterApplication ? {
                    filters: {
                      applied: blockFilterApplication.appliedFilters,
                      skipped: blockFilterApplication.skippedFilters,
                    },
                  } : {}),
                  ...(blockInvocation ? {
                    invocation: {
                      resolvedParameters: blockInvocation.resolvedParameters,
                      unresolvedParameters: blockInvocation.unresolvedParameters,
                      auditId: blockInvocation.auditId,
                    },
                  } : {}),
                  trustState: 'review_required',
                  repair: repaired.repair,
                  citation: { kind: 'block_repaired', name: block.name, path: block.filePath },
                  artifact: {
                    version: 1,
                    sourceKind: block.status === 'certified' ? 'certified_block' : 'review_block',
                    name: block.name,
                    sourcePath: block.filePath,
                    ...(repaired.repairedDql ?? blockSource ? { dql: (repaired.repairedDql ?? blockSource!).slice(0, 40_000) } : {}),
                    sql: repaired.repairedSql.slice(0, 40_000),
                    trustState: 'review_required',
                    explanation: [
                      'The saved certified block was not changed.',
                      'A bounded repair executed on the original data target; this repaired result requires human review.',
                    ],
                    executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                  },
                });
                continue;
              }
              tiles.push({
                tileId: item.i,
                status: 'error',
                tileType: 'block',
                blockId: block.name,
                error: err instanceof Error ? err.message : String(err),
                repair: repaired.repair,
                ...(blockSource ? {
                  artifact: {
                    version: 1,
                    sourceKind: block.status === 'certified' ? 'certified_block' : 'review_block',
                    name: block.name,
                    sourcePath: block.filePath,
                    dql: blockSource.slice(0, 40_000),
                    ...(blockFilterApplication?.sql ?? blockPlan?.sql ? { sql: (blockFilterApplication?.sql ?? blockPlan!.sql).slice(0, 40_000) } : {}),
                    trustState: 'review_required',
                    explanation: ['Automatic repair could not produce a safe executable result. The saved block was not changed.'],
                    executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
                  },
                } : {}),
              });
            }
          }
          }
        };
        await Promise.all(Array.from(
          { length: Math.min(4, itemsToRun.length) },
          () => runTileWorker(),
        ));
        tiles.sort((left, right) => (tileOrder.get(left.tileId) ?? 0) - (tileOrder.get(right.tileId) ?? 0));
        localApps.current?.close();
        // Which of each tile's result columns a viewer may safely filter on.
        // Decided here, from a real dialect parse of the SQL that actually ran,
        // for the same reason Ask does it server-side: an aggregate output needs
        // HAVING, and picking such a column off the table would quietly change
        // the measure. The browser must never re-derive this.
        const runDialect = (() => {
          try { return requireActiveConnection().driver || 'duckdb'; } catch { return 'duckdb'; }
        })();
        const tilesWithFilters = tiles.map((tile) => {
          const executedSql = (tile as { artifact?: { sql?: unknown } }).artifact?.sql;
          const columns = (tile as { result?: { columns?: string[] } }).result?.columns ?? [];
          if (typeof executedSql !== 'string' || columns.length === 0) return tile;
          try {
            const dashboardItem = loaded.dashboard.layout.items.find((item) => item.i === tile.tileId);
            const block = dashboardItem ? resolveDashboardItemBlock(dashboardItem, manifest) : null;
            const declaredDimensions = block?.dimensions ?? [];
            const filterable = dashboardFilterableResultColumns(executedSql, columns, declaredDimensions, runDialect);
            return filterable.length > 0 ? { ...tile, filterableColumns: filterable } : tile;
          } catch {
            return tile; // Unparseable SQL simply offers no filter candidates.
          }
        });
        const filterOptions = collectDashboardFilterOptions(loaded.dashboard, tilesWithFilters);
        const snapshot = projectSnapshot();
        const filterFingerprint = createHash('sha256').update(JSON.stringify(dashboardVariables)).digest('hex');
        const resultFingerprint = createHash('sha256').update(JSON.stringify(tiles.map((tile) => ({ tileId: tile.tileId, status: tile.status, result: tile.result })))).digest('hex');
        const personaFingerprint = createHash('sha256').update(activePersonaAppId() ?? 'global').digest('hex');
        const runId = `app_run_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
        const storyResult = buildDeterministicDashboardStory({
          goal: loaded.dashboard.story?.goal ?? loaded.dashboard.metadata.businessOutcome ?? loaded.dashboard.metadata.title,
          audience: loaded.dashboard.story?.audience ?? loaded.dashboard.metadata.audience,
          filters: dashboardVariables,
          tiles: tiles.map((tile) => ({
            tileId: tile.tileId,
            title: typeof tile.title === 'string' ? tile.title : tile.tileId,
            status: tile.status,
            trustState: (tile.trustState === 'certified' || tile.trustState === 'review_required' || tile.trustState === 'draft_ready'
              ? tile.trustState
              : tile.certificationStatus === 'certified' ? 'certified' : 'review_required') as DashboardDisplayTrustState,
            result: tile.result as { columns?: unknown[]; rows?: unknown[]; rowCount?: number } | undefined,
            citation: tile.citation,
          })),
          eligibleTileIds: loaded.dashboard.story?.eligibleTileIds,
          driverTileIds: loaded.dashboard.story?.driverTileIds,
        });
        const runEvidence = {
          appId,
          dashboardId,
          snapshotId: snapshot.snapshotId,
          filterFingerprint,
          resultFingerprint,
          personaFingerprint,
          successfulTileIds: tiles.filter((tile) => tile.status === 'ok').map((tile) => tile.tileId),
          semanticApprovalEligibleTileIds: tiles.filter((tile) => (
            tile.status === 'ok'
            && tile.tileType === 'semantic'
            && (!('repair' in tile) || tile.repair?.approvalEligible !== false)
          )).map((tile) => tile.tileId),
          facts: storyResult.facts,
          story: storyResult.story,
          expiresAt: Date.now() + 15 * 60_000,
        };
        dashboardRunEvidence.set(runId, runEvidence);
        if (runSurface === 'app-builds') {
          const receiptStorage = new LocalAppStorage(defaultLocalAppsDbPath(projectRoot));
          try {
            receiptStorage.saveAppPreviewEvidence({
              runId,
              draftId: appId,
              dashboardId,
              snapshotId: snapshot.snapshotId,
              filterFingerprint,
              resultFingerprint,
              personaFingerprint,
              successfulTileIds: runEvidence.successfulTileIds,
              semanticApprovalEligibleTileIds: runEvidence.semanticApprovalEligibleTileIds,
              createdAt: new Date().toISOString(),
            });
          } finally {
            receiptStorage.close();
          }
        }
        for (const [id, evidence] of dashboardRunEvidence) if (evidence.expiresAt < Date.now()) dashboardRunEvidence.delete(id);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          appId,
          dashboardId,
          persona: activePersonaAppId() ? { appId: activePersonaAppId() } : null,
          runId,
          snapshotId: snapshot.snapshotId,
          filterFingerprint,
          resultFingerprint,
          personaFingerprint,
          filterOptions,
          tiles: tilesWithFilters,
          facts: storyResult.facts,
          story: storyResult.story,
        }));
      } catch (err) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: err instanceof Error ? err.message : String(err) }));
      }
      return;
    }

    // Apps, dashboards, persona — see apps-api.ts. Returns true if handled.
    if (path.startsWith('/api/apps')
      || path.startsWith('/api/app-builds')
      || path.startsWith('/api/app-recoveries')
      || path.startsWith('/api/visualizations')
      || path === '/api/persona') {
      try {
          const handled = await handleAppsApi({
            req,
            res: res as unknown as ServerResponse,
          url,
          path,
          projectRoot,
          executeSql: executeLocalSqlForStoredResult,
          generateInvestigationSql: generateInvestigationSqlForApp,
          runNotebook: (appId, notebookPath) => runNotebookForApp(appId, notebookPath),
          // P4: give the App ask lane a grounded research planner over the catalog.
          planResearch: async ({ question, isFollowUp }) => {
            const metrics = loadSemanticMetrics(projectRoot);
            let blocks = collectPlanBlocks(projectRoot, { certifiedOnly: true });
            if (blocks.length === 0) blocks = collectPlanBlocks(projectRoot, { certifiedOnly: false });
            return planResearch({ question, metrics, blocks, isFollowUp });
          },
          // Two-phase app build gap-fill: bounded governed answers for uncovered
          // questions. Throws when no provider is configured — propose degrades
          // gracefully by listing the gap instead.
          generateGovernedAnswer: (question, appContext) => generateAppBuildAnswerWithRepair(question, appContext),
          // App Builder owns its orchestration and structured state. It shares
          // only the configured provider adapter with Ask/Notebook.
          planAppBuild: async ({ system, user }) => {
            const provider = await createBlockStudioAssistProvider(projectRoot);
            if (!provider) return undefined;
            return provider.generate([
              { role: 'system', content: system },
              { role: 'user', content: user },
            ], { maxTokens: 2_400, temperature: 0.1 });
          },
          queueOperation: <TResult>(
            input: { type: string; scope: string; resourceRevision?: string; message?: string; cancellable?: boolean },
            task: (signal: AbortSignal, report: (progress: Partial<LocalOperationProgress>) => void) => Promise<TResult>,
          ) => {
            const operation = operationCoordinator.create(input) as LocalOperation<TResult>;
            void operationCoordinator.run(operation.id, task);
            return operation;
          },
          scheduleProjectRefresh: (reason) => { scheduleProjectRefresh(reason); },
          verifyDashboardRun: ({ runId, appId, dashboardId, tileIds }) => {
            const evidence = dashboardRunEvidence.get(runId);
            if (!evidence || evidence.expiresAt < Date.now()) return { ok: false, error: 'The dashboard run receipt expired. Run the dashboard again.' };
            if (evidence.appId !== appId || evidence.dashboardId !== dashboardId) return { ok: false, error: 'The dashboard run receipt does not match this App page.' };
            const successful = new Set(evidence.successfulTileIds);
            const failed = tileIds.filter((tileId) => !successful.has(tileId));
            if (failed.length > 0) return { ok: false, error: `These semantic tiles did not complete successfully: ${failed.join(', ')}` };
            const approvalEligible = new Set(evidence.semanticApprovalEligibleTileIds);
            const repaired = tileIds.filter((tileId) => !approvalEligible.has(tileId));
            if (repaired.length > 0) {
              return { ok: false, error: `These semantic previews required SQL repair and cannot be approved as governed semantic results: ${repaired.join(', ')}. Review them as exploratory App analysis instead.` };
            }
            return { ok: true, snapshotId: evidence.snapshotId, resultFingerprint: evidence.resultFingerprint };
          },
          verifyAppBuildPreview: ({ runId, draftId, dashboardId, tileIds }) => {
            const evidence = loadAppBuildPreviewEvidence(runId);
            if (!evidence) return { ok: false, error: 'The App preview receipt is unavailable. Run the local draft again.' };
            if (evidence.appId !== draftId || evidence.dashboardId !== dashboardId) return { ok: false, error: 'The App preview receipt does not match this local draft page.' };
            const successful = new Set(evidence.successfulTileIds);
            const failed = tileIds.filter((tileId) => !successful.has(tileId));
            if (failed.length > 0) return { ok: false, error: `These App components did not complete successfully: ${failed.join(', ')}` };
            return { ok: true, snapshotId: evidence.snapshotId, resultFingerprint: evidence.resultFingerprint };
          },
          // Story narration for commit — LLM-backed with deterministic fallback.
          narrate: narrateForAgentRun,
        });
        if (handled) return;
      } catch (err) {
        if (!res.headersSent) {
          res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: (err as Error).message }));
        }
        return;
      }
    }

    // SSE endpoint for hot-reload file watching
    if (req.method === 'GET' && path === '/api/watch') {
      res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
        'X-Accel-Buffering': 'no',
      });
      res.write(': connected\n\n');
        sseClients.add(res as unknown as ServerResponse);
        req.on('close', () => { sseClients.delete(res as unknown as ServerResponse); });
      return;
    }

    // ── dql-notebook file management API ─────────────────────────────────────
    // GET  /api/notebooks          — list all .dql/.dqlnb files grouped by folder
    // GET  /api/notebook-content   — read a file (?path=relative/path)
    // POST /api/notebooks          — create new notebook
    // PUT  /api/notebook-content   — save file
    // GET  /api/schema             — list data files for schema panel
    if (req.method === 'GET' && path === '/api/notebooks') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(scanNotebookFiles(projectRoot)));
      return;
    }

    if (req.method === 'GET' && path === '/api/notebook-content') {
      const filePath = url.searchParams.get('path');
      if (!filePath) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Missing path query parameter' }));
        return;
      }
      const absPath = safeJoin(projectRoot, filePath);
      if (!absPath || !existsSync(absPath)) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'File not found' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ content: readFileSync(absPath, 'utf-8') }));
      return;
    }

    if (req.method === 'POST' && path === '/api/notebooks') {
      try {
        const body = await readJSON(req);
        const { name, template, ownerDomain, usesDomains } = body as {
          name: string;
          template: string;
          ownerDomain?: string;
          usesDomains?: string[];
        };
        if (!name || typeof name !== 'string') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing notebook name' }));
          return;
        }
        const normalizedOwnerDomain = typeof ownerDomain === 'string' && ownerDomain.trim()
          ? ownerDomain.trim()
          : undefined;
        if (normalizedOwnerDomain && !loadDomainPackageRegistry(projectRoot).get(normalizedOwnerDomain)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Unknown domain: ${normalizedOwnerDomain}` }));
          return;
        }
        const normalizedUsesDomains = Array.from(new Set([
          ...(normalizedOwnerDomain ? [normalizedOwnerDomain] : []),
          ...(Array.isArray(usesDomains) ? usesDomains : []),
        ].map((domain) => typeof domain === 'string' ? domain.trim() : '').filter(Boolean)));
        const registry = loadDomainPackageRegistry(projectRoot);
        const unknownUsedDomain = normalizedUsesDomains.find((domain) => !registry.get(domain));
        if (unknownUsedDomain) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Unknown domain: ${unknownUsedDomain}` }));
          return;
        }
        const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'notebook';
        const privateDraft = (body as { visibility?: unknown }).visibility === 'private';
        const nbDir = privateDraft ? privateNotebookDir(projectRoot) : join(projectRoot, 'notebooks');
        mkdirSync(nbDir, { recursive: true });
        const nbPath = join(nbDir, `${slug}.dqlnb`);
        if (existsSync(nbPath)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Notebook already exists' }));
          return;
        }
        const content = buildNotebookTemplate(name, template ?? 'blank', {
          ownerDomain: normalizedOwnerDomain,
          usesDomains: normalizedUsesDomains,
        });
        writeFileSync(nbPath, content, 'utf-8');
        const createdPath = privateDraft
          ? `${PRIVATE_NOTEBOOK_PREFIX}/${slug}.dqlnb`
          : `notebooks/${slug}.dqlnb`;
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          path: createdPath,
          content,
          visibility: privateDraft ? 'private' : 'shared',
        }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: error.message, code: 'unauthorized' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // POST /api/notebooks/publish — move a private draft into tracked source.
    // Publishing is the moment a notebook becomes the team's: until now it sat
    // under .dql/local/, which the ignore rules keep out of every commit and
    // diff. The move is a rename, so the file is never half-published.
    if (req.method === 'POST' && path === '/api/notebooks/publish') {
      try {
        const body = await readJSON(req) as { path?: unknown };
        const requested = typeof body.path === 'string' ? normalizeNotebookPath(body.path.trim()) : '';
        if (!requested) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Missing notebook path.' }));
          return;
        }
        if (!isPrivateNotebookPath(requested) || requested.includes('..') || !/\.(dqlnb|dql)$/i.test(requested)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Only a private notebook draft can be published.' }));
          return;
        }
        const source = resolve(projectRoot, requested);
        const rootPrefix = `${resolve(projectRoot)}${sep}`;
        if (!source.startsWith(rootPrefix) || !existsSync(source)) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Draft not found.' }));
          return;
        }
        const fileName = requested.split('/').at(-1) as string;
        const destination = join(projectRoot, 'notebooks', fileName);
        if (existsSync(destination)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            ok: false,
            error: `notebooks/${fileName} already exists. Rename the draft before publishing it.`,
          }));
          return;
        }
        mkdirSync(join(projectRoot, 'notebooks'), { recursive: true });
        renameSync(source, destination);
        // Cached results are local state, not something to publish: leaving the
        // sidecar behind would strand it beside a draft that no longer exists.
        const sidecar = source.replace(/\.(dqlnb|dql)$/i, '.run.json');
        if (sidecar !== source) rmSync(sidecar, { force: true });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          path: `notebooks/${fileName}`,
          previousPath: requested,
          visibility: 'shared',
        }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: error.message, code: 'unauthorized' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // DELETE /api/notebooks?path=notebooks/x.dqlnb — remove a notebook file.
    // Deliberately narrow: only .dqlnb/.dql files under notebooks/, resolved and
    // re-checked against the project root so a crafted path cannot escape it.
    if (req.method === 'DELETE' && path === '/api/notebooks') {
      try {
        const relativePath = url.searchParams.get('path')?.trim();
        if (!relativePath) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Missing notebook path.' }));
          return;
        }
        const normalized = normalizeNotebookPath(relativePath);
        const deletable = normalized.startsWith('notebooks/') || isPrivateNotebookPath(normalized);
        if (!deletable || !/\.(dqlnb|dql)$/i.test(normalized) || normalized.includes('..')) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Only notebook files under notebooks/ can be deleted.' }));
          return;
        }
        const absolute = resolve(projectRoot, normalized);
        const rootPrefix = `${resolve(projectRoot)}${sep}`;
        if (!absolute.startsWith(rootPrefix)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Path escapes the project root.' }));
          return;
        }
        if (!existsSync(absolute)) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Notebook not found.' }));
          return;
        }
        // A private draft was never committed and an uncommitted notebook is not
        // in git either, so deleting the file outright is unrecoverable. It goes
        // to the same recovery bundle discard uses instead.
        const recovered = moveToTrashBundle(projectRoot, projectRoot, [normalized], 'notebooks');
        // Drop the run-state sidecar too, or the next notebook created with the
        // same slug inherits the deleted one's cached results.
        const sidecar = absolute.replace(/\.(dqlnb|dql)$/i, '.run.json');
        if (sidecar !== absolute) rmSync(sidecar, { force: true });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, path: normalized, recovered }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: error.message, code: 'unauthorized' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'PUT' && path === '/api/notebook-content') {
      try {
        const body = await readJSON(req);
        const { path: filePath, content } = body as { path: string; content: string };
        if (!filePath || typeof content !== 'string') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing path or content' }));
          return;
        }
        const absPath = safeJoin(projectRoot, filePath);
        if (!absPath) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Invalid path' }));
          return;
        }
        await mkdirAsync(dirname(absPath), { recursive: true });
        const toWrite = absPath.endsWith('.dql')
          ? canonicalizeSafe(content)
          : absPath.endsWith('.dqlnb')
            ? canonicalizeNotebookSafe(content)
            : content;
        const tempPath = `${absPath}.tmp-${process.pid}-${Date.now()}`;
        try {
          await writeFileAsync(tempPath, toWrite, 'utf-8');
          await renameAsync(tempPath, absPath);
        } catch (error) {
          await rmAsync(tempPath, { force: true }).catch(() => undefined);
          throw error;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: error.message, code: 'unauthorized' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/notebook/research') {
      let storage: LocalNotebookResearchStorage | undefined;
      const limit = notebookResearchInteger(url.searchParams.get('limit'), 50, 1, 500);
      const offset = notebookResearchInteger(url.searchParams.get('offset'), 0, 0, Number.MAX_SAFE_INTEGER);
      try {
        storage = openNotebookResearchStorage();
        const notebookPath = notebookResearchString(url.searchParams.get('path'));
        const sourceCellId = notebookResearchString(url.searchParams.get('sourceCellId') ?? url.searchParams.get('cellId'));
        const domain = notebookResearchString(url.searchParams.get('domain'));
        const owner = notebookResearchString(url.searchParams.get('owner'));
        const intent = notebookResearchIntent(url.searchParams.get('intent'));
        const search = notebookResearchString(url.searchParams.get('q')) ?? notebookResearchString(url.searchParams.get('search'));
        const status = notebookResearchStatus(url.searchParams.get('status'));
        const reviewStatus = notebookResearchReviewStatus(url.searchParams.get('reviewStatus'));
        const promotionAction = notebookResearchPromotionAction(url.searchParams.get('promotionAction') ?? url.searchParams.get('action'));
        const readiness = notebookResearchReadiness(url.searchParams.get('readiness') ?? url.searchParams.get('ready'));
        const age = notebookResearchAge(url.searchParams.get('age'));
        const nextAction = notebookResearchNextAction(url.searchParams.get('nextAction') ?? url.searchParams.get('next'));
        const activeOnlyParam = url.searchParams.get('activeOnly') ?? url.searchParams.get('active');
        const activeOnly = activeOnlyParam === 'true' || activeOnlyParam === '1';
        const sort = notebookResearchSort(url.searchParams.get('sort'));
        const page = storage.listRunsPage({ notebookPath, sourceCellId, domain, owner, intent, search, status, reviewStatus, promotionAction, readiness, age, nextAction, activeOnly, sort, limit, offset });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(withNotebookResearchChecklistPage(page)));
      } catch (error) {
        if (isNotebookResearchStorageUnavailable(error)) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(withNotebookResearchChecklistPage(emptyNotebookResearchListPage({ limit, offset }))));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      } finally {
        storage?.close();
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/notebook/research') {
      let storage: LocalNotebookResearchStorage | undefined;
      try {
        storage = openNotebookResearchStorage();
	        const body = await readJSON(req);
	        const notebookPath = notebookResearchString(body.notebookPath) ?? notebookResearchString(body.path);
	        const question = notebookResearchString(body.question);
	        const sourceCell = notebookResearchSourceCellPayload(body);
        const sourceCellId = notebookResearchString(body.sourceCellId) ?? notebookResearchSourceCellId(sourceCell);
        const sourceCellName = notebookResearchString(body.sourceCellName) ?? notebookResearchSourceCellName(sourceCell);
        const sourceCellFingerprint = notebookResearchString(body.sourceCellFingerprint) ?? notebookResearchSourceCellFingerprint(sourceCell);
        const dqlArtifact = normalizeDqlArtifactReference(body.dqlArtifact);
	        if (!notebookPath || !question) {
	          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
	          res.end(serializeJSON({ error: 'notebookPath and question are required.' }));
          return;
        }
        const created = storage.createRun({
          notebookPath,
          domain: notebookResearchString(body.domain),
          owner: notebookResearchString(body.owner),
          sourceCell,
	          sourceCellId,
	          sourceCellName,
	          sourceCellFingerprint,
	          title: notebookResearchString(body.title),
	          question,
          intent: notebookResearchIntent(body.intent),
          context: body.context,
          generatedSql: notebookResearchString(body.generatedSql),
          reviewedSql: notebookResearchString(body.reviewedSql),
          dqlArtifact,
        });
        const run = body.run === true
          ? await runNotebookResearch(storage, created, {
              domain: notebookResearchString(body.domain),
	              sourceCellFingerprint,
	              question,
              intent: notebookResearchIntent(body.intent),
              context: body.context,
              generatedSql: notebookResearchString(body.generatedSql),
              reviewedSql: notebookResearchString(body.reviewedSql),
              dqlArtifact,
            })
          : created;
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ run: withNotebookResearchChecklist(run) }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      } finally {
        storage?.close();
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/notebook/research/context-preview') {
      try {
        const body = await readJSON(req);
        const notebookPath = notebookResearchString(body.notebookPath) ?? notebookResearchString(body.path);
        const question = notebookResearchString(body.question);
        if (!notebookPath || !question) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'notebookPath and question are required.' }));
          return;
        }
	        const intent = notebookResearchIntent(body.intent) ?? 'ad_hoc_analysis';
	        const domain = notebookResearchString(body.domain);
	        const context = body.context;
	        const sourceCell = notebookResearchSourceCellPayload(body);
	        const contextPack = await buildLocalContextPack(projectRoot, {
          question,
          mode: 'question',
          surface: 'notebook',
          selectedContext: {
	            activeSurface: 'notebook',
	            notebookPath,
	            domain,
	            sourceCellId: notebookResearchString(body.sourceCellId) ?? notebookResearchSourceCellId(sourceCell),
	            sourceCellName: notebookResearchString(body.sourceCellName) ?? notebookResearchSourceCellName(sourceCell),
	            context,
            intent,
            researchPattern: notebookResearchIntentPattern(intent),
          },
          strictness: 'exploratory',
          limit: 160,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(notebookResearchContextPreview(contextPack)));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/notebook/research/seed-cells') {
      let storage: LocalNotebookResearchStorage | undefined;
      try {
        storage = openNotebookResearchStorage();
        const body = await readJSON(req);
        const notebookPath = notebookResearchString(body.notebookPath) ?? notebookResearchString(body.path);
        if (!notebookPath) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'notebookPath is required.' }));
          return;
        }
        const cells: unknown[] = Array.isArray(body.cells) ? body.cells : [];
        if (cells.length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'At least one source cell is required.' }));
          return;
        }
        const validCells = cells.filter((cell): cell is Record<string, unknown> => Boolean(cell && typeof cell === 'object' && !Array.isArray(cell)));
        const invalidCellCount = cells.length - validCells.length;
        const seeded = storage.seedRunsFromCells({
          notebookPath,
          domain: notebookResearchString(body.domain),
          owner: notebookResearchString(body.owner),
          notebookTitle: notebookResearchString(body.notebookTitle),
	          cells: validCells.map((cell) => ({
	            sourceCell: notebookResearchSourceCellPayload(cell),
	            id: notebookResearchString(cell.id),
	            sourceCellId: notebookResearchString(cell.sourceCellId),
	            name: notebookResearchString(cell.name),
	            sourceCellName: notebookResearchString(cell.sourceCellName),
	            sourceCellFingerprint: notebookResearchString(cell.sourceCellFingerprint),
	            title: notebookResearchString(cell.title),
	            type: notebookResearchString(cell.type),
	            sql: notebookResearchString(cell.sql),
	            content: notebookResearchString(cell.content),
	            source: notebookResearchString(cell.source),
	            question: notebookResearchString(cell.question),
	            intent: notebookResearchIntent(cell.intent),
	          })),
          limit: 1000,
        });
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          created: seeded.created.map(withNotebookResearchChecklist),
          createdCount: seeded.createdCount,
          skippedCount: seeded.skippedCount + invalidCellCount,
          limitApplied: seeded.limitApplied,
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      } finally {
        storage?.close();
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/notebook/research/source-coverage') {
      let storage: LocalNotebookResearchStorage | undefined;
      let requestedSourceCellCount = 0;
      let limit = 10_000;
      try {
        const body = await readJSON(req);
        const notebookPath = notebookResearchString(body.notebookPath) ?? notebookResearchString(body.path);
        if (!notebookPath) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'notebookPath is required.' }));
          return;
        }
	        const rawSourceCells = Array.isArray(body.sourceCells)
	          ? body.sourceCells
	          : Array.isArray(body.cells)
	            ? body.cells
	            : [];
	        const sourceCells = rawSourceCells.flatMap((cell: unknown): NotebookResearchSourceCellInput[] => {
	          if (!cell || typeof cell !== 'object' || Array.isArray(cell)) return [];
	          const record = cell as Record<string, unknown>;
	          const nested = notebookResearchSourceCellPayload(record) ?? {};
	          return [{
	            ...nested,
	            id: notebookResearchString(record.id) ?? nested.id,
	            sourceCellId: notebookResearchString(record.sourceCellId) ?? nested.sourceCellId,
	            cellId: notebookResearchString(record.cellId) ?? nested.cellId,
	            name: notebookResearchString(record.name) ?? nested.name,
	            sourceCellName: notebookResearchString(record.sourceCellName) ?? nested.sourceCellName,
	            title: notebookResearchString(record.title) ?? nested.title,
	            fingerprint: notebookResearchString(record.fingerprint) ?? nested.fingerprint,
	            sourceCellFingerprint: notebookResearchString(record.sourceCellFingerprint) ?? nested.sourceCellFingerprint,
	            sqlFingerprint: notebookResearchString(record.sqlFingerprint) ?? nested.sqlFingerprint,
	            type: notebookResearchString(record.type) ?? nested.type,
	          }];
	        });
	        const requestedIds: unknown[] = Array.isArray(body.sourceCellIds)
	          ? body.sourceCellIds
	          : rawSourceCells.length > 0
	            ? sourceCells.map((cell: NotebookResearchSourceCellInput) => notebookResearchSourceCellId(cell))
	            : [];
	        const sourceCellIds: string[] = Array.from(new Set(
	          requestedIds
	            .map((id: unknown) => notebookResearchString(id))
	            .filter((id: string | undefined): id is string => Boolean(id)),
	        ));
	        requestedSourceCellCount = new Set([
	          ...sourceCellIds,
	          ...sourceCells
	            .map((cell: NotebookResearchSourceCellInput) => notebookResearchSourceCellId(cell))
	            .filter((id: string | undefined): id is string => Boolean(id)),
	        ]).size;
        limit = typeof body.limit === 'number' && Number.isFinite(body.limit)
          ? Math.max(1, Math.min(10_000, Math.floor(body.limit)))
          : 10_000;
        storage = openNotebookResearchStorage();
	        const linkedRuns = storage.listLatestRunsBySourceCell({
	          notebookPath,
	          sourceCellIds,
	          sourceCells,
	          limit,
	        });
	        const missingRuns = storage.listLatestRunsForMissingSourceCells({
	          notebookPath,
	          sourceCellIds,
	          sourceCells,
	          limit,
	        });
        const runs = [...linkedRuns, ...missingRuns];
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          runs: runs.map(withNotebookResearchChecklist),
	          requestedCount: requestedSourceCellCount,
	          matchedCount: runs.length,
	          limitApplied: requestedSourceCellCount > limit,
	        }));
      } catch (error) {
        if (isNotebookResearchStorageUnavailable(error)) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            runs: [],
            requestedCount: requestedSourceCellCount,
            matchedCount: 0,
            limitApplied: requestedSourceCellCount > limit,
          }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      } finally {
        storage?.close();
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/notebook/research/diagnostics') {
      let storage: LocalNotebookResearchStorage | undefined;
      try {
        storage = openNotebookResearchStorage();
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(storage.getDiagnostics()));
      } catch (error) {
        if (isNotebookResearchStorageUnavailable(error)) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(emptyNotebookResearchDiagnostics()));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      } finally {
        storage?.close();
      }
      return;
    }

    const notebookResearchMatch = /^\/api\/notebook\/research\/([^/]+)(?:\/([^/]+))?$/.exec(path);
    if (notebookResearchMatch) {
      const id = decodeURIComponent(notebookResearchMatch[1]);
      const action = notebookResearchMatch[2];
      let storage: LocalNotebookResearchStorage | undefined;
      try {
        storage = openNotebookResearchStorage();
        const run = storage.getRun(id);
        if (!run) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Notebook research run not found.' }));
          return;
        }

        if (req.method === 'GET' && !action) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ run: withNotebookResearchChecklist(run) }));
          return;
        }

	        if (req.method === 'PATCH' && !action) {
	          const body = await readJSON(req);
	          const sourceCell = notebookResearchSourceCellPayload(body);
	          const sourceCellIdPatch = notebookResearchPatchString(body, 'sourceCellId');
	          const sourceCellNamePatch = notebookResearchPatchString(body, 'sourceCellName');
	          const sourceCellFingerprintPatch = notebookResearchPatchString(body, 'sourceCellFingerprint');
          const updated = storage.updateRun(id, {
            domain: notebookResearchString(body.domain),
            owner: notebookResearchString(body.owner),
            sourceCellId: sourceCellIdPatch !== undefined ? sourceCellIdPatch : notebookResearchSourceCellId(sourceCell),
	            sourceCellName: sourceCellNamePatch !== undefined ? sourceCellNamePatch : notebookResearchSourceCellName(sourceCell),
	            sourceCellFingerprint: sourceCellFingerprintPatch !== undefined ? sourceCellFingerprintPatch : notebookResearchSourceCellFingerprint(sourceCell),
            title: notebookResearchString(body.title),
            question: notebookResearchString(body.question),
            intent: notebookResearchIntent(body.intent),
            context: body.context,
            recommendation: notebookResearchString(body.recommendation),
            evidence: body.evidence,
            contextPackId: notebookResearchString(body.contextPackId),
            routeDecision: body.routeDecision,
            generatedSql: notebookResearchString(body.generatedSql),
            reviewedSql: notebookResearchString(body.reviewedSql),
            dqlArtifact: normalizeDqlArtifactReference(body.dqlArtifact),
            warnings: Array.isArray(body.warnings) ? body.warnings.filter((item: unknown): item is string => typeof item === 'string') : undefined,
            reviewStatus: notebookResearchReviewStatus(body.reviewStatus),
            dqlPromotionAction: notebookResearchPromotionAction(body.dqlPromotionAction),
          }) ?? run;
          const planned = storage.updateRun(updated.id, {
            researchPlan: buildNotebookResearchPlan({
              run: updated,
              evidence: updated.evidence,
              resultPreview: updated.resultPreview as ReturnType<typeof normalizeQueryResult> | undefined,
              previewError: updated.error,
              generatedSql: updated.generatedSql,
              reviewedSql: updated.reviewedSql,
              dqlArtifact: updated.dqlArtifact,
              routeDecision: updated.routeDecision,
            }),
          }) ?? updated;
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ run: withNotebookResearchChecklist(planned) }));
          return;
        }

	        if (req.method === 'POST' && action === 'run') {
	          const body = await readJSON(req).catch(() => ({}));
	          const sourceCell = notebookResearchSourceCellPayload(body);
          const updated = await runNotebookResearch(storage, run, {
            domain: notebookResearchString(body.domain),
            owner: notebookResearchString(body.owner),
            sourceCellFingerprint: notebookResearchString(body.sourceCellFingerprint) ?? notebookResearchSourceCellFingerprint(sourceCell),
            question: notebookResearchString(body.question),
            intent: notebookResearchIntent(body.intent),
            context: body.context,
            generatedSql: notebookResearchString(body.generatedSql),
            reviewedSql: notebookResearchString(body.reviewedSql),
            dqlArtifact: normalizeDqlArtifactReference(body.dqlArtifact),
          });
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ run: withNotebookResearchChecklist(updated) }));
          return;
        }

        if (req.method === 'POST' && action === 'reuse-check') {
          const body = await readJSON(req).catch(() => ({}));
          const payload = await checkNotebookResearchReuse(storage, run, {
            domain: notebookResearchString(body.domain),
            owner: notebookResearchString(body.owner),
          });
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ...payload, run: withNotebookResearchChecklist(payload.run) }));
          return;
        }

        if (req.method === 'POST' && action === 'promote-dql') {
          const body = await readJSON(req).catch(() => ({}));
          const payload = await promoteNotebookResearchToDql(storage, run, {
            domain: notebookResearchString(body.domain),
            owner: notebookResearchString(body.owner),
            provider: notebookResearchString(body.provider),
            tags: Array.isArray(body.tags) ? body.tags.filter((item: unknown): item is string => typeof item === 'string') : undefined,
          });
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ...payload, run: withNotebookResearchChecklist(payload.run) }));
          return;
        }

        res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Unsupported notebook research operation.' }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      } finally {
        storage?.close();
      }
      return;
    }

    // ── run snapshots (v0.11) ───────────────────────────────────────────────
    // Captures executed notebook state (query results + timings) in a
    // sibling `.run.json` so notebooks can show last-run output without
    // re-executing after a reload. Snapshots are git-ignored by default.
    if (req.method === 'GET' && path === '/api/run-snapshot') {
      const notebookPath = url.searchParams.get('path') ?? '';
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(readRunSnapshot(projectRoot, notebookPath)));
      return;
    }
    if (req.method === 'PUT' && path === '/api/run-snapshot') {
      try {
        const body = await readJSON(req) as { path: string; snapshot: unknown };
        if (!body.path || typeof body.path !== 'string' || !body.snapshot) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing path or snapshot' }));
          return;
        }
        writeRunSnapshot(projectRoot, body.path, body.snapshot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true }));
      } catch (err) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: err instanceof Error ? err.message : String(err) }));
      }
      return;
    }

    // ── git read-only API (v0.11) ───────────────────────────────────────────
    // GET /api/git/status  — branch, clean, changed files
    // GET /api/git/log     — last N commits (?limit=20)
    // GET /api/git/diff    — unified diff for a single file (?path=relative/path)
    if (req.method === 'GET' && path === '/api/git/status') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(await readGitStatus(projectRoot)));
      return;
    }
    if (req.method === 'GET' && path === '/api/git/log') {
      const limit = Math.min(Number(url.searchParams.get('limit') ?? 20), 200);
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(await readGitLog(projectRoot, limit)));
      return;
    }
    if (req.method === 'GET' && path === '/api/git/diff') {
      const filePath = url.searchParams.get('path') ?? '';
      const staged = url.searchParams.get('staged') === 'true';
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(await readGitDiff(projectRoot, filePath, staged)));
      return;
    }
    if (req.method === 'GET' && path === '/api/git/branches') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(await readGitBranches(projectRoot)));
      return;
    }
    if (req.method === 'GET' && path === '/api/git/remote') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(await readGitRemote(projectRoot)));
      return;
    }
    // POST /api/git/init — `git init` in the project root, only when the
    // project is not already inside a repository.
    if (req.method === 'POST' && path === '/api/git/init') {
      try {
        const result = await gitInitProject(projectRoot);
        const status = result.ok ? 201 : result.code === 'already_a_repo' ? 409 : result.code === 'git_unavailable' ? 503 : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, code: 'error', error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    // POST /api/git/remote { name?, url, replace? } — saves the remote address
    // locally (`git remote add|set-url`). Never fetches or contacts the remote.
    if (req.method === 'POST' && path === '/api/git/remote') {
      try {
        const body = (await readJSON(req)) as { name?: unknown; url?: unknown; replace?: unknown };
        const result = await gitAddRemote(projectRoot, body ?? {});
        const status = result.ok ? 200 : result.code === 'remote_exists' ? 409 : result.code === 'error' ? 500 : 400;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, code: 'error', error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'GET' && path === '/api/git/governed-context') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(await readGitGovernedContext(projectRoot)));
      return;
    }
    if (req.method === 'POST' && path === '/api/git/governed-context/enable') {
      try {
        const result = await enableGitGovernedContextTracking(projectRoot);
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/stage') {
      try {
        const body = (await readJSON(req)) as { paths?: string[] };
        const result = await gitStage(projectRoot, body.paths ?? []);
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/unstage') {
      try {
        const body = (await readJSON(req)) as { paths?: string[] };
        const result = await gitUnstage(projectRoot, body.paths ?? []);
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/discard') {
      try {
        const body = (await readJSON(req)) as { paths?: string[] };
        const result = await gitDiscard(projectRoot, body.paths ?? []);
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/commit') {
      try {
        const body = (await readJSON(req)) as { message?: string; stageAll?: boolean; paths?: string[] };
        const result = await gitCommit(projectRoot, body.message ?? '', {
          stageAll: body.stageAll === true,
          ...(Array.isArray(body.paths) ? { paths: body.paths } : {}),
        });
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/push') {
      try {
        const result = await gitPush(projectRoot);
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/review') {
      try {
        const body = (await readJSON(req)) as { paths?: string[]; title?: string; body?: string; base?: string };
        const result = await gitCreateReview(projectRoot, {
          paths: body.paths ?? [],
          title: body.title ?? '',
          body: body.body ?? '',
          base: body.base ?? 'main',
        });
        res.writeHead(result.ok ? 201 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/review/open') {
      try {
        const body = (await readJSON(req)) as { title?: string; body?: string; base?: string };
        const result = await gitOpenReview(projectRoot, {
          title: body.title ?? '',
          body: body.body ?? '',
          base: body.base ?? 'main',
        });
        res.writeHead(result.ok ? 201 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/pull') {
      try {
        const result = await gitPull(projectRoot);
        if (result.ok) {
          try {
            await refreshUnifiedProjectIndexes(projectRoot);
          } catch (error) {
            const refreshWarning = `Git pull succeeded, but local DQL indexes could not be refreshed: ${error instanceof Error ? error.message : String(error)}`;
            result.output = [result.output, refreshWarning].filter(Boolean).join('\n');
          }
        }
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/branch') {
      try {
        const body = (await readJSON(req)) as { name?: string; checkout?: boolean };
        const result = await gitCreateBranch(projectRoot, body.name ?? '', body.checkout !== false);
        if (result.ok && body.checkout !== false) {
          await refreshUnifiedProjectIndexes(projectRoot).catch(() => undefined);
        }
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/git/checkout') {
      try {
        const body = (await readJSON(req)) as { name?: string };
        const result = await gitCheckout(projectRoot, body.name ?? '');
        if (result.ok) await refreshUnifiedProjectIndexes(projectRoot).catch(() => undefined);
        res.writeHead(result.ok ? 200 : 400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: e instanceof Error ? e.message : String(e) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/schema') {
      try {
        const dataFiles = scanDataFiles(projectRoot);
        const notebookDatasets = datasetWorkspace.list().map((dataset) => ({
          name: dataset.alias,
          path: dataset.sourcePath,
          columns: dataset.profile.columns.map((column) => ({
            name: column.name,
            type: column.type,
          })),
          source: "file",
          objectType:
            dataset.storageMode === "staged" ? "staged_dataset" : "dataset",
          datasetId: dataset.id,
          fileFingerprint: dataset.fileFingerprint,
          storageMode: dataset.storageMode,
          refreshedAt: dataset.refreshedAt,
          trustState: dataset.trustState,
        }));
        const schemaLimit = Math.min(500, Math.max(1, Number(url.searchParams.get('limit')) || 200));
        const schemaOffset = Math.max(0, Number(url.searchParams.get('offset')) || 0);
        const schemaSearch = (url.searchParams.get('q') ?? '').trim();
        const activeScope = connection
          ? optionalActiveConnectionMetadataScope(
              projectRoot,
              projectConfig,
              connection,
              projectConfig.defaultConnectionName ?? 'default',
            )
          : null;
        const cachedSnapshot = latestRuntimeSchemaSnapshotForProject(projectRoot);
        const cachedScopeMatches = Boolean(
          cachedSnapshot
          && activeScope
          && cachedSnapshot.scopeFingerprint === activeScope.scopeFingerprint,
        );
        const cachedTables = cachedScopeMatches
          ? cachedSnapshot!.tables
              .filter((table) => {
                if (!schemaSearch) return true;
                const needle = schemaSearch.toLowerCase();
                return table.relation.toLowerCase().includes(needle)
                  || table.name?.toLowerCase().includes(needle)
                  || table.schema?.toLowerCase().includes(needle);
              })
              .slice(schemaOffset, schemaOffset + schemaLimit)
          : [];
        const { tables, columnsByPath } = cachedScopeMatches
          ? {
              tables: cachedTables.map((table) => ({
                schema: table.schema ?? '',
                name: table.name ?? table.relation.split('.').at(-1) ?? table.relation,
                path: table.relation,
                type: 'TABLE',
              })),
              columnsByPath: new Map(cachedTables.map((table) => [
                table.relation,
                table.columns.map((column) => ({ name: column.name, type: column.type ?? '' })),
              ])),
            }
          : connection
            ? await introspectSchema(executor, connection, {
                limit: schemaLimit,
                offset: schemaOffset,
                search: schemaSearch,
              })
            : { tables: [], columnsByPath: new Map<string, Array<{ name: string; type: string }>>() };
        const dbTables = tables.map((t) => ({
          name: t.path,
          path: t.path,
          columns: columnsByPath.get(t.path) ?? [],
          source: 'database',
          objectType: t.type,
        }));
        const seen = new Set([
          ...dataFiles.map((f) => f.name),
          ...notebookDatasets.map((dataset) => dataset.name),
        ]);
        const merged = [
          ...notebookDatasets,
          ...dataFiles.map((f) => ({ ...f, source: "file" })),
          ...dbTables.filter((t) => !seen.has(t.name)),
        ];
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(merged));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.warn(`[dql] /api/schema introspection failed: ${message}`);
        const fallback = [
          ...datasetWorkspace.list().map((dataset) => ({
            name: dataset.alias,
            path: dataset.sourcePath,
            columns: dataset.profile.columns.map((column) => ({
              name: column.name,
              type: column.type,
            })),
            source: "file",
            objectType:
              dataset.storageMode === "staged" ? "staged_dataset" : "dataset",
            datasetId: dataset.id,
            fileFingerprint: dataset.fileFingerprint,
            storageMode: dataset.storageMode,
            refreshedAt: dataset.refreshedAt,
            trustState: dataset.trustState,
          })),
          ...scanDataFiles(projectRoot).map((f) => ({ ...f, source: "file" })),
        ];
        res.writeHead(200, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(serializeJSON(fallback));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/blocks') {
      try {
        const body = await readJSON(req);
        const {
          name,
          domain,
          content,
          description,
          tags,
          folderPath,
          metricRefs,
          template,
          blockType,
          visibility,
        } = body as {
          name: string;
          domain?: string;
          content?: string;
          description?: string;
          tags?: string[];
          folderPath?: string;
          metricRefs?: string[];
          template?: string;
          blockType?: 'custom' | 'semantic';
          visibility?: 'private' | 'shared';
        };
        if (!name || typeof name !== 'string') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing block name' }));
          return;
        }
        if (dbtFirstOwnsSemanticAuthoring(projectConfig)
          && (blockType === 'semantic' || /\btype\s*=\s*["']semantic["']/i.test(content ?? ''))) {
          sendDbtOwnedSemanticAuthoringError(res);
          return;
        }
        const created = createBlockArtifacts(projectRoot, {
          name,
          domain,
          content,
          description,
          tags,
          folderPath,
          metricRefs,
          template,
          blockType,
          visibility,
        });
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ...created, visibility: visibility === 'private' ? 'private' : 'shared' }));
      } catch (error) {
        if (error instanceof Error && error.message === 'BLOCK_EXISTS') {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block already exists' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/blocks/save-from-cell') {
      try {
        const body = await readJSON(req);
        const {
          name,
          domain,
          owner,
          content,
          description,
          tags,
          metricRefs,
          template,
          llmContext,
          examples,
          invariants,
          reviewRequired,
          datasetRefs,
          lineage,
        } = body as {
          name: string;
          domain?: string;
          owner?: string;
          content: string;
          description?: string;
          tags?: string[];
          metricRefs?: string[];
          template?: string;
          llmContext?: string;
          examples?: Array<{ question: string; sql?: string }>;
          invariants?: string[];
          reviewRequired?: boolean;
          datasetRefs?: Array<{
            id?: string;
            alias?: string;
            role?: string;
            fingerprint?: string;
          }>;
          lineage?: Record<string, unknown>;
        };
        if (!name || typeof name !== 'string' || !content || typeof content !== 'string') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'name and content are required' }));
          return;
        }
        if (dbtFirstOwnsSemanticAuthoring(projectConfig) && /\btype\s*=\s*["']semantic["']/i.test(content)) {
          sendDbtOwnedSemanticAuthoringError(res);
          return;
        }
        // OSS keeps the save flow deliberately small: the person saving the
        // reusable answer is accountable for it. Domain/description/tags are
        // helpful defaults, but not reasons to send a single-user back to a
        // review queue.
        const missing: string[] = [];
        if (!owner || !owner.trim()) missing.push('owner');
        if (missing.length > 0) {
          res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            error: `Block is missing required governance fields: ${missing.join(', ')}`,
            missing,
          }));
          return;
        }
        const created = createBlockArtifacts(projectRoot, {
          name,
          domain,
          owner,
          content,
          description,
          tags,
          metricRefs,
          template,
          llmContext,
          examples,
          invariants,
          gitMetadata: readGitMetadata(projectRoot),
        });
        // Save first, then certify against the same local runtime used for the
        // answer. Passing blocks become certified immediately; anything that
        // cannot prove itself remains a clearly labelled draft at this path.
        setBlockStudioStatus(projectRoot, created.path, "draft");
        let source = readFileSync(join(projectRoot, created.path), "utf-8");
        let status: "certified" | "draft" = "draft";
        let blockers: string[] = reviewRequired
          ? [
              "Imported or staged datasets require review and reproducibility checks before certification.",
            ]
          : [];
        let certification:
          | { certified: boolean; errors: unknown[]; warnings: unknown[] }
          | undefined;
        try {
          if (reviewRequired) throw new Error(blockers[0]);
          const verdict = await certifyBlockStudioSource(source, created.path);
          blockers = Array.from(new Set(verdict.checklist.blockers));
          certification = {
            certified: verdict.certification.certified && blockers.length === 0,
            errors: verdict.certification.errors,
            warnings: verdict.certification.warnings,
          };
          if (certification.certified) {
            setBlockStudioStatus(projectRoot, created.path, 'certified');
            status = 'certified';
            source = readFileSync(join(projectRoot, created.path), 'utf-8');
          }
        } catch (error) {
          blockers = Array.from(
            new Set([
              ...blockers,
              error instanceof Error ? error.message : String(error),
            ]),
          );
        }
        await refreshLocalMetadataCatalog(projectRoot);
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ...created, content: source, status, blockers, certification }));
      } catch (error) {
        if (error instanceof Error && error.message === 'BLOCK_EXISTS') {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block already exists' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // POST /api/blocks/publish — move a private block into tracked source.
    // Two files travel together: the block and its companion YAML. A block
    // published without its companion would lose its semantic bindings, so a
    // failed companion move puts the block back where it was.
    if (req.method === 'POST' && path === '/api/blocks/publish') {
      try {
        const body = await readJSON(req) as { path?: unknown };
        const requested = typeof body.path === 'string' ? normalizeNotebookPath(body.path.trim()) : '';
        if (!requested) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Missing block path.' }));
          return;
        }
        if (!isPrivateBlockPath(requested) || !requested.endsWith('.dql') || requested.includes('..')) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Only a private block can be published.' }));
          return;
        }
        const sourceAbs = resolve(projectRoot, requested);
        const rootPrefix = `${resolve(projectRoot)}${sep}`;
        if (!sourceAbs.startsWith(rootPrefix) || !existsSync(sourceAbs)) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'Private block not found.' }));
          return;
        }
        const source = readFileSync(sourceAbs, 'utf-8');
        const rawDomain = (/^\s*domain\s*=\s*"([^"]+)"/m.exec(source)?.[1] ?? '').trim();
        const safeDomain = (rawDomain === 'uncategorized' ? '' : rawDomain)
          .toLowerCase()
          .replace(/[^a-z0-9._/-]+/g, '-')
          .replace(/^\/+|\/+$/g, '');
        const inside = requested.slice(`${PRIVATE_BLOCK_PREFIX}/`.length);
        const segments = inside.split('/').filter(Boolean);
        const slug = (segments.at(-1) as string).replace(/\.dql$/, '');
        const folder = segments.slice(0, -1).join('/');
        const target = resolveBlockWriteTarget(projectRoot, safeDomain, folder, slug, 'shared');
        if (existsSync(target.absPath)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            ok: false,
            error: `${target.relativePath} already exists. Rename the private block before publishing it.`,
          }));
          return;
        }
        const companionFrom = blockCompanionRelativePath(projectRoot, requested);
        const companionTo = blockCompanionRelativePath(projectRoot, target.relativePath);
        mkdirSync(dirname(target.absPath), { recursive: true });
        renameSync(sourceAbs, target.absPath);
        try {
          if (companionFrom && companionTo && existsSync(join(projectRoot, companionFrom))) {
            const companionAbs = join(projectRoot, companionTo);
            mkdirSync(dirname(companionAbs), { recursive: true });
            renameSync(join(projectRoot, companionFrom), companionAbs);
          }
        } catch (error) {
          // Put the block back rather than leave it published without bindings.
          renameSync(target.absPath, sourceAbs);
          throw error;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          path: target.relativePath,
          previousPath: requested,
          companionPath: companionTo,
          visibility: 'shared',
        }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: error.message, code: 'unauthorized' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/blocks/templates') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ templates: listBlockTemplates() }));
      return;
    }

    // ── Block library (list all blocks with metadata) ────────────────────
    if (req.method === 'GET' && path === '/api/blocks/library') {
      try {
        const blocks: Array<{
          name: string; domain: string; status: string;
          owner: string | null; tags: string[]; path: string;
          lastModified: string; description: string;
          llmContext: string | null;
          visibility: 'private' | 'shared';
        }> = [];
        const seen = new Set<string>();
        const scanDir = (dir: string) => {
          if (!existsSync(dir)) return;
          for (const entry of readdirSync(dir, { withFileTypes: true })) {
            const filePath = join(dir, entry.name);
            if (entry.isDirectory()) {
              scanDir(filePath);
            } else if (entry.name.endsWith('.dql') && !seen.has(filePath)) {
              seen.add(filePath);
              const relPath = relative(projectRoot, filePath).replaceAll('\\', '/');
              try {
                const source = readFileSync(filePath, 'utf-8');
                const stat = statSync(filePath);
                // Quick parse for key block fields. Each field is matched at the
                // start of its own line, so `review_status = ...` or a word inside
                // a description never stands in for the block's status or domain.
                const nameMatch = /^\s*block\s+"([^"]+)"/m.exec(source);
                // `domains/**/domain.dql` is a business-boundary declaration,
                // not a reusable block. Only a real block declaration belongs
                // in the Blocks library.
                if (!nameMatch) continue;
                const domainMatch = /^\s*domain\s*=\s*"([^"]+)"/m.exec(source);
                const statusMatch = /^\s*status\s*=\s*"([^"]+)"/m.exec(source);
                const ownerMatch = /^\s*owner\s*=\s*"([^"]+)"/m.exec(source);
                const descMatch = /^\s*description\s*=\s*"([^"]+)"/m.exec(source);
                const tagsMatch = /^\s*tags\s*=\s*\[([^\]]*)\]/m.exec(source);
                const parsedTags = tagsMatch
                  ? tagsMatch[1].split(',').map((tag) => tag.trim().replace(/^"|"$/g, '')).filter(Boolean)
                  : [];
                const llmMatch = /^\s*llmContext\s*=\s*"((?:[^"\\]|\\.)*)"/m.exec(source);
                blocks.push({
                  name: nameMatch?.[1] ?? entry.name.replace('.dql', ''),
                  domain: (domainMatch?.[1] ?? inferBlockStudioPathDomain(projectRoot, relPath)) || 'uncategorized',
                  status: statusMatch?.[1] ?? 'draft',
                  owner: ownerMatch?.[1] ?? null,
                  tags: parsedTags,
                  path: relPath,
                  lastModified: stat.mtime.toISOString(),
                  description: descMatch?.[1] ?? '',
                  llmContext: llmMatch?.[1] ?? null,
                  visibility: isPrivateBlockPath(relPath) ? 'private' : 'shared',
                });
              } catch { /* skip unreadable files */ }
            }
          }
        };
        scanDir(join(projectRoot, 'blocks'));
        scanDir(join(projectRoot, 'domains'));
        // Private blocks are listed like any other: hiding them would lose the
        // author's work behind a folder they never open.
        scanDir(privateBlockDir(projectRoot));
        blocks.sort((a, b) => new Date(b.lastModified).getTime() - new Date(a.lastModified).getTime());
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ blocks }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: error.message, code: 'unauthorized' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Apps (App artifact listing for notebook AppsPanel) ────────────────
    if (req.method === 'GET' && path === '/api/apps') {
      try {
        const appsRoot = join(projectRoot, 'apps');
        type AppManifest = {
          name: string;
          domain: string;
          owner?: string;
          description?: string;
          cadence?: string;
          consumers?: string[];
          entryPoints?: string[];
        };
        type DiscoveredApp = {
          path: string;
          manifest: AppManifest;
          notebooks: string[];
          dashboards: string[];
          hasDigest: boolean;
        };
        const apps: DiscoveredApp[] = [];
        const listFilesByExt = (dir: string, ext: string): string[] => {
          const out: string[] = [];
          try {
            for (const entry of readdirSync(dir, { withFileTypes: true })) {
              const full = join(dir, entry.name);
              if (entry.isDirectory()) {
                out.push(...listFilesByExt(full, ext).map((n) => `${entry.name}/${n}`));
              } else if (entry.isFile() && entry.name.endsWith(ext)) {
                out.push(entry.name);
              }
            }
          } catch { /* dir missing; return [] */ }
          return out;
        };
        if (existsSync(appsRoot)) {
          for (const entry of readdirSync(appsRoot, { withFileTypes: true })) {
            if (!entry.isDirectory() || !entry.name.endsWith('.dql-app')) continue;
            const appDir = join(appsRoot, entry.name);
            try {
              const raw = readFileSync(join(appDir, 'app.yml'), 'utf-8');
              const manifest = loadYaml(raw) as AppManifest | null;
              if (!manifest || !manifest.name || !manifest.domain) continue;
              apps.push({
                path: relative(projectRoot, appDir),
                manifest,
                notebooks: listFilesByExt(join(appDir, 'notebooks'), '.dqlnb'),
                dashboards: listFilesByExt(join(appDir, 'dashboards'), '.dql'),
                hasDigest: existsSync(join(appDir, 'digest.dql')),
              });
            } catch { /* skip unreadable apps */ }
          }
        }
        apps.sort((a, b) => a.manifest.name.localeCompare(b.manifest.name));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ apps }));
      } catch (error) {
        const status = error instanceof DQLAccessDeniedError ? 403 : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          error: error instanceof Error ? error.message : String(error),
          ...(status === 403 ? { code: 'unauthorized' } : {}),
        }));
      }
      return;
    }

    // ── Block status update ──────────────────────────────────────────────
    if (req.method === 'POST' && path === '/api/blocks/status') {
      try {
        const body = await readJSON(req);
        const blockPath = body.path as string;
        const newStatus = body.newStatus as string;
        const validStatuses = ['draft', 'review', 'certified', 'deprecated'];
        if (!validStatuses.includes(newStatus)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Status must be one of: ${validStatuses.join(', ')}` }));
          return;
        }
        if (newStatus === 'certified') {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Use /api/block-studio/certify so validation, run, and tests gate certification.' }));
          return;
        }
        setBlockStudioStatus(projectRoot, blockPath, newStatus);
        await refreshLocalMetadataCatalog(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, status: newStatus }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Block version history (git log) ──────────────────────────────────
    if (req.method === 'GET' && path === '/api/blocks/history') {
      // `{ entries, status: 'ok' | 'not_a_repo' | 'git_unavailable' | 'error', message? }`.
      // git runs with an argument array (no shell) and the path must stay inside the project.
      try {
        const history = await readBlockHistory(projectRoot, url.searchParams.get('path'));
        res.writeHead(history.httpStatus, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(history.body));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ entries: [], status: 'error', message: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Block body (re-read from disk, used by bound-cell refresh) ──────
    if (req.method === 'GET' && path === '/api/blocks/body') {
      try {
        const blockPath = url.searchParams.get('path');
        if (!blockPath) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'path parameter is required' }));
          return;
        }
        const absolutePath = resolve(projectRoot, blockPath);
        if (!absolutePath.startsWith(projectRoot + '/') && absolutePath !== projectRoot) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'path escapes project root' }));
          return;
        }
        if (!existsSync(absolutePath)) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'block not found' }));
          return;
        }
        const body = readFileSync(absolutePath, 'utf-8');
        let commitSha: string | null = null;
        try {
          // Arguments, never a shell string: the path comes from the request.
          const logged = await execGit(projectRoot, ['--literal-pathspecs', 'log', '-1', '--format=%H', '--', relative(projectRoot, absolutePath)], { timeoutMs: 5000 });
          const sha = logged.code === 0 ? logged.stdout.trim() : '';
          commitSha = sha.length > 0 ? sha : null;
        } catch {
          commitSha = null;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ path: blockPath, body, commitSha }));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: message }));
      }
      return;
    }

    // ── Distinct values for a block column → app/dashboard filter dropdowns ──
    if (req.method === 'GET' && path === '/api/dashboard/filter-options') {
      try {
        const blockIdParam = url.searchParams.get('block');
        const blockPath = url.searchParams.get('path')
          ?? (blockIdParam ? resolveBlockPathById(projectRoot, blockIdParam) : null);
        const column = (url.searchParams.get('column') ?? '').trim();
        const limit = Math.min(Math.max(Number(url.searchParams.get('limit') ?? 50) || 50, 1), 200);
        if (!blockPath || !column || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(column)) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'path and a valid column are required' }));
          return;
        }
        const absolutePath = resolve(projectRoot, blockPath);
        if (!absolutePath.startsWith(projectRoot + '/') && absolutePath !== projectRoot) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'path escapes project root' }));
          return;
        }
        if (!existsSync(absolutePath)) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'block not found' }));
          return;
        }
        const source = readFileSync(absolutePath, 'utf-8');
        // Only expose distinct values for a DECLARED output column — keeps the probe
        // inside the governed block contract (no arbitrary column scanning).
        const parsedMeta = parseBlockSourceMetadata(source);
        const validation = validateBlockStudioSource(source, semanticLayer);
        const parameterNames = new Set((validation.parameters ?? []).map((parameter) => parameter.name));
        if (parameterNames.has(column) || (parsedMeta.outputs.length > 0 && !parsedMeta.outputs.includes(column))) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `"${column}" is not a declared output of this block` }));
          return;
        }
        const activeConnection = requireActiveConnection();
        const tableMapping = await resolveSemanticTableMapping(executor, activeConnection, semanticLayer, projectRoot);
        const semanticCompose = semanticLayer
          ? await composeSemanticBlockSqlForRuntime(source, semanticLayer, {
              driver: activeConnection.driver,
              tableMapping,
              projectRoot,
              projectConfig,
              detectedProvider: semanticDetectedProvider,
            })
          : null;
        const baseSql = semanticCompose?.sql ?? validation.executableSql;
        if (!baseSql) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'block has no executable SQL' }));
          return;
        }
        const prepared = prepareLocalExecution(baseSql, activeConnection, projectRoot, projectConfig);
        const q = quoteAgentIdentifier(column, prepared.connection);
        const wrapped = `SELECT DISTINCT ${q} AS value FROM (${stripSqlTerminator(prepared.sql)}) _dql_opt WHERE ${q} IS NOT NULL ORDER BY 1 LIMIT ${limit + 1}`;
        const result = await executor.executeQuery(wrapped, [], runtimeVariables({}), prepared.connection);
        const rows = Array.isArray(result?.rows) ? result.rows : [];
        const truncated = rows.length > limit;
        const options = rows
          .slice(0, limit)
          .map((row: any) => row?.value)
          .filter((value: any) => value !== null && value !== undefined)
          .map((value: any) => String(value));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ column, options, truncated }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Plan an app from a goal (P1: plan → critique → show gaps) ──────────
    // The agent decomposes the goal into the questions an app should answer
    // (KPI + trend + breakdowns), matches each to a CERTIFIED block, derives the
    // shared filters that refresh every tile, and reports coverage + gaps BEFORE
    // anything is built — so the human reviews the plan, not a blank canvas.
    if (req.method === 'POST' && path === '/api/app-plan') {
      try {
        const body = await readJSON(req);
        const goal = typeof body.goal === 'string' ? body.goal.trim() : '';
        if (!goal) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'goal is required' }));
          return;
        }
        const snapshot = projectSnapshot();
        const kgPath = defaultKgPath(projectRoot);
        await reindexProject(projectRoot, { kgPath, manifest: snapshot.manifest });
        const kg = new KGStore(kgPath);
        let plan;
        try {
          plan = planAppFromPrompt({
            prompt: goal,
            kg,
            domain: typeof body.domain === 'string' ? body.domain : undefined,
            audience: typeof body.audience === 'string' ? body.audience : undefined,
            mode: body.mode === 'personal' ? 'personal' : 'stakeholder',
            snapshotId: snapshot.snapshotId,
          });
        } finally {
          kg.close();
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ plan, snapshotId: snapshot.snapshotId }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Research / follow-up planning (P4: ReAct over the catalog) ─────────
    // Decide whether to answer, research across grounded steps, or ask a smart
    // follow-up — so the agent behaves like a real assistant instead of always
    // generating one query. Every step + option is bound to a real metric/block.
    if (req.method === 'POST' && path === '/api/research-plan') {
      try {
        const body = await readJSON(req);
        const question = typeof body.question === 'string' ? body.question.trim() : '';
        if (!question) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'question is required' }));
          return;
        }
        const metrics = loadSemanticMetrics(projectRoot);
        let blocks = collectPlanBlocks(projectRoot, { certifiedOnly: true });
        if (blocks.length === 0) blocks = collectPlanBlocks(projectRoot, { certifiedOnly: false });
        const plan = await planResearch({
          question,
          metrics,
          blocks,
          intent: typeof body.intent === 'string'
            ? (body.intent as Parameters<typeof planResearch>[0]['intent'])
            : undefined,
          isFollowUp: body.isFollowUp === true,
          history: Array.isArray(body.history) ? body.history : undefined,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ plan, blockCount: blocks.length, metricCount: metrics.length }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Run block tests ────────────────────────────────────────────────
    if (req.method === 'POST' && path === '/api/blocks/run-tests') {
      try {
        const body = await readJSON(req);
        const source = body.source as string;
        if (!source) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'source is required' }));
          return;
        }
        const summary = await runBlockStudioTestSummary(source);
        const results = summary.assertions.map((assertion) => ({
          name: assertion.name,
          field: assertion.name.match(/^assert\s+(\S+)/)?.[1] ?? assertion.name,
          operator: assertion.name.match(/^assert\s+\S+\s+(\S+)/)?.[1] ?? '',
          expected: assertion.expected !== undefined ? String(assertion.expected) : assertion.name.replace(/^assert\s+\S+\s+\S+\s*/, ''),
          passed: assertion.passed,
          actual: assertion.error ?? (assertion.actual !== undefined ? String(assertion.actual) : undefined),
        }));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ assertions: results, passed: summary.passed, failed: summary.failed, duration: summary.duration }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/certifications') {
      try {
        const body = await readJSON(req);
        const source = typeof body.source === 'string' ? body.source : '';
        const suppliedMetadata = body.metadata && typeof body.metadata === 'object'
          ? body.metadata as Record<string, unknown>
          : {};
        const currentPath = typeof body.path === 'string'
          ? normalize(body.path).replace(/^\/+/, '').replaceAll('\\', '/')
          : undefined;
        const expectedSourceFingerprint = typeof body.expectedSourceFingerprint === 'string'
          ? body.expectedSourceFingerprint
          : undefined;
        const idempotencyKey = typeof req.headers['idempotency-key'] === 'string'
          ? req.headers['idempotency-key'].trim()
          : '';

        if (!source.trim()) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'source is required' }));
          return;
        }
        if (idempotencyKey) {
          const existingId = operationIdempotency.get(idempotencyKey);
          const existing = existingId ? operationCoordinator.get(existingId) : null;
          if (existing) {
            // The repeated request gets the same draft identity the first one did.
            const scopedPath = existing.scope.startsWith('block:') ? existing.scope.slice('block:'.length) : undefined;
            const scopedAbsolute = scopedPath ? safeJoin(projectRoot, scopedPath) : undefined;
            const draft = scopedPath && scopedAbsolute && existsSync(scopedAbsolute)
              ? openBlockStudioDocument(projectRoot, scopedPath, semanticLayer)
              : undefined;
            res.writeHead(202, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ operation: existing, deduplicated: true, ...(draft ? { draft } : {}) }));
            return;
          }
        }
        if (currentPath && expectedSourceFingerprint) {
          const absoluteCurrentPath = safeJoin(projectRoot, currentPath);
          if (!absoluteCurrentPath || !existsSync(absoluteCurrentPath)) {
            res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ error: 'The block changed or moved. Reopen it before certifying.', code: 'SOURCE_CHANGED' }));
            return;
          }
          const actualFingerprint = createHash('sha256')
            .update(readFileSync(absoluteCurrentPath, 'utf-8'))
            .digest('hex');
          if (actualFingerprint !== expectedSourceFingerprint) {
            res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ error: 'The block changed after it was opened. Reopen it before certifying.', code: 'SOURCE_CHANGED' }));
            return;
          }
        }

        const draftSource = markBlockStudioSourceReusable(setBlockStudioStatusInSource(source, 'draft'));
        const parsed = parseBlockSourceMetadata(draftSource);
        const name = typeof suppliedMetadata.name === 'string' && suppliedMetadata.name.trim()
          ? suppliedMetadata.name.trim()
          : parsed.name;
        if (!name) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block name is required.' }));
          return;
        }
        const existingCanonical = Boolean(currentPath && !isDraftBlockPath(currentPath));
        // A certified block stays certified on disk until a new certification
        // passes. Re-certifying the unchanged source checks it in place; edited
        // source is checked as a separate draft beside it. Writing the draft over
        // the certified file first demoted it whenever a gate failed.
        const canonicalAbsolute = existingCanonical ? safeJoin(projectRoot, currentPath!) : undefined;
        const canonicalOnDisk = canonicalAbsolute && existsSync(canonicalAbsolute) ? readFileSync(canonicalAbsolute, 'utf-8') : undefined;
        const canonicalCertified = canonicalOnDisk !== undefined && /^\s*status\s*=\s*"certified"/m.test(canonicalOnDisk);
        const unchangedCertified = canonicalCertified
          && markBlockStudioSourceReusable(setBlockStudioStatusInSource(canonicalOnDisk!, 'draft')).trim() === draftSource.trim();
        const existingCanonicalDraft = existingCanonical && !canonicalCertified;
        const stableSuffix = createHash('sha256')
          .update(currentPath ?? `${name}:${draftSource}`)
          .digest('hex')
          .slice(0, 16);
        const draftSaveOptions = {
          source: draftSource,
          name,
          domain: typeof suppliedMetadata.domain === 'string' ? suppliedMetadata.domain : parsed.domain,
          description: typeof suppliedMetadata.description === 'string' ? suppliedMetadata.description : parsed.description,
          owner: typeof suppliedMetadata.owner === 'string' ? suppliedMetadata.owner : parsed.owner,
          tags: Array.from(new Set([
            ...(Array.isArray(suppliedMetadata.tags) ? suppliedMetadata.tags.map(String) : parsed.tags),
            APP_SOURCE_REUSABLE_TAG,
          ])),
          lineage: Array.isArray(suppliedMetadata.lineage) ? suppliedMetadata.lineage.map(String) : undefined,
        };
        // A saved draft already has a durable identity, even when it lives in
        // the canonical domain blocks directory. Reuse that identity for the
        // certification attempt. Creating a second `_drafts` artifact here
        // made a failed gate duplicate the block in the library.
        const draftPath = unchangedCertified
          ? currentPath!
          : existingCanonicalDraft
            ? saveBlockStudioArtifacts(projectRoot, {
                currentPath: currentPath!,
                ...draftSaveOptions,
              })
            : saveBlockStudioDraftArtifacts(projectRoot, {
                currentPath: currentPath && isDraftBlockPath(currentPath)
                  ? currentPath
                  : canonicalCertified ? draftBesideCanonical(projectRoot, currentPath!).existingPath : undefined,
                ...draftSaveOptions,
                stableSuffix,
              });
        const canonicalPath = existingCanonicalDraft ? draftPath : canonicalCertified ? currentPath! : undefined;
        const operation = operationCoordinator.create({
          type: 'block_certification',
          scope: `block:${draftPath}`,
          resourceRevision: typeof body.clientRevision === 'string'
            ? body.clientRevision
            : createHash('sha256').update(draftSource).digest('hex'),
          message: `Certification queued for ${name}.`,
          cancellable: true,
        });
        if (idempotencyKey) {
          operationIdempotency.set(idempotencyKey, operation.id);
          while (operationIdempotency.size > 100) {
            const oldest = operationIdempotency.keys().next().value;
            if (typeof oldest !== 'string') break;
            operationIdempotency.delete(oldest);
          }
        }

        operationCoordinator.run(operation.id, async (signal, report) => {
          const result = await certifyBlockStudioSource(draftSource, draftPath, {
            enterprise: body.enterprise === true,
            reportProgress: (progress) => {
              if (signal.aborted) throw Object.assign(new Error('Certification cancelled.'), { code: 'OPERATION_CANCELLED' });
              report(progress);
            },
          });
          const blockers = Array.from(new Set(result.checklist.blockers));
          if (signal.aborted) throw Object.assign(new Error('Certification cancelled.'), { code: 'OPERATION_CANCELLED' });
          if (!result.certification.certified || blockers.length > 0) {
            if (result.preview && !unchangedCertified) writeBlockStudioRunSummary(projectRoot, draftPath, draftSource, result.preview.result);
            const openedDraft = openBlockStudioDocument(projectRoot, draftPath, semanticLayer);
            return {
              // Nothing was written for an unchanged certified block: it is still certified.
              outcome: unchangedCertified ? 'certified_unchanged_with_blockers' : 'draft_saved_with_blockers',
              oldPath: currentPath ?? draftPath,
              draftPath,
              blockers,
              checklist: result.checklist,
              runSummary: result.preview ? {
                rowCount: result.preview.result.rowCount ?? result.preview.result.rows.length,
                executionTime: result.preview.result.executionTime,
                columns: result.preview.result.columns,
                ranAt: new Date().toISOString(),
              } : undefined,
              block: { ...openedDraft, validation: result.validation },
            };
          }

          report({ phase: 'publishing', progress: 82, message: 'Publishing the certified block.' });
          const certifiedSource = setBlockStudioStatusInSource(draftSource, 'certified');
          const certifiedMetadata = parseBlockSourceMetadata(certifiedSource);
          const savedPath = saveBlockStudioArtifacts(projectRoot, {
            currentPath: canonicalPath ?? draftPath,
            source: certifiedSource,
            name: certifiedMetadata.name || name,
            domain: certifiedMetadata.domain,
            description: certifiedMetadata.description,
            owner: certifiedMetadata.owner,
            tags: certifiedMetadata.tags,
          });
          if (canonicalPath && draftPath !== savedPath) {
            try { deleteBlockStudioArtifacts(projectRoot, draftPath); } catch { /* certified source is already durable */ }
          }

          // Shared learning remains the same deterministic, advisory write used
          // by the synchronous compatibility route. It never gates publication.
          try {
            const learnedOutputs = Array.isArray(certifiedMetadata.outputs)
              ? certifiedMetadata.outputs.filter((output): output is string => typeof output === 'string')
              : [];
            if (certifiedMetadata.name) {
              const memory = new MemoryStore(defaultMemoryPath(projectRoot));
              memory.upsert({
                id: `mem_certify_${certifiedMetadata.name}`,
                scope: 'project',
                title: `Certified block: ${certifiedMetadata.name}`,
                content: `Prefer the certified block "${certifiedMetadata.name}" for ${certifiedMetadata.description?.trim() || `questions in the ${certifiedMetadata.domain ?? 'analytics'} domain`}.${certifiedMetadata.grain ? ` Grain: ${certifiedMetadata.grain}.` : ''}${learnedOutputs.length ? ` Outputs: ${learnedOutputs.slice(0, 8).join(', ')}.` : ''} It is the trusted source — reuse it instead of generating new SQL.`,
                tags: [certifiedMetadata.domain, certifiedMetadata.name, ...learnedOutputs.slice(0, 4)].filter((value): value is string => Boolean(value)),
                source: 'certify',
                confidence: 0.95,
                importance: 0.85,
                enabled: true,
              });
            }
          } catch {
            /* best-effort: learning capture must never block certification */
          }
          report({ phase: 'indexing', progress: 92, message: 'Queueing the certified source index refresh.' });
          const refreshOperation = scheduleProjectRefresh('block-studio-certification');
          report({ phase: 'indexing', progress: 96, message: 'Certified source saved; index refresh queued.' });
          if (result.preview) writeBlockStudioRunSummary(projectRoot, savedPath, certifiedSource, result.preview.result);
          const openedCertified = openBlockStudioDocument(projectRoot, savedPath, semanticLayer);
          return {
            outcome: 'certified',
            oldPath: currentPath ?? draftPath,
            draftPath,
            newPath: savedPath,
            block: { ...openedCertified, validation: result.validation },
            checklist: result.checklist,
            runSummary: result.preview ? {
              rowCount: result.preview.result.rowCount ?? result.preview.result.rows.length,
              executionTime: result.preview.result.executionTime,
              columns: result.preview.result.columns,
              ranAt: new Date().toISOString(),
            } : undefined,
            indexRefresh: { status: 'queued', operationId: refreshOperation.id },
          };
        });

        res.writeHead(202, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          operation: operationCoordinator.get(operation.id) ?? operation,
          draft: openBlockStudioDocument(projectRoot, draftPath, semanticLayer),
        }));
      } catch (error) {
        const code = apiErrorCode(error, 'CERTIFICATION_REQUEST_FAILED');
        const status = code === 'SOURCE_CHANGED' || apiErrorMessage(error) === 'BLOCK_EXISTS' ? 409 : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: apiErrorMessage(error), code }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/certification-check') {
      try {
        const body = await readJSON(req);
        const source = typeof body.source === 'string' ? body.source : '';
        if (!source.trim()) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'source is required' }));
          return;
        }
        // Read-only certification assessment for repair/review workflows. It
        // deliberately does not write source, receipts, learning, or indexes.
        const result = await certifyBlockStudioSource(source, null, { enterprise: body.enterprise === true });
        const blockers = Array.from(new Set(result.checklist.blockers));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: result.certification.certified && blockers.length === 0,
          ...result,
          blockers,
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/certify') {
      try {
        const body = await readJSON(req);
        const source = typeof body.source === 'string' ? body.source : '';
        const blockPath = typeof body.path === 'string' ? body.path : null;
        if (!source.trim()) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'source is required' }));
          return;
        }
        // OSS local-first certifies in non-enterprise mode: owner + passing tests +
        // a successful run are the gate; grain/outputs/pattern/lineage/cadence are
        // AI-filled advisory warnings, not hard blockers. Enterprise-grade certification
        // (all of those required) is an opt-in for the cloud tier — request it explicitly.
        const result = await certifyBlockStudioSource(source, blockPath, { enterprise: body.enterprise === true });
        const blockers = Array.from(new Set(result.checklist.blockers));
        if (!result.certification.certified || blockers.length > 0) {
          if (blockPath && result.preview) writeBlockStudioRunSummary(projectRoot, blockPath, source, result.preview.result);
          res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, ...result, blockers }));
          return;
        }
        let certifiedPayload: ReturnType<typeof openBlockStudioDocument> | null = null;
        const certifiedSource = setBlockStudioStatusInSource(source, 'certified');
        if (blockPath) {
          const normalizedBlockPath = normalize(blockPath).replace(/^\/+/, '');
          const parsed = parseBlockSourceMetadata(certifiedSource);
          if (isDraftBlockPath(normalizedBlockPath)) {
            const savedPath = saveBlockStudioArtifacts(projectRoot, {
              currentPath: normalizedBlockPath,
              source: certifiedSource,
              name: parsed.name,
              domain: parsed.domain,
              description: parsed.description,
              owner: parsed.owner,
              tags: parsed.tags,
            });
            if (result.preview) writeBlockStudioRunSummary(projectRoot, savedPath, certifiedSource, result.preview.result);
            certifiedPayload = openBlockStudioDocument(projectRoot, savedPath, semanticLayer);
          } else {
            setBlockStudioStatus(projectRoot, normalizedBlockPath, 'certified');
            if (result.preview) writeBlockStudioRunSummary(projectRoot, normalizedBlockPath, certifiedSource, result.preview.result);
            certifiedPayload = openBlockStudioDocument(projectRoot, normalizedBlockPath, semanticLayer);
          }
        }
        // Auto-capture (OSS local learning loop): certifying a block teaches the
        // agent to prefer it. Write a scoped, advisory project memory — deterministic,
        // best-effort, and it never blocks certification.
        try {
          const learned = parseBlockSourceMetadata(certifiedSource);
          if (learned.name) {
            const learnedOutputs = Array.isArray(learned.outputs)
              ? learned.outputs.filter((o): o is string => typeof o === 'string')
              : [];
            const memory = new MemoryStore(defaultMemoryPath(projectRoot));
            memory.upsert({
              id: `mem_certify_${learned.name}`,
              scope: 'project',
              title: `Certified block: ${learned.name}`,
              content: `Prefer the certified block "${learned.name}" for ${learned.description?.trim() || `questions in the ${learned.domain ?? 'analytics'} domain`}.${learned.grain ? ` Grain: ${learned.grain}.` : ''}${learnedOutputs.length ? ` Outputs: ${learnedOutputs.slice(0, 8).join(', ')}.` : ''} It is the trusted source — reuse it instead of generating new SQL.`,
              tags: [learned.domain, learned.name, ...learnedOutputs.slice(0, 4)].filter((x): x is string => Boolean(x)),
              source: 'certify',
              confidence: 0.95,
              importance: 0.85,
              enabled: true,
            });
          }
        } catch {
          /* best-effort: learning capture must never block certification */
        }
        const refreshOperation = scheduleProjectRefresh('block-studio-certify');
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          status: 'certified',
          ...result,
          path: certifiedPayload?.path ?? blockPath ?? null,
          source: certifiedPayload?.source ?? certifiedSource,
          metadata: certifiedPayload?.metadata,
          companionPath: certifiedPayload?.companionPath ?? null,
          validation: result.validation,
          lineageRefresh: { status: 'queued', operationId: refreshOperation.id },
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/ai-imports') {
      try {
        const body = await readJSON(req);
        const session = await createDqlGenerationSessionFromBody(body);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(session));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/match-sql') {
      try {
        const body = await readJSON(req);
        if (typeof body.sql !== 'string' || body.sql.trim().length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing SQL in request body.' }));
          return;
        }
        const sql = body.sql.trim();
        const match = await matchSqlForDqlReuse({
          sql,
          sourcePath: typeof body.sourcePath === 'string' ? body.sourcePath : 'pasted.sql',
          name: typeof body.name === 'string' ? body.name : 'SQL match preview',
          domain: typeof body.domain === 'string' ? body.domain : 'imported',
          owner: typeof body.owner === 'string' ? body.owner : 'analytics',
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(match));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const aiImportSaveSelectedMatch = path.match(/^\/api\/block-studio\/ai-imports\/([^/]+)\/save-selected$/);
    if (req.method === 'POST' && aiImportSaveSelectedMatch) {
      const importId = decodeURIComponent(aiImportSaveSelectedMatch[1]);
      try {
        const body = await readJSON(req);
        const candidateIds: string[] = Array.from(new Set<string>(
          Array.isArray(body.candidateIds) ? body.candidateIds.map((value: unknown) => String(value)) : [],
        ));
        const owner = typeof body.owner === 'string' ? body.owner.trim() : '';
        if (candidateIds.length === 0 || !owner) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Select at least one candidate and provide an owner.' }));
          return;
        }

        const results: Array<{
          candidateId: string;
          path?: string;
          status: 'certified' | 'draft' | 'error';
          blockers: string[];
          candidate?: DqlGenerationCandidate;
          block?: ReturnType<typeof openBlockStudioDocument>;
          error?: string;
        }> = [];

        for (const candidateId of candidateIds) {
          try {
            let candidate = readBlockStudioImportCandidate(projectRoot, importId, candidateId);
            if (candidate.reviewStatus === 'saved' && candidate.savedPath && existsSync(join(projectRoot, candidate.savedPath))) {
              results.push({
                candidateId,
                path: candidate.savedPath,
                status: 'certified',
                blockers: [],
                candidate: candidate as DqlGenerationCandidate,
                block: openBlockStudioDocument(projectRoot, candidate.savedPath, semanticLayer),
              });
              continue;
            }
            if (candidate.recommendedAction === 'reuse_existing') {
              results.push({
                candidateId,
                status: 'error',
                blockers: ['An equivalent governed block already exists. Open and reuse it instead of saving a duplicate.'],
                candidate: candidate as DqlGenerationCandidate,
              });
              continue;
            }

            candidate = updateBlockStudioImportCandidate(projectRoot, importId, candidateId, { owner });
            const readiness = validateImportCandidateForSave(candidate);
            const validationBlockers = readiness.errors;
            if (validationBlockers.length === 0) {
              const certifiedSource = setBlockStudioSourceStatus(readiness.candidate.dqlSource, 'certified');
              const certification = await certifyBlockStudioSource(certifiedSource, readiness.candidate.savedPath, { enterprise: false });
              const blockers = Array.from(new Set(certification.checklist.blockers));
              if (certification.certification.certified && blockers.length === 0) {
                const savedPath = saveBlockStudioArtifacts(projectRoot, {
                  currentPath: readiness.candidate.savedPath,
                  source: certifiedSource,
                  name: readiness.candidate.name,
                  domain: readiness.candidate.domain,
                  description: readiness.candidate.description,
                  owner,
                  tags: readiness.candidate.tags,
                  lineage: readiness.candidate.lineage.sourceTables,
                  importMeta: { importId, candidateId, sourceKind: readiness.candidate.sourceKind, sourcePath: readiness.candidate.sourcePath },
                });
                const savedCandidate: DqlGenerationCandidate = {
                  ...readiness.candidate,
                  dqlSource: certifiedSource,
                  reviewStatus: 'saved',
                  savedPath,
                  analysisStatus: 'ready',
                  validation: validateBlockStudioSource(certifiedSource, semanticLayer),
                  generationMode: readiness.candidate.generationMode ?? 'deterministic',
                  generationProvider: readiness.candidate.generationProvider ?? 'local-deterministic',
                  llmContext: readiness.candidate.llmContext ?? deterministicDqlGenerationContext(readiness.candidate, readiness.candidate.evidence ?? []),
                  evidence: readiness.candidate.evidence ?? [],
                  draftSave: { status: 'saved', path: savedPath, savedAt: new Date().toISOString() },
                };
                writeBlockStudioImportCandidate(projectRoot, importId, savedCandidate);
                results.push({ candidateId, path: savedPath, status: 'certified', blockers: [], candidate: savedCandidate, block: openBlockStudioDocument(projectRoot, savedPath, semanticLayer) });
                continue;
              }
              validationBlockers.push(...blockers);
            }

            const draftCandidate = saveDqlGenerationDraft(importId, {
              ...readiness.candidate,
              dqlSource: setBlockStudioSourceStatus(readiness.candidate.dqlSource, 'draft'),
              analysisStatus: 'needs_attention',
            });
            writeBlockStudioImportCandidate(projectRoot, importId, draftCandidate);
            results.push({
              candidateId,
              path: draftCandidate.savedPath,
              status: 'draft',
              blockers: Array.from(new Set(validationBlockers.length > 0 ? validationBlockers : ['Certification gates did not pass.'])),
              candidate: draftCandidate,
              block: draftCandidate.savedPath ? openBlockStudioDocument(projectRoot, draftCandidate.savedPath, semanticLayer) : undefined,
            });
          } catch (error) {
            results.push({
              candidateId,
              status: 'error',
              blockers: [],
              error: error instanceof Error ? error.message : String(error),
            });
          }
        }

        await refreshLocalMetadataCatalog(projectRoot);
        const nextSession = loadDqlGenerationSession(importId);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: results.every((result) => result.status !== 'error'), session: nextSession, results }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const aiImportPathMatch = path.match(/^\/api\/block-studio\/ai-imports\/([^/]+)(?:\/candidates\/([^/]+)(?:\/(preview|certify))?)?$/);
    if (aiImportPathMatch) {
      const importId = decodeURIComponent(aiImportPathMatch[1]);
      const candidateId = aiImportPathMatch[2] ? decodeURIComponent(aiImportPathMatch[2]) : null;
      const action = aiImportPathMatch[3] ?? null;
      try {
        if (req.method === 'GET' && !candidateId) {
          const session = loadDqlGenerationSession(importId);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(session));
          return;
        }

        if (req.method === 'PATCH' && candidateId && !action) {
          const body = await readJSON(req);
          const candidate = updateBlockStudioImportCandidate(projectRoot, importId, candidateId, {
            name: typeof body.name === 'string' ? body.name : undefined,
            domain: typeof body.domain === 'string' ? body.domain : undefined,
            description: typeof body.description === 'string' ? body.description : undefined,
            owner: typeof body.owner === 'string' ? body.owner : undefined,
            tags: Array.isArray(body.tags) ? body.tags.map(String) : undefined,
            terms: Array.isArray(body.terms) ? body.terms.map(String) : undefined,
            pattern: typeof body.pattern === 'string' ? body.pattern : undefined,
            grain: typeof body.grain === 'string' ? body.grain : undefined,
            entities: Array.isArray(body.entities) ? body.entities.map(String) : undefined,
            outputs: Array.isArray(body.outputs) ? body.outputs.map(String) : undefined,
            dimensions: Array.isArray(body.dimensions) ? body.dimensions.map(String) : undefined,
            allowedFilters: Array.isArray(body.allowedFilters) ? body.allowedFilters.map(String) : undefined,
            parameterPolicy: Array.isArray(body.parameterPolicy) ? body.parameterPolicy : undefined,
            filterBindings: Array.isArray(body.filterBindings) ? body.filterBindings : undefined,
            sourceSystems: Array.isArray(body.sourceSystems) ? body.sourceSystems.map(String) : undefined,
            replacementFor: Array.isArray(body.replacementFor) ? body.replacementFor.map(String) : undefined,
            reviewCadence: typeof body.reviewCadence === 'string' ? body.reviewCadence : undefined,
            sql: typeof body.sql === 'string' ? body.sql : undefined,
            llmContext: typeof body.llmContext === 'string' ? body.llmContext : undefined,
          });
          const validated = validateImportCandidate(candidate);
          const savedDraft = validated.draftSave?.status === 'pending' && !isDraftBlockPath(validated.savedPath)
            ? ({
                ...validated,
                analysisStatus: 'ready',
                generationMode: validated.generationMode ?? 'deterministic',
                generationProvider: validated.generationProvider ?? 'local-deterministic',
                llmContext: validated.llmContext ?? deterministicDqlGenerationContext(validated, validated.evidence ?? []),
                evidence: validated.evidence ?? [],
                draftSave: { status: 'pending' as const },
              } satisfies DqlGenerationCandidate)
            : saveDqlGenerationDraft(importId, validated);
          writeBlockStudioImportCandidate(projectRoot, importId, savedDraft);
          if (savedDraft.draftSave.status === 'saved') await refreshLocalMetadataCatalog(projectRoot);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(savedDraft));
          return;
        }

        if (req.method === 'POST' && candidateId && action === 'preview') {
          const candidate = readBlockStudioImportCandidate(projectRoot, importId, candidateId);
          const preview = await runBlockStudioPreviewSource(candidate.dqlSource);
          const previewed = {
            ...candidate,
            preview,
            analysisStatus: 'ready' as const,
            validation: validateBlockStudioSource(candidate.dqlSource, semanticLayer),
          };
          const next = candidate.draftSave?.status === 'pending' && !isDraftBlockPath(candidate.savedPath)
            ? ({
                ...previewed,
                generationMode: candidate.generationMode ?? 'deterministic',
                generationProvider: candidate.generationProvider ?? 'local-deterministic',
                llmContext: candidate.llmContext ?? deterministicDqlGenerationContext(candidate, candidate.evidence ?? []),
                evidence: candidate.evidence ?? [],
                draftSave: { status: 'pending' as const },
              } satisfies DqlGenerationCandidate)
            : saveDqlGenerationDraft(importId, previewed);
          writeBlockStudioImportCandidate(projectRoot, importId, next);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(next));
          return;
        }

        if (req.method === 'POST' && candidateId && action === 'certify') {
          const candidate = readBlockStudioImportCandidate(projectRoot, importId, candidateId);
          const readiness = validateImportCandidateForSave(candidate);
          if (readiness.errors.length > 0) {
            const savedDraft = saveDqlGenerationDraft(importId, readiness.candidate);
            writeBlockStudioImportCandidate(projectRoot, importId, savedDraft);
            res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({
              error: readiness.errors.join(' '),
              candidate: savedDraft,
              diagnostics: (savedDraft.validation as any)?.diagnostics ?? [],
            }));
            return;
          }
          const certifiedSource = setBlockStudioSourceStatus(readiness.candidate.dqlSource, 'certified');
          // OSS certify = non-enterprise (owner-gated); enterprise depth is the cloud tier.
          const certification = await certifyBlockStudioSource(certifiedSource, readiness.candidate.savedPath, { enterprise: false });
          const blockers = Array.from(new Set(certification.checklist.blockers));
          if (!certification.certification.certified || blockers.length > 0) {
            const savedDraft = saveDqlGenerationDraft(importId, readiness.candidate);
            writeBlockStudioImportCandidate(projectRoot, importId, savedDraft);
            res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ ok: false, candidate: savedDraft, blockers, ...certification }));
            return;
          }
          const savedPath = saveBlockStudioArtifacts(projectRoot, {
            currentPath: readiness.candidate.savedPath,
            source: certifiedSource,
            name: readiness.candidate.name,
            domain: readiness.candidate.domain,
            description: readiness.candidate.description,
            owner: readiness.candidate.owner,
            tags: readiness.candidate.tags,
            lineage: readiness.candidate.lineage.sourceTables,
            importMeta: {
              importId,
              candidateId,
              sourceKind: readiness.candidate.sourceKind,
              sourcePath: readiness.candidate.sourcePath,
            },
          });
          const next: DqlGenerationCandidate = {
            ...readiness.candidate,
            dqlSource: certifiedSource,
            reviewStatus: 'saved',
            savedPath,
            validation: validateBlockStudioSource(certifiedSource, semanticLayer),
            generationMode: readiness.candidate.generationMode ?? 'deterministic',
            generationProvider: readiness.candidate.generationProvider ?? 'local-deterministic',
            llmContext: readiness.candidate.llmContext ?? deterministicDqlGenerationContext(readiness.candidate, readiness.candidate.evidence ?? []),
            evidence: readiness.candidate.evidence ?? [],
            draftSave: readiness.candidate.draftSave ?? { status: 'pending' },
          };
          writeBlockStudioImportCandidate(projectRoot, importId, next);
          let compiledManifest: DQLManifest | undefined;
          let lineageRefresh: {
            status: 'ready' | 'failed';
            compiledAt?: string;
            message?: string;
          };
          try {
            compiledManifest = compileBlockStudioManifest(projectRoot, projectConfig);
            lineageRefresh = { status: 'ready', compiledAt: new Date().toISOString() };
          } catch (error) {
            lineageRefresh = {
              status: 'failed',
              message: error instanceof Error ? error.message : String(error),
            };
          }
          await refreshLocalMetadataCatalog(projectRoot, compiledManifest, semanticLayer);
          const payload = {
            ...openBlockStudioDocument(projectRoot, savedPath, semanticLayer),
            lineageRefresh,
          };
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ candidate: next, block: payload, certification }));
          return;
        }

        res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Unsupported AI import operation.' }));
      } catch (error) {
        if (error instanceof Error && error.message === 'BLOCK_EXISTS') {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block already exists' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/block-studio/imports') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ sessions: listBlockStudioImportSessions(projectRoot) }));
      return;
    }

    if (req.method === 'DELETE' && path === '/api/block-studio/imports') {
      try {
        const removed = clearBlockStudioImportSessions(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, removed }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && (path === '/api/block-studio/import/preview' || path === '/api/block-studio/imports')) {
      try {
        const body = await readJSON(req);
        const inputPath = typeof body.path === 'string' ? body.path : '';
        const session = createBlockStudioImportSession(projectRoot, {
          inputPath,
          inputMode: body.inputMode === 'paste' || body.inputMode === 'upload' || body.inputMode === 'path' ? body.inputMode : undefined,
          sources: Array.isArray(body.sources)
            ? body.sources.map((source: any, index: number) => ({
                path: typeof source?.path === 'string' ? source.path : `source-${index + 1}.sql`,
                content: typeof source?.content === 'string' ? source.content : '',
              }))
            : undefined,
          sourceKind: typeof body.sourceKind === 'string' ? body.sourceKind : 'raw-sql',
          domain: typeof body.domain === 'string' ? body.domain : undefined,
          owner: typeof body.owner === 'string' ? body.owner : undefined,
          tags: Array.isArray(body.tags) ? body.tags.map(String) : undefined,
        });
        const candidates = session.candidates.map(validateImportCandidate);
        const validatedSession = { ...session, candidates };
        for (const candidate of candidates) {
          writeBlockStudioImportCandidate(projectRoot, session.id, candidate);
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(validatedSession));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const importSaveAllMatch = path.match(/^\/api\/block-studio\/imports\/([^/]+)\/save-all$/);
    if (importSaveAllMatch && req.method === 'POST') {
      const importId = decodeURIComponent(importSaveAllMatch[1]);
      try {
        const session = loadBlockStudioImportSession(projectRoot, importId);
        const saved: Array<{ candidateId: string; path: string }> = [];
        const errors: Array<{ candidateId: string; error: string }> = [];
        const nextCandidates = [...session.candidates];
        for (let i = 0; i < nextCandidates.length; i += 1) {
          const candidate = nextCandidates[i];
          if (candidate.reviewStatus === 'saved' || candidate.reviewStatus === 'rejected') continue;
          const readiness = validateImportCandidateForSave(candidate);
          nextCandidates[i] = readiness.candidate;
          writeBlockStudioImportCandidate(projectRoot, importId, readiness.candidate);
          if (readiness.errors.length > 0) {
            errors.push({ candidateId: candidate.id, error: readiness.errors.join(' ') });
            continue;
          }
          try {
            const savedPath = saveBlockStudioArtifacts(projectRoot, {
              source: readiness.candidate.dqlSource,
              name: readiness.candidate.name,
              domain: readiness.candidate.domain,
              description: readiness.candidate.description,
              owner: readiness.candidate.owner,
              tags: readiness.candidate.tags,
              lineage: readiness.candidate.lineage.sourceTables,
              importMeta: {
                importId,
                candidateId: readiness.candidate.id,
                sourceKind: readiness.candidate.sourceKind,
                sourcePath: readiness.candidate.sourcePath,
              },
            });
            nextCandidates[i] = { ...readiness.candidate, reviewStatus: 'saved', savedPath };
            writeBlockStudioImportCandidate(projectRoot, importId, nextCandidates[i]);
            saved.push({ candidateId: candidate.id, path: savedPath });
          } catch (error) {
            errors.push({ candidateId: candidate.id, error: error instanceof Error ? error.message : String(error) });
          }
        }
        const nextSession = { ...session, candidates: nextCandidates, updatedAt: new Date().toISOString() };
        writeBlockStudioImportSession(projectRoot, nextSession);
        let lineageRefresh: { status: 'ready' | 'failed'; compiledAt?: string; message?: string } | undefined;
        if (saved.length > 0) {
          let compiledManifest: DQLManifest | undefined;
          try {
            compiledManifest = compileBlockStudioManifest(projectRoot, projectConfig);
            lineageRefresh = { status: 'ready', compiledAt: new Date().toISOString() };
          } catch (error) {
            lineageRefresh = {
              status: 'failed',
              message: error instanceof Error ? error.message : String(error),
            };
          }
          await refreshLocalMetadataCatalog(projectRoot, compiledManifest, semanticLayer);
        }
        res.writeHead(errors.length > 0 ? 207 : 200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: errors.length === 0, session: nextSession, saved, errors, lineageRefresh }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    const importPathMatch = path.match(/^\/api\/block-studio\/imports\/([^/]+)(?:\/candidates\/([^/]+)(?:\/(run|save|ai-assist))?)?$/);
    if (importPathMatch) {
      const importId = decodeURIComponent(importPathMatch[1]);
      const candidateId = importPathMatch[2] ? decodeURIComponent(importPathMatch[2]) : null;
      const action = importPathMatch[3] ?? null;
      try {
        if (req.method === 'DELETE' && !candidateId) {
          deleteBlockStudioImportSession(projectRoot, importId);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: true }));
          return;
        }

        if (req.method === 'GET' && !candidateId) {
          const session = loadBlockStudioImportSession(projectRoot, importId);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(session));
          return;
        }

        if (req.method === 'PATCH' && candidateId && !action) {
          const body = await readJSON(req);
          const reviewStatus = typeof body.reviewStatus === 'string' && ['draft', 'review', 'saved', 'rejected'].includes(body.reviewStatus)
            ? body.reviewStatus as BlockStudioImportCandidate['reviewStatus']
            : undefined;
          const candidate = updateBlockStudioImportCandidate(projectRoot, importId, candidateId, {
            name: typeof body.name === 'string' ? body.name : undefined,
            domain: typeof body.domain === 'string' ? body.domain : undefined,
            description: typeof body.description === 'string' ? body.description : undefined,
            owner: typeof body.owner === 'string' ? body.owner : undefined,
            tags: Array.isArray(body.tags) ? body.tags.map(String) : undefined,
            terms: Array.isArray(body.terms) ? body.terms.map(String) : undefined,
            reviewCadence: typeof body.reviewCadence === 'string' ? body.reviewCadence : undefined,
            sql: typeof body.sql === 'string' ? body.sql : undefined,
            reviewStatus,
          });
          const validated = validateImportCandidate(candidate);
          writeBlockStudioImportCandidate(projectRoot, importId, validated);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(validated));
          return;
        }

        if (req.method === 'POST' && candidateId && action === 'run') {
          const candidate = readBlockStudioImportCandidate(projectRoot, importId, candidateId);
          const preview = await runBlockStudioPreviewSource(candidate.dqlSource);
          const next = { ...candidate, preview, validation: validateBlockStudioSource(candidate.dqlSource, semanticLayer) };
          writeBlockStudioImportCandidate(projectRoot, importId, next);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(next));
          return;
        }

        if (req.method === 'POST' && candidateId && action === 'ai-assist') {
          const body = await readJSON(req).catch(() => ({}));
          const candidate = readBlockStudioImportCandidate(projectRoot, importId, candidateId);
          const actionName = typeof body.action === 'string' ? body.action : 'explain';
          const validation = validateBlockStudioSource(candidate.dqlSource, semanticLayer);
          const assist = await buildBlockStudioAiAssistSummary(
            projectRoot,
            actionName,
            candidate,
            validation,
            isProviderSettingsId(body.provider) ? body.provider : undefined,
          );
          const next: BlockStudioImportCandidate = {
            ...candidate,
            validation,
            aiAssistance: [
              ...(candidate.aiAssistance ?? []),
              {
                action: actionName,
                summary: assist.summary,
                createdAt: new Date().toISOString(),
                status: 'suggested',
                provider: assist.provider,
              },
            ],
          };
          writeBlockStudioImportCandidate(projectRoot, importId, next);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON(next));
          return;
        }

        if (req.method === 'POST' && candidateId && action === 'save') {
          const candidate = readBlockStudioImportCandidate(projectRoot, importId, candidateId);
          if (candidate.reviewStatus === 'saved' && candidate.savedPath) {
            const payload = openBlockStudioDocument(projectRoot, candidate.savedPath, semanticLayer);
            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({ candidate, block: payload }));
            return;
          }
          const readiness = validateImportCandidateForSave(candidate);
          if (readiness.errors.length > 0) {
            writeBlockStudioImportCandidate(projectRoot, importId, readiness.candidate);
            res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
            res.end(serializeJSON({
              error: readiness.errors.join(' '),
              candidate: readiness.candidate,
              diagnostics: (readiness.candidate.validation as any)?.diagnostics ?? [],
            }));
            return;
          }
          const reusableSource = markBlockStudioSourceReusable(readiness.candidate.dqlSource);
          const savedPath = saveBlockStudioArtifacts(projectRoot, {
            source: reusableSource,
            name: readiness.candidate.name,
            domain: readiness.candidate.domain,
            description: readiness.candidate.description,
            owner: readiness.candidate.owner,
            tags: Array.from(new Set([...readiness.candidate.tags, APP_SOURCE_REUSABLE_TAG])),
            lineage: readiness.candidate.lineage.sourceTables,
            importMeta: {
              importId,
              candidateId,
              sourceKind: readiness.candidate.sourceKind,
              sourcePath: readiness.candidate.sourcePath,
            },
          });
          const next = {
            ...readiness.candidate,
            dqlSource: reusableSource,
            tags: Array.from(new Set([...readiness.candidate.tags, APP_SOURCE_REUSABLE_TAG])),
            reviewStatus: 'saved' as const,
            savedPath,
          };
          writeBlockStudioImportCandidate(projectRoot, importId, next);
          await refreshLocalMetadataCatalog(projectRoot);
          const payload = openBlockStudioDocument(projectRoot, savedPath, semanticLayer);
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ candidate: next, block: payload }));
          return;
        }

        res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Unsupported import operation.' }));
      } catch (error) {
        if (error instanceof Error && error.message === 'BLOCK_EXISTS') {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block already exists' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/block-studio/catalog') {
      try {
        const cfg = loadProjectConfig(projectRoot) as any;
        const connections = getProjectConnectionsForApi(cfg);
        const defaultKey = resolveDefaultConnectionKey(cfg, connections) ?? Object.keys(connections)[0] ?? 'default';
        const userPrefs = readUserPrefs(userPrefsPath);
        // UI-009 / PERF-001: Block Studio already loads the canonical semantic
        // layer. Let it omit this second, potentially multi-megabyte rendering
        // of the same 7,500+ object catalog while keeping the route compatible
        // for older clients.
        const includeSemantic = url.searchParams.get('includeSemantic') !== 'false';
        const dbtManifestPath = resolveDbtManifestPath(projectRoot, cfg);
        let databaseTree: ReturnType<typeof buildDbtDatabaseSchemaTree> = [];
        if (cfg.manifestVersion === 3 && cfg.modeling?.mode === 'dbt-first' && dbtManifestPath) {
          try {
            databaseTree = buildDbtDatabaseSchemaTree(
              projectSnapshot().manifest,
              25,
              physicalDbtRelationIds(dbtManifestPath),
            );
          } catch {
            // Keep the rest of Block Studio available while dbt is rebuilt.
          }
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          semanticTree: includeSemantic && semanticLayer ? buildSemanticTree(semanticLayer, semanticImportManifest) : null,
          databaseTree,
          connection: {
            default: defaultKey,
            current: defaultKey,
            connections,
          },
          favorites: userPrefs.favorites,
          recentlyUsed: userPrefs.recentlyUsed,
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/block-studio/dbt-status') {
      try {
        const status = buildDbtStatus(projectRoot, projectConfig, semanticLastSyncTime);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(status));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/semantic-layer/diagnostics') {
      try {
        const diagnostics = buildSemanticLayerDiagnostics(projectRoot, projectConfig, {
          semanticLayer,
          semanticErrors: semanticLayerErrors,
          semanticConfig,
          detectedProvider: semanticDetectedProvider,
          lastSyncTime: semanticLastSyncTime,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(diagnostics));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/semantic-layer/reload') {
      try {
        await reloadSemanticLayer();
        const diagnostics = buildSemanticLayerDiagnostics(projectRoot, projectConfig, {
          semanticLayer,
          semanticErrors: semanticLayerErrors,
          semanticConfig,
          detectedProvider: semanticDetectedProvider,
          lastSyncTime: semanticLastSyncTime,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: Boolean(semanticLayer),
          ...diagnostics,
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/block-studio/open') {
      try {
        const relativePath = url.searchParams.get('path');
        if (!relativePath) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing block path.' }));
          return;
        }
        const payload = openBlockStudioDocument(projectRoot, relativePath, semanticLayer);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(payload));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // Semantic-first block authoring. When the governed catalog can express a
    // question as {metrics} x {dimensions}, a generated block must be the SEMANTIC
    // form — not hand-rolled SQL. The answer that prompted this may legitimately
    // have come from a certified block (certified-first stays the answering rule),
    // but the block we CREATE from it should still be the simple governed shape.
    // Returns ok:false when the catalog cannot cover it, so the caller falls back
    // to the answer's own SQL-backed artifact.
    if (req.method === 'POST' && path === '/api/block-studio/compose-semantic') {
      try {
        const body = await readJSON(req).catch(() => null) as Record<string, unknown> | null;
        const question = typeof body?.question === 'string' ? body.question.trim() : '';
        if (!question) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, error: 'question is required.' }));
          return;
        }
        if (!semanticLayer) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, reason: 'no_semantic_layer' }));
          return;
        }
        let driver: string | undefined;
        let composeConnection: ConnectionConfig | undefined;
        try {
          composeConnection = requireActiveConnection();
          driver = composeConnection.driver;
        } catch {
          driver = undefined;
        }
        const tableMapping = composeConnection
          ? await resolveSemanticTableMapping(executor, composeConnection, semanticLayer, projectRoot)
          : undefined;
        const composed = composeSemanticQueryForQuestion({
          semanticLayer,
          question,
          questionPlan: buildAnalysisQuestionPlan(question),
          ...(driver ? { driver } : {}),
          ...(tableMapping ? { tableMapping } : {}),
        });
        if (!composed?.dqlArtifact?.source) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ ok: false, reason: 'no_semantic_coverage' }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          source: composed.dqlArtifact.source,
          sql: composed.sql,
          metrics: composed.metrics,
          dimensions: composed.dimensions,
          dqlArtifact: composed.dqlArtifact,
        }));
      } catch (error) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, reason: 'compose_failed', error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/validate') {
      try {
        const body = await readJSON(req);
        const source = typeof body.source === 'string' ? body.source : '';
        const validation = validateBlockStudioSource(source, semanticLayer);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(validation));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/run') {
      try {
        const body = await readJSON(req);
        const source = typeof body.source === 'string' ? body.source : '';
        const targetConnection = isConnectionConfig(body.connection) ? body.connection : connection;
        const parameters = body.parameters && typeof body.parameters === 'object' && !Array.isArray(body.parameters)
          ? body.parameters as Record<string, unknown>
          : {};
        const preview = await runBlockStudioPreviewSource(source, targetConnection, parameters);
        const blockPath = typeof body.path === 'string' ? body.path : null;
        if (blockPath) writeBlockStudioRunSummary(projectRoot, blockPath, source, preview.result);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(preview));
      } catch (error) {
        const raw = error instanceof Error ? error.message : String(error);
        const friendlyMessage = compactBlockStudioRuntimeFailure(raw);
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        // Keep the result surface concise. Raw compiler output remains available
        // for support and AI repair, but is never the primary end-user message.
        res.end(serializeJSON({
          error: raw,
          friendlyMessage,
          code: 'BLOCK_PREVIEW_FAILED',
          recoverable: true,
          details: { technicalDetails: raw },
          nextActions: ['Review the named field or metric.', 'Fix the draft and run it again.'],
        }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/agent-drafts') {
      try {
        const body = await readJSON(req);
        const source = typeof body.source === 'string'
          ? markBlockStudioSourceReusable(sanitizeAgentBlockDraftSource(body.source))
          : '';
        const name = typeof body.name === 'string' ? body.name.trim() : '';
        if (!source.trim() || !name) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'DQL source and block name are required.' }));
          return;
        }
        const savedPath = saveBlockStudioDraftArtifacts(projectRoot, {
          source,
          name,
          domain: typeof body.domain === 'string' ? body.domain : undefined,
          description: typeof body.description === 'string' ? body.description : undefined,
          tags: Array.from(new Set([
            ...(Array.isArray(body.tags) ? body.tags.map(String) : ['ai-generated', 'review-required']),
            APP_SOURCE_REUSABLE_TAG,
          ])),
          stableSuffix: typeof body.runId === 'string' ? body.runId : undefined,
        });
        const payload = openBlockStudioDocument(projectRoot, savedPath, semanticLayer);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(payload));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/block-studio/save') {
      try {
        const body = await readJSON(req);
        const source = typeof body.source === 'string'
          ? markBlockStudioSourceReusable(body.source)
          : '';
        const metadata = body.metadata && typeof body.metadata === 'object'
          ? body.metadata as {
            name?: string;
            domain?: string;
            folderPath?: string;
            description?: string;
            owner?: string;
            tags?: string[];
            sourceKind?: string;
            sourcePath?: string;
            importId?: string;
            candidateId?: string;
            lineage?: string[];
          }
          : {};
        if (!source.trim()) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block source is required.' }));
          return;
        }
        if (!metadata.name || typeof metadata.name !== 'string') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block name is required.' }));
          return;
        }
        const validation = validateBlockStudioSource(source, semanticLayer);
        if (!blockStudioValidationAllowsDraftSave(validation)) {
          const errors = validation.diagnostics.filter((diagnostic) =>
            diagnostic.severity === 'error'
            && !BLOCK_STUDIO_DRAFT_RUNTIME_DIAGNOSTICS.has(diagnostic.code ?? ''),
          );
          res.writeHead(422, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            error: errors[0]?.message ?? 'Fix the block errors before saving.',
            code: 'BLOCK_VALIDATION_FAILED',
            recoverable: true,
            details: { validation: { ...validation, saveable: false } },
            nextActions: ['Edit the DQL source', 'Fix with AI and run'],
          }));
          return;
        }
        const currentPath = typeof body.path === 'string' ? body.path : undefined;
        // Saving never certifies, and never replaces a certified block. The
        // certified status is kept only for the exact certified source; edits to
        // a certified block are saved as its draft beside it, and the certified
        // file stays in use until a new certification passes.
        const certifiedStatus = /^\s*status\s*=\s*"certified"/m;
        const canonicalAbsolute = currentPath && !isDraftBlockPath(currentPath) ? safeJoin(projectRoot, currentPath) : undefined;
        const canonicalOnDisk = canonicalAbsolute && existsSync(canonicalAbsolute) ? readFileSync(canonicalAbsolute, 'utf-8') : undefined;
        const canonicalCertified = canonicalOnDisk !== undefined && certifiedStatus.test(canonicalOnDisk);
        const sameAsCertified = canonicalCertified
          && markBlockStudioSourceReusable(setBlockStudioStatusInSource(canonicalOnDisk!, 'draft')).trim()
            === markBlockStudioSourceReusable(setBlockStudioStatusInSource(source, 'draft')).trim();
        const keepCertified = sameAsCertified && certifiedStatus.test(source);
        const sourceToWrite = certifiedStatus.test(source) && !keepCertified
          ? markBlockStudioSourceReusable(setBlockStudioStatusInSource(source, 'draft'))
          : source;
        const besideCertified = canonicalCertified && !keepCertified ? draftBesideCanonical(projectRoot, currentPath!) : undefined;
        const saveOptions = {
          currentPath,
          source: sourceToWrite,
          name: metadata.name,
          domain: metadata.domain,
          folderPath: metadata.folderPath,
          description: metadata.description,
          owner: metadata.owner,
          tags: Array.from(new Set([
            ...(Array.isArray(metadata.tags) ? metadata.tags.map(String) : []),
            APP_SOURCE_REUSABLE_TAG,
          ])),
          lineage: Array.isArray(metadata.lineage) ? metadata.lineage.map(String) : undefined,
          importMeta: metadata.sourceKind || metadata.sourcePath || metadata.importId || metadata.candidateId
            ? {
                importId: metadata.importId,
                candidateId: metadata.candidateId,
                sourceKind: metadata.sourceKind,
                sourcePath: metadata.sourcePath,
              }
            : undefined,
        };
        const savedPath = besideCertified
          ? saveBlockStudioDraftArtifacts(projectRoot, {
              ...saveOptions,
              currentPath: besideCertified.existingPath,
              stableSuffix: besideCertified.stableSuffix,
            })
          : isDraftBlockPath(currentPath)
            ? saveBlockStudioDraftArtifacts(projectRoot, {
                ...saveOptions,
                stableSuffix: metadata.candidateId,
              })
            : saveBlockStudioArtifacts(projectRoot, saveOptions);
        const refreshOperation = scheduleProjectRefresh('block-studio-save');
        const payload = {
          ...openBlockStudioDocument(projectRoot, savedPath, semanticLayer),
          lineageRefresh: {
            status: 'queued' as const,
            operationId: refreshOperation.id,
          },
        };
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(payload));
      } catch (error) {
        if (error instanceof Error && error.message === 'BLOCK_EXISTS') {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'A block with this name already exists in this folder. Rename it and try again.', code: 'BLOCK_EXISTS' }));
          return;
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'DELETE' && path === '/api/block-studio/block') {
      try {
        const blockPath = url.searchParams.get('path');
        const deleted = deleteBlockStudioArtifacts(projectRoot, blockPath ?? '');
        const refreshOperation = scheduleProjectRefresh('block-studio-delete');
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          ...deleted,
          lineageRefresh: { status: 'queued', operationId: refreshOperation.id },
        }));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        const status = message.startsWith('File not found:')
          ? 404
          : message === 'Invalid block path'
            ? 400
            : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: message }));
      }
      return;
    }

    const metadataScopePreviewMatch = path.match(/^\/api\/connections\/([^/]+)\/metadata-scope\/preview$/);
    const metadataDiscoveryMatch = path.match(/^\/api\/connections\/([^/]+)\/metadata-scope\/discovery$/);
    const metadataScopeMatch = path.match(/^\/api\/connections\/([^/]+)\/metadata-scope$/);
    const metadataSyncMatch = path.match(/^\/api\/connections\/([^/]+)\/metadata-sync$/);

    if (metadataDiscoveryMatch && req.method === 'POST') {
      try {
        const connectionId = decodeURIComponent(metadataDiscoveryMatch[1]!);
        const cfg = loadProjectConfig(projectRoot);
        const selectedConnection = projectConnectionById(projectRoot, cfg, connectionId);
        if (!selectedConnection) throw new Error(`Unknown connection "${connectionId}".`);
        const defaults = metadataScopeDbtDefaults(projectRoot, cfg);
        const discovery = await discoverWarehouseMetadataScopes({
          connectionId,
          executor,
          connection: selectedConnection,
          dbtRelations: defaults.relations,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(discovery));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (metadataScopePreviewMatch && req.method === 'POST') {
      try {
        const connectionId = decodeURIComponent(metadataScopePreviewMatch[1]!);
        const cfg = loadProjectConfig(projectRoot);
        const selectedConnection = projectConnectionById(projectRoot, cfg, connectionId);
        if (!selectedConnection) throw new Error(`Unknown connection "${connectionId}".`);
        const body = await readJSON(req).catch(() => ({})) as ConnectionMetadataScopeInput;
        const scope = normalizeConnectionMetadataScope(
          connectionId,
          selectedConnection,
          body,
          metadataScopeDbtDefaults(projectRoot, cfg),
        );
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          scope,
          status: warehouseMetadataStatus(projectRoot, scope.scopeFingerprint, connectionId),
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (metadataScopeMatch && req.method === 'GET') {
      try {
        const connectionId = decodeURIComponent(metadataScopeMatch[1]!);
        const cfg = loadProjectConfig(projectRoot);
        const selectedConnection = projectConnectionById(projectRoot, cfg, connectionId);
        if (!selectedConnection) throw new Error(`Unknown connection "${connectionId}".`);
        const scope = normalizeConnectionMetadataScope(
          connectionId,
          selectedConnection,
          configuredMetadataScopeInput(cfg, connectionId),
          metadataScopeDbtDefaults(projectRoot, cfg),
        );
        const warehouseCatalog = warehouseCatalogStatus(projectRoot, cfg, connectionId);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          scope,
          status: warehouseMetadataStatus(projectRoot, scope.scopeFingerprint, connectionId),
          ...(warehouseCatalog ? { warehouseCatalog } : {}),
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (metadataScopeMatch && req.method === 'PUT') {
      try {
        const connectionId = decodeURIComponent(metadataScopeMatch[1]!);
        const cfg = loadProjectConfig(projectRoot);
        const selectedConnection = projectConnectionById(projectRoot, cfg, connectionId);
        if (!selectedConnection) throw new Error(`Unknown connection "${connectionId}".`);
        const body = await readJSON(req) as ConnectionMetadataScopeInput;
        const scope = normalizeConnectionMetadataScope(
          connectionId,
          selectedConnection,
          body,
          metadataScopeDbtDefaults(projectRoot, cfg),
        );
        // The model as it stands, so drift can name what a re-sync touches.
        const modelBeforeSync = modelingModeOf(cfg) === 'warehouse-first' || modelingModeOf(cfg) === 'hybrid'
          ? (() => { try { return projectSnapshot().manifest; } catch { return undefined; } })()
          : undefined;
        const synced = await syncWarehouseMetadata({
          projectRoot,
          executor,
          connection: selectedConnection,
          scope,
        });
        persistConnectionMetadataScope(projectRoot, connectionId, scope);
        projectConfig = loadProjectConfig(projectRoot);
        const warehouseCatalog = await refreshWarehouseCatalogAfterSync(projectRoot, projectConfig, executor, selectedConnection, connectionId, synced.scope, modelBeforeSync);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          scope: synced.scope,
          status: warehouseMetadataStatus(projectRoot, synced.scope.scopeFingerprint, connectionId),
          ...(warehouseCatalog ? { warehouseCatalog } : {}),
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (metadataSyncMatch && req.method === 'POST') {
      try {
        const connectionId = decodeURIComponent(metadataSyncMatch[1]!);
        const cfg = loadProjectConfig(projectRoot);
        const selectedConnection = projectConnectionById(projectRoot, cfg, connectionId);
        if (!selectedConnection) throw new Error(`Unknown connection "${connectionId}".`);
        const scope = normalizeConnectionMetadataScope(
          connectionId,
          selectedConnection,
          configuredMetadataScopeInput(cfg, connectionId),
          metadataScopeDbtDefaults(projectRoot, cfg),
        );
        // The model as it stands, so drift can name what a re-sync touches.
        const modelBeforeSync = modelingModeOf(cfg) === 'warehouse-first' || modelingModeOf(cfg) === 'hybrid'
          ? (() => { try { return projectSnapshot().manifest; } catch { return undefined; } })()
          : undefined;
        const synced = await syncWarehouseMetadata({
          projectRoot,
          executor,
          connection: selectedConnection,
          scope,
        });
        const warehouseCatalog = await refreshWarehouseCatalogAfterSync(projectRoot, cfg, executor, selectedConnection, connectionId, synced.scope, modelBeforeSync);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          scope: synced.scope,
          status: warehouseMetadataStatus(projectRoot, synced.scope.scopeFingerprint, connectionId),
          ...(warehouseCatalog ? { warehouseCatalog } : {}),
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/connections') {
      const cfg = loadProjectConfig(projectRoot);
      const connections = getProjectConnectionsForApi(cfg);
      const defaultKey = resolveDefaultConnectionKey(cfg as unknown as Record<string, unknown>, connections)
        ?? Object.keys(connections)[0]
        ?? 'default';
      const dbtProfiles = discoverDbtProfileConnections(projectRoot, cfg);
      const activeDbtProfile = dbtProfiles.find((candidate) =>
        candidate.missingFields.length === 0
        && !candidate.warnings.some((warning) => warning.startsWith('DuckDB file not found'))
        && !candidate.warnings.some((warning) => warning.startsWith('Not the default dbt target'))
      );
      const activeConnection = connection ? {
        source: Object.keys(connections).length > 0 ? 'dql_config' : activeDbtProfile ? 'dbt_profile' : 'runtime',
        driver: connection.driver,
        ...(Object.keys(connections).length === 0 && activeDbtProfile ? { profileId: activeDbtProfile.id } : {}),
      } : null;
      const connectorStatus = getConnectorInstallStatuses(projectRoot);
      const metadataScope = connection
        ? optionalActiveConnectionMetadataScope(projectRoot, cfg, connection, defaultKey)
        : null;
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        default: defaultKey,
        // Saved secrets never travel to the browser.
        connections: redactConnections(connections),
        dbtProfiles: dbtProfiles.map((profile) => ({ ...profile, connection: redactConnections({ c: profile.connection }).c })),
        activeConnection,
        connectorStatus,
        metadataScope,
        metadataStatus: metadataScope
          ? warehouseMetadataStatus(projectRoot, metadataScope.scopeFingerprint, defaultKey)
          : warehouseMetadataStatus(projectRoot),
        // Present only in warehouse-first and hybrid modeling (RFC 0007).
        ...(() => {
          const warehouseCatalog = warehouseCatalogStatus(projectRoot, cfg, defaultKey);
          return warehouseCatalog ? { warehouseCatalog, modelingMode: modelingModeOf(cfg) } : {};
        })(),
      }));
      return;
    }

    if (req.method === 'POST' && path === '/api/connections/dbt-profiles/preview') {
      const body = await readJSON(req).catch(() => ({})) as { path?: unknown };
      const profilePath = typeof body.path === 'string' ? body.path.trim() : '';
      if (!profilePath) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Enter a profiles.yml file or folder path.' }));
        return;
      }
      const dbtProfiles = discoverDbtProfileConnections(projectRoot, loadProjectConfig(projectRoot), profilePath);
      if (dbtProfiles.length === 0) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'No supported dbt profile targets were found at that path.' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ dbtProfiles }));
      return;
    }

    if (req.method === "GET" && path === "/api/datasets") {
      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
      res.end(
        serializeJSON({
          datasets: datasetWorkspace.list(),
          workspace: {
            target: "local",
            databasePath: relative(
              projectRoot,
              datasetWorkspace.databasePath,
            ).replaceAll("\\", "/"),
          },
        }),
      );
      return;
    }

    if (req.method === "POST" && path === "/api/datasets/import") {
      try {
        const multipart = String(req.headers["content-type"] ?? "")
          .toLowerCase()
          .startsWith("multipart/form-data")
          ? await readMultipartForm(req)
          : null;
        const body = multipart?.fields ?? (await readJSON(req));
        if (
          typeof body.contentBase64 === "string" &&
          body.contentBase64.length > 350_000_000
        ) {
          throw new Error(
            "Uploaded dataset exceeds the 250 MB local import limit. Link the local path or reduce the file first.",
          );
        }
        if (
          multipart?.file &&
          multipart.file.content.byteLength > 250_000_000
        ) {
          throw new Error(
            "Uploaded dataset exceeds the 250 MB local import limit. Link the local path or reduce the file first.",
          );
        }
        await ensureLocalWorkspaceReady();
        const imported = await datasetWorkspace.import({
          filename:
            multipart?.file?.filename ??
            (typeof body.filename === "string" ? body.filename : undefined),
          sourcePath:
            typeof body.sourcePath === "string" ? body.sourcePath : undefined,
          contentBase64:
            typeof body.contentBase64 === "string"
              ? body.contentBase64
              : undefined,
          content: multipart?.file?.content,
          storageMode: body.storageMode === "project" ? "project" : "local",
          link: body.link === true || body.link === "true",
          name: typeof body.name === "string" ? body.name : undefined,
          alias: typeof body.alias === "string" ? body.alias : undefined,
          description:
            typeof body.description === "string" ? body.description : undefined,
          owner: typeof body.owner === "string" ? body.owner : undefined,
          tags: Array.isArray(body.tags)
            ? body.tags.map(String)
            : typeof body.tags === "string"
              ? body.tags
                  .split(",")
                  .map((tag: string) => tag.trim())
                  .filter(Boolean)
              : undefined,
        });
        recordDatasetMetadataSnapshot();
        res.writeHead(imported.duplicate ? 200 : 201, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(serializeJSON(imported));
      } catch (error) {
        res.writeHead(400, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(
          serializeJSON({
            error: error instanceof Error ? error.message : String(error),
          }),
        );
      }
      return;
    }

    if (req.method === "GET" && /^\/api\/datasets\/[^/]+$/.test(path)) {
      const id = decodeURIComponent(path.slice("/api/datasets/".length));
      const dataset = datasetWorkspace.get(id);
      if (!dataset) {
        res.writeHead(404, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(serializeJSON({ error: "Dataset not found." }));
      } else {
        res.writeHead(200, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(serializeJSON({ dataset }));
      }
      return;
    }

    if (
      req.method === "POST" &&
      /^\/api\/datasets\/[^/]+\/refresh$/.test(path)
    ) {
      try {
        const id = decodeURIComponent(
          path.match(/^\/api\/datasets\/([^/]+)\/refresh$/)?.[1] ?? "",
        );
        await ensureLocalWorkspaceReady();
        const dataset = await datasetWorkspace.refresh(id);
        recordDatasetMetadataSnapshot();
        res.writeHead(200, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(serializeJSON({ dataset }));
      } catch (error) {
        res.writeHead(400, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(
          serializeJSON({
            error: error instanceof Error ? error.message : String(error),
          }),
        );
      }
      return;
    }

    if (
      req.method === "POST" &&
      /^\/api\/datasets\/[^/]+\/(rename|pin)$/.test(path)
    ) {
      try {
        const match = path.match(/^\/api\/datasets\/([^/]+)\/(rename|pin)$/)!;
        const body = await readJSON(req);
        const dataset =
          match[2] === "pin"
            ? datasetWorkspace.pin(
                decodeURIComponent(match[1]),
                body.pinned !== false,
              )
            : datasetWorkspace.rename(
                decodeURIComponent(match[1]),
                String(body.name ?? ""),
                typeof body.alias === "string" ? body.alias : undefined,
              );
        recordDatasetMetadataSnapshot();
        res.writeHead(200, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(serializeJSON({ dataset }));
      } catch (error) {
        res.writeHead(400, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(
          serializeJSON({
            error: error instanceof Error ? error.message : String(error),
          }),
        );
      }
      return;
    }

    if (
      req.method === "POST" &&
      /^\/api\/datasets\/[^/]+\/schema$/.test(path)
    ) {
      try {
        const id = decodeURIComponent(
          path.match(/^\/api\/datasets\/([^/]+)\/schema$/)?.[1] ?? "",
        );
        const body = await readJSON(req);
        await ensureLocalWorkspaceReady();
        const dataset = await datasetWorkspace.updateSchema(
          id,
          body.overrides && typeof body.overrides === "object"
            ? body.overrides
            : {},
        );
        recordDatasetMetadataSnapshot();
        res.writeHead(200, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(serializeJSON({ dataset }));
      } catch (error) {
        res.writeHead(400, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(
          serializeJSON({
            error: error instanceof Error ? error.message : String(error),
          }),
        );
      }
      return;
    }

    if (req.method === "DELETE" && /^\/api\/datasets\/[^/]+$/.test(path)) {
      const id = decodeURIComponent(path.slice("/api/datasets/".length));
      datasetWorkspace.remove(id);
      recordDatasetMetadataSnapshot();
      res.writeHead(204);
      res.end();
      return;
    }

    if (req.method === "POST" && path === "/api/datasets/stage") {
      try {
        const body = await readJSON(req);
        if (body.confirmed !== true) {
          res.writeHead(428, {
            "Content-Type": "application/json; charset=utf-8",
          });
          res.end(
            serializeJSON({
              error:
                "Confirm the bounded local copy before staging warehouse data.",
            }),
          );
          return;
        }
        const configured = projectConfig.notebook?.staging;
        const maxRows = Math.max(
          1,
          Math.min(
            Number(body.maxRows ?? configured?.maxRows ?? 100_000),
            500_000,
          ),
        );
        const maxBytes = Math.max(
          1_000_000,
          Math.min(
            Number(body.maxBytes ?? configured?.maxBytes ?? 250_000_000),
            1_000_000_000,
          ),
        );
        const timeoutMs = Math.max(
          1_000,
          Math.min(
            Number(body.timeoutSeconds ?? configured?.timeoutSeconds ?? 120) *
              1000,
            600_000,
          ),
        );
        const sql = typeof body.sql === "string" ? body.sql.trim() : "";
        const validationError = readOnlySqlValidationError(
          sql,
          "Local staging",
        );
        if (validationError) throw new Error(validationError);
        const semantic = prepareSemanticSql(sql, semanticLayer);
        if (semantic.unresolvedRefs.length > 0)
          throw new Error(
            `Unknown semantic references: ${semantic.unresolvedRefs.join(", ")}`,
          );
        const named =
          typeof body.connectionName === "string"
            ? resolveNamedConnection(body.connectionName)
            : connection;
        const sourceConnection = requireActiveConnection(named);
        const prepared = prepareLocalExecution(
          `SELECT * FROM (${stripSqlTerminator(semantic.sql)}) AS dql_stage_source LIMIT ${maxRows + 1}`,
          sourceConnection,
          projectRoot,
          projectConfig,
        );
        const execution = executor.executeQuery(
          prepared.sql,
          [],
          runtimeVariables({}),
          prepared.connection,
        );
        const result = await Promise.race([
          execution,
          new Promise<never>((_, reject) =>
            setTimeout(
              () =>
                reject(
                  new Error(
                    `Staging query exceeded ${Math.round(timeoutMs / 1000)} seconds.`,
                  ),
                ),
              timeoutMs,
            ),
          ),
        ]);
        const rows = (result.rows ?? []) as Array<Record<string, unknown>>;
        if (rows.length > maxRows)
          throw new Error(
            `Staging would exceed the ${maxRows.toLocaleString()} row limit. Add filters or aggregate the warehouse query.`,
          );
        const rowPayload = serializeJSON(rows);
        const byteCount = Buffer.byteLength(rowPayload);
        if (byteCount > maxBytes)
          throw new Error(
            `Staging would exceed the ${(maxBytes / 1_000_000).toFixed(0)} MB limit. Add filters or aggregate the warehouse query.`,
          );
        await ensureLocalWorkspaceReady();
        const dataset = await datasetWorkspace.stageRows({
          name:
            typeof body.name === "string" && body.name.trim()
              ? body.name.trim()
              : "Staged warehouse result",
          rows,
          expiresInDays: configured?.expiryDays ?? 7,
          lineage: {
            connectionName:
              typeof body.connectionName === "string"
                ? body.connectionName
                : projectConfig.defaultConnectionName,
            query: sql,
            blockPath:
              typeof body.blockPath === "string" ? body.blockPath : undefined,
            semanticMetrics: semantic.semanticRefs.metrics,
            semanticDimensions: semantic.semanticRefs.dimensions,
            filters:
              body.filters && typeof body.filters === "object"
                ? body.filters
                : undefined,
            parameters:
              body.parameters && typeof body.parameters === "object"
                ? body.parameters
                : undefined,
            extractedAt: new Date().toISOString(),
            rowCount: rows.length,
            byteCount,
            sourceFingerprint: createHash("sha256")
              .update(
                `${body.connectionName ?? projectConfig.defaultConnectionName ?? "default"}:${sql}`,
              )
              .digest("hex"),
            resultFingerprint: createHash("sha256")
              .update(rowPayload)
              .digest("hex"),
          },
        });
        recordDatasetMetadataSnapshot();
        res.writeHead(201, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(
          serializeJSON({
            dataset,
            limits: { maxRows, maxBytes, timeoutMs },
            trustLabel: "review_required",
          }),
        );
      } catch (error) {
        res.writeHead(400, {
          "Content-Type": "application/json; charset=utf-8",
        });
        res.end(
          serializeJSON({
            error: error instanceof Error ? error.message : String(error),
          }),
        );
      }
      return;
    }

    if (req.method === "POST" && path === "/api/connectors/install") {
      try {
        const body = await readJSON(req);
        const driver = typeof body.driver === 'string' ? body.driver : '';
        const status = installConnectorPackage(projectRoot, driver);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          status,
          connectorStatus: getConnectorInstallStatuses(projectRoot),
        }));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: false,
          error: message,
          connectorStatus: getConnectorInstallStatuses(projectRoot),
        }));
      }
      return;
    }

    // Save/update connections
    if (req.method === 'PUT' && path === '/api/connections') {
      try {
        const body = await readJSON(req);
        const configPath = join(projectRoot, 'dql.config.json');
        let raw: Record<string, unknown> = {};
        if (existsSync(configPath)) {
          raw = JSON.parse(readFileSync(configPath, 'utf-8')) as Record<string, unknown>;
        }
        if (body.connections && typeof body.connections === 'object') {
          const previousConnections = getStoredConnections(raw);
          const renames = body.renames && typeof body.renames === 'object' ? body.renames as Record<string, string> : {};
          raw.connections = storeConnectionSecrets(projectRoot, body.connections as Record<string, unknown>, previousConnections, {
            renames,
            fallback: (name, field) => dbtProfileSecret(projectRoot, loadProjectConfig(projectRoot), name, field),
          });
        }
        const connections = getStoredConnections(raw);
        if (body.connections && typeof body.connections === 'object') {
          const requestedDefault = typeof body.defaultConnectionName === 'string'
            ? body.defaultConnectionName
            : typeof body.default === 'string'
              ? body.default
              : undefined;
          const defaultConnectionName = resolveDefaultConnectionKey(
            requestedDefault ? { ...raw, defaultConnectionName: requestedDefault } : raw,
            connections,
          );
          delete raw.defaultConnection;
          if (defaultConnectionName) {
            raw.defaultConnectionName = defaultConnectionName;
          } else {
            delete raw.defaultConnectionName;
          }
        }
        writeFileSync(configPath, JSON.stringify(raw, null, 2) + '\n', 'utf-8');

        // Hot-swap: re-read the config and re-initialize the active connection
        projectConfig = loadProjectConfig(projectRoot);
        const newDefault = projectConfig.defaultConnection;
        if (newDefault) {
          connection = normalizeProjectConnection(newDefault, projectRoot);
          // The driver and any add-on (SSH tunnel, IAM sign-in) the saved
          // connection needs are installed now, so the first test just works.
          try {
            ensureConnectionPackages(projectRoot, connection);
          } catch {
            // The test reports the missing package with its install command.
          }
          // Auto-register data files if DuckDB/file driver
          if (connection.driver === 'file' || connection.driver === 'duckdb') {
            const dataDir = projectConfig.dataDir
              ? resolve(projectRoot, projectConfig.dataDir)
              : join(projectRoot, 'data');
            if (existsSync(dataDir)) {
              try {
                const files = readdirSync(dataDir, { withFileTypes: true })
                  .filter((e) => e.isFile() && /\.(csv|parquet)$/i.test(e.name));
                for (const file of files) {
                  const tableName = file.name.replace(/\.(csv|parquet)$/i, '');
                  const absPath = join(dataDir, file.name).replaceAll('\\', '/');
                  const reader = file.name.endsWith('.parquet') ? 'read_parquet' : 'read_csv_auto';
                  const ddl = `CREATE OR REPLACE VIEW "${tableName}" AS SELECT * FROM ${reader}('${absPath}')`;
                  try { await executor.executeQuery(ddl, [], {}, connection); } catch { /* non-fatal */ }
                }
              } catch { /* non-fatal */ }
            }
          }
        }

        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Semantic runtime adapters (API-004 / UI-009 / E2E-008) ───────────────
    if (req.method === 'GET' && path === '/api/semantic-runtime') {
      try {
        const runtime = await getSemanticRuntimeStatus(projectRoot, { probeConfiguredCloud: true });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ...getSemanticRuntimeSettings(projectRoot), runtime }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }
    if (req.method === 'GET' && path === '/api/semantic-runtime/metricflow/installer') {
      try {
        const profileAdapter = discoverDbtProfileConnections(projectRoot, projectConfig)[0]?.adapter;
        const recommendedAdapter = metricFlowAdapterForDriver(connection?.driver ?? profileAdapter);
        const dbtProjectDir = findDbtProjectPath(projectRoot, projectConfig);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          job: metricFlowInstaller.latest(),
          recommendedAdapter,
          supportedAdapters: ['duckdb', 'snowflake', 'bigquery', 'databricks', 'redshift', 'postgres', 'trino'],
          projectConfigured: existsSync(join(dbtProjectDir, 'dbt_project.yml')),
          semanticManifestFound: existsSync(join(dbtProjectDir, 'target', 'semantic_manifest.json')),
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/semantic-runtime/metricflow/install') {
      try {
        const body = await readJSON(req) as { adapter?: unknown };
        const profileAdapter = discoverDbtProfileConnections(projectRoot, projectConfig)[0]?.adapter;
        const inferred = metricFlowAdapterForDriver(connection?.driver ?? profileAdapter);
        const adapter = body.adapter === undefined ? inferred : body.adapter;
        if (!isMetricFlowWarehouseAdapter(adapter)) {
          throw new Error('Choose a supported warehouse adapter before installing MetricFlow.');
        }
        const { dbtProjectDir, profilesDir } = onboardingDbtPaths({});
        const job = metricFlowInstaller.start({ adapter, dbtProjectDir, profilesDir });
        res.writeHead(202, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, job }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/semantic-runtime/dbt-cloud/test') {
      try {
        const body = await readJSON(req) as SemanticRuntimeSettingsInput;
        const result = await testSemanticRuntimeDraft(projectRoot, body);
        const { metricNames: _metricNames, ...publicResult } = result;
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(publicResult));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/semantic-runtime/dbt-cloud/apply') {
      try {
        const body = await readJSON(req) as SemanticRuntimeSettingsInput;
        const result = await testSemanticRuntimeDraft(projectRoot, body);
        const targetConnection = requireActiveConnection(connection);
        const executionTarget = await observeWarehouseTargetIdentity(executor, targetConnection);
        const settings = saveTestedSemanticRuntimeSettings(projectRoot, body, result, executionTarget);
        const runtime = await getSemanticRuntimeStatus(projectRoot);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, ...settings, runtime }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }
    // Set the runtime preference alone (no dbt Cloud test required), so a user
    // can prefer Native / Local MetricFlow / dbt Cloud explicitly.
    if (req.method === 'POST' && path === '/api/semantic-runtime/preference') {
      try {
        const body = await readJSON(req) as { preference?: string };
        const preference = body.preference;
        if (preference !== 'auto' && preference !== 'native' && preference !== 'metricflow-cli' && preference !== 'dbt-cloud') {
          throw new Error('preference must be one of: auto, native, metricflow-cli, dbt-cloud');
        }
        const settings = saveSemanticRuntimePreference(projectRoot, preference);
        const runtime = await getSemanticRuntimeStatus(projectRoot, { probeConfiguredCloud: true });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, ...settings, runtime }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    // ── Semantic layer discovery API ─────────────────────────────────────────
    if (req.method === 'GET' && path === '/api/semantic-layer') {
      const userPrefs = readUserPrefs(userPrefsPath);
      if (!semanticLayer) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          available: false,
          provider: semanticConfig?.provider ?? semanticDetectedProvider ?? null,
          errors: semanticLayerErrors,
          metrics: [],
          measures: [],
          dimensions: [],
          timeDimensions: [],
          entities: [],
          hierarchies: [],
          semanticModels: [],
          savedQueries: [],
          domains: [],
          tags: [],
          favorites: userPrefs.favorites,
          recentlyUsed: userPrefs.recentlyUsed,
          lastSyncTime: semanticLastSyncTime,
        }));
        return;
      }
      const provider = semanticConfig?.provider ?? semanticDetectedProvider ?? 'dql';
      const dbtManifestReady = provider === 'dbt'
        ? hasDbtSemanticManifest(projectRoot, semanticConfig?.projectPath)
        : false;
      const semanticRuntime = await getSemanticRuntimeStatus(projectRoot, { probeConfiguredCloud: true });
      // The public catalog exposes business metrics only. Measures remain
      // available in the dedicated technical collection for model inspection
      // and native composition, but no longer appear as duplicate metrics.
      const metrics = semanticLayer.listMetrics(undefined, { includeMeasures: false }).map((m) => ({
        name: m.name,
        label: m.label,
        description: m.description,
        domain: m.domain,
        cube: m.cube ?? null,
        semanticModelIds: m.semanticModelIds ?? (m.cube ? [m.cube] : []),
        canonicalId: `semantic:${m.domain || 'uncategorized'}:metric:${m.name}`,
        sql: m.sql,
        type: m.type,
        table: m.table,
        tags: m.tags ?? [],
        owner: m.owner ?? null,
        metricType: m.metricType ?? null,
        typeParams: m.typeParams ?? null,
        filter: m.filter ?? null,
        source: m.source ?? null,
        execution: runtimeMetricExecutionCapability(
          m.name,
          semanticLayer!,
          provider,
          semanticRuntime,
          projectRoot,
        ),
      }));
      const measures = semanticLayer.listMeasures().map((m) => ({
        name: m.name,
        label: m.label,
        description: m.description,
        domain: m.domain,
        agg: m.agg,
        expr: m.expr ?? null,
        table: m.table,
        cube: m.cube ?? null,
        aggTimeDimension: m.aggTimeDimension ?? null,
        nonAdditiveDimension: m.nonAdditiveDimension ?? null,
        tags: m.tags ?? [],
        owner: m.owner ?? null,
        source: m.source ?? null,
      }));
      const dimensions = semanticLayer.listDimensions(undefined, { includeVariants: true }).map((d) => ({
        name: d.name,
        label: d.label,
        description: d.description,
        domain: d.domain,
        sql: d.sql,
        type: d.type,
        table: d.table,
        tags: d.tags ?? [],
        owner: d.owner ?? null,
        cube: d.cube ?? null,
        reference: semanticDimensionReference(d),
        qualifiedName: d.qualifiedName ?? null,
        entityLink: d.entityLink ?? null,
        canonicalId: `semantic:${d.domain || 'uncategorized'}:dimension:${semanticDimensionReference(d)}`,
        isTimeDimension: d.isTimeDimension ?? false,
        typeParams: d.typeParams ?? null,
        source: d.source ?? null,
      }));
      const timeDimensions = semanticLayer.listTimeDimensions(undefined, { includeVariants: true }).map((d) => ({
        name: d.name,
        label: d.label,
        description: d.description,
        domain: d.domain,
        sql: d.sql,
        type: d.type,
        table: d.table,
        cube: d.cube ?? null,
        reference: semanticDimensionReference(d),
        qualifiedName: d.qualifiedName ?? null,
        entityLink: d.entityLink ?? null,
        canonicalId: `semantic:${d.domain || 'uncategorized'}:dimension:${semanticDimensionReference(d)}`,
        granularities: d.granularities ?? [],
        primaryTime: d.primaryTime ?? false,
        tags: d.tags ?? [],
        owner: d.owner ?? null,
        typeParams: d.typeParams ?? null,
        source: d.source ?? null,
      }));
      const entities = semanticLayer.listEntities().map((e) => ({
        name: e.name,
        label: e.label,
        description: e.description,
        domain: e.domain,
        type: e.type,
        expr: e.expr ?? null,
        table: e.table,
        cube: e.cube ?? null,
        role: e.role ?? null,
        tags: e.tags ?? [],
        owner: e.owner ?? null,
        source: e.source ?? null,
      }));
      const hierarchies = semanticLayer.listHierarchies().map((h) => ({
        name: h.name,
        label: h.label,
        description: h.description,
        domain: h.domain,
        levels: h.levels.map((l) => ({ name: l.name, label: l.label })),
      }));
      const semanticModels = semanticLayer.listSemanticModels().map((m) => ({
        name: m.name,
        label: m.label,
        description: m.description,
        domain: m.domain,
        model: m.model ?? null,
        table: m.table,
        entities: m.entities,
        measures: m.measures,
        dimensions: m.dimensions,
        timeDimensions: m.timeDimensions,
        tags: m.tags ?? [],
        owner: m.owner ?? null,
        source: m.source ?? null,
      }));
      const savedQueries = semanticLayer.listSavedQueries().map((q) => ({
        name: q.name,
        label: q.label,
        description: q.description,
        domain: q.domain,
        metrics: q.metrics,
        dimensions: q.dimensions,
        timeDimension: q.timeDimension ?? null,
        granularity: q.granularity ?? null,
        filters: q.filters ?? null,
        tags: q.tags ?? [],
        owner: q.owner ?? null,
        source: q.source ?? null,
      }));
      const dbtExecutionSetup = !dbtManifestReady
        ? 'Run `dbt parse` or `dbt build` so target/semantic_manifest.json exists.'
        : semanticRuntime.setup;
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        available: true,
        provider,
        execution: provider === 'dbt'
          ? {
              engine: semanticRuntime.active,
              ready: semanticRuntime.active !== 'native' || metrics.every((metric) => metric.execution.status === 'ready'),
              setup: dbtExecutionSetup,
              adapters: semanticRuntime.adapters,
            }
          : { engine: 'native', ready: true, setup: null, adapters: semanticRuntime.adapters },
        errors: semanticLayerErrors,
        metrics,
        measures,
        dimensions,
        timeDimensions,
        entities,
        hierarchies,
        semanticModels,
        savedQueries,
        domains: semanticLayer.listDomains(),
        tags: semanticLayer.listTags(),
        favorites: userPrefs.favorites,
        recentlyUsed: userPrefs.recentlyUsed,
        lastSyncTime: semanticLastSyncTime,
      }));
      return;
    }
    if (req.method === 'GET' && path === '/api/semantic-layer/tree') {
      if (!semanticLayer) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          tree: {
            id: 'provider:dql',
            label: 'semantic layer',
            kind: 'provider',
            count: 0,
            children: [],
          },
        }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        tree: buildSemanticTree(semanticLayer, semanticImportManifest),
      }));
      return;
    }
    if (req.method === 'GET' && path.startsWith('/api/semantic-layer/object/')) {
      if (!semanticLayer) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'No semantic layer configured.' }));
        return;
      }
      const id = decodeURIComponent(path.slice('/api/semantic-layer/object/'.length));
      const detail = buildSemanticObjectDetail(semanticLayer, semanticImportManifest, id);
      if (!detail) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: `Unknown semantic object: ${id}` }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON(detail));
      return;
    }
    if (req.method === 'POST' && path === '/api/semantic-layer/import') {
      try {
        const body = await readJSON(req);
        const provider = body.provider as 'dbt' | 'cubejs' | 'snowflake';
        if (provider !== 'dbt' && provider !== 'cubejs' && provider !== 'snowflake') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'provider must be one of dbt, cubejs, snowflake' }));
          return;
        }
        const sourceConfig = provider === 'snowflake'
          ? {
              provider,
              projectPath: body.projectPath ?? projectConfig.semanticLayer?.projectPath,
              connection: body.connection ?? projectConfig.semanticLayer?.connection,
            }
          : {
              provider,
              projectPath: typeof body.projectPath === 'string' ? body.projectPath : projectConfig.semanticLayer?.projectPath,
              repoUrl: typeof body.repoUrl === 'string' ? body.repoUrl : projectConfig.semanticLayer?.repoUrl,
              branch: typeof body.branch === 'string' ? body.branch : projectConfig.semanticLayer?.branch,
              subPath: typeof body.subPath === 'string' ? body.subPath : projectConfig.semanticLayer?.subPath,
              source: body.repoUrl || projectConfig.semanticLayer?.repoUrl
                ? ((body.source ?? projectConfig.semanticLayer?.source ?? 'github') as 'local' | 'github' | 'gitlab')
                : 'local',
            };
        const executeQuery = provider === 'snowflake'
          ? async (sql: string) => {
              const result = await executor.executeQuery(sql, [], {}, requireActiveConnection());
              return { rows: result.rows };
            }
          : undefined;
        const importResult = await performSemanticImport({
          targetProjectRoot: projectRoot,
          provider,
          sourceConfig,
          executeQuery,
        });
        // Re-resolve using project's actual semantic config (not hardcoded 'dql')
        const projSemConfig = loadProjectConfig(projectRoot)?.semanticLayer ?? { provider: 'dql', path: './semantic-layer' };
        const refreshed = await resolveSemanticLayerAsync(projSemConfig, projectRoot);
        semanticLayer = refreshed.layer;
        semanticLayerErrors = refreshed.errors;
        semanticDetectedProvider = refreshed.detectedProvider ?? 'dql';
        semanticLastSyncTime = importResult.manifest.importedAt;
        semanticImportManifest = importResult.manifest;
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(importResult));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        const hint = message.includes('conflict')
          ? 'A file conflict was detected. Remove or rename the conflicting file and retry.'
          : message.includes('dbt_project.yml')
            ? 'Ensure your dbt project path contains a valid dbt_project.yml file.'
            : message.includes('query executor')
              ? 'A Snowflake connection is required. Configure one in the Connection panel first.'
              : 'Check the provider path and ensure the source files are accessible.';
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: message, hint }));
      }
      return;
    }
    if (req.method === 'POST' && path === '/api/semantic-layer/sync') {
      try {
        const executeQuery = semanticImportManifest?.provider === 'snowflake'
          ? async (sql: string) => {
              const result = await executor.executeQuery(sql, [], {}, requireActiveConnection());
              return { rows: result.rows };
            }
          : undefined;
        const importResult = await syncSemanticImport({
          targetProjectRoot: projectRoot,
          executeQuery,
        });
        // Re-resolve using project's actual semantic config (not hardcoded 'dql')
        const projSemConfig = loadProjectConfig(projectRoot)?.semanticLayer ?? { provider: 'dql', path: './semantic-layer' };
        const refreshed = await resolveSemanticLayerAsync(projSemConfig, projectRoot);
        semanticLayer = refreshed.layer;
        semanticLayerErrors = refreshed.errors;
        semanticDetectedProvider = refreshed.detectedProvider ?? 'dql';
        semanticLastSyncTime = importResult.manifest.importedAt;
        semanticImportManifest = importResult.manifest;
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(importResult));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        const hint = message.includes('No semantic import manifest')
          ? 'No previous import found. Use the Setup Wizard to import a semantic layer first.'
          : 'Check the source configuration and retry.';
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: message, hint }));
      }
      return;
    }
    // ── Semantic layer import preview (dry-run) ──────────────────────────
    if (req.method === 'POST' && path === '/api/semantic-layer/import-preview') {
      try {
        const body = await readJSON(req);
        const provider = body.provider as 'dbt' | 'cubejs' | 'snowflake';
        if (provider !== 'dbt' && provider !== 'cubejs' && provider !== 'snowflake') {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'provider must be one of dbt, cubejs, snowflake' }));
          return;
        }
        const sourceConfig = provider === 'snowflake'
          ? {
              provider,
              projectPath: body.projectPath ?? projectConfig.semanticLayer?.projectPath,
              connection: body.connection ?? projectConfig.semanticLayer?.connection,
            }
          : {
              provider,
              projectPath: typeof body.projectPath === 'string' ? body.projectPath : projectConfig.semanticLayer?.projectPath,
              repoUrl: typeof body.repoUrl === 'string' ? body.repoUrl : projectConfig.semanticLayer?.repoUrl,
              branch: typeof body.branch === 'string' ? body.branch : projectConfig.semanticLayer?.branch,
              subPath: typeof body.subPath === 'string' ? body.subPath : projectConfig.semanticLayer?.subPath,
              source: body.repoUrl || projectConfig.semanticLayer?.repoUrl
                ? ((body.source ?? projectConfig.semanticLayer?.source ?? 'github') as 'local' | 'github' | 'gitlab')
                : 'local',
            };
        const executeQuery = provider === 'snowflake'
          ? async (sql: string) => {
              const result = await executor.executeQuery(sql, [], {}, requireActiveConnection());
              return { rows: result.rows };
            }
          : undefined;
        const preview = await previewSemanticImport({
          targetProjectRoot: projectRoot,
          provider,
          sourceConfig,
          executeQuery,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(preview));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        const hint = message.includes('dbt_project.yml')
          ? 'Ensure your dbt project path contains a valid dbt_project.yml file.'
          : message.includes('model/') || message.includes('schema/')
            ? 'Ensure your Cube.js project has a model/ or schema/ directory.'
            : message.includes('query executor')
              ? 'A Snowflake connection is required. Configure one in the Connection panel first.'
              : 'Check the provider path and ensure the source files are accessible.';
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: message, hint }));
      }
      return;
    }

    // ── Semantic layer sync diff preview ────────────────────────────────
    if (req.method === 'POST' && path === '/api/semantic-layer/sync-preview') {
      try {
        const executeQuery = semanticImportManifest?.provider === 'snowflake'
          ? async (sql: string) => {
              const result = await executor.executeQuery(sql, [], {}, requireActiveConnection());
              return { rows: result.rows };
            }
          : undefined;
        const diff = await computeSyncDiff({
          targetProjectRoot: projectRoot,
          executeQuery,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(diff));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/semantic-layer/search') {
      if (!semanticLayer) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ metrics: [], measures: [], dimensions: [], timeDimensions: [], entities: [], hierarchies: [], semanticModels: [], savedQueries: [] }));
        return;
      }
      const q = url.searchParams.get('q') ?? '';
      const domain = url.searchParams.get('domain') ?? '';
      const tag = url.searchParams.get('tag') ?? '';
      const type = url.searchParams.get('type') ?? '';
      const results = semanticLayer.searchAdvanced(q, {
        domains: domain ? [domain] : undefined,
        tags: tag ? [tag] : undefined,
        types: ['metric', 'measure', 'dimension', 'hierarchy', 'entity', 'semantic_model', 'saved_query'].includes(type) ? [type as any] : undefined,
      });
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        metrics: results.metrics.map((m) => ({
          name: m.name,
          label: m.label,
          description: m.description,
          domain: m.domain,
          sql: m.sql,
          type: m.type,
          table: m.table,
          tags: m.tags ?? [],
          owner: m.owner ?? null,
        })),
        measures: results.measures.map((m) => ({
          name: m.name,
          label: m.label,
          description: m.description,
          domain: m.domain,
          agg: m.agg,
          expr: m.expr,
          table: m.table,
          cube: m.cube,
          tags: m.tags ?? [],
          owner: m.owner ?? null,
        })),
        dimensions: results.dimensions.map((d) => ({
          name: d.name,
          label: d.label,
          description: d.description,
          domain: d.domain,
          sql: d.sql,
          type: d.type,
          table: d.table,
          cube: d.cube ?? null,
          reference: semanticDimensionReference(d),
          qualifiedName: d.qualifiedName ?? null,
          entityLink: d.entityLink ?? null,
          canonicalId: `semantic:${d.domain || 'uncategorized'}:dimension:${semanticDimensionReference(d)}`,
          tags: d.tags ?? [],
          owner: d.owner ?? null,
        })),
        timeDimensions: semanticLayer.listTimeDimensions(undefined, { includeVariants: true }).filter((d) =>
          results.dimensions.some((dim) => semanticDimensionReference(dim) === semanticDimensionReference(d))
        ).map((d) => ({
          name: d.name,
          label: d.label,
          description: d.description,
          domain: d.domain,
          sql: d.sql,
          type: d.type,
          table: d.table,
          cube: d.cube ?? null,
          reference: semanticDimensionReference(d),
          qualifiedName: d.qualifiedName ?? null,
          entityLink: d.entityLink ?? null,
          canonicalId: `semantic:${d.domain || 'uncategorized'}:dimension:${semanticDimensionReference(d)}`,
          tags: d.tags ?? [],
          owner: d.owner ?? null,
        })),
        entities: results.entities.map((e) => ({
          name: e.name,
          label: e.label,
          description: e.description,
          domain: e.domain,
          type: e.type,
          table: e.table,
          tags: e.tags ?? [],
          owner: e.owner ?? null,
        })),
        hierarchies: results.hierarchies.map((h) => ({
          name: h.name,
          label: h.label,
          description: h.description,
          domain: h.domain,
          levels: h.levels.map((l) => ({ name: l.name, label: l.label })),
        })),
        semanticModels: results.semanticModels.map((m) => ({
          name: m.name,
          label: m.label,
          description: m.description,
          domain: m.domain,
          table: m.table,
          measures: m.measures,
          dimensions: m.dimensions,
          timeDimensions: m.timeDimensions,
        })),
        savedQueries: results.savedQueries.map((q) => ({
          name: q.name,
          label: q.label,
          description: q.description,
          domain: q.domain,
          metrics: q.metrics,
          dimensions: q.dimensions,
        })),
      }));
      return;
    }
    if (req.method === 'GET' && path === '/api/semantic-layer/compatible-dims') {
      if (!semanticLayer) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ dimensions: [] }));
        return;
      }
      const metrics = (url.searchParams.get('metrics') ?? '')
        .split(',')
        .map((value) => value.trim())
        .filter(Boolean);
      try {
        const compat = await describeRuntimeCompatibility(projectRoot, semanticLayer, metrics, projectConfig);
        const dimensions = compat.dimensions.map((d) => ({
          name: d.name,
          label: d.label,
          description: d.description,
          domain: d.domain,
          sql: d.sql,
          type: d.type,
          table: d.table,
          tags: d.tags ?? [],
          owner: d.owner ?? null,
          cube: d.cube ?? null,
          reference: semanticDimensionReference(d),
          entityLink: d.entityLink ?? null,
          canonicalId: `semantic:${d.domain || 'uncategorized'}:dimension:${semanticDimensionReference(d)}`,
          // Additive: qualified name, real grains, and time flag (existing fields
          // above are byte-identical for compatibility).
          qualifiedName: d.qualifiedName ?? null,
          granularities: d.granularities ?? (d as { granularities?: string[] }).granularities ?? null,
          isTimeDimension: Boolean((d as { isTimeDimension?: boolean }).isTimeDimension),
        }));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          dimensions,
          engine: compat.engine,
          incompatible: compat.incompatible,
          degraded: compat.degraded ?? null,
        }));
      } catch (error) {
        const code = semanticRuntimeErrorCode(error) ?? 'SEMANTIC_COMPATIBILITY_FAILED';
        res.writeHead(code === 'SEMANTIC_SOURCE_DRIFT' ? 409 : 400, {
          'Content-Type': 'application/json; charset=utf-8',
        });
        res.end(serializeJSON(apiErrorEnvelope({
          requestId: apiRequestId('semantic-compatible-dimensions'),
          code,
          message: apiErrorMessage(error),
          recoverable: true,
          details: semanticRuntimeErrorDetails(error),
          nextActions: code === 'SEMANTIC_SOURCE_DRIFT'
            ? ['Deploy the intended dbt semantic project.', 'Reapply dbt Cloud Semantic Layer settings.']
            : ['Check the selected semantic runtime and retry.'],
        })));
      }
      return;
    }
    if (req.method === 'GET' && path === '/api/user-prefs/favorites') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ favorites: readUserPrefs(userPrefsPath).favorites }));
      return;
    }
    if (req.method === 'POST' && path === '/api/user-prefs/favorites') {
      try {
        const body = await readJSON(req);
        const prefs = readUserPrefs(userPrefsPath);
        const name = typeof body.name === 'string' ? body.name.trim() : '';
        if (name) {
          prefs.favorites = prefs.favorites.includes(name)
            ? prefs.favorites.filter((item) => item !== name)
            : [...prefs.favorites, name].sort((a, b) => a.localeCompare(b));
          writeUserPrefs(userPrefsPath, prefs);
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ favorites: prefs.favorites }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }
    if (req.method === 'GET' && path === '/api/user-prefs/recent') {
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ recentlyUsed: readUserPrefs(userPrefsPath).recentlyUsed }));
      return;
    }
    if (req.method === 'POST' && path === '/api/user-prefs/recent') {
      try {
        const body = await readJSON(req);
        const prefs = readUserPrefs(userPrefsPath);
        const name = typeof body.name === 'string' ? body.name.trim() : '';
        if (name) {
          prefs.recentlyUsed = [name, ...prefs.recentlyUsed.filter((item) => item !== name)].slice(0, 12);
          writeUserPrefs(userPrefsPath, prefs);
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ recentlyUsed: prefs.recentlyUsed }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }
    // ── Ranked, lazy editor completions (large-repo safe) ───────────────────────
    if (req.method === "GET" && path === "/api/editor/completions") {
      const query = (url.searchParams.get("q") ?? "").trim().toLowerCase();
      const kind = (url.searchParams.get("kind") ?? "all").trim().toLowerCase();
      const relationFilter = (url.searchParams.get("relation") ?? "")
        .trim()
        .toLowerCase();
      const selectedDomain = (url.searchParams.get("domain") ?? "")
        .trim()
        .toLowerCase();
      const limit = Math.max(
        1,
        Math.min(100, Number(url.searchParams.get("limit") ?? 50) || 50),
      );
      const recent = readUserPrefs(userPrefsPath).recentlyUsed.map((name) =>
        name.toLowerCase(),
      );
      const candidates: Array<{
        type: string;
        name: string;
        label: string;
        description: string;
        detail?: string;
        domain?: string;
        tags?: string[];
        relation?: string;
        governance?: string;
        apply?: string;
        score?: number;
      }> = [];
      if (semanticLayer && (kind === "all" || kind === "metric")) {
        for (const metric of semanticLayer.listMetrics(undefined, { includeMeasures: false }))
          candidates.push({
            type: "metric",
            name: metric.name,
            label: metric.label,
            description: metric.description ?? "",
            domain: metric.domain,
            tags: metric.tags ?? [],
            detail: "@metric",
            apply: metric.name,
            governance: "semantic",
          });
      }
      if (semanticLayer && (kind === "all" || kind === "dimension")) {
        for (const dimension of semanticLayer.listDimensions(undefined, { includeVariants: true }))
          candidates.push({
            type: "dimension",
            name: semanticDimensionReference(dimension),
            label: dimension.label,
            description: dimension.description ?? "",
            domain: dimension.domain,
            tags: dimension.tags ?? [],
            detail: `${dimension.cube ?? dimension.table} · @dim`,
            apply: semanticDimensionReference(dimension),
            governance: "semantic",
          });
      }
      const datasets = datasetWorkspace.list();
      if (kind === "all" || kind === "relation" || kind === "dataset") {
        for (const dataset of datasets)
          candidates.push({
            type: kind === "dataset" ? "dataset" : "relation",
            name: dataset.alias,
            label: dataset.name,
            description: `${dataset.storageMode} ${dataset.format} · refreshed ${dataset.refreshedAt}`,
            relation: dataset.alias,
            detail: dataset.trustState,
            apply: `"${dataset.alias.replaceAll('"', '""')}"`,
            governance: dataset.trustState,
          });
      }
      if (kind === "all" || kind === "column") {
        for (const dataset of datasets) {
          if (
            relationFilter &&
            ![dataset.id, dataset.alias, dataset.name].some(
              (value) => value.toLowerCase() === relationFilter,
            )
          )
            continue;
          for (const column of dataset.profile.columns)
            candidates.push({
              type: "column",
              name: column.name,
              label: column.name,
              description: column.flags?.join(", ") ?? "",
              relation: dataset.alias,
              detail: column.type,
              apply: column.name,
              governance: dataset.trustState,
            });
        }
        const snapshot = latestRuntimeSchemaSnapshotForProject(projectRoot);
        for (const table of snapshot?.tables ?? []) {
          if (
            relationFilter &&
            ![table.relation, table.name]
              .filter(Boolean)
              .some(
                (value) =>
                  value!.toLowerCase() === relationFilter ||
                  value!.toLowerCase().endsWith(`.${relationFilter}`),
              )
          )
            continue;
          for (const column of table.columns)
            candidates.push({
              type: "column",
              name: column.name,
              label: column.name,
              description: column.description ?? "",
              relation: table.relation,
              detail: column.type,
              apply: column.name,
              governance: "runtime_schema",
            });
        }
      }
      if (kind === "all" || kind === "relation") {
        const snapshot = latestRuntimeSchemaSnapshotForProject(projectRoot);
        for (const table of snapshot?.tables ?? [])
          candidates.push({
            type: "relation",
            name: table.relation,
            label: table.name ?? table.relation,
            description: table.description ?? "",
            relation: table.relation,
            detail: table.schema,
            apply: table.relation,
            governance: table.source ?? "runtime_schema",
          });
      }
      if (kind === "all" || kind === "block") {
        for (const file of scanNotebookFiles(projectRoot).filter(
          (entry) => entry.type === "block",
        ))
          candidates.push({
            type: "block",
            name: file.name.replace(/\.dql$/i, ""),
            label: file.name.replace(/\.dql$/i, ""),
            description: file.path,
            detail: "@block",
            apply: `@block("${file.name.replace(/\.dql$/i, "")}")`,
            governance: file.path.includes("_draft") ? "draft" : "governed",
          });
      }
      if (kind === "all" || kind === "connection") {
        for (const name of Object.keys(
          getStoredConnections(
            projectConfig as unknown as Record<string, unknown>,
          ),
        ))
          candidates.push({
            type: "connection",
            name,
            label: name,
            description: "Configured connection",
            detail:
              name === projectConfig.defaultConnectionName
                ? "default"
                : undefined,
            apply: name,
          });
      }
      const uniqueCandidates = [
        ...new Map(
          candidates.map((candidate) => [
            `${candidate.type}:${candidate.name.toLowerCase()}:${candidate.relation?.toLowerCase() ?? ""}`,
            candidate,
          ]),
        ).values(),
      ];
      const scored = uniqueCandidates
        .map((candidate) => {
          const name = candidate.name.toLowerCase();
          const label = candidate.label.toLowerCase();
          const haystack = `${name} ${label} ${candidate.description.toLowerCase()} ${(candidate.tags ?? []).join(" ").toLowerCase()} ${candidate.domain?.toLowerCase() ?? ""}`;
          let score = query
            ? name === query
              ? 100
              : name.startsWith(query)
                ? 80
                : label.startsWith(query)
                  ? 70
                  : haystack.includes(query)
                    ? 40
                    : 0
            : 10;
          if (
            selectedDomain &&
            candidate.domain?.toLowerCase() === selectedDomain
          )
            score += 20;
          if (recent.includes(name)) score += 15;
          if (
            candidate.governance === "certified" ||
            candidate.governance === "semantic" ||
            candidate.governance === "project_controlled"
          )
            score += 10;
          return { ...candidate, score };
        })
        .filter((candidate) => !query || (candidate.score ?? 0) > 0)
        .sort(
          (a, b) =>
            (b.score ?? 0) - (a.score ?? 0) || a.name.localeCompare(b.name),
        )
        .slice(0, limit);
      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
      res.end(
        serializeJSON({
          completions: scored,
          query,
          kind,
          limit,
          totalCandidates: uniqueCandidates.length,
        }),
      );
      return;
    }

    // ── Legacy semantic completion endpoint ────────────────────────────────────
    if (req.method === "GET" && path === "/api/semantic-completions") {
      const completions: Array<{
        type: string;
        name: string;
        label: string;
        description: string;
        sql: string;
        domain?: string;
        tags: string[];
      }> = [];
      if (semanticLayer) {
        for (const m of semanticLayer.listMetrics(undefined, { includeMeasures: false })) {
          completions.push({
            type: 'metric',
            name: m.name,
            label: m.label,
            description: m.description ?? '',
            sql: m.sql,
            domain: m.domain,
            tags: m.tags ?? [],
          });
        }
        for (const d of semanticLayer.listDimensions()) {
          completions.push({
            type: 'dimension',
            name: d.name,
            label: d.label,
            description: d.description ?? '',
            sql: d.sql,
            domain: d.domain,
            tags: d.tags ?? [],
          });
        }
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({ completions }));
      return;
    }
    // ── end dql-notebook API ──────────────────────────────────────────────────

    // GET /api/describe-table?table=schema.table — returns columns for a specific table
    if (req.method === 'GET' && path === '/api/describe-table') {
      try {
        const requestedRelation = url.searchParams.get('relation')?.trim() ?? '';
        const legacyTable = url.searchParams.get('table')?.trim() ?? '';
        const legacySchema = url.searchParams.get('schema')?.trim() ?? '';
        const relationParts = splitQualifiedRelationIdentifier(
          requestedRelation || [legacySchema, legacyTable].filter(Boolean).join('.'),
        );
        if (!relationParts?.length) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'A safe dbt relation is required.' }));
          return;
        }
        const tablePath = relationParts.at(-1)!;
        const schemaName = relationParts.length > 1 ? relationParts.slice(0, -1).join('.') : undefined;
        // Try connector.listColumns() first
        let columns: Array<{ name: string; type: string }> = [];
        const activeConnection = connection;
        try {
          if (!activeConnection) throw new Error('No active connection');
          const connector = await executor.getConnector(activeConnection);
          if (typeof connector.listColumns === 'function') {
            // Connector contracts accept one schema plus one table. For a
            // three-part dbt relation, the active connection owns the database
            // and the final namespace segment is the schema.
            const connectorSchema = schemaName?.split('.').filter(Boolean).at(-1);
            const rawCols = await connector.listColumns(connectorSchema, tablePath);
            columns = rawCols.map((c) => ({ name: c.name, type: c.dataType }));
          }
        } catch {
          // fallback below
        }
        // Fallback: DESCRIBE via SQL (works for DuckDB, PG)
        if (columns.length === 0) {
          try {
            const isFile = /\.(csv|parquet|json)$/i.test(tablePath) || tablePath.startsWith('data/');
            const safePath = tablePath.replace(/'/g, "''");
            if (!activeConnection) throw new Error('No active connection');
            const dialect = getDialect(activeConnection.driver);
            const qualifiedIdentifier = relationParts.map((part) => dialect.quoteIdentifier(part)).join('.');
            const sql = isFile
              ? `DESCRIBE SELECT * FROM read_csv_auto('${safePath}') LIMIT 0`
              : `DESCRIBE ${qualifiedIdentifier}`;
            const result = await executor.executeQuery(sql, [], {}, activeConnection);
            columns = schemaColumnsFromDescribeRows(result.rows);
          } catch {
            // empty columns
          }
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(columns));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/llm/run') {
      const body = await readJSON(req).catch(() => null);
      if (!body || typeof body !== 'object') {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Invalid JSON body' }));
        return;
      }
      const { provider, messages, upstream, conversationContext } = body as {
        provider?: string;
        messages?: Array<{ role: 'user' | 'assistant'; content: string }>;
        upstream?: { cellId?: string; sql?: string };
        conversationContext?: unknown;
      };
      const resolvedProvider = isLLMProviderId(provider) ? provider : resolveDefaultLLMProvider(projectRoot);
      if (!resolvedProvider) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'No AI provider is configured. Configure OpenAI, Gemini, Ollama, or a custom OpenAI-compatible endpoint in Settings.' }));
        return;
      }
      if (!Array.isArray(messages) || messages.length === 0) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'messages[] required' }));
        return;
      }
      res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache, no-transform',
        Connection: 'keep-alive',
      });
      const controller = new AbortController();
      req.on('close', () => controller.abort());
      const emit = (turn: unknown) => { res.write(`data: ${JSON.stringify(turn)}\n\n`); };
      try {
        // The raw runner endpoint answers through the Ask pipeline like every
        // other analytical surface; its SSE contract (a governed_answer tool
        // result, then the answer text) is unchanged.
        const question = [...messages].reverse().find((message) => message.role === 'user')?.content?.trim() ?? '';
        const answer = await runGovernedAgentAnswerForRun({
          question,
          requestedMode: 'ask',
          signal: controller.signal,
          workspaceContext: { surface: 'notebook', ...(upstream?.cellId ? { cellId: upstream.cellId } : {}), ...(upstream?.sql ? { upstreamSql: upstream.sql } : {}) },
          ...(conversationContext && typeof conversationContext === 'object' && !Array.isArray(conversationContext) ? { conversationContext: conversationContext as AgentRunRequest['conversationContext'] } : {}),
        } as AgentRunRequest, undefined, 'generated_answer', (message) => emit({ kind: 'thinking', text: message }));
        emit({ kind: 'tool_result', id: 'governed_answer', output: answer });
        emit({ kind: 'text', text: answer.answer ?? answer.text });
      } catch (err) {
        emit({ kind: 'error', message: err instanceof Error ? err.message : String(err) });
      }
      res.end();
      return;
    }

    if (req.method === 'POST' && path === '/api/ai/sql-draft/preview') {
      try {
        const body = await readJSON(req);
        if (typeof body.sql !== 'string' || body.sql.trim().length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing SQL in request body.' }));
          return;
        }
        const previewSql = buildAgentPreviewSql(body.sql);
        // The preview runs where the notebook runs: its execution target, not
        // whatever connection happens to be active.
        const result = await executeLocalSqlForStoredResult(previewSql, await resolveExecutionConnection(body as Record<string, unknown>));
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, result }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: false,
          error: error instanceof Error ? error.message : String(error),
        }));
      }
      return;
    }

    /**
     * Repair an editable notebook cell or Block Studio draft without starting
     * an AI conversation. The returned source is applied only to the in-memory
     * editor by the client; this endpoint never writes governed source files.
     */
    if (req.method === 'POST' && (
      path === '/api/notebook/repair-execution'
      || path === '/api/block-studio/repair-and-run'
    )) {
      let body: Record<string, unknown> = {};
      let execContext: NotebookExecutionContextInput | null = null;
      const start = Date.now();
      try {
        body = await readJSON(req) as Record<string, unknown>;
        execContext = notebookExecutionContext(body.executionContext);
        const cell = normalizeNotebookCell(body.cell);
        if (!cell || (cell.type !== 'sql' && cell.type !== 'dql')) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'An editable SQL or DQL notebook cell is required.' }));
          return;
        }
        if (cell.type === 'dql' && /^\s*@block\(/i.test(cell.source)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Customize the bound block as a notebook copy before repairing it.' }));
          return;
        }
        const embeddedSourceSql = notebookCellRepairSql(cell);
        if (!embeddedSourceSql && (cell.type !== 'dql' || !notebookDqlSourceAllowsBackgroundRepair(cell.source))) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Background repair supports SQL cells and editable custom DQL blocks. Open governed references or semantic definitions in their owning editor.' }));
          return;
        }
        if (cell.type === 'sql' && /\{\{[^}]+\}\}/.test(cell.source)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Run or repair the referenced upstream cell before repairing this dependent query.' }));
          return;
        }

        const targetConnection = await resolveExecutionConnection(body);
        const submittedError = typeof body.error === 'string' ? body.error.trim() : '';
        const submittedFailure = body.failure && typeof body.failure === 'object' && !Array.isArray(body.failure)
          ? body.failure as Record<string, unknown>
          : undefined;
        const failureCode = typeof submittedFailure?.code === 'string' ? submittedFailure.code : undefined;
        if (!notebookFailureAllowsBackgroundRepair({ code: failureCode, message: submittedError })) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'This failure needs a data, access, parameter, or notebook dependency change and cannot be auto-fixed safely.' }));
          return;
        }
        const retainedFailure = submittedError
          ? normalizeWarehouseSqlFailure({ code: failureCode, message: submittedError }, targetConnection.driver)
          : undefined;
        if (!analyticalFailureAllowsDeterministicRetry(retainedFailure)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            error: 'This failure requires authorized access or a policy change and cannot be repaired in the background.',
            warehouseFailure: retainedFailure,
          }));
          return;
        }

        const parameters = body.parameters && typeof body.parameters === 'object' && !Array.isArray(body.parameters)
          ? body.parameters as Record<string, unknown>
          : {};
        let invocation: ReturnType<typeof prepareBlockInvocation> | null = null;
        let plan: ReturnType<typeof buildExecutionPlan> = null;
        let dqlCompilationError: string | undefined;
        if (cell.type === 'dql') {
          try {
            invocation = prepareBlockInvocation({ source: cell.source, parameters, surface: 'notebook' });
            if (invocation.errors.length) throw boundedRepairError(invocation.errors.join(' '), 409);
            if (invocation.unresolvedParameters.length) {
              throw boundedRepairError(
                `Provide required parameter${invocation.unresolvedParameters.length === 1 ? '' : 's'} before retrying: ${invocation.unresolvedParameters.join(', ')}.`,
                409,
              );
            }
            plan = buildExecutionPlan(cell, {
              semanticLayer,
              driver: targetConnection.driver,
              parameters: invocation.values,
            });
          } catch (error) {
            const repairError = error as Error & { status?: number };
            if (repairError.status === 409) throw error;
            dqlCompilationError = repairError.message || String(error);
          }
        }
        const attemptedSql = typeof body.attemptedSql === 'string' && body.attemptedSql.trim()
          ? body.attemptedSql.trim()
          : embeddedSourceSql;

        const executionTarget = executionTargetDescriptor(body);
        const targetConnectionName = executionTarget.target === 'connection'
          ? executionTarget.connectionName
          : executionTarget.target === 'local'
            ? 'local'
            : projectConfig.defaultConnectionName;
        const question = [
          `Repair notebook cell ${cell.title?.trim() || cell.id}.`,
          submittedError ? `Failure: ${submittedError.slice(0, 1_000)}` : '',
        ].filter(Boolean).join(' ');
        let repaired: BoundedSqlRepairResult | BoundedDqlRepairResult;
        let repairedSource: string | undefined;
        if (cell.type === 'dql' && dqlCompilationError) {
          const repairedDql = await executeBoundedDqlRepair({
            question,
            source: cell.source,
            failure: [submittedError, dqlCompilationError].filter(Boolean).join('\n'),
            targetConnection,
            targetConnectionName,
            parameters,
            artifactName: cell.title,
          });
          repaired = repairedDql;
          repairedSource = repairedDql.repairedSource;
        } else {
          const sourceSql = plan?.sql ?? attemptedSql;
          if (!sourceSql?.trim()) {
            throw boundedRepairError('DQL could not identify an embedded query to repair.', 422);
          }
          const sqlParams = plan?.sqlParams ?? [];
          repaired = await executeBoundedSqlRepair({
            question,
            sourceSql,
            targetConnection,
            targetConnectionName,
            sqlParams,
            variables: {
              ...(plan?.variables ?? {}),
              ...(invocation?.values ?? {}),
            },
          });
          if (cell.type === 'dql') {
            const originalQuery = notebookCellRepairSql(cell)!;
            const repairedQuery = repaired.repairMode === 'deterministic'
              ? applyNotebookRepairRewrites(originalQuery, repaired.rewrites)
              : restoreNotebookDqlParameterInterpolations(repaired.repairedSql, sqlParams);
            repairedSource = replaceNotebookDqlQueryForRepair(cell.source, repairedQuery);
          } else {
            repairedSource = repaired.repairedSql;
          }
        }
        if (!repairedSource) {
          throw boundedRepairError('DQL could not safely replace the embedded query in this cell.', 422);
        }

        // Prove the repaired DQL wrapper still compiles. SQL execution above
        // already proved the corrected statement on the selected target.
        if (cell.type === 'dql') {
          const validationPlan = buildExecutionPlan({ ...cell, source: repairedSource }, {
            semanticLayer,
            driver: targetConnection.driver,
            parameters: invocation?.values ?? parameters,
          });
          if (!validationPlan?.sql) {
            throw boundedRepairError('The repaired SQL ran, but the DQL wrapper no longer compiles.', 422);
          }
          const beforeParameters = (plan?.sqlParams ?? ('sqlParams' in repaired ? repaired.sqlParams : []))
            .map((parameter) => `${parameter.position}:${parameter.name}`);
          const afterParameters = validationPlan.sqlParams.map((parameter) => `${parameter.position}:${parameter.name}`);
          if (beforeParameters.join('|') !== afterParameters.join('|')) {
            throw boundedRepairError('The repaired DQL changed the cell parameter contract, so the update was stopped.', 422);
          }
        }

        if (execContext?.notebookPath) {
          recordNotebookQueryRun(projectRoot, {
            notebookPath: execContext.notebookPath,
            cellId: execContext.cellId ?? cell.id,
            cellName: execContext.cellName ?? cell.title,
            source: execContext.source ?? (cell.type === 'dql' ? 'notebook_dql_cell' : 'notebook_sql_cell'),
            status: 'success',
            rowCount: repaired.result.rowCount ?? repaired.result.rows.length,
            durationMs: Date.now() - start,
            sql: repaired.repairedSql,
          });
        }

        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: true,
          source: repairedSource,
          repairedSql: repaired.repairedSql,
          repairMode: repaired.repairMode,
          result: repaired.result,
          executionTarget,
          executionContext: notebookExecutionIdentity(execContext, cell.id),
          compiledSql: repaired.repairedSql,
          executedSql: repaired.result.sql ?? repaired.repairedSql,
          executionReceipt: repaired.result.executionReceipt,
        }));
      } catch (error) {
        const repairError = error as Error & { status?: number; warehouseFailure?: WarehouseSqlFailureV1 };
        if (execContext?.notebookPath) {
          recordNotebookQueryRun(projectRoot, {
            notebookPath: execContext.notebookPath,
            cellId: execContext.cellId,
            cellName: execContext.cellName,
            source: execContext.source ?? 'notebook_cell_repair',
            status: 'error',
            durationMs: Date.now() - start,
            errorCode: repairError.warehouseFailure?.category ?? repairError.message,
            sql: typeof body.attemptedSql === 'string' ? body.attemptedSql : undefined,
          });
        }
        res.writeHead(repairError.status ?? 500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          error: repairError.message,
          ...(repairError.warehouseFailure ? { warehouseFailure: repairError.warehouseFailure } : {}),
        }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/query') {
      let body: any;
      let execContext: NotebookExecutionContextInput | null = null;
      const start = Date.now();
      try {
        body = await readJSON(req);
        execContext = notebookExecutionContext(body.executionContext);
        if (typeof body.sql !== 'string' || body.sql.trim().length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            columns: [],
            rows: [],
            error: 'Missing SQL in request body.',
            code: 'COMPILATION_FAILED',
            details: {
              phase: 'compilation',
              executionContext: notebookExecutionIdentity(execContext),
              executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
            },
          }));
          return;
        }
        const executionConnection = await resolveExecutionConnection(
          body as Record<string, unknown>,
        );
        const tableMapping = hasStandaloneSemanticRef(body.sql)
          ? await resolveSemanticTableMapping(executor, executionConnection, semanticLayer, projectRoot)
          : undefined;
        const semantic = prepareSemanticSql(body.sql, semanticLayer, { tableMapping });
        if (semantic.unresolvedRefs.length > 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            columns: [],
            rows: [],
            error: `Unknown semantic reference${semantic.unresolvedRefs.length > 1 ? 's' : ''}: ${semantic.unresolvedRefs.join(', ')}`,
            code: 'semantic_ref',
            unresolvedRefs: semantic.unresolvedRefs,
            details: {
              phase: 'compilation',
              executionContext: notebookExecutionIdentity(execContext),
              executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
            },
          }));
          return;
        }
        const app = loadRuntimeApp(projectRoot, typeof body.appId === 'string' ? body.appId : activePersonaAppId());
        const domain = typeof body.domain === 'string' ? body.domain : app?.domain;
        assertAppAccess({ app, domain, level: 'execute' });
        const execution = await analyticalExecutionService.execute({
          sql: semantic.sql,
          subject: 'Notebook query',
          connection: executionConnection,
          sqlParams: Array.isArray(body.sqlParams) ? body.sqlParams : [],
          variables: body.variables && typeof body.variables === 'object' ? body.variables : {},
          semanticRefs: semantic.semanticRefs,
        });
        const { preparation, result: normalized } = execution;
        if (execContext?.notebookPath) {
          recordNotebookQueryRun(projectRoot, {
            notebookPath: execContext.notebookPath!,
            cellId: execContext.cellId,
            cellName: execContext.cellName,
            researchRunId: execContext.researchRunId,
            source: execContext.source ?? 'notebook_sql_cell',
            status: 'success',
            rowCount: normalized.rowCount ?? normalized.rows.length,
            durationMs: Date.now() - start,
            sql: body.sql,
          });
          updateNotebookResearchFromCellExecution(projectRoot, execContext, {
            status: 'success',
            resultPreview: normalized,
            sql: body.sql,
          });
        }
        const payload = serializeJSON({
          ...normalized,
          executionContext: notebookExecutionIdentity(execContext),
          executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
          compiledSql: preparation.decodedSql,
          executedSql: preparation.executedSql,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(payload);
      } catch (error) {
        if (res.headersSent || res.writableEnded) {
          res.end();
          return;
        }
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            columns: [],
            rows: [],
            error: error.message,
            code: 'unauthorized',
            details: {
              phase: 'execution',
              executionContext: notebookExecutionIdentity(execContext),
              executionTarget: executionTargetDescriptor(
                body && typeof body === 'object' ? body as Record<string, unknown> : {},
              ),
            },
          }));
          return;
        }
        if (execContext?.notebookPath) {
          recordNotebookQueryRun(projectRoot, {
            notebookPath: execContext.notebookPath!,
            cellId: execContext.cellId,
            cellName: execContext.cellName,
            researchRunId: execContext.researchRunId,
            source: execContext.source ?? 'notebook_sql_cell',
            status: 'error',
            durationMs: Date.now() - start,
            errorCode: error instanceof Error ? error.message : String(error),
            sql: typeof body?.sql === 'string' ? body.sql : undefined,
          });
          updateNotebookResearchFromCellExecution(projectRoot, execContext, {
            status: 'error',
            error: error instanceof Error ? error.message : String(error),
            sql: typeof body?.sql === 'string' ? body.sql : undefined,
          });
        }
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          columns: [],
          rows: [],
          error: error instanceof Error ? error.message : String(error),
          code: classifyAnalyticalFailure(error),
          details: {
            phase: 'execution',
            executionContext: notebookExecutionIdentity(execContext),
            executionTarget: executionTargetDescriptor(
              body && typeof body === 'object' ? body as Record<string, unknown> : {},
            ),
          },
        }));
      }
      return;
    }

    // Semantic layer query endpoint: compose SQL from metrics/dimensions
    if (req.method === 'POST' && path === '/api/semantic-query') {
      try {
        if (!semanticLayer) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'No semantic layer configured. Add YAML files to semantic-layer/ directory.' }));
          return;
        }
        const body = await readJSON(req);
        const { metrics = [], dimensions = [], filters = [], limit, timeDimension, orderBy, savedQuery, engine } = body as {
          metrics: string[];
          dimensions: string[];
          filters?: Array<{ dimension: string; operator: string; values: string[]; expression?: string }>;
          timeDimension?: { name: string; granularity: string };
          orderBy?: Array<{ name: string; direction: 'asc' | 'desc' }>;
          limit?: number;
          savedQuery?: string;
          engine?: SemanticRuntimeQueryRequest['engine'];
        };
        // Resolve which connection to use — request can override default
        const targetConnection = await resolveExecutionConnection(body as Record<string, unknown>);
        const plannedAdapter = await resolvePlannedSemanticAdapter(projectRoot, engine);
        const metricFlow = plannedAdapter === 'metricflow-cli'
          ? resolveMetricFlowTargetMetadata(projectRoot, projectConfig)
          : undefined;
        const execution = await executeTargetBoundSemanticQuery({
          executor,
          connection: targetConnection,
          projectRoot,
          plannedAdapter,
          metricFlow,
          compile: async () => {
            const tableMapping = plannedAdapter === 'native'
              ? await resolveSemanticTableMapping(executor, targetConnection, semanticLayer, projectRoot)
              : undefined;
            return composeRuntimeSemanticQuery({
              metrics,
              dimensions,
              filters,
              limit,
              timeDimension,
              orderBy,
              savedQuery,
              engine: plannedAdapter,
            }, semanticLayer!, {
              projectRoot,
              projectConfig,
              detectedProvider: semanticDetectedProvider,
              driver: targetConnection.driver,
              tableMapping,
            });
          },
          prepareSql: (sql) => prepareLocalExecution(sql, targetConnection, projectRoot, projectConfig),
          rowBound: limit,
        });
        if (!execution) {
          const provider = semanticConfig?.provider ?? semanticDetectedProvider ?? 'dql';
          const semanticRuntime = await getSemanticRuntimeStatus(projectRoot, { probeConfiguredCloud: true });
          const blocked = metrics.map((metricName) => ({
            metric: metricName,
            ...runtimeMetricExecutionCapability(metricName, semanticLayer!, provider, semanticRuntime, projectRoot),
          })).filter((capability) => capability.status !== 'ready');
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            error: blocked.length > 0
              ? blocked.map((capability) => `${capability.metric}: ${capability.reason}`).join(' ')
              : 'The selected dimensions do not share a governed join path with every selected metric.',
            code: blocked.length > 0 ? 'SEMANTIC_RUNTIME_REQUIRED' : 'SEMANTIC_FIELDS_INCOMPATIBLE',
            details: { metrics, dimensions, blocked },
          }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          sql: execution.compiled.sql,
          executedSql: execution.preparedSql,
          tables: execution.compiled.tables,
          joins: execution.compiled.joins,
          engine: execution.compiled.engine,
          effectiveRequest: execution.compiled.effectiveRequest,
          runtimeRequest: execution.compiled.runtimeRequest,
          semanticTrace: execution.semanticTrace,
          warnings: execution.compiled.warnings,
          targetBinding: execution.targetBinding,
          executionReceipt: execution.executionReceipt,
          result: normalizeQueryResult(execution.result),
        }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: error.message, code: 'unauthorized' }));
          return;
        }
        const runtimeCode = semanticExecutionFailureCode(error) ?? semanticRuntimeErrorCode(error);
        const status = runtimeCode === 'EXECUTION_TARGET_MISMATCH' || runtimeCode === 'SEMANTIC_SOURCE_DRIFT'
          ? 409
          : runtimeCode
            ? 400
            : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          error: error instanceof Error ? error.message : String(error),
          code: runtimeCode,
          details: semanticExecutionFailureDetails(error) ?? semanticRuntimeErrorDetails(error),
          hint: runtimeCode === 'SEMANTIC_RUNTIME_REQUIRED'
            ? 'Configure dbt Cloud Semantic Layer in Project & dbt settings, or install a compatible local MetricFlow runtime.'
            : runtimeCode === 'SEMANTIC_SOURCE_DRIFT'
              ? 'Deploy the intended dbt semantic project, then reapply dbt Cloud Semantic Layer settings to refresh its metric inventory.'
            : undefined,
        }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/semantic-builder/preview') {
      try {
        if (!semanticLayer) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'No semantic layer configured.' }));
          return;
        }
        const body = await readJSON(req);
        const { metrics = [], dimensions = [], filters = [], limit, timeDimension, orderBy, savedQuery, engine } = body as {
          metrics: string[];
          dimensions: string[];
          filters?: Array<{ dimension: string; operator: string; values: string[]; expression?: string }>;
          timeDimension?: { name: string; granularity: string };
          orderBy?: Array<{ name: string; direction: 'asc' | 'desc' }>;
          limit?: number;
          savedQuery?: string;
          engine?: SemanticRuntimeQueryRequest['engine'];
        };
        const targetConnection = await resolveExecutionConnection(body as Record<string, unknown>);
        const plannedAdapter = await resolvePlannedSemanticAdapter(projectRoot, engine);
        const metricFlow = plannedAdapter === 'metricflow-cli'
          ? resolveMetricFlowTargetMetadata(projectRoot, projectConfig)
          : undefined;
        const execution = await executeTargetBoundSemanticQuery({
          executor,
          connection: targetConnection,
          projectRoot,
          plannedAdapter,
          metricFlow,
          compile: async () => {
            const tableMapping = plannedAdapter === 'native'
              ? await resolveSemanticTableMapping(executor, targetConnection, semanticLayer, projectRoot)
              : undefined;
            return composeRuntimeSemanticQuery({
              metrics,
              dimensions,
              filters,
              limit,
              timeDimension,
              orderBy,
              savedQuery,
              engine: plannedAdapter,
            }, semanticLayer!, {
              projectRoot,
              projectConfig,
              detectedProvider: semanticDetectedProvider,
              driver: targetConnection.driver,
              tableMapping,
            });
          },
          prepareSql: (sql) => prepareLocalExecution(sql, targetConnection, projectRoot, projectConfig),
          rowBound: limit,
        });
        if (!execution) {
          const provider = semanticConfig?.provider ?? semanticDetectedProvider ?? 'dql';
          const semanticRuntime = await getSemanticRuntimeStatus(projectRoot, { probeConfiguredCloud: true });
          const blocked = metrics.map((metricName) => ({
            metric: metricName,
            ...runtimeMetricExecutionCapability(metricName, semanticLayer!, provider, semanticRuntime, projectRoot),
          })).filter((capability) => capability.status !== 'ready');
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            error: blocked.length > 0
              ? blocked.map((capability) => `${capability.metric}: ${capability.reason}`).join(' ')
              : 'The selected dimensions do not share a governed join path with every selected metric.',
            code: blocked.length > 0 ? 'SEMANTIC_RUNTIME_REQUIRED' : 'SEMANTIC_FIELDS_INCOMPATIBLE',
            details: { metrics, dimensions, blocked },
          }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          sql: execution.compiled.sql,
          executedSql: execution.preparedSql,
          joins: execution.compiled.joins,
          tables: execution.compiled.tables,
          engine: execution.compiled.engine,
          effectiveRequest: execution.compiled.effectiveRequest,
          runtimeRequest: execution.compiled.runtimeRequest,
          semanticTrace: execution.semanticTrace,
          warnings: execution.compiled.warnings,
          targetBinding: execution.targetBinding,
          executionReceipt: execution.executionReceipt,
          result: normalizeQueryResult(execution.result),
        }));
      } catch (error) {
        const runtimeCode = semanticExecutionFailureCode(error) ?? semanticRuntimeErrorCode(error);
        const status = runtimeCode === 'EXECUTION_TARGET_MISMATCH' || runtimeCode === 'SEMANTIC_SOURCE_DRIFT'
          ? 409
          : runtimeCode
            ? 400
            : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          error: error instanceof Error ? error.message : String(error),
          code: runtimeCode,
          details: semanticExecutionFailureDetails(error) ?? semanticRuntimeErrorDetails(error),
          hint: runtimeCode === 'SEMANTIC_RUNTIME_REQUIRED'
            ? 'Configure dbt Cloud Semantic Layer in Project & dbt settings, or install a compatible local MetricFlow runtime.'
            : runtimeCode === 'SEMANTIC_SOURCE_DRIFT'
              ? 'Deploy the intended dbt semantic project, then reapply dbt Cloud Semantic Layer settings to refresh its metric inventory.'
            : undefined,
        }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/semantic-builder/save') {
      try {
        if (!semanticLayer) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'No semantic layer configured.' }));
          return;
        }
        const body = await readJSON(req);
        const {
          name,
          domain,
          description,
          owner,
          tags,
          metrics = [],
          dimensions = [],
          timeDimension,
          filters = [],
          chart = 'table',
          blockType = 'semantic',
          engine,
        } = body as {
          name: string;
          domain?: string;
          description?: string;
          owner?: string;
          tags?: string[];
          metrics: string[];
          dimensions: string[];
          timeDimension?: { name: string; granularity: string };
          filters?: Array<{ dimension: string; operator: string; values: string[] }>;
          chart?: string;
          blockType?: 'semantic' | 'custom';
          engine?: SemanticRuntimeQueryRequest['engine'];
        };
        if (!name || metrics.length === 0) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'name and at least one metric are required.' }));
          return;
        }
        if (blockType === 'semantic' && dbtFirstOwnsSemanticAuthoring(projectConfig)) {
          sendDbtOwnedSemanticAuthoringError(res);
          return;
        }
        const targetConnection = await resolveExecutionConnection(body as Record<string, unknown>);
        const tableMapping = await resolveSemanticTableMapping(executor, targetConnection, semanticLayer, projectRoot);
        const composed = await composeRuntimeSemanticQuery({
          metrics,
          dimensions,
          filters,
          timeDimension,
          engine,
        }, semanticLayer, {
          projectRoot,
          projectConfig,
          detectedProvider: semanticDetectedProvider,
          driver: targetConnection.driver,
          tableMapping,
        });
        if (!composed) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Could not compose semantic block SQL.' }));
          return;
        }
        const created = createSemanticBuilderBlock(projectRoot, {
          name,
          domain,
          description,
          owner,
          tags,
          metrics,
          dimensions,
          timeDimension,
          chart,
          blockType,
          sql: composed.sql,
          tables: composed.tables,
          provider: semanticImportManifest?.provider ?? semanticDetectedProvider ?? 'dql',
        });
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(created));
      } catch (error) {
        if (error instanceof Error && error.message === 'BLOCK_EXISTS') {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Block already exists' }));
          return;
        }
        const runtimeCode = semanticRuntimeErrorCode(error);
        const status = runtimeCode ? 400 : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          error: error instanceof Error ? error.message : String(error),
          code: runtimeCode,
          details: semanticRuntimeErrorDetails(error),
          hint: runtimeCode === 'SEMANTIC_RUNTIME_REQUIRED'
            ? 'Configure dbt Cloud Semantic Layer in Project & dbt settings, or install a compatible local MetricFlow runtime.'
            : undefined,
        }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/test-connection') {
      let target: ConnectionConfig | null = connection;
      try {
        const body = await readJSON(req);
        target = normalizeProjectConnection(
          requireActiveConnection(isConnectionConfig(body.connection) ? body.connection : connection),
          projectRoot,
        );
        const connector = await executor.getConnector(target);
        const result = await validateConnectionForTest(connector, target);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          ok: false,
          message: target ? formatConnectionTestError(target, error) : error instanceof Error ? error.message : String(error),
        }));
      }
      return;
    }

    // ---- Lineage API ----
    if (req.method === 'GET' && path === '/api/lineage') {
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(graph.toJSON()));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/lineage/search') {
      const term = url.searchParams.get('q') ?? '';
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const result = queryLineage(graph, { search: term });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ matches: result.matches ?? [] }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/lineage/scope') {
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const result = buildScopedLineage(graph, {
          domain: url.searchParams.get('domain') ?? undefined,
          appId: url.searchParams.get('appId') ?? undefined,
          dashboardId: url.searchParams.get('dashboardId') ?? undefined,
          blockId: url.searchParams.get('blockId') ?? undefined,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/lineage/query') {
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const types = url.searchParams.get('types')
          ?.split(',')
          .map((value) => value.trim())
          .filter(Boolean) as any[] | undefined;
        const upstreamDepthParam = url.searchParams.get('upstreamDepth');
        const downstreamDepthParam = url.searchParams.get('downstreamDepth');
        const result = queryLineage(graph, {
          focus: url.searchParams.get('focus') ?? undefined,
          search: url.searchParams.get('search') ?? undefined,
          types,
          domain: url.searchParams.get('domain') ?? undefined,
          upstreamDepth: upstreamDepthParam ? Number(upstreamDepthParam) : undefined,
          downstreamDepth: downstreamDepthParam ? Number(downstreamDepthParam) : undefined,
        });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/lineage/business-360/')) {
      const rawNodeId = decodeURIComponent(path.slice('/api/lineage/business-360/'.length));
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const result: Business360ResultV2 | null = queryBusiness360(graph, rawNodeId);
        const snapshot = projectSnapshot();
        await ensureMetadataCatalogFresh(projectRoot, { manifest: snapshot.manifest, semanticLayer });
        const knowledge = readIndexedKnowledge360(projectRoot, rawNodeId)
          ?? canonicalKnowledge360(snapshot.manifest, rawNodeId, snapshot.snapshotId);
        if (!result && !knowledge) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Lineage node "${rawNodeId}" not found` }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result ? { ...result, knowledge } : { version: 3, knowledge }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/lineage/node/')) {
      const rawNodeId = decodeURIComponent(path.slice('/api/lineage/node/'.length));
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const node = resolveLineageNode(graph, rawNodeId);
        if (!node) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ node: null, incoming: [], outgoing: [] }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          node,
          incoming: graph.getIncomingEdges(node.id).map((edge) => ({
            edge,
            node: graph.getNode(edge.source),
          })),
          outgoing: graph.getOutgoingEdges(node.id).map((edge) => ({
            edge,
            node: graph.getNode(edge.target),
          })),
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/lineage/domain/')) {
      const domain = decodeURIComponent(path.slice('/api/lineage/domain/'.length));
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const overview = getDomainTrustOverview(graph, domain);
        const nodes = graph.getNodesByDomain(domain);
        const flows = detectDomainFlows(graph);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          domain,
          overview,
          nodes,
          inFlows: flows.filter((f) => f.to === domain),
          outFlows: flows.filter((f) => f.from === domain),
        }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/lineage/impact/')) {
      const blockName = decodeURIComponent(path.slice('/api/lineage/impact/'.length));
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const nodeId = `block:${blockName}`;
        if (!graph.getNode(nodeId)) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Block "${blockName}" not found` }));
          return;
        }
        const impact = analyzeImpact(graph, nodeId);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(impact));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/lineage/block/')) {
      const blockName = decodeURIComponent(path.slice('/api/lineage/block/'.length));
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const nodeId = `block:${blockName}`;
        const node = graph.getNode(nodeId);
        if (!node) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Block "${blockName}" not found` }));
          return;
        }
        const ancestors = graph.ancestors(nodeId);
        const descendants = graph.descendants(nodeId);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ node, ancestors, descendants }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path.startsWith('/api/lineage/paths/')) {
      const rawNodeId = decodeURIComponent(path.slice('/api/lineage/paths/'.length));
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const maxDepth = Number(url.searchParams.get('maxDepth') ?? '10') || 10;
        const maxPaths = Number(url.searchParams.get('maxPaths') ?? '20') || 20;
        const result = queryCompleteLineagePaths(graph, rawNodeId, { maxDepth, maxPaths });
        if (!result) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end('null');
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(result));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/lineage/trust-chain') {
      const from = url.searchParams.get('from');
      const to = url.searchParams.get('to');
      if (!from || !to) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Missing "from" and "to" query parameters' }));
        return;
      }
      try {
        const graph = buildProjectLineageGraph(projectRoot, semanticLayer);
        const chain = buildTrustChain(graph, `block:${from}`, `block:${to}`);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON(chain ?? { error: 'No path found' }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/notebook/bootstrap') {
      const welcomeNotebook = resolveNotebook(projectRoot, projectConfig.project ?? 'DQL Project');
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(serializeJSON({
        projectRoot,
        project: projectConfig.project ?? 'DQL Project',
        defaultConnection: projectConfig.defaultConnection ?? connection,
        connectorForms: getConnectorFormSchemas(),
        files: listProjectFiles(projectRoot),
        notebook: welcomeNotebook,
      }));
      return;
    }

    if (req.method === 'GET' && path === '/api/notebook/file') {
      const relativePath = url.searchParams.get('path');
      if (!relativePath) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: 'Missing file path.' }));
        return;
      }

      const filePath = safeJoin(projectRoot, relativePath);
      if (!filePath || !existsSync(filePath) || statSync(filePath).isDirectory()) {
        res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: `File not found: ${relativePath}` }));
        return;
      }

      res.writeHead(200, { 'Content-Type': contentTypeFor(filePath) });
      res.end(readFileSync(filePath));
      return;
    }

    /**
     * Promote a RESULT COLUMN into a runtime filter input on a generated answer.
     *
     * The SQL edit happens here, not in the browser: deciding where a predicate
     * may go needs a real dialect parse, and shipping a SQL parser to the client
     * to guess at it is exactly how a filter ends up silently attached to the
     * wrong query. The client sends a column; it gets back an artifact.
     */
    if (req.method === 'POST' && path === '/api/dql/artifacts/add-filter') {
      try {
        const body = await readJSON(req);
        const artifact = normalizeDqlArtifactReference(body.artifact);
        const column = typeof body.column === 'string' ? body.column.trim() : '';
        const value = body.value;
        const resultColumns = Array.isArray(body.resultColumns)
          ? body.resultColumns.filter((entry: unknown): entry is string => typeof entry === 'string')
          : [];
        if (!artifact) throw new Error('A DQL artifact is required to add a filter input.');
        if (!column) throw new Error('Choose a result column to filter on.');
        if (value === undefined || value === null || String(value).trim() === '') {
          throw new Error('Choose a default filter value before adding the input.');
        }
        const sql = extractBlockStudioSql(artifact.source);
        if (!sql) throw new Error('This answer has no editable SQL to filter.');

        const activeConnection = requireActiveConnection();
        const existingNames = (artifact.parameters ?? []).map((parameter) => parameter.name);
        const added = addSqlResultFilter(sql, resultColumns, column, existingNames, activeConnection.driver);
        const source = replaceBlockStudioSql(artifact.source, added.sql, added.parameterName, value);
        // Re-parse so the returned contract is what the block ACTUALLY declares,
        // rather than what this endpoint believes it wrote.
        const invocation = prepareBlockInvocation({ source, surface: 'ask_ai' });
        if (invocation.errors.length > 0) throw new Error(invocation.errors.join(' '));

        const { executionReceipt: _receipt, executableArtifact: _executable, compiledSql: _compiled, ...unexecuted } = artifact;
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          artifact: {
            ...unexecuted,
            source,
            parameters: invocation.parameters,
            parameterValues: { ...(artifact.parameterValues ?? {}), [added.parameterName]: value },
          },
          parameterName: added.parameterName,
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: apiErrorMessage(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/dql/artifacts/execute') {
      try {
        const body = await readJSON(req);
        const targetConnection = await resolveExecutionConnection(body as Record<string, unknown>);
        const targetDescriptor = executionTargetDescriptor(body as Record<string, unknown>);
        const targetConnectionName = targetDescriptor.target === 'connection'
          ? targetDescriptor.connectionName
          : 'local';
        const requestedArtifact = normalizeDqlArtifactReference(body.artifact);
        const requestedBlockName = typeof body.blockName === 'string' ? body.blockName.trim() : '';
        let source = requestedArtifact?.source ?? '';
        let sourcePath = requestedArtifact?.sourcePath;
        let blockName = requestedBlockName || requestedArtifact?.name;
        let domain: string | undefined;
        let chartType: string | undefined;

        if (requestedBlockName) {
          const block = buildManifest({ projectRoot }).blocks[requestedBlockName];
          if (!block) throw new Error(`Block "${requestedBlockName}" was not found.`);
          source = readFileSync(join(projectRoot, block.filePath), 'utf-8');
          sourcePath = block.filePath;
          blockName = block.name;
          domain = block.domain;
          chartType = block.chartType;
        } else if (!source.trim() && sourcePath) {
          const filePath = safeJoin(projectRoot, sourcePath);
          if (filePath && existsSync(filePath) && !statSync(filePath).isDirectory()) source = readFileSync(filePath, 'utf-8');
        }
        if (!source.trim()) throw new Error('Provide an executable DQL artifact or block name.');
        const expectedReceipt = requestedArtifact?.executionReceipt;
        // When a block name is given we deliberately re-read the CANONICAL block
        // from disk, so `source` is no longer the text the receipt was taken
        // from. Comparing the two made every "change an input and apply" fail
        // with "source changed after the answer was produced" whenever the saved
        // block differed from the answer's copy at all — even by formatting —
        // and changing inputs is precisely what that control is for.
        //
        // Check the receipt against the artifact the CLIENT holds (tamper
        // detection, its real purpose). A canonical block that has genuinely
        // moved on is reported alongside the fresh result instead of refusing
        // to run: the user still gets their answer and is told it was rebuilt.
        const receiptSource = requestedArtifact?.source ?? '';
        const sourceRefreshedFromDisk = Boolean(requestedBlockName)
          && receiptSource.trim().length > 0
          && receiptSource !== source;
        if (
          expectedReceipt
          && !sourceRefreshedFromDisk
          && !executionSourceFingerprintMatches(expectedReceipt.sourceFingerprint, source)
        ) {
          throw new Error('DQL artifact source changed after the answer was produced. Refresh the answer before applying it.');
        }
        const parameters = body.parameters && typeof body.parameters === 'object' && !Array.isArray(body.parameters)
          ? body.parameters as Record<string, unknown>
          : requestedArtifact?.parameterValues ?? {};
        const result = await executeDqlArtifactSourceForAgent(source, {
          name: blockName,
          path: sourcePath,
          domain,
          chartType,
        }, {
          parameters,
          question: typeof body.question === 'string' ? body.question : undefined,
          rowLimit: requestedArtifact?.limit,
        }, targetConnection, targetConnectionName);
        const actualReceipt = result.executionReceipt;
        // Same reasoning: if the canonical block was reloaded, its compiled SQL
        // is EXPECTED to differ, so this determinism check would fire on a
        // change we already know about.
        if (expectedReceipt && actualReceipt && !sourceRefreshedFromDisk) {
          if (
            expectedReceipt.parameterFingerprint === actualReceipt.parameterFingerprint
            && expectedReceipt.compiledSqlFingerprint !== actualReceipt.compiledSqlFingerprint
          ) {
            throw new Error('DQL artifact execution changed while its source and inputs were unchanged. Refresh the answer before applying it.');
          }
        }
        const contract = prepareBlockInvocation({
          source,
          parameters,
          question: typeof body.question === 'string' ? body.question : undefined,
          surface: 'ask_ai',
        });
        const certified = /\bstatus\s*=\s*"certified"/i.test(source);
        const semantic = /\btype\s*=\s*"semantic"/i.test(source);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          result,
          artifact: {
            ...(requestedArtifact ?? { kind: semantic ? 'semantic_block' : 'sql_block' }),
            source,
            ...(blockName ? { name: blockName } : {}),
            ...(sourcePath ? { sourcePath } : {}),
            parameters: contract.parameters,
            parameterValues: contract.values,
            persistence: sourcePath ? 'saved' : 'transient',
            trustState: certified ? 'certified' : semantic ? 'governed' : 'review_required',
            compiledSql: result.sql,
            executionReceipt: result.executionReceipt,
            ...(result.executableArtifact ? {
              executableArtifact: {
                ...result.executableArtifact,
                kind: certified ? 'certified_block' : semantic ? 'semantic_block' : 'sql_block',
                trustState: certified ? 'certified' : semantic ? 'governed' : 'review_required',
              },
            } : {}),
            ...(requestedArtifact?.limit ? { limit: requestedArtifact.limit } : {}),
          },
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'GET' && path === '/api/blocks/parameters') {
      try {
        const blockName = url.searchParams.get('name')?.trim();
        if (!blockName) throw new Error('Missing certified block name.');
        const manifest = buildManifest({ projectRoot });
        const block = manifest.blocks[blockName];
        if (!block) {
          res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `Block "${blockName}" was not found.` }));
          return;
        }
        if (block.status !== 'certified') throw new Error(`Block "${blockName}" is not certified.`);
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          blockName: block.name,
          blockPath: block.filePath,
          parameters: block.parameters ?? [],
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/blocks/invoke') {
      try {
        const body = await readJSON(req);
        const blockName = typeof body.blockName === 'string' ? body.blockName.trim() : '';
        if (!blockName) throw new Error('Missing certified block name.');
        const parameters = body.parameters && typeof body.parameters === 'object' && !Array.isArray(body.parameters)
          ? body.parameters as Record<string, unknown>
          : {};
        const result = await executeCertifiedBlockByNameForAgent(
          blockName,
          { parameters, question: typeof body.question === 'string' ? body.question : undefined },
          true,
        );
        const manifest = buildManifest({ projectRoot });
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          result,
          parameters: manifest.blocks[blockName]?.parameters ?? [],
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method === 'POST' && path === '/api/notebook/execute') {
      let body: any;
      let execContext: NotebookExecutionContextInput | null = null;
      const start = Date.now();
      try {
        body = await readJSON(req);
        execContext = notebookExecutionContext(body.executionContext);
        const cell = normalizeNotebookCell(body.cell);
        if (!cell) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'Missing notebook cell payload.' }));
          return;
        }

        const resolved = resolveNotebookBlockReferenceCell(cell, projectRoot);
        const executableCell = resolved.cell;
        const invocation = executableCell.type === 'dql'
          ? prepareBlockInvocation({
              source: executableCell.source,
              parameters: body.parameters && typeof body.parameters === 'object' && !Array.isArray(body.parameters)
                ? body.parameters as Record<string, unknown>
                : {},
              question: typeof body.question === 'string' ? body.question : undefined,
              surface: 'notebook',
            })
          : null;
        if (invocation?.errors.length) throw new Error(invocation.errors.join(' '));
        if (invocation?.unresolvedParameters.length) {
          throw new Error(`Provide required parameter${invocation.unresolvedParameters.length === 1 ? '' : 's'}: ${invocation.unresolvedParameters.join(', ')}.`);
        }
        const cellConnection = await resolveExecutionConnection(
          body as Record<string, unknown>,
        );
        const tableMapping = needsSemanticTableMapping(executableCell)
          ? await resolveSemanticTableMapping(executor, cellConnection, semanticLayer, projectRoot)
          : undefined;
        const semanticCompose = executableCell.type === 'dql'
          && semanticLayer
          && /\btype\s*=\s*"semantic"/i.test(executableCell.source)
          ? await composeSemanticBlockSqlForRuntime(executableCell.source, semanticLayer, {
              driver: cellConnection.driver,
              tableMapping,
              parameters: invocation?.values,
              detectedProvider: semanticDetectedProvider,
              projectRoot,
              projectConfig,
            })
          : null;
        if (semanticCompose && !semanticCompose.sql) {
          throw new Error(semanticCompose.diagnostics.map((diagnostic) => diagnostic.message).join(' '));
        }
        const plan = buildExecutionPlan(executableCell, {
          semanticLayer,
          driver: cellConnection.driver,
          tableMapping,
          parameters: invocation?.values,
          semanticSql: semanticCompose?.sql ?? undefined,
        });
        const executableSql = semanticCompose?.sql ?? plan?.sql;
        if (!executableSql) {
          res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ cellType: cell.type, result: null }));
          return;
        }
        const app = loadRuntimeApp(projectRoot, typeof body.appId === 'string' ? body.appId : activePersonaAppId());
        assertAppAccess({ app, domain: resolved.domain ?? app?.domain, level: 'execute' });
        const semanticExecutionHolder: {
          value: Awaited<ReturnType<typeof executeTargetBoundSemanticQuery>> | null;
        } = { value: null };
        const execution = await analyticalExecutionService.execute({
          sql: executableSql,
          subject: cell.type === 'dql' ? 'DQL query' : 'Notebook query',
          connection: cellConnection,
          sqlParams: plan?.sqlParams,
          variables: { ...(plan?.variables ?? {}), ...(invocation?.values ?? {}) },
          executePrepared: semanticCompose?.compiled
            ? async (preparation) => {
                const semanticExecution = await executeTargetBoundSemanticQuery({
                  executor,
                  connection: cellConnection,
                  projectRoot,
                  plannedAdapter: semanticCompose.compiled!.engine,
                  metricFlow: semanticCompose.compiled!.engine === 'metricflow-cli'
                    ? resolveMetricFlowTargetMetadata(projectRoot, projectConfig)
                    : undefined,
                  // Compilation already produced the exact pinned adapter result
                  // used by the plan. The gateway validates target identity before
                  // accepting that result for preflight and execution.
                  compile: async () => semanticCompose.compiled!,
                  prepareSql: () => ({ sql: preparation.executedSql, connection: preparation.connection }),
                  rowBound: semanticCompose.compiled!.effectiveRequest.limit,
                });
                if (semanticExecution) {
                  semanticExecutionHolder.value = semanticExecution;
                  return semanticExecution.result;
                }
                return executor.executeQuery(
                  preparation.executedSql,
                  plan?.sqlParams ?? [],
                  runtimeVariables({ ...(plan?.variables ?? {}), ...(invocation?.values ?? {}) }),
                  preparation.connection,
                );
              }
            : undefined,
        });
        const { preparation, result: normalized } = execution;
        const decodedSql = preparation.decodedSql;
        const semanticExecution = semanticExecutionHolder.value;
        // Enforce the block's declared invariants against the result set. This
        // is additive: blocks without invariants produce `null` and the
        // response is unchanged. The agent surface (`query_via_block`) reads
        // these fields to downgrade the trust label on violation.
        const invariants = evaluateBlockInvariants(executableCell.source || cell.source || '', {
          columns: normalized.columns,
          rows: normalized.rows,
        });
        if (execContext?.notebookPath) {
          recordNotebookQueryRun(projectRoot, {
            notebookPath: execContext.notebookPath!,
            cellId: execContext.cellId ?? cell.id,
            cellName: execContext.cellName ?? plan?.title ?? resolved.blockName,
            researchRunId: execContext.researchRunId,
            source: execContext.source ?? (cell.type === 'dql' ? 'notebook_dql_cell' : 'notebook_cell'),
            status: 'success',
            rowCount: normalized.rowCount ?? normalized.rows.length,
            durationMs: Date.now() - start,
            sql: executableSql,
            objectKey: resolved.blockPath,
          });
          updateNotebookResearchFromCellExecution(projectRoot, execContext, {
            status: 'success',
            resultPreview: normalized,
            sql: executableSql,
          });
        }
        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          cellType: cell.type,
          executionContext: notebookExecutionIdentity(execContext, cell.id),
          title: plan?.title,
          blockName: resolved.blockName,
          blockPath: resolved.blockPath,
          chartConfig: plan?.chartConfig,
          tests: plan?.tests,
          result: normalized,
          executionTarget: executionTargetDescriptor(body as Record<string, unknown>),
          // Report the statement that ACTUALLY ran. `executableSql` is the
          // pre-decode text, so showing it would put a `source::` identity in
          // front of the user that the warehouse never saw.
          compiledSql: semanticCompose?.compiled?.sql ?? decodedSql,
          engine: semanticCompose?.compiled?.engine,
          ...(semanticExecution ? {
            semanticTrace: semanticExecution.semanticTrace,
            targetBinding: semanticExecution.targetBinding,
            executionReceipt: semanticExecution.executionReceipt,
            executedSql: semanticExecution.preparedSql,
          } : {}),
          ...(invocation ? {
            invocation: {
              resolvedParameters: invocation.resolvedParameters,
              unresolvedParameters: invocation.unresolvedParameters,
              auditId: invocation.auditId,
            },
          } : {}),
          ...(invariants
            ? {
                invariantResults: invariants.invariantResults,
                invariantViolation: invariants.invariantViolation,
              }
            : {}),
        }));
      } catch (error) {
        if (error instanceof DQLAccessDeniedError) {
          res.writeHead(403, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({
            error: error.message,
            code: 'unauthorized',
            details: {
              phase: 'execution',
              executionContext: notebookExecutionIdentity(execContext, body?.cell?.id),
              executionTarget: executionTargetDescriptor(
                body && typeof body === 'object' ? body as Record<string, unknown> : {},
              ),
            },
          }));
          return;
        }
        if (execContext?.notebookPath) {
          recordNotebookQueryRun(projectRoot, {
            notebookPath: execContext.notebookPath!,
            cellId: execContext.cellId,
            cellName: execContext.cellName,
            researchRunId: execContext.researchRunId,
            source: execContext.source ?? 'notebook_cell',
            status: 'error',
            durationMs: Date.now() - start,
            errorCode: error instanceof Error ? error.message : String(error),
          });
          updateNotebookResearchFromCellExecution(projectRoot, execContext, {
            status: 'error',
            error: error instanceof Error ? error.message : String(error),
          });
        }
        const internalRelationCode = error instanceof DqlInternalRelationIdError
          ? 'DQL_INTERNAL_RELATION_ID'
          : undefined;
        const semanticCode = semanticExecutionFailureCode(error) ?? semanticRuntimeErrorCode(error);
        const code = internalRelationCode ?? semanticCode ?? classifyAnalyticalFailure(error);
        const semanticDetails = semanticExecutionFailureDetails(error) ?? semanticRuntimeErrorDetails(error);
        const details = semanticDetails && typeof semanticDetails === 'object' && !Array.isArray(semanticDetails)
          ? semanticDetails as Record<string, unknown>
          : {};
        const status = internalRelationCode
          ? 400
          : code === 'EXECUTION_TARGET_MISMATCH' || code === 'SEMANTIC_SOURCE_DRIFT'
          ? 409
          : semanticCode
            ? 400
            : 500;
        res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({
          error: error instanceof Error ? error.message : String(error),
          code,
          details: {
            ...details,
            phase: typeof details.phase === 'string'
              ? details.phase
              : internalRelationCode || semanticCode
                ? 'compilation'
                : 'execution',
            executionContext: notebookExecutionIdentity(execContext, body?.cell?.id),
            executionTarget: executionTargetDescriptor(
              body && typeof body === 'object' ? body as Record<string, unknown> : {},
            ),
          },
        }));
      }
      return;
    }

    // Create a new metric YAML file in semantic-layer/metrics/
    if (req.method === 'POST' && path === '/api/semantic-layer/metric') {
      try {
        if (dbtFirstOwnsSemanticAuthoring(projectConfig)) {
          sendDbtOwnedSemanticAuthoringError(res);
          return;
        }
        const body = await readJSON(req);
        const { name, label, description, domain, sql, type, table, tags, ifAbsent } = body as {
          name: string; label: string; description: string; domain: string;
          sql: string; type: string; table: string; tags?: string[];
          /** Refuse to replace an existing metric of the same name. */
          ifAbsent?: boolean;
        };
        if (!name || !sql || !type || !table) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: 'name, sql, type, and table are required' }));
          return;
        }
        const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
        const metricsDir = join(projectRoot, 'semantic-layer', 'metrics');
        mkdirSync(metricsDir, { recursive: true });
        const filePath = join(metricsDir, `${slug}.yaml`);
        if (ifAbsent === true && existsSync(filePath)) {
          res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(serializeJSON({ error: `A metric named "${slug}" already exists (semantic-layer/metrics/${slug}.yaml).` }));
          return;
        }
        // Serialized, not interpolated: a colon or newline in a description
        // or expression stays valid YAML.
        const yaml = dumpYaml({
          name: slug,
          label: label || name,
          description: description || '',
          domain: domain || 'general',
          sql,
          type,
          table,
          ...(Array.isArray(tags) && tags.length > 0 ? { tags } : {}),
        }, { lineWidth: -1 });
        writeFileSync(filePath, yaml, 'utf-8');
        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ ok: true, path: `semantic-layer/metrics/${slug}.yaml` }));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(serializeJSON({ error: error instanceof Error ? error.message : String(error) }));
      }
      return;
    }

    if (req.method !== 'GET') {
      res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Method not allowed');
      return;
    }

    // The notebook owns these explicit client routes. Keep the fallback
    // deliberately narrow: arbitrary missing paths remain real 404s.
    const requestedPath = path === '/'
      || isAskClientRoutePath(path)
      ? '/index.html'
      : path;
    const filePath = safeJoin(rootDir, requestedPath);
    if (!filePath || !existsSync(filePath) || statSync(filePath).isDirectory()) {
      res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(renderNotFound(path));
      return;
    }

    const content = readFileSync(filePath);
    res.writeHead(200, {
      'Content-Type': contentTypeFor(filePath),
      'Cache-Control': staticResponseCacheControl(filePath),
      'Content-Length': content.byteLength,
    });
    res.end(content);
    })().catch((error) => {
      // API-007/E2E-014: no rejected request promise may terminate the local
      // notebook process. Route-specific handlers should still return their
      // richer contracts; this boundary is the final server-survival guard.
      if (res.writableEnded || res.destroyed) return;
      const code = apiErrorCode(error, 'INTERNAL_RUNTIME_ERROR');
      const message = apiErrorMessage(error);
      if (res.headersSent) {
        res.end();
        return;
      }
      res.writeHead(code === 'SEMANTIC_SOURCE_DRIFT' ? 409 : 500, {
        'Content-Type': 'application/json; charset=utf-8',
      });
      res.end(serializeJSON(apiErrorEnvelope({
        requestId: apiRequestId('unhandled-runtime-request'),
        code,
        message,
        recoverable: code !== 'POLICY_DENIED',
        details: semanticExecutionFailureDetails(error) ?? semanticRuntimeErrorDetails(error),
        nextActions: code === 'SEMANTIC_SOURCE_DRIFT'
          ? ['Deploy the intended dbt semantic project.', 'Reapply dbt Cloud Semantic Layer settings.']
          : ['Retry the request.', 'Open Trust & Steps for the stable failure details.'],
      })));
    });
  });

  server.once('close', () => {
    runtimeClosing = true;
    for (const watcher of [...projectWatchers]) closeProjectWatcher(watcher);
    projectWatchers.length = 0;
    unsubscribeOperationEvents();
    projectRefreshCoordinator.close();
    askTraceStore.close();
    // The conversation store owns a SQLite handle for this runtime only.
    // Closing it with the HTTP server is required for a genuine local restart
    // to reopen the persisted thread cleanly (and avoids retaining a stale
    // WAL handle after the Notebook process has stopped).
    conversationStoreInstance?.close();
    conversationStoreInstance = undefined;
    for (const client of operationSseClients) {
      try { client.end(); } catch { /* connection already closed */ }
    }
    operationSseClients.clear();
    operationCoordinator.close();
  });

  opts.captureServer?.(server);

  return new Promise<number>((resolvePromise, reject) => {
    let retriedWithRandomPort = false;

    server.on('error', (error: NodeJS.ErrnoException) => {
      if (error.code === 'EADDRINUSE' && !retriedWithRandomPort) {
        retriedWithRandomPort = true;
        server.listen(0, bindHost);
        return;
      }
      reject(error);
    });

    server.listen(preferredPort, bindHost, () => {
      const address = server.address();
      if (!address || typeof address === 'string') {
        reject(new Error('Failed to resolve local server address.'));
        return;
      }
      resolvePromise(address.port);
    });
  });
}

function providerDispatchTerminalEvidence(value: unknown): ProviderDispatchTerminalEvidence | undefined {
  if (!value || typeof value !== 'object') return undefined;
  const candidate = (value as { providerDispatchEvidence?: unknown }).providerDispatchEvidence;
  if (!candidate || typeof candidate !== 'object') return undefined;
  const evidence = candidate as Partial<ProviderDispatchTerminalEvidence>;
  if (!Array.isArray(evidence.providerEgressReceipts)
    || !Number.isInteger(evidence.providerRoundTrips)
    || (evidence.providerRoundTrips ?? -1) < 0) return undefined;
  return {
    providerEgressReceipts: evidence.providerEgressReceipts.flatMap((receipt) => {
      const normalized = normalizeProviderEgressReceiptV1(receipt);
      return normalized ? [normalized] : [];
    }),
    providerRoundTrips: evidence.providerRoundTrips!,
    toolCalls: Number.isInteger(evidence.toolCalls) && (evidence.toolCalls ?? -1) >= 0 ? evidence.toolCalls! : 0,
    sqlExecutions: Number.isInteger(evidence.sqlExecutions) && (evidence.sqlExecutions ?? -1) >= 0 ? evidence.sqlExecutions! : 0,
    repairs: Number.isInteger(evidence.repairs) && (evidence.repairs ?? -1) >= 0 ? evidence.repairs! : 0,
    fallbackReason: typeof evidence.fallbackReason === 'string' ? evidence.fallbackReason : 'provider_error',
  };
}

/** The warehouse relations behind two models on the map. */
function relationshipRelations(manifest: DQLManifest, from: string, to: string): { fromRelation: string; toRelation: string; fromUniqueId: string; toUniqueId: string } {
  const fromEntity = manifest.modeling?.entities[from];
  const toEntity = manifest.modeling?.entities[to];
  if (!fromEntity || !toEntity) throw new Error('Both models must be on the map before their relationship can be checked.');
  const fromNode = manifest.dbtProvenance?.nodes[fromEntity.dbtUniqueId];
  const toNode = manifest.dbtProvenance?.nodes[toEntity.dbtUniqueId];
  if (!fromNode?.relation || !toNode?.relation) throw new Error('Both dbt models must expose warehouse relation names.');
  return { fromRelation: fromNode.relation, toRelation: toNode.relation, fromUniqueId: fromEntity.dbtUniqueId, toUniqueId: toEntity.dbtUniqueId };
}

/** dbt `relationships` tests, read once per project snapshot: the dbt manifest can be large. */
const relationshipTestEdgesBySnapshot = new Map<string, ReturnType<typeof collectDbtRelationshipTests>>();

function dbtRelationshipTestEdges(snapshotId: string, manifestPath: string | null | undefined): ReturnType<typeof collectDbtRelationshipTests> {
  if (!manifestPath) return [];
  const key = `${snapshotId}:${manifestPath}`;
  if (!relationshipTestEdgesBySnapshot.has(key)) {
    let edges: ReturnType<typeof collectDbtRelationshipTests> = [];
    try { edges = collectDbtRelationshipTests(JSON.parse(readFileSync(manifestPath, 'utf8')) as Record<string, unknown>); } catch { edges = []; }
    relationshipTestEdgesBySnapshot.clear();
    relationshipTestEdgesBySnapshot.set(key, edges);
  }
  return relationshipTestEdgesBySnapshot.get(key) ?? [];
}

async function validateModelingRelationship(
  relationship: RelationshipAuthoringInput,
  manifest: DQLManifest,
  execute: (sql: string) => Promise<{ rows: Array<Record<string, unknown>> }>,
  quoteIdentifier: (identifier: string) => string = quoteSqlIdentifier,
  projectRoot?: string,
): Promise<ManifestRelationshipValidationEvidence> {
  const { fromRelation, toRelation } = relationshipRelations(manifest, relationship.from, relationship.to);
  if (!relationship.keys.length) throw new Error('At least one join key pair is required.');
  // ONE PROOF (REL-005): the builder's profile and this validation run the same
  // statement and write the same evidence.
  const spec = { fromRelation, toRelation, keys: relationship.keys, cardinality: relationship.cardinality, fanout: relationship.fanout };
  return validateRelationshipOnWarehouse({ ...spec, keyTypes: catalogKeyTypes(manifest, spec, undefined, projectRoot) }, execute, quoteIdentifier);
}

function relatedProductsForDomain(
  manifest: DQLManifest,
  domainId?: string,
  liveNotebookFiles: NotebookFileEntry[] = [],
): {
  apps: Array<Record<string, unknown>>;
  notebooks: Array<Record<string, unknown>>;
} {
  const apps = Object.values(manifest.apps ?? {})
    .filter((app) => !domainId || app.ownerDomain === domainId || app.usesDomains.includes(domainId))
    .map((app) => ({
      id: app.id,
      name: app.name,
      filePath: app.filePath,
      ownerDomain: app.ownerDomain ?? app.domain,
      usesDomains: app.usesDomains,
      purpose: app.purpose,
      requiredExports: app.requiredExports,
      classification: app.classification,
      lifecycle: app.lifecycle,
      legacyLayout: app.filePath.startsWith('domains/'),
    }));
  const compiledNotebooks = Object.entries(manifest.notebooks)
    .filter(([, notebook]) => !domainId || notebook.ownerDomain === domainId || notebook.usesDomains.includes(domainId))
    .map(([id, notebook]) => ({
      id,
      title: notebook.title,
      filePath: notebook.filePath,
      ownerDomain: notebook.ownerDomain,
      usesDomains: notebook.usesDomains,
      purpose: notebook.purpose,
      requiredExports: notebook.requiredExports,
      classification: notebook.classification,
      legacyLayout: notebook.filePath.startsWith('domains/'),
    }));
  const notebooksByPath = new Map(compiledNotebooks.map((notebook) => [String(notebook.filePath), notebook]));
  for (const file of liveNotebookFiles) {
    if (file.type !== 'notebook') continue;
    const usesDomains = file.usesDomains ?? [];
    if (domainId && file.ownerDomain !== domainId && !usesDomains.includes(domainId)) continue;
    if (notebooksByPath.has(file.path)) continue;
    notebooksByPath.set(file.path, {
      id: file.path,
      title: file.name,
      filePath: file.path,
      ownerDomain: file.ownerDomain,
      usesDomains,
      purpose: undefined,
      requiredExports: [],
      classification: undefined,
      legacyLayout: file.path.startsWith('domains/'),
    });
  }
  const notebooks = [...notebooksByPath.values()]
    .sort((a, b) => String(a.title).localeCompare(String(b.title)));
  return { apps, notebooks };
}

function domainWorkspaceSummary(manifest: DQLManifest, domainId: string): Record<string, unknown> {
  const pkg = manifest.modeling?.packages[domainId];
  const entities = Object.values(manifest.modeling?.entities ?? {}).filter((entity) => entity.domain === domainId);
  const entityKeys = new Set(Object.entries(manifest.modeling?.entities ?? {}).filter(([, entity]) => entity.domain === domainId).map(([key]) => key));
  const relationships = Object.values(manifest.modeling?.relationships ?? {}).filter((relationship) => entityKeys.has(relationship.from) || entityKeys.has(relationship.to));
  const contracts = Object.values(manifest.modeling?.contracts ?? {}).filter((contract) => contract.domain === domainId);
  const imports = Object.values(manifest.modeling?.interfaces?.imports ?? {}).filter((value) => value.domain === domainId);
  const exports = Object.values(manifest.modeling?.interfaces?.exports ?? {}).filter((value) => value.domain === domainId);
  return {
    id: domainId,
    parent: pkg?.parent,
    owner: pkg?.owner,
    filePath: pkg?.filePath,
    counts: {
      entities: entities.length,
      relationships: relationships.length,
      safeRelationships: relationships.filter((relationship) => relationship.automaticJoinAllowed).length,
      staleRelationships: relationships.filter((relationship) => relationship.staleCertification).length,
      contracts: contracts.length,
      imports: imports.length,
      exports: exports.length,
      relatedProducts: Object.values(relatedProductsForDomain(manifest, domainId)).reduce((sum, values) => sum + values.length, 0),
    },
    readiness: relationships.some((relationship) => relationship.staleCertification) ? 'attention' : entities.length > 0 ? 'ready' : 'setup',
  };
}

function quoteQualifiedIdentifier(value: string, quote: (identifier: string) => string = quoteSqlIdentifier): string {
  return value.split('.').map((part) => quote(assertSafeSqlIdentifier(part))).join('.');
}

function quoteSqlIdentifier(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

function assertSafeSqlIdentifier(value: string): string {
  if (!value || !/^[A-Za-z_][A-Za-z0-9_$]*$/.test(value)) throw new Error(`Unsafe SQL identifier: ${value}`);
  return value;
}

function numericValue(value: unknown): number {
  if (typeof value === 'bigint') return Number(value);
  const numeric = Number(value ?? 0);
  return Number.isFinite(numeric) ? numeric : 0;
}

export async function assertLocalQueryRuntimeReady(
  executor: QueryExecutor,
  connection: ConnectionConfig,
): Promise<void> {
  try {
    const connector = await executor.getConnector(connection);
    const ok = await connector.ping();
    if (!ok) {
      throw new Error(`Connection check failed for driver "${connection.driver}".`);
    }
  } catch (error) {
    throw new Error(formatLocalQueryRuntimeError(connection, error));
  }
}

export function formatLocalQueryRuntimeError(
  connection: ConnectionConfig,
  error: unknown,
): string {
  const detail = error instanceof Error ? error.message : String(error);
  const driver = connection.driver;
  const currentNode = process.versions.node;

  if (
    (driver === 'file' || driver === 'duckdb') &&
    detail.includes('duckdb.node')
  ) {
    return `Local query runtime is unavailable for driver "${driver}": DuckDB native bindings could not be loaded. Current Node.js runtime: ${currentNode}. Reinstall dependencies with a supported LTS Node release (for example Node 18, 20, or 22), then rerun "pnpm install". Original error: ${detail}`;
  }

  return `Local query runtime is unavailable for driver "${driver}": ${detail}`;
}

export interface ConnectionTestResult {
  ok: boolean;
  message: string;
  details?: Record<string, unknown>;
}

export async function validateConnectionForTest(
  connector: DatabaseConnector,
  connection: ConnectionConfig,
): Promise<ConnectionTestResult> {
  if (connection.driver === 'snowflake') {
    return validateSnowflakeConnectionForTest(connector, connection);
  }

  const ok = await connector.ping();
  const label = connectionDriverLabel(connection);
  return {
    ok,
    message: ok
      ? `Connected to ${label} successfully.`
      : `Connection to ${label} failed. Check credentials, network access, and database availability.`,
  };
}

function formatConnectionTestError(connection: ConnectionConfig, error: unknown): string {
  const detail = error instanceof Error ? error.message : String(error);
  const label = connectionDriverLabel(connection);
  if (connection.driver === 'snowflake') {
    const cleaned = detail.replace(/^Snowflake (?:connection|query) failed:\s*/i, '').trim();
    return `Snowflake connection failed: ${cleaned || 'Check account, user, password/auth method, role, and network access.'}`;
  }
  return `Connection to ${label} failed: ${detail}`;
}

async function validateSnowflakeConnectionForTest(
  connector: DatabaseConnector,
  connection: ConnectionConfig,
): Promise<ConnectionTestResult> {
  const warehouse = connection.warehouse?.trim();
  if (!warehouse) {
    return {
      ok: false,
      message: 'Snowflake connection requires a warehouse before it can be tested.',
    };
  }

  const warehouseRow = await findSnowflakeWarehouse(connector, warehouse);
  if (!warehouseRow) {
    return {
      ok: false,
      message: `Snowflake warehouse "${warehouse}" was not found or is not visible to this role.`,
    };
  }

  const state = String(readRowField(warehouseRow, 'state') ?? '').trim();
  const normalizedState = state.toUpperCase();
  if (normalizedState && normalizedState !== 'STARTED') {
    return {
      ok: false,
      message: `Snowflake warehouse "${warehouse}" is ${state}. Start or resume it, then test again.`,
      details: {
        warehouse,
        state,
      },
    };
  }

  const context = await connector.execute(
    `SELECT
       CURRENT_ACCOUNT() AS account_name,
       CURRENT_USER() AS user_name,
       CURRENT_ROLE() AS role_name,
       CURRENT_DATABASE() AS database_name,
       CURRENT_SCHEMA() AS schema_name,
       CURRENT_WAREHOUSE() AS warehouse_name`,
  );
  const row = context.rows[0] ?? {};
  const user = String(readRowField(row, 'user_name') ?? connection.username ?? '').trim();
  const role = String(readRowField(row, 'role_name') ?? connection.role ?? '').trim();
  const activeWarehouse = String(readRowField(row, 'warehouse_name') ?? warehouse).trim();

  return {
    ok: true,
    message: `Connected to Snowflake${user ? ` as ${user}` : ''} using warehouse ${activeWarehouse || warehouse}.`,
    details: {
      warehouse: activeWarehouse || warehouse,
      warehouseState: state || 'STARTED',
      role: role || undefined,
      database: readRowField(row, 'database_name') ?? connection.database,
      schema: readRowField(row, 'schema_name') ?? connection.schema,
    },
  };
}

async function findSnowflakeWarehouse(
  connector: DatabaseConnector,
  warehouse: string,
): Promise<Record<string, unknown> | null> {
  const candidates = Array.from(new Set([warehouse, warehouse.toUpperCase()]));
  for (const candidate of candidates) {
    const result = await connector.execute(`SHOW WAREHOUSES LIKE '${escapeSqlString(candidate)}'`);
    const row = result.rows.find((item) => {
      const name = String(readRowField(item, 'name') ?? '').trim();
      return name.localeCompare(warehouse, undefined, { sensitivity: 'accent' }) === 0;
    });
    if (row) return row;
  }
  return null;
}

function readRowField(row: Record<string, unknown>, field: string): unknown {
  const expected = field.toLowerCase();
  const entry = Object.entries(row).find(([key]) => key.toLowerCase() === expected);
  return entry?.[1];
}

function escapeSqlString(value: string): string {
  return value.replace(/'/g, "''");
}

function connectionDriverLabel(connection: ConnectionConfig): string {
  return connection.driver === 'snowflake' ? 'Snowflake' : connection.driver ?? 'database';
}

/**
 * Normalize connector QueryResult → SPA-friendly shape.
 * Connector returns columns as ColumnMeta[] ({name,type,driverType}).
 * The notebook SPA expects columns as string[] (just names).
 */
function normalizeQueryResult(
  result: any,
  semanticRefs?: { metrics: string[]; dimensions: string[] },
): {
  columns: string[];
  rows: Record<string, unknown>[];
  rowCount: number;
  resultFingerprint: string;
  executionTime: number;
  truncated?: boolean;
  executionReceipt?: AgentResultPayload['executionReceipt'];
  trustState?: string;
  answerTier?: string;
  semanticRefs?: { metrics: string[]; dimensions: string[] };
} {
  const canonical = normalizeCanonicalQueryResult({
    columns: result?.columns,
    rows: result?.rows,
    rowCount: result?.rowCount,
    executionTime: result?.executionTime,
    executionTimeMs: result?.executionTimeMs,
    truncated: result?.truncated,
    resultFingerprint: result?.resultFingerprint,
    executionReceipt: result?.executionReceipt,
    trustState: canonicalPersistedTrustState({
      trustState: result?.trustState,
      answerTier: result?.answerTier,
    }),
    answerTier: result?.answerTier,
  });
  const rawRows = Array.isArray(result?.rows) ? result.rows : [];
  const rows = canonical.rows.slice(0, NOTEBOOK_EXECUTE_PREVIEW_ROW_LIMIT);
  const hasRefs = semanticRefs && (semanticRefs.metrics.length > 0 || semanticRefs.dimensions.length > 0);
  return {
    columns: canonical.columns,
    rows,
    rowCount: canonical.rowCount,
    resultFingerprint: canonical.resultFingerprint,
    executionTime: canonical.executionTime ?? 0,
    ...(rawRows.length > rows.length || canonical.truncated ? { truncated: true } : {}),
    ...(canonical.executionReceipt ? { executionReceipt: canonical.executionReceipt } : {}),
    ...(canonical.trustState ? { trustState: canonical.trustState } : {}),
    ...(canonical.answerTier ? { answerTier: canonical.answerTier } : {}),
    ...(hasRefs ? { semanticRefs } : {}),
  };
}

function isLLMProviderId(value: unknown): value is ProviderId {
  return value === 'anthropic'
    || value === 'claude-agent-sdk'
    || value === 'claude-code'
    || value === 'codex'
    || value === 'openai'
    || value === 'gemini'
    || value === 'ollama'
    || value === 'custom-openai';
}

export function resolveDefaultLLMProvider(projectRoot: string): ProviderId | null {
  const settings = listProviderSettings(projectRoot);
  const activeProvider = getActiveProvider(projectRoot);
  if (activeProvider) {
    const active = settings.find((item) => item.id === activeProvider);
    // Only return it for the chat-cell runner path if it's a runner provider id
    // (subscription-only ids like `codex` aren't runners; they fall through).
    if (active?.enabled && isLLMProviderId(activeProvider)) return activeProvider;
  }
  const preferred: ProviderId[] = ['openai', 'gemini', 'anthropic', 'custom-openai', 'ollama'];
  for (const id of preferred) {
    const provider = settings.find((item) => item.id === id);
    if (provider?.enabled && provider.configured) return id;
  }
  return null;
}

/**
 * Resolve the runner that produces a GOVERNED answer (answer-loop with a completion
 * provider). Subscription CLI providers (Claude Code / Codex) are forced through the
 * answer-loop runner — never the MCP `claudeCodeRunner`, which doesn't emit a governed
 * answer envelope. Everything else uses the Settings-resolved default runner.
 */
export async function resolveGovernedAnswerRunner(
  projectRoot: string,
  requestedProvider?: string,
): Promise<{ provider: ProviderId; runner: LLMAgentRunner } | null> {
  // This is intentionally before configuration discovery. It lets the
  // canonical AgentRun preflight distinguish an explicit unknown provider from
  // an absent configuration, while a known-but-unavailable provider still
  // reaches its real adapter readiness check (for example Ollama network
  // failure rather than a fabricated authentication error).
  if (requestedProvider !== undefined) {
    if (!isGovernedAnswerProviderId(requestedProvider)) return null;
    return {
      provider: requestedProvider as ProviderId,
      runner: createDqlAgentProviderRunner(requestedProvider),
    };
  }
  // One selection for every surface: cassette, then the configured providers
  // with failover. The runner carries the SELECTED transport, so an expired
  // Claude login no longer ends a governed answer while Codex or Ollama sit
  // idle; readiness is checked by the runner's own preflight, as before.
  const selection = await selectAssistProvider(projectRoot, undefined, { availability: 'defer' });
  if (!selection) return null;
  return { provider: selection.id, runner: createDqlAgentProviderRunner(selection.id, selection.provider) };
}

function governedRunnerProviderForCassette(
  name: AgentProvider['name'],
): 'anthropic' | 'openai' | 'gemini' | 'ollama' | undefined {
  switch (name) {
    case 'claude': return 'anthropic';
    case 'openai': return 'openai';
    case 'gemini': return 'gemini';
    case 'ollama': return 'ollama';
  }
}

function isGovernedAnswerProviderId(value: unknown): value is ProviderSettingsId {
  return value === 'anthropic'
    || value === 'openai'
    || value === 'gemini'
    || value === 'ollama'
    || value === 'custom-openai'
    || value === 'claude-code'
    || value === 'codex';
}

/**
 * The no-runner outcome is still an authoritative provider preflight result.
 * Preserve an explicit invalid selection as `MODEL_NOT_FOUND` instead of
 * collapsing it into the historical generic authentication error.
 */
export function governedProviderPreflightError(requestedProvider?: string): Error & {
  code: 'MODEL_NOT_FOUND' | 'AUTHENTICATION_FAILED';
  providerPhase: 'preflight';
} {
  const invalidRequestedProvider = Boolean(requestedProvider)
    && !isGovernedAnswerProviderId(requestedProvider);
  return Object.assign(
    new Error(invalidRequestedProvider
      ? 'The selected AI provider is not available in this local runtime. Choose a configured provider in Settings and retry.'
      : 'No AI provider is configured. Configure a subscription (Claude Code / Codex), OpenAI, Gemini, Ollama, or a custom OpenAI-compatible endpoint in Settings.'),
    {
      code: invalidRequestedProvider ? 'MODEL_NOT_FOUND' as const : 'AUTHENTICATION_FAILED' as const,
      providerPhase: 'preflight' as const,
    },
  );
}

/** The provider each Ask request selected, so its calls use that provider's reasoning ceiling. */
const askRequestProviders = new WeakMap<object, ProviderSettingsId>();

/** Map a runner provider id to the settings id whose reasoning ceiling applies. */
function reasoningSettingsIdFor(provider: ProviderId): ProviderSettingsId {
  return provider === 'claude-agent-sdk' ? 'anthropic' : (provider as ProviderSettingsId);
}

/** Type-guard for the reasoning-effort settings value from an untrusted request body. */
function isReasoningEffortSetting(value: unknown): value is 'auto' | ReasoningEffort {
  return value === 'auto' || value === 'low' || value === 'medium' || value === 'high';
}

// Per-project singleton OAuth managers — they hold pending-auth state that must
// survive between the `/start` request and the loopback callback. Keyed by
// project root. "Pending" is derived from the manager itself (isPending) so a
// superseded double-start can't desync a separate flag.
const claudeOAuthManagers = new Map<string, ClaudeOAuthManager>();
const codexOAuthManagers = new Map<string, CodexOAuthManager>();

function getOAuthManager(projectRoot: string, provider: 'claude' | 'codex'): ClaudeOAuthManager | CodexOAuthManager {
  if (provider === 'claude') {
    let m = claudeOAuthManagers.get(projectRoot);
    if (!m) { m = new ClaudeOAuthManager(projectRoot); claudeOAuthManagers.set(projectRoot, m); }
    return m;
  }
  let m = codexOAuthManagers.get(projectRoot);
  if (!m) { m = new CodexOAuthManager(projectRoot); codexOAuthManagers.set(projectRoot, m); }
  return m;
}

/**
 * Resolve the concrete reasoning effort for a run: the route's task-adaptive
 * effort (bumped one level on a repair attempt), clamped by the provider's
 * Settings ceiling (`auto` = no cap). Providers no-op when their model has no
 * reasoning surface, so returning a concrete level here is always safe.
 */
function resolveRunReasoningEffort(
  projectRoot: string,
  provider: ProviderId,
  route: AgentRunRoute | undefined,
  isRepair: boolean,
): ReasoningEffort {
  const ceiling = getEffectiveProviderConfig(projectRoot, reasoningSettingsIdFor(provider)).reasoningEffort;
  let desired: ReasoningEffort = route ? routeReasoningEffort(route) : 'medium';
  if (isRepair) desired = bumpReasoningEffort(desired);
  return ceiling ? clampReasoningEffort(desired, ceiling) : desired;
}

/**
 * The reasoning effort for one provider call made by the Ask pipeline. The
 * request's own choice (an explicit effort, or the composer's thinking mode)
 * wins; otherwise the route decides (`medium` for reading an answer's
 * question, `high` for drafting SQL and for research). A pipeline repair asks one level harder, and the provider's
 * Settings ceiling caps the result. This is the rule the pre-pipeline runtime
 * applied per run; it was lost when that runtime was removed.
 */
/** API providers whose Ask reading runs at low effort by default (see askDispatchReasoningEffort). */
const API_READING_LOW_PROVIDERS = new Set<string>(['anthropic', 'openai', 'gemini', 'custom-openai']);

export function askDispatchReasoningEffort(
  projectRoot: string,
  purpose: 'resolve' | 'correct' | 'repair' | 'draft' | 'research_select' | 'research_narrate',
  request: Pick<AgentRunRequest, 'reasoningEffort' | 'thinkingMode'>,
  provider: ProviderId | undefined,
): ReasoningEffort {
  const isRepair = purpose === 'repair';
  // The reading is the slowest call of an Ask turn (on the Anthropic API about
  // 17 s of a 27 s question, most of it thinking). An operator may set its
  // effort apart from SQL drafting, which stays at the authoring effort:
  // DQL_ASK_READING_EFFORT=low|medium|high. The request's own choice and the
  // provider's Settings ceiling still apply.
  // On a configured API provider the reading defaults to low effort: measured on the
  // Anthropic API over 3×41 questions, the median fell from 20.6 s to 15.3 s
  // and stops from 11.4% to 6.5%, with no significant accuracy change
  // (69.9% against 72.4%, paired p = 0.55). Subscription command-line
  // providers keep the route effort.
  const reading = purpose === 'resolve' || purpose === 'correct';
  const envReading = process.env.DQL_ASK_READING_EFFORT;
  const readingOverride = !reading
    ? undefined
    : isReasoningEffortSetting(envReading)
      ? (envReading === 'auto' ? undefined : envReading as ReasoningEffort)
      // The provider the project CONFIGURED, not the one a run fell back to:
      // a project with no provider settings (a replayed golden suite, a key
      // only in the environment) keeps the route effort.
      : API_READING_LOW_PROVIDERS.has(getActiveProvider(projectRoot) ?? '') ? 'low' as ReasoningEffort : undefined;
  const requested = request.reasoningEffort
    ?? (request.thinkingMode ? resolveThinkingMode(request.thinkingMode).reasoningEffort : undefined)
    ?? readingOverride;
  // Writing a SQL statement is authoring, the `sql_cell` effort: in the golden
  // suite a medium-effort draft joined order costs onto order items and
  // counted each cost once per item. Reading the question stays at the route's
  // effort; that is the call whose thinking time the subscription CLI could
  // not afford.
  const route: AgentRunRoute = purpose === 'research_select' || purpose === 'research_narrate'
    ? 'research'
    : purpose === 'draft' ? 'sql_cell' : 'generated_answer';
  if (!provider) {
    const desired = requested ?? routeReasoningEffort(route);
    return isRepair ? bumpReasoningEffort(desired) : desired;
  }
  return requested
    ? resolveRequestedRunReasoningEffort(projectRoot, provider, requested, isRepair)
    : resolveRunReasoningEffort(projectRoot, provider, route, isRepair);
}

function resolveRequestedRunReasoningEffort(
  projectRoot: string,
  provider: ProviderId,
  requested: ReasoningEffort,
  isRepair: boolean,
): ReasoningEffort {
  const ceiling = getEffectiveProviderConfig(projectRoot, reasoningSettingsIdFor(provider)).reasoningEffort;
  const desired = isRepair ? bumpReasoningEffort(requested) : requested;
  return ceiling ? clampReasoningEffort(desired, ceiling) : desired;
}

function loadAppDashboard(
  projectRoot: string,
  appId: string,
  dashboardId: string,
): { app: AppDocument; dashboard: DashboardDocument; appDir: string; draftArtifactsDir?: string } | null {
  for (const p of findAppDocuments(projectRoot)) {
    const { document: app } = loadAppDocument(p);
    if (!app || app.id !== appId) continue;
    const appDir = p.slice(0, -'/dql.app.json'.length);
    for (const d of findDashboardsForApp(appDir)) {
      const { document: dashboard } = loadDashboardDocument(d);
      if (dashboard?.id === dashboardId) return { app, dashboard, appDir };
    }
  }
  return null;
}

/**
 * Resolves an App Studio draft directly from local SQLite for read-only preview.
 * The draft is never copied into the Git-owned `apps/` tree. This gives manual
 * and AI authoring the same execution path and the same filter/story receipts
 * as a published App while keeping publication explicit.
 */
function loadAppBuildDraftDashboard(
  projectRoot: string,
  draftId: string,
  dashboardId: string,
): { app: AppDocument; dashboard: DashboardDocument; appDir: string; draftArtifactsDir?: string } | null {
  const storage = new LocalAppStorage(defaultLocalAppsDbPath(projectRoot));
  try {
    const draft = storage.getAppBuildDraft(draftId);
    if (!draft) return null;
    const dashboard = draft.pages.find((page) => page.id === dashboardId);
    if (!dashboard) return null;
    const base = draft.baseApp ? findAppById(projectRoot, draft.baseApp.appId) : null;
    const app: AppDocument = base?.app ?? {
      version: 1,
      id: draft.appId,
      name: draft.name,
      description: draft.frame.goal,
      visibility: 'private',
      publicationIntent: 'personal',
      domain: dashboard.metadata.domain ?? 'general',
      usesDomains: [],
      requiredExports: [],
      audience: draft.frame.audience || 'stakeholders',
      lifecycle: 'draft',
      owners: ['local-author'],
      tags: ['app-studio', 'local-draft'],
      members: [],
      roles: [],
      policies: [],
      homepage: { type: 'dashboard', id: dashboard.id },
    };
    return {
      app: { ...app, id: draft.appId, name: draft.name, visibility: 'private', lifecycle: 'draft' },
      dashboard,
      appDir: base?.appDir ?? join(projectRoot, '.dql', 'local', 'app-builds', draft.id),
      draftArtifactsDir: join(projectRoot, '.dql', 'local', 'app-builds', draft.id),
    };
  } finally {
    storage.close();
  }
}

function findAppById(projectRoot: string, appId: string): { app: AppDocument; appDir: string } | null {
  for (const path of findAppDocuments(projectRoot)) {
    const { document: app } = loadAppDocument(path);
    if (app?.id !== appId) continue;
    return { app, appDir: path.slice(0, -'/dql.app.json'.length) };
  }
  return null;
}

function resolveDashboardItemBlock(
  item: DashboardGridItem,
  manifest: DQLManifest,
): ManifestBlock | null {
  if (!item.block) return null;
  if (isBlockIdRef(item.block)) {
    return manifest.blocks[item.block.blockId] ?? null;
  }
  const normalizedRef = normalize(item.block.ref).replaceAll('\\', '/');
  return (manifest.blockDeclarations ?? Object.values(manifest.blocks))
    .find((b) => normalize(b.filePath).replaceAll('\\', '/') === normalizedRef) ?? null;
}

function mergeDashboardChartConfig(
  base: object | null | undefined,
  item: DashboardGridItem,
): Record<string, unknown> {
  const options = item.viz.options ?? {};
  const baseChart = (base as { chart?: unknown } | null | undefined)?.chart;
  return {
    ...(base ?? {}),
    ...options,
    chart: dashboardVizToChart(String(options.chart ?? baseChart ?? item.viz.type)),
  };
}

function dashboardVizToChart(value: string): string {
  const normalized = value.toLowerCase().replace(/_/g, '-');
  if (normalized === 'single-value') return 'kpi';
  return normalized;
}

export function serializeJSON(value: unknown): string {
  return JSON.stringify(value, (_key, current) => {
    if (typeof current === 'bigint') {
      const asNumber = Number(current);
      return Number.isSafeInteger(asNumber) ? asNumber : current.toString();
    }
    return current;
  });
}

/**
 * Extract the single time value returned by an authorized semantic freshness
 * lookup. Adapter aliases may differ by warehouse, so typed date metadata is
 * the only fallback; arbitrary string columns are never treated as freshness.
 * Acceptance: AGT-019, SEC-004.
 */
export function analyticalFreshnessObservedThrough(
  result: QueryResult,
  request: AnalyticalFreshnessRequestV1,
): string {
  const binding = request.authorizedAdapterRequest;
  if (!binding || binding.route !== 'semantic') {
    throw Object.assign(new Error('The freshness lookup has no authorized semantic adapter binding.'), {
      code: 'FRESHNESS_BINDING_REQUIRED',
    });
  }
  const row = result.rows[0];
  if (!row) {
    throw Object.assign(new Error('The authorized freshness lookup returned no rows.'), {
      code: 'FRESHNESS_OBSERVATION_MISSING',
    });
  }
  const normalize = (value: string) => value.replace(/[^a-zA-Z0-9]+/g, '_').toLowerCase();
  const target = normalize(binding.outputField);
  const exact = result.columns.find((column) => normalize(column.name) === target);
  const typedDates = result.columns.filter((column) => column.type === 'date' || column.type === 'datetime');
  const column = exact ?? (typedDates.length === 1 ? typedDates[0] : undefined);
  if (!column) {
    throw Object.assign(new Error('The authorized freshness lookup did not return one identifiable time field.'), {
      code: 'FRESHNESS_OBSERVATION_INVALID',
    });
  }
  const value = row[column.name];
  const instant = value instanceof Date
    ? value
    : typeof value === 'string' && value.trim()
      ? new Date(value)
      : undefined;
  if (!instant || Number.isNaN(instant.getTime())) {
    throw Object.assign(new Error('The authorized freshness value is not a valid instant.'), {
      code: 'FRESHNESS_OBSERVATION_INVALID',
    });
  }
  return instant.toISOString();
}

/** Serialize a Skill to the shared API contract shape (spec 16). */
function serializeSkill(skill: Skill): {
  id: string;
  localId?: string;
  qualifiedId?: string;
  scope: 'project' | 'personal';
  user?: string;
  domain?: string;
  domains?: string[];
  modelAreaRefs?: string[];
  kind?: Skill['kind'];
  status?: Skill['status'];
  owner?: string;
  triggers?: string[];
  exclusions?: string[];
  description?: string;
  body: string;
  preferredMetrics: string[];
  preferredBlocks: string[];
  preferredDimensions?: string[];
  requiredFilters?: string[];
  clarifyWhen?: string[];
  examples?: string[];
  sourceRefs?: string[];
  analyticalPolicy?: Skill['analyticalPolicy'];
  vocabulary: Record<string, string>;
  sourcePath: string;
  isStarter?: boolean;
  visibility: 'private' | 'shared';
} {
  return {
    id: skill.id,
    localId: skill.localId,
    qualifiedId: skill.qualifiedId,
    visibility: isPrivateSkillSource(skill.sourcePath) ? 'private' : 'shared',
    scope: 'project',
    user: undefined,
    domain: skill.domain,
    domains: skill.domains,
    modelAreaRefs: skill.modelAreaRefs,
    kind: skill.kind,
    status: skill.status,
    owner: skill.owner,
    triggers: skill.triggers,
    exclusions: skill.exclusions,
    description: skill.description,
    body: skill.body,
    preferredMetrics: skill.preferredMetrics,
    preferredBlocks: skill.preferredBlocks,
    preferredDimensions: skill.preferredDimensions,
    requiredFilters: skill.requiredFilters,
    clarifyWhen: skill.clarifyWhen,
    examples: skill.examples,
    sourceRefs: skill.sourceRefs,
    analyticalPolicy: skill.analyticalPolicy,
    vocabulary: skill.vocabulary,
    sourcePath: skill.sourcePath,
    isStarter: skill.isStarter,
  };
}

/**
 * Validate + normalize an inbound `{ skill }` body into a WriteSkillInput.
 * `id` + `scope` + `body` are required; `fallbackId` supplies the id on PUT
 * (from the URL). Returns null when the payload is invalid.
 */
function parseSkillInput(raw: unknown, fallbackId?: string): WriteSkillInput | null {
  if (!raw || typeof raw !== 'object') return null;
  const skill = raw as Record<string, unknown>;
  const id = typeof skill.id === 'string' && skill.id.trim() ? skill.id.trim() : fallbackId;
  if (!id) return null;
  const scope = skill.scope === 'project' ? 'project' : undefined;
  if (!scope) return null;
  if (typeof skill.body !== 'string') return null;
  const asStrings = (value: unknown): string[] =>
    Array.isArray(value) ? value.filter((v): v is string => typeof v === 'string') : [];
  const asMap = (value: unknown): Record<string, string> => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    const out: Record<string, string> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (typeof v === 'string') out[k] = v;
    }
    return out;
  };
  return {
    id,
    scope: 'project',
    user: undefined,
    domain: typeof skill.domain === 'string' && skill.domain.trim() ? skill.domain.trim() : undefined,
    domains: asStrings(skill.domains),
    modelAreaRefs: asStrings(skill.modelAreaRefs),
    kind: skill.kind === 'domain_reference' || skill.kind === 'metric_policy' || skill.kind === 'glossary' || skill.kind === 'analysis_pattern' || skill.kind === 'sql_policy' ? skill.kind : 'custom',
    status: skill.status === 'draft' || skill.status === 'deprecated' ? skill.status : 'active',
    owner: typeof skill.owner === 'string' ? skill.owner : undefined,
    triggers: asStrings(skill.triggers),
    exclusions: asStrings(skill.exclusions),
    description: typeof skill.description === 'string' ? skill.description : undefined,
    body: skill.body,
    preferredMetrics: asStrings(skill.preferredMetrics),
    preferredBlocks: asStrings(skill.preferredBlocks),
    preferredDimensions: asStrings(skill.preferredDimensions),
    requiredFilters: asStrings(skill.requiredFilters),
    clarifyWhen: asStrings(skill.clarifyWhen),
    examples: asStrings(skill.examples),
    sourceRefs: asStrings(skill.sourceRefs),
    vocabulary: asMap(skill.vocabulary),
    analyticalPolicy: parseSkillAnalyticalPolicyInput(skill.analyticalPolicy),
    isStarter: skill.isStarter === true ? true : undefined,
  };
}

function parseSkillAnalyticalPolicyInput(value: unknown): WriteSkillInput['analyticalPolicy'] {
  const policy = contextRecord(value);
  if (!Object.keys(policy).length) return undefined;
  const strings = (input: unknown): string[] => Array.isArray(input) ? input.filter((item): item is string => typeof item === 'string') : [];
  const pick = (input: unknown): string | undefined => typeof input === 'string' && input.trim() ? input.trim() : undefined;
  return {
    metricIds: strings(policy.metricIds ?? policy.metric_ids),
    timeRole: pick(policy.timeRole ?? policy.time_role),
    calendarId: pick(policy.calendarId ?? policy.calendar_id),
    timezone: pick(policy.timezone),
    completenessPolicy: ['partial_current', 'latest_complete', 'closed_period'].includes(String(policy.completenessPolicy ?? policy.completeness_policy)) ? String(policy.completenessPolicy ?? policy.completeness_policy) as NonNullable<WriteSkillInput['analyticalPolicy']>['completenessPolicy'] : undefined,
    comparisonAlignment: ['elapsed_period', 'calendar_period', 'fiscal_period'].includes(String(policy.comparisonAlignment ?? policy.comparison_alignment)) ? String(policy.comparisonAlignment ?? policy.comparison_alignment) as NonNullable<WriteSkillInput['analyticalPolicy']>['comparisonAlignment'] : undefined,
    defaultRankingPeriod: ['current', 'comparison'].includes(String(policy.defaultRankingPeriod ?? policy.default_ranking_period)) ? String(policy.defaultRankingPeriod ?? policy.default_ranking_period) as NonNullable<WriteSkillInput['analyticalPolicy']>['defaultRankingPeriod'] : undefined,
    narrativeGuidance: strings(policy.narrativeGuidance ?? policy.narrative_guidance),
  };
}

// ── Domains (spec 17, part B) ────────────────────────────────────────────────

/** The Domain shape the frontend codes to (spec 17 shared contract). */
interface DomainDto {
  id: string;
  name: string;
  parent?: string;
  owner?: string;
  businessOwner?: string;
  boundedContext?: string;
  sourceSystems?: string[];
  description?: string;
  primaryTerms?: string[];
  tags?: string[];
  businessOutcome?: string;
  reviewCadence?: string;
  inScope?: string[];
  outOfScope?: string[];
  dbtGroups?: string[];
  dbtPaths?: string[];
  dbtTags?: string[];
  semanticDomains?: string[];
  semanticTags?: string[];
  sourcePath?: string;
  blockCount?: number;
  skillCount?: number;
  termCount?: number;
}

/** Loose, case/slug-insensitive domain key for counting membership. */
function domainKey(value: string | undefined): string {
  if (!value) return '';
  return value.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function manifestDomainToDto(
  domain: ManifestDomain,
  counts: { blockCount: number; skillCount: number; termCount: number },
): DomainDto {
  return {
    id: domain.id ?? domain.name,
    name: domain.name,
    parent: domain.parent,
    owner: domain.owner,
    businessOwner: domain.businessOwner,
    boundedContext: domain.boundedContext,
    sourceSystems: domain.sourceSystems,
    description: domain.description,
    primaryTerms: domain.primaryTerms,
    tags: domain.tags,
    businessOutcome: domain.businessOutcome,
    reviewCadence: domain.reviewCadence,
    inScope: domain.inScope,
    outOfScope: domain.outOfScope,
    dbtGroups: domain.dbtGroups,
    dbtPaths: domain.dbtPaths,
    dbtTags: domain.dbtTags,
    semanticDomains: domain.semanticDomains,
    semanticTags: domain.semanticTags,
    sourcePath: domain.filePath,
    blockCount: counts.blockCount,
    skillCount: counts.skillCount,
    termCount: counts.termCount,
  };
}

/** List authored domains with per-domain block/skill/term counts. */
export function listDomains(projectRoot: string): DomainDto[] {
  const manifest = buildManifest({ projectRoot, dqlVersion: 'notebook' });
  const domains = manifest.domains ?? {};
  const skills = loadSkills(projectRoot).skills;

  const blockCounts = new Map<string, number>();
  for (const block of Object.values(manifest.blocks)) {
    const key = domainKey(block.domain);
    if (key) blockCounts.set(key, (blockCounts.get(key) ?? 0) + 1);
  }
  const termCounts = new Map<string, number>();
  for (const term of Object.values(manifest.terms ?? {})) {
    const key = domainKey(term.domain);
    if (key) termCounts.set(key, (termCounts.get(key) ?? 0) + 1);
  }
  const skillCounts = new Map<string, number>();
  for (const skill of skills) {
    const key = domainKey(skill.domain);
    if (key) skillCounts.set(key, (skillCounts.get(key) ?? 0) + 1);
  }

  return Object.values(domains)
    .map((domain) => {
      const key = domainKey(domain.id ?? domain.name);
      return manifestDomainToDto(domain, {
        blockCount: blockCounts.get(key) ?? 0,
        skillCount: skillCounts.get(key) ?? 0,
        termCount: termCounts.get(key) ?? 0,
      });
    })
    .sort((a, b) => a.name.localeCompare(b.name));
}

/** Find a single authored domain by name/id (case/slug-insensitive). */
function findDomain(projectRoot: string, nameOrId: string): DomainDto | undefined {
  const key = domainKey(nameOrId);
  return listDomains(projectRoot).find((domain) => domainKey(domain.id) === key || domainKey(domain.name) === key);
}

function deleteCanonicalDomainDeclaration(projectRoot: string, nameOrId: string): boolean {
  const registry = loadDomainPackageRegistry(projectRoot);
  const key = domainKey(nameOrId);
  const pkg = registry.values().find((candidate) => domainKey(candidate.id) === key || domainKey(candidate.name) === key);
  if (!pkg) return false;
  const declaration = join(projectRoot, pkg.declarationPath);
  if (existsSync(declaration)) rmSync(declaration, { force: true });
  if (pkg.legacyYamlPath) {
    const legacy = join(projectRoot, pkg.legacyYamlPath);
    if (existsSync(legacy)) rmSync(legacy, { force: true });
  }
  return true;
}

async function refreshUnifiedProjectIndexes(projectRoot: string): Promise<void> {
  const dbtManifestPath = resolveDbtManifestPath(projectRoot) ?? undefined;
  const manifest = buildManifest({ projectRoot, dqlVersion: 'notebook', dbtManifestPath });
  invalidateAgentProjectState(projectRoot);
  await reindexProject(projectRoot, {
    manifest,
    kgPath: defaultKgPath(projectRoot),
    forceMetadataCatalog: true,
    forceKgIndex: true,
  });
}

function collectDomainPackageAssets(
  projectRoot: string,
  registry: ReturnType<typeof loadDomainPackageRegistry>,
): Record<string, Record<string, string[]>> {
  const output: Record<string, Record<string, string[]>> = {};
  for (const pkg of registry.values()) output[pkg.id] = {};
  for (const path of listProjectFiles(projectRoot).filter((candidate) => candidate.startsWith('domains/'))) {
    const pkg = registry.packageForPath(join(projectRoot, path));
    if (!pkg || path === pkg.declarationPath) continue;
    const local = relative(pkg.root, join(projectRoot, path)).replace(/\\/g, '/');
    const top = local.split('/')[0] ?? '';
    const kind = top === 'business-views' ? 'views' : top;
    if (!['terms', 'skills', 'blocks', 'views', 'notebooks', 'apps', 'evaluations', 'tests'].includes(kind)) continue;
    const bucket = output[pkg.id] ?? (output[pkg.id] = {});
    (bucket[kind] ??= []).push(path);
  }
  for (const assets of Object.values(output)) {
    for (const paths of Object.values(assets)) paths.sort();
  }
  return output;
}

/** Validate + normalize an inbound `{ domain }` body into a DomainInput. */
export function parseDomainInput(raw: unknown, fallbackId?: string): DomainInput | null {
  if (!raw || typeof raw !== 'object') return null;
  const domain = raw as Record<string, unknown>;
  const name =
    typeof domain.name === 'string' && domain.name.trim()
      ? domain.name.trim()
      : typeof domain.id === 'string' && domain.id.trim()
        ? domain.id.trim()
        : fallbackId;
  if (!name) return null;
  const asStrings = (value: unknown): string[] | undefined =>
    Array.isArray(value)
      ? value.filter((v): v is string => typeof v === 'string' && v.trim().length > 0)
      : undefined;
  return {
    id: typeof domain.id === 'string' && domain.id.trim() ? domain.id.trim() : domainFolderSlug(name).replace(/-/g, '_'),
    name,
    parent: typeof domain.parent === 'string' ? domain.parent : undefined,
    owner: typeof domain.owner === 'string' ? domain.owner : undefined,
    businessOwner: typeof domain.businessOwner === 'string' ? domain.businessOwner : undefined,
    boundedContext: typeof domain.boundedContext === 'string' ? domain.boundedContext : undefined,
    sourceSystems: asStrings(domain.sourceSystems),
    description: typeof domain.description === 'string' ? domain.description : undefined,
    primaryTerms: asStrings(domain.primaryTerms),
    tags: asStrings(domain.tags),
    businessOutcome: typeof domain.businessOutcome === 'string' ? domain.businessOutcome : undefined,
    reviewCadence: typeof domain.reviewCadence === 'string' ? domain.reviewCadence : undefined,
    inScope: asStrings(domain.inScope),
    outOfScope: asStrings(domain.outOfScope),
    dbtGroups: asStrings(domain.dbtGroups),
    dbtPaths: asStrings(domain.dbtPaths),
    dbtTags: asStrings(domain.dbtTags),
    semanticDomains: asStrings(domain.semanticDomains),
    semanticTags: asStrings(domain.semanticTags),
    sourcePath: typeof domain.sourcePath === 'string' ? domain.sourcePath : undefined,
  };
}

const COMPLETENESS_TEXT: Record<string, string> = { latest_complete: 'uses the latest complete period', closed_period: 'uses closed periods only', partial_current: 'includes the current period so far' };

/**
 * What Ask will use and enforce for questions scoped to a domain (and subject
 * area), from the same skills, relationships and interfaces it reads.
 */
export function askImpactFor(manifest: DQLManifest, skills: Array<{ id: string; qualifiedId?: string; description?: string; domain?: string; domains?: string[]; modelAreaRefs?: string[]; status?: string; triggers?: string[]; vocabulary?: Record<string, string>; requiredFilters?: string[]; analyticalPolicy?: { timeRole?: string; completenessPolicy?: string; defaultRankingPeriod?: string } }>, domain: string, area?: string) {
  const modeling = manifest.modeling;
  const leaf = (value: string) => value.split('::').pop()!.toLowerCase();
  const inArea = (refs: string[] | undefined) => !area || !refs?.length || refs.some((ref) => leaf(ref) === leaf(area));
  const applies = skills.flatMap((skill) => {
    const owned = skill.domain === domain || Boolean(skill.domains?.includes(domain));
    const projectWide = !skill.domain && !(skill.domains?.length);
    if ((!owned && !projectWide) || (owned && !inArea(skill.modelAreaRefs))) return [];
    const policy = skill.analyticalPolicy ?? {};
    return [{
      id: skill.id,
      ...(skill.description ? { description: skill.description } : {}),
      scope: owned ? 'domain' as const : 'project' as const,
      triggers: skill.triggers ?? [],
      vocabularyCount: Object.keys(skill.vocabulary ?? {}).length,
      requiredFilters: (skill.requiredFilters ?? []).filter(Boolean),
      policy: [
        policy.timeRole ? `periods are measured on ${policy.timeRole}` : '',
        policy.completenessPolicy ? COMPLETENESS_TEXT[policy.completenessPolicy] ?? policy.completenessPolicy : '',
        policy.defaultRankingPeriod ? `rankings use the ${policy.defaultRankingPeriod} period` : '',
      ].filter(Boolean),
      status: skill.status ?? 'active',
      findable: (skill.triggers ?? []).length > 0 || Object.keys(skill.vocabulary ?? {}).length > 0,
    }];
  }).sort((a, b) => (a.scope === b.scope ? a.id.localeCompare(b.id) : a.scope === 'domain' ? -1 : 1));
  const areaRecord = area ? modeling?.areas?.[area] ?? Object.values(modeling?.areas ?? {}).find((candidate) => candidate.qualifiedId === area) : undefined;
  const entityName = (ref: string) => modeling?.entities?.[ref]?.businessName || modeling?.entities?.[ref]?.localId || ref.split('::').pop() || ref;
  const edges = new Map(modelingRelationshipEdges(manifest).map((edge) => [edge.relationshipId, edge]));
  const relationships = Object.values(modeling?.relationships ?? {}).flatMap((relationship) => {
    const edge = edges.get(relationship.qualifiedId ?? relationship.id);
    if (!edge) return [];
    const owner = relationship.ownerDomain ?? relationship.qualifiedId.split('::')[0];
    const touches = owner === domain || modeling?.entities?.[relationship.from]?.domain === domain || modeling?.entities?.[relationship.to]?.domain === domain;
    if (!touches || (areaRecord && !areaRecord.relationshipIds.includes(relationship.qualifiedId))) return [];
    return [{ name: relationship.localId, from: entityName(relationship.from), to: entityName(relationship.to), keys: relationship.keys.map((key) => `${key.from} = ${key.to}`).join(' and '), level: edge.level }];
  });
  const sameDomain = (value: string | undefined) => Boolean(value) && value!.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_') === domain.toLowerCase().replace(/[^a-z0-9]+/g, '_');
  return {
    domain,
    ...(area ? { area } : {}),
    skills: applies,
    requiredFilters: applies.filter((skill) => skill.status === 'active').flatMap((skill) => skill.requiredFilters.map((text) => ({ text, skill: skill.id }))),
    relationships,
    imports: Object.values(modeling?.interfaces?.imports ?? {}).filter((item) => item.domain === domain).map((item) => ({ id: item.qualifiedId ?? item.id, exportRef: item.exportRef, purpose: item.purpose, status: item.status, usable: item.status === 'certified' })),
    terms: Object.values(manifest.terms ?? {}).filter((term) => sameDomain(term.domain)).length,
    concepts: Object.values(modeling?.concepts ?? {}).filter((concept) => concept.domain === domain).length,
    certifiedBlocks: Object.values(manifest.blocks ?? {}).filter((block) => block.status === 'certified' && sameDomain(block.domain)).length,
  };
}

/** A term body from the Terms & concepts tab: a name is required, everything else is trimmed or dropped. */
export function parseTermInput(raw: unknown): TermInput | null {
  if (!raw || typeof raw !== 'object') return null;
  const term = raw as Record<string, unknown>;
  const text = (value: unknown): string | undefined => (typeof value === 'string' && value.trim() ? value.trim() : undefined);
  const list = (value: unknown): string[] | undefined => Array.isArray(value)
    ? [...new Set(value.filter((item): item is string => typeof item === 'string').map((item) => item.trim()).filter(Boolean))]
    : undefined;
  const name = text(term.name);
  if (!name) return null;
  const status = text(term.status);
  return {
    name,
    domain: text(term.domain),
    termType: text(term.termType),
    status: status === 'certified' || status === 'draft' || status === 'deprecated' ? status : undefined,
    description: text(term.description),
    owner: text(term.owner),
    businessOwner: text(term.businessOwner),
    tags: list(term.tags),
    synonyms: list(term.synonyms),
    identifiers: list(term.identifiers),
    metricRefs: list(term.metricRefs),
    businessOutcome: text(term.businessOutcome),
    decisionUse: text(term.decisionUse),
    reviewCadence: text(term.reviewCadence),
    businessRules: list(term.businessRules),
    caveats: list(term.caveats),
  };
}

/** Where a new term file goes: the domain package's `terms/` folder, or project `terms/` for a project-wide term. */
export function termDirectoryFor(projectRoot: string, domain: string | undefined): string {
  if (!domain) return 'terms';
  const pkg = loadDomainPackageRegistry(projectRoot).get(domain);
  const root = pkg ? relative(resolve(projectRoot), resolve(projectRoot, pkg.root)).replace(/\\/g, '/') : `domains/${domainFolderSlug(domain)}`;
  return `${root || '.'}/terms`;
}

// ── Domain / skill bootstrap sessions (local-only; never tracked) ────────────

type ModelingYamlDialect = 'dql_modeling' | 'dbt_resource' | 'dbt_semantic' | 'unsupported';

interface ModelingImportCandidate {
  id: string;
  name: string;
  path?: string;
  dialect: ModelingYamlDialect;
  action: 'import' | 'open_existing' | 'unsupported';
  summary: string;
  warnings: string[];
  document?: Record<string, unknown>;
}

interface ModelingImportSession {
  version: 1;
  id: string;
  createdAt: string;
  updatedAt: string;
  source: { mode: 'current_project' | 'path' | 'upload' | 'paste'; label: string };
  candidates: ModelingImportCandidate[];
  /** Files the scan skipped, so a truncated import never looks like a miss. */
  warnings?: string[];
  proposalId?: string;
}

/** Bounded discovery: an import scan reads at most this many YAML files. */
const MODELING_IMPORT_FILE_LIMIT = 100;

function modelingImportDirectory(projectRoot: string): string {
  return join(projectRoot, '.dql', 'local', 'modeling-imports');
}

function modelingImportSessionPath(projectRoot: string, id: string): string {
  const safe = id.replace(/[^a-zA-Z0-9_-]/g, '');
  if (!safe || safe !== id) throw new Error('Invalid modeling import id.');
  return join(modelingImportDirectory(projectRoot), `${safe}.json`);
}

function writeModelingImportSession(projectRoot: string, session: ModelingImportSession): void {
  mkdirSync(modelingImportDirectory(projectRoot), { recursive: true });
  writeFileSync(modelingImportSessionPath(projectRoot, session.id), `${JSON.stringify(session, null, 2)}\n`, 'utf8');
}

function readModelingImportSession(projectRoot: string, id: string): ModelingImportSession | null {
  const path = modelingImportSessionPath(projectRoot, id);
  if (!existsSync(path)) return null;
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf8')) as ModelingImportSession;
    return parsed.version === 1 && parsed.id === id ? parsed : null;
  } catch {
    return null;
  }
}

function publicModelingImportSession(session: ModelingImportSession): ModelingImportSession {
  return {
    ...session,
    candidates: session.candidates.map(({ document: _document, ...candidate }) => candidate),
  };
}

function createModelingImportSession(
  projectRoot: string,
  gitRoot: string | null,
  loopback: boolean,
  source: Record<string, unknown>,
): ModelingImportSession {
  const mode = source.mode;
  if (mode !== 'current_project' && mode !== 'path' && mode !== 'upload' && mode !== 'paste') throw Object.assign(new Error('Choose current_project, path, upload, or paste.'), { code: 'INVALID_REQUEST' });
  const files: Array<{ name: string; path?: string; content: string; inProject: boolean }> = [];
  const truncationWarnings: string[] = [];
  if (mode === 'paste' || mode === 'upload') {
    const content = typeof source.content === 'string' ? source.content : '';
    if (!content.trim() || Buffer.byteLength(content) > 1_000_000) throw Object.assign(new Error('YAML content is required and must be 1 MB or smaller.'), { code: 'MODELING_IMPORT_LIMIT' });
    files.push({ name: typeof source.filename === 'string' ? source.filename : mode === 'paste' ? 'pasted-modeling.yaml' : 'uploaded-modeling.yaml', content, inProject: false });
  } else {
    if (mode === 'path' && !loopback) throw Object.assign(new Error('Local path import is available only on the loopback Notebook runtime.'), { code: 'PATH_ACCESS_FORBIDDEN' });
    const allowedRoot = realpathSync(resolve(gitRoot ?? projectRoot));
    const requestedInput = mode === 'current_project'
      ? resolve(projectRoot)
      : resolve(projectRoot, typeof source.path === 'string' ? source.path : '');
    if (!existsSync(requestedInput)) throw Object.assign(new Error('The selected YAML path does not exist.'), { code: 'MODELING_IMPORT_NOT_FOUND' });
    const requested = realpathSync(requestedInput);
    if (requested !== allowedRoot && !requested.startsWith(`${allowedRoot}${sep}`)) throw Object.assign(new Error('Import path must stay inside the current Git workspace.'), { code: 'PATH_ACCESS_FORBIDDEN' });
    const paths = collectModelingYamlPaths(requested, MODELING_IMPORT_FILE_LIMIT);
    // Truncation used to be silent, which reads as "DQL did not find my file".
    if (paths.length >= MODELING_IMPORT_FILE_LIMIT) {
      truncationWarnings.push(`Only the first ${MODELING_IMPORT_FILE_LIMIT} YAML files in this location were scanned. Point the import at a narrower folder to see the rest.`);
    }
    for (const path of paths) {
      const size = statSync(path).size;
      if (size > 1_000_000) {
        truncationWarnings.push(`Skipped ${relative(requested, path).replace(/\\/g, '/')}: larger than the 1 MB import limit.`);
        continue;
      }
      const resolvedPath = realpathSync(path);
      if (resolvedPath !== allowedRoot && !resolvedPath.startsWith(`${allowedRoot}${sep}`)) continue;
      const resolvedProject = realpathSync(projectRoot);
      files.push({ name: relative(requested, resolvedPath).replace(/\\/g, '/') || resolvedPath.split(sep).at(-1)!, path: relative(resolvedProject, resolvedPath).replace(/\\/g, '/'), content: readFileSync(resolvedPath, 'utf8'), inProject: resolvedPath === resolvedProject || resolvedPath.startsWith(`${resolvedProject}${sep}`) });
    }
  }
  if (files.length === 0) throw Object.assign(new Error('No YAML files were found in the selected source.'), { code: 'MODELING_IMPORT_EMPTY' });
  const candidates = files.map((file, index) => classifyModelingYamlCandidate(file, index));
  const now = new Date().toISOString();
  const session: ModelingImportSession = {
    version: 1,
    id: apiRequestId('import'),
    createdAt: now,
    updatedAt: now,
    source: { mode, label: mode === 'path' ? String(source.path ?? '') : mode === 'current_project' ? 'Current project' : files[0]!.name },
    candidates,
    ...(truncationWarnings.length ? { warnings: truncationWarnings } : {}),
  };
  writeModelingImportSession(projectRoot, session);
  return session;
}

function collectModelingYamlPaths(start: string, limit: number): string[] {
  if (!existsSync(start)) throw Object.assign(new Error('The selected YAML path does not exist.'), { code: 'MODELING_IMPORT_NOT_FOUND' });
  if (statSync(start).isFile()) return /\.ya?ml$/i.test(start) ? [start] : [];
  const output: string[] = [];
  const visit = (directory: string): void => {
    if (output.length >= limit) return;
    for (const entry of readdirSync(directory, { withFileTypes: true })) {
      if (output.length >= limit) return;
      if (entry.name.startsWith('.') || ['node_modules', 'target', 'dist', 'build'].includes(entry.name)) continue;
      const path = join(directory, entry.name);
      if (entry.isDirectory()) visit(path);
      else if (entry.isFile() && /\.ya?ml$/i.test(entry.name)) output.push(path);
    }
  };
  visit(start);
  return output.sort();
}

function classifyModelingYamlCandidate(
  file: { name: string; path?: string; content: string; inProject: boolean },
  index: number,
): ModelingImportCandidate {
  let document: Record<string, unknown> = {};
  try {
    const parsed = loadYaml(file.content);
    document = contextRecord(parsed);
  } catch (error) {
    return { id: `file-${index + 1}`, name: file.name, path: file.path, dialect: 'unsupported', action: 'unsupported', summary: 'Malformed YAML', warnings: [error instanceof Error ? error.message : String(error)] };
  }
  const keys = new Set(Object.keys(document));
  const dialect: ModelingYamlDialect = keys.has('entities') || keys.has('relationships') || keys.has('area') || keys.has('domain')
    ? 'dql_modeling'
    : keys.has('semantic_models') || keys.has('metrics')
      ? 'dbt_semantic'
      : keys.has('models') || keys.has('sources')
        ? 'dbt_resource'
        : 'unsupported';
  const objectCount = ['entities', 'relationships', 'models', 'sources', 'semantic_models', 'metrics']
    .reduce((total, key) => total + (Array.isArray(document[key]) ? (document[key] as unknown[]).length : 0), 0);
  const openExisting = file.inProject && dialect === 'dql_modeling' && Boolean(file.path?.startsWith('domains/'));
  return {
    id: `file-${index + 1}`,
    name: file.name,
    path: file.path,
    dialect,
    action: dialect === 'unsupported' ? 'unsupported' : openExisting ? 'open_existing' : 'import',
    summary: dialect === 'unsupported' ? 'Unsupported generic YAML' : `${objectCount || 1} ${dialect.replace('_', ' ')} candidate${objectCount === 1 ? '' : 's'}`,
    warnings: dialect === 'unsupported' ? ['v1 supports DQL modeling, dbt resource, and dbt semantic YAML only.'] : openExisting ? ['This is already governed by the current project and should be opened in place.'] : [],
    document,
  };
}

function modelingImportOperations(
  session: ModelingImportSession,
  selectedIds: string[],
  domain: string,
  areaId: string,
  manifest: DQLManifest,
): { operations: ContextAuthoringOperation[]; diagnostics: ContextAuthoringDiagnosticV1[] } {
  const diagnostics: ContextAuthoringDiagnosticV1[] = [];
  const operations: ContextAuthoringOperation[] = [];
  const selected = session.candidates.filter((candidate) => selectedIds.includes(candidate.id));
  if (!selected.length) throw Object.assign(new Error('Select at least one supported YAML candidate.'), { code: 'MODELING_IMPORT_EMPTY' });
  const packageExists = Boolean(manifest.modeling?.packages?.[domain]);
  const area = Object.values(manifest.modeling?.areas ?? {}).find((item) => item.domain === domain && (item.localId === areaId || item.qualifiedId === areaId));
  // A missing Domain/subject area is created by `ensureAuthoringScopeOperations`
  // as part of this same proposal, so it is reported, not blocked.
  if (!packageExists) diagnostics.push({ code: 'DOMAIN_CREATED', severity: 'info', message: `Domain "${domain}" does not exist yet and will be created with these models.` });
  if (!area) diagnostics.push({ code: 'MODEL_AREA_CREATED', severity: 'info', message: `Subject area "${areaId}" does not exist yet in ${domain} and will be created with these models.` });
  const nodes = Object.values(manifest.dbtProvenance?.nodes ?? {});
  const resolveDbt = (reference: string, operationId: string): string | undefined => {
    const cleaned = reference.replace(/^ref\(['"]|['"]\)$/g, '').replace(/^model\./, '');
    const matches = nodes.filter((node) => node.uniqueId === reference || node.name === reference || node.name === cleaned || node.uniqueId.endsWith(`.${cleaned}`));
    if (matches.length !== 1) diagnostics.push({ code: matches.length ? 'AMBIGUOUS_DBT_MODEL' : 'DBT_MODEL_NOT_FOUND', severity: 'blocking', operationId, message: `${reference} ${matches.length ? 'matches multiple dbt models' : 'was not found in the active dbt manifest'}.` });
    return matches.length === 1 ? matches[0]!.uniqueId : undefined;
  };
  const used = new Set(Object.values(manifest.modeling?.entities ?? {}).filter((entity) => entity.domain === domain).map((entity) => entity.localId));
  /**
   * REL-004: dbt already declares its relationships. Every model this import
   * binds is recorded here so the dbt `relationships` tests and MetricFlow
   * `entities:` blocks covering those models become draft edges instead of
   * leaving the author to redraw connections they already wrote down.
   */
  const boundEntityByDbtId = new Map<string, { id: string; operationId: string }>();
  const semanticPrimaryByName = new Map<string, { dbtModel: string; column: string }>();
  const semanticForeignRefs: Array<{ name: string; column: string; dbtModel: string; operationId: string }> = [];
  const allocate = (value: string): string => {
    const base = authoringSlug(value).replace(/-/g, '_') || 'model';
    let id = base;
    let suffix = 2;
    while (used.has(id)) id = `${base}_${suffix++}`;
    used.add(id);
    return id;
  };
  for (const candidate of selected) {
    if (candidate.action === 'open_existing') {
      diagnostics.push({ code: 'OPEN_EXISTING_SOURCE', severity: 'info', message: `${candidate.path ?? candidate.name} is already in the current Domain Package and was not copied.` });
      continue;
    }
    if (candidate.dialect === 'unsupported' || !candidate.document) {
      diagnostics.push({ code: 'UNSUPPORTED_YAML', severity: 'blocking', message: `${candidate.name} is not DQL or dbt modeling YAML.` });
      continue;
    }
    const document = candidate.document;
    if (candidate.dialect === 'dql_modeling') {
      const importedEntities = new Map<string, { id: string; operationId: string }>();
      for (const [index, raw] of contextArray(document.entities).entries()) {
        const entity = contextRecord(raw);
        const operationId = `${candidate.id}:entity:${index + 1}`;
        const dbtModel = resolveDbt(String(entity.dbt_model ?? entity.dbtModel ?? ''), operationId);
        if (!dbtModel) continue;
        const sourceId = String(entity.id ?? nodes.find((node) => node.uniqueId === dbtModel)?.name ?? `model_${index + 1}`);
        const id = allocate(sourceId);
        boundEntityByDbtId.set(dbtModel, { id, operationId });
        importedEntities.set(sourceId, { id, operationId });
        importedEntities.set(String(entity.qualified_id ?? entity.qualifiedId ?? ''), { id, operationId });
        importedEntities.set(dbtModel, { id, operationId });
        operations.push({ id: operationId, kind: 'modeling_change', evidence: [candidate.path ?? candidate.name, dbtModel], change: { operation: 'upsert_entity', value: { id, domain, areaId: area?.localId ?? areaId, dbtModel, businessName: typeof entity.business_name === 'string' ? entity.business_name : undefined, businessContext: typeof entity.business_context === 'string' ? entity.business_context : undefined, conceptRefs: contextStrings(entity.concept_refs), analyticalRole: parseImportedAnalyticalRole(entity.analytical_role), status: 'draft', owner: typeof entity.owner === 'string' ? entity.owner : undefined, grain: typeof entity.grain === 'string' ? entity.grain : undefined, keys: contextStrings(entity.keys) } } });
      }
      for (const [index, raw] of contextArray(document.relationships).entries()) {
        const relationship = contextRecord(raw);
        const operationId = `${candidate.id}:relationship:${index + 1}`;
        const keys = contextArray(relationship.keys).flatMap((value) => {
          const key = contextRecord(value);
          return typeof key.from === 'string' && typeof key.to === 'string' ? [{ from: key.from, to: key.to }] : [];
        });
        if (!relationship.from || !relationship.to || !keys.length) {
          diagnostics.push({ code: 'RELATIONSHIP_INCOMPLETE', severity: 'blocking', operationId, message: 'Imported relationship requires from, to, and at least one key pair.' });
          continue;
        }
        const resolveEndpoint = (rawRef: unknown): { id?: string; dependency?: string } => {
          const ref = String(rawRef);
          const imported = importedEntities.get(ref);
          if (imported) return { id: imported.id, dependency: imported.operationId };
          const matches = Object.values(manifest.modeling?.entities ?? {}).filter((entity) => entity.domain === domain && (entity.localId === ref || entity.id === ref || entity.qualifiedId === ref));
          return matches.length === 1 ? { id: matches[0]!.localId } : {};
        };
        const from = resolveEndpoint(relationship.from);
        const to = resolveEndpoint(relationship.to);
        if (!from.id || !to.id) {
          diagnostics.push({ code: 'RELATIONSHIP_REFERENCE_UNRESOLVED', severity: 'blocking', operationId, message: `Relationship endpoints must resolve inside ${domain}; simple import cannot create cross-domain relationships.` });
          continue;
        }
        operations.push({ id: operationId, kind: 'modeling_change', dependsOn: [...new Set([from.dependency, to.dependency].filter((value): value is string => Boolean(value)))], evidence: [candidate.path ?? candidate.name], change: { operation: 'upsert_relationship', value: { id: String(relationship.id ?? `${relationship.from}_to_${relationship.to}`), domain, areaId: area?.localId ?? areaId, from: from.id, to: to.id, keys, cardinality: parseImportedCardinality(relationship.cardinality), fanout: parseImportedFanout(relationship.fanout), status: 'draft', description: typeof relationship.description === 'string' ? relationship.description : undefined, rationale: 'Imported as a draft; certification and warehouse proof were intentionally removed.' } } });
      }
    } else {
      const modelRecords = candidate.dialect === 'dbt_resource'
        ? contextArray(document.models)
        : contextArray(document.semantic_models);
      for (const [index, raw] of modelRecords.entries()) {
        const model = contextRecord(raw);
        const operationId = `${candidate.id}:model:${index + 1}`;
        const reference = String(model.model ?? model.name ?? '');
        const dbtModel = resolveDbt(reference, operationId);
        if (!dbtModel) continue;
        const existing = Object.values(manifest.modeling?.entities ?? {}).find((entity) => entity.dbtUniqueId === dbtModel);
        if (existing && existing.domain !== domain) {
          diagnostics.push({ code: 'OWNERSHIP_CONFLICT', severity: 'blocking', operationId, message: `${dbtModel} is already owned by ${existing.domain}; import cannot move it implicitly.` });
          continue;
        }
        const id = existing?.localId ?? allocate(String(model.name ?? nodes.find((node) => node.uniqueId === dbtModel)?.name ?? `model_${index + 1}`));
        boundEntityByDbtId.set(dbtModel, { id, operationId });
        // MetricFlow states its own join graph in `entities:`; keep the primary
        // key so the semantic branch can pair it with foreign references below.
        const semanticEntities = contextArray(model.entities).map(contextRecord);
        const primary = semanticEntities.find((entry) => entry.type === 'primary');
        if (primary?.name) semanticPrimaryByName.set(String(primary.name), { dbtModel, column: String(primary.expr ?? primary.name) });
        for (const entry of semanticEntities) {
          if (entry.type !== 'foreign' || !entry.name) continue;
          semanticForeignRefs.push({ name: String(entry.name), column: String(entry.expr ?? entry.name), dbtModel, operationId });
        }
        const aggTimeDimension = contextRecord(model.defaults).agg_time_dimension;
        operations.push({ id: operationId, kind: 'modeling_change', evidence: [candidate.path ?? candidate.name, dbtModel], change: { operation: 'upsert_entity', value: { id, domain, areaId: area?.localId ?? areaId, dbtModel, businessName: typeof model.name === 'string' ? titleCaseAuthoring(model.name) : undefined, businessContext: typeof model.description === 'string' ? model.description : undefined, status: 'draft', analyticalRole: 'unknown', ...(typeof aggTimeDimension === 'string' ? { grain: aggTimeDimension } : {}), ...(primary?.name ? { keys: [String(primary.expr ?? primary.name)] } : {}) } } });
      }
    }
  }

  // REL-004: pair MetricFlow foreign references against the primary entity of
  // the same name. This is dbt's own declared join graph, so it needs no
  // guessing — but it is still only a draft candidate (REL-001).
  for (const reference of semanticForeignRefs) {
    const primary = semanticPrimaryByName.get(reference.name);
    if (!primary || primary.dbtModel === reference.dbtModel) continue;
    const from = boundEntityByDbtId.get(reference.dbtModel);
    const to = boundEntityByDbtId.get(primary.dbtModel);
    if (!from || !to) continue;
    operations.push({
      id: `semantic-entity:${from.id}:${to.id}:${reference.name}`,
      kind: 'modeling_change',
      dependsOn: [...new Set([from.operationId, to.operationId])],
      evidence: [`MetricFlow entity "${reference.name}" declared foreign in ${reference.dbtModel} and primary in ${primary.dbtModel}`],
      change: {
        operation: 'upsert_relationship',
        value: {
          id: `${from.id}_to_${to.id}`, domain, areaId: area?.localId ?? areaId,
          from: from.id, to: to.id,
          keys: [{ from: reference.column, to: primary.column }],
          cardinality: 'many_to_one', fanout: 'unknown', status: 'draft',
          verb: reference.name,
          rationale: 'Declared by the MetricFlow semantic entity graph. Validate against the warehouse before certifying.',
        },
      },
    });
  }

  // REL-004: dbt `relationships` tests state an exact key pair and are already
  // enforced by `dbt test`, which makes them the strongest available candidate.
  // They remain drafts: a dbt test is evidence, never join authorization.
  const manifestPath = manifest.dbtProvenance?.manifestPath;
  if (manifestPath && boundEntityByDbtId.size > 1) {
    let rawManifest: Record<string, unknown> | undefined;
    try { rawManifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as Record<string, unknown>; } catch { rawManifest = undefined; }
    if (rawManifest) {
      for (const edge of collectDbtRelationshipTests(rawManifest, new Set(boundEntityByDbtId.keys()))) {
        if (edge.fromColumn === 'unknown' || edge.toColumn === 'unknown') continue;
        const from = boundEntityByDbtId.get(edge.fromDbtUniqueId);
        const to = boundEntityByDbtId.get(edge.toDbtUniqueId);
        if (!from || !to || from.id === to.id) continue;
        const id = `${from.id}_to_${to.id}`;
        if (operations.some((operation) => operation.kind === 'modeling_change' && operation.change.operation === 'upsert_relationship' && operation.change.value.id === id)) continue;
        operations.push({
          id: `dbt-test:${edge.testUniqueId}`,
          kind: 'modeling_change',
          dependsOn: [...new Set([from.operationId, to.operationId])],
          evidence: [edge.testUniqueId, ...(edge.sourcePath ? [edge.sourcePath] : [])],
          change: {
            operation: 'upsert_relationship',
            value: {
              id, domain, areaId: area?.localId ?? areaId,
              from: from.id, to: to.id,
              keys: [{ from: edge.fromColumn, to: edge.toColumn }],
              cardinality: 'many_to_one', fanout: 'unknown', status: 'draft',
              rationale: `Declared by the dbt relationships test ${edge.testUniqueId}. Validate against the warehouse before certifying.`,
            },
          },
        });
      }
    }
  }

  if (!operations.length) throw Object.assign(new Error('The selected YAML did not produce any resolvable modeling changes.'), { code: 'MODELING_IMPORT_EMPTY', diagnostics });
  return { operations, diagnostics };
}

function contextRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function contextArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function contextStrings(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string') : [];
}

function parseImportedAnalyticalRole(value: unknown): 'event' | 'dimension' | 'snapshot' | 'bridge' | 'unknown' {
  return value === 'event' || value === 'dimension' || value === 'snapshot' || value === 'bridge' ? value : 'unknown';
}

function parseImportedCardinality(value: unknown): RelationshipAuthoringInput['cardinality'] {
  return value === 'one_to_one' || value === 'one_to_many' || value === 'many_to_one' || value === 'many_to_many' ? value : 'unknown';
}

function parseImportedFanout(value: unknown): RelationshipAuthoringInput['fanout'] {
  if (value === 'unsafe' || value === 'forbidden') return 'forbidden';
  return value === 'safe' || value === 'dedupe_required' || value === 'attribution_required' ? value : 'unknown';
}

function contextSourceReferenceExists(manifest: DQLManifest, reference: string): boolean {
  if (!reference.includes('::entity::') && !reference.includes('::relationship::')) return true;
  return Object.values(manifest.modeling?.entities ?? {}).some((entity) => entity.qualifiedId === reference)
    || Object.values(manifest.modeling?.relationships ?? {}).some((relationship) => relationship.qualifiedId === reference);
}

function parseContextAuthoringOrigin(value: unknown): ContextAuthoringOrigin {
  if (value === 'manual' || value === 'yaml_import' || value === 'dbt_discovery' || value === 'ai' || value === 'correction') return value;
  throw Object.assign(new Error('A valid context proposal origin is required.'), { code: 'INVALID_REQUEST' });
}

function parseContextAuthoringOperations(value: unknown): ContextAuthoringOperation[] {
  if (!Array.isArray(value) || value.length === 0 || value.length > 100) throw Object.assign(new Error('Provide 1-100 authoring operations.'), { code: 'INVALID_REQUEST' });
  const ids = new Set<string>();
  return value.map((raw, index): ContextAuthoringOperation => {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw Object.assign(new Error(`Operation ${index + 1} is invalid.`), { code: 'INVALID_REQUEST' });
    const operation = raw as Record<string, unknown>;
    const id = typeof operation.id === 'string' ? operation.id.trim() : '';
    if (!id || ids.has(id)) throw Object.assign(new Error(`Operation ${index + 1} requires a unique id.`), { code: 'INVALID_REQUEST' });
    ids.add(id);
    const dependsOn = Array.isArray(operation.dependsOn) ? operation.dependsOn.filter((item): item is string => typeof item === 'string') : undefined;
    const evidence = Array.isArray(operation.evidence) ? operation.evidence.filter((item): item is string => typeof item === 'string').slice(0, 32) : undefined;
    if (operation.kind === 'modeling_change') {
      const change = operation.change as ModelingAuthoringChange | undefined;
      const allowed = new Set(['upsert_domain', 'upsert_area', 'upsert_entity', 'upsert_relationship', 'upsert_contract', 'upsert_export', 'upsert_import', 'upsert_concept', 'remove_entity', 'remove_relationship', 'remove_area', 'remove_contract', 'remove_export', 'remove_import', 'remove_concept']);
      if (!change || typeof change !== 'object' || !allowed.has(change.operation) || !('value' in change) || !change.value || typeof change.value !== 'object') throw Object.assign(new Error(`Modeling operation ${id} is invalid.`), { code: 'INVALID_REQUEST' });
      return { id, kind: 'modeling_change', change, dependsOn, evidence };
    }
    if (operation.kind === 'skill_change') {
      const skillOperation = operation.operation;
      const skill = operation.value as WriteSkillInput | undefined;
      if ((skillOperation !== 'create' && skillOperation !== 'update' && skillOperation !== 'move') || !skill || typeof skill.id !== 'string' || !skill.id.trim() || typeof skill.body !== 'string') throw Object.assign(new Error(`Skill operation ${id} is invalid.`), { code: 'INVALID_REQUEST' });
      return {
        id,
        kind: 'skill_change',
        operation: skillOperation,
        value: { ...skill, scope: 'project', status: 'draft' },
        targetQualifiedId: typeof operation.targetQualifiedId === 'string' ? operation.targetQualifiedId : undefined,
        expectedSourceHash: typeof operation.expectedSourceHash === 'string' ? operation.expectedSourceHash : undefined,
        dependsOn,
        evidence,
      };
    }
    if (operation.kind === 'dbt_source_change') {
      const change = operation.change as DbtSourceAuthoringInput | undefined;
      if (!change || typeof change.uniqueId !== 'string' || !change.uniqueId.trim()) throw Object.assign(new Error(`dbt source operation ${id} is invalid.`), { code: 'INVALID_REQUEST' });
      return { id, kind: 'dbt_source_change', change, dependsOn, evidence };
    }
    if (operation.kind === 'term_change') {
      const value = operation.value as TermTemplateInput | undefined;
      if (!value || typeof value.title !== 'string' || !value.title.trim() || typeof value.domain !== 'string' || !value.domain.trim()) throw Object.assign(new Error(`Term operation ${id} needs a title and a domain.`), { code: 'INVALID_REQUEST' });
      return { id, kind: 'term_change', value: { ...value, title: value.title.trim(), domain: value.domain.trim(), owner: typeof value.owner === 'string' && value.owner.trim() ? value.owner.trim() : 'unassigned', status: 'draft' }, dependsOn, evidence };
    }
    throw Object.assign(new Error(`Unsupported context operation kind for ${id}.`), { code: 'INVALID_REQUEST' });
  });
}

function resolveContextPatchPath(projectRoot: string, gitRoot: string | null, relativePath: string): string {
  const allowedRoot = resolve(gitRoot ?? projectRoot);
  const absolute = resolve(projectRoot, relativePath);
  if (absolute !== allowedRoot && !absolute.startsWith(`${allowedRoot}${sep}`)) {
    throw Object.assign(new Error(`Proposal path escapes the Git workspace: ${relativePath}`), { code: 'OWNERSHIP_CONFLICT' });
  }
  return absolute;
}

/**
 * Modeling AI: propose modeling changes from repository metadata.
 *
 * `AGT-024` — the model receives manifest identifiers, columns, lineage, tests,
 * current modeling, and source locations, and never query rows. It proposes;
 * this function then validates every identifier against the live snapshot and
 * drops anything invented, so a hallucinated model or column cannot enter a
 * proposal. `previewContextAuthoring` independently forces `status: 'draft'`,
 * strips certification and validation, and blocks deletes and cross-domain
 * relationships, so nothing here can certify or authorize a join.
 */
async function buildAiModelingOperations(
  projectRoot: string,
  manifest: DQLManifest,
  request: AgentRunRequest,
  provider: AgentProvider,
  priorOperations: ContextAuthoringOperation[] = [],
): Promise<ContextAuthoringOperation[]> {
  const modeling = manifest.modeling;
  if (!modeling || !manifest.dbtProvenance) throw new Error('Modeling AI requires a compiled dbt-first project snapshot.');
  const context = request.workspaceContext ?? {};
  const requestedDomain = typeof context.domain === 'string'
    ? context.domain
    : request.selectedObject?.kind === 'domain' ? request.selectedObject.id : undefined;
  const domain = requestedDomain ?? Object.keys(modeling.packages)[0] ?? defaultAuthoringDomainId(manifest);
  const requestedArea = typeof context.modelAreaId === 'string' ? context.modelAreaId : typeof context.areaId === 'string' ? context.areaId : undefined;
  const area = Object.values(modeling.areas).find((candidate) => candidate.domain === domain
    && (!requestedArea || candidate.qualifiedId === requestedArea || candidate.localId === requestedArea));
  const areaId = area?.localId ?? modelAreaLocalId(requestedArea) ?? DEFAULT_MODEL_AREA_ID;

  const bound = new Set(Object.values(modeling.entities).map((entity) => entity.dbtUniqueId));
  const manifestPath = resolveDbtManifestPath(projectRoot);
  const describe = (uniqueId: string) => {
    const detail = manifestPath ? loadDbtNodeAuthoringDetail(manifestPath, uniqueId) : undefined;
    return {
      dbtUniqueId: uniqueId,
      name: manifest.dbtProvenance!.nodes[uniqueId]?.name,
      relation: manifest.dbtProvenance!.nodes[uniqueId]?.relation,
      description: detail?.description,
      columns: (detail?.columns ?? []).slice(0, 60).map((column) => ({ name: column.name, type: column.type, description: column.description })),
      tests: (detail?.tests ?? []).slice(0, 40),
    };
  };
  // Bound as candidates so a large project still fits a prompt.
  const unbound = Object.values(manifest.dbtProvenance.nodes).filter((node) => !bound.has(node.uniqueId));
  const tokens = authoringTokens(request.question);
  const ranked = [
    ...unbound.filter((node) => tokens.some((token) => `${node.name} ${node.uniqueId} ${node.sourcePath ?? ''}`.toLowerCase().includes(token))),
    ...unbound,
  ].filter((node, index, values) => values.findIndex((other) => other.uniqueId === node.uniqueId) === index).slice(0, 24);

  // The author is looking at one subject area, so that is what the AI may
  // change. Models outside it are offered only when the request actually asks
  // for new ones: "connect these models" once came back with six models nobody
  // asked about, which buries the two the author meant.
  const domainEntities = Object.values(modeling.entities).filter((entity) => entity.domain === domain);
  const inArea = area ? domainEntities.filter((entity) => entity.areaId === area.qualifiedId) : domainEntities;
  const scopedEntities = inArea.length > 0 ? inArea : domainEntities;
  const scopedRecordKeys = new Set(Object.entries(modeling.entities)
    .filter(([, entity]) => scopedEntities.includes(entity))
    .map(([recordKey]) => recordKey));
  // Models the open draft adds are in scope for the turn that revises it.
  const draftEntities = draftEntityIndex(priorOperations);
  const scopedDbtIds = new Set([
    ...scopedEntities.map((entity) => entity.dbtUniqueId),
    ...draftEntities.map((entity) => entity.dbtModel),
  ]);
  const wantsNewModels = requestAsksForNewModels(request.question, unbound.map((node) => `${node.name ?? ''} ${node.uniqueId}`));
  const focusedId = request.selectedObject?.kind === 'model'
    ? request.selectedObject.id
    : typeof context.focusedObjectId === 'string' ? context.focusedObjectId : undefined;

  const payload = {
    request: request.question.trim(),
    targetDomain: domain,
    targetAreaId: areaId,
    currentModels: scopedEntities.map((entity) => ({
      id: entity.localId, dbtUniqueId: entity.dbtUniqueId, businessName: entity.businessName,
      businessContext: entity.businessContext, grain: entity.grain, keys: entity.keys, analyticalRole: entity.analyticalRole,
    })),
    currentRelationships: Object.values(modeling.relationships).filter((relationship) => relationship.ownerDomain === domain
      && scopedRecordKeys.has(relationship.from) && scopedRecordKeys.has(relationship.to)).map((relationship) => ({
      id: relationship.localId, from: modeling.entities[relationship.from]?.localId, to: modeling.entities[relationship.to]?.localId,
      keys: relationship.keys, cardinality: relationship.cardinality, fanout: relationship.fanout, status: relationship.status,
    })),
    availableDbtModels: wantsNewModels ? ranked.map((node) => describe(node.uniqueId)) : [],
    focusedModel: focusedId
      ? Object.values(modeling.entities).find((entity) => entity.qualifiedId === focusedId)
      : undefined,
    // What this turn is revising, when the author is following up on a draft.
    draftInProgress: priorOperations.flatMap((operation) => operation.kind === 'modeling_change' ? [operation.change] : []),
  };

  let raw: string;
  try {
    raw = await provider.generate([
      {
        role: 'system',
        content: [
          'You design analytical data models. Propose modeling changes for review; you are never applying them.',
          'Return exactly one JSON object in a ```json fence: {"operations":[...]}. No prose outside the fence.',
          'Each operation is {"kind":"upsert_entity","id":"<snake_case>","dbtModel":"<exact dbt unique id>","businessName":"...","businessContext":"...","grain":"...","keys":["..."],"analyticalRole":"event|dimension|snapshot|bridge|unknown"}',
          'or {"kind":"upsert_relationship","id":"<snake_case>","from":"<entity id>","to":"<entity id>","keys":[{"from":"<column>","to":"<column>"}],"cardinality":"one_to_one|one_to_many|many_to_one|many_to_many|unknown","fanout":"safe|dedupe_required|attribution_required|forbidden|unknown","verb":"...","description":"...","rationale":"..."}.',
          'Use ONLY dbt unique ids and column names present in the supplied metadata. Never invent an identifier.',
          'businessContext states what one row means in business terms. Never restate the request back as business context.',
          'Set cardinality and fanout from the evidence; use "unknown" when the metadata does not establish them. Never claim a relationship is certified or validated.',
          'Do not propose deletions, cross-domain relationships, or changes to dbt-owned SQL, columns, tests, or descriptions.',
          wantsNewModels
            ? 'You may add models from availableDbtModels when the request asks for them.'
            : 'Propose changes only for the models listed in currentModels. This request did not ask for new models, so do not add any.',
          priorOperations.length
            ? 'draftInProgress holds the changes you proposed last turn and the request revises them: return only the operations that change, repeating the id of the one you are revising. Everything you leave out stays as it is.'
            : 'There is no draft in progress.',
        ].join(' '),
      },
      { role: 'user', content: JSON.stringify(payload) },
    ], { maxTokens: 3000, temperature: 0 });
  } catch (error) {
    throw new Error(`The AI provider could not complete this modeling request: ${error instanceof Error ? error.message : String(error)}`);
  }

  const parsed = parseAiModelingOperations(raw);
  if (parsed.length === 0) throw new Error('Modeling AI did not return any usable modeling changes. Try naming the models or the relationship you want.');

  // Validate every identifier against the live snapshot. An operation that
  // references something the project does not have is dropped, not repaired.
  const knownDbtIds = new Set(Object.keys(manifest.dbtProvenance.nodes));
  const columnsFor = new Map<string, Set<string>>();
  // Entity ids the model may name: the ones already in scope, plus whatever it
  // proposes. Keyed by a normalized id because Modeling writes hyphenated ids
  // ("local-team-season-facts") while a model answers in snake_case — without
  // this every relationship to an existing model was silently dropped.
  const entityIdByNormalizedId = new Map([
    ...scopedEntities.map((entity) => [normalizeAuthoringEntityId(entity.localId), entity.localId] as const),
    ...draftEntities.map((entity) => [normalizeAuthoringEntityId(entity.id), entity.id] as const),
  ]);
  // Where each entity id gets its columns from, including models that so far
  // exist only in the draft being revised.
  const dbtModelForEntityId = new Map<string, string>([
    ...domainEntities.map((entity) => [entity.localId, entity.dbtUniqueId] as const),
    ...draftEntities.map((entity) => [entity.id, entity.dbtModel] as const),
  ]);
  const operations: ContextAuthoringOperation[] = [];

  let droppedOutOfScope = 0;
  for (const candidate of parsed) {
    if (candidate.kind === 'upsert_entity') {
      if (!candidate.dbtModel || !knownDbtIds.has(candidate.dbtModel)) continue;
      // Scope is enforced here too: a prompt line is guidance, this is the rule.
      if (!wantsNewModels && !scopedDbtIds.has(candidate.dbtModel)) { droppedOutOfScope += 1; continue; }
      const boundEntity = domainEntities.find((entity) => entity.dbtUniqueId === candidate.dbtModel);
      const id = authoringEntityIdForDbtModel(candidate.id, candidate.dbtModel, domainEntities);
      if (!id) continue;
      entityIdByNormalizedId.set(normalizeAuthoringEntityId(id), id);
      dbtModelForEntityId.set(id, candidate.dbtModel);
      const detail = manifestPath ? loadDbtNodeAuthoringDetail(manifestPath, candidate.dbtModel) : undefined;
      const columns = new Set((detail?.columns ?? []).map((column) => column.name.toLowerCase()));
      columnsFor.set(id, columns);
      operations.push({
        id: `entity:${domain}:${id}`,
        kind: 'modeling_change',
        evidence: [candidate.dbtModel, ...(detail?.sourcePath ? [detail.sourcePath] : [])],
        change: {
          operation: 'upsert_entity',
          value: {
            id, domain,
            // An existing model keeps the subject area it is already filed under.
            areaId: (boundEntity ? modeling.areas[boundEntity.areaId ?? '']?.localId : undefined) ?? areaId,
            dbtModel: candidate.dbtModel,
            businessName: candidate.businessName?.trim() || titleCaseAuthoring(id),
            businessContext: candidate.businessContext?.trim() || undefined,
            grain: candidate.grain && columns.has(candidate.grain.toLowerCase()) ? candidate.grain : undefined,
            keys: (candidate.keys ?? []).filter((key) => columns.has(key.toLowerCase())),
            analyticalRole: parseImportedAnalyticalRole(candidate.analyticalRole) ?? 'unknown',
            status: 'draft',
          },
        },
      });
      continue;
    }

    const from = entityIdByNormalizedId.get(normalizeAuthoringEntityId(candidate.from ?? ''));
    const to = entityIdByNormalizedId.get(normalizeAuthoringEntityId(candidate.to ?? ''));
    if (!from || !to || from === to) continue;
    const knownColumns = (entityId: string): Set<string> => {
      const cached = columnsFor.get(entityId);
      if (cached) return cached;
      const dbtUniqueId = dbtModelForEntityId.get(entityId);
      const detail = dbtUniqueId && manifestPath ? loadDbtNodeAuthoringDetail(manifestPath, dbtUniqueId) : undefined;
      const columns = new Set((detail?.columns ?? []).map((column) => column.name.toLowerCase()));
      columnsFor.set(entityId, columns);
      return columns;
    };
    const fromColumns = knownColumns(from);
    const toColumns = knownColumns(to);
    const keys = (candidate.keys ?? []).filter((key) =>
      key?.from && key?.to && fromColumns.has(key.from.toLowerCase()) && toColumns.has(key.to.toLowerCase()));
    if (keys.length === 0) continue;
    const id = authoringSlug(candidate.id || `${from}_to_${to}`).replace(/-/g, '_');
    operations.push({
      id: `relationship:${domain}:${id}`,
      kind: 'modeling_change',
      dependsOn: [`entity:${domain}:${from}`, `entity:${domain}:${to}`].filter((dependency) =>
        operations.some((operation) => operation.id === dependency)),
      evidence: ['Modeling AI proposal from dbt metadata; requires warehouse validation before certification'],
      change: {
        operation: 'upsert_relationship',
        value: {
          id, domain, areaId, from, to, keys,
          cardinality: parseImportedCardinality(candidate.cardinality),
          fanout: parseImportedFanout(candidate.fanout),
          status: 'draft',
          verb: candidate.verb?.trim() || undefined,
          description: candidate.description?.trim() || undefined,
          rationale: candidate.rationale?.trim() || undefined,
        },
      },
    });
  }

  if (operations.length === 0 && droppedOutOfScope > 0) {
    throw new Error(`Modeling AI only proposed ${droppedOutOfScope} model${droppedOutOfScope === 1 ? '' : 's'} outside this subject area, which this request did not ask for. Ask to add models by name to bring new ones in.`);
  }
  if (operations.length === 0) throw new Error('Modeling AI referenced models or columns that are not in the current dbt snapshot, so nothing was proposed.');
  return operations;
}

/**
 * A follow-up turn overwrites the operation it revises and leaves the rest of
 * the draft standing. Operation ids are deterministic, so "make that
 * many_to_one" replaces that one relationship instead of proposing a second.
 */
export function mergeAuthoringOperations(
  base: ContextAuthoringOperation[],
  next: ContextAuthoringOperation[],
): ContextAuthoringOperation[] {
  return [...new Map([...base, ...next].map((operation) => [operation.id, operation])).values()];
}

/**
 * The models an open draft adds. A follow-up may name them ("make that
 * many_to_one") even though they are not committed yet, so they have to count
 * as real for the turn that revises the draft.
 */
export function draftEntityIndex(operations: ContextAuthoringOperation[]): Array<{ id: string; dbtModel: string }> {
  const entities: Array<{ id: string; dbtModel: string }> = [];
  for (const operation of operations) {
    if (operation.kind !== 'modeling_change' || operation.change.operation !== 'upsert_entity') continue;
    const { id, dbtModel } = operation.change.value;
    if (typeof id === 'string' && id && typeof dbtModel === 'string' && dbtModel) entities.push({ id, dbtModel });
  }
  return entities;
}

/**
 * The uncommitted draft a follow-up message revises, when the author is looking
 * at one. A draft built on an older snapshot is ignored — the files moved under
 * it — and the turn starts fresh rather than editing something stale.
 */
function openAuthoringDraft(
  store: FileContextAuthoringProposalStore,
  request: AgentRunRequest,
  snapshotId: string,
  kind: ContextAuthoringOperation['kind'],
): ContextAuthoringProposalV1 | undefined {
  const id = request.workspaceContext?.priorProposalId;
  if (typeof id !== 'string' || !id.trim()) return undefined;
  let proposal: ContextAuthoringProposalV1 | undefined;
  try {
    proposal = store.get(id);
  } catch {
    return undefined;
  }
  if (!proposal || proposal.status !== 'proposed' || proposal.baseSnapshotId !== snapshotId) return undefined;
  return proposal.operations.some((operation) => operation.kind === kind) ? proposal : undefined;
}

/**
 * The id an AI-proposed model is written under. A dbt model already on the map
 * keeps the id it has: generating a fresh snake_case one wrote a second copy of
 * the model beside the original instead of editing it.
 */
export function authoringEntityIdForDbtModel(
  candidateId: string | undefined,
  dbtModel: string,
  existing: Array<{ localId: string; dbtUniqueId: string }>,
): string {
  const bound = existing.find((entity) => entity.dbtUniqueId === dbtModel);
  if (bound) return bound.localId;
  return authoringSlug(candidateId || dbtModel.split('.').at(-1) || 'model').replace(/-/g, '_');
}

/**
 * One spelling for an entity id, so a model that answers `local_team_season_facts`
 * still resolves to the `local-team-season-facts` on the map.
 */
export function normalizeAuthoringEntityId(value: string): string {
  return authoringSlug(value).replace(/-/g, '_');
}

/**
 * Whether a modeling request asks to bring new models in. Without this every
 * "describe" or "connect" request could return a pile of unrequested models.
 */
export function requestAsksForNewModels(question: string, unboundModelNames: string[] = []): boolean {
  // "model"/"models" are deliberately absent: "relationships between the models
  // in this area" is about what is already there, not a request for more.
  if (/\b(add|adds|adding|bind|binds|binding|include|includes|including|import|imports|onboard|onboards|build|builds|building|create|creates|creating|design|designs|designing|set up|expand|extend|capture|captures|cover|covers|new|missing|another|more|extra|remaining|rest of)\b/.test(question.toLowerCase())) return true;
  // Naming something that is not on the map yet ("players performance") asks
  // for it just as plainly as the verb does.
  const tokens = authoringTokens(question);
  return unboundModelNames.some((name) => name.toLowerCase().split(/[^a-z0-9]+/)
    .filter((part) => part.length > 3)
    .some((part) => tokens.includes(part)));
}

type AiModelingCandidate =
  | {
      kind: 'upsert_entity';
      id?: string;
      dbtModel?: string;
      businessName?: string;
      businessContext?: string;
      grain?: string;
      /** Analytical key column names asserted on the bound dbt model. */
      keys: string[];
      analyticalRole?: unknown;
    }
  | {
      kind: 'upsert_relationship';
      id?: string;
      from?: string;
      to?: string;
      keys: Array<{ from: string; to: string }>;
      verb?: string;
      description?: string;
      rationale?: string;
      cardinality?: unknown;
      fanout?: unknown;
    };

/** Tolerant JSON extraction; a malformed provider reply yields no operations. */
export function parseAiModelingOperations(raw: string): AiModelingCandidate[] {
  const fenced = raw.match(/```json\s*([\s\S]*?)```/i)?.[1] ?? raw.match(/```\s*([\s\S]*?)```/)?.[1] ?? raw;
  let parsed: unknown;
  try { parsed = JSON.parse(fenced.trim()); } catch { return []; }
  const text = (value: unknown): string | undefined => (typeof value === 'string' ? value : undefined);
  return contextArray(contextRecord(parsed).operations).flatMap((value): AiModelingCandidate[] => {
    const record = contextRecord(value);
    if (record.kind === 'upsert_entity') {
      return [{
        kind: 'upsert_entity',
        id: text(record.id),
        dbtModel: text(record.dbtModel),
        businessName: text(record.businessName),
        businessContext: text(record.businessContext),
        grain: text(record.grain),
        analyticalRole: record.analyticalRole,
        keys: contextStrings(record.keys),
      }];
    }
    if (record.kind === 'upsert_relationship') {
      return [{
        kind: 'upsert_relationship',
        id: text(record.id),
        from: text(record.from),
        to: text(record.to),
        verb: text(record.verb),
        description: text(record.description),
        rationale: text(record.rationale),
        cardinality: record.cardinality,
        fanout: record.fanout,
        keys: contextArray(record.keys).flatMap((entry) => {
          const key = contextRecord(entry);
          return typeof key.from === 'string' && typeof key.to === 'string' ? [{ from: key.from, to: key.to }] : [];
        }),
      }];
    }
    return [];
  });
}

/**
 * Evidence-only modeling suggestions: deterministic, no provider required.
 *
 * This is the `AGT-024` provider-unavailable fallback, not "Modeling AI". It
 * matches dbt model names against the request and pairs shared `*_id` columns.
 * Callers must label its output honestly so a user is never told a template
 * expansion was an AI proposal.
 */
function buildDeterministicModelingOperations(
  projectRoot: string,
  manifest: DQLManifest,
  request: AgentRunRequest,
): ContextAuthoringOperation[] {
  const modeling = manifest.modeling;
  if (!modeling || !manifest.dbtProvenance) throw new Error('Modeling AI requires a compiled dbt-first project snapshot.');
  const context = request.workspaceContext ?? {};
  const requestedDomain = typeof context.domain === 'string'
    ? context.domain
    : request.selectedObject?.kind === 'domain'
      ? request.selectedObject.id
      : undefined;
  const domain = requestedDomain ?? Object.keys(modeling.packages)[0];
  if (!domain || !modeling.packages[domain]) throw new Error('Select or create a Domain before building models with AI.');
  const selectedIdentity = request.selectedObject?.id;
  const selectedRelationship = request.selectedObject?.kind === 'relationship'
    ? Object.values(modeling.relationships).find((item) => item.qualifiedId === selectedIdentity || item.id === selectedIdentity || item.localId === selectedIdentity)
    : undefined;
  if (selectedRelationship) {
    const cardinality = /one[-_ ]to[-_ ]one|1\s*:\s*1/i.test(request.question)
      ? 'one_to_one'
      : /one[-_ ]to[-_ ]many|1\s*:\s*n/i.test(request.question)
        ? 'one_to_many'
        : /many[-_ ]to[-_ ]one|n\s*:\s*1/i.test(request.question)
          ? 'many_to_one'
          : /many[-_ ]to[-_ ]many|n\s*:\s*n/i.test(request.question)
            ? 'many_to_many'
            : selectedRelationship.cardinality;
    return [{
      id: `relationship:${selectedRelationship.qualifiedId}`,
      kind: 'modeling_change',
      evidence: [selectedRelationship.sourcePath, ...(selectedRelationship.validation?.queryFingerprint ? [`validation:${selectedRelationship.validation.queryFingerprint}`] : [])],
      change: {
        operation: 'upsert_relationship',
        value: {
          id: selectedRelationship.localId,
          domain: selectedRelationship.ownerDomain ?? domain,
          areaId: modelAreaLocalId(selectedRelationship.areaId),
          from: modeling.entities[selectedRelationship.from]?.localId ?? selectedRelationship.from,
          to: modeling.entities[selectedRelationship.to]?.localId ?? selectedRelationship.to,
          keys: selectedRelationship.keys,
          cardinality,
          fanout: selectedRelationship.fanout === 'unsafe' ? 'forbidden' : selectedRelationship.fanout,
          status: 'draft',
          owner: selectedRelationship.owner,
          ownerDomain: selectedRelationship.ownerDomain,
          verb: selectedRelationship.verb,
          description: selectedRelationship.description,
          rationale: request.question.trim(),
          roles: selectedRelationship.roles,
          optionality: selectedRelationship.optionality,
          joinTypes: selectedRelationship.joinTypes,
          aggregation: selectedRelationship.aggregation,
          temporal: selectedRelationship.temporal,
          attributionBlock: selectedRelationship.attributionBlock,
          importRefs: selectedRelationship.importRefs,
          evidenceExpiresAt: undefined,
        },
      },
    }];
  }

  const selectedEntity = request.selectedObject?.kind === 'model'
    ? Object.values(modeling.entities).find((item) => item.qualifiedId === selectedIdentity || item.id === selectedIdentity || item.localId === selectedIdentity)
    : undefined;
  if (selectedEntity) {
    // Without a provider there is nothing evidence-backed to propose here.
    // Copying the raw request into `businessContext` would present the user's
    // own prompt back to them as authored business meaning.
    throw new Error('Writing business context needs an AI provider. Configure one in Settings, or edit this model directly in Modeling.');
  }

  const requestedArea = typeof context.modelAreaId === 'string' ? context.modelAreaId : typeof context.areaId === 'string' ? context.areaId : undefined;
  const existingArea = Object.values(modeling.areas).find((area) => area.domain === domain
    && (!requestedArea || area.qualifiedId === requestedArea || area.localId === requestedArea));
  const areaId = existingArea?.localId ?? modelAreaLocalId(requestedArea) ?? `${authoringSlug(request.question).slice(0, 36) || 'metadata'}_models`;
  const operations: ContextAuthoringOperation[] = [];
  if (!existingArea) {
    operations.push({
      id: `area:${domain}:${areaId}`,
      kind: 'modeling_change',
      evidence: [`domain:${domain}`],
      change: { operation: 'upsert_area', value: { id: areaId, domain, name: titleCaseAuthoring(areaId), description: `Metadata-backed modeling area requested by the author: ${request.question.trim()}`, intentExamples: [request.question.trim()] } },
    });
  }
  const bound = new Set(Object.values(modeling.entities).map((entity) => entity.dbtUniqueId));
  const tokens = authoringTokens(request.question);
  let candidates = Object.values(manifest.dbtProvenance.nodes).filter((node) => !bound.has(node.uniqueId));
  const matched = candidates.filter((node) => tokens.some((token) => `${node.name} ${node.uniqueId} ${node.sourcePath ?? ''}`.toLowerCase().includes(token)));
  if (matched.length) candidates = matched;
  candidates = candidates.slice(0, 12);
  if (candidates.length === 0) throw new Error('No unbound dbt models match this request. Focus an existing model to update its business context.');
  const usedIds = new Set(Object.values(modeling.entities).filter((entity) => entity.domain === domain).map((entity) => entity.localId));
  for (const node of candidates) {
    const base = authoringSlug(node.name).replace(/-/g, '_') || 'model';
    let id = base;
    let suffix = 2;
    while (usedIds.has(id)) id = `${base}_${suffix++}`;
    usedIds.add(id);
    operations.push({
      id: `entity:${domain}:${id}`,
      kind: 'modeling_change',
      dependsOn: existingArea ? [] : [`area:${domain}:${areaId}`],
      evidence: [node.uniqueId, ...(node.sourcePath ? [node.sourcePath] : [])],
      change: { operation: 'upsert_entity', value: { id, domain, areaId, dbtModel: node.uniqueId, businessName: titleCaseAuthoring(node.name), status: 'draft', analyticalRole: 'unknown' } },
    });
  }

  if (/\b(connect|relationship|join|related)\b/i.test(request.question) && candidates.length >= 2) {
    const manifestPath = resolveDbtManifestPath(projectRoot);
    const left = manifestPath ? loadDbtNodeAuthoringDetail(manifestPath, candidates[0]!.uniqueId) : undefined;
    const right = manifestPath ? loadDbtNodeAuthoringDetail(manifestPath, candidates[1]!.uniqueId) : undefined;
    const rightColumns = new Set((right?.columns ?? []).map((column) => column.name.toLowerCase()));
    const sharedKey = (left?.columns ?? []).map((column) => column.name).find((name) => /(^id$|_id$)/i.test(name) && rightColumns.has(name.toLowerCase()));
    if (sharedKey) {
      const fromOperation = operations.find((operation) => operation.id.startsWith('entity:') && operation.kind === 'modeling_change' && operation.change.operation === 'upsert_entity' && operation.change.value.dbtModel === candidates[0]!.uniqueId);
      const toOperation = operations.find((operation) => operation.id.startsWith('entity:') && operation.kind === 'modeling_change' && operation.change.operation === 'upsert_entity' && operation.change.value.dbtModel === candidates[1]!.uniqueId);
      if (fromOperation?.kind === 'modeling_change' && fromOperation.change.operation === 'upsert_entity' && toOperation?.kind === 'modeling_change' && toOperation.change.operation === 'upsert_entity') {
        const relationshipId = `${fromOperation.change.value.id}_to_${toOperation.change.value.id}`;
        operations.push({
          id: `relationship:${domain}:${relationshipId}`,
          kind: 'modeling_change',
          dependsOn: [fromOperation.id, toOperation.id],
          evidence: [`shared column suggestion:${sharedKey}`, left?.uniqueId ?? '', right?.uniqueId ?? ''].filter(Boolean),
          change: { operation: 'upsert_relationship', value: { id: relationshipId, domain, areaId, from: fromOperation.change.value.id, to: toOperation.change.value.id, keys: [{ from: sharedKey, to: sharedKey }], cardinality: 'unknown', fanout: 'unknown', status: 'draft', rationale: 'Candidate only: shared dbt column name requires warehouse validation.' } },
        });
      }
    }
  }
  return operations;
}

/**
 * Skills AI: draft a domain skill's purpose, guardrails, and vocabulary.
 *
 * `SKILL-006` — the model sees qualified modeling/metric references, the
 * current skill, and the Domain/Area scope. It writes prose and vocabulary
 * only; every governed reference is taken from the deterministic base built
 * below, so it cannot invent a metric, block, or model. `previewContextAuthoring`
 * independently forces `status: 'draft'`, so a drafted skill never guides an
 * agent until a human activates it.
 */
async function buildAiSkillOperations(
  projectRoot: string,
  manifest: DQLManifest,
  request: AgentRunRequest,
  provider: AgentProvider,
  priorOperations: ContextAuthoringOperation[] = [],
): Promise<ContextAuthoringOperation[]> {
  const base = buildMetadataBoundSkillOperations(projectRoot, manifest, request);
  const operation = base[0];
  if (!operation || operation.kind !== 'skill_change') return base;
  // A follow-up ("give it more trigger words") edits the draft on screen, not
  // the saved skill the draft was built from.
  const priorDraft = priorOperations.find((candidate) => candidate.kind === 'skill_change' && candidate.id === operation.id);
  const current = priorDraft && priorDraft.kind === 'skill_change' ? priorDraft : operation;

  const raw = await provider.generate([
    {
      role: 'system',
      content: [
        'You write governed analytics guidance for one business domain.',
        'Return exactly one JSON object in a ```json fence: {"description":"...","body":"...","triggers":["..."],"clarifyWhen":["..."],"vocabulary":{"term":"meaning"}}. No prose outside the fence.',
        'body is markdown with a "## Purpose" section, a "## Guardrails" section, and a "## Clarify" section.',
        'Write guidance an analyst would follow. Never restate the request back as the guidance.',
        'Never name a metric, block, model, or relationship that is not in the supplied governed references.',
        'Do not grant tools, authorize joins or data access, activate the skill, or write executable code.',
      ].join(' '),
    },
    {
      role: 'user',
      content: JSON.stringify({
        request: request.question.trim(),
        domain: operation.value.domain,
        modelAreaRefs: operation.value.modelAreaRefs,
        currentSkill: { id: current.value.id, description: current.value.description, body: current.value.body },
        ...(priorDraft ? { revising: 'currentSkill is the draft from the previous turn; change only what this request asks for.' } : {}),
        governedReferences: {
          metrics: operation.value.preferredMetrics,
          blocks: operation.value.preferredBlocks,
          modelingRefs: operation.value.sourceRefs,
        },
      }),
    },
  ], { maxTokens: 2000, temperature: 0.2 });

  const fenced = raw.match(/```json\s*([\s\S]*?)```/i)?.[1] ?? raw.match(/```\s*([\s\S]*?)```/)?.[1] ?? raw;
  let parsed: Record<string, unknown>;
  try { parsed = contextRecord(JSON.parse(fenced.trim())); } catch { return base; }
  const body = typeof parsed.body === 'string' ? parsed.body.trim() : '';
  if (!body) return base;

  const vocabulary = contextRecord(parsed.vocabulary);
  return [{
    ...current,
    evidence: [...(current.evidence ?? []), 'drafted by Skills AI from governed references only'],
    value: {
      ...current.value,
      description: typeof parsed.description === 'string' && parsed.description.trim() ? parsed.description.trim() : operation.value.description,
      body,
      triggers: contextStrings(parsed.triggers).slice(0, 12).length ? contextStrings(parsed.triggers).slice(0, 12) : operation.value.triggers,
      clarifyWhen: contextStrings(parsed.clarifyWhen).slice(0, 8).length ? contextStrings(parsed.clarifyWhen).slice(0, 8) : operation.value.clarifyWhen,
      vocabulary: Object.fromEntries(Object.entries(vocabulary)
        .filter(([, value]) => typeof value === 'string')
        .slice(0, 24)) as Record<string, string>,
      // Governed references always come from the deterministic base; the model
      // never gets to add one.
      preferredMetrics: operation.value.preferredMetrics,
      preferredBlocks: operation.value.preferredBlocks,
      sourceRefs: operation.value.sourceRefs,
      status: 'draft',
    },
  }];
}

function buildMetadataBoundSkillOperations(
  projectRoot: string,
  manifest: DQLManifest,
  request: AgentRunRequest,
): ContextAuthoringOperation[] {
  const context = request.workspaceContext ?? {};
  const selectedIdentity = request.selectedObject?.kind === 'skill' ? request.selectedObject.id : undefined;
  const existing = selectedIdentity
    ? loadSkills(projectRoot).skills.find((skill) => skill.qualifiedId === selectedIdentity || skill.id === selectedIdentity)
    : undefined;
  const domain = typeof context.domain === 'string'
    ? context.domain
    : existing?.domain
      ?? (request.selectedObject?.kind === 'domain' ? request.selectedObject.id : undefined)
      ?? Object.keys(manifest.modeling?.packages ?? {})[0];
  if (!domain) throw new Error('Select a Domain before building a Skill with AI.');
  const area = typeof context.modelAreaId === 'string' ? context.modelAreaId : existing?.modelAreaRefs?.[0];
  const focusReference = request.selectedObject?.kind === 'model' || request.selectedObject?.kind === 'relationship'
    ? request.selectedObject.id
    : undefined;
  if (focusReference && !contextSourceReferenceExists(manifest, focusReference)) throw new Error('The focused modeling object is not present in the current snapshot.');
  const id = existing?.localId ?? existing?.id ?? skillDraftId(request.question, domain);
  const body = existing
    ? `${existing.body.trim()}\n\n## Proposed correction\n${request.question.trim()}\n`
    : `## Purpose\nGuide analysis for ${domain} using reviewed repository metadata.\n\n## Guardrails\n${request.question.trim()}\n\n## Clarify\nAsk when the requested metric, model, or relationship is not governed.`;
  const value: WriteSkillInput = {
    id,
    qualifiedId: existing?.qualifiedId,
    sourcePath: existing?.sourcePath,
    scope: 'project',
    domain,
    domains: [domain],
    modelAreaRefs: area ? [area] : [],
    kind: existing?.kind ?? 'domain_reference',
    status: 'draft',
    owner: existing?.owner,
    triggers: existing?.triggers ?? authoringTokens(request.question).slice(0, 8),
    exclusions: existing?.exclusions ?? [],
    description: existing?.description ?? `Metadata-backed guidance for ${titleCaseAuthoring(domain)}.`,
    preferredMetrics: existing?.preferredMetrics ?? Object.values(manifest.metrics ?? {}).filter((metric) => metric.domain === domain).slice(0, 12).map((metric) => metric.name),
    preferredBlocks: existing?.preferredBlocks ?? Object.values(manifest.blocks ?? {}).filter((block) => block.domain === domain && block.status === 'certified').slice(0, 12).map((block) => block.name),
    preferredDimensions: existing?.preferredDimensions ?? [],
    requiredFilters: existing?.requiredFilters ?? [],
    clarifyWhen: existing?.clarifyWhen ?? ['The request needs a model, metric, or relationship not present in the current governed context.'],
    examples: existing?.examples ?? [request.question.trim()],
    sourceRefs: [...new Set([...(existing?.sourceRefs ?? []), ...(focusReference ? [focusReference] : [])])],
    vocabulary: existing?.vocabulary ?? {},
    analyticalPolicy: existing?.analyticalPolicy,
    body,
    isStarter: existing?.isStarter,
  };
  const before = existing?.sourcePath && existsSync(existing.sourcePath) ? readFileSync(existing.sourcePath, 'utf8') : '';
  return [{
    id: `skill:${existing?.qualifiedId ?? `${domain}::skill::${id}`}`,
    kind: 'skill_change',
    operation: existing ? 'update' : 'create',
    targetQualifiedId: existing?.qualifiedId,
    expectedSourceHash: existing ? createHash('sha256').update(before).digest('hex') : undefined,
    evidence: [existing?.sourcePath ?? `domain:${domain}`, ...(focusReference ? [focusReference] : [])],
    value,
  }];
}

/**
 * The Domain an author lands in when none is selected: the single existing
 * Domain if there is exactly one, otherwise a new one named after the dbt
 * project. Callers keep full control — this is only the prefilled default.
 */
function defaultAuthoringDomainId(manifest: DQLManifest): string {
  const packages = Object.keys(manifest.modeling?.packages ?? {});
  if (packages.length === 1) return packages[0]!;
  const projectName = manifest.dbtProvenance?.projectName;
  return projectName ? authoringSlug(projectName).replace(/-/g, '_') || 'analytics' : 'analytics';
}

function authoringTokens(value: string): string[] {
  const stop = new Set(['the', 'and', 'for', 'with', 'from', 'this', 'that', 'build', 'create', 'model', 'models', 'skill', 'please', 'into', 'about']);
  return [...new Set(value.toLowerCase().split(/[^a-z0-9_]+/).filter((token) => token.length > 2 && !stop.has(token)))];
}

/**
 * A drafted skill is named for its subject, not for the sentence that asked for
 * it: "create a skill: team wins ... trigger words wins, record" became the id
 * `create-a-skill-team-wins-for-a-season-come-from--guidance`.
 */
export function skillDraftId(question: string, domain: string): string {
  const words = authoringTokens(question).filter((token) => token.length <= 18).slice(0, 4);
  const base = (words.join('-') || authoringSlug(domain) || 'domain').slice(0, 48).replace(/-+$/, '');
  return `${base}-guidance`;
}

function authoringSlug(value: string): string {
  return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function titleCaseAuthoring(value: string): string {
  return value.replace(/[._-]+/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
}

interface ContextBootstrapSession {
  id: string;
  createdAt: string;
  closedAt?: string;
  persistence: 'session-only';
  candidates: ReturnType<typeof draftDomainSkillBootstrap>;
  status: 'queued' | 'inventory' | 'grounding' | 'generating' | 'validating' | 'ready' | 'needs_attention';
  ai: {
    requested: boolean;
    mode: 'pending' | 'provider' | 'evidence_only';
    provider?: string;
  };
  progress: {
    percent: number;
    message: string;
    domains: { total: number; ready: number };
    skills: { total: number; ready: number };
    events: string[];
  };
  warnings?: string[];
}

function contextBootstrapDir(projectRoot: string): string {
  return join(projectRoot, '.dql', 'local', 'context-bootstrap');
}

function contextBootstrapPath(projectRoot: string, id: string): string {
  const safe = id.replace(/[^a-zA-Z0-9_-]/g, '');
  return join(contextBootstrapDir(projectRoot), `${safe}.json`);
}

function writeContextBootstrapSession(
  projectRoot: string,
  input: Pick<ContextBootstrapSession, 'candidates' | 'status' | 'ai' | 'progress'> & Partial<Pick<ContextBootstrapSession, 'warnings'>>,
): ContextBootstrapSession {
  const id = `ctx_${Date.now().toString(36)}_${createHash('sha1').update(JSON.stringify(input.candidates)).digest('hex').slice(0, 8)}`;
  const session: ContextBootstrapSession = { id, createdAt: new Date().toISOString(), persistence: 'session-only', ...input };
  const dir = contextBootstrapDir(projectRoot);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(contextBootstrapPath(projectRoot, id), JSON.stringify(session, null, 2), 'utf-8');
  return session;
}

function updateContextBootstrapSession(
  projectRoot: string,
  id: string,
  update: (session: ContextBootstrapSession) => ContextBootstrapSession,
): ContextBootstrapSession | null {
  const current = readContextBootstrapSession(projectRoot, id);
  if (!current) return null;
  const next = update(current);
  writeFileSync(contextBootstrapPath(projectRoot, id), JSON.stringify(next, null, 2), 'utf-8');
  return next;
}

function bootstrapProgress(candidates: ReturnType<typeof draftDomainSkillBootstrap>, readyCandidateIds: Set<string>, percent: number, message: string, events: string[]) {
  const count = (kind: 'domain' | 'skill') => {
    const all = candidates.filter((candidate) => candidate.kind === kind);
    return { total: all.length, ready: all.filter((candidate) => readyCandidateIds.has(candidate.id)).length };
  };
  return { percent, message, domains: count('domain'), skills: count('skill'), events: events.slice(-6) };
}

async function enrichContextBootstrapSession(projectRoot: string, id: string): Promise<void> {
  // One compiled snapshot serves the entire session; do not re-search a large
  // repository for every domain/skill candidate.
  const manifest = buildManifest({ projectRoot, dqlVersion: 'notebook' });
  let session = updateContextBootstrapSession(projectRoot, id, (current) => ({
    ...current,
    status: 'inventory',
    progress: bootstrapProgress(current.candidates, new Set(), 12, 'Repository inventory is ready. Checking the configured AI provider…', ['Repository inventory complete.']),
  }));
  if (!session) return;
  const provider = session.ai.requested ? await createBlockStudioAssistProvider(projectRoot) : null;
  if (!provider) {
    updateContextBootstrapSession(projectRoot, id, (current) => ({
      ...current,
      status: 'ready',
      ai: { ...current.ai, mode: 'evidence_only' },
      progress: bootstrapProgress(current.candidates, new Set(current.candidates.map((candidate) => candidate.id)), 100, 'Evidence-first draft is ready. Configure an AI provider to enrich its prose and guidance.', ['Repository inventory complete.', 'No configured AI provider was available; retained evidence-only drafts.']),
      warnings: [...(current.warnings ?? []), 'No configured AI provider was available. Candidates were drafted from repository evidence only.'],
    }));
    return;
  }
  session = updateContextBootstrapSession(projectRoot, id, (current) => ({
    ...current,
    status: 'grounding',
    ai: { ...current.ai, mode: 'provider', provider: provider.name },
    progress: bootstrapProgress(current.candidates, new Set(), 25, `Grounding ${current.candidates.length} candidate(s) in governed repository metadata…`, ['Repository inventory complete.', `Using ${provider.name} to enrich bounded guidance.`]),
  }));
  if (!session) return;

  const chunks: Array<ReturnType<typeof draftDomainSkillBootstrap>> = [];
  for (let index = 0; index < session.candidates.length; index += 4) chunks.push(session.candidates.slice(index, index + 4));
  const complete = new Set<string>();
  const warnings: string[] = [];
  for (let index = 0; index < chunks.length; index += 1) {
    const before = readContextBootstrapSession(projectRoot, id);
    if (!before) return;
    updateContextBootstrapSession(projectRoot, id, (current) => ({
      ...current,
      status: 'generating',
      progress: bootstrapProgress(current.candidates, complete, 25 + Math.floor((index / Math.max(chunks.length, 1)) * 60), `Writing grounded guidance for ${index * 4 + 1}–${Math.min((index + 1) * 4, current.candidates.length)} of ${current.candidates.length} candidates…`, [...current.progress.events, `AI enrichment batch ${index + 1} of ${chunks.length}.`]),
    }));
    const prompt = buildDomainSkillBootstrapPrompt(manifest, chunks[index]);
    try {
      const response = await provider.generate([
        { role: 'system', content: prompt.system },
        { role: 'user', content: prompt.user },
      ], { maxTokens: 1800, temperature: 0.1 });
      updateContextBootstrapSession(projectRoot, id, (current) => {
        const candidateById = new Map(current.candidates.map((candidate) => [candidate.id, candidate]));
        const currentChunk = chunks[index].map((candidate) => candidateById.get(candidate.id) ?? candidate);
        const merged = mergeDomainSkillBootstrapEnrichment(currentChunk, response);
        for (const candidate of merged.candidates) candidateById.set(candidate.id, candidate);
        for (const candidate of chunks[index]) complete.add(candidate.id);
        warnings.push(...merged.rejected);
        const candidates = current.candidates.map((candidate) => candidateById.get(candidate.id) ?? candidate);
        return {
          ...current,
          candidates,
          progress: bootstrapProgress(candidates, complete, 25 + Math.floor(((index + 1) / Math.max(chunks.length, 1)) * 60), `Grounded guidance ready for ${complete.size} of ${candidates.length} candidates.`, [...current.progress.events, `AI enrichment batch ${index + 1} complete.`]),
        };
      });
    } catch (error) {
      for (const candidate of chunks[index]) complete.add(candidate.id);
      warnings.push(`AI enrichment batch ${index + 1} failed: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
  updateContextBootstrapSession(projectRoot, id, (current) => ({
    ...current,
    status: warnings.length ? 'needs_attention' : 'ready',
    progress: bootstrapProgress(current.candidates, new Set(current.candidates.map((candidate) => candidate.id)), 100, warnings.length ? 'Drafts are ready; review the noted AI enrichment gaps before saving.' : 'Grounded domain and skill drafts are ready for review.', [...current.progress.events, warnings.length ? 'Some AI enrichment needs attention.' : 'Validation complete.']),
    warnings: warnings.length ? [...(current.warnings ?? []), ...warnings] : current.warnings,
  }));
}

function readContextBootstrapSession(projectRoot: string, id: string): ContextBootstrapSession | null {
  const path = contextBootstrapPath(projectRoot, id);
  if (!existsSync(path)) return null;
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf-8')) as ContextBootstrapSession;
    return parsed?.id === id && Array.isArray(parsed.candidates) ? parsed : null;
  } catch {
    return null;
  }
}

function latestOpenContextBootstrapSession(projectRoot: string): ContextBootstrapSession | null {
  const dir = contextBootstrapDir(projectRoot);
  if (!existsSync(dir)) return null;
  const paths = readdirSync(dir)
    .filter((name) => name.endsWith('.json'))
    .map((name) => join(dir, name))
    .sort((left, right) => statSync(right).mtimeMs - statSync(left).mtimeMs);
  for (const path of paths) {
    try {
      const session = JSON.parse(readFileSync(path, 'utf-8')) as ContextBootstrapSession;
      if (session?.id && Array.isArray(session.candidates) && !session.closedAt) return session;
    } catch {
      // A truncated local session should not hide an earlier valid session.
    }
  }
  return null;
}

/**
 * API-004 / E2E-006: save-time compile for Block Studio. The manifest is
 * replaced atomically so lineage readers and agent retrieval never observe a
 * half-written snapshot, and an existing manifest survives compilation errors.
 */
export function compileBlockStudioManifest(
  projectRoot: string,
  projectConfig: ProjectConfig = loadProjectConfig(projectRoot),
): DQLManifest {
  const dbtManifestPath = resolveDbtManifestPath(projectRoot, projectConfig) ?? undefined;
  const manifest = buildManifest({ projectRoot, dqlVersion: 'notebook', dbtManifestPath });
  const manifestPath = join(projectRoot, 'dql-manifest.json');
  const tempPath = `${manifestPath}.tmp-${process.pid}-${Date.now()}`;
  try {
    writeFileSync(tempPath, `${JSON.stringify(manifest, null, 2)}\n`, 'utf-8');
    renameSync(tempPath, manifestPath);
  } catch (error) {
    rmSync(tempPath, { force: true });
    throw error;
  }
  _lineageCache.delete(projectRoot);
  return manifest;
}

async function refreshLocalMetadataCatalog(
  projectRoot: string,
  manifest?: DQLManifest,
  semanticLayer?: SemanticLayer | null,
  force = true,
): Promise<void> {
  try {
    await ensureMetadataCatalogFresh(projectRoot, {
      force,
      ...(manifest ? { manifest } : {}),
      ...(semanticLayer ? { semanticLayer } : {}),
    });
  } catch {
    // The catalog is a rebuildable local cache. Save/certify flows should not
    // fail only because metadata refresh hit a stale dbt or semantic config.
  }
}

function renderNotFound(path: string): string {
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <title>DQL Local Runtime</title>
    <style>
      body { font-family: Inter, system-ui, sans-serif; margin: 40px; color: #111827; }
      code { background: #f3f4f6; padding: 2px 6px; border-radius: 6px; }
    </style>
  </head>
  <body>
    <h1>DQL Local Runtime</h1>
    <p>No file exists for <code>${escapeHtml(path)}</code>.</p>
    <p>Try opening <code>/</code> or confirm that you built the bundle correctly.</p>
  </body>
</html>`;
}

function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

export function findProjectRoot(startDir: string): string {
  let current = resolve(startDir);
  while (true) {
    if (existsSync(join(current, 'dql.config.json'))) {
      return current;
    }
    const parent = dirname(current);
    if (parent === current) {
      return startDir;
    }
    current = parent;
  }
}

export function loadProjectConfig(projectRoot: string): ProjectConfig {
  const configPath = join(projectRoot, 'dql.config.json');
  if (!existsSync(configPath)) {
    return {};
  }

  const raw = JSON.parse(readFileSync(configPath, 'utf-8')) as Record<string, unknown>;
  const config = raw as unknown as ProjectConfig;

  const connections = getStoredConnections(raw);
  const defaultConnectionName = resolveDefaultConnectionKey(raw, connections);
  if (defaultConnectionName) {
    const selected = normalizeStoredConnection(connections[defaultConnectionName]);
    if (selected) {
      config.defaultConnection = selected;
      config.defaultConnectionName = defaultConnectionName;
    }
  } else if (config.defaultConnection) {
    const normalized = normalizeStoredConnection(config.defaultConnection as ConnectionConfig & { path?: string; type?: string });
    if (normalized) {
      config.defaultConnection = normalized;
    }
  }

  return config;
}

export interface SkillPathSettings {
  path: string;
  resolvedPath: string;
  exists: boolean;
  skillCount: number;
  errorCount: number;
}

/** Current Git-backed Skills folder and what the loader can read from it. */
export function buildSkillPathSettings(projectRoot: string): SkillPathSettings {
  const resolvedPath = skillsDir(projectRoot);
  const loaded = loadSkills(projectRoot);
  return {
    path: configuredSkillsPath(projectRoot),
    resolvedPath,
    exists: existsSync(resolvedPath) && statSync(resolvedPath).isDirectory(),
    skillCount: loaded.skills.filter((skill) => skill.scope === 'project').length,
    errorCount: loaded.errors.length,
  };
}

function dbtFirstOwnsSemanticAuthoring(config: ProjectConfig): boolean {
  return config.manifestVersion === 3 && config.modeling?.mode === 'dbt-first';
}

function sendDbtOwnedSemanticAuthoringError(res: {
  writeHead(statusCode: number, headers: Record<string, string>): unknown;
  end(chunk?: string): unknown;
}): void {
  res.writeHead(409, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(serializeJSON({
    error: 'dbt-first projects use dbt/MetricFlow as the physical and metric source of truth. Edit the dbt project and refresh artifacts instead of creating duplicate local semantic definitions.',
    code: 'DQL_MODELING_DBT_OWNED',
    nextAction: 'Create or edit the metric in dbt/MetricFlow, run dbt parse or dbt build, then run dql sync dbt.',
  }));
}

/**
 * Shape returned by `/api/propose`. Drives the notebook Readiness surface:
 * a readiness summary plus a ranked queue of DRAFT proposals, each carrying its
 * stored Certifier verdict ("what's missing to certify"). The endpoint NEVER
 * certifies — proposals always render as AI-Generated drafts and route into the
 * existing human review/certify flow.
 */
export interface ProposeReadinessResult {
  /** True when a dbt manifest was found and the engine ran. */
  ready: boolean;
  /**
   * Why the engine could not run (no dbt manifest). Present only when
   * `ready === false`; the UI shows this as a "what to do next" hint.
   */
  reason?: string;
  summary: {
    projectName?: string;
    /** dbt models the engine scanned (whole manifest). */
    modelsScanned: number;
    /** Models classified `business` by the cascade. */
    businessModels: number;
    /** Models classified `plumbing` and excluded from generation. */
    plumbingExcluded: number;
    /** Semantic metrics discovered in the manifest. */
    metricsFound: number;
    /** Selected (bounded, business-only) proposals the engine ranked. */
    proposalsRanked: number;
    /** Drafts already written to the project (skipped on re-run). */
    draftsExisting: number;
    /** Proposals with zero blocking certifier errors (closest to certifiable). */
    readyForReview: number;
    /** Total blocking certifier errors across the queue. */
    blockingTotal: number;
    /** Total certifier warnings across the queue. */
    warningTotal: number;
    /** Review telemetry for the ranked queue. */
    reviewTelemetry?: {
      existingDrafts: number;
      medianReviewAgeHours: number | null;
      readyForReviewRate: number | null;
      estimatedReviewMinutes: number;
    };
  };
  /**
   * Deterministic PLAN of the bounded, business-only seed (writes nothing).
   * Drives the plan/approve gate in the Get Started flow.
   */
  plan: ProposePlan;
  /** Ranked DRAFT proposals for the selected scope (engine order preserved). */
  proposals: ReviewableProposalResult[];
}

export interface ReviewableProposalResult extends ProposalResult {
  /** One-screen review handoff for the certification flywheel. */
  review: {
    queueRank: number;
    status: 'new' | 'draft_exists' | 'ready_for_review';
    priorityScore: number;
    blockingCount: number;
    warningCount: number;
    estimatedReviewMinutes: number;
    draftPath: string;
    draftExists: boolean;
    firstSeenAt?: string;
    lastUpdatedAt?: string;
    reviewAgeHours?: number;
    certifyCommand: string;
    payload: {
      question: string;
      model: string;
      domain: string;
      sqlPreview?: string;
      outputs: string[];
      grain?: string;
      pattern?: string;
      evidence: string[];
      resultSample: { status: 'not_run'; rows: [] };
      nearestCertifiedBlock?: {
        name: string;
        path?: string;
        domain?: string;
        overlapScore: number;
        sharedOutputs: string[];
      };
    };
  };
}

/**
 * Core of the `/api/propose` endpoint, factored out as a pure function so it can
 * be unit-tested without standing up an HTTP server.
 *
 * It reuses the existing `propose` engine from `@duckcodeailabs/dql-agent`
 * verbatim (no inference/ranking logic is duplicated here) in `dryRun` mode so a
 * readiness preview never mutates the project. Every returned proposal is a
 * `status: draft` block with the engine's stored Certifier verdict attached.
 */
export function buildProposeReadiness(
  projectRoot: string,
  projectConfig: ProjectConfig = loadProjectConfig(projectRoot),
  options: { owner?: string; limit?: number } = {},
): ProposeReadinessResult {
  const manifestPath = resolveDbtManifestPath(projectRoot, projectConfig);
  if (!manifestPath) {
    return {
      ready: false,
      reason:
        'No dbt manifest found. Run `dbt parse` (or `dbt compile`) in your dbt project, then reopen Get Started.',
      summary: {
        modelsScanned: 0,
        businessModels: 0,
        plumbingExcluded: 0,
        metricsFound: 0,
        proposalsRanked: 0,
        draftsExisting: 0,
        readyForReview: 0,
        blockingTotal: 0,
        warningTotal: 0,
      },
      plan: {
        totals: { modelsScanned: 0, businessModels: 0, plumbingExcluded: 0, metricsFound: 0 },
        willGenerate: 0,
        willSkip: 0,
        domains: [],
        config: {
          businessLayers: [],
          excludeLayers: [],
          maxPerDomain: 0,
          minScore: 0,
          aiEnrichment: 'auto',
        },
      },
      proposals: [],
    };
  }

  const proposeConfig: ProposeConfigInput | undefined = projectConfig.propose;

  // PLAN: deterministic, business-only, bounded. Writes nothing.
  const plan: ProposePlan = proposePlan(projectRoot, manifestPath, { config: proposeConfig });

  // dryRun: rank + certify the selected scope only. Never writes from a preview.
  // Stamp the resolved local OSS owner when none was passed so the stored verdict
  // does not carry a phantom "Missing owner" strike. Read-only resolution — the
  // preview must not mutate the project.
  const summary: ProposeSummary = propose({
    projectRoot,
    dbtManifestPath: manifestPath,
    owner: options.owner || resolveLocalOwner(projectRoot, { persist: false }),
    limit: options.limit,
    dryRun: true,
    config: proposeConfig,
  });

  let readyForReview = 0;
  let blockingTotal = 0;
  let warningTotal = 0;
  for (const proposal of summary.proposals) {
    blockingTotal += proposal.certification.errors.length;
    warningTotal += proposal.certification.warnings.length;
    if (proposal.certification.errors.length === 0) readyForReview += 1;
  }
  const reviewableProposals = buildReviewableProposals(projectRoot, manifestPath, projectConfig, summary.proposals, options.owner);
  const reviewAges = reviewableProposals
    .map((proposal) => proposal.review.reviewAgeHours)
    .filter((value): value is number => typeof value === 'number' && Number.isFinite(value));
  const estimatedReviewMinutes = reviewableProposals.reduce((sum, proposal) => sum + proposal.review.estimatedReviewMinutes, 0);

  return {
    ready: true,
    summary: {
      projectName: summary.projectName,
      modelsScanned: summary.modelsScanned,
      businessModels: summary.businessModels,
      plumbingExcluded: summary.plumbingExcluded,
      metricsFound: summary.metricsFound,
      proposalsRanked: summary.proposalsRanked,
      // In dryRun the engine marks already-present blocks as skipped.
      draftsExisting: summary.draftsSkipped,
      readyForReview,
      blockingTotal,
      warningTotal,
      reviewTelemetry: {
        existingDrafts: reviewableProposals.filter((proposal) => proposal.review.draftExists).length,
        medianReviewAgeHours: median(reviewAges),
        readyForReviewRate: ratio(readyForReview, summary.proposalsRanked),
        estimatedReviewMinutes,
      },
    },
    plan,
    proposals: reviewableProposals,
  };
}

function buildReviewableProposals(
  projectRoot: string,
  dbtManifestPath: string,
  projectConfig: ProjectConfig,
  proposals: ProposalResult[],
  owner?: string,
): ReviewableProposalResult[] {
  const manifest = safeBuildProjectManifest(projectRoot);
  return proposals.map((proposal, index) => {
    const preview = buildProposePreview(projectRoot, dbtManifestPath, proposal.slug, {
      config: projectConfig.propose,
      owner,
    });
    const draftPath = proposal.path ?? resolveProposeDraftPath(projectRoot, proposal.domain, proposal.slug);
    const draftFile = join(projectRoot, draftPath);
    const draftExists = existsSync(draftFile);
    const stats = draftExists ? statSync(draftFile) : undefined;
    const firstSeenAt = stats ? stableFsTime(stats.birthtimeMs, stats.ctimeMs) : undefined;
    const lastUpdatedAt = stats ? stableFsTime(stats.mtimeMs, stats.ctimeMs) : undefined;
    const reviewAgeHours = firstSeenAt ? hoursSince(firstSeenAt) : undefined;
    const blockingCount = proposal.certification.errors.length;
    const warningCount = proposal.certification.warnings.length;
    const outputs = preview?.outputs ?? proposal.inference.declaredOutputs;
    const status = blockingCount === 0
      ? 'ready_for_review'
      : draftExists
        ? 'draft_exists'
        : 'new';

    return {
      ...proposal,
      review: {
        queueRank: index + 1,
        status,
        priorityScore: proposal.ranking.score,
        blockingCount,
        warningCount,
        estimatedReviewMinutes: estimateProposalReviewMinutes(blockingCount, warningCount, Boolean(preview?.sqlPreview)),
        draftPath,
        draftExists,
        firstSeenAt,
        lastUpdatedAt,
        reviewAgeHours,
        certifyCommand: `dql certify --from-draft ${quoteCliArg(draftPath)} --owner you@example.com`,
        payload: {
          question: preview?.examples?.[0] ?? proposal.inference.examples[0]?.question ?? `Review ${proposal.slug}`,
          model: proposal.model,
          domain: proposal.domain,
          sqlPreview: preview?.sqlPreview,
          outputs,
          grain: preview?.grain ?? proposal.inference.grain,
          pattern: preview?.pattern ?? proposal.inference.pattern,
          evidence: proposal.evidence,
          resultSample: { status: 'not_run', rows: [] },
          nearestCertifiedBlock: findNearestCertifiedBlock(manifest, proposal, outputs),
        },
      },
    };
  });
}

function safeBuildProjectManifest(projectRoot: string): DQLManifest {
  try {
    return buildManifest({ projectRoot });
  } catch {
    return { blocks: {} } as DQLManifest;
  }
}

function resolveProposeDraftPath(projectRoot: string, domain: string, slug: string): string {
  const safeDomain = domain
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9/_-]+/g, '-')
    .replace(/^[-/]+|[-/]+$/g, '');
  return safeDomain && existsSync(join(projectRoot, 'domains', safeDomain))
    ? `domains/${safeDomain}/blocks/_drafts/${slug}.dql`
    : `blocks/_drafts/${slug}.dql`;
}

function findNearestCertifiedBlock(
  manifest: DQLManifest,
  proposal: ProposalResult,
  outputs: string[],
): ReviewableProposalResult['review']['payload']['nearestCertifiedBlock'] {
  const outputSet = new Set(outputs.map((output) => output.toLowerCase()));
  let best: ReviewableProposalResult['review']['payload']['nearestCertifiedBlock'];
  for (const block of Object.values(manifest.blocks ?? {})) {
    if (String(block.status ?? '').toLowerCase() !== 'certified') continue;
    const blockOutputs = (block.declaredOutputs ?? []).map((output) => output.toLowerCase());
    const sharedOutputs = blockOutputs.filter((output) => outputSet.has(output));
    const sameDomain = block.domain === proposal.domain;
    const overlapScore = sharedOutputs.length * 10 + (sameDomain ? 5 : 0);
    if (overlapScore <= 0) continue;
    if (!best || overlapScore > best.overlapScore) {
      best = {
        name: block.name,
        path: block.filePath,
        domain: block.domain,
        overlapScore,
        sharedOutputs,
      };
    }
  }
  return best;
}

function estimateProposalReviewMinutes(blockingCount: number, warningCount: number, hasSqlPreview: boolean): number {
  const base = hasSqlPreview ? 12 : 18;
  return base + blockingCount * 8 + warningCount * 4;
}

function stableFsTime(primaryMs: number, fallbackMs: number): string | undefined {
  const ms = Number.isFinite(primaryMs) && primaryMs > 0 ? primaryMs : fallbackMs;
  return Number.isFinite(ms) && ms > 0 ? new Date(ms).toISOString() : undefined;
}

function hoursSince(iso: string): number {
  const ts = Date.parse(iso);
  if (!Number.isFinite(ts)) return 0;
  return Number(Math.max(0, (Date.now() - ts) / 3_600_000).toFixed(2));
}

function median(values: number[]): number | null {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  const value = sorted.length % 2 === 1
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
  return Number(value.toFixed(2));
}

function ratio(numerator: number, denominator: number): number | null {
  if (denominator === 0) return null;
  return Number((numerator / denominator).toFixed(4));
}

function quoteCliArg(value: string): string {
  if (/^[A-Za-z0-9_./:-]+$/.test(value)) return value;
  return `'${value.replace(/'/g, "'\\''")}'`;
}

export interface SemanticCompostingChangesetResult {
  ready: boolean;
  reason?: string;
  summary: {
    certifiedBlocksScanned: number;
    eligibleMetricClusters: number;
    candidatesRanked: number;
    existingDrafts: number;
    donorBlocksUsed: number;
    minSupport: number;
  };
  candidates: SemanticCompostingMetricCandidate[];
  /** Recurring join shapes across certified blocks (composting v2, W4.4). */
  joinCandidates: JoinPatternCandidate[];
  prBody: string;
}

export interface SemanticCompostingMetricCandidate {
  id: string;
  kind: 'metric';
  name: string;
  label: string;
  description: string;
  domain: string;
  table: string;
  type: MetricDefinition['type'];
  sql: string;
  filter?: string;
  status: 'draft';
  support: number;
  donorBlocks: Array<{
    name: string;
    path: string;
    domain?: string;
    outputs: string[];
    filters: string[];
  }>;
  draftPath: string;
  draftExists: boolean;
  yaml: string;
  provenance: {
    normalizedExpression: string;
    normalizedFilter?: string;
    recurringFilters: string[];
  };
  review: {
    priorityScore: number;
    rationale: string;
  };
}

export interface GenerateSemanticCompostingDraftsResult {
  ready: boolean;
  reason?: string;
  draftsWritten: number;
  draftsSkipped: number;
  candidates: SemanticCompostingMetricCandidate[];
  paths: string[];
  prBody: string;
  prBodyPath?: string;
}

interface CompostMetricAccumulator {
  domain: string;
  table: string;
  type: MetricDefinition['type'];
  expression: string;
  normalizedExpression: string;
  filter?: string;
  normalizedFilter?: string;
  aliases: string[];
  donors: Map<string, SemanticCompostingMetricCandidate['donorBlocks'][number]>;
}

interface ExtractedAggregateMetric {
  expression: string;
  alias?: string;
  type: MetricDefinition['type'];
}

/**
 * Mine certified block clusters for recurring metric definitions and render a
 * reviewable semantic-layer changeset. This is read-only: callers must confirm
 * candidate ids through generateSemanticCompostingDrafts before files are written.
 */
export function buildSemanticCompostingChangeset(
  projectRoot: string,
  options: { minSupport?: number; limit?: number; owner?: string } = {},
): SemanticCompostingChangesetResult {
  let manifest: DQLManifest;
  try {
    manifest = buildManifest({ projectRoot });
  } catch (error) {
    return {
      ready: false,
      reason: error instanceof Error ? error.message : String(error),
      summary: {
        certifiedBlocksScanned: 0,
        eligibleMetricClusters: 0,
        candidatesRanked: 0,
        existingDrafts: 0,
        donorBlocksUsed: 0,
        minSupport: Math.max(2, Math.floor(options.minSupport ?? 2)),
      },
      candidates: [],
      joinCandidates: [],
      prBody: '',
    };
  }

  const minSupport = Math.max(2, Math.floor(options.minSupport ?? 2));
  const limit = Number.isFinite(options.limit) && Number(options.limit) > 0 ? Math.floor(Number(options.limit)) : 10;
  const owner = options.owner?.trim() || resolveLocalOwner(projectRoot, { persist: false });
  const existingMetricNames = new Set(
    Object.entries(manifest.metrics ?? {})
      .filter(([, metric]) => !isSemanticDraftMetricPath(metric.filePath))
      .map(([name]) => name.toLowerCase()),
  );
  const certifiedBlocks = Object.values(manifest.blocks ?? {})
    .filter((block) => String(block.status ?? '').toLowerCase() === 'certified');
  const groups = new Map<string, CompostMetricAccumulator>();

  for (const block of certifiedBlocks) {
    const table = singleTableDependency(block);
    if (!table) continue;
    const where = extractCompostingWhereClause(block.sql);
    const normalizedFilter = where ? normalizeCompostingSql(where) : undefined;
    const metrics = extractCompostingAggregateMetrics(block.sql);
    if (metrics.length === 0) continue;
    const donor = {
      name: block.name,
      path: block.filePath,
      domain: block.domain,
      outputs: blockOutputNames(block),
      filters: where ? splitCompostingFilters(where) : [],
    };

    for (const metric of metrics) {
      const normalizedExpression = normalizeCompostingSql(metric.expression);
      const domain = block.domain?.trim() || 'misc';
      const key = [
        domain.toLowerCase(),
        table.toLowerCase(),
        metric.type,
        normalizedExpression,
        normalizedFilter ?? '',
      ].join('\0');
      const existing = groups.get(key);
      if (existing) {
        existing.aliases.push(metric.alias ?? '');
        existing.donors.set(block.filePath, donor);
      } else {
        groups.set(key, {
          domain,
          table,
          type: metric.type,
          expression: metric.expression,
          normalizedExpression,
          filter: where,
          normalizedFilter,
          aliases: [metric.alias ?? ''],
          donors: new Map([[block.filePath, donor]]),
        });
      }
    }
  }

  const usedNames = new Set(existingMetricNames);
  const candidates = Array.from(groups.values())
    .filter((group) => group.donors.size >= minSupport)
    .sort((a, b) => b.donors.size - a.donors.size || a.normalizedExpression.localeCompare(b.normalizedExpression))
    .map((group) => buildCompostingMetricCandidate(projectRoot, group, owner, usedNames))
    .filter((candidate): candidate is SemanticCompostingMetricCandidate => Boolean(candidate))
    .slice(0, limit);
  const donorBlocksUsed = new Set(candidates.flatMap((candidate) => candidate.donorBlocks.map((donor) => donor.path))).size;
  // Composting v2 (W4.4) — recurring join shapes across certified blocks.
  const joinCandidates = mineJoinPatterns(
    certifiedBlocks.map((block) => ({ name: block.name, sql: block.sql })),
    minSupport,
  ).slice(0, limit);

  return {
    ready: true,
    summary: {
      certifiedBlocksScanned: certifiedBlocks.length,
      eligibleMetricClusters: Array.from(groups.values()).filter((group) => group.donors.size >= minSupport).length,
      candidatesRanked: candidates.length,
      existingDrafts: candidates.filter((candidate) => candidate.draftExists).length,
      donorBlocksUsed,
      minSupport,
    },
    candidates,
    joinCandidates,
    prBody: renderCompostingPrBody(candidates),
  };
}

export function generateSemanticCompostingDrafts(
  projectRoot: string,
  candidateIds?: string[],
  options: { minSupport?: number; limit?: number; owner?: string } = {},
): GenerateSemanticCompostingDraftsResult {
  const changeset = buildSemanticCompostingChangeset(projectRoot, options);
  if (!changeset.ready) {
    return {
      ready: false,
      reason: changeset.reason,
      draftsWritten: 0,
      draftsSkipped: 0,
      candidates: [],
      paths: [],
      prBody: '',
    };
  }

  const wanted = candidateIds && candidateIds.length > 0 ? new Set(candidateIds) : undefined;
  const selected = wanted ? changeset.candidates.filter((candidate) => wanted.has(candidate.id)) : changeset.candidates;
  const paths: string[] = [];
  let draftsWritten = 0;
  let draftsSkipped = 0;
  for (const candidate of selected) {
    const absolutePath = join(projectRoot, candidate.draftPath);
    if (existsSync(absolutePath)) {
      draftsSkipped += 1;
    } else {
      mkdirSync(dirname(absolutePath), { recursive: true });
      writeFileSync(absolutePath, candidate.yaml, 'utf-8');
      draftsWritten += 1;
    }
    paths.push(candidate.draftPath);
  }

  let prBodyPath: string | undefined;
  const prBody = renderCompostingPrBody(selected);
  if (selected.length > 0) {
    prBodyPath = 'semantic-layer/metrics/_drafts/PR_BODY.md';
    const absolutePrBodyPath = join(projectRoot, prBodyPath);
    mkdirSync(dirname(absolutePrBodyPath), { recursive: true });
    writeFileSync(absolutePrBodyPath, prBody, 'utf-8');
  }

  return {
    ready: true,
    draftsWritten,
    draftsSkipped,
    candidates: selected,
    paths,
    prBody,
    prBodyPath,
  };
}

function buildCompostingMetricCandidate(
  projectRoot: string,
  group: CompostMetricAccumulator,
  owner: string,
  usedNames: Set<string>,
): SemanticCompostingMetricCandidate | undefined {
  const baseName = preferredCompostingMetricName(group);
  const name = dedupeCompostingName(baseName, usedNames);
  if (!name) return undefined;
  usedNames.add(name.toLowerCase());
  const label = titleFromSlug(name);
  const donors = Array.from(group.donors.values()).sort((a, b) => a.path.localeCompare(b.path));
  const support = donors.length;
  const domainSlug = slugForPath(group.domain);
  const draftPath = `semantic-layer/metrics/_drafts/${domainSlug}/${name}.yaml`;
  const recurringFilters = group.filter ? splitCompostingFilters(group.filter) : [];
  const metric: MetricDefinition = {
    name,
    label,
    description: `Draft metric composted from ${support} certified DQL blocks. Review the expression, filter, grain, and owner before certification.`,
    domain: group.domain,
    status: 'draft',
    sql: group.expression,
    type: group.type,
    table: group.table,
    filter: group.filter,
    tags: ['composted', 'human-review'],
    owner,
    source: {
      provider: 'dql',
      objectType: 'composted_metric',
      objectId: `composted:${name}`,
      objectName: label,
      importedAt: new Date().toISOString(),
      extra: {
        support,
        donorBlocks: donors.map((donor) => donor.name),
        donorPaths: donors.map((donor) => donor.path),
        normalizedExpression: group.normalizedExpression,
        normalizedFilter: group.normalizedFilter,
      },
    },
  };
  return {
    id: `metric:${name}:${stableShortHash(`${group.domain}|${group.table}|${group.normalizedExpression}|${group.normalizedFilter ?? ''}`)}`,
    kind: 'metric',
    name,
    label,
    description: metric.description,
    domain: group.domain,
    table: group.table,
    type: group.type,
    sql: group.expression,
    filter: group.filter,
    status: 'draft',
    support,
    donorBlocks: donors,
    draftPath,
    draftExists: existsSync(join(projectRoot, draftPath)),
    yaml: serializeMetricDefinitionToYaml(metric),
    provenance: {
      normalizedExpression: group.normalizedExpression,
      normalizedFilter: group.normalizedFilter,
      recurringFilters,
    },
    review: {
      priorityScore: support * 10 + recurringFilters.length * 2,
      rationale: `Recurring ${group.type} metric found in ${support} certified blocks${group.filter ? ' with the same filter' : ''}.`,
    },
  };
}

function singleTableDependency(block: ManifestBlock): string | undefined {
  const dependencies = Array.from(new Set((block.tableDependencies ?? []).filter((table) => table && !table.startsWith('ref:'))));
  if (dependencies.length === 1) return dependencies[0];
  const rawRefs = Array.from(new Set((block.rawTableRefs ?? []).filter(Boolean)));
  return rawRefs.length === 1 ? rawRefs[0] : undefined;
}

function blockOutputNames(block: ManifestBlock): string[] {
  if (Array.isArray(block.declaredOutputs) && block.declaredOutputs.length > 0) return block.declaredOutputs;
  if (Array.isArray(block.outputContract) && block.outputContract.length > 0) return block.outputContract.map((output) => output.name);
  if (Array.isArray(block.outputs) && block.outputs.length > 0) return block.outputs.map((output) => output.name);
  return [];
}

function isSemanticDraftMetricPath(filePath: string | undefined): boolean {
  return Boolean(filePath?.replaceAll('\\', '/').includes('semantic-layer/metrics/_drafts/'));
}

function extractCompostingAggregateMetrics(sql: string): ExtractedAggregateMetric[] {
  const select = extractCompostingSelectClause(sql);
  if (!select) return [];
  return splitCompostingTopLevel(select, ',').flatMap((item): ExtractedAggregateMetric[] => {
    const parsed = parseCompostingSelectItem(item);
    if (!parsed) return [];
    return [parsed];
  });
}

function extractCompostingSelectClause(sql: string): string | undefined {
  const source = stripSqlTerminator(sql);
  const selectMatch = /\bselect\b/i.exec(source);
  if (!selectMatch) return undefined;
  const fromIndex = findTopLevelKeyword(source, 'from', selectMatch.index + selectMatch[0].length);
  if (fromIndex < 0) return undefined;
  return source.slice(selectMatch.index + selectMatch[0].length, fromIndex).trim();
}

function parseCompostingSelectItem(item: string): ExtractedAggregateMetric | undefined {
  const { expression, alias } = splitCompostingAlias(item.trim());
  const normalizedExpression = expression.trim();
  const distinctCount = normalizedExpression.match(/^count\s*\(\s*distinct\s+[\s\S]+\)$/i);
  if (distinctCount) {
    return { expression: normalizedExpression, alias, type: 'count_distinct' };
  }
  const count = normalizedExpression.match(/^count\s*\([\s\S]*\)$/i);
  if (count) return { expression: normalizedExpression, alias, type: 'count' };
  const aggregate = normalizedExpression.match(/^(sum|avg|min|max)\s*\([\s\S]+\)$/i);
  if (!aggregate) return undefined;
  return {
    expression: normalizedExpression,
    alias,
    type: aggregate[1].toLowerCase() as MetricDefinition['type'],
  };
}

function splitCompostingAlias(item: string): { expression: string; alias?: string } {
  const asMatch = item.match(/^([\s\S]+?)\s+as\s+("[^"]+"|`[^`]+`|\[[^\]]+\]|[A-Za-z_][A-Za-z0-9_$]*)$/i);
  if (asMatch) return { expression: asMatch[1].trim(), alias: stripIdentifierQuotes(asMatch[2]) };
  return { expression: item.trim() };
}

function extractCompostingWhereClause(sql: string): string | undefined {
  const source = stripSqlTerminator(sql);
  const whereIndex = findTopLevelKeyword(source, 'where', 0);
  if (whereIndex < 0) return undefined;
  const start = whereIndex + 'where'.length;
  const endCandidates = ['group by', 'having', 'order by', 'limit', 'qualify']
    .map((keyword) => findTopLevelKeyword(source, keyword, start))
    .filter((index) => index >= 0);
  const end = endCandidates.length > 0 ? Math.min(...endCandidates) : source.length;
  const where = source.slice(start, end).trim();
  return where || undefined;
}

function splitCompostingFilters(where: string): string[] {
  return splitCompostingTopLevel(where, 'and')
    .map((part) => part.trim())
    .filter(Boolean);
}

function splitCompostingTopLevel(input: string, delimiter: ',' | 'and'): string[] {
  const out: string[] = [];
  let start = 0;
  let depth = 0;
  let quote: '"' | "'" | '`' | undefined;
  for (let i = 0; i < input.length; i += 1) {
    const char = input[i];
    if (quote) {
      if (char === quote && input[i - 1] !== '\\') quote = undefined;
      continue;
    }
    if (char === '"' || char === "'" || char === '`') {
      quote = char;
      continue;
    }
    if (char === '(') depth += 1;
    else if (char === ')') depth = Math.max(0, depth - 1);
    if (depth !== 0) continue;
    if (delimiter === ',' && char === ',') {
      out.push(input.slice(start, i).trim());
      start = i + 1;
    } else if (
      delimiter === 'and'
      && input.slice(i, i + 3).toLowerCase() === 'and'
      && !/[A-Za-z0-9_]/.test(input[i - 1] ?? '')
      && !/[A-Za-z0-9_]/.test(input[i + 3] ?? '')
    ) {
      out.push(input.slice(start, i).trim());
      start = i + 3;
      i += 2;
    }
  }
  out.push(input.slice(start).trim());
  return out.filter(Boolean);
}

function findTopLevelKeyword(input: string, keyword: string, fromIndex: number): number {
  const lower = input.toLowerCase();
  const target = keyword.toLowerCase();
  let depth = 0;
  let quote: '"' | "'" | '`' | undefined;
  for (let i = Math.max(0, fromIndex); i <= input.length - target.length; i += 1) {
    const char = input[i];
    if (quote) {
      if (char === quote && input[i - 1] !== '\\') quote = undefined;
      continue;
    }
    if (char === '"' || char === "'" || char === '`') {
      quote = char;
      continue;
    }
    if (char === '(') {
      depth += 1;
      continue;
    }
    if (char === ')') {
      depth = Math.max(0, depth - 1);
      continue;
    }
    if (depth !== 0) continue;
    if (
      lower.slice(i, i + target.length) === target
      && !/[A-Za-z0-9_]/.test(input[i - 1] ?? '')
      && !/[A-Za-z0-9_]/.test(input[i + target.length] ?? '')
    ) {
      return i;
    }
  }
  return -1;
}

function preferredCompostingMetricName(group: CompostMetricAccumulator): string {
  const aliases = group.aliases.map((alias) => slugForIdentifier(alias)).filter(Boolean);
  const counts = new Map<string, number>();
  for (const alias of aliases) counts.set(alias, (counts.get(alias) ?? 0) + 1);
  const preferredAlias = Array.from(counts.entries()).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0];
  if (preferredAlias) return preferredAlias;
  const expressionName = slugForIdentifier(group.expression.replace(/\b(sum|avg|min|max|count|distinct)\b/gi, ''));
  return expressionName ? `${expressionName}_${group.type}` : `${group.type}_metric`;
}

function dedupeCompostingName(baseName: string, usedNames: Set<string>): string | undefined {
  const base = slugForIdentifier(baseName).slice(0, 72).replace(/_+$/g, '');
  if (!base) return undefined;
  if (!usedNames.has(base.toLowerCase())) return base;
  let index = 2;
  while (usedNames.has(`${base}_${index}`.toLowerCase())) index += 1;
  return `${base}_${index}`;
}

function normalizeCompostingSql(value: string): string {
  return value
    .replace(/["`]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function slugForIdentifier(value: string): string {
  return value
    .trim()
    .replace(/["`[\]]/g, '')
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function slugForPath(value: string): string {
  return slugForIdentifier(value) || 'misc';
}

function stripIdentifierQuotes(value: string): string {
  return value.replace(/^["`\[]|["`\]]$/g, '').trim();
}

function titleFromSlug(value: string): string {
  return value.split('_').filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
}

function stableShortHash(value: string): string {
  return createHash('sha1').update(value).digest('hex').slice(0, 10);
}

function createDqlArtifactExecutionReceipt(
  source: string,
  compiledSql: string,
  parameters: Record<string, unknown>,
  result: { columns: unknown[]; rows: unknown[]; rowCount: number },
): DqlArtifactExecutionReceipt {
  return {
    sourceFingerprint: executionFingerprint(source),
    compiledSqlFingerprint: executionFingerprint(compiledSql),
    parameterFingerprint: executionFingerprint(stableExecutionValue(parameters)),
    resultFingerprint: executionFingerprint(stableExecutionValue({
      columns: result.columns,
      rows: result.rows,
      rowCount: result.rowCount,
    })),
  };
}

function agentRunTelemetryForAnswer(
  answer: AgentAnswer,
  egressReceipts: ProviderEgressReceiptV1[],
  totalDurationMs: number,
  narrationDurationMs: number,
  engineRepairAttempts: number,
): AgentRunTelemetryV1 {
  const timings = new Map((answer.evidence?.timings ?? []).map((timing) => [timing.phase, timing.durationMs]));
  const toolCalls = answer.evidence?.toolCalls ?? [];
  const toolDurationMs = toolCalls.reduce((sum, call) => sum + Math.max(0, call.durationMs ?? 0), 0);
  const warehouseDurationMs = answer.evidence?.execution?.executionTime ?? answer.result?.executionTime;
  const counters = answer.evidence?.runtimeCounters;
  const stageDurationsMs: AgentRunTelemetryV1['stageDurationsMs'] = {
    ...(timings.has('project_state') ? { snapshot: timings.get('project_state')! } : {}),
    ...(timings.has('context_retrieval') ? { retrieval: timings.get('context_retrieval')! } : {}),
    ...(timings.has('runtime_schema') ? { schema: timings.get('runtime_schema')! } : {}),
    ...(timings.has('source_search') ? { meaning: timings.get('source_search')! } : {}),
    ...(timings.has('answer_resolution') ? { provider: timings.get('answer_resolution')! } : {}),
    ...(toolCalls.length > 0 ? { tools: toolDurationMs } : {}),
    ...(typeof warehouseDurationMs === 'number' ? { execution: Math.max(0, warehouseDurationMs) } : {}),
    ...(narrationDurationMs > 0 ? { narration: narrationDurationMs } : {}),
    total: Math.max(0, totalDurationMs),
  };
  return {
    version: 1,
    stageDurationsMs,
    providerRoundTrips: counters?.providerRoundTrips ?? 0,
    toolCalls: counters?.toolCalls ?? toolCalls.length,
    sqlExecutions: counters?.sqlExecutions ?? 0,
    repairs: Math.max(engineRepairAttempts, counters?.repairs ?? 0),
    egressReceipts: egressReceipts.length,
    ...(typeof warehouseDurationMs === 'number' ? { warehouseDurationMs: Math.max(0, warehouseDurationMs) } : {}),
    ...(terminalFallbackReasonForAnswer(answer)
      ? { fallbackReason: terminalFallbackReasonForAnswer(answer) }
      : {}),
  };
}

function executionFingerprint(value: string): string {
  return createHash('sha256').update(value).digest('hex');
}

/**
 * Opaque browser-cache identity for local Ask conversations.  A browser origin
 * is not a project boundary: a user can stop one `dql notebook` process and
 * start a different project on the same port.  The client therefore receives
 * only this one-way, server-owned value and never a local path. It is not a
 * secret: it is intentionally linkable only within the local browser/runtime
 * across restarts so stale cache can be rejected; never log or export it.
 */
export function askConversationProjectIdentity(projectRoot: string): string {
  let canonicalRoot: string;
  try {
    canonicalRoot = realpathSync(projectRoot);
  } catch {
    canonicalRoot = resolve(projectRoot);
  }
  return `sha256:${executionFingerprint(`dql.ask.conversation-cache.v1\0${canonicalRoot}`)}`;
}

function buildSemanticAggregationCompilerReceipt(input: {
  semanticLayer: SemanticLayer;
  metricNames: string[];
  compiledSql: string;
  plan?: NonNullable<IntentDecision['resolvedAnalyticalPlan']>;
  targetFingerprint?: string;
}): SemanticAggregationCompilerReceiptV1 | undefined {
  const plan = input.plan;
  const metricId = plan?.analyticalFrame?.metricConceptIds[0];
  if (input.metricNames.length !== 1 || !plan || !metricId || !plan.executionId
    || !plan.selectedCapabilityFingerprint || !input.targetFingerprint) return undefined;
  const metric = input.semanticLayer.getMetric(input.metricNames[0]);
  if (!metric || (metric.aggregation ?? metric.metricType)?.toLowerCase() !== 'ratio') return undefined;
  const refName = (value: unknown): string | undefined => {
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    const name = (value as Record<string, unknown>).name;
    return typeof name === 'string' && name.trim() ? name.trim() : undefined;
  };
  const numeratorName = refName(metric.typeParams?.numerator);
  const denominatorName = refName(metric.typeParams?.denominator);
  if (!numeratorName || !denominatorName || !metric.sql.trim()) return undefined;
  const measures = [numeratorName, denominatorName].map((name) => {
    const matches = input.semanticLayer.listMeasures().filter((measure) => measure.name === name
      && (!metric.cube || !measure.cube || measure.cube === metric.cube));
    return matches.length === 1 ? matches[0] : undefined;
  });
  if (measures.some((measure) => !measure)) return undefined;
  const relations = Array.from(new Set(measures.map((measure) => measure!.table.trim()).filter(Boolean)));
  if (relations.length !== 1) return undefined;
  const outputAlias = metricId.split(/[:.]/).at(-1);
  if (!outputAlias) return undefined;
  const orderedMeasureIds = measures.map((measure) =>
    `semantic:${measure!.domain || 'uncategorized'}:measure:${measure!.cube ? `${measure!.cube}.` : ''}${measure!.name}`);
  const compiledSqlFingerprint = semanticExecutionFingerprint(input.compiledSql);
  const compiledOutputExpression = buildSqlOutputExpressionSignature(input.compiledSql, outputAlias);
  if (!compiledOutputExpression) return undefined;
  const compiledExpressionFingerprint = semanticExecutionFingerprint(compiledOutputExpression.canonicalExpression);
  const compiledSignature = buildGeneratedAnalyticalSqlSignature(input.compiledSql);
  if (!compiledSignature) return undefined;
  const body = {
    version: 1 as const,
    executionId: plan.executionId,
    capabilityFingerprint: plan.selectedCapabilityFingerprint,
    metricId,
    metricExpressionSql: metric.sql,
    operator: 'ratio' as const,
    orderedMeasureIds,
    physicalRelation: relations[0],
    relationAliases: Array.from(new Set([metric.cube, ...measures.map((measure) => measure!.cube)].filter((value): value is string => Boolean(value)))),
    outputAlias,
    dimensionIds: [...new Set(plan.analyticalFrame?.dimensions.map((dimension) => dimension.dimensionId) ?? [])].sort(),
    relationshipPathIds: [...plan.relationshipPathIds].sort(),
    relationshipProofFingerprints: [...new Set(
      plan.relationshipProofs?.map((proof) => proof.authorityFingerprint) ?? [],
    )].sort(),
    orderBy: compiledSignature.orderBy,
    compiledSqlFingerprint,
    compiledExpressionFingerprint,
    planFingerprint: plan.fingerprint,
    snapshotId: plan.snapshotId,
    targetFingerprint: input.targetFingerprint,
  };
  return { ...body, receiptFingerprint: semanticExecutionFingerprint(body) };
}

/**
 * Older clients normalized executable DQL with trim(), while the receipt was
 * correctly created from the original renderer output ending in one newline.
 * Accept only that exact legacy line-ending variant; any substantive source
 * change still fails closed.
 */
function executionSourceFingerprintMatches(expected: string, source: string): boolean {
  return [
    source,
    `${source}\n`,
    `${source}\r\n`,
  ].some((candidate) => executionFingerprint(candidate) === expected);
}

function stableExecutionValue(value: unknown): string {
  const seen = new WeakSet<object>();
  return JSON.stringify(value, (_key, item: unknown) => {
    if (!item || typeof item !== 'object') {
      if (typeof item === 'bigint') return item.toString();
      return item;
    }
    if (seen.has(item)) return '[Circular]';
    seen.add(item);
    if (Array.isArray(item)) return item;
    return Object.fromEntries(Object.entries(item as Record<string, unknown>).sort(([left], [right]) => left.localeCompare(right)));
  });
}

/**
 * Opaque continuity proof for a server-issued Ask clarification. Snapshot
 * handles can be recreated when a local runtime restarts, but an old semantic
 * dimension button must be usable only if the currently retrieved semantic
 * metric capability is exactly equivalent. The retrieval set deliberately is
 * not part of this proof: a focused continuation changes lexical/vector ranks
 * and can legitimately omit unrelated physical/context cards. The runtime
 * still rechecks the selected option against the CURRENT metric capability,
 * eligibility, compatibility, and role support before it binds a program.
 *
 * Keep business definitions, member values, retrieval ranks, prompts, and
 * rows out of the proof: this value is persisted with a conversation and may
 * appear in a redacted receipt.
 */
function askEvidenceContinuityFingerprint(evidence: Pick<AgentRetrievalEvidence, 'candidates'>): string {
  const semanticCapabilities = evidence.candidates
    .filter((candidate) => candidate.kind === 'semantic_metric' && candidate.analyticalCapability)
    .map((candidate) => ({
    id: candidate.id,
    qualifiedId: candidate.qualifiedId,
    aliases: [...(candidate.aliases ?? [])].sort(),
    semanticModel: candidate.semanticModel,
    analyticalCapability: candidate.analyticalCapability,
  })).sort((left, right) => `${left.qualifiedId ?? left.id}\u0000${left.id}`.localeCompare(`${right.qualifiedId ?? right.id}\u0000${right.id}`));
  return `sha256:${createHash('sha256').update(stableExecutionValue({ semanticCapabilities })).digest('hex')}`;
}

function renderCompostingPrBody(candidates: SemanticCompostingMetricCandidate[]): string {
  const lines = [
    '# Semantic Composting Changeset',
    '',
    'This changeset proposes draft semantic metrics mined from recurring logic in certified DQL blocks.',
    'Review each metric expression, filter, owner, grain compatibility, and downstream impact before marking it certified.',
    '',
  ];
  if (candidates.length === 0) {
    lines.push('No recurring certified-block metric clusters met the current support threshold.');
    return `${lines.join('\n')}\n`;
  }
  for (const candidate of candidates) {
    lines.push(`## ${candidate.label}`);
    lines.push('');
    lines.push(`- Draft path: \`${candidate.draftPath}\``);
    lines.push(`- Domain/table: \`${candidate.domain}\` / \`${candidate.table}\``);
    lines.push(`- Expression: \`${candidate.sql}\``);
    if (candidate.filter) lines.push(`- Filter: \`${candidate.filter}\``);
    lines.push(`- Support: ${candidate.support} certified block(s)`);
    lines.push(`- Donors: ${candidate.donorBlocks.map((donor) => `\`${donor.path}\``).join(', ')}`);
    lines.push('');
  }
  return `${lines.join('\n')}\n`;
}

/**
 * Materialize drafts for an APPROVED scope (selected slugs / domains). Reuses
 * the propose engine's `onlySlugs` path + the draft writer. Plumbing is never
 * generated even if an approved slug names a plumbing model. Returns the written
 * summary so the caller can route into the per-block review flow.
 */
export interface ProposeGenerateResult {
  ready: boolean;
  reason?: string;
  draftsWritten: number;
  draftsSkipped: number;
  proposals: ProposalResult[];
}

export async function generateProposeDrafts(
  projectRoot: string,
  slugs: string[],
  projectConfig: ProjectConfig = loadProjectConfig(projectRoot),
  options: { owner?: string } = {},
): Promise<ProposeGenerateResult> {
  const manifestPath = resolveDbtManifestPath(projectRoot, projectConfig);
  if (!manifestPath) {
    return {
      ready: false,
      reason: 'No dbt manifest found. Run `dbt parse` (or `dbt compile`) first.',
      draftsWritten: 0,
      draftsSkipped: 0,
      proposals: [],
    };
  }

  // Structure deterministic, content AI-optional: optionally pre-compute AI
  // enrichment (description / llmContext / examples) for the approved slugs, then
  // hand it to the deterministic engine as data. Best-effort — any failure or a
  // missing provider falls back to dbt-derived content.
  let enrichedBySlug: Map<string, EnrichedContent> | undefined;
  const proposeConfig = resolveProposeConfig(projectConfig.propose);
  if (proposeConfig.aiEnrichment !== 'off' && slugs.length > 0) {
    enrichedBySlug = await gatherProposeEnrichment(projectRoot, manifestPath, projectConfig.propose, slugs).catch(() => undefined);
  }

  const summary = propose({
    projectRoot,
    dbtManifestPath: manifestPath,
    // Stamp the resolved local OSS owner when none was passed so drafts are not
    // born with a "Missing owner" Certifier strike.
    owner: options.owner || resolveLocalOwner(projectRoot),
    config: projectConfig.propose,
    onlySlugs: slugs,
    enrichedBySlug,
  });
  return {
    ready: true,
    draftsWritten: summary.draftsWritten,
    draftsSkipped: summary.draftsSkipped,
    proposals: summary.proposals,
  };
}

/**
 * Build the FILLED transparent preview for ONE proposed candidate slug (spec 14,
 * part A). Reuses the deterministic `buildProposePreview` engine (real SQL +
 * Certifier verdict) and best-effort AI enrichment (description/llmContext/
 * examples) when a provider is available. Writes NOTHING. Returns `undefined`
 * when the slug is not part of the bounded, business-only selection.
 */
export async function buildProposeCandidatePreview(
  projectRoot: string,
  slug: string,
  owner?: string,
  projectConfig: ProjectConfig = loadProjectConfig(projectRoot),
): Promise<ProposePlanCandidate | undefined> {
  const manifestPath = resolveDbtManifestPath(projectRoot, projectConfig);
  if (!manifestPath) return undefined;

  // Best-effort AI enrichment for this one slug (content only). Any miss falls
  // back to the deterministic dbt-derived content inside buildProposePreview.
  let enriched: EnrichedContent | undefined;
  const proposeConfig = resolveProposeConfig(projectConfig.propose);
  if (proposeConfig.aiEnrichment !== 'off') {
    const map = await gatherProposeEnrichment(projectRoot, manifestPath, projectConfig.propose, [slug]).catch(() => undefined);
    enriched = map?.get(slug);
  }

  return buildProposePreview(projectRoot, manifestPath, slug, {
    config: projectConfig.propose,
    owner: owner || resolveLocalOwner(projectRoot),
    enriched,
  });
}

function getProjectConnectionsForApi(config: ProjectConfig | Record<string, unknown>): Record<string, unknown> {
  const connections = getStoredConnections(config as Record<string, unknown>);
  if (Object.keys(connections).length === 0 && isConnectionLike((config as ProjectConfig).defaultConnection)) {
    return { default: (config as ProjectConfig).defaultConnection };
  }
  return connections;
}

function metadataScopeDbtDefaults(
  projectRoot: string,
  config: ProjectConfig,
): { relations: string[]; dbtFingerprint?: string } {
  const manifestPath = resolveDbtManifestPath(projectRoot, config);
  if (!manifestPath || !existsSync(manifestPath)) return { relations: [] };
  try {
    const source = readFileSync(manifestPath, 'utf-8');
    const lookup = buildDbtRelationLookup(JSON.parse(source));
    return {
      relations: Array.from(new Set([...lookup.models.values(), ...lookup.sources.values()])).sort(),
      dbtFingerprint: createHash('sha256').update(source).digest('hex'),
    };
  } catch {
    return { relations: [] };
  }
}

/** What the Settings page and `dql sync warehouse` show about the warehouse catalog snapshot. */
export interface WarehouseCatalogSummary {
  path: string;
  relations?: number;
  fingerprint?: string;
  capturedAt?: string;
  connectionId?: string;
  warnings?: string[];
  /** Why this sync did not refresh the snapshot. */
  skipped?: string;
  error?: string;
  /** What changed since the previous sync, and the modeled objects it touches. Absent when nothing changed. */
  drift?: WarehouseCatalogDrift & { affected: string[] };
}

/** The entities and relationships bound to relations that changed. */
function driftAffected(manifest: DQLManifest | undefined, drift: WarehouseCatalogDrift): string[] {
  const changed = new Set(drift.changedRelationIds);
  const entities = Object.values(manifest?.modeling?.entities ?? {}).filter((entity) => changed.has(entity.dbtUniqueId));
  const entityIds = new Set(entities.map((entity) => entity.qualifiedId ?? entity.id));
  const relationships = Object.values(manifest?.modeling?.relationships ?? {}).filter((relationship) => entityIds.has(relationship.from) || entityIds.has(relationship.to));
  return [...entityIds, ...relationships.map((relationship) => relationship.qualifiedId ?? relationship.id)].sort();
}

function warehouseCatalogModeling(config: ProjectConfig): boolean {
  const mode = modelingModeOf(config);
  return mode === 'warehouse-first' || mode === 'hybrid';
}

/** The project's modeling connection: the one whose catalog entities bind to. */
function warehouseCatalogConnectionId(config: ProjectConfig): string {
  const connections = getProjectConnectionsForApi(config);
  return resolveDefaultConnectionKey(config as unknown as Record<string, unknown>, connections) ?? Object.keys(connections)[0] ?? 'default';
}

/**
 * RFC 0007: in warehouse-first and hybrid modeling a schema sync also
 * refreshes the warehouse catalog snapshot the manifest builder reads. A
 * dbt-first project, or a sync of another connection, is left untouched.
 */
async function refreshWarehouseCatalogAfterSync(
  projectRoot: string,
  config: ProjectConfig,
  executor: QueryExecutor,
  connection: ConnectionConfig,
  connectionId: string,
  scope: ConnectionMetadataScopeV1,
  /** The model before this sync, to name what drift touches. */
  manifest?: DQLManifest,
): Promise<WarehouseCatalogSummary | undefined> {
  if (!warehouseCatalogModeling(config)) return undefined;
  const path = readWarehouseCatalog(projectRoot).path;
  const modelingConnectionId = warehouseCatalogConnectionId(config);
  if (connectionId !== modelingConnectionId) {
    return { path, skipped: `modeling reads connection "${modelingConnectionId}"; this sync did not change its catalog` };
  }
  try {
    const previous = readWarehouseCatalog(projectRoot).snapshot;
    const { snapshot, warnings } = await syncWarehouseCatalog({ projectRoot, executor, connection, scope });
    const drift = previous && previous.fingerprint !== snapshot.fingerprint ? diffWarehouseCatalogs(previous, snapshot) : undefined;
    const changed = drift && (drift.addedRelations.length || drift.removedRelations.length || drift.addedColumns.length || drift.removedColumns.length || drift.changedColumnTypes.length);
    return {
      path,
      relations: snapshot.relations.length,
      fingerprint: snapshot.fingerprint,
      capturedAt: snapshot.capturedAt,
      connectionId,
      warnings,
      ...(drift && changed ? { drift: { ...drift, affected: driftAffected(manifest, drift) } } : {}),
    };
  } catch (error) {
    return { path, error: error instanceof Error ? error.message : String(error) };
  }
}

/**
 * `dql sync warehouse`: the same work as Settings → Sync schema, without a
 * running server. With `schemas`, the schema selection is saved first.
 */
export async function syncProjectWarehouse(projectRoot: string, options: {
  connectionId?: string;
  database?: string;
  schemas?: string[];
  executor: QueryExecutor;
}): Promise<{ connectionId: string; scope: ConnectionMetadataScopeV1; metadataRelations: number; warehouseCatalog?: WarehouseCatalogSummary }> {
  const cfg = loadProjectConfig(projectRoot);
  const connectionId = options.connectionId || warehouseCatalogConnectionId(cfg);
  const selectedConnection = projectConnectionById(projectRoot, cfg, connectionId);
  if (!selectedConnection) throw new Error(`Unknown connection "${connectionId}". Add it in Settings → Connections or dql.config.json.`);
  const configured = configuredMetadataScopeInput(cfg, connectionId);
  let input: ConnectionMetadataScopeInput | undefined = configured;
  if (options.schemas?.length) {
    const database = options.database
      ?? selectedConnection.catalog
      ?? selectedConnection.database
      ?? await databaseHoldingSchemas(options.executor, selectedConnection, connectionId, options.schemas);
    input = { mode: 'selected_scopes', scopes: [{ catalogOrDatabase: database, schemas: options.schemas }] };
  }
  const scope = normalizeConnectionMetadataScope(connectionId, selectedConnection, input, metadataScopeDbtDefaults(projectRoot, cfg));
  const modelBeforeSync = warehouseCatalogModeling(cfg)
    ? (() => { try { return buildManifest({ projectRoot, dbtManifestPath: resolveDbtManifestPath(projectRoot, cfg) ?? undefined }); } catch { return undefined; } })()
    : undefined;
  const synced = await syncWarehouseMetadata({ projectRoot, executor: options.executor, connection: selectedConnection, scope });
  if (options.schemas?.length) persistConnectionMetadataScope(projectRoot, connectionId, scope);
  const warehouseCatalog = await refreshWarehouseCatalogAfterSync(projectRoot, loadProjectConfig(projectRoot), options.executor, selectedConnection, connectionId, synced.scope, modelBeforeSync);
  const metadataRelations = warehouseMetadataStatus(projectRoot, synced.scope.scopeFingerprint, connectionId).relationCount;
  return { connectionId, scope: synced.scope, metadataRelations, ...(warehouseCatalog ? { warehouseCatalog } : {}) };
}

/**
 * `dql model discover` and Modeling → Build the map for warehouse-first and
 * hybrid modeling: draft domains, entities and relationships from the
 * warehouse catalog snapshot, optionally checked on the warehouse.
 */
export async function discoverProjectWarehouseModel(projectRoot: string, options: {
  manifest?: DQLManifest;
  domain?: string;
  validate?: boolean;
  /** Opt-in: also learn joins from recent query history (text read in memory, only join pairs kept). */
  queryHistory?: boolean;
  executor?: QueryExecutor;
}): Promise<WarehouseDiscoveryReport> {
  const cfg = loadProjectConfig(projectRoot);
  const mode = modelingModeOf(cfg);
  if (mode !== 'warehouse-first' && mode !== 'hybrid') {
    throw Object.assign(new Error('Warehouse discovery needs "manifestVersion": 3 and "modeling": { "mode": "warehouse-first" } (or "hybrid") in dql.config.json.'), { code: 'WAREHOUSE_MODELING_NOT_ENABLED' });
  }
  const { snapshot, error } = readWarehouseCatalog(projectRoot);
  if (!snapshot) {
    throw Object.assign(new Error(error ? `The warehouse catalog could not be read: ${error}` : 'No warehouse catalog yet. Run `dql sync warehouse --schemas <schema>` or Sync schema in Settings first.'), { code: 'WAREHOUSE_CATALOG_MISSING' });
  }
  const manifest = options.manifest ?? buildManifest({ projectRoot, dbtManifestPath: resolveDbtManifestPath(projectRoot, cfg) ?? undefined });
  const connectionId = snapshot.connectionId || warehouseCatalogConnectionId(cfg);
  const connection = options.validate || options.queryHistory ? projectConnectionById(projectRoot, cfg, connectionId) : null;
  if ((options.validate || options.queryHistory) && (!options.executor || !connection)) {
    throw new Error(`Checking the warehouse needs the connection "${connectionId}" the catalog was read from.`);
  }
  let queryHistory: WarehouseDiscoveryReport['queryHistory'];
  let observedJoins: ReturnType<typeof observedJoinsFromQueries> | undefined;
  if (options.queryHistory && connection && options.executor) {
    const sql = queryHistorySql(connection.driver, { database: connection.database ?? connection.catalog, location: (connection as { location?: string }).location });
    if (!sql) {
      queryHistory = { error: `${connection.driver} keeps no query history DQL can read.` };
    } else {
      try {
        const result = await options.executor.executePositional(sql, [], connection, { maxRows: 20_000, maxBytes: 64 * 1024 * 1024, batchSize: 1_000, deadlineMs: 60_000 });
        const texts = result.rows.map((row) => String((row as Record<string, unknown>).query_text ?? (row as Record<string, unknown>).QUERY_TEXT ?? ''));
        observedJoins = observedJoinsFromQueries(texts);
        queryHistory = { statements: texts.length, joins: observedJoins.length };
      } catch (error) {
        queryHistory = { error: `Query history could not be read: ${error instanceof Error ? error.message.split('\n')[0] : String(error)}` };
      }
    }
  }
  const drafted = discoverWarehouseModel({
    snapshot,
    manifest,
    ...(options.domain ? { domain: options.domain } : {}),
    ...(cfg.project ? { projectName: cfg.project } : {}),
    existingDomains: loadDomainPackageRegistry(projectRoot).values().map((pkg) => pkg.id),
    ...(observedJoins ? { observedJoins } : {}),
  });
  const report = queryHistory ? { ...drafted, queryHistory } : drafted;
  if (!options.validate || !connection || !options.executor) return report;
  const executor = options.executor;
  return validateWarehouseDiscovery(
    report,
    snapshot,
    (sql) => executor.executeQuery(sql, [], {}, connection),
    (identifier) => getDialect(connection.driver).quoteIdentifier(identifier),
  );
}

/** Write a discovery report's drafts (optionally only the chosen ones) through the reviewed modeling path. */
export function applyProjectWarehouseDiscovery(projectRoot: string, report: WarehouseDiscoveryReport, selection: { entityIds?: string[]; relationshipIds?: string[] } = {}): { changes: number; paths: string[] } {
  const relationships = selection.relationshipIds
    ? report.relationships.filter((relationship) => selection.relationshipIds!.includes(relationship.id))
    : report.relationships;
  const wantedEntities = new Set(selection.entityIds ?? report.entities.map((entity) => `${entity.domain}::${entity.id}`));
  // A chosen relationship brings the two entities it joins.
  for (const relationship of relationships) {
    wantedEntities.add(`${relationship.fromDomain}::${relationship.from}`);
    wantedEntities.add(`${relationship.toDomain}::${relationship.to}`);
  }
  const entities = report.entities.filter((entity) => wantedEntities.has(`${entity.domain}::${entity.id}`) || (selection.entityIds ?? []).includes(entity.id));
  const domains = report.domains.filter((domain) => entities.some((entity) => entity.domain === domain.id));
  // Reading the owner must not write it: that would change the project's
  // sources under the batch being applied.
  const changes = warehouseDiscoveryChanges({ ...report, domains, entities, relationships }, { owner: resolveLocalOwner(projectRoot, { persist: false }) ?? undefined });
  if (changes.length === 0) return { changes: 0, paths: [] };
  const preview = previewModelingChanges(projectRoot, changes);
  const applied = applyModelingChanges(projectRoot, changes, preview.fingerprint);
  return { changes: changes.length, paths: [...new Set(applied.patches.map((patch) => patch.path))].sort() };
}

/** The one database/catalog that holds every named schema, found by asking the warehouse. */
async function databaseHoldingSchemas(executor: QueryExecutor, connection: ConnectionConfig, connectionId: string, schemas: string[]): Promise<string> {
  const discovery = await discoverWarehouseMetadataScopes({ connectionId, executor, connection });
  const wanted = schemas.map((schema) => schema.toLowerCase());
  const holders = discovery.scopes.filter((scope) => {
    const names = new Set(scope.schemas.map((schema) => schema.name.toLowerCase()));
    return wanted.every((schema) => names.has(schema));
  });
  if (holders.length === 1) return holders[0]!.catalogOrDatabase;
  if (holders.length === 0) throw new Error(`No database on this connection has schema(s) ${schemas.join(', ')}. Check the names, or pass --database.`);
  throw new Error(`Schema(s) ${schemas.join(', ')} exist in ${holders.map((scope) => scope.catalogOrDatabase).join(', ')}; pass --database to choose one.`);
}

function warehouseCatalogStatus(projectRoot: string, config: ProjectConfig, connectionId: string): WarehouseCatalogSummary | undefined {
  if (!warehouseCatalogModeling(config) || connectionId !== warehouseCatalogConnectionId(config)) return undefined;
  const { snapshot, path, error } = readWarehouseCatalog(projectRoot);
  if (error) return { path, error };
  if (!snapshot) return { path, relations: 0 };
  return { path, relations: snapshot.relations.length, fingerprint: snapshot.fingerprint, capturedAt: snapshot.capturedAt, connectionId: snapshot.connectionId };
}

function configuredMetadataScopeInput(
  config: ProjectConfig,
  connectionId: string,
): ConnectionMetadataScopeInput | undefined {
  const value = config.metadataScopes?.[connectionId];
  return value && typeof value === 'object' ? value : undefined;
}

function activeConnectionMetadataScope(
  projectRoot: string,
  config: ProjectConfig,
  activeConnection: ConnectionConfig,
  connectionId: string = config.defaultConnectionName ?? 'default',
) {
  return normalizeConnectionMetadataScope(
    connectionId,
    activeConnection,
    configuredMetadataScopeInput(config, connectionId),
    metadataScopeDbtDefaults(projectRoot, config),
  );
}

function optionalActiveConnectionMetadataScope(
  projectRoot: string,
  config: ProjectConfig,
  activeConnection: ConnectionConfig,
  connectionId: string,
) {
  try {
    return activeConnectionMetadataScope(projectRoot, config, activeConnection, connectionId);
  } catch {
    return null;
  }
}

function projectConnectionById(
  projectRoot: string,
  config: ProjectConfig,
  connectionId: string,
): ConnectionConfig | null {
  const stored = getStoredConnections(config as unknown as Record<string, unknown>);
  const normalized = normalizeStoredConnection(stored[connectionId]);
  if (normalized) return normalizeProjectConnection(normalized, projectRoot);
  if (connectionId === (config.defaultConnectionName ?? 'default') && config.defaultConnection) {
    return normalizeProjectConnection(config.defaultConnection, projectRoot);
  }
  return null;
}

function persistConnectionMetadataScope(
  projectRoot: string,
  connectionId: string,
  scope: ConnectionMetadataScopeV1,
): void {
  const configPath = join(projectRoot, 'dql.config.json');
  const raw = existsSync(configPath)
    ? JSON.parse(readFileSync(configPath, 'utf-8')) as Record<string, unknown>
    : {};
  const existing = raw.metadataScopes && typeof raw.metadataScopes === 'object' && !Array.isArray(raw.metadataScopes)
    ? raw.metadataScopes as Record<string, unknown>
    : {};
  raw.metadataScopes = {
    ...existing,
    [connectionId]: {
      mode: scope.mode,
      scopes: scope.selectedScopes,
      relations: scope.relations.length > 0 ? scope.relations : undefined,
      dbtFingerprint: scope.dbtFingerprint,
    },
  };
  writeFileSync(configPath, JSON.stringify(raw, null, 2) + '\n', 'utf-8');
}

