function providerSettingsLabel(id: ProviderSettingsId): string {
  switch (id) {
    case 'anthropic': return 'Anthropic Claude';
    case 'openai': return 'OpenAI';
    case 'gemini': return 'Gemini';
    case 'ollama': return 'Ollama';
    case 'custom-openai': return 'Custom OpenAI-compatible provider';
    case 'claude-code': return 'Claude subscription (Claude Code CLI)';
    case 'codex': return 'ChatGPT subscription (Codex CLI)';
  }
}

function providerConfigDetails(id: ProviderSettingsId, config: ReturnType<typeof getEffectiveProviderConfig>): string {
  // Subscription providers (Claude Code / Codex) authenticate via OAuth/CLI, not an
  // API key — omit the key clause so we don't report a misleading "API key missing".
  const isSubscription = id === 'claude-code' || id === 'codex';
  const authNote = isSubscription
    ? ''
    : id === 'ollama' ? 'local endpoint' : config.apiKey ? 'API key present' : 'API key missing';
  const parts = [
    config.model ? `model ${config.model}` : '',
    config.baseUrl ? `base URL ${config.baseUrl}` : '',
    authNote,
  ].filter(Boolean);
  return parts.length ? ` (${parts.join(', ')})` : '';
}

function isAiPinRefreshDue(lastRefreshedAt?: string): boolean {
  if (!lastRefreshedAt) return true;
  const last = Date.parse(lastRefreshedAt);
  if (!Number.isFinite(last)) return true;
  return Date.now() - last >= 24 * 60 * 60 * 1000;
}

async function buildAgentSchemaContextFromCatalog(
  projectRoot: string,
  question: string,
  preparedContextPack?: LocalContextPack,
): Promise<AgentSchemaTable[]> {
  const contextPack = preparedContextPack ?? await buildLocalContextPack(projectRoot, { question, limit: 80 });
  return buildAgentSchemaContextFromContextPack(question, contextPack);
}

/** How long a stored live-warehouse schema snapshot is trusted before a rescan (P6). */
const RUNTIME_SNAPSHOT_MAX_AGE_MS = 60 * 60 * 1000; // 1 hour
// A resolver compares at most 12 compact cards and never performs tool calls;
// ten seconds is the full allowance, not the start of another planning loop.
/**
 * Ceiling on the one bounded meaning-resolution call.
 *
 * 10s assumes a hosted model. A local Ollama model needs ~7s for a ONE-WORD
 * reply, so a 600-token resolution over a dozen candidates never lands: it
 * aborts, the router falls back to its evidence-only decision, and
 * `mayAssumeInterpretation` goes false — which sends every ambiguous question to
 * the clarification gate (AGT-017). The effect is that a local model cannot
 * answer anything ambiguous, in a product whose whole positioning is local-first.
 *
 * Scaled by the same `DQL_AGENT_DEADLINE_SCALE` as the run budget, so one
 * setting moves the provider's whole time envelope together rather than leaving
 * an inner bound to silently cap an outer one.
 */
/**
 * Predict how long the next provider call will take, for admission control.
 *
 * With fewer than three samples the MAX is the only honest predictor: there is
 * no distribution yet, and admitting a call the deadline then kills wastes the
 * whole remaining budget.
 *
 * With a real sample, p75 rather than the max. One slow response — a cold model
 * load, a retried connection — otherwise poisons admission control for the rest
 * of the run: every later call is refused against a worst case that already
 * passed. A recorded run tripped RUN_DEADLINE_INSUFFICIENT 6.4s into a 45s
 * budget for exactly that reason. p75 still errs slow, so a genuinely slow
 * provider is still respected.
 */
/**
 * The answer an Ask pipeline trace explains: its SQL, DQL, columns and a small
 * row sample, read from the saved run at this local API boundary (the trace
 * store itself keeps no SQL or rows).
 */
export function traceAnswerProjection(run: { status?: string; artifacts?: Array<{ kind?: string; payload?: unknown }>; evaluations?: unknown[] }): Record<string, unknown> | undefined {
  const artifact = run.artifacts?.find((item) => item.kind === 'answer') ?? run.artifacts?.[0];
  const payload = (artifact?.payload && typeof artifact.payload === 'object' ? artifact.payload : {}) as Record<string, unknown>;
  const result = (payload.result && typeof payload.result === 'object' ? payload.result : {}) as { columns?: unknown[]; rows?: unknown[]; rowCount?: number };
  const gap = payload.gap && typeof payload.gap === 'object' ? payload.gap as Record<string, unknown> : undefined;
  const projection: Record<string, unknown> = {
    // How the turn ended, so the trace tells a gap, a clarification and a failure apart.
    ...(typeof run.status === 'string' ? { status: run.status } : {}),
    ...(gap ? { gap: { ...(typeof gap.kind === 'string' ? { kind: gap.kind } : {}), ...(typeof gap.message === 'string' ? { message: gap.message } : {}) } } : {}),
    ...(typeof payload.executionError === 'string' ? { executionError: payload.executionError } : {}),
    ...(typeof payload.failedStage === 'string' ? { failedStage: payload.failedStage } : {}),
    ...(typeof payload.certifiedBlockRef === 'string' ? { certifiedBlockRef: payload.certifiedBlockRef } : {}),
    ...(Array.isArray(payload.proof) ? { proof: payload.proof.filter((line) => typeof line === 'string').slice(0, 40) } : {}),
    ...(typeof payload.sql === 'string' ? { sql: payload.sql } : {}),
    ...(Array.isArray(payload.sqlParams) ? { sqlParams: payload.sqlParams } : {}),
    ...(payload.dqlArtifact && typeof payload.dqlArtifact === 'object' ? { dqlArtifact: payload.dqlArtifact } : {}),
    ...(Array.isArray(result.columns) ? { columns: result.columns } : {}),
    ...(Array.isArray(result.rows) ? { rowsSample: result.rows.slice(0, 20) } : {}),
    ...(typeof result.rowCount === 'number' ? { rowCount: result.rowCount } : {}),
    ...(Array.isArray(run.evaluations) && run.evaluations.length ? { evaluations: run.evaluations } : {}),
  };
  return Object.keys(projection).length ? projection : undefined;
}

export function predictDispatchMs(
  observed: readonly number[],
  assumedMs: number = ASSUMED_PROVIDER_DISPATCH_MS,
): number {
  if (observed.length === 0) return assumedMs;
  const sorted = [...observed].sort((left, right) => left - right);
  if (sorted.length < 3) return sorted[sorted.length - 1]!;
  const index = Math.max(0, Math.min(sorted.length - 1, Math.ceil(sorted.length * 0.75) - 1));
  return sorted[index]!;
}

const AGENT_MEANING_TIMEOUT_BASE_MS = 10_000;
const AGENT_MEANING_TIMEOUT_MS = AGENT_MEANING_TIMEOUT_BASE_MS * deadlineScale();

export function boundedAgentMeaningSignal(
  signal?: AbortSignal,
  timeoutMs: number = AGENT_MEANING_TIMEOUT_MS,
): AbortSignal {
  const timeout = AbortSignal.timeout(Math.max(1, timeoutMs));
  return signal ? AbortSignal.any([signal, timeout]) : timeout;
}

/**
 * Whether the project's stored live-schema snapshot is missing or older than the
 * freshness window (P6). Used to force a fresh information_schema scan even when the
 * question-shape heuristic wouldn't otherwise trigger one — so a warehouse schema
 * change between sessions isn't silently reasoned over. Best-effort: a catalog error
 * returns false so it never causes a rescan storm.
 */
export function runtimeSnapshotStale(projectRoot: string, maxAgeMs: number = RUNTIME_SNAPSHOT_MAX_AGE_MS): boolean {
  try {
    const snapshot = latestRuntimeSchemaSnapshotForProject(projectRoot);
    if (!snapshot?.capturedAt) return true;
    const age = Date.now() - new Date(snapshot.capturedAt).getTime();
    return !Number.isFinite(age) || age > maxAgeMs;
  } catch {
    return false;
  }
}

/**
 * Resolve only metadata captured for the connection executing this Ask run.
 * Returning an explicit empty snapshot is a correctness boundary: callers pass
 * it into the context builder so it cannot silently fall back to another
 * connection's project-global runtime FTS rows.
 */
export function runtimeSchemaSnapshotForAgentConnection(
  projectRoot: string,
  connectionId: string,
  expectedScopeFingerprint?: string,
): RuntimeSchemaSnapshot {
  const snapshot = latestRuntimeSchemaSnapshotForProject(projectRoot, connectionId);
  const current = Boolean(
    snapshot
    && snapshot.status !== 'stale'
    && (
      !expectedScopeFingerprint
      || !snapshot.scopeFingerprint
      || snapshot.scopeFingerprint === expectedScopeFingerprint
    ),
  );
  return current
    ? snapshot!
    : {
        version: 1,
        connectionId,
        status: 'partial',
        source: 'selected connection has no current runtime metadata',
        tables: [],
      };
}

function recordAgentRuntimeSchemaSnapshot(
  projectRoot: string,
  schemaContext: AgentSchemaTable[],
  source: string,
  connectionId?: string,
): void {
  if (schemaContext.length === 0) return;
  try {
    recordRuntimeSchemaSnapshot(projectRoot, {
      ...(connectionId ? { connectionId } : {}),
      status: 'partial',
      source,
      tables: schemaContext.map((table) => ({
        relation: table.relation,
        schema: table.schema,
        name: table.name,
        description: table.description,
        source: table.source,
        columns: table.columns.slice(0, 120).map((column) => ({
          name: column.name,
          type: column.type,
          description: column.description,
        })),
      })),
    });
  } catch {
    // Runtime schema snapshots are advisory local metadata and must not block answers.
  }
}

function notebookResearchString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() ? value.trim() : undefined;
}

function notebookResearchRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}

function notebookResearchSourceCellPayload(body: Record<string, unknown>): NotebookResearchSourceCellInput | undefined {
  const sourceCell = notebookResearchRecord(body.sourceCell)
    ?? notebookResearchRecord(notebookResearchRecord(body.context)?.sourceCell);
  if (!sourceCell) return undefined;
  const payload: NotebookResearchSourceCellInput = {
    id: notebookResearchString(sourceCell.id),
    sourceCellId: notebookResearchString(sourceCell.sourceCellId),
    cellId: notebookResearchString(sourceCell.cellId),
    name: notebookResearchString(sourceCell.name),
    sourceCellName: notebookResearchString(sourceCell.sourceCellName),
    title: notebookResearchString(sourceCell.title),
    fingerprint: notebookResearchString(sourceCell.fingerprint),
    sourceCellFingerprint: notebookResearchString(sourceCell.sourceCellFingerprint),
    sqlFingerprint: notebookResearchString(sourceCell.sqlFingerprint),
    type: notebookResearchString(sourceCell.type),
    sql: notebookResearchString(sourceCell.sql),
    content: notebookResearchString(sourceCell.content),
    source: notebookResearchString(sourceCell.source),
  };
  return Object.values(payload).some(Boolean) ? payload : undefined;
}

function notebookResearchSourceCellId(sourceCell: NotebookResearchSourceCellInput | undefined): string | undefined {
  return notebookResearchString(sourceCell?.id)
    ?? notebookResearchString(sourceCell?.sourceCellId)
    ?? notebookResearchString(sourceCell?.cellId);
}

function notebookResearchSourceCellName(sourceCell: NotebookResearchSourceCellInput | undefined): string | undefined {
  return notebookResearchString(sourceCell?.name)
    ?? notebookResearchString(sourceCell?.sourceCellName)
    ?? notebookResearchString(sourceCell?.title);
}

function notebookResearchSourceCellFingerprint(sourceCell: NotebookResearchSourceCellInput | undefined): string | undefined {
  return notebookResearchString(sourceCell?.sourceCellFingerprint)
    ?? notebookResearchString(sourceCell?.fingerprint)
    ?? notebookResearchString(sourceCell?.sqlFingerprint);
}

function notebookResearchPatchString(body: Record<string, unknown>, key: string): string | null | undefined {
  if (!Object.prototype.hasOwnProperty.call(body, key)) return undefined;
  return notebookResearchString(body[key]) ?? null;
}

function notebookResearchIntent(value: unknown): NotebookResearchIntent | undefined {
  return value === 'ad_hoc_analysis'
    || value === 'diagnose_change'
    || value === 'driver_breakdown'
    || value === 'segment_compare'
    || value === 'entity_drilldown'
    || value === 'anomaly_investigation'
    || value === 'trust_gap_review'
    ? value
    : undefined;
}

function notebookResearchReviewStatus(value: unknown): NotebookResearchRun['reviewStatus'] | undefined {
  return value === 'needs_review'
    || value === 'draft_created'
    || value === 'completed'
    || value === 'certified'
    || value === 'rejected'
    ? value
    : undefined;
}

function notebookResearchStatus(value: unknown): NotebookResearchRun['status'] | undefined {
  return value === 'draft'
    || value === 'running'
    || value === 'ready'
    || value === 'error'
    ? value
    : undefined;
}

function notebookResearchPromotionAction(value: unknown): NotebookResearchDqlPromotionAction | undefined {
  return value === 'reuse_existing'
    || value === 'extend_existing'
    || value === 'create_replacement'
    || value === 'create_new'
    || value === 'review_required'
    ? value
    : undefined;
}

function notebookResearchReadiness(value: unknown): NotebookResearchReadinessFilter | undefined {
  return value === 'draft_ready' || value === 'certification_ready' || value === 'blocked' ? value : undefined;
}

function notebookResearchAge(value: unknown): 'stale_open' | 'expired_open' | undefined {
  return value === 'stale_open' || value === 'expired_open' ? value : undefined;
}

function notebookResearchNextAction(value: unknown): NotebookResearchNextActionFilter | undefined {
  return value === 'fix_blockers'
    || value === 'review_sql'
    || value === 'review_context'
    || value === 'run_preview'
    || value === 'reuse_existing'
    || value === 'create_dql_draft'
    || value === 'open_certification'
    || value === 'complete_review'
    || value === 'continue_review'
    ? value
    : undefined;
}

function notebookResearchSort(value: unknown): NotebookResearchSort | undefined {
  return value === 'priority' || value === 'updated_desc' ? value : undefined;
}

type NotebookResearchChecklistItemStatus = 'passed' | 'pending' | 'warning' | 'blocked';
type NotebookResearchReviewChecklist = {
  readyForDqlDraft: boolean;
  readyForCertificationReview: boolean;
  blockers: string[];
  warnings: string[];
  items: Array<{
    id: string;
    label: string;
    status: NotebookResearchChecklistItemStatus;
    detail: string;
  }>;
};

function withNotebookResearchChecklistPage(page: NotebookResearchRunListResult): Omit<NotebookResearchRunListResult, 'runs'> & { runs: Array<NotebookResearchRun & { reviewChecklist: NotebookResearchReviewChecklist }> } {
  return {
    ...page,
    runs: page.runs.map(withNotebookResearchChecklist),
  };
}

function withNotebookResearchChecklist(run: NotebookResearchRun): NotebookResearchRun & { reviewChecklist: NotebookResearchReviewChecklist } {
  const researchPlan = run.researchPlan ?? buildNotebookResearchPlan({
    run,
    evidence: run.evidence,
    resultPreview: run.resultPreview as ReturnType<typeof normalizeQueryResult> | undefined,
    previewError: run.status === 'error' ? run.error : undefined,
    generatedSql: run.generatedSql,
    reviewedSql: run.reviewedSql,
    routeDecision: run.routeDecision,
  });
  return {
    ...run,
    researchPlan,
    reviewChecklist: buildNotebookResearchReviewChecklist(run),
  };
}

function buildNotebookResearchReviewChecklist(run: NotebookResearchRun): NotebookResearchReviewChecklist {
  const questionReady = Boolean(notebookResearchString(run.question));
  const hasReviewedSql = Boolean(notebookResearchString(run.reviewedSql));
  const hasGeneratedSql = Boolean(notebookResearchString(run.generatedSql));
  const hasDqlArtifact = Boolean(normalizeDqlArtifactReference(run.dqlArtifact)?.source);
  const hasSql = hasReviewedSql || hasGeneratedSql;
  const hasPromotableSource = hasReviewedSql || hasDqlArtifact;
  const preview = notebookResearchPreviewInfo(run.resultPreview);
  const previewReady = run.status === 'ready' && preview.hasPreview;
  const evidenceReady = notebookResearchEvidenceCount(run.evidence) > 0 || Boolean(run.contextPackId);
  const promoted = Boolean(run.dqlPromotion || run.dqlImportId || run.draftBlockPath);
  const duplicateChecked = Boolean(run.dqlPromotionAction || run.dqlPromotion);
  const promotionAction = run.dqlPromotionAction ?? run.dqlPromotion?.recommendedAction;
  const reuseRecommended = promotionAction === 'reuse_existing';
  const promotionReviewRequired = promotionAction === 'review_required';
  const reuseClosed = reuseRecommended && (run.reviewStatus === 'completed' || run.reviewStatus === 'certified');
  const hasDraft = Boolean(notebookResearchString(run.draftBlockPath));
  const sqlForParameterReview = notebookResearchString(run.reviewedSql) ?? notebookResearchString(run.generatedSql);
  const parameterReview = sqlForParameterReview ? parameterizeSqlForDqlImport(sqlForParameterReview) : null;
  const dynamicParameters = parameterReview?.parameterPolicy.filter((item) => item.policy === 'dynamic') ?? [];
  const staticParameters = parameterReview?.parameterPolicy.filter((item) => item.policy !== 'dynamic') ?? [];
  const blockers: string[] = [];
  const warnings: string[] = [];

  if (!questionReady) blockers.push('Add a business question before review.');
  if (!hasSql && !hasDqlArtifact && !reuseRecommended) blockers.push('Add reviewed SQL, generate SQL, or attach a DQL artifact before promotion.');
  if (run.status === 'error') blockers.push(run.error ? `Fix preview error: ${run.error}` : 'Fix the failed preview before promotion.');
  if (!previewReady && run.status !== 'error' && !reuseRecommended) warnings.push('Run a bounded preview before certification review.');
  if (!evidenceReady && !reuseRecommended) warnings.push('Inspect metadata evidence before turning this into a reusable block.');
  if (hasSql && dynamicParameters.length === 0) warnings.push('No dynamic parameters were detected; confirm this should be a static block before certification.');
  for (const warning of parameterReview?.warnings ?? []) warnings.push(warning);
  if (promoted && !duplicateChecked) warnings.push('Promotion exists but duplicate/reuse evidence is missing.');
  if (reuseRecommended && !reuseClosed) warnings.push('Reuse the matching block or explicitly document a replacement before certification.');
  if (promotionReviewRequired) warnings.push('Resolve the review-required promotion decision before certification.');

  const items: NotebookResearchReviewChecklist['items'] = [
    {
      id: 'question',
      label: 'Question',
      status: questionReady ? 'passed' : 'blocked',
      detail: questionReady ? 'Business question is captured.' : 'A reusable block needs a clear business question.',
    },
    {
      id: 'sql',
      label: hasDqlArtifact && !hasReviewedSql ? 'DQL artifact' : 'Reviewed SQL',
      status: hasReviewedSql || hasDqlArtifact || (reuseRecommended && !hasSql) ? 'passed' : hasGeneratedSql ? 'warning' : 'blocked',
      detail: reuseRecommended && !hasSql
        ? 'Existing certified DQL should be reused; no new SQL is required.'
        : hasDqlArtifact && !hasReviewedSql
        ? 'Generated DQL artifact is saved for reviewer promotion.'
        : hasReviewedSql
        ? 'Reviewer SQL is saved.'
        : hasGeneratedSql
          ? 'Generated SQL exists; review it before promotion.'
          : 'No SQL is available for preview or DQL generation.',
    },
    {
      id: 'preview',
      label: 'Preview',
      status: previewReady || (reuseRecommended && !hasSql) ? 'passed' : run.status === 'error' ? 'blocked' : 'pending',
      detail: reuseRecommended && !hasSql
        ? 'Certified block reuse does not require a new raw SQL preview.'
        : previewReady
        ? `Preview returned ${preview.rowCount.toLocaleString()} row${preview.rowCount === 1 ? '' : 's'}.`
        : run.status === 'error'
          ? (run.error ?? 'Preview failed.')
          : 'Run a bounded preview to validate the query shape.',
    },
    {
      id: 'evidence',
      label: 'Evidence',
      status: evidenceReady || reuseRecommended ? 'passed' : 'warning',
      detail: evidenceReady
        ? 'Metadata evidence or context pack is attached.'
        : reuseRecommended
          ? 'Reuse evidence is captured in the AI recommendation.'
          : 'No context evidence is attached yet.',
    },
    {
      id: 'duplicates',
      label: 'Reuse check',
      status: duplicateChecked ? (reuseRecommended || promotionReviewRequired ? 'warning' : 'passed') : promoted ? 'warning' : 'pending',
      detail: duplicateChecked
        ? `Promotion decision: ${promotionAction ?? 'review required'}.`
        : promoted
          ? 'Draft was created without stored duplicate evidence.'
          : 'Duplicate check runs when creating a DQL draft.',
    },
    {
      id: 'parameters',
      label: 'Parameter review',
      status: reuseRecommended && !hasSql ? 'passed' : !hasSql && !hasDqlArtifact ? 'pending' : hasDqlArtifact && !hasSql ? 'passed' : dynamicParameters.length > 0 ? 'passed' : 'warning',
      detail: reuseRecommended && !hasSql
        ? 'Use the certified block parameters; no new SQL parameterization is required.'
        : !hasSql && hasDqlArtifact
        ? 'Review parameters declared in the DQL artifact.'
        : !hasSql
        ? 'Add SQL or a DQL artifact before checking runtime parameters.'
        : dynamicParameters.length > 0
          ? `Detected ${dynamicParameters.length.toLocaleString()} dynamic parameter${dynamicParameters.length === 1 ? '' : 's'}: ${dynamicParameters.slice(0, 6).map((item) => item.name).join(', ')}.`
          : staticParameters.length > 0
            ? `Only static or review-required literals were detected: ${staticParameters.slice(0, 6).map((item) => `${item.name} (${item.policy})`).join(', ')}.`
            : 'No reusable runtime parameters were detected. Certify as static only if the business question is intentionally fixed.',
    },
    {
      id: 'dql_draft',
      label: 'DQL draft',
      status: reuseRecommended && !hasDraft ? 'passed' : hasDraft ? 'passed' : hasPromotableSource && evidenceReady ? 'pending' : 'blocked',
      detail: reuseRecommended && !hasDraft
        ? 'No new draft is required because an existing DQL block should be reused.'
        : hasDraft
        ? `Draft saved at ${run.draftBlockPath}.`
        : !hasPromotableSource
          ? 'Save reviewed SQL or review the generated DQL artifact before DQL draft creation.'
          : evidenceReady
            ? (hasDqlArtifact && !hasReviewedSql ? 'Create a draft after DQL artifact review.' : 'Create a draft after SQL review.')
            : 'Save metadata evidence before creating a reusable DQL draft.',
    },
  ];

  const readyForDqlDraft = questionReady && hasPromotableSource && evidenceReady && run.status !== 'error';
  const readyForCertificationReview = readyForDqlDraft && previewReady && hasDraft && !reuseRecommended && !promotionReviewRequired;
  return { readyForDqlDraft, readyForCertificationReview, blockers, warnings, items };
}

function buildNotebookResearchPlan(input: {
  run: NotebookResearchRun;
  evidence?: unknown;
  resultPreview?: ReturnType<typeof normalizeQueryResult>;
  previewError?: string;
  generatedSql?: string;
  reviewedSql?: string;
  dqlArtifact?: NotebookResearchDqlArtifact;
  routeDecision?: unknown;
}): NotebookResearchPlan {
  const reviewedSql = notebookResearchString(input.reviewedSql);
  const generatedSql = notebookResearchString(input.generatedSql);
  const sql = reviewedSql ?? generatedSql;
  const dqlArtifact = normalizeDqlArtifactReference(input.dqlArtifact) ?? input.run.dqlArtifact;
  const hasDqlArtifact = Boolean(dqlArtifact?.source);
  const parameterized = sql ? parameterizeSqlForDqlImport(sql) : null;
  const evidence = input.evidence && typeof input.evidence === 'object' && !Array.isArray(input.evidence)
    ? input.evidence as Record<string, unknown>
    : {};
  const trustStatus = evidence.trustStatus && typeof evidence.trustStatus === 'object' && !Array.isArray(evidence.trustStatus)
    ? evidence.trustStatus as Record<string, unknown>
    : {};
  const allowedSqlContext = evidence.allowedSqlContext && typeof evidence.allowedSqlContext === 'object' && !Array.isArray(evidence.allowedSqlContext)
    ? evidence.allowedSqlContext as Record<string, unknown>
    : {};
  const previewRows = input.resultPreview?.rowCount ?? input.resultPreview?.rows.length;
  const hasEvidence = notebookResearchEvidenceCount(input.evidence) > 0 || Boolean(input.run.contextPackId);
  const hasPreview = previewRows !== undefined && (previewRows > 0 || Boolean(input.resultPreview?.columns.length));
  const promotionAction = input.run.dqlPromotionAction ?? input.run.dqlPromotion?.recommendedAction;
  const missingContext = Array.isArray(evidence.missingContext) ? evidence.missingContext : [];
  const relations = Array.isArray(allowedSqlContext.relations) ? allowedSqlContext.relations : [];
  return {
    sqlState: reviewedSql ? 'reviewed' : generatedSql ? 'generated' : 'missing',
    grain: sql ? extractDqlGenerationGroupByFields(sql)[0] : undefined,
    parameterPolicy: (parameterized?.parameterPolicy ?? []).slice(0, 16).map((entry) => ({
      name: entry.name,
      policy: entry.policy,
    })),
    allowedFilters: (parameterized?.allowedFilters ?? []).slice(0, 16),
    evidence: {
      trustLabel: notebookResearchString(trustStatus.label),
      contextPackId: notebookResearchString(evidence.contextPackId) ?? input.run.contextPackId,
      evidenceCount: notebookResearchEvidenceCount(input.evidence),
      relationCount: relations.length,
      missingContextCount: missingContext.length,
    },
    preview: {
      status: input.previewError ? 'error' : hasPreview ? 'ready' : 'not_run',
      ...(previewRows === undefined ? {} : { rowCount: previewRows }),
    },
    promotion: {
      path: notebookResearchPlanPromotionPath({
        hasSql: Boolean(sql),
        hasDqlArtifact,
        hasEvidence,
        hasPreview,
        previewError: input.previewError,
        draftBlockPath: input.run.draftBlockPath,
        promotionAction,
      }),
      duplicateDecision: promotionAction,
    },
    reviewFocus: notebookResearchPlanFocus(input.run.intent, {
      hasSql: Boolean(sql),
      hasDqlArtifact,
      hasEvidence,
      hasPreview,
      dynamicParameterCount: parameterized?.parameterPolicy.filter((entry) => entry.policy === 'dynamic').length ?? 0,
      missingContextCount: missingContext.length,
      promotionAction,
    }),
    generatedAt: new Date().toISOString(),
  };
}

function notebookResearchPlanPromotionPath(input: {
  hasSql: boolean;
  hasDqlArtifact: boolean;
  hasEvidence: boolean;
  hasPreview: boolean;
  previewError?: string;
  draftBlockPath?: string;
  promotionAction?: string;
}): NotebookResearchPlan['promotion']['path'] {
  if (input.promotionAction === 'reuse_existing') return 'reuse_existing';
  if (!input.hasSql && !input.hasDqlArtifact) return 'needs_sql';
  if (!input.hasEvidence) return 'review_context';
  if (input.previewError || !input.hasPreview) return 'run_preview';
  if (input.draftBlockPath) return 'open_certification';
  return 'create_dql_draft';
}

function notebookResearchPlanFocus(
  intent: NotebookResearchIntent,
  input: {
    hasSql: boolean;
    hasDqlArtifact: boolean;
    hasEvidence: boolean;
    hasPreview: boolean;
    dynamicParameterCount: number;
    missingContextCount: number;
    promotionAction?: string;
  },
): string[] {
  const focus = new Set<string>();
  if (!input.hasSql && !input.hasDqlArtifact) focus.add('Add reviewed SQL, a DQL artifact, or configure AI generation.');
  if (!input.hasEvidence) focus.add('Save metadata context evidence before DQL promotion.');
  if (!input.hasPreview) focus.add('Run a bounded preview and inspect result shape.');
  if (input.dynamicParameterCount === 0) focus.add('Confirm whether this should be static or parameterized.');
  if (input.missingContextCount > 0) focus.add('Resolve missing metadata context before certification.');
  if (input.promotionAction === 'reuse_existing') focus.add('Reuse the existing certified block or document replacement rationale.');
  const pattern = notebookResearchIntentPattern(intent);
  const reviewFocus = Array.isArray(pattern.reviewFocus) ? pattern.reviewFocus : [];
  for (const item of reviewFocus.slice(0, 4)) focus.add(String(item));
  return Array.from(focus).slice(0, 8);
}

function notebookResearchPreviewInfo(value: unknown): { hasPreview: boolean; rowCount: number } {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return { hasPreview: false, rowCount: 0 };
  const record = value as Record<string, unknown>;
  const rowCount = typeof record.rowCount === 'number' && Number.isFinite(record.rowCount)
    ? record.rowCount
    : Array.isArray(record.rows)
      ? record.rows.length
      : 0;
  const hasColumns = Array.isArray(record.columns) && record.columns.length > 0;
  return { hasPreview: hasColumns || rowCount > 0, rowCount };
}

function notebookResearchEvidenceCount(value: unknown): number {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return 0;
  const record = value as Record<string, unknown>;
  const selected = Array.isArray(record.selectedEvidence) ? record.selectedEvidence.length : 0;
  const citations = Array.isArray(record.citations) ? record.citations.length : 0;
  const roles = Array.isArray(record.evidenceRoles) ? record.evidenceRoles.length : 0;
  return selected + citations + roles;
}

function notebookResearchInteger(value: unknown, fallback: number, min: number, max: number): number {
  if (typeof value !== 'string' || !value.trim()) return fallback;
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(min, Math.min(max, Math.floor(parsed)));
}

type NotebookExecutionContextInput = {
  notebookPath?: string;
  cellId?: string;
  cellName?: string;
  researchRunId?: string;
  source?: string;
  runId?: string;
};

function notebookExecutionContext(value: unknown): NotebookExecutionContextInput | null {
  if (!value || typeof value !== 'object') return null;
  const raw = value as Record<string, unknown>;
  const notebookPath = notebookResearchString(raw.notebookPath);
  const cellId = notebookResearchString(raw.cellId);
  const runId = notebookResearchString(raw.runId);
  if (!notebookPath && !cellId && !runId) return null;
  return {
    notebookPath,
    cellId,
    cellName: notebookResearchString(raw.cellName),
    researchRunId: notebookResearchString(raw.researchRunId),
    source: notebookResearchString(raw.source),
    runId,
  };
}

function notebookExecutionIdentity(
  context: NotebookExecutionContextInput | null,
  fallbackCellId?: string,
): { cellId?: string; runId?: string } | undefined {
  const cellId = context?.cellId ?? fallbackCellId;
  const runId = context?.runId;
  return cellId || runId ? { cellId, runId } : undefined;
}

function notebookResearchSelectedContext(run: NotebookResearchRun, context: unknown): Record<string, unknown> {
  return {
    activeSurface: 'notebook',
    notebookPath: run.notebookPath,
    domain: run.domain,
    sourceCellId: run.sourceCellId,
    sourceCellName: run.sourceCellName,
    context,
  };
}

function notebookResearchIntentPattern(intent: NotebookResearchIntent): Record<string, unknown> {
  switch (intent) {
    case 'diagnose_change':
      return {
        label: 'Change diagnosis',
        dqlTarget: 'driver or trend block',
        sqlFocus: ['baseline period', 'comparison period', 'metric delta', 'driver dimensions'],
        reviewFocus: ['time grain', 'comparison filters', 'metric definition', 'explainability evidence'],
      };
    case 'driver_breakdown':
      return {
        label: 'Driver breakdown',
        dqlTarget: 'ranking or contribution block',
        sqlFocus: ['contribution metric', 'ranking', 'tie breaker', 'segment dimensions'],
        reviewFocus: ['metric grain', 'ranking direction', 'parameterized filters', 'duplicate block match'],
      };
    case 'segment_compare':
      return {
        label: 'Segment compare',
        dqlTarget: 'comparison block',
        sqlFocus: ['shared metric', 'segment fields', 'normalized comparisons', 'deltas'],
        reviewFocus: ['segment definitions', 'filter compatibility', 'comparison grain', 'semantic metric alignment'],
      };
    case 'entity_drilldown':
      return {
        label: 'Entity drilldown',
        dqlTarget: 'entity profile or drilldown block',
        sqlFocus: ['entity grain', 'stable identifier', 'detail fields', 'supporting metrics'],
        reviewFocus: ['entity contract', 'primary key', 'allowed filters', 'downstream drill path'],
      };
    case 'anomaly_investigation':
      return {
        label: 'Anomaly investigation',
        dqlTarget: 'monitoring or exception block',
        sqlFocus: ['observed value', 'expected range', 'anomaly rule', 'supporting dimensions'],
        reviewFocus: ['threshold definition', 'time window', 'false-positive risk', 'evidence fields'],
      };
    case 'trust_gap_review':
      return {
        label: 'Trust review',
        dqlTarget: 'replacement or validation block',
        sqlFocus: ['definition comparison', 'lineage trace', 'duplicate candidates', 'conflict evidence'],
        reviewFocus: ['certified block match', 'semantic metric match', 'replacement reason', 'governance blockers'],
      };
    default:
      return {
        label: 'Ad hoc analysis',
        dqlTarget: 'custom block',
        sqlFocus: ['business question', 'grain', 'metrics', 'dimensions', 'filters'],
        reviewFocus: ['reusability', 'parameterization', 'lineage evidence', 'DQL promotion path'],
      };
  }
}

function notebookResearchAgentPrompt(question: string, intent: NotebookResearchIntent): string {
  const pattern = notebookResearchIntentPattern(intent);
  const sqlFocus = Array.isArray(pattern.sqlFocus) ? pattern.sqlFocus.join(', ') : 'business logic';
  const reviewFocus = Array.isArray(pattern.reviewFocus) ? pattern.reviewFocus.join(', ') : 'review evidence';
  return [
    `Research question: ${question}`,
    `Research pattern: ${pattern.label ?? intent}`,
    `DQL target: ${pattern.dqlTarget ?? 'custom block'}`,
    `SQL focus: ${sqlFocus}`,
    `Review focus: ${reviewFocus}`,
    'Generate read-only SQL that can become a reusable, parameterized DQL block after human review.',
  ].join('\n');
}

function notebookResearchRouteDecisionForRun(
  run: NotebookResearchRun,
  routeDecision: LocalContextPack['routeDecision'] | undefined,
  sqlForPreview?: string,
): LocalContextPack['routeDecision'] | undefined {
  if (!routeDecision) return undefined;
  const hasSelectedNotebookSql = Boolean(run.sourceCellId && notebookResearchString(sqlForPreview));
  if (!hasSelectedNotebookSql || routeDecision.route !== 'certified') return routeDecision;

  const certifiedEvidence = routeDecision.selectedEvidence.find((item) => item.role === 'exact_certified_answer')
    ?? routeDecision.selectedEvidence.find((item) => item.role === 'certified_context');
  const certifiedName = certifiedEvidence?.name ?? routeDecision.certifiedApplicability?.objectKey ?? 'matching certified artifact';
  return {
    ...routeDecision,
    route: 'research',
    trustLabel: routeDecision.trustLabel === 'certified' ? 'mixed' : routeDecision.trustLabel,
    reviewStatus: 'needs_review',
    exactObjectKey: undefined,
    reason: `Selected notebook SQL from "${run.sourceCellName ?? run.sourceCellId}" is the source for this research run. Certified artifact "${certifiedName}" is duplicate/reuse evidence until the reviewed SQL, grain, parameters, and preview are accepted.`,
    selectedEvidence: routeDecision.selectedEvidence.map((item) => item.role === 'exact_certified_answer'
      ? {
          ...item,
          role: 'certified_context',
          reason: 'Certified block is reuse or duplicate evidence for the selected notebook SQL; it is not an automatic answer for this research run.',
        }
      : item),
    missingContext: routeDecision.missingContext.length > 0
      ? routeDecision.missingContext
      : [{
          kind: 'metadata',
          severity: 'warning',
          message: 'Selected notebook SQL requires human review before DQL promotion, even when certified context exists.',
        }],
  };
}

function notebookResearchContextPreview(contextPack: LocalContextPack): Record<string, unknown> {
  return {
    contextPackId: contextPack.id,
    trustLabel: contextPack.trustLabel,
    routeDecision: contextPack.routeDecision
      ? {
          route: contextPack.routeDecision.route,
          intent: contextPack.routeDecision.intent,
          reason: contextPack.routeDecision.reason,
        }
      : undefined,
    evidence: contextPack.evidenceRoles.slice(0, 16).map((item) => ({
      objectKey: item.objectKey,
      objectType: item.objectType,
      name: item.name,
      role: item.role,
      reason: item.reason,
    })),
    summaries: contextPack.evidenceSummaries.slice(0, 12).map((item) => ({
      title: item.title,
      detail: item.detail,
      objectType: item.objectType,
      reason: item.reason,
    })),
    relations: contextPack.allowedSqlContext.relations.slice(0, 12).map((relation) => ({
      relation: relation.relation,
      name: relation.name,
      source: relation.source,
      columns: relation.columns.slice(0, 24).map((column) => {
        if (typeof column === 'string') return column;
        if (column && typeof column === 'object' && typeof (column as { name?: unknown }).name === 'string') {
          return String((column as { name: unknown }).name);
        }
        return String(column);
      }),
    })),
    missingContext: contextPack.missingContext.slice(0, 12).map((item) => ({
      kind: item.kind,
      message: item.message,
      severity: item.severity,
    })),
    warnings: contextPack.warnings.slice(0, 12),
    topRejected: contextPack.retrievalDiagnostics.topRejected.slice(0, 8).map((item) => ({
      name: item.name,
      objectType: item.objectType,
      reason: item.reason,
      score: item.score,
    })),
    counts: {
      objects: contextPack.objects.length,
      evidence: contextPack.evidenceRoles.length,
      relations: contextPack.allowedSqlContext.relations.length,
      warnings: contextPack.warnings.length + contextPack.missingContext.length,
    },
  };
}

function normalizeNotebookAgentResult(result: AgentResultPayload): ReturnType<typeof normalizeQueryResult> {
  const canonical = normalizeCanonicalQueryResult({
    columns: result.columns,
    rows: result.rows,
    rowCount: result.rowCount,
    executionTime: result.executionTime,
    resultFingerprint: result.resultFingerprint,
    executionReceipt: result.executionReceipt,
    trustState: canonicalPersistedTrustState({
      trustState: result.executableArtifact?.trustState,
      answerTier: result.answerTier,
    }),
    answerTier: result.answerTier,
  });
  return {
    columns: canonical.columns,
    rows: canonical.rows,
    rowCount: canonical.rowCount,
    resultFingerprint: canonical.resultFingerprint,
    executionTime: canonical.executionTime ?? 0,
    ...(canonical.truncated ? { truncated: true } : {}),
    ...(canonical.executionReceipt ? { executionReceipt: canonical.executionReceipt } : {}),
    ...(canonical.trustState ? { trustState: canonical.trustState } : {}),
    ...(canonical.answerTier ? { answerTier: canonical.answerTier } : {}),
  };
}

function notebookResearchSummary(
  question: string,
  result: ReturnType<typeof normalizeQueryResult> | undefined,
  error: string | undefined,
): string {
  if (error) return `Research could not preview results for "${question}". ${error}`;
  if (result) {
    const rowCount = result.rowCount ?? result.rows.length;
    return `Research preview for "${question}" returned ${rowCount.toLocaleString()} row${rowCount === 1 ? '' : 's'} across ${result.columns.length.toLocaleString()} column${result.columns.length === 1 ? '' : 's'}.`;
  }
  return `Research plan created for "${question}". Add or generate SQL, then run a bounded preview.`;
}

/**
 * Persisted Research children are deliberately narrated without another model
 * call after a frozen Ask plan has returned rows.  This keeps the branch inside
 * its fair-share deadline and makes the stored finding a direct consequence of
 * its execution receipt rather than an unbounded second interpretation pass.
 */
function deterministicResearchBranchSummary(input: {
  question: string;
  result: ReturnType<typeof normalizeQueryResult>;
  executionReceipt?: DqlArtifactExecutionReceipt;
  analyticalNarrative?: AgentAnswer['analyticalNarrative'];
}): string {
  const factNarrative = notebookResearchString(input.analyticalNarrative?.text);
  const fallback = notebookResearchSummary(input.question, input.result, undefined);
  const receiptKind = input.executionReceipt?.resultFingerprint
    ? 'receipt-bound'
    : 'execution-fingerprint-bound';
  return `${factNarrative ?? fallback} This ${receiptKind} Research branch was retained for synthesis without a follow-up provider narration.`;
}

function recordNotebookQueryRun(projectRoot: string, input: {
  notebookPath: string;
  cellId?: string;
  cellName?: string;
  researchRunId?: string;
  source: string;
  status: string;
  rowCount?: number;
  durationMs?: number;
  errorCode?: string;
  sql?: string;
  contextPackId?: string;
  objectKey?: string;
}): void {
  try {
    recordQueryRun(projectRoot, {
      objectKey: input.objectKey,
      source: input.source,
      status: input.status,
      rowCount: input.rowCount,
      durationMs: input.durationMs,
      errorCode: input.errorCode,
      payload: {
        notebookPath: input.notebookPath,
        cellId: input.cellId,
        cellName: input.cellName,
        researchRunId: input.researchRunId,
        contextPackId: input.contextPackId,
        sql: input.sql ? compactSqlForRunHistory(input.sql) : undefined,
      },
    });
  } catch {
    // Query history is advisory metadata and must not block notebook execution.
  }
}

function updateNotebookResearchFromCellExecution(
  projectRoot: string,
  execContext: NotebookExecutionContextInput,
  input: {
    status: 'success' | 'error';
    resultPreview?: ReturnType<typeof normalizeQueryResult>;
    error?: string;
    sql?: string;
  },
): void {
  if (!execContext.notebookPath || (!execContext.cellId && !execContext.researchRunId)) return;
  const storage = new LocalNotebookResearchStorage(defaultNotebookResearchDbPath(projectRoot));
  try {
    const page = storage.listRunsPage({
      notebookPath: execContext.notebookPath,
      sort: 'updated_desc',
      limit: 500,
    });
    const matches = page.runs.filter((run) => {
      if (execContext.researchRunId && run.id === execContext.researchRunId) return true;
      return Boolean(execContext.cellId && run.sourceCellId === execContext.cellId);
    });
    const now = new Date().toISOString();
    for (const run of matches.slice(0, 20)) {
      if (input.status === 'success') {
        storage.updateRun(run.id, {
          status: 'ready',
          resultPreview: input.resultPreview,
          summary: notebookResearchSummary(run.question, input.resultPreview, undefined),
          recommendation: run.recommendation ?? 'Review SQL, metadata evidence, grain, filters, and duplicate matches before DQL draft promotion.',
          error: '',
          lastRunAt: now,
        });
      } else {
        storage.updateRun(run.id, {
          status: 'error',
          error: input.error,
          summary: notebookResearchSummary(run.question, undefined, input.error),
          lastRunAt: now,
        });
      }
    }
  } catch {
    // Research run sync is advisory metadata and must not block notebook execution.
  } finally {
    storage.close();
  }
}

function compactSqlForRunHistory(sql: string): string {
  const clean = sql.replace(/\s+/g, ' ').trim();
  return clean.length > 1200 ? `${clean.slice(0, 1197)}...` : clean;
}

/**
 * Compile the intentionally tiny physical subset that the authoritative Ask
 * runtime has already proved without a provider: one qualified relation and a
 * projection of selected, qualified columns. This is not a general text-to-SQL
 * fallback. Filters, joins, grain transforms, rankings, and derived
 * aggregations remain on their existing compiler/agent paths because a local
 * projection must not invent any of those semantics.
 *
 * The SQL still enters the normal exploratory closure validator and one-shot
 * execution-capability gate. Returning undefined means the caller must use the
 * ordinary bounded provider path instead of widening this compiler.
 */
function deterministicExploratoryProposalFromRuntime(
  routeDecision: IntentDecision | undefined,
): { sql: string; summary: string; suggestedViz: string } | undefined {
  const runtime = routeDecision?.askAnalystDecision;
  const state = runtime?.state;
  const plan = routeDecision?.resolvedAnalyticalPlan;
  const cascade = routeDecision?.analyticalCascadeDecision;
  if (
    runtime?.mode !== 'authoritative'
    || !state
    || state.resolvedPlan?.compiler !== 'exploratory_sql'
    || !plan
    || plan.mode !== 'authoritative'
    || plan.capability !== 'bounded_exploration'
    || cascade?.selectedTier !== 'exploratory_sql'
    || cascade.planFrozen !== true
  ) return undefined;

  // This receipt is minted only by AskAnalystRuntimeV1 after its strict
  // same-relation, every-field binding check. Canonical-ID and provider-backed
  // selections deliberately remain on their own compilers.
  // Task-local execution states are produced before the final root receipt
  // appends the human-readable planner tool. Their typed planning receipt is
  // nevertheless immutable, and is the authoritative signal for a
  // provider-free single-relation physical program. Prefer it, retaining the
  // V1 tool receipt as a backwards-compatible fallback for persisted runs.
  const v3State = state.version === 3 ? state : undefined;
  const hasDeterministicPlanningReceipt = v3State?.planningMode === 'deterministic_binding'
    && v3State.planningReceipt?.mode === 'deterministic_binding'
    && v3State.planningReceipt.plannerCalls === 0
    && v3State.planningReceipt.verification.status === 'valid';
  const hasLegacyDeterministicReceipt = state.workspace.tools.some((tool) =>
    tool.kind === 'provider_meaning'
      && tool.status === 'skipped'
      && tool.reasonCode === 'deterministic_single_relation_physical_binding');
  const deterministicBinding = hasDeterministicPlanningReceipt || hasLegacyDeterministicReceipt;
  if (!deterministicBinding) return undefined;

  const program = state.program;
  if (
    program.filters.length > 0
    || Boolean(program.ranking)
    || Boolean(program.time)
    || program.comparison?.kind && program.comparison.kind !== 'none'
    || program.relationshipRequirements.length > 0
  ) return undefined;
  const relations = plan.sourceRelationIds ?? [];
  if (relations.length !== 1 || !isSafeQualifiedPhysicalIdentifier(relations[0])) return undefined;

  const selectedColumns = (routeDecision?.meaningResolution?.selectedConceptIds ?? [])
    .map(deterministicPhysicalColumnName)
    .filter((column): column is string => Boolean(column));
  const columns = [...new Set(selectedColumns)];
  if (columns.length === 0 || columns.some((column) => !isSafePhysicalIdentifier(column))) return undefined;

  const requirements = state.frame.requirements;
  const requiredTerms = [
    ...requirements.measures,
    ...requirements.dimensions,
    ...requirements.entityTerms,
    ...requirements.entityDisplayTerms,
  ];
  if (requiredTerms.length === 0 || !requiredTerms.every((term) =>
    columns.some((column) => deterministicPhysicalTermMatchesColumn(term, column)))) return undefined;

  // Keep human-readable entity/display columns ahead of stored metric columns.
  // This is presentation only; the immutable selected IDs retain authority.
  const measureColumns = columns.filter((column) => requirements.measures.some((term) =>
    deterministicPhysicalTermMatchesColumn(term, column)));
  const dimensionColumns = columns.filter((column) => !measureColumns.includes(column));
  const projection = [...dimensionColumns, ...measureColumns];
  if (projection.length !== columns.length) return undefined;
  const quote = (identifier: string) => `"${identifier.replaceAll('"', '""')}"`;
  const sql = `SELECT ${projection.map(quote).join(', ')} FROM ${relations[0]!.split('.').map(quote).join('.')}`;
  return {
    sql,
    summary: 'Executed the frozen, single-relation physical projection. This answer is review-required because it was compiled from qualified raw metadata rather than a certified block or semantic metric.',
    suggestedViz: 'table',
  };
}

function deterministicPhysicalColumnName(candidateId: string): string | undefined {
  const normalized = candidateId.trim();
  if (!normalized.startsWith('dbt:column:')) return undefined;
  const identity = normalized.slice('dbt:column:'.length);
  const column = identity.slice(identity.lastIndexOf('.') + 1).trim();
  return column || undefined;
}

function isSafePhysicalIdentifier(value: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_$]*$/.test(value);
}

function isSafeQualifiedPhysicalIdentifier(value: string): boolean {
  const parts = value.split('.').map((part) => part.trim());
  return parts.length > 0 && parts.every(isSafePhysicalIdentifier);
}

function deterministicPhysicalTermMatchesColumn(term: string, column: string): boolean {
  const tokens = (value: string) => value.toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .map((token) => token.endsWith('s') && token.length > 3 ? token.slice(0, -1) : token);
  const termTokens = tokens(term);
  const columnTokens = new Set(tokens(column));
  return termTokens.length > 0 && termTokens.every((token) => columnTokens.has(token));
}

function buildAgentSchemaContextFromContextPack(
  question: string,
  contextPack: LocalContextPack,
  options: { includeUnscored?: boolean; limit?: number } = {},
): AgentSchemaTable[] {
  const byRelation = new Map<string, AgentSchemaTable>();
  const objectsByKey = new Map(contextPack.objects.map((object) => [object.objectKey, object]));

  const boundColumns = (
    columns: AgentSchemaTable['columns'],
    declared: AgentSchemaTable['columnCompleteness'],
  ) => boundAgentSchemaColumns(columns, declared, dedupeAgentSchemaColumns);
  const upsert = (table: AgentSchemaTable) => {
    if (!table.relation || !table.name) return;
    const key = table.relation.toLowerCase();
    const existing = byRelation.get(key);
    if (!existing) {
      byRelation.set(key, { ...table, ...boundColumns(table.columns, table.columnCompleteness) });
      return;
    }
    const mergedCompleteness = mergeAgentSchemaCompleteness(existing.columnCompleteness, table.columnCompleteness);
    byRelation.set(key, {
      ...existing,
      description: existing.description ?? table.description,
      source: existing.source === table.source ? existing.source : 'local metadata catalog',
      ...boundColumns([...existing.columns, ...table.columns], mergedCompleteness),
    });
  };

  for (const object of contextPack.objects) {
    const table = metadataObjectToAgentSchemaTable(object);
    if (table) upsert(table);
  }

  for (const edge of contextPack.edges) {
    if (edge.edgeType !== 'maps_to_dbt_model' && edge.edgeType !== 'uses_dbt_model') continue;
    const from = objectsByKey.get(edge.fromKey);
    const to = objectsByKey.get(edge.toKey);
    const warehouse = from?.objectType === 'warehouse_table' ? from : null;
    const dbtModel = to && (to.objectType === 'dbt_model' || to.objectType === 'dbt_source') ? to : null;
    if (!warehouse || !dbtModel) continue;
    const warehouseTable = metadataObjectToAgentSchemaTable(warehouse);
    const modelTable = metadataObjectToAgentSchemaTable(dbtModel);
    if (!warehouseTable || !modelTable) continue;
    upsert({
      ...warehouseTable,
      description: warehouseTable.description ?? modelTable.description,
      columns: modelTable.columns,
      source: 'local metadata catalog',
    });
  }

  const tokens = agentSchemaTokens(question);
  const shouldProbeValues = extractAgentValueSearchTerms(question).length > 0;
  return Array.from(byRelation.values())
    .map((table) => ({
      table,
      score: scoreAgentSchemaTable(table, tokens) + (shouldProbeValues ? scoreAgentValueProbeTable(table) : 0),
    }))
    .filter((entry) => entry.table.columns.length > 0 && (options.includeUnscored || entry.score > 0))
    .sort((a, b) => b.score - a.score || a.table.relation.localeCompare(b.table.relation))
    .slice(0, Math.max(1, options.limit ?? 12))
    .map((entry) => entry.table);
}

/**
 * Exact frozen certified execution needs the physical relation closure from
 * the same source snapshot, not only the twelve tables that happened to rank
 * for the natural-language prompt.  An artifact may project `category` while
 * its authored SQL says `FROM order_items`, so prompt relevance alone is not
 * a safe authority to remove that relation from the execution handoff.
 *
 * This remains deliberately narrower than an exploratory repair: it exposes
 * only snapshot-indexed dbt models plus the already retrieved local objects.
 * `qualifyUnambiguousSqlRelationsFromSchema` still changes a leaf only when
 * exactly one physical relation in that closure owns it.  Duplicate leaves
 * therefore remain a same-tier certified failure rather than a guessed bind.
 */
function buildFrozenCertifiedSchemaContext(
  contextPack: LocalContextPack | undefined,
  manifest: DQLManifest,
): AgentSchemaTable[] {
  const byRelation = new Map<string, AgentSchemaTable>();
  const upsert = (table: AgentSchemaTable) => {
    if (!table.relation || !table.name) return;
    const key = table.relation.toLowerCase();
    const existing = byRelation.get(key);
    if (!existing) {
      byRelation.set(key, {
        ...table,
        columns: dedupeAgentSchemaColumns(table.columns).slice(0, 80),
      });
      return;
    }
    byRelation.set(key, {
      ...existing,
      description: existing.description ?? table.description,
      source: existing.source === table.source ? existing.source : 'local metadata catalog',
      columns: dedupeAgentSchemaColumns([...existing.columns, ...table.columns]).slice(0, 80),
    });
  };

  if (contextPack) {
    for (const object of contextPack.objects) {
      const table = metadataObjectToAgentSchemaTable(object);
      if (table) upsert(table);
    }
  }

  for (const model of manifest.dbtImport?.dbtDag?.models ?? []) {
    const relation = [model.database, model.schema, model.name].filter(Boolean).join('.');
    // A bare dbt identity does not prove a physical catalog/schema and must
    // not be promoted into a qualifier. It remains harmless context only.
    if (!relation || relation === model.name) continue;
    upsert({
      relation,
      schema: model.schema,
      name: model.name,
      // A manifest lists the columns an author documented, not necessarily
      // every column the relation has.
      columnCompleteness: 'partial',
      description: model.description,
      columns: (model.columns ?? []).map((column) => ({
        name: column.name,
        type: column.type,
        description: column.description,
      })),
      source: 'local metadata catalog',
    });
  }

  return Array.from(byRelation.values())
    .filter((table) => table.columns.length > 0)
    .sort((left, right) => left.relation.localeCompare(right.relation));
}

function metadataObjectToAgentSchemaTable(object: MetadataObject): AgentSchemaTable | null {
  if (object.objectType === 'dbt_column' || object.objectType === 'runtime_column') {
    const relation = metadataPayloadString(object, 'relation');
    const model = metadataPayloadString(object, 'model') ?? relation;
    if (!model) return null;
    return {
      relation: relation ?? model,
      schema: relation ? relation.split('.').slice(-2, -1)[0] : undefined,
      name: relation ? relation.split('.').at(-1) ?? model : model,
      source: 'local metadata catalog',
      // One column object is one column of a relation, never the relation's
      // whole column list — say so, or the merge below inherits a false claim.
      columnCompleteness: 'partial',
      columns: [{
        name: object.name,
        type: metadataPayloadString(object, 'type'),
        description: object.description,
      }],
    };
  }

  if (object.objectType !== 'dbt_model' && object.objectType !== 'dbt_source' && object.objectType !== 'warehouse_table' && object.objectType !== 'runtime_table') {
    return null;
  }

  const relation = metadataObjectRelation(object);
  if (!relation) return null;
  const relationParts = relation.split('.').filter(Boolean);
  const schema = metadataPayloadString(object, 'schema') ?? (relationParts.length >= 2 ? relationParts[relationParts.length - 2] : undefined);
  const name = relationParts.at(-1) ?? object.name;
  const columns = metadataObjectColumns(object);
  // The catalog knows whether it holds every column of this relation. Dropping
  // that on the way into the schema context let a bounded projection be read as
  // proof, and the SQL gate then rejected real columns it had never been shown.
  const declaredCompleteness = metadataPayloadString(object, 'columnCompleteness');
  // Unknown is not complete: a gate may only trust a list the catalog vouched for.
  const columnCompleteness: AgentSchemaTable['columnCompleteness'] = declaredCompleteness === 'complete' ? 'complete' : 'partial';
  return {
    relation,
    schema,
    name,
    description: object.description,
    columns,
    source: 'local metadata catalog',
    columnCompleteness,
  };
}

function metadataObjectRelation(object: MetadataObject): string | undefined {
  const relation = metadataPayloadString(object, 'relation');
  if (relation) return relation;
  const database = metadataPayloadString(object, 'database');
  const schema = metadataPayloadString(object, 'schema');
  if (database && schema) return [database, schema, object.name].join('.');
  return object.fullName ?? object.name;
}

function metadataObjectColumns(object: MetadataObject): AgentSchemaTable['columns'] {
  const columns = object.payload?.columns;
  if (!Array.isArray(columns)) return [];
  return columns.flatMap((column) => {
    if (!column || typeof column !== 'object') return [];
    const record = column as Record<string, unknown>;
    const name = stringFromRecord(record, 'name') ?? stringFromRecord(record, 'column_name');
    if (!name) return [];
    return [{
      name,
      type: stringFromRecord(record, 'type') ?? stringFromRecord(record, 'data_type'),
      description: stringFromRecord(record, 'description'),
    }];
  });
}

function metadataPayloadString(object: MetadataObject, key: string): string | undefined {
  const value = object.payload?.[key];
  return typeof value === 'string' && value.trim() ? value.trim() : undefined;
}

function dedupeAgentSchemaColumns(columns: AgentSchemaTable['columns']): AgentSchemaTable['columns'] {
  const byName = new Map<string, AgentSchemaTable['columns'][number]>();
  for (const column of columns) {
    const key = column.name.toLowerCase();
    const existing = byName.get(key);
    byName.set(key, existing ? {
      ...existing,
      type: existing.type ?? column.type,
      description: existing.description ?? column.description,
      sampleValues: uniqueStrings([...(existing.sampleValues ?? []), ...(column.sampleValues ?? [])]).slice(0, 5),
    } : column);
  }
  return Array.from(byName.values());
}

export function buildAgentSchemaContext(
  question: string,
  rows: unknown[],
  options: { includeUnscored?: boolean; limit?: number } = {},
): AgentSchemaTable[] {
  const byRelation = new Map<string, AgentSchemaTable>();
  for (const row of rows) {
    if (!row || typeof row !== 'object') continue;
    const record = row as Record<string, unknown>;
    const schema = stringFromRecord(record, 'table_schema');
    const table = stringFromRecord(record, 'table_name');
    const column = stringFromRecord(record, 'column_name');
    if (!schema || !table || !column) continue;
    const relation = `${schema}.${table}`;
    const current = byRelation.get(relation) ?? {
      relation,
      schema,
      name: table,
      source: 'runtime information_schema',
      columns: [],
      columnCompleteness: 'complete' as const,
    };
    if (current.columns.length < 80) {
      current.columns.push({
        name: column,
        type: stringFromRecord(record, 'data_type'),
      });
    } else {
      // The cap is for the prompt; the gate must know a column was left out.
      current.columnCompleteness = 'partial';
    }
    byRelation.set(relation, current);
  }
  const tokens = agentSchemaTokens(question);
  const shouldProbeValues = extractAgentValueSearchTerms(question).length > 0;
  const limit = Math.max(1, Math.trunc(options.limit ?? 12));
  return Array.from(byRelation.values())
    .map((table) => ({
      table,
      score: scoreAgentSchemaTable(table, tokens) + (shouldProbeValues ? scoreAgentValueProbeTable(table) : 0),
    }))
    .filter((entry) => options.includeUnscored || entry.score > 0)
    .sort((a, b) => b.score - a.score || a.table.relation.localeCompare(b.table.relation))
    .slice(0, limit)
    .map((entry) => entry.table);
}

const RUNTIME_SCHEMA_SEARCH_STOPWORDS = new Set([
  'what', 'which', 'where', 'when', 'who', 'why', 'how', 'show', 'give', 'find',
  'from', 'with', 'without', 'this', 'that', 'these', 'those', 'current', 'today',
  'yesterday', 'last', 'year', 'month', 'week', 'day', 'top', 'bottom', 'their',
  'have', 'does', 'into', 'than', 'then', 'also', 'all', 'the', 'and', 'for',
]);

/**
 * Physical catalog evidence fallback. This is deliberately question-scoped and
 * result-bounded: dbt/DQL metadata remains the planning authority, while
 * information_schema confirms discoverable relations/columns in the selected
 * execution target. Tokens are reduced to safe identifier characters before
 * interpolation, so user text cannot become SQL syntax.
 */
/**
 * A dbt model's columns completed from the warehouse.
 *
 * dbt only knows the columns a project documented, or all of them after
 * `dbt docs generate` writes catalog.json. Without that, a model can show no
 * columns at all and the relationship builder cannot offer a key. The
 * warehouse's own `information_schema` rows fill the gap: documented columns
 * keep their dbt descriptions and tests, the rest are added in table order.
 */
export function mergeWarehouseColumns(
  detail: DbtNodeAuthoringDetail,
  rows: Array<Record<string, unknown>>,
): DbtNodeAuthoringDetail {
  const table = detail.relation?.replace(/["`\[\]]/g, '').split('.').filter(Boolean).at(-1)?.toLowerCase();
  if (!table) return detail;
  const value = (row: Record<string, unknown>, key: string): string | undefined => {
    const found = row[key] ?? row[key.toUpperCase()];
    return typeof found === 'string' && found ? found : undefined;
  };
  const known = new Map(detail.columns.map((column) => [column.name.toLowerCase(), column]));
  const columns: DbtNodeAuthoringDetail['columns'] = [];
  const seen = new Set<string>();
  for (const row of rows) {
    const name = value(row, 'column_name');
    if (!name || value(row, 'table_name')?.toLowerCase() !== table || seen.has(name.toLowerCase())) continue;
    seen.add(name.toLowerCase());
    const documented = known.get(name.toLowerCase());
    columns.push(documented ? { ...documented, type: documented.type ?? value(row, 'data_type') } : { name, type: value(row, 'data_type'), tests: [] });
  }
  // A documented column the warehouse did not return stays: dbt may describe a column the query could not see.
  for (const column of detail.columns) if (!seen.has(column.name.toLowerCase())) columns.push(column);
  return columns.length > detail.columns.length || columns.some((column, index) => column.type !== detail.columns[index]?.type)
    ? { ...detail, columns }
    : detail;
}

/**
 * Point-lookup of NAMED relations in `information_schema.columns`.
 *
 * This is deliberately not `buildRuntimeSchemaSearchSql`. That one matches
 * `LOWER(table_name) LIKE '%term%'` across every visible schema, which is the
 * unbounded rescan the "a lexical miss is not permission to rescan" policy
 * exists to prevent. This one asks about specific `(schema, table)` pairs the
 * model actually referenced, with equality predicates — a metadata point
 * lookup, not a scan.
 *
 * Returns null when nothing safe to ask about survives normalization.
 */
export function buildNamedRelationProbeSql(relations: string[], maxRelations = 4): string | null {
  const predicates: string[] = [];
  const seen = new Set<string>();
  for (const raw of relations) {
    const parts = raw.replace(/["`\[\]]/g, '').trim().split('.').filter(Boolean);
    const table = parts.at(-1);
    // Identifiers only — never interpolate anything that could carry SQL.
    if (!table || !/^[A-Za-z_][A-Za-z0-9_$]*$/.test(table)) continue;
    const schema = parts.length >= 2 ? parts.at(-2) : undefined;
    if (schema && !/^[A-Za-z_][A-Za-z0-9_$]*$/.test(schema)) continue;
    const key = `${schema ?? ''}.${table}`.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    predicates.push(schema
      ? `(LOWER(table_schema) = '${schema.toLowerCase()}' AND LOWER(table_name) = '${table.toLowerCase()}')`
      : `(LOWER(table_name) = '${table.toLowerCase()}')`);
    if (predicates.length >= maxRelations) break;
  }
  if (predicates.length === 0) return null;
  return `SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE UPPER(table_schema) NOT IN ('INFORMATION_SCHEMA', 'PG_CATALOG')
  AND (
${predicates.map((predicate) => `    ${predicate}`).join(' OR\n')}
  )
ORDER BY table_schema, table_name, ordinal_position
LIMIT 400`;
}

/**
 * Conservative fallback for deciding whether an unparsed statement still
 * needs DQL's structural join validation. Join-free SELECT syntax may be
 * newer than the local parser and can safely continue to the read-only
 * warehouse boundary; an unparsed join must never bypass relationship proof.
 */
export function sqlMayContainJoin(sql: string): boolean {
  const normalized = stripSqlStringsAndComments(sql)
    .replace(/\s+/g, ' ')
    .trim();
  if (/\bjoin\b/i.test(normalized)) return true;

  const fromMatch = /\bfrom\b/i.exec(normalized);
  if (!fromMatch) return false;
  const tail = normalized.slice(fromMatch.index + fromMatch[0].length);
  const clauseMatch = /\b(where|group\s+by|having|qualify|order\s+by|limit|fetch|union|intersect|except)\b/i.exec(tail);
  const fromClause = clauseMatch ? tail.slice(0, clauseMatch.index) : tail;

  let depth = 0;
  for (const char of fromClause) {
    if (char === '(') depth += 1;
    else if (char === ')') depth = Math.max(0, depth - 1);
    else if (char === ',' && depth === 0) return true;
  }
  return false;
}

/**
 * Resolve a BARE internal graph identity (`source::orders` — a name with no
 * database or schema) against the warehouse.
 *
 * A qualified identity decodes mechanically, but a bare one carries no
 * location, so the old behaviour was to reject the cell and hand the user an
 * "Ask AI to fix" button. That was an LLM round trip for a lookup: the name is
 * unambiguous whenever exactly one relation in the connection answers to it.
 * Probe for it, and only refuse when the answer is genuinely zero or many —
 * at which point the refusal can say which it was.
 *
 * Runs ONLY after a decode has already failed, so the happy path pays nothing.
 */
export async function resolveBareInternalRelationIds(
  sql: string,
  executor: QueryExecutor,
  connection: ConnectionConfig,
): Promise<{ sql: string; resolved: Array<{ from: string; to: string }>; ambiguous: string[] }> {
  const bare = internalRelationIdsInSql(stripSqlStringsAndComments(sql))
    .filter((id) => !id.slice(id.indexOf('::') + 2).includes('.'));
  if (bare.length === 0) return { sql, resolved: [], ambiguous: [] };

  const names = bare.map((id) => id.slice(id.indexOf('::') + 2));
  const probeSql = buildNamedRelationProbeSql(names);
  if (!probeSql) return { sql, resolved: [], ambiguous: [] };

  let rows: Array<Record<string, unknown>> = [];
  try {
    const probe = await executor.executeQuery(probeSql, [], {}, connection);
    rows = (probe?.rows ?? []) as Array<Record<string, unknown>>;
  } catch {
    // The probe is best-effort. A warehouse that cannot answer it leaves the
    // identity unresolved, which is the same outcome as not probing at all.
    return { sql, resolved: [], ambiguous: [] };
  }

  const resolved: Array<{ from: string; to: string }> = [];
  const ambiguous: string[] = [];
  let out = sql;
  for (const id of bare) {
    const name = id.slice(id.indexOf('::') + 2).toLowerCase();
    const matches = new Set(
      rows
        .filter((row) => String(row.table_name ?? '').toLowerCase() === name)
        .map((row) => `${String(row.table_schema ?? '')}.${String(row.table_name ?? '')}`),
    );
    if (matches.size !== 1) {
      if (matches.size > 1) ambiguous.push(id);
      continue;
    }
    const target = [...matches][0]!;
    const idPattern = id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    out = out.replace(new RegExp(`\\b${idPattern}`, 'g'), target);
    resolved.push({ from: id, to: target });
  }
  return { sql: out, resolved, ambiguous };
}

export function buildRuntimeSchemaSearchSql(question: string): string {
  const terms = Array.from(agentSchemaTokens(question))
    .map((term) => term.toLowerCase().replace(/[^a-z0-9_]/g, ''))
    .filter((term) => term.length >= 3 && !RUNTIME_SCHEMA_SEARCH_STOPWORDS.has(term))
    .slice(0, 8);
  const predicate = terms.length > 0
    ? `\n  AND (\n${terms.map((term) =>
        `    LOWER(table_name) LIKE '%${term}%' OR LOWER(column_name) LIKE '%${term}%'`,
      ).join(' OR\n')}\n  )`
    : '';
  return `SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE UPPER(table_schema) NOT IN ('INFORMATION_SCHEMA', 'PG_CATALOG')${predicate}
ORDER BY table_schema, table_name, ordinal_position
LIMIT 600`;
}

function mergeAgentSchemaContexts(...contexts: AgentSchemaTable[][]): AgentSchemaTable[] {
  const byRelation = new Map<string, AgentSchemaTable>();
  for (const table of contexts.flat()) {
    const key = table.relation.toLowerCase();
    const existing = byRelation.get(key);
    if (!existing) {
      byRelation.set(key, {
        ...table,
        columns: dedupeAgentSchemaColumns(table.columns).slice(0, 80),
      });
      continue;
    }
    byRelation.set(key, {
      ...existing,
      description: existing.description ?? table.description,
      source: existing.source === table.source ? existing.source : 'catalog and runtime schema',
      columns: dedupeAgentSchemaColumns([...existing.columns, ...table.columns]).slice(0, 80),
    });
  }
  return Array.from(byRelation.values()).slice(0, 16);
}

function agentRelationMatchKey(relation: string): string {
  return relation
    .replace(/["`\[\]]/g, '')
    .split('.')
    .filter(Boolean)
    .slice(-2)
    .join('.')
    .toLowerCase();
}

/**
 * Keep dbt descriptions and semantic meaning, but make a complete live point
 * lookup authoritative for executable column names on the selected connection.
 * No fuzzy aliases are invented: a stale `customer_name` declaration disappears
 * when the live relation exposes only `name`.
 */
export function reconcileAgentSchemaContextWithLive(
  catalog: AgentSchemaTable[],
  live: AgentSchemaTable[],
): AgentSchemaTable[] {
  const liveByRelation = new Map(
    live
      .filter((table) => table.columns.length > 0)
      .map((table) => [agentRelationMatchKey(table.relation), table] as const),
  );
  return catalog.map((table) => {
    const verified = liveByRelation.get(agentRelationMatchKey(table.relation));
    if (!verified) return table;
    const metadataColumns = new Map(table.columns.map((column) => [column.name.toLowerCase(), column] as const));
    return {
      ...table,
      source: 'dbt metadata verified against live runtime schema',
      columnCompleteness: 'complete',
      columns: verified.columns.map((column) => {
        const metadata = metadataColumns.get(column.name.toLowerCase());
        return {
          ...column,
          type: column.type ?? metadata?.type,
          description: metadata?.description,
          sampleValues: metadata?.sampleValues,
        };
      }),
    };
  });
}

function mergeAgentSchemaSampleValues(snapshot: AgentSchemaTable[], enriched: AgentSchemaTable[]): AgentSchemaTable[] {
  const samples = new Map<string, string[]>();
  for (const table of enriched) {
    for (const column of table.columns) {
      if (!column.sampleValues?.length) continue;
      samples.set(`${table.relation.toLowerCase()}\u0000${column.name.toLowerCase()}`, column.sampleValues);
    }
  }
  if (samples.size === 0) return snapshot;
  return snapshot.map((table) => ({
    ...table,
    columns: table.columns.map((column) => {
      const sampleValues = samples.get(`${table.relation.toLowerCase()}\u0000${column.name.toLowerCase()}`);
      return sampleValues?.length
        ? { ...column, sampleValues: uniqueStrings([...(column.sampleValues ?? []), ...sampleValues]).slice(0, 8) }
        : column;
    }),
  }));
}

// Common English plurals that are NOT entity nouns, so a multi-entity heuristic
// doesn't count them. Domain-agnostic (no project-specific vocabulary).
const NON_ENTITY_PLURALS = new Set([
  'details', 'values', 'results', 'rows', 'numbers', 'records', 'items', 'things',
  'totals', 'amounts', 'metrics', 'columns', 'fields', 'names', 'ids',
]);

/**
 * Decide whether to run the (advisory, best-effort) runtime value-scan + schema
 * enrichment for a question. Generic multi-entity / detail intent — no hard-coded
 * project vocabulary — so it fires for ANY repo's join-shaped questions, not just
 * jaffle. Over-triggering only costs a few extra bounded probes (all in try/catch).
 */
export function shouldAugmentAgentRuntimeSchema(
  question: string,
  questionPlan?: {
    entities?: Array<string | { text?: string; typeHint?: string }>;
    metricTerms?: string[];
    dimensionTerms?: string[];
  },
): boolean {
  const lower = question.toLowerCase();
  const wantsMetric = /\brevenu|\bsales\b|\bamount\b|\bspend\b|\bcost\b|\bcount\b|\btotal\b|\bsum\b|\bavg\b|\baverage\b|\bvalue\b|\bprice\b/.test(lower);
  const wantsDetail = /\bdetails?\b|\bcomplete\b|\bbreakdown\b|\ball\s+values?\b|\beach\b|\bevery\b/.test(lower);
  const referencesPriorRows = /\b(?:above|previous|prior|these|those|same)\s+\w+/.test(lower);
  const explicitJoin = /\bjoin(?:ed|ing)?\b|\bcombine[ds]?\b|\bcross[- ]?reference\b|\balong\s+with\b|\btogether\s+with\b/.test(lower);
  // Multi-entity intent: a linking word + >= 2 distinct plural content nouns.
  const nouns = new Set((lower.match(/\b[a-z]{4,}s\b/g) ?? []).filter((word) => !NON_ENTITY_PLURALS.has(word)));
  const multiEntity = /\b(?:and|with|plus|per|for\s+each|by)\b/.test(lower) && nouns.size >= 2;
  const plannedConcepts = new Set([
    ...(questionPlan?.entities ?? []).map((entity) => typeof entity === 'string' ? entity : entity.typeHint ?? entity.text ?? ''),
    ...(questionPlan?.dimensionTerms ?? []),
  ].map((value) => value.trim().toLowerCase()).filter(Boolean));
  const plannedCompositeMetric = (questionPlan?.metricTerms?.length ?? 0) > 0 && plannedConcepts.size >= 2;
  return explicitJoin || referencesPriorRows || plannedCompositeMetric || (multiEntity && (wantsMetric || wantsDetail));
}

async function enrichAgentSchemaContextWithValueMatches(
  question: string,
  schemaContext: AgentSchemaTable[],
  executor: QueryExecutor,
  connection: ConnectionConfig,
  searchSafeColumns: ReadonlySet<string>,
): Promise<AgentSchemaTable[]> {
  const searchTerms = extractAgentValueSearchTerms(question);
  if (schemaContext.length === 0 || searchTerms.length === 0) return schemaContext;

  const matches = new Map<string, Map<string, string[]>>();
  const probes = rankAgentValueProbeColumns(schemaContext, searchSafeColumns).slice(0, 3).map(async (candidate) => {
    try {
      const result = await withAgentValueProbeTimeout(
        executor.executeQuery(
          buildAgentValueProbeSql(candidate.table, candidate.column.name, searchTerms, connection),
          [],
          runtimeVariables({}),
          connection,
        ),
        2_000,
      );
      const values = uniqueStrings(result.rows.flatMap(valueProbeRowValues)).slice(0, 25);
      return values.length > 0 ? { candidate, values } : undefined;
    } catch {
      // Value probes are advisory. Unsupported casts, privileges, and large-table
      // failures should not block the metadata-backed answer path.
      return undefined;
    }
  });
  for (const match of await Promise.all(probes)) {
    if (!match) continue;
    const tableMatches = matches.get(match.candidate.table.relation) ?? new Map<string, string[]>();
    tableMatches.set(match.candidate.column.name, match.values);
    matches.set(match.candidate.table.relation, tableMatches);
  }
  if (matches.size === 0) return schemaContext;

  return schemaContext.map((table) => {
    const tableMatches = matches.get(table.relation);
    if (!tableMatches) return table;
    return {
      ...table,
      columns: table.columns.map((column) => {
        const sampleValues = tableMatches.get(column.name);
        return sampleValues?.length
          ? { ...column, sampleValues: uniqueStrings([...(column.sampleValues ?? []), ...sampleValues]).slice(0, 25) }
          : column;
      }),
    };
  });
}

async function withAgentValueProbeTimeout<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<T>((_resolve, reject) => {
        timer = setTimeout(() => reject(new Error('VALUE_LOOKUP_TIMEOUT')), timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

function scoreAgentSchemaTable(table: AgentSchemaTable, tokens: Set<string>): number {
  let score = 0;
  const relationTokens = agentSchemaTokens(`${table.schema ?? ''} ${table.name} ${table.relation}`);
  for (const token of tokens) {
    if (relationTokens.has(token)) score += 8;
  }
  for (const column of table.columns) {
    const columnTokens = agentSchemaTokens(column.name);
    for (const token of tokens) {
      if (columnTokens.has(token)) score += 3;
    }
  }
  score += scoreCompositeAgentSchemaTable(table, tokens);
  // Small tiebreaker toward modeled analytics tables (fct_/dim_/fact_/mart_ …),
  // a warehouse-modeling convention that generalizes across repos — not a fixed
  // list of jaffle entity names.
  if (/^(?:fct|fact|dim|dimension|mart|rpt|report|agg|f|d)[_-]/i.test(table.name)
    || /(?:^|[_-])(?:fact|dim|mart|summary|report)(?:$|[_-])/i.test(table.name)) {
    score += 1;
  }
  return score;
}

const COMPOSITE_METRIC_TOKENS = new Set([
  'revenue', 'sales', 'amount', 'spend', 'price', 'cost', 'total', 'sum',
  'count', 'quantity', 'qty', 'value', 'subtotal', 'order', 'orders',
]);
const COMPOSITE_STOPWORD_TOKENS = new Set([
  'the', 'and', 'with', 'for', 'each', 'per', 'all', 'top', 'show', 'list',
  'give', 'get', 'find', 'plus', 'along', 'together', 'combined', 'combine',
  'detail', 'details', 'complete', 'breakdown', 'values', 'name', 'names',
  ...COMPOSITE_METRIC_TOKENS,
]);

/**
 * Boost the fact/junction table for a multi-entity ("composite") question. Fully
 * domain-agnostic: the ask is detected from >= 2 distinct entity tokens + a metric,
 * and the winning table is identified STRUCTURALLY (>= 2 foreign-key-style id columns
 * plus a numeric measure column) rather than by hard-coded jaffle table names — so it
 * ranks the right join table for any repo, while jaffle's fct_orders still qualifies.
 */
function scoreCompositeAgentSchemaTable(table: AgentSchemaTable, tokens: Set<string>): number {
  const entityTokens = [...tokens].filter((token) => token.length >= 3 && !COMPOSITE_STOPWORD_TOKENS.has(token));
  const hasMetric = [...tokens].some((token) => COMPOSITE_METRIC_TOKENS.has(token));
  const hasCompositeAsk = entityTokens.length >= 2 && hasMetric;
  const hasPriorRowsAsk = ['above', 'previous', 'prior', 'these', 'those', 'same'].some((token) => tokens.has(token))
    && entityTokens.length >= 1;
  if (!hasCompositeAsk && !hasPriorRowsAsk) return 0;

  const columns = table.columns.map((column) => column.name.toLowerCase());
  let score = 0;
  // Structural fact/junction-table signal: multiple FK-style id columns + a measure.
  const idColumnCount = columns.filter((name) => /(?:^id$|_id$|_key$|_sk$|_uuid$|_fk$)/.test(name)).length;
  const hasMeasureColumn = columns.some((name) =>
    /revenue|sales|amount|price|spend|cost|subtotal|total|quantity|\bqty\b|count|value/.test(name));
  if (idColumnCount >= 2 && hasMeasureColumn) score += 18;
  else if (idColumnCount >= 2) score += 8;
  if (hasMeasureColumn) score += 8;
  // Reward columns whose names overlap the question's actual entity tokens (any domain).
  for (const token of entityTokens) {
    if (columns.some((name) => name.includes(token))) score += 4;
  }
  return score;
}

function scoreAgentValueProbeTable(table: AgentSchemaTable): number {
  let score = 0;
  if (hasAgentSchemaToken(table.name, ['account', 'customer', 'member', 'order', 'product', 'sku', 'subscriber', 'user'])) score += 5;
  for (const column of table.columns) {
    if (!isAgentValueProbeColumn(column)) continue;
    score += 2;
    if (hasAgentSchemaToken(column.name, ['account', 'customer', 'email', 'full', 'member', 'name', 'product', 'sku', 'user'])) score += 2;
  }
  return Math.min(score, 18);
}

export interface AgentRuntimeValueGroundingPolicy {
  mode: 'disabled' | 'safe_automatic';
  searchSafeColumns: ReadonlySet<string>;
}

/**
 * Trace-only provenance for the two host-added catalog cards below. This is
 * not a planner hint or an execution capability: it explains why an exact
 * physical field was retained when ordinary fused ranking did not select it.
 */
export const AGENT_RUNTIME_VALUE_GROUNDING_PIN_REASON = 'host configured runtime value grounding pin';

/**
 * Resolve the project-admin boundary for live value lookup. An absent/malformed
 * policy is deliberately disabled; a broad table or wildcard cannot make an
 * unknown column search-safe.
 */
export function resolveAgentRuntimeValueGrounding(config: ProjectConfig): AgentRuntimeValueGroundingPolicy {
  const configured = config.agent?.runtimeValueGrounding;
  if (configured?.mode !== 'safe_automatic') {
    return { mode: 'disabled', searchSafeColumns: new Set<string>() };
  }
  const searchSafeColumns = new Set(
    (configured.searchSafeColumns ?? [])
      .map(normalizeAgentSafeColumnReference)
      // A bare `table.column` can name different objects in multiple schemas.
      // Literal probes require the operator to name the complete physical
      // relation plus column; this is an authorization boundary, not a
      // convenience matcher.
      .filter((value) => value.split('.').length >= 3 && !value.includes('*')),
  );
  return searchSafeColumns.size > 0
    ? { mode: 'safe_automatic', searchSafeColumns }
    : { mode: 'disabled', searchSafeColumns };
}

function normalizeAgentSafeColumnReference(value: string): string {
  return value.trim().replace(/[`"\[\]]/g, '').toLowerCase();
}

function isExplicitlySearchSafeAgentColumn(
  table: AgentSchemaTable,
  column: AgentSchemaTable['columns'][number],
  searchSafeColumns: ReadonlySet<string>,
): boolean {
  const qualified = normalizeAgentSafeColumnReference(`${table.relation}.${column.name}`);
  return searchSafeColumns.has(qualified);
}

/**
 * Preserve one explicitly configured physical categorical field in the Ask
 * evidence snapshot before the runtime applies its 32/16 role-balanced caps.
 *
 * A cold runtime-value index is not evidence that a literal is absent. The
 * host may therefore retain exactly one catalog column that an operator named
 * in `runtimeValueGrounding`, together with exactly one owning dbt relation.
 * It does not retain a semantic dimension as a value authority, infer a field
 * from the question, or broaden a configuration with multiple candidate
 * fields. The later exact value probe and relationship/compiler gates remain
 * the only ways this card can become a filter or executable plan.
 */
export function pinConfiguredRuntimeValueGroundingEvidence(input: {
  evidence: AgentRetrievalEvidence;
  question: string;
  policy: AgentRuntimeValueGroundingPolicy;
  catalogObjects: readonly MetadataObject[];
  /**
   * Ephemeral host token issued by the local server registry after this exact
   * catalog field was verified. It is opaque: relation/column authority stays
   * in the registry and the Ask runtime strips this token before projection.
   */
  literalProbeToken?: string;
}): AgentRetrievalEvidence {
  const literals = currentQuestionLiteralMemberTerms(input.question);
  if (input.policy.mode !== 'safe_automatic' || literals.length !== 1) return input.evidence;

  // There is no safe host choice between two configured physical fields. A
  // question literal alone cannot decide whether a project means city, sales
  // region, account segment, or another allowed categorical field.
  const configuredFields = [...input.policy.searchSafeColumns];
  if (configuredFields.length !== 1) return input.evidence;
  const configuredField = configuredFields[0]!;
  const separator = configuredField.lastIndexOf('.');
  if (separator <= 0 || separator === configuredField.length - 1) return input.evidence;
  const configuredRelation = configuredField.slice(0, separator);
  const configuredColumn = configuredField.slice(separator + 1);

  const exactRelation = (object: MetadataObject): string | undefined => {
    const relation = object.payload?.relation;
    return typeof relation === 'string' && relation.trim().length > 0
      ? relation.trim()
      : undefined;
  };
  const eligible = (object: MetadataObject): boolean => !/\b(?:deleted|disabled|archived|invalid|conflict)\b/i.test(object.status ?? '');
  const relationMatches = (relation: string | undefined): relation is string =>
    Boolean(relation) && normalizeAgentSafeColumnReference(relation!) === configuredRelation;

  // Limit authority to physical dbt catalog columns. An identically named
  // semantic dimension can describe the business concept but never proves a
  // warehouse value is safe to probe.
  const columns = input.catalogObjects.filter((object) => {
    if (object.objectType !== 'dbt_column' || !eligible(object)) return false;
    const relation = exactRelation(object);
    const dataType = typeof object.payload?.type === 'string' ? object.payload.type : undefined;
    return relationMatches(relation)
      && normalizeAgentSafeColumnReference(object.name) === configuredColumn
      && isAgentValueProbeColumn({ name: object.name, ...(dataType ? { type: dataType } : {}) });
  });
  if (columns.length !== 1) return input.evidence;
  const column = columns[0]!;
  const relation = exactRelation(column);
  if (!relation) return input.evidence;

  const owningRelations = input.catalogObjects.filter((object) =>
    (object.objectType === 'dbt_model' || object.objectType === 'dbt_source')
    && eligible(object)
    && relationMatches(exactRelation(object)));
  if (owningRelations.length !== 1) return input.evidence;
  const owner = owningRelations[0]!;
  const declaredOwner = typeof column.payload?.model === 'string' ? column.payload.model.trim() : '';
  if (declaredOwner && normalizeAgentSafeColumnReference(declaredOwner) !== normalizeAgentSafeColumnReference(owner.name)) {
    return input.evidence;
  }
  const literalProbeToken = input.literalProbeToken?.trim() || undefined;

  const cardFor = (object: MetadataObject, kind: AgentEvidenceCandidate['kind']): AgentEvidenceCandidate => {
    const dataType = typeof object.payload?.type === 'string' ? object.payload.type : undefined;
    return {
      id: object.objectKey,
      qualifiedId: object.fullName ?? object.objectKey,
      kind,
      trustTier: 'exploratory',
      name: object.name,
      ...(object.description ? { definition: object.description } : {}),
      ...(dataType ? { dataType } : {}),
      // Keep the exact configured physical relation, not a leaf/table guess.
      sourceObjects: [`dbt:relation:${relation}`],
      relevanceScore: 1,
      matchReasons: [AGENT_RUNTIME_VALUE_GROUNDING_PIN_REASON],
      compatibility: 'unknown',
      eligible: true,
      ...(kind === 'sql_column' && literalProbeToken ? { hostLiteralProbeToken: literalProbeToken } : {}),
    };
  };
  const pins = [
    cardFor(owner, owner.objectType === 'dbt_source' ? 'dbt_source' : 'dbt_model'),
    cardFor(column, 'sql_column'),
  ];
  // A weak runtime-schema card can share a friendly/qualified leaf with the
  // configured catalog column while omitting the exact physical relation
  // reference that `agentLiteralProbeTarget` requires. Treating that as the
  // pin already being present left the field visible in source coverage but
  // unreachable by the host-only probe. Deduplicate only a structurally
  // equivalent card: same kind/name and the one exact configured relation.
  // This cannot broaden authority because `relation`/`column` above were
  // already matched against the server-owned fully-qualified allowlist.
  const structurallyEquivalentPins = (pin: AgentEvidenceCandidate): AgentEvidenceCandidate[] =>
    input.evidence.candidates.filter((candidate) => {
      if (candidate.kind !== pin.kind
        || candidate.eligible === false
        || candidate.compatibility === 'incompatible'
        || normalizeAgentSafeColumnReference(candidate.name) !== normalizeAgentSafeColumnReference(pin.name)) return false;
      const references = (candidate.sourceObjects ?? [])
        .map((source) => /^(?:(?:runtime|dbt):relation|dbt:(?:model|source)|sql:table):(.+)$/i.exec(source.trim())?.[1])
        .filter((source): source is string => Boolean(source))
        .map(normalizeAgentSafeColumnReference);
      return references.length === 1 && references[0] === normalizeAgentSafeColumnReference(relation);
    });
  const matchingColumns = structurallyEquivalentPins(pins[1]!);
  const existingCandidates = matchingColumns.length > 0
    ? input.evidence.candidates.map((candidate) => matchingColumns.includes(candidate)
      ? literalProbeToken ? { ...candidate, hostLiteralProbeToken: literalProbeToken } : candidate
      : candidate)
    : input.evidence.candidates;
  const missing = pins.filter((candidate) => structurallyEquivalentPins(candidate).length === 0);
  if (missing.length === 0 && existingCandidates === input.evidence.candidates) return input.evidence;

  // Prepend so the lifecycle projection retains the explicit pin even when
  // the pre-existing fused snapshot already occupies its 80-card trace cap.
  // The Ask runtime still owns its independent 32-card workspace and 16-card
  // planner package caps.
  return {
    ...input.evidence,
    candidates: [...missing, ...existingCandidates],
  };
}

function rankAgentValueProbeColumns(
  schemaContext: AgentSchemaTable[],
  searchSafeColumns: ReadonlySet<string>,
): Array<{
  table: AgentSchemaTable;
  column: AgentSchemaTable['columns'][number];
  score: number;
}> {
  const ranked: Array<{
    table: AgentSchemaTable;
    column: AgentSchemaTable['columns'][number];
    score: number;
  }> = [];
  for (const table of schemaContext) {
    for (const column of table.columns) {
      if (!isAgentValueProbeColumn(column) || !isExplicitlySearchSafeAgentColumn(table, column, searchSafeColumns)) continue;
      ranked.push({
        table,
        column,
        score: scoreAgentValueProbeColumn(table, column),
      });
    }
  }
  return ranked.sort((a, b) => b.score - a.score || a.table.relation.localeCompare(b.table.relation) || a.column.name.localeCompare(b.column.name));
}

function scoreAgentValueProbeColumn(table: AgentSchemaTable, column: AgentSchemaTable['columns'][number]): number {
  let score = 0;
  if (hasAgentSchemaToken(table.name, ['account', 'customer', 'member', 'product', 'sku', 'subscriber', 'user'])) score += 4;
  if (hasAgentSchemaToken(column.name, ['full', 'name', 'email', 'account', 'customer', 'member', 'product', 'sku', 'subscriber', 'user'])) score += 8;
  if (hasAgentSchemaToken(column.name, ['id', 'key', 'code', 'number', 'status', 'segment', 'region', 'category', 'type'])) score += 3;
  return score;
}

export function isAgentValueProbeColumn(column: AgentSchemaTable['columns'][number]): boolean {
  // Delegates to the canonical predicate in dql-agent. Two copies of a security
  // rule drift, and the one that drifts is the one nobody is looking at.
  return isProbeSafeColumn({ name: column.name, ...(column.type ? { type: column.type } : {}) });
}

export function buildAgentValueProbeSql(
  table: AgentSchemaTable,
  column: string,
  searchTerms: string[],
  connection: ConnectionConfig,
): string {
  const relation = quoteAgentRelation(table.relation, connection);
  const identifier = quoteAgentIdentifier(column, connection);
  const castValue = `LOWER(CAST(${identifier} AS ${agentTextCastType(connection.driver)}))`;
  const predicates = uniqueStrings(searchTerms.flatMap((term) => {
    const normalized = term.toLowerCase().replace(/\s+/g, ' ').trim();
    const tokens = normalized.split(' ').filter((token) => token.length >= 4);
    return [
      `${castValue} = ${sqlStringLiteral(normalized)}`,
      ...tokens.slice(0, 2).map((token) => `${castValue} LIKE ${sqlStringLiteral(`${escapeSqlLike(token)}%`)} ESCAPE '\\'`),
    ];
  }))
    .slice(0, 8)
    .map((predicate) => predicate)
    .join(' OR ');
  return [
    `SELECT DISTINCT CAST(${identifier} AS ${agentTextCastType(connection.driver)}) AS value`,
    `FROM ${relation}`,
    `WHERE ${identifier} IS NOT NULL AND (${predicates})`,
    'LIMIT 25',
  ].join('\n');
}

/**
 * One host-owned literal check used only after the immutable Ask snapshot has
 * already selected a qualified physical column. Unlike the advisory value
 * search above, this returns no values: the caller learns only whether the
 * current literal exists exactly once on this approved field.
 */
/**
 * Case-insensitive existence probe that also returns the canonical stored
 * spelling, so a host-bound equality filter matches the warehouse casing
 * ("ronnie knight" typed, "Ronnie Knight" stored). LIMIT 2 detects two
 * distinct stored spellings — that is ambiguity, not proof.
 */
export function buildAgentCanonicalValueProbeSql(
  relation: string,
  column: string,
  literal: string,
  connection: ConnectionConfig,
): string {
  const normalized = literal.toLowerCase().replace(/\s+/g, ' ').trim();
  const quotedRelation = quoteAgentRelation(relation, connection);
  const identifier = quoteAgentIdentifier(column, connection);
  const castValue = `LOWER(CAST(${identifier} AS ${agentTextCastType(connection.driver)}))`;
  // Word-boundary containment in addition to equality: users name people
  // without honorifics ("Matthew Meyer" for the stored "Mr. Matthew Meyer").
  // DISTINCT + LIMIT 2 keeps this proof-grade — two stored values containing
  // the term is ambiguity and binds nothing.
  const exact = `${castValue} = ${sqlStringLiteral(normalized)}`;
  const wordSuffix = `${castValue} LIKE ${sqlStringLiteral(`% ${normalized}`)}`;
  const wordPrefix = `${castValue} LIKE ${sqlStringLiteral(`${normalized} %`)}`;
  const wordInner = `${castValue} LIKE ${sqlStringLiteral(`% ${normalized} %`)}`;
  return [
    `SELECT DISTINCT ${identifier} AS dql_literal_value`,
    `FROM ${quotedRelation}`,
    `WHERE ${identifier} IS NOT NULL AND (${exact} OR ${wordSuffix} OR ${wordPrefix} OR ${wordInner})`,
    'LIMIT 2',
  ].join('\n');
}

export function buildAgentExactValueProbeSql(
  table: AgentSchemaTable,
  column: string,
  literal: string,
  connection: ConnectionConfig,
): string {
  const normalized = literal.toLowerCase().replace(/\s+/g, ' ').trim();
  const relation = quoteAgentRelation(table.relation, connection);
  const identifier = quoteAgentIdentifier(column, connection);
  const castValue = `LOWER(CAST(${identifier} AS ${agentTextCastType(connection.driver)}))`;
  return [
    'SELECT 1 AS dql_literal_match',
    `FROM ${relation}`,
    `WHERE ${identifier} IS NOT NULL AND ${castValue} = ${sqlStringLiteral(normalized)}`,
    'LIMIT 1',
  ].join('\n');
}

/**
 * Resolve a planner-admitted raw field back to exactly one physical relation.
 * This deliberately accepts only explicit runtime/dbt relation references;
 * a semantic model name or a bare table leaf is not a warehouse target.
 */
export function agentLiteralProbeTarget(
  candidate: AgentEvidenceCandidate,
): { table: AgentSchemaTable; column: AgentSchemaTable['columns'][number] } | undefined {
  if (candidate.kind !== 'sql_column' || !candidate.qualifiedId?.trim()) return undefined;
  const references = uniqueStrings((candidate.sourceObjects ?? [])
    .map((source) => {
      const match = /^(?:(?:runtime|dbt):relation|dbt:(?:model|source)|sql:table):(.+)$/i.exec(source.trim());
      return match?.[1]?.trim() ?? '';
    })
    .filter(Boolean));
  if (references.length !== 1) return undefined;
  const column = candidate.name.trim();
  if (!column) return undefined;
  const relation = references[0]!;
  return {
    table: {
      relation,
      name: relation.split('.').filter(Boolean).at(-1) ?? relation,
      source: 'immutable Ask snapshot qualified physical relation',
      columns: [{ name: column, ...(candidate.dataType ? { type: candidate.dataType } : {}) }],
      columnCompleteness: 'partial',
    },
    column: { name: column, ...(candidate.dataType ? { type: candidate.dataType } : {}) },
  };
}

function agentTextCastType(driver?: string): string {
  switch (driver) {
    case 'bigquery':
      return 'STRING';
    case 'clickhouse':
      return 'String';
    case 'fabric':
    case 'mssql':
      return 'NVARCHAR(MAX)';
    case 'mysql':
      return 'CHAR';
    case 'sqlite':
      return 'TEXT';
    default:
      return 'VARCHAR';
  }
}

function quoteAgentRelation(relation: string, connection: ConnectionConfig): string {
  return relation.split('.').map((part) => quoteAgentIdentifier(part, connection)).join('.');
}

function quoteAgentIdentifier(identifier: string, connection: ConnectionConfig): string {
  return getDialect(connection.driver).quoteIdentifier(identifier);
}

function sqlStringLiteral(value: string): string {
  return `'${value.replace(/'/g, "''")}'`;
}

function escapeSqlLike(value: string): string {
  return value.replace(/[\\%_]/g, (match) => `\\${match}`);
}

function valueProbeRowValues(row: unknown): string[] {
  if (!row || typeof row !== 'object') return [];
  const record = row as Record<string, unknown>;
  return Object.values(record)
    .filter((value): value is string | number | boolean => (
      typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean'
    ))
    .map(String)
    .map((value) => value.trim())
    .filter(Boolean);
}

function uniqueStrings(values: string[]): string[] {
  const seen = new Set<string>();
  const output: string[] = [];
  for (const value of values) {
    const normalized = value.toLowerCase();
    if (seen.has(normalized)) continue;
    seen.add(normalized);
    output.push(value);
  }
  return output;
}

/**
 * Mark only a declared, same-snapshot exploratory path that the canonical
 * analytical policy has accepted. The marker is deliberately host-local: no
 * indexed card, provider proposal, client request, or persisted result can
 * raise a draft edge to this state. The router still keeps it
 * review-required because `automaticJoinAllowed` remains false.
 */
export function attestExploratoryRelationshipEvidence(
  evidence: AgentRetrievalEvidence,
  manifest: DQLManifest | undefined,
): AgentRetrievalEvidence {
  const relationships = Object.values(manifest?.modeling?.relationships ?? {});
  if (relationships.length === 0) return evidence;
  let changed = false;
  const candidates = evidence.candidates.map((candidate) => {
    const safety = candidate.relationshipSafety;
    if (!safety?.length) return candidate;
    const attested = safety.map((proof) => {
      // An identity is only a lookup key. The actual authorization binds the
      // physical endpoints and ordered keys from the retrieved proof to the
      // edge selected by the immutable manifest policy. A same-ID card with
      // different keys/endpoints is therefore a no-op, never an attestation.
      //
      // The catalog relationship projection intentionally carries canonical
      // *entity* endpoints (for example `commerce::entity::customer`), while
      // the exploratory compiler operates on the manifest's physical dbt
      // relations. A host may bridge those two representations only through
      // this same immutable manifest: the canonical entity pair and ordered
      // key sequence must first match the declared relationship, then the
      // selected manifest edge supplies the exact physical endpoints. This is
      // not a name/leaf fallback and cannot attest an arbitrary retrieved
      // relationship card.
      const matches = relationships.flatMap((relationship) => {
        if (!relationshipSafetyMatchesManifestRelationship(proof, relationship)) return [];
        const plan = planAnalyticalPath(manifest!, {
          entityIds: [relationship.from, relationship.to],
        });
        const exploratoryPath = plan.exploratoryPath;
        if (plan.disposition !== 'exploratory_candidate' || !exploratoryPath?.fingerprint) return [];
        const matchingEdges = exploratoryPath.edges.filter((value) =>
          normalizedAgentRelationshipIdentity(value.relationshipId) === normalizedAgentRelationshipIdentity(relationship.id)
          || normalizedAgentRelationshipIdentity(value.relationshipId) === normalizedAgentRelationshipIdentity(relationship.qualifiedId));
        // An ID that appears on two physical edges is not sufficient
        // authority. The proof must bind exactly one ordered edge/key sequence
        // in the selected path.
        if (matchingEdges.length !== 1) return [];
        const edge = matchingEdges[0]!;
        const physicalMatch = relationshipSafetyMatchesPlannedPhysicalEdge(proof, edge);
        const logicalOrientation = physicalMatch
          ? undefined
          : relationshipSafetyMatchesManifestEntityEdge(proof, relationship, manifest!);
        if (!physicalMatch && !logicalOrientation) return [];
        return [{
          fingerprint: exploratoryPath.fingerprint,
          // Normalize an entity-endpoint catalog proof to the manifest's
          // exact physical edge before it enters the exploratory closure. The
          // path fingerprint below binds this marker to the selected complete
          // manifest path, while the copied keys bind the compiler to the
          // physical join predicate it must validate.
          physicalProof: physicalMatch
            ? proof
            : {
              ...proof,
              from: logicalOrientation === 'forward' ? edge.fromRelation : edge.toRelation,
              to: logicalOrientation === 'forward' ? edge.toRelation : edge.fromRelation,
              keys: edge.keys.map((key) => logicalOrientation === 'forward'
                ? ({ from: key.from, to: key.to })
                : ({ from: key.to, to: key.from })),
            },
        }];
      });
      if (matches.length !== 1) return proof;
      const match = matches[0]!;
      changed = true;
      return {
        ...match.physicalProof,
        exploratoryJoinAllowed: true,
        // Bind the marker to the complete selected path, not just its friendly
        // relationship ID. The runtime cannot reuse it after a manifest path
        // or key sequence changes.
        exploratoryPathFingerprint: match.fingerprint,
      };
    });
    return attested.some((proof, index) => proof !== safety[index])
      ? { ...candidate, relationshipSafety: attested }
      : candidate;
  });
  return changed ? { ...evidence, candidates } : evidence;
}

function relationshipSafetyMatchesManifestRelationship(
  safety: NonNullable<AgentEvidenceCandidate['relationshipSafety']>[number],
  relationship: NonNullable<DQLManifest['modeling']>['relationships'][string],
): boolean {
  const safetyIdentities = new Set([
    safety.id,
    ...(safety.aliases ?? []),
  ].map(normalizedAgentRelationshipIdentity).filter(Boolean));
  const relationshipIdentities = [relationship.id, relationship.localId, relationship.qualifiedId]
    .map(normalizedAgentRelationshipIdentity)
    .filter(Boolean);
  return relationshipIdentities.some((identity) => safetyIdentities.has(identity));
}

/**
 * Match the catalog's canonical modeling endpoints to exactly the manifest
 * relationship that owns a planned physical edge. This accepts only complete
 * qualified/local entity identities; it never falls back to a display name or
 * relation leaf. Reverse orientation is allowed only with the reversed
 * ordered key sequence.
 */
function relationshipSafetyMatchesManifestEntityEdge(
  safety: NonNullable<AgentEvidenceCandidate['relationshipSafety']>[number],
  relationship: NonNullable<DQLManifest['modeling']>['relationships'][string],
  manifest: DQLManifest,
): 'forward' | 'reverse' | undefined {
  const fromIdentities = manifestEntityIdentitySet(manifest, relationship.from);
  const toIdentities = manifestEntityIdentitySet(manifest, relationship.to);
  const safetyFrom = normalizedAgentLogicalIdentity(safety.from ?? '');
  const safetyTo = normalizedAgentLogicalIdentity(safety.to ?? '');
  if (!safetyFrom || !safetyTo || fromIdentities.size === 0 || toIdentities.size === 0) return undefined;
  if (fromIdentities.has(safetyFrom)
    && toIdentities.has(safetyTo)
    && orderedAgentKeySignature(safety.keys) === orderedAgentKeySignature(relationship.keys)) {
    return 'forward';
  }
  if (fromIdentities.has(safetyTo)
    && toIdentities.has(safetyFrom)
    && orderedAgentKeySignature(safety.keys, true) === orderedAgentKeySignature(relationship.keys)) {
    return 'reverse';
  }
  return undefined;
}

function manifestEntityIdentitySet(manifest: DQLManifest, key: string): Set<string> {
  const entity = manifest.modeling?.entities[key];
  return new Set([
    key,
    entity?.id,
    entity?.localId,
    entity?.qualifiedId,
  ].map((value) => normalizedAgentLogicalIdentity(value ?? '')).filter(Boolean));
}

function relationshipSafetyMatchesPlannedPhysicalEdge(
  safety: NonNullable<AgentEvidenceCandidate['relationshipSafety']>[number],
  edge: { fromRelation?: string; toRelation?: string; keys: Array<{ from: string; to: string }> },
): boolean {
  const safetyFrom = canonicalAgentPhysicalReference(safety.from ?? '');
  const safetyTo = canonicalAgentPhysicalReference(safety.to ?? '');
  const edgeFrom = canonicalAgentPhysicalReference(edge.fromRelation ?? '');
  const edgeTo = canonicalAgentPhysicalReference(edge.toRelation ?? '');
  if (!safetyFrom || !safetyTo || !edgeFrom || !edgeTo) return false;
  const forward = safetyFrom === edgeFrom
    && safetyTo === edgeTo
    && orderedAgentKeySignature(safety.keys) === orderedAgentKeySignature(edge.keys);
  const reverse = safetyFrom === edgeTo
    && safetyTo === edgeFrom
    && orderedAgentKeySignature(safety.keys, true) === orderedAgentKeySignature(edge.keys);
  return forward || reverse;
}

function canonicalAgentPhysicalReference(value: string): string {
  return value.trim()
    .replace(/^(?:runtime:relation:|dbt:relation:|dbt:model:|dbt:source:|sql:table:)/i, '')
    .replace(/[`"\[\]]/g, '')
    .toLowerCase();
}

/** Canonical modeling identities intentionally retain their namespaces. */
function normalizedAgentLogicalIdentity(value: string): string {
  return value.trim().replace(/[`"\[\]]/g, '').toLowerCase();
}

function orderedAgentKeySignature(
  keys: readonly { from: string; to: string }[],
  reverse = false,
): string {
  return keys.map((key) => {
    const from = canonicalAgentPhysicalReference(reverse ? key.to : key.from);
    const to = canonicalAgentPhysicalReference(reverse ? key.from : key.to);
    return `${from}=${to}`;
  }).join('|');
}

function normalizedAgentRelationshipIdentity(value: string): string {
  return value.trim().replace(/[`"\[\]]/g, '').toLowerCase();
}

function agentSchemaTokens(value: string): Set<string> {
  const tokens = new Set<string>();
  for (const raw of value.toLowerCase().match(/[a-z0-9_]+/g) ?? []) {
    for (const part of raw.split('_')) {
      const normalized = normalizeAgentSchemaToken(part);
      if (!normalized || normalized.length < 3 || AGENT_SCHEMA_STOPWORDS.has(normalized)) continue;
      tokens.add(normalized);
    }
  }
  return tokens;
}

function hasAgentSchemaToken(value: string, expected: string[]): boolean {
  const tokens = agentSchemaTokens(value);
  return expected.some((token) => tokens.has(token));
}

export function extractAgentValueSearchTerms(question: string): string[] {
  const terms: string[] = [];
  for (const match of question.matchAll(/["']([^"']{3,120})["']/g)) {
    terms.push(match[1]);
  }
  for (const match of question.matchAll(/\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g)) {
    terms.push(match[0]);
  }
  for (const match of question.matchAll(/\b[A-Z][a-z0-9]+(?:\s+[A-Z][a-z0-9]+){1,3}\b/g)) {
    terms.push(match[0]);
  }
  for (const match of question.matchAll(/\b(?:for|named|called|only|where|customer|user|account|product)\s+([A-Za-z0-9@._-]+(?:\s+[A-Za-z0-9@._-]+){0,3})/gi)) {
    terms.push(match[1]);
  }
  for (const match of question.matchAll(/\b(?:than|versus|vs\.?)\s+([A-Za-z0-9@._-]+(?:\s+[A-Za-z0-9@._-]+){0,3})/gi)) {
    terms.push(match[1]);
  }
  return uniqueStrings(
    terms
      .map(cleanAgentValueSearchTerm)
      .filter((term) => term.length >= 3 && !AGENT_VALUE_SEARCH_STOP_PHRASES.has(term.toLowerCase())),
  ).slice(0, 6);
}

function cleanAgentValueSearchTerm(term: string): string {
  return term
    .replace(/[?.,;:]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^(?:account|customer|member|named|called|product|sku|subscriber|user)\s+/i, '')
    .replace(/\s+\b(?:got|get|gets|bought|buy|buys|purchased|purchase|purchases|spent|spend|spends|has|have|with)\b.*$/i, '')
    .replace(/\s+\b(?:last|next|this)\b.*$/i, '')
    .replace(/\s+\b(?:last|this)\s+(?:day|week|month|quarter|year)\b.*$/i, '')
    .replace(/\s+\b(?:daily|weekly|monthly|quarterly|yearly)\b.*$/i, '')
    .trim();
}

const AGENT_SCHEMA_STOPWORDS = new Set([
  'all', 'and', 'are', 'can', 'data', 'for', 'from', 'have', 'how', 'many', 'me',
  'show', 'the', 'this', 'who', 'with', 'value',
]);

const AGENT_VALUE_SEARCH_STOP_PHRASES = new Set([
  'account',
  'customer',
  'last week',
  'this week',
  'last month',
  'this month',
  'last quarter',
  'this quarter',
  'last year',
  'this year',
  'member',
  'product',
  'sku',
  'subscriber',
  'user',
]);

function normalizeAgentSchemaToken(token: string): string {
  if (token === 'orders') return 'order';
  if (token === 'customers') return 'customer';
  if (token === 'products') return 'product';
  if (token.endsWith('ies') && token.length > 4) return `${token.slice(0, -3)}y`;
  if (token.endsWith('s') && token.length > 4) return token.slice(0, -1);
  return token;
}

function stringFromRecord(record: Record<string, unknown>, key: string): string | undefined {
  const value = record[key];
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : undefined;
}

function isMemoryScope(value: unknown): value is 'thread' | 'notebook' | 'project' | 'user' | 'artifact' {
  return value === 'thread'
    || value === 'notebook'
    || value === 'project'
    || value === 'user'
    || value === 'artifact';
}
